def _parse_iso_datetime(value: object) -> datetime | None:
    if value in (None, ""):
        return None
    if isinstance(value, datetime):
        dt = value
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        try:
            parsed = datetime.fromisoformat(text)
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(timezone.utc)
        except Exception:
            pass
    try:
        parsed_pd = pd.to_datetime(value, utc=True, errors="coerce")
    except Exception:
        return None
    if parsed_pd is None or pd.isna(parsed_pd):
        return None
    if hasattr(parsed_pd, "to_pydatetime"):
        dt = parsed_pd.to_pydatetime()
        if isinstance(dt, datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc)
    return None


def _timestamp_epoch_seconds(value: object, *, cache: Optional[Dict[str, float]] = None) -> float:
    if value in (None, ""):
        return float("-inf")
    key = None
    if cache is not None:
        key = f"{type(value).__name__}:{repr(value)}"
        if key in cache:
            return cache[key]
    ts = float("-inf")
    try:
        if isinstance(value, datetime):
            dt = value if value.tzinfo else value.replace(tzinfo=timezone.utc)
            ts = float(dt.astimezone(timezone.utc).timestamp())
        elif isinstance(value, _date):
            dt = datetime(value.year, value.month, value.day, tzinfo=timezone.utc)
            ts = float(dt.timestamp())
        elif isinstance(value, (int, float)) and math.isfinite(float(value)):
            fv = float(value)
            if fv > 10**11:
                ts = fv / 1000.0
            elif fv > 10**9:
                ts = fv
            else:
                parsed = _parse_iso_datetime(value)
                ts = float(parsed.timestamp()) if isinstance(parsed, datetime) else float("-inf")
        else:
            parsed = _parse_iso_datetime(value)
            ts = float(parsed.timestamp()) if isinstance(parsed, datetime) else float("-inf")
    except Exception:
        ts = float("-inf")
    if cache is not None and key is not None:
        cache[key] = ts
    return ts


def _pid_is_alive(pid: object) -> bool:
    try:
        pid_int = int(pid)
    except Exception:
        return False
    if pid_int <= 0:
        return False
    try:
        os.kill(pid_int, 0)
        return True
    except PermissionError:
        return True
    except Exception:
        return False


def _scanner_status_payload(status_path: Path) -> dict[str, object]:
    if not status_path.exists():
        return {"ui_status": "stopped", "display_status": "Stopped", "reason": "missing"}
    payload: object | None = None
    read_error: Exception | None = None
    for attempt in range(3):
        try:
            payload = json.loads(status_path.read_text(encoding="utf-8"))
            read_error = None
            break
        except (PermissionError, json.JSONDecodeError) as exc:
            read_error = exc
            if attempt < 2:
                time.sleep(0.02)
                continue
            break
        except Exception as exc:
            read_error = exc
            break
    if read_error is not None:
        return {
            "ui_status": "unavailable",
            "display_status": "Status unavailable",
            "reason": "malformed",
            "error": str(read_error),
        }
    if not isinstance(payload, dict):
        return {
            "ui_status": "unavailable",
            "display_status": "Status unavailable",
            "reason": "malformed",
            "error": "Runtime status must be a JSON object.",
        }

    running = bool(payload.get("running"))
    wait_seconds = int(payload.get("wait_seconds") or 0)
    stale_after = int(payload.get("heartbeat_timeout_seconds") or max(60, wait_seconds * 2 + SCANNER_HEARTBEAT_GRACE_SECONDS))
    hb_dt = _parse_iso_datetime(payload.get("last_heartbeat_at"))
    now = datetime.now(timezone.utc)
    heartbeat_fresh = bool(hb_dt and (now - hb_dt).total_seconds() <= stale_after)
    pid_alive = _pid_is_alive(payload.get("pid")) if payload.get("pid") is not None else True

    if running and heartbeat_fresh and pid_alive:
        ui_status = "running"
        display = "Running"
    else:
        ui_status = "stopped"
        display = "Stopped"
    result = dict(payload)
    result.update(
        {
            "ui_status": ui_status,
            "display_status": display,
            "heartbeat_fresh": heartbeat_fresh,
            "pid_alive": pid_alive,
            "stale_after_seconds": stale_after,
        }
    )
    return result


def _scanner_runtime_is_live(script_name: str) -> bool:
    path = BYBIT_RUNTIME_STATUS_PATH if script_name == "bybit_monitor" else OANDA_RUNTIME_STATUS_PATH
    payload = _scanner_status_payload(path)
    return payload.get("ui_status") == "running"


def _merged_monitor_row(
    by_name: Dict[str, Dict[str, object]],
    autostart_targets: Set[str],
) -> Dict[str, object]:
    scanner_names = ("bybit_monitor", "oanda_monitor")
    scanner_children: Dict[str, Dict[str, object]] = {}
    required_children = [name for name in scanner_names if name in autostart_targets]
    eval_children = required_children or list(scanner_names)

    for child_name in scanner_names:
        managed = by_name.get(child_name, {}) if isinstance(by_name.get(child_name), dict) else {}
        runtime_live = _scanner_runtime_is_live(child_name)
        managed_running = bool(managed.get("running"))
        managed_starting = bool(managed.get("starting"))
        child_running = managed_running or runtime_live
        child_row: Dict[str, object] = {
            "running": child_running,
            "starting": managed_starting,
            "runtime_live": runtime_live,
            "managed_running": managed_running,
            "required": child_name in required_children,
        }
        for err_field in ("last_start_error", "last_exit_reason", "last_error"):
            value = managed.get(err_field)
            if value:
                child_row[err_field] = value
        scanner_children[child_name] = child_row

    all_required_running = bool(eval_children) and all(
        bool(scanner_children[name]["running"]) for name in eval_children
    )
    any_required_starting = any(
        bool(scanner_children[name]["starting"]) for name in eval_children
    )
    any_required_running = any(
        bool(scanner_children[name]["running"]) for name in eval_children
    )
    failed_required = [
        name for name in eval_children if not bool(scanner_children[name]["running"])
    ]
    running = all_required_running
    starting = (not running) and (any_required_starting or any_required_running)
    if running:
        detail = "running"
    elif starting:
        detail = "starting"
    else:
        detail = "stopped"
    if failed_required:
        detail = f"{detail}: missing live alert monitor(s): {', '.join(failed_required)}"

    return {
        "running": running,
        "starting": starting,
        "status_detail": detail,
        "scanner_children": scanner_children,
        "scanner_required_targets": eval_children,
    }

