def _default_journal_diagnostics() -> Dict[str, object]:
    return {
        "rows_total": 0,
        "raw_workbook_rows_total": 0,
        "visible_trade_rows_total": 0,
        "excluded_test_trade_rows": 0,
        "quarantined_invalid_time_rows": 0,
        "blank_pnl_trade_rows": 0,
        "cashflow_rows_total": 0,
        "rows_by_source": {},
        "rows_by_account": {},
        "rows_by_asset_class": {},
        "last_sync": {},
        "local_workbooks_seen": 0,
        "dropbox_workbooks_seen": 0,
        "duplicate_rows_dropped": 0,
        "source_duplicate_rows_dropped": 0,
        "dedupe_groups": 0,
        "ignored_local_workbooks": [],
        "quarantined_rows": 0,
        "errors": [],
    }


def _set_trading_journal_diagnostics(payload: Optional[Dict[str, object]]) -> None:
    base = _default_journal_diagnostics()
    if isinstance(payload, dict):
        base.update(payload)
    global TRADING_JOURNAL_IMPORT_DIAGNOSTICS
    TRADING_JOURNAL_IMPORT_DIAGNOSTICS = base


def _is_visible_trading_journal_row(row: object) -> bool:
    if not isinstance(row, dict):
        return False
    if _exclude_bybit_demo_row(row):
        return False
    return str(row.get("status") or "").strip().lower() != "invalid_time_order"


def _build_trading_journal_diagnostics_snapshot() -> Dict[str, object]:
    diagnostics = dict(TRADING_JOURNAL_IMPORT_DIAGNOSTICS or _default_journal_diagnostics())
    state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
    sync_state = _sync_state_snapshot()
    sync_result = sync_state.get("result") if isinstance(sync_state.get("result"), dict) else {}
    raw_rows = [row for row in _get_trading_journal_rows() if isinstance(row, dict)]
    visible_rows = [row for row in raw_rows if _is_visible_trading_journal_row(row)]
    visible_trade_rows = [row for row in visible_rows if _row_type(row) == "trade"]
    stats_included_trade_rows = [row for row in visible_trade_rows if not _is_test_trade_row(row)]
    raw_rows_total = len(raw_rows)
    visible_rows_total = len(visible_rows)
    quarantined_rows = sum(
        1 for row in raw_rows if str(row.get("status") or "").strip().lower() == "invalid_time_order"
    )
    excluded_bybit_demo_rows = sum(1 for row in raw_rows if _exclude_bybit_demo_row(row))
    excluded_rows_total = max(0, raw_rows_total - visible_rows_total)
    journal_rows_total = visible_rows_total

    computed_rows_by_source: Dict[str, int] = defaultdict(int)
    computed_rows_by_asset_class: Dict[str, int] = defaultdict(int)
    for row in visible_rows:
        computed_rows_by_source[str(row.get("source") or "unknown")] += 1
        computed_rows_by_asset_class[str(row.get("asset_class") or "unknown")] += 1

    diagnostics_rows_total = int(diagnostics.get("rows_total") or 0)
    rows_total = int(journal_rows_total)

    rows_by_source = diagnostics.get("rows_by_source") if isinstance(diagnostics.get("rows_by_source"), dict) else {}
    rows_by_asset_class = diagnostics.get("rows_by_asset_class") if isinstance(diagnostics.get("rows_by_asset_class"), dict) else {}
    rows_by_source_sum = sum(int(v or 0) for v in rows_by_source.values()) if rows_by_source else 0
    rows_by_asset_sum = sum(int(v or 0) for v in rows_by_asset_class.values()) if rows_by_asset_class else 0
    if journal_rows_total > 0 and (not rows_by_source or rows_by_source_sum != journal_rows_total):
        rows_by_source = dict(computed_rows_by_source)
    if journal_rows_total > 0 and (not rows_by_asset_class or rows_by_asset_sum != journal_rows_total):
        rows_by_asset_class = dict(computed_rows_by_asset_class)

    source_mode = str(
        (diagnostics.get("last_sync") if isinstance(diagnostics.get("last_sync"), dict) else {}).get("source_mode")
        or (sync_result or {}).get("source_mode")
        or sync_state.get("source_mode")
        or _trading_journal_source_mode()
    ).strip().lower()
    if source_mode not in {"dropbox", "local", "both", "auto"}:
        source_mode = _trading_journal_source_mode()

    local_workbooks_seen = int(diagnostics.get("local_workbooks_seen") or 0)
    if local_workbooks_seen <= 0:
        local_workbooks_seen = int((sync_result or {}).get("local_workbooks_seen") or 0)
    if local_workbooks_seen <= 0:
        local_workbooks_seen = int(sync_state.get("local_workbooks_seen") or 0)
    if local_workbooks_seen <= 0 and isinstance(state, dict):
        local_workbooks_seen = int(state.get("local_workbooks_seen") or 0)

    dropbox_workbooks_seen = 0
    if source_mode != "local":
        dropbox_workbooks_seen = int(diagnostics.get("dropbox_workbooks_seen") or 0)
        if dropbox_workbooks_seen <= 0:
            dropbox_workbooks_seen = int((sync_result or {}).get("dropbox_workbooks_seen") or 0)
        if dropbox_workbooks_seen <= 0:
            dropbox_workbooks_seen = int(sync_state.get("dropbox_workbooks_seen") or 0)
        if dropbox_workbooks_seen <= 0 and isinstance(state, dict):
            dropbox_workbooks_seen = int(state.get("workbooks_seen") or state.get("dropbox_workbooks_seen") or 0)

    if journal_rows_total > 0 and diagnostics_rows_total <= 0:
        diagnostics_source = "derived_from_current_rows"
    elif rows_total != diagnostics_rows_total:
        diagnostics_source = "mixed"
    else:
        diagnostics_source = "import"

    snapshot = _default_journal_diagnostics()
    snapshot.update(diagnostics)
    snapshot["rows_total"] = int(rows_total)
    snapshot["journal_rows_total"] = int(journal_rows_total)
    snapshot["raw_rows_total"] = int(raw_rows_total)
    snapshot["visible_rows_total"] = int(visible_rows_total)
    snapshot["visible_trade_rows_total"] = int(len(visible_trade_rows))
    snapshot["stats_included_trade_rows_total"] = int(len(stats_included_trade_rows))
    snapshot["excluded_test_trade_rows"] = int(sum(1 for row in visible_trade_rows if _is_test_trade_row(row)))
    snapshot["blank_pnl_trade_rows"] = int(sum(1 for row in visible_trade_rows if _row_pnl(row) is None))
    snapshot["cashflow_rows_total"] = int(sum(1 for row in visible_rows if _row_type(row) == "cashflow"))
    snapshot["quarantined_invalid_time_rows"] = int(quarantined_rows)
    snapshot["excluded_rows_total"] = int(excluded_rows_total)
    snapshot["excluded_bybit_demo_rows"] = int(excluded_bybit_demo_rows)
    snapshot["has_current_journal_rows"] = journal_rows_total > 0
    snapshot["rows_by_source"] = rows_by_source if isinstance(rows_by_source, dict) else {}
    snapshot["rows_by_asset_class"] = rows_by_asset_class if isinstance(rows_by_asset_class, dict) else {}
    snapshot["last_sync"] = snapshot.get("last_sync") if isinstance(snapshot.get("last_sync"), dict) else {}
    snapshot["local_workbooks_seen"] = int(local_workbooks_seen)
    snapshot["dropbox_workbooks_seen"] = int(dropbox_workbooks_seen)
    snapshot["workbook_sources_seen"] = int(local_workbooks_seen if source_mode == "local" else (local_workbooks_seen + dropbox_workbooks_seen))
    snapshot["duplicate_rows_dropped"] = int(snapshot.get("duplicate_rows_dropped") or 0)
    snapshot["source_duplicate_rows_dropped"] = int(snapshot.get("source_duplicate_rows_dropped") or 0)
    snapshot["dedupe_groups"] = int(snapshot.get("dedupe_groups") or 0)
    snapshot["quarantined_rows"] = int(quarantined_rows)
    invalid_details: List[Dict[str, object]] = []
    repaired_rows = 0
    for row in raw_rows:
        refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
        if metrics.get("time_order_repaired") is True or str(refs.get("time_order_repaired") or "").strip():
            repaired_rows += 1
        if str(row.get("status") or "").strip().lower() != "invalid_time_order":
            continue
        invalid_details.append(
            {
                "symbol": row.get("symbol"),
                "side": row.get("side"),
                "order_id": refs.get("orderId") or row.get("order_id"),
                "open_time": row.get("open_time"),
                "close_time": row.get("close_time"),
                "source": row.get("source"),
                "reason": str(metrics.get("time_warning_code") or refs.get("time_warning_code") or "invalid_time_order"),
            }
        )
    snapshot["invalid_time_order_rows"] = int(quarantined_rows)
    snapshot["repaired_time_order_rows"] = int(repaired_rows)
    snapshot["quarantined_invalid_time_rows"] = int(quarantined_rows)
    snapshot["invalid_time_order_row_details"] = invalid_details
    snapshot["ignored_local_workbooks"] = snapshot.get("ignored_local_workbooks") if isinstance(snapshot.get("ignored_local_workbooks"), list) else []
    snapshot["errors"] = snapshot.get("errors") if isinstance(snapshot.get("errors"), list) else []
    snapshot["diagnostics_source"] = diagnostics_source
    return snapshot


def _build_authoritative_trading_journal_diagnostics_snapshot(items: List[Dict[str, object]]) -> Dict[str, object]:
    visible_rows = [row for row in items if _is_visible_trading_journal_row(row)]
    visible_trade_rows = [row for row in visible_rows if _row_type(row) == "trade"]
    rows_by_source: Dict[str, int] = defaultdict(int)
    rows_by_asset_class: Dict[str, int] = defaultdict(int)
    for row in visible_rows:
        rows_by_source[str(row.get("source") or "unknown")] += 1
        rows_by_asset_class[str(row.get("asset_class") or "unknown")] += 1
    return {
        **_default_journal_diagnostics(),
        "rows_total": len(visible_rows),
        "journal_rows_total": len(visible_rows),
        "raw_rows_total": len(items),
        "visible_rows_total": len(visible_rows),
        "visible_trade_rows_total": len(visible_trade_rows),
        "stats_included_trade_rows_total": len([r for r in visible_trade_rows if not _is_test_trade_row(r)]),
        "excluded_test_trade_rows": len([r for r in visible_trade_rows if _is_test_trade_row(r)]),
        "rows_by_source": dict(rows_by_source),
        "rows_by_asset_class": dict(rows_by_asset_class),
        "errors": [],
    }


_TRADING_JOURNAL_VIEW_CACHE: Dict[str, object] = {"key": None, "payload": None}
_PENDING_MANUAL_SYNC_ROWS: List[Dict[str, object]] = []
_PENDING_MANUAL_SYNC_BALANCES: List[Dict[str, object]] = []
TRADING_JOURNAL_VIEW_CACHE_VERSION = 6
TRADING_JOURNAL_EQUITY_CACHE_SCHEMA_VERSION = 2
TRADING_JOURNAL_EQUITY_CURVE_TYPE = "cashflow_neutral_compounded_index"
TRADING_JOURNAL_EQUITY_BASE_INDEX = 100.0
TRADING_JOURNAL_EQUITY_RETURN_BASIS = (
    "net_trade_result_over_analysis_balance_before_trade"
)
TRADING_JOURNAL_EQUITY_BALANCE_PROVENANCE = frozenset(
    {
        "authoritative_after_minus_trade_result",
        "cashflow_anchor_plus_trade_results",
        "prior_verified_trade_balance_plus_results",
    }
)
TRADING_JOURNAL_EQUITY_ACCOUNTS: Tuple[str, ...] = (
    "BINANCE",
    "BYBIT",
    "OANDA DEMO",
    "OANDA LIVE",
    "PEPPERSTONE DEMO",
    "PEPPERSTONE LIVE",
)


def _equity_account_key(value: object) -> str:
    if isinstance(value, dict):
        raw = (
            value.get("account_label")
            or value.get("account")
            or value.get("label")
            or value.get("provider_account")
            or ""
        )
    else:
        raw = value
    normalized = re.sub(r"\s+", " ", re.sub(r"[_-]+", " ", str(raw or "").strip())).upper()
    aliases = {
        "BINANCE": "BINANCE",
        "BYBIT": "BYBIT",
        "BYBIT LIVE": "BYBIT",
        "OANDA DEMO": "OANDA DEMO",
        "OANDA LIVE": "OANDA LIVE",
        "PEPPERSTONE DEMO": "PEPPERSTONE DEMO",
        "PEPPERSTONE LIVE": "PEPPERSTONE LIVE",
    }
    return aliases.get(normalized, "")


def _equity_trade_return_pct(row: object) -> Optional[float]:
    if not isinstance(row, dict):
        return None
    balance_provenance = str(
        row.get("analysis_balance_before_trade_source") or ""
    ).strip()
    if balance_provenance not in TRADING_JOURNAL_EQUITY_BALANCE_PROVENANCE:
        return None
    pnl = _row_pnl(row)
    balance_before = _to_float(row.get("analysis_balance_before_trade"))
    if pnl is None or balance_before is None or balance_before <= 0:
        return None
    return (pnl / balance_before) * 100.0


def _equity_point_counts(items: object, balances: object) -> Dict[str, int]:
    del balances  # Percentage indices are currency-neutral.
    events: Dict[str, Dict[str, Tuple[float, str, str]]] = {
        account: {} for account in TRADING_JOURNAL_EQUITY_ACCOUNTS
    }
    for row in items if isinstance(items, list) else []:
        if not isinstance(row, dict):
            continue
        account = _equity_account_key(row)
        if not account or _is_test_trade_value(row.get("is_test_trade")):
            continue
        row_type = re.sub(
            r"\s+",
            "_",
            str(row.get("row_type") or "trade").strip().lower(),
        )
        cashflow_balance = _to_float(row.get("cashflow_new_balance"))
        valid_cashflow = row_type == "cashflow" and cashflow_balance is not None
        trade_return_pct = _equity_trade_return_pct(row) if row_type == "trade" else None
        if row_type == "monthly_aud_reval" or (
            row_type == "trade" and trade_return_pct is None
        ) or (
            row_type != "trade" and not valid_cashflow
        ):
            continue
        timestamp = _timestamp_epoch_seconds(row.get("close_time") or row.get("open_time"))
        if not math.isfinite(timestamp):
            continue
        stable_identity = str(
            row.get("id") or row.get("row_id") or row.get("stable_row_id") or ""
        ).strip()
        identity = stable_identity or (
            f"{account}|{row_type}|{int(timestamp * 1000.0)}|"
            f"{trade_return_pct if row_type == 'trade' else cashflow_balance}"
        )
        events[account][identity] = (timestamp, identity, row_type)

    counts: Dict[str, int] = {}
    for account in TRADING_JOURNAL_EQUITY_ACCOUNTS:
        ordered = sorted(events[account].values(), key=lambda event: (event[0], event[1]))
        first_trade = next((event for event in ordered if event[2] == "trade"), None)
        if first_trade is None:
            counts[account] = 0
            continue
        first_trade_timestamp = first_trade[0]
        counts[account] = 1 + sum(
            1 for event in ordered if event[0] >= first_trade_timestamp
        )
    return counts


def _stable_json_sha256(value: object) -> str:
    safe = _json_safe(value)
    return hashlib.sha256(
        json.dumps(
            safe,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8")
    ).hexdigest()


def _attach_trading_journal_equity_metadata(payload: Dict[str, object]) -> Dict[str, object]:
    generated_at = str(payload.get("generated_at") or _utc_now_iso())
    payload["generated_at"] = generated_at
    snapshot_id = uuid4().hex
    source_fingerprints = payload.get("source_fingerprints")
    source_fingerprint_sha256 = _stable_json_sha256(source_fingerprints)
    point_counts = _equity_point_counts(payload.get("items"), payload.get("balances"))
    snapshot_fingerprint = _stable_json_sha256(
        {
            "snapshot_id": snapshot_id,
            "generated_at": generated_at,
            "source_fingerprint_sha256": source_fingerprint_sha256,
            "equity_schema_version": TRADING_JOURNAL_EQUITY_CACHE_SCHEMA_VERSION,
            "equity_curve_type": TRADING_JOURNAL_EQUITY_CURVE_TYPE,
            "equity_return_basis": TRADING_JOURNAL_EQUITY_RETURN_BASIS,
            "point_counts": point_counts,
        }
    )
    payload["snapshot_id"] = snapshot_id
    payload["snapshot_fingerprint"] = snapshot_fingerprint
    payload["equity_cache"] = {
        "schema_version": TRADING_JOURNAL_EQUITY_CACHE_SCHEMA_VERSION,
        "verified": True,
        "verified_at": generated_at,
        "source_fingerprint_sha256": source_fingerprint_sha256,
        "curve_type": TRADING_JOURNAL_EQUITY_CURVE_TYPE,
        "base_index": TRADING_JOURNAL_EQUITY_BASE_INDEX,
        "return_field": "equity_return_pct",
        "return_basis": TRADING_JOURNAL_EQUITY_RETURN_BASIS,
        "point_counts": point_counts,
    }
    return payload


def _trading_journal_snapshot_freshness(
    snapshot: object,
    current_fingerprints: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    reasons: List[str] = []
    if not isinstance(snapshot, dict):
        return {"current": False, "reasons": ["snapshot_missing"], "point_counts": {}}
    if int(snapshot.get("cache_version") or 0) != TRADING_JOURNAL_VIEW_CACHE_VERSION:
        reasons.append("cache_version_incompatible")
    fingerprints = (
        current_fingerprints
        if isinstance(current_fingerprints, dict)
        else _journal_source_fingerprint()
    )
    if snapshot.get("source_fingerprints") != fingerprints:
        reasons.append("source_fingerprint_stale")
    equity_meta = snapshot.get("equity_cache")
    if not isinstance(equity_meta, dict):
        reasons.append("equity_proof_missing")
        equity_meta = {}
    else:
        if int(equity_meta.get("schema_version") or 0) != TRADING_JOURNAL_EQUITY_CACHE_SCHEMA_VERSION:
            reasons.append("equity_schema_incompatible")
        if str(equity_meta.get("curve_type") or "") != TRADING_JOURNAL_EQUITY_CURVE_TYPE:
            reasons.append("equity_curve_type_incompatible")
        if _to_float(equity_meta.get("base_index")) != TRADING_JOURNAL_EQUITY_BASE_INDEX:
            reasons.append("equity_base_index_incompatible")
        if str(equity_meta.get("return_field") or "") != "equity_return_pct":
            reasons.append("equity_return_field_incompatible")
        if str(equity_meta.get("return_basis") or "") != TRADING_JOURNAL_EQUITY_RETURN_BASIS:
            reasons.append("equity_return_basis_incompatible")
        if equity_meta.get("verified") is not True:
            reasons.append("equity_not_verified")
        expected_source_hash = _stable_json_sha256(snapshot.get("source_fingerprints"))
        if str(equity_meta.get("source_fingerprint_sha256") or "") != expected_source_hash:
            reasons.append("equity_source_fingerprint_mismatch")
    actual_counts = _equity_point_counts(snapshot.get("items"), snapshot.get("balances"))
    if equity_meta.get("point_counts") != actual_counts:
        reasons.append("equity_point_coverage_mismatch")
    if not str(snapshot.get("snapshot_id") or "").strip():
        reasons.append("snapshot_id_missing")
    if not str(snapshot.get("snapshot_fingerprint") or "").strip():
        reasons.append("snapshot_fingerprint_missing")
    return {
        "current": not reasons,
        "reasons": reasons,
        "point_counts": actual_counts,
        "current_fingerprints": fingerprints,
    }


def _source_file_fingerprint(path: Path) -> Dict[str, object]:
    info: Dict[str, object] = {"path": str(path), "exists": path.exists()}
    if not path.exists():
        return info
    stat = path.stat()
    info["size"] = int(stat.st_size)
    info["mtime"] = float(stat.st_mtime)
    try:
        info["sha256"] = hashlib.sha256(path.read_bytes()).hexdigest()
    except Exception:
        info["sha256"] = ""
    return info




def _master_journal_authoritative_enabled() -> bool:
    source = str(os.getenv("TRADING_JOURNAL_SOURCE", "") or "").strip().lower()
    explicit = str(os.getenv("TRADING_JOURNAL_MASTER_JOURNAL_AUTHORITATIVE", "0") or "0").strip().lower() in {"1","true","yes","on"}
    return source == "master_journal" or explicit


def _enforce_single_master_journal_xlsx(journal_dir: Path, *, cleanup_known_generated: bool) -> dict:
    known_generated = {
        "account_cashflows.xlsx",
        "bybit demo.xlsx",
        "bybit live.xlsx",
        "oanda demo.xlsx",
        "oanda live.xlsx",
    }
    found: List[Path] = []
    removed: List[str] = []
    unknown: List[str] = []
    migrated_legacy_master_journal = False
    for pattern in ("*.xlsx", "*.xlsm", "*.xls"):
        for p in sorted(journal_dir.glob(pattern)):
            name = p.name
            lname = name.lower()
            if lname.startswith("~$") or lname.endswith(".tmp.xlsx") or lname.endswith(".pending.xlsx"):
                continue
            found.append(p)

    canonical = journal_dir / "Trading Journal.xlsx"
    legacy = journal_dir / "Master Journal.xlsx"
    if canonical.exists() and legacy.exists():
        unknown.extend([legacy.name])
    elif (not canonical.exists()) and legacy.exists():
        legacy.replace(canonical)
        migrated_legacy_master_journal = True

    for p in found:
        if p.name == "Trading Journal.xlsx" or p.name == "Master Journal.xlsx":
            continue
        if p.name.lower() in known_generated and cleanup_known_generated:
            try:
                p.unlink(missing_ok=True)
                removed.append(p.name)
                continue
            except Exception:
                pass
        unknown.append(p.name)
    return {
        "ok": len(unknown) == 0,
        "journal_dir": str(journal_dir),
        "removed_known_generated": removed,
        "unknown_extra_excel_files": sorted(set(unknown)),
        "migrated_legacy_master_journal": migrated_legacy_master_journal,
    }

def _journal_source_fingerprint() -> dict:
    mode = TRADING_JOURNAL_SOURCE if TRADING_JOURNAL_SOURCE in {"dropbox", "local", "both", "auto", "master_journal"} else "both"
    source_files: List[Dict[str, object]] = []
    authoritative = _master_journal_authoritative_enabled()
    if authoritative:
        source_files.append(_source_file_fingerprint(_master_journal_path()))
    else:
        for path in _list_local_trading_journal_workbooks():
            source_files.append(_source_file_fingerprint(path))
        source_files.append(_source_file_fingerprint(_resolve_local_journal_file("account_cashflows.xlsx", TRADING_JOURNAL_LOCAL_DIR)))
        source_files.append(_source_file_fingerprint(_resolve_local_journal_file(BYBIT_DEMO_WORKBOOK_NAME, TRADING_JOURNAL_LOCAL_DIR)))
        source_files.append(_source_file_fingerprint(_resolve_local_journal_file(BYBIT_DEMO_TEMPLATE_NAME, TRADING_JOURNAL_LOCAL_DIR)))
    source_files.append(_source_file_fingerprint(TRADING_JOURNAL_PATH))
    source_files.append(_source_file_fingerprint(TRADING_JOURNAL_STATE_PATH))
    source_files.append(_source_file_fingerprint(OANDA_FILL_STATE_PATH))
    source_files.append(_source_file_fingerprint(MONTHLY_AUD_REVALUATION_PATH))
    source_files.append(_source_file_fingerprint(MONTHLY_AUD_REVALUATION_STATE_PATH))
    source_files = sorted(source_files, key=lambda x: str(x.get("path") or ""))
    return {
        "source_mode": mode,
        "local_dir": str(TRADING_JOURNAL_LOCAL_DIR),
        "files": source_files,
    }


def _load_trading_journal_view_snapshot() -> Optional[Dict[str, object]]:
    payload = _load_json_file(TRADING_JOURNAL_VIEW_CACHE_PATH, {})
    if not isinstance(payload, dict) or not payload:
        return None
    if int(payload.get("cache_version") or 0) != TRADING_JOURNAL_VIEW_CACHE_VERSION:
        return None
    return payload


def _snapshot_balance_items(snapshot: object) -> List[Dict[str, object]]:
    if not isinstance(snapshot, dict):
        return []
    balances = snapshot.get("balances")
    if isinstance(balances, list):
        return [b for b in balances if isinstance(b, dict)]
    if isinstance(balances, dict):
        items = balances.get("items")
        if isinstance(items, list):
            return [b for b in items if isinstance(b, dict)]
    return []


def _save_trading_journal_view_snapshot(payload: dict) -> None:
    safe_payload = _json_safe(payload if isinstance(payload, dict) else {})
    _save_json_file(TRADING_JOURNAL_VIEW_CACHE_PATH, safe_payload if isinstance(safe_payload, dict) else {})


def _invalidate_trading_journal_view_snapshot() -> None:
    _TRADING_JOURNAL_VIEW_CACHE["key"] = None
    _TRADING_JOURNAL_VIEW_CACHE["payload"] = None
    try:
        if TRADING_JOURNAL_VIEW_CACHE_PATH.exists():
            TRADING_JOURNAL_VIEW_CACHE_PATH.unlink()
    except Exception as exc:
        BYBIT_LOGGER.warning("Trading journal view cache invalidation failed: %s", exc)


def _reconcile_trading_journal_equity_refresh_state_locked() -> None:
    task = TRADING_JOURNAL_EQUITY_REFRESH_TASK
    pending = bool(
        TRADING_JOURNAL_EQUITY_REFRESH_STATE.get("running")
        or TRADING_JOURNAL_EQUITY_REFRESH_STATE.get("pending")
    )
    active_task = isinstance(task, asyncio.Task) and not task.done()
    if not pending or active_task:
        return

    if isinstance(task, asyncio.Task) and task.cancelled():
        error = "Equity cache build was cancelled."
    elif isinstance(task, asyncio.Task):
        try:
            task_error = task.exception()
        except asyncio.CancelledError:
            task_error = None
            error = "Equity cache build was cancelled."
        except Exception as exc:
            task_error = exc
            error = f"Equity cache task status could not be read: {exc}"
        else:
            error = (
                f"Equity cache build stopped unexpectedly: {task_error}"
                if task_error is not None
                else "Equity cache build ended without publishing a terminal status."
            )
    else:
        error = "Equity cache build has no active task."

    TRADING_JOURNAL_EQUITY_REFRESH_STATE.update(
        {
            "running": False,
            "pending": False,
            "ok": False,
            "error": error,
            "message": "Equity cache build stopped before completion.",
            "finished_at": _utc_now_iso(),
        }
    )


def _trading_journal_equity_refresh_state_snapshot() -> Dict[str, object]:
    with TRADING_JOURNAL_EQUITY_REFRESH_LOCK:
        _reconcile_trading_journal_equity_refresh_state_locked()
        state = dict(TRADING_JOURNAL_EQUITY_REFRESH_STATE)
        task = TRADING_JOURNAL_EQUITY_REFRESH_TASK
        state["active_task_known"] = bool(
            isinstance(task, asyncio.Task) and not task.done()
        )
        safe = _json_safe(state)
        return safe if isinstance(safe, dict) else state


def _set_trading_journal_equity_refresh_state(**updates: object) -> Dict[str, object]:
    with TRADING_JOURNAL_EQUITY_REFRESH_LOCK:
        TRADING_JOURNAL_EQUITY_REFRESH_STATE.update(updates)
        safe = _json_safe(TRADING_JOURNAL_EQUITY_REFRESH_STATE)
        if isinstance(safe, dict):
            TRADING_JOURNAL_EQUITY_REFRESH_STATE.clear()
            TRADING_JOURNAL_EQUITY_REFRESH_STATE.update(safe)
        return dict(TRADING_JOURNAL_EQUITY_REFRESH_STATE)


async def _run_trading_journal_equity_refresh_job(
    *,
    reason: str,
    refresh_id: str,
) -> None:
    _set_trading_journal_equity_refresh_state(
        running=True,
        pending=True,
        ok=None,
        error=None,
        message="Building current equity cache from Trading Journal.xlsx…",
        reason=reason,
        refresh_id=refresh_id,
        started_at=_utc_now_iso(),
        finished_at=None,
    )
    try:
        snapshot: Dict[str, object] = {}
        freshness: Dict[str, object] = {"current": False}
        for attempt in range(2):
            snapshot = await asyncio.to_thread(
                _build_trading_journal_view_snapshot,
                force=True,
                skip_external_balances=True,
                skip_live_account_refresh=True,
                sync_id=refresh_id,
                sync_caller=f"equity_cache:{reason}",
            )
            current_fingerprints = _journal_source_fingerprint()
            freshness = _trading_journal_snapshot_freshness(
                snapshot,
                current_fingerprints,
            )
            if freshness.get("current") is True:
                break
            if "source_fingerprint_stale" not in list(freshness.get("reasons") or []):
                break
            APP_LOGGER.info(
                "trading_journal_equity_refresh_retry refresh_id=%s reason=%s attempt=%s freshness_reasons=%s",
                refresh_id,
                reason,
                attempt + 1,
                freshness.get("reasons"),
            )
        if freshness.get("current") is not True:
            raise RuntimeError(
                "Equity cache build did not produce a current authoritative snapshot: "
                + ", ".join(str(item) for item in (freshness.get("reasons") or []))
            )
        _set_trading_journal_equity_refresh_state(
            running=False,
            pending=False,
            ok=True,
            error=None,
            message="Equity cache is current.",
            finished_at=_utc_now_iso(),
            snapshot_id=str(snapshot.get("snapshot_id") or ""),
            snapshot_fingerprint=str(snapshot.get("snapshot_fingerprint") or ""),
            point_counts=freshness.get("point_counts") or {},
            completed_source_fingerprints=snapshot.get("source_fingerprints"),
        )
    except asyncio.CancelledError:
        _set_trading_journal_equity_refresh_state(
            running=False,
            pending=False,
            ok=False,
            error="Equity cache build was cancelled.",
            message="Equity cache build stopped before completion.",
            finished_at=_utc_now_iso(),
        )
        raise
    except Exception as exc:
        APP_LOGGER.exception(
            "trading_journal_equity_refresh_failed refresh_id=%s reason=%s",
            refresh_id,
            reason,
        )
        _set_trading_journal_equity_refresh_state(
            running=False,
            pending=False,
            ok=False,
            error=str(exc),
            message="Equity cache build failed.",
            finished_at=_utc_now_iso(),
        )


def _queue_trading_journal_equity_refresh_if_idle(
    reason: str,
    *,
    current_fingerprints: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    global TRADING_JOURNAL_EQUITY_REFRESH_TASK
    with TRADING_JOURNAL_EQUITY_REFRESH_LOCK:
        task = TRADING_JOURNAL_EQUITY_REFRESH_TASK
        if isinstance(task, asyncio.Task) and not task.done():
            return _trading_journal_equity_refresh_state_snapshot()
        refresh_id = f"equity-{uuid4().hex[:12]}"
        requested_fingerprints = (
            current_fingerprints
            if isinstance(current_fingerprints, dict)
            else _journal_source_fingerprint()
        )
        TRADING_JOURNAL_EQUITY_REFRESH_STATE.update(
            {
                "running": True,
                "pending": True,
                "ok": None,
                "error": None,
                "message": "Equity cache build queued…",
                "reason": str(reason or "equity_refresh"),
                "refresh_id": refresh_id,
                "started_at": _utc_now_iso(),
                "finished_at": None,
                "requested_source_fingerprints": requested_fingerprints,
                "snapshot_id": "",
                "snapshot_fingerprint": "",
                "point_counts": {},
            }
        )
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError as exc:
            TRADING_JOURNAL_EQUITY_REFRESH_STATE.update(
                {
                    "running": False,
                    "pending": False,
                    "ok": False,
                    "error": str(exc),
                    "message": "Equity cache build could not be queued.",
                    "finished_at": _utc_now_iso(),
                }
            )
            return _trading_journal_equity_refresh_state_snapshot()
        TRADING_JOURNAL_EQUITY_REFRESH_TASK = loop.create_task(
            _run_trading_journal_equity_refresh_job(
                reason=str(reason or "equity_refresh"),
                refresh_id=refresh_id,
            )
        )
        return _trading_journal_equity_refresh_state_snapshot()


async def _start_master_journal_equity_cache_after_restore() -> None:
    await _wait_for_startup_restore_signal(
        timeout=STARTUP_RESTORE_WAIT_TIMEOUT_SECONDS,
        timeout_warning="EQUITY_CACHE_STARTUP_WAIT_TIMEOUT proceeding without restore signal",
    )
    _queue_trading_journal_equity_refresh_if_idle("startup_master_journal")
    task = TRADING_JOURNAL_EQUITY_REFRESH_TASK
    if isinstance(task, asyncio.Task) and task is not asyncio.current_task():
        await asyncio.shield(task)


def _ensure_trading_journal_sqlite_schema(conn: sqlite3.Connection) -> None:
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS journal_trades (id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS journal_cashflows (id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS journal_balances (account_key TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS journal_notes (id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS journal_metrics (id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS journal_stats (snapshot_id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS journal_diagnostics (snapshot_id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, imported_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS source_files (absolute_path TEXT PRIMARY KEY, file_size INTEGER, modified_at REAL, content_hash TEXT, last_imported_at TEXT);
        CREATE TABLE IF NOT EXISTS import_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT, finished_at TEXT, source_mode TEXT, workbooks_scanned INTEGER, workbooks_changed INTEGER, rows_imported INTEGER, cashflow_rows_loaded INTEGER, warnings_json TEXT, errors_json TEXT, metadata_json TEXT);
        """
    )
    import_run_columns = {
        str(row[1])
        for row in conn.execute("PRAGMA table_info(import_runs)").fetchall()
        if len(row) > 1
    }
    if "metadata_json" not in import_run_columns:
        conn.execute("ALTER TABLE import_runs ADD COLUMN metadata_json TEXT")


def _persist_trading_journal_sqlite(snapshot: Dict[str, object], import_meta: Optional[Dict[str, object]] = None) -> None:
    safe_snapshot = _json_safe(snapshot)
    if not isinstance(safe_snapshot, dict):
        safe_snapshot = {}
    safe_import_meta = _json_safe(import_meta) if isinstance(import_meta, dict) else None
    if safe_import_meta is not None and not isinstance(safe_import_meta, dict):
        safe_import_meta = {}
    TRADING_JOURNAL_SQLITE_PATH.parent.mkdir(parents=True, exist_ok=True)
    now_iso = _utc_now_iso()
    conn = sqlite3.connect(TRADING_JOURNAL_SQLITE_PATH)
    try:
        _ensure_trading_journal_sqlite_schema(conn)
        items = safe_snapshot.get("items") if isinstance(safe_snapshot.get("items"), list) else []
        balances = safe_snapshot.get("balances") if isinstance(safe_snapshot.get("balances"), list) else []
        diagnostics = safe_snapshot.get("diagnostics") if isinstance(safe_snapshot.get("diagnostics"), dict) else {}
        stats = safe_snapshot.get("stats") if isinstance(safe_snapshot.get("stats"), dict) else {}
        conn.execute("DELETE FROM journal_trades")
        conn.execute("DELETE FROM journal_cashflows")
        conn.execute("DELETE FROM journal_balances")
        conn.execute("DELETE FROM journal_notes")
        conn.execute("DELETE FROM journal_metrics")
        for row in items:
            if not isinstance(row, dict):
                continue
            row_id = str(row.get("id") or uuid4().hex)
            payload_json = json.dumps(row, ensure_ascii=False)
            row_type = _row_type(row)
            if row_type == "cashflow":
                conn.execute("INSERT OR REPLACE INTO journal_cashflows(id,payload_json,imported_at) VALUES(?,?,?)", (row_id, payload_json, now_iso))
            elif row_type == "monthly_aud_reval":
                conn.execute("INSERT OR REPLACE INTO journal_notes(id,payload_json,imported_at) VALUES(?,?,?)", (row_id, payload_json, now_iso))
            else:
                conn.execute("INSERT OR REPLACE INTO journal_trades(id,payload_json,imported_at) VALUES(?,?,?)", (row_id, payload_json, now_iso))
                metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
                conn.execute("INSERT OR REPLACE INTO journal_metrics(id,payload_json,imported_at) VALUES(?,?,?)", (row_id, json.dumps(metrics, ensure_ascii=False), now_iso))
        for bal in balances:
            if not isinstance(bal, dict):
                continue
            account_key = _norm_account_key(str(bal.get("account") or bal.get("label") or uuid4().hex))
            conn.execute("INSERT OR REPLACE INTO journal_balances(account_key,payload_json,imported_at) VALUES(?,?,?)", (account_key, json.dumps(bal, ensure_ascii=False), now_iso))
        snapshot_id = str(safe_snapshot.get("generated_at") or now_iso)
        conn.execute("INSERT OR REPLACE INTO journal_stats(snapshot_id,payload_json,imported_at) VALUES(?,?,?)", (snapshot_id, json.dumps(stats, ensure_ascii=False), now_iso))
        conn.execute("INSERT OR REPLACE INTO journal_diagnostics(snapshot_id,payload_json,imported_at) VALUES(?,?,?)", (snapshot_id, json.dumps(diagnostics, ensure_ascii=False), now_iso))
        for src in (safe_snapshot.get("source_fingerprints") or {}).get("files", []):
            if not isinstance(src, dict):
                continue
            conn.execute(
                "INSERT OR REPLACE INTO source_files(absolute_path,file_size,modified_at,content_hash,last_imported_at) VALUES(?,?,?,?,?)",
                (str(src.get("path") or ""), int(src.get("size") or 0), float(src.get("mtime") or 0.0), str(src.get("sha256") or ""), now_iso),
            )
        if isinstance(safe_import_meta, dict):
            conn.execute(
                "INSERT INTO import_runs(started_at,finished_at,source_mode,workbooks_scanned,workbooks_changed,rows_imported,cashflow_rows_loaded,warnings_json,errors_json) VALUES(?,?,?,?,?,?,?,?,?)",
                (
                    str(safe_import_meta.get("started_at") or now_iso),
                    now_iso,
                    str(safe_import_meta.get("source_mode") or ""),
                    int(safe_import_meta.get("workbooks_scanned") or 0),
                    int(safe_import_meta.get("workbooks_changed") or 0),
                    int(safe_import_meta.get("rows_imported") or 0),
                    int(safe_import_meta.get("cashflow_rows_loaded") or 0),
                    json.dumps(safe_import_meta.get("warnings") or [], ensure_ascii=False),
                    json.dumps(safe_import_meta.get("errors") or [], ensure_ascii=False),
                ),
            )
        conn.commit()
    finally:
        conn.close()


def _persist_trading_journal_sqlite_incremental(
    changed_rows: List[Dict[str, object]],
    account_balance: Dict[str, object],
    *,
    import_meta: Optional[Dict[str, object]] = None,
    derived_refresh_state: Optional[Dict[str, object]] = None,
) -> None:
    safe_rows = _json_safe(
        [dict(row) for row in changed_rows if isinstance(row, dict)]
    )
    if not isinstance(safe_rows, list):
        safe_rows = []
    safe_balance = _json_safe(dict(account_balance))
    if not isinstance(safe_balance, dict):
        raise ValueError("Incremental journal persistence requires an account balance.")
    safe_import_meta = _json_safe(import_meta) if isinstance(import_meta, dict) else {}
    if not isinstance(safe_import_meta, dict):
        safe_import_meta = {}
    safe_refresh_state = (
        _json_safe(
            _public_trading_journal_derived_refresh_state(
                derived_refresh_state
            )
        )
        if isinstance(derived_refresh_state, dict)
        else {}
    )
    if not isinstance(safe_refresh_state, dict):
        safe_refresh_state = {}
    affected_row_ids = sorted(
        {
            str(row.get("id") or "").strip()
            for row in safe_rows
            if isinstance(row, dict) and str(row.get("id") or "").strip()
        }
    )
    metadata = {
        "derived_refresh_pending": True,
        "derived_refresh": safe_refresh_state,
        "affected_row_ids": affected_row_ids,
    }
    TRADING_JOURNAL_SQLITE_PATH.parent.mkdir(parents=True, exist_ok=True)
    now_iso = _utc_now_iso()
    conn = sqlite3.connect(TRADING_JOURNAL_SQLITE_PATH)
    try:
        _ensure_trading_journal_sqlite_schema(conn)
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        for row in safe_rows:
            if not isinstance(row, dict) or _row_type(row) != "trade":
                continue
            row_id = str(row.get("id") or "").strip()
            if not row_id:
                raise ValueError("Incremental journal row is missing a stable ID.")
            conn.execute(
                "INSERT OR REPLACE INTO journal_trades(id,payload_json,imported_at) VALUES(?,?,?)",
                (row_id, json.dumps(row, ensure_ascii=False), now_iso),
            )
            metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
            conn.execute(
                "INSERT OR REPLACE INTO journal_metrics(id,payload_json,imported_at) VALUES(?,?,?)",
                (row_id, json.dumps(metrics, ensure_ascii=False), now_iso),
            )
        account_key = _norm_account_key(
            safe_balance.get("account")
            or safe_balance.get("label")
            or safe_balance.get("account_label")
        )
        if not account_key:
            raise ValueError("Incremental account balance is missing an account label.")
        conn.execute(
            "INSERT OR REPLACE INTO journal_balances(account_key,payload_json,imported_at) VALUES(?,?,?)",
            (account_key, json.dumps(safe_balance, ensure_ascii=False), now_iso),
        )
        conn.execute(
            "INSERT INTO import_runs(started_at,finished_at,source_mode,workbooks_scanned,workbooks_changed,rows_imported,cashflow_rows_loaded,warnings_json,errors_json,metadata_json) VALUES(?,?,?,?,?,?,?,?,?,?)",
            (
                str(safe_import_meta.get("started_at") or now_iso),
                now_iso,
                str(safe_import_meta.get("source_mode") or "manual_upload_incremental"),
                int(safe_import_meta.get("workbooks_scanned") or 1),
                int(safe_import_meta.get("workbooks_changed") or 1),
                int(safe_import_meta.get("rows_imported") or len(safe_rows)),
                int(safe_import_meta.get("cashflow_rows_loaded") or 0),
                json.dumps(safe_import_meta.get("warnings") or [], ensure_ascii=False),
                json.dumps(safe_import_meta.get("errors") or [], ensure_ascii=False),
                json.dumps(metadata, ensure_ascii=False),
            ),
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _journal_local_now_naive_iso() -> str:
    tz_name = str(APP_TIMEZONE or "").strip() or "Australia/Brisbane"
    try:
        now = datetime.now(ZoneInfo(tz_name))
    except Exception:
        now = datetime.now(ZoneInfo("Australia/Brisbane"))
    return now.replace(tzinfo=None, microsecond=0).isoformat()


def _check_master_journal_write_lock(path: Path) -> Dict[str, object]:
    if not path.exists():
        return {"locked": False, "reason": "", "path": str(path)}
    lock_file = path.with_name(f"~${path.name}")
    if os.name == "nt":
        try:
            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            handle = kernel32.CreateFileW(str(path), 0x40000000, 0, None, 3, 0x80, None)
            invalid = ctypes.c_void_p(-1).value
            if handle == invalid or handle == -1:
                err = ctypes.get_last_error() if hasattr(ctypes, "get_last_error") else None
                return {"locked": True, "code": "EXCEL_WORKBOOK_OPEN", "reason": "workbook_locked", "path": str(path), "lock_file": str(lock_file) if lock_file.exists() else "", "winerror": err}
            try:
                kernel32.CloseHandle(handle)
            except Exception:
                pass
            if lock_file.exists():
                return {"locked": False, "reason": "lockfile_stale", "path": str(path), "lock_file": str(lock_file)}
            return {"locked": False, "reason": "", "path": str(path)}
        except Exception as exc:
            return {"locked": True, "reason": "workbook_locked", "path": str(path), "error": str(exc), "error_type": type(exc).__name__}
    if lock_file.exists():
        return {"locked": True, "reason": "excel_open", "path": str(path), "lock_file": str(lock_file)}
    try:
        with path.open("r+b"):
            pass
    except Exception as exc:
        return {"locked": True, "reason": "workbook_locked", "path": str(path), "error": str(exc), "error_type": type(exc).__name__}
    return {"locked": False, "reason": "", "path": str(path)}


def _master_journal_lock_status(path: Path) -> Dict[str, object]:
    return _check_master_journal_write_lock(path)


def _is_workbook_lock_exception(exc: BaseException) -> bool:
    if isinstance(exc, PermissionError):
        return True
    winerror = getattr(exc, "winerror", None)
    if winerror in {5, 32, 33}:
        return True
    text = str(exc).lower()
    return "access is denied" in text or "permission denied" in text or "being used by another process" in text


def _excel_workbook_open_payload(*, message_prefix: str = "Trading Journal.xlsx appears to be open in Excel", status_code: int = 423, extra: Optional[Dict[str, object]] = None) -> Dict[str, object]:
    payload: Dict[str, object] = {
        "ok": False,
        "status_code": status_code,
        "code": "EXCEL_WORKBOOK_OPEN",
        "retryable": True,
        "errors": ["workbook_locked"],
        "message": f"{message_prefix}. Close Excel, then press Resume.",
    }
    if extra:
        payload.update(extra)
    return payload


def _update_trading_journal_import_status(**updates: object) -> None:
    with TRADING_JOURNAL_IMPORT_STATUS_LOCK:
        TRADING_JOURNAL_IMPORT_STATUS.update(updates)
        TRADING_JOURNAL_IMPORT_STATUS["updated_at"] = _utc_now_iso()


def _trading_journal_import_status_snapshot() -> Dict[str, object]:
    with TRADING_JOURNAL_IMPORT_STATUS_LOCK:
        status = dict(TRADING_JOURNAL_IMPORT_STATUS)
    started = status.get("started_at")
    status["elapsed_seconds"] = round(max(0.0, time.time() - float(status.get("started_epoch") or time.time())), 3) if status.get("running") else 0.0
    if started and not status.get("running"):
        status.pop("started_epoch", None)
    status["derived_refresh"] = _trading_journal_derived_refresh_status_snapshot()
    return status


def _cashflow_row_to_ledger_event(row: Dict[str, object]) -> Dict[str, object]:
    row_data = row if isinstance(row, dict) else {}
    row_id = str(row_data.get("id") or "").strip()
    account = str(row_data.get("account_label") or row_data.get("account") or "").strip()
    date = str(row_data.get("close_time") or row_data.get("open_time") or "").strip()
    amount = _to_float(row_data.get("cashflow_amount"))
    if amount is None:
        amount = _to_float(row_data.get("amount"))
    new_balance = _to_float(row_data.get("cashflow_new_balance"))
    if new_balance is None:
        new_balance = _to_float(row_data.get("balance_after_trade"))
    currency = str(
        row_data.get("currency")
        or row_data.get("account_currency")
        or row_data.get("balance_after_trade_currency")
        or ""
    ).strip()
    reason = str(row_data.get("notes") or row_data.get("cashflow_reason") or "").strip()
    if not account or not date or new_balance is None:
        return {}
    return {
        "id": row_id,
        "account": account,
        "date": date,
        "amount": amount,
        "new_balance": new_balance,
        "currency": currency,
        "reason": reason,
        "side": str(row_data.get("side") or row_data.get("cashflow_type") or "").strip(),
    }


def _normalize_cashflow_ledger_keys(ledger: Dict[str, object]) -> Dict[str, List[Dict[str, object]]]:
    out: Dict[str, List[Dict[str, object]]] = {}
    for raw_key, events in (ledger or {}).items():
        fallback_key = _norm_account_key(raw_key)
        for ev in (events or []):
            if isinstance(ev, dict):
                event = dict(ev)
                event_key = _norm_account_key(event.get("account"))
                bucket_key = event_key or fallback_key
                if not bucket_key:
                    continue
                out.setdefault(bucket_key, []).append(event)
    return out


def _merge_pending_cashflow_rows_into_ledger(ledger: Dict[str, object], pending_rows: List[Dict[str, object]]) -> Dict[str, List[Dict[str, object]]]:
    merged = _normalize_cashflow_ledger_keys(ledger if isinstance(ledger, dict) else {})
    def event_identity(event: Dict[str, object]) -> Tuple[object, ...]:
        return (
            _norm_account_key(event.get("account")),
            round(_timestamp_epoch_seconds(event.get("date")), 6),
            _to_float(event.get("amount")),
            _to_float(event.get("new_balance")),
            str(event.get("currency") or "").strip().upper(),
        )

    seen_ids = {str((ev or {}).get("id") or "").strip() for vals in merged.values() for ev in vals if isinstance(ev, dict)}
    seen_ids.discard("")
    seen_events = {
        event_identity(ev)
        for vals in merged.values()
        for ev in vals
        if isinstance(ev, dict)
    }
    for row in pending_rows or []:
        if not isinstance(row, dict) or str(row.get("row_type") or "").strip().lower() != "cashflow":
            continue
        row_id = str(row.get("id") or "").strip()
        if row_id and row_id in seen_ids:
            continue
        event = _cashflow_row_to_ledger_event(row)
        if not event:
            continue
        identity = event_identity(event)
        if identity in seen_events:
            continue
        key = _norm_account_key(event.get("account") or row.get("account_label") or row.get("account") or "")
        if not key:
            continue
        merged.setdefault(key, []).append(event)
        seen_events.add(identity)
        if row_id:
            seen_ids.add(row_id)
    return merged


def _build_trading_journal_view_snapshot(
    force: bool = False,
    *,
    local_only: bool = False,
    skip_external_balances: bool = False,
    skip_live_account_refresh: bool = False,
    persist_sqlite: bool = True,
    sync_id: Optional[str] = None,
    sync_caller: Optional[str] = None,
) -> Dict[str, object]:
    snapshot_sync_id = str(sync_id or f"snapshot-{uuid4().hex[:12]}")
    snapshot_caller = str(sync_caller or "snapshot").strip() or "snapshot"
    snapshot_started = time.perf_counter()
    APP_LOGGER.info(
        "trading_journal_snapshot_build_start sync_id=%s caller=%s force=%s local_only=%s skip_external_balances=%s skip_live_account_refresh=%s",
        snapshot_sync_id, snapshot_caller, force, local_only, skip_external_balances, skip_live_account_refresh,
    )
    existing = _load_trading_journal_view_snapshot()
    fingerprint = _journal_source_fingerprint()
    existing_freshness = _trading_journal_snapshot_freshness(existing, fingerprint)
    if not local_only and not force and existing_freshness.get("current") is True:
        APP_LOGGER.info("trading_journal_snapshot_build_done sync_id=%s caller=%s elapsed=%.6fs cached=True", snapshot_sync_id, snapshot_caller, time.perf_counter() - snapshot_started)
        return existing
    source_mode_runtime = str(os.getenv("TRADING_JOURNAL_SOURCE", TRADING_JOURNAL_SOURCE) or "").strip().lower()
    if source_mode_runtime not in {"dropbox", "local", "both", "auto", "master_journal"}:
        source_mode_runtime = _trading_journal_source_mode()
    authoritative_enabled = _master_journal_authoritative_enabled()
    use_master_journal_snapshot = _master_journal_single_file_mode()
    if (
        not use_master_journal_snapshot
        and authoritative_enabled
        and force
        and source_mode_runtime in {"both", "master_journal"}
        and _master_journal_path().exists()
    ):
        use_master_journal_snapshot = True
    if local_only:
        use_master_journal_snapshot = False
    if use_master_journal_snapshot:
        snapshot_substage_timings: Dict[str, float] = {}
        _snapshot_substage_started = time.perf_counter()

        def _finish_snapshot_substage(stage: str) -> None:
            nonlocal _snapshot_substage_started
            elapsed = round(time.perf_counter() - _snapshot_substage_started, 6)
            snapshot_substage_timings[stage] = elapsed
            APP_LOGGER.info(
                "trading_journal_snapshot_substage_done sync_id=%s caller=%s stage=%s elapsed=%.6fs",
                snapshot_sync_id, snapshot_caller, stage, elapsed,
            )
            _snapshot_substage_started = time.perf_counter()

        source_payload = read_master_journal_source(_master_journal_path())
        _finish_snapshot_substage("workbook_source_read")
        items = [dict(r) for r in (source_payload.get("items") or []) if isinstance(r, dict)]
        monthly_note_rows = _monthly_aud_revaluation_rows_for_journal_view()
        _finish_snapshot_substage("monthly_aud_revaluation_rows")
        monthly_fallback_by_id = {
            str(row.get("id") or "").strip(): _normalize_monthly_aud_reval_snapshot_row(row)
            for row in monthly_note_rows
            if _is_monthly_aud_reval_row(row) and str(row.get("id") or "").strip()
        }
        if _PENDING_MANUAL_SYNC_ROWS:
            merged: Dict[str, Dict[str, object]] = {}
            for row in items:
                rid = str(row.get("id") or "").strip()
                if rid:
                    merged[rid] = row
            for row in _PENDING_MANUAL_SYNC_ROWS:
                if not isinstance(row, dict):
                    continue
                rid = str(row.get("id") or "").strip()
                if rid:
                    merged[rid] = dict(row)
            items = list(merged.values())
        merged_items: List[Dict[str, object]] = []
        seen_monthly_ids: Set[str] = set()
        canonical_monthly_indexes: Dict[str, int] = {}
        canonical_monthly_ranks: Dict[str, Tuple[int, int, int, int, int, int, str]] = {}
        duplicate_monthly_rows_removed = 0
        duplicate_monthly_ids: Set[str] = set()
        for row in items:
            if not _is_monthly_aud_reval_row(row):
                merged_items.append(row)
                continue
            row_id = str(row.get("id") or "").strip()
            fallback = monthly_fallback_by_id.get(row_id)
            normalized_row = _normalize_monthly_aud_reval_snapshot_row(row, fallback=fallback)
            canonical_month = _canonical_monthly_aud_reval_id_month(row_id)
            existing_index = canonical_monthly_indexes.get(row_id) if canonical_month else None
            if existing_index is not None:
                duplicate_monthly_rows_removed += 1
                duplicate_monthly_ids.add(row_id)
                candidate_rank = _monthly_aud_reval_snapshot_record_rank(row)
                if candidate_rank > canonical_monthly_ranks[row_id]:
                    merged_items[existing_index] = normalized_row
                    canonical_monthly_ranks[row_id] = candidate_rank
                seen_monthly_ids.add(row_id)
                continue
            if canonical_month:
                canonical_monthly_indexes[row_id] = len(merged_items)
                canonical_monthly_ranks[row_id] = _monthly_aud_reval_snapshot_record_rank(row)
            merged_items.append(normalized_row)
            if row_id:
                seen_monthly_ids.add(row_id)
        for row_id, fallback_row in monthly_fallback_by_id.items():
            if row_id in seen_monthly_ids:
                continue
            merged_items.append(dict(fallback_row))
        items = _sanitize_oanda_commission_fields(merged_items)
        _finish_snapshot_substage("pending_and_monthly_merge")
        raw_trade_items = [r for r in items if _row_type(r) == "trade"]
        non_trade_items = [r for r in items if _row_type(r) != "trade"]
        _finish_snapshot_substage("trade_cashflow_split")
        trade_items = [_backfill_trade_row_context_fields(dict(r)) if isinstance(r, dict) else r for r in raw_trade_items]
        _finish_snapshot_substage("trade_context_backfill_initial")
        trade_items = _enrich_trade_row_metrics(trade_items)
        _finish_snapshot_substage("trade_metric_enrichment_initial")
        merged_ledger = _merge_pending_cashflow_rows_into_ledger(
            source_payload.get("cashflow_ledger") or {},
            _PENDING_MANUAL_SYNC_ROWS or [],
        )
        source_balance_seeds = _snapshot_balance_items(source_payload)
        external_balance_seeds = [] if skip_external_balances else _get_excel_account_balances()
        timeline_balance_seeds = [
            *[dict(item) for item in source_balance_seeds],
            *[dict(item) for item in external_balance_seeds if isinstance(item, dict)],
            *[dict(item) for item in _PENDING_MANUAL_SYNC_BALANCES if isinstance(item, dict)],
        ]
        timeline = _build_journal_balance_timelines(
            trade_items,
            merged_ledger,
            timeline_balance_seeds,
        )
        _finish_snapshot_substage("balance_timeline_build")
        trade_items = [_backfill_trade_row_context_fields(dict(r)) if isinstance(r, dict) else r for r in (timeline.get("rows") if isinstance(timeline.get("rows"), list) else trade_items)]
        _finish_snapshot_substage("trade_context_backfill_post_timeline")
        trade_items = _enrich_trade_row_metrics(trade_items)
        _finish_snapshot_substage("trade_metric_enrichment_post_timeline")
        items = sorted([*trade_items, *non_trade_items], key=_row_sort_dt, reverse=True)
        _finish_snapshot_substage("journal_item_sort")
        balances = timeline.get("balances") or []
        state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
        _finish_snapshot_substage("local_state_read")
        broker_balances = [] if (skip_external_balances or skip_live_account_refresh) else ((state or {}).get("broker_account_balances") if isinstance(state, dict) else [])
        if not isinstance(broker_balances, list):
            broker_balances = []
        balances = _merge_missing_timeline_balances_with_broker(balances, broker_balances)
        _finish_snapshot_substage("broker_balance_merge")
        stats = _compute_journal_stats_with_period_reports(items, balances)
        _finish_snapshot_substage("stats_dashboard_instrument_calendar_build")
        diagnostics = _build_authoritative_trading_journal_diagnostics_snapshot(items)
        _finish_snapshot_substage("diagnostics_build")
        diagnostics.update({
            "source": "master_journal_authoritative",
            "authoritative_mode": True,
            "source_workbooks_scanned": 0,
            "parsed_trade_rows": len(trade_items),
            "parsed_cashflow_rows": len([r for r in non_trade_items if _row_type(r) == "cashflow"]),
            "duplicate_monthly_aud_reval_rows_removed": duplicate_monthly_rows_removed,
            "deduplicated_monthly_aud_reval_row_ids": sorted(duplicate_monthly_ids),
            "snapshot_substage_timings": dict(snapshot_substage_timings),
        })
        result = {"cache_version": TRADING_JOURNAL_VIEW_CACHE_VERSION, "generated_at": _utc_now_iso(), "items": items, "balances": balances, "stats": stats, "diagnostics": diagnostics, "source_fingerprints": fingerprint}
        monthly_note_by_id = {
            str(row.get("id") or ""): _normalize_monthly_aud_reval_snapshot_row(row)
            for row in items
            if _is_monthly_aud_reval_row(row)
        }
        safe_result = _json_safe(result)
        if not isinstance(safe_result, dict):
            safe_result = {}
        safe_items = safe_result.get("items")
        if isinstance(safe_items, list):
            normalized_items: List[Dict[str, object]] = []
            for item in safe_items:
                if not isinstance(item, dict):
                    continue
                if not _is_monthly_aud_reval_row(item):
                    normalized_items.append(item)
                    continue
                row_id = str(item.get("id") or "")
                fallback = monthly_note_by_id.get(row_id)
                if fallback is not None:
                    normalized_items.append(dict(fallback))
                else:
                    normalized_items.append(_normalize_monthly_aud_reval_snapshot_row(item))
            safe_result["items"] = normalized_items
        _attach_trading_journal_equity_metadata(safe_result)
        _save_trading_journal_view_snapshot(safe_result)
        _finish_snapshot_substage("view_cache_write")
        if persist_sqlite:
            _persist_trading_journal_sqlite(safe_result)
        _finish_snapshot_substage("sqlite_snapshot_persist")
        safe_diag = safe_result.get("diagnostics") if isinstance(safe_result.get("diagnostics"), dict) else {}
        if isinstance(safe_diag, dict):
            safe_diag["snapshot_substage_timings"] = dict(snapshot_substage_timings)
        _TRADING_JOURNAL_VIEW_CACHE["key"] = "snapshot"
        _TRADING_JOURNAL_VIEW_CACHE["payload"] = safe_result
        APP_LOGGER.info("trading_journal_snapshot_build_done sync_id=%s caller=%s elapsed=%.6fs cached=False mode=master_journal", snapshot_sync_id, snapshot_caller, time.perf_counter() - snapshot_started)
        return safe_result
    rows = _sanitize_oanda_commission_fields([
        _backfill_trade_row_context_fields(r)
        for r in _get_trading_journal_rows()
        if _is_visible_trading_journal_row(r)
    ])
    if _trading_journal_local_excel_authoritative():
        rows = [
            r for r in rows
            if (_row_type(r) != "trade") or str(r.get("source") or "").strip().lower() == "local_excel"
        ]
    excel_balances = [] if skip_external_balances else _get_excel_account_balances()
    excel_balances = [
        *[dict(item) for item in excel_balances if isinstance(item, dict)],
        *[dict(item) for item in _PENDING_MANUAL_SYNC_BALANCES if isinstance(item, dict)],
    ]
    balances_seed = [b for b in excel_balances if not _is_bybit_demo_account_label(b.get("label") or b.get("account"))]
    state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
    if local_only:
        local_cashflow_dir = TRADING_JOURNAL_LOCAL_DIR
        ledger = _load_cashflows_from_local(local_cashflow_dir) if (local_cashflow_dir / "account_cashflows.xlsx").exists() else {}
    else:
        ledger = _load_cashflows_for_active_journal_source(state if isinstance(state, dict) else {})
    source_cashflow_rows = [row for row in rows if _row_type(row) == "cashflow"]
    other_non_trade_rows = [
        row for row in rows
        if _row_type(row) not in {"trade", "cashflow"}
        and not _is_monthly_aud_reval_row(row)
    ]
    ledger = _merge_pending_cashflow_rows_into_ledger(ledger, source_cashflow_rows)
    timeline_source_rows = [row for row in rows if _row_type(row) == "trade"]
    excel_balances, oanda_balance_warnings = _reconcile_oanda_export_balance_labels(
        excel_balances,
        ledger,
    )
    timeline = _build_journal_balance_timelines(timeline_source_rows, ledger, excel_balances)
    trade_items = _enrich_trade_row_metrics(timeline.get("rows") if isinstance(timeline.get("rows"), list) else timeline_source_rows)
    cashflow_rows = [r for r in _cashflow_rows_for_journal(ledger) if isinstance(r, dict) and not _exclude_bybit_demo_row(r)]
    stats_items = sorted([*trade_items, *cashflow_rows], key=_row_sort_dt, reverse=True)
    monthly_note_rows = _monthly_aud_revaluation_rows_for_journal_view()
    combined_items = sorted([*trade_items, *cashflow_rows, *other_non_trade_rows, *monthly_note_rows], key=_row_sort_dt, reverse=True)
    balances = timeline.get("balances") if isinstance(timeline.get("balances"), list) else []
    stats = _compute_journal_stats_with_period_reports(stats_items, balances)
    broker_balances = (state or {}).get("broker_account_balances") if isinstance(state, dict) else []
    if not isinstance(broker_balances, list):
        broker_balances = []
    balances = _merge_missing_timeline_balances_with_broker(balances, broker_balances)
    for bal in balances:
        if not isinstance(bal, dict):
            continue
        label = str(bal.get("label") or bal.get("account") or "").strip().upper()
        if (not local_only) and label == "OANDA DEMO" and str(bal.get("balance_source") or "") == "cashflow_anchor_plus_trades":
            demo_exports = [p for p in _list_local_oanda_history_exports() if "demo" in p.name.lower()]
            latest_export = sorted(demo_exports, key=lambda p: p.stat().st_mtime, reverse=True)[0] if demo_exports else None
            blocked_reason = None
            latest_backfill_error = (TRADING_JOURNAL_IMPORT_DIAGNOSTICS or {}).get("oanda_export_append_error")
            if latest_backfill_error and "MISSING_XLRD_FOR_XLS" in str(latest_backfill_error):
                blocked_reason = "MISSING_XLRD_FOR_XLS"
            elif not latest_export:
                blocked_reason = "OANDA_DEMO_EXPORT_NOT_FOUND"
            bal["stale_balance_warning"] = True
            bal["stale_balance_reason"] = "oanda_demo_cashflow_anchor"
            bal["repair_available"] = True
            bal["repair_endpoint"] = "/api/trading-journal/oanda-demo/repair-balance"
            bal["latest_backfill_error"] = latest_backfill_error
            bal["repair_export_available"] = bool(latest_export) and blocked_reason is None
            bal["repair_blocked_reason"] = blocked_reason
            bal["latest_oanda_demo_export_path"] = str(latest_export) if latest_export else ""
    diagnostics = _build_trading_journal_diagnostics_snapshot()
    diagnostics['authoritative_mode'] = False
    diagnostics['source'] = diagnostics.get('source') or 'trading_journal_sources'
    diagnostics["monthly_aud_revaluation_rows_visible"] = len(monthly_note_rows)
    diagnostics["monthly_aud_revaluation_latest_month"] = max((str((r.get("raw_refs") or {}).get("period_month") or "") for r in monthly_note_rows), default="")
    diagnostics["monthly_aud_revaluation_source_path"] = str(MONTHLY_AUD_REVALUATION_PATH)
    if oanda_balance_warnings:
        existing_errors = diagnostics.get("errors") if isinstance(diagnostics.get("errors"), list) else []
        diagnostics["errors"] = [*existing_errors, *oanda_balance_warnings]
    timeline_diag = timeline.get("diagnostics") if isinstance(timeline.get("diagnostics"), dict) else {}
    def _diag_account_key_variants(value: object) -> Set[str]:
        raw = str(value or "").strip()
        if not raw:
            return set()
        variants = {raw}
        variants.add(_norm_account_key(raw))
        variants.add(_norm_account_key(raw.replace("_", " ")))
        return {v for v in variants if v}

    balances_by_key: Dict[str, Dict[str, object]] = {}
    for item in balances:
        if not isinstance(item, dict):
            continue
        for candidate in _diag_account_key_variants(item.get("label") or item.get("account")):
            balances_by_key[candidate] = item
    for account_key, diag_entry in list(timeline_diag.items()):
        if not isinstance(diag_entry, dict):
            continue
        bal = None
        for candidate in _diag_account_key_variants(account_key):
            bal = balances_by_key.get(candidate)
            if isinstance(bal, dict):
                break
        if isinstance(bal, dict) and bool(bal.get("resolved_missing_balance_with_broker")):
            patched = dict(diag_entry)
            patched["missing_balance"] = False
            patched["resolved_missing_balance_with_broker"] = True
            patched["warning"] = ""
            timeline_diag[account_key] = patched
    missing_accounts = [d.get("account_key") for d in timeline_diag.values() if isinstance(d, dict) and d.get("missing_balance")]
    if missing_accounts:
        existing_errors = diagnostics.get("errors") if isinstance(diagnostics.get("errors"), list) else []
        diagnostics["errors"] = [*existing_errors, f"Missing balance anchor for accounts: {', '.join(str(x) for x in missing_accounts)}"]
    diagnostics["balance_timeline"] = timeline_diag
    broker_diag = (state or {}).get("broker_balance_diagnostics") if isinstance(state, dict) else {}
    if isinstance(broker_diag, dict):
        warnings = broker_diag.get("warnings")
        if isinstance(warnings, list) and warnings:
            existing_errors = diagnostics.get("errors") if isinstance(diagnostics.get("errors"), list) else []
            diagnostics["errors"] = [*existing_errors, *[str(w) for w in warnings if str(w).strip()]]
    try:
        if local_only or skip_live_account_refresh:
            export_files = []
        demo_balance = next(
            (b for b in balances if isinstance(b, dict) and str(b.get("label") or b.get("account") or "").strip().upper() == "OANDA DEMO"),
            None,
        )
        export_files = export_files if (local_only or skip_live_account_refresh) else [p for p in _list_local_oanda_history_exports() if "demo" in p.name.lower()]
        latest_export_balance = None
        latest_export_as_of = None
        for p in export_files:
            _rows_tmp, bal_tmp = _parse_local_trading_journal_workbook(p)
            if isinstance(bal_tmp, dict) and bal_tmp.get("balance") is not None:
                latest_export_balance = bal_tmp.get("balance")
                latest_export_as_of = bal_tmp.get("as_of")
        if isinstance(demo_balance, dict) and str(demo_balance.get("balance_source") or "") == "cashflow_anchor_plus_trades" and latest_export_as_of:
            diagnostics["stale_oanda_demo_balance_not_backfilled"] = True
            diagnostics["current_balance_source"] = demo_balance.get("balance_source")
            diagnostics["current_balance_as_of"] = demo_balance.get("as_of")
            diagnostics["latest_export_balance"] = latest_export_balance
            diagnostics["latest_export_as_of"] = latest_export_as_of
            diagnostics["backfill_required"] = True
    except Exception:
        pass
    payload: Dict[str, object] = {
        "cache_version": TRADING_JOURNAL_VIEW_CACHE_VERSION,
        "generated_at": _utc_now_iso(),
        "items": combined_items,
        "count": len(combined_items),
        "stats": stats,
        "balances": balances,
        "diagnostics": diagnostics,
        "warnings": diagnostics.get("errors") if isinstance(diagnostics.get("errors"), list) else [],
        "source_fingerprints": fingerprint,
    }
    monthly_note_by_id = {
        str(row.get("id") or ""): _normalize_monthly_aud_reval_snapshot_row(row)
        for row in monthly_note_rows
        if _is_monthly_aud_reval_row(row)
    }
    safe_payload = _json_safe(payload)
    if not isinstance(safe_payload, dict):
        safe_payload = {}
    safe_items = safe_payload.get("items")
    if isinstance(safe_items, list):
        normalized_items: List[Dict[str, object]] = []
        for item in safe_items:
            if not isinstance(item, dict):
                continue
            if not _is_monthly_aud_reval_row(item):
                normalized_items.append(item)
                continue
            row_id = str(item.get("id") or "")
            fallback = monthly_note_by_id.get(row_id)
            if fallback is not None:
                normalized_items.append(dict(fallback))
            else:
                normalized_items.append(_normalize_monthly_aud_reval_snapshot_row(item))
        safe_payload["items"] = normalized_items
    _attach_trading_journal_equity_metadata(safe_payload)
    _save_trading_journal_view_snapshot(safe_payload)
    if persist_sqlite:
        _persist_trading_journal_sqlite(safe_payload)
    _TRADING_JOURNAL_VIEW_CACHE["key"] = "snapshot"
    _TRADING_JOURNAL_VIEW_CACHE["payload"] = safe_payload
    APP_LOGGER.info("trading_journal_snapshot_build_done sync_id=%s caller=%s elapsed=%.6fs cached=False mode=sources", snapshot_sync_id, snapshot_caller, time.perf_counter() - snapshot_started)
    return safe_payload


def _reconcile_oanda_export_balance_labels(
    excel_balances: List[Dict[str, object]],
    cashflow_ledger: Dict[str, List[Dict[str, object]]],
) -> Tuple[List[Dict[str, object]], List[str]]:
    def _is_oanda_account_key_or_label(value: object) -> bool:
        text = str(value or "").strip().lower()
        norm = _norm_account_key(value).strip().lower()
        return ("oanda" in text) or ("oanda" in norm)

    def _canonical_oanda_key(value: object) -> Optional[str]:
        norm = _norm_account_key(value).strip().upper()
        if not norm or "OANDA" not in norm:
            return None
        if "DEMO" in norm:
            return "OANDA DEMO"
        if "LIVE" in norm:
            return "OANDA LIVE"
        return norm

    reconciled: List[Dict[str, object]] = []
    warnings: List[str] = []
    oanda_keys: Set[str] = set()
    for key, events in (cashflow_ledger or {}).items():
        if _is_oanda_account_key_or_label(key):
            canon = _canonical_oanda_key(key)
            if canon:
                oanda_keys.add(canon)
        for ev in (events or []):
            acct = (ev or {}).get("account")
            if _is_oanda_account_key_or_label(acct):
                canon = _canonical_oanda_key(acct)
                if canon:
                    oanda_keys.add(canon)
    for item in excel_balances or []:
        if not isinstance(item, dict):
            continue
        patched = dict(item)
        source = str(patched.get("balance_source") or patched.get("source") or "").strip().lower()
        if source != "oanda_transaction_export_balance":
            reconciled.append(patched)
            continue
        label = str(patched.get("label") or patched.get("account") or "").strip()
        text = f"{label} {patched.get('dropbox_path') or ''}".lower()
        if "demo" in text:
            target = "OANDA DEMO"
        elif "live" in text:
            target = "OANDA LIVE"
        elif len(oanda_keys) == 1:
            target = next(iter(oanda_keys))
        elif len(oanda_keys) > 1:
            warnings.append(
                f"ambiguous_oanda_export_account_mapping: cannot map export '{label}' to OANDA DEMO/LIVE without filename hint."
            )
            continue
        else:
            target = label
        patched["account"] = target
        patched["label"] = target
        as_of = patched.get("as_of")
        raw_refs = patched.get("raw_refs") if isinstance(patched.get("raw_refs"), dict) else {}
        if not as_of:
            as_of = raw_refs.get("transaction_date")
        has_dated_cashflow = any(
            _norm_account_key((ev or {}).get("account")) == _norm_account_key(target)
            and str((ev or {}).get("date") or "").strip()
            for ev in (cashflow_ledger.get(target) or [])
        )
        if (not str(as_of or "").strip()) and has_dated_cashflow:
            warnings.append(
                f"oanda_export_balance_missing_timestamp: cannot prove export balance is newer than cashflow for {target}."
            )
        reconciled.append(patched)
    return reconciled, warnings


