class BybitOrderRejected(RuntimeError):
    def __init__(
        self,
        *,
        ret_code: object,
        ret_msg: object,
        ret_ext_info: object,
        result: object,
        request_body: Dict[str, object],
        http_status: Optional[int],
        response_body: Optional[Dict[str, object]] = None,
    ) -> None:
        self.ret_code = ret_code
        self.ret_msg = str(ret_msg or "").strip() or "Unknown Bybit rejection"
        self.ret_ext_info = ret_ext_info if isinstance(ret_ext_info, dict) else {}
        self.result = result if isinstance(result, dict) else {}
        self.request_body = dict(request_body) if isinstance(request_body, dict) else {}
        self.http_status = int(http_status) if http_status is not None else None
        self.response_body = (
            dict(response_body) if isinstance(response_body, dict) else {}
        )
        message = (
            f"Bybit order rejected retCode={self.ret_code} retMsg={self.ret_msg} "
            f"http_status={self.http_status}"
        )
        super().__init__(message)


class BybitSignedAPIError(ValueError):
    def __init__(self, *, path: str, ret_code: object, ret_msg: object, recv_window: str, http_status: Optional[int], response_body: Optional[Dict[str, object]] = None) -> None:
        self.path = path
        self.ret_code = ret_code
        self.ret_msg = str(ret_msg or "").strip() or "Bybit request failed"
        self.recv_window = recv_window
        self.http_status = int(http_status) if http_status is not None else None
        self.response_body = dict(response_body) if isinstance(response_body, dict) else {}
        super().__init__(f"Bybit signed POST failed path={path} retCode={ret_code} retMsg={self.ret_msg} recv_window={recv_window}")


class BybitPreSubmitValidationError(ValueError):
    def __init__(self, *, code: str, message: str, debug: Dict[str, object]) -> None:
        self.code = code
        self.message = message
        self.debug = dict(debug or {})
        super().__init__(message)


class BybitPostCreateProtectionError(RuntimeError):
    def __init__(self, *, order_id: object, order_link_id: object, symbol: str, account: str, category: str, side: str, request_body: Dict[str, object], order_result: Dict[str, object], tpsl_error: str, stage: str) -> None:
        self.order_id = str(order_id or "")
        self.order_link_id = str(order_link_id or "")
        self.symbol = symbol
        self.account = account
        self.category = category
        self.side = side
        self.request_body = dict(request_body or {})
        self.order_result = dict(order_result or {})
        self.tpsl_error = str(tpsl_error or "")
        self.stage = stage
        super().__init__(f"Bybit order {self.order_id} created but TP/SL application failed at stage={stage}: {self.tpsl_error}")


class OandaUpstreamError(ValueError):
    def __init__(
        self,
        message: str,
        *,
        upstream_status: Optional[int],
        upstream_error_message: str,
        endpoint: str,
        mode: str,
        retry_exhausted: bool,
        maintenance_detected: bool,
    ) -> None:
        self.upstream_status = upstream_status
        self.upstream_error_message = _safe_bybit_diagnostic_text(
            upstream_error_message,
            fallback="",
        )
        self.endpoint = endpoint
        self.mode = mode
        self.retry_exhausted = bool(retry_exhausted)
        self.maintenance_detected = bool(maintenance_detected)
        safe_message = _safe_bybit_diagnostic_text(
            message,
            fallback="OANDA upstream request failed",
        )
        retry_detail = " after retry exhaustion" if self.retry_exhausted else ""
        super().__init__(
            f"{safe_message}{retry_detail} mode={mode} endpoint={endpoint}"
        )


class OandaUpstreamHTTPError(ValueError):
    def __init__(
        self,
        *,
        status_code: int,
        mode: str,
        account_id: str,
        endpoint: str,
        body_summary: str,
        transient: bool,
    ) -> None:
        self.status_code = status_code
        self.mode = mode
        self.account_id = account_id
        self.endpoint = endpoint
        self.body_summary = body_summary
        self.transient = transient
        super().__init__(
            f"OANDA upstream HTTP {status_code} mode={mode} "
            f"account={account_id} endpoint={endpoint}: {body_summary}"
        )


