BYBIT_BASE = "https://api.bybit.com"


def _is_likely_bybit_symbol(value: str) -> bool:
    s = str(value or "").strip().upper()
    if not s:
        return False
    return (
        s.endswith("USDT")
        or s.endswith("USDC")
        or s.endswith("USD")
        or s.endswith("PERP")
        or s.endswith("USDT.P")
    )


async def _bybit_get_async(base_url: str, path: str, params: Dict[str, object], *, timeout_s: float = 6.0, connect_s: float = 2.0, read_s: Optional[float] = None) -> Dict[str, object]:
    timeout = httpx.Timeout(timeout_s, connect=connect_s, read=(read_s if read_s is not None else timeout_s), write=timeout_s, pool=2.0)
    async with httpx.AsyncClient(timeout=timeout) as client:
        res = await client.get(f"{base_url}{path}", params=params)
    res.raise_for_status()
    return res.json()


ATR_SCANNER_SETTINGS_PATH = BASE_DIR / "render" / "data" / "atr_scanner_settings.json"


def _atr_scanner_public_base_url() -> str:
    """Resolve only a public live Bybit market-data origin for the scanner."""

    raw = str(os.getenv("BYBIT_PUBLIC_MARKET_BASE_URL") or BYBIT_BASE).strip().rstrip("/")
    parsed = urlparse(raw)
    host = str(parsed.hostname or "").strip().lower()
    try:
        port = parsed.port
    except ValueError:
        port = -1
    if (
        parsed.scheme == "https"
        and host in {"api.bybit.com", "api.bytick.com"}
        and parsed.username is None
        and parsed.password is None
        and port in {None, 443}
        and parsed.path in {"", "/"}
        and not parsed.params
        and not parsed.query
        and not parsed.fragment
    ):
        return f"https://{host}"
    return BYBIT_BASE


async def _atr_scanner_fetch_public_json(
    path: str, params: Dict[str, object]
) -> Dict[str, object]:
    return await _bybit_get_async(
        _atr_scanner_public_base_url(),
        path,
        params,
        timeout_s=12.0,
        connect_s=3.0,
        read_s=12.0,
    )


ATR_SCANNER_SERVICE = ATRScannerService(
    fetch_json=_atr_scanner_fetch_public_json,
    settings_path=ATR_SCANNER_SETTINGS_PATH,
    source_base_url=_atr_scanner_public_base_url(),
)


async def _bybit_avg_7d_turnover_usd_async(
    base_url: str, symbol: str, category: str = "linear"
) -> Optional[float]:
    try:
        end_ms = int(time.time() * 1000)
        data = await _bybit_get_async(
            base_url,
            "/v5/market/kline",
            {
                "category": category,
                "symbol": symbol,
                "interval": "D",
                "end": end_ms,
                "limit": 10,
            },
        )
        rows = (data.get("result") or {}).get("list") or []
        turnovers: List[float] = []
        for row in rows[:7]:
            if isinstance(row, list) and len(row) >= 7:
                try:
                    turnovers.append(float(row[6]))
                except Exception:
                    pass
        return (sum(turnovers) / len(turnovers)) if turnovers else None
    except Exception:
        return None




def _bybit_base_key(base_url: str) -> str:
    parsed = urlparse(str(base_url or '').strip())
    host = str(parsed.netloc or parsed.path or '').strip().lower()
    return host or str(base_url or '').strip().lower()


def _bybit_symbol_list_cache_key(base_url: str, category: str) -> str:
    category_key = category if category in {"linear", "spot", "inverse"} else "linear"
    return f"{_bybit_base_key(base_url)}:{category_key}"


def _bybit_instrument_cache_key(base_url: str, category: str, selector: str, selector_value: str) -> str:
    category_key = category if category in {"linear", "spot", "inverse"} else "linear"
    return f"{_bybit_base_key(base_url)}:{category_key}:{selector}:{str(selector_value or '').strip().upper()}"

async def _bybit_fetch_symbols_by_category(base_url: str, category: str) -> List[str]:
    symbols: List[str] = []
    cursor: Optional[str] = None
    for _ in range(10):
        params: Dict[str, object] = {"category": category, "limit": 1000}
        if cursor:
            params["cursor"] = cursor
        payload = await _bybit_get_async(base_url, "/v5/market/instruments-info", params)
        rows = (payload.get("result") or {}).get("list") or []
        if isinstance(rows, list):
            for row in rows:
                if not isinstance(row, dict):
                    continue
                symbol = str(row.get("symbol") or "").upper()
                if symbol:
                    symbols.append(symbol)
        cursor = (payload.get("result") or {}).get("nextPageCursor")
        if not cursor:
            break
    return sorted(set(symbols))


async def _bybit_get_symbols_by_category_cached(base_url: str, category: str) -> List[str]:
    category_key = category if category in {"linear", "spot", "inverse"} else "linear"
    cache_key = _bybit_symbol_list_cache_key(base_url, category_key)
    entry = _BYBIT_SYMBOL_LIST_CACHE.get(cache_key) or {"ts": 0.0, "symbols": []}
    now = time.time()
    cached = entry.get("symbols")
    ts = float(entry.get("ts") or 0.0)
    if isinstance(cached, list) and cached and (now - ts) <= _BYBIT_SYMBOL_LIST_CACHE_TTL_SECONDS:
        return list(cached)

    try:
        symbols = await _bybit_fetch_symbols_by_category(base_url, category_key)
    except Exception:
        if isinstance(cached, list) and cached:
            return list(cached)
        raise

    _BYBIT_SYMBOL_LIST_CACHE[cache_key] = {"ts": now, "symbols": symbols}
    return list(symbols)


async def _bybit_get_instrument_info_cached(base_url: str, category: str, symbol: str, *, timeout_s: float = 6.0, connect_s: float = 2.0, read_s: Optional[float] = None) -> Optional[Dict[str, object]]:
    category_key = category if category in {"linear", "spot", "inverse"} else "linear"
    symbol_key = str(symbol or "").strip().upper()
    if not symbol_key:
        return None
    cache_key = _bybit_instrument_cache_key(base_url, category_key, "symbol", symbol_key)
    now = time.time()
    cached = _BYBIT_INSTRUMENT_CACHE.get(cache_key)
    if cached and (now - float(cached.get("ts") or 0.0)) <= float(cached.get("ttl") or _BYBIT_INSTRUMENT_CACHE_TTL_SECONDS):
        row = cached.get("row")
        return dict(row) if isinstance(row, dict) else None
    payload = await _bybit_get_async(base_url, "/v5/market/instruments-info", {"category": category_key, "symbol": symbol_key}, timeout_s=timeout_s, connect_s=connect_s, read_s=read_s)
    items = (payload.get("result") or {}).get("list") or []
    row = dict(items[0]) if isinstance(items, list) and items and isinstance(items[0], dict) else None
    if row:
        _BYBIT_INSTRUMENT_CACHE[cache_key] = {"ts": now, "ttl": _BYBIT_INSTRUMENT_CACHE_TTL_SECONDS, "row": row}
    else:
        _BYBIT_INSTRUMENT_CACHE[cache_key] = {"ts": now, "ttl": _BYBIT_INSTRUMENT_NEGATIVE_TTL_SECONDS, "row": None}
    return row


async def _bybit_get_instrument_rows_by_base_cached(base_url: str, category: str, base_coin: str, *, timeout_s: float = 6.0, connect_s: float = 2.0, read_s: Optional[float] = None) -> List[Dict[str, object]]:
    category_key = category if category in {"linear", "spot", "inverse"} else "linear"
    base_key = str(base_coin or '').strip().upper()
    if not base_key:
        return []
    cache_key = _bybit_instrument_cache_key(base_url, category_key, "base", base_key)
    now = time.time()
    cached = _BYBIT_INSTRUMENT_CACHE.get(cache_key)
    if cached and (now - float(cached.get("ts") or 0.0)) <= float(cached.get("ttl") or _BYBIT_INSTRUMENT_CACHE_TTL_SECONDS):
        rows = cached.get("rows")
        return [dict(r) for r in rows] if isinstance(rows, list) else []
    payload = await _bybit_get_async(base_url, "/v5/market/instruments-info", {"category": category_key, "baseCoin": base_key}, timeout_s=timeout_s, connect_s=connect_s, read_s=read_s)
    rows = [dict(r) for r in ((payload.get("result") or {}).get("list") or []) if isinstance(r, dict)]
    ttl = _BYBIT_INSTRUMENT_CACHE_TTL_SECONDS if rows else _BYBIT_INSTRUMENT_NEGATIVE_TTL_SECONDS
    _BYBIT_INSTRUMENT_CACHE[cache_key] = {"ts": now, "ttl": ttl, "rows": rows}
    return rows


class CalculatorDependencyTimeout(Exception):
    def __init__(self, dependency: str, timeout_s: float, elapsed_ms: int, path: Optional[str] = None):
        self.dependency = dependency
        self.timeout_s = timeout_s
        self.elapsed_ms = elapsed_ms
        self.path = path
        super().__init__(f"{dependency} timed out after {timeout_s}s")


def _calculator_quote_elapsed_ms(quote_started: Optional[float]) -> int:
    if not quote_started:
        return 0
    return int((time.perf_counter() - quote_started) * 1000)


def _calculator_remaining_timeout_s(deadline: Optional[float], fallback_s: float) -> float:
    if not deadline:
        return max(0.01, fallback_s)
    remaining = deadline - time.perf_counter()
    return max(0.01, min(fallback_s, remaining))


def _calculator_safe_submitted_payload(payload: Dict[str, object]) -> Dict[str, object]:
    safe: Dict[str, object] = {}
    for key in ("asset", "account", "submitted_symbol", "webhook", "test", "timeframe", "risk_mode", "risk_value", "stop_loss_ticks", "order_type", "side"):
        if key in payload:
            safe[key] = payload.get(key)
    return safe




def _classify_bybit_api_key_expired(error_text: object, *, account: str = "", key_source: str = "", dependency: str = "bybit_wallet_balance", path: str = "/v5/account/wallet-balance") -> Optional[Dict[str, object]]:
    text = str(error_text or "")
    low = text.lower()
    ret_match = re.search(r"retCode=([0-9-]+)", text)
    ret_code = ret_match.group(1) if ret_match else ""
    msg_match = re.search(r"retMsg=([^\n\r]+)", text)
    ret_msg = (msg_match.group(1).strip() if msg_match else "")
    if ret_msg:
        ret_msg = ret_msg.split(" recv_window=")[0].strip()
    if ret_code != "33004" and "api key has expired" not in low:
        return None
    acct = str(account or "live").strip().lower()
    account_label = "Demo" if acct == "demo" else "Live"
    env_hint = "BYBIT_API_KEY2/BYBIT_API_SECRET2" if acct == "demo" else "BYBIT_API_KEY1/BYBIT_API_SECRET1"
    return {
        "code": "BYBIT_API_KEY_EXPIRED",
        "dependency": dependency,
        "account": acct,
        "key_source": str(key_source or ""),
        "path": path,
        "retCode": 33004,
        "retMsg": ret_msg or "Your api key has expired",
        "message": f"Bybit {account_label} API key has expired. Replace {env_hint}, then restart Local Trading Tools.",
    }


def _build_bybit_demo_calc_context_save_error(
    *,
    error: Exception,
    resolved_symbol: str,
    account: str,
    timings_ms: Dict[str, Any],
    quote_started: Optional[float],
    submitted_payload: Dict[str, object],
    pending_dependencies: Set[str],
) -> Dict[str, object]:
    return {
        "code": "BYBIT_DEMO_CALC_CONTEXT_SAVE_FAILED",
        "message": (
            "Bybit Demo calculation was not saved to the repo-local calculation context file, so the journal cannot safely enrich the completed trade."
            if _calc_context_uses_repo_local()
            else "Bybit Demo calculation was not saved to Dropbox, so the journal cannot safely enrich the completed trade."
        ),
        "debug": {
            "context_path": _bybit_demo_calc_context_path(),
            "state_source": ("repo_local" if _calc_context_uses_repo_local() else "dropbox"),
            "error": str(error),
            "symbol": resolved_symbol,
            "account": account,
            "quote_latency_ms": _calculator_quote_elapsed_ms(quote_started),
            "upstream_timings_ms": timings_ms or {},
            "submitted_payload": submitted_payload or {},
            "resolved_symbol": resolved_symbol or "",
            "pending_dependencies": sorted(pending_dependencies or set()),
        },
    }

def _calculator_quote_error_detail(
    code: str,
    message: str,
    *,
    dependency: Optional[str] = None,
    timings_ms: Optional[Dict[str, Any]] = None,
    quote_started: Optional[float] = None,
    submitted_payload: Optional[Dict[str, object]] = None,
    resolved_symbol: Optional[str] = None,
    pending_dependencies: Optional[Set[str]] = None,
) -> Dict[str, object]:
    return {
        "code": code,
        "message": message,
        "dependency": dependency,
        "debug": {
            "submitted_payload": submitted_payload or {},
            "resolved_symbol": resolved_symbol or "",
            "quote_latency_ms": _calculator_quote_elapsed_ms(quote_started),
            "quote_timeout_ms": int(CALCULATOR_QUOTE_TIMEOUT_S * 1000),
            "upstream_timings_ms": timings_ms or {},
            "pending_dependencies": sorted(pending_dependencies or set()),
        },
    }


async def _calculator_timed_dependency(
    name: str,
    coro: Any,
    timings_ms: Dict[str, Any],
    timeout_s: float,
    path: Optional[str] = None,
    *,
    deadline: Optional[float] = None,
    pending_dependencies: Optional[Set[str]] = None,
    last_dependency_started: Optional[Dict[str, Optional[str]]] = None,
) -> Any:
    started = time.perf_counter()
    if pending_dependencies is not None:
        pending_dependencies.add(name)
    if last_dependency_started is not None:
        last_dependency_started["name"] = name
    CALCULATOR_LOGGER.info("CALCULATOR_QUOTE_DEPENDENCY_START dependency=%s path=%s", name, path or "")
    try:
        effective_timeout = _calculator_remaining_timeout_s(deadline, timeout_s)
        result = await asyncio.wait_for(coro, timeout=effective_timeout)
        elapsed = int((time.perf_counter() - started) * 1000)
        timings_ms[name] = {"elapsed_ms": elapsed, "timeout_ms": int(effective_timeout * 1000), "path": path, "status": "ok"}
        CALCULATOR_LOGGER.info("CALCULATOR_QUOTE_DEPENDENCY_DONE dependency=%s elapsed_ms=%s path=%s", name, elapsed, path or "")
        return result
    except asyncio.CancelledError:
        raise
    except asyncio.TimeoutError as exc:
        elapsed = int((time.perf_counter() - started) * 1000)
        timings_ms[name] = {"elapsed_ms": elapsed, "timeout_ms": int((locals().get("effective_timeout", timeout_s))*1000), "path": path, "status": "timeout"}
        CALCULATOR_LOGGER.warning("CALCULATOR_QUOTE_DEPENDENCY_TIMEOUT dependency=%s elapsed_ms=%s timeout_s=%s path=%s", name, elapsed, timeout_s, path or "")
        raise CalculatorDependencyTimeout(name, timeout_s, elapsed, path) from exc
    finally:
        if pending_dependencies is not None:
            pending_dependencies.discard(name)


async def _bybit_lookup_symbol(base_url: str, symbol: str) -> Optional[Dict[str, object]]:
    normalized_symbol = _norm_symbol(symbol)
    if not normalized_symbol:
        return None

    for category in ("linear", "spot", "inverse"):
        try:
            choices = await _bybit_get_symbols_by_category_cached(base_url, category)
        except Exception:
            choices = []
        resolved = resolve_bybit_symbol_from_choices(
            normalized_symbol,
            choices,
            preferred_quotes=("USDT", "USDC", "USD"),
            exact_first=True,
        )
        if not resolved or not resolved.get("resolved_symbol"):
            name_aliases = await _bybit_name_aliases_for_choices(base_url, set(choices))
            if name_aliases:
                resolved = resolve_bybit_symbol_from_choices(
                    normalized_symbol,
                    choices,
                    preferred_quotes=("USDT", "USDC", "USD"),
                    exact_first=True,
                    extra_aliases=name_aliases,
                )
        resolved_symbol = str((resolved or {}).get("resolved_symbol") or "").upper()
        if not resolved_symbol:
            continue
        try:
            payload = await _bybit_get_async(
                base_url,
                "/v5/market/instruments-info",
                {"category": category, "symbol": resolved_symbol},
            )
        except Exception:
            continue

        items = (payload.get("result") or {}).get("list") or []
        if isinstance(items, list) and items and isinstance(items[0], dict):
            inst = dict(items[0])
            inst["_category"] = category
            return inst
    return None


async def _bybit_lookup_linear_symbol_with_fallback(base_url: str, symbol: str) -> Optional[Dict[str, object]]:
    inst = await _bybit_lookup_symbol(base_url, symbol)
    tick = ((inst or {}).get("priceFilter") or {}).get("tickSize") if isinstance(inst, dict) else None
    if tick not in (None, "", "0", 0):
        return inst
    payload = await _bybit_get_async(base_url, "/v5/market/instruments-info", {"category": "linear", "symbol": symbol})
    rows = ((payload.get("result") or {}).get("list") or []) if isinstance(payload, dict) else []
    for row in rows:
        if isinstance(row, dict) and str(row.get("symbol") or "").upper() == str(symbol).upper():
            row_tick = ((row.get("priceFilter") or {}).get("tickSize") if isinstance(row, dict) else None)
            if row_tick in (None, "", "0", 0):
                continue
            row["_category"] = "linear"
            return row
    return None


def _oanda_specs_mode() -> str:
    env = (os.getenv("OANDA_ENV") or "live").strip().lower()
    return "demo" if env in {"practice", "demo", "test"} else "live"


async def _oanda_resolve_and_fetch_specs(query: str) -> Optional[Dict[str, object]]:
    try:
        normalized_query = _normalize_oanda_symbol_query(query)
    except ValueError:
        return None

    cache_key = normalized_query.upper()
    now = time.time()
    cached = _OANDA_SPECS_CACHE.get(cache_key)
    if cached and cached[0] > now:
        return dict(cached[1])

    try:
        cfg = _get_oanda_config(_oanda_specs_mode())
        payload = await _fetch_oanda_json(
            base_url=cfg["base_url"],
            account_id=cfg["account_id"],
            api_key=cfg["token"],
            endpoint=f"/accounts/{{account_id}}/instruments?instruments={normalized_query}",
            mode=cfg["mode"],
            timeout_s=4.0,
        )
    except ValueError:
        return None

    instruments = payload.get("instruments") or []
    if not isinstance(instruments, list) or not instruments:
        return None

    matched = instruments[0] if isinstance(instruments[0], dict) else None
    if not matched:
        return None

    financing = matched.get("financing") or {}
    result = {
        "source": "oanda",
        "query": query,
        "resolved_symbol": matched.get("name"),
        "type": matched.get("type"),
        "displayName": matched.get("displayName"),
        "pipLocation": matched.get("pipLocation"),
        "displayPrecision": matched.get("displayPrecision"),
        "tradeUnitsPrecision": matched.get("tradeUnitsPrecision"),
        "minimumTradeSize": matched.get("minimumTradeSize"),
        "maximumOrderUnits": matched.get("maximumOrderUnits"),
        "marginRate": matched.get("marginRate"),
        "financing.longRate": financing.get("longRate"),
        "financing.shortRate": financing.get("shortRate"),
        "financing.financingDaysOfWeek": financing.get("financingDaysOfWeek"),
    }
    _OANDA_SPECS_CACHE[cache_key] = (now + _OANDA_SPECS_CACHE_TTL_SECONDS, result)
    return dict(result)


async def _bybit_fetch_range_specs_async(base_url: str, category: str, symbol: str) -> Tuple[Dict[str, float], List[Dict[str, str]]]:
    out: Dict[str, float] = {}
    warnings: List[Dict[str, str]] = []
    for field, interval in _BYBIT_RANGE_INTERVALS:
        try:
            payload = await _bybit_get_async(
                base_url,
                "/v5/market/kline",
                {"category": category, "symbol": symbol, "interval": interval, "limit": 1},
            )
            rows = _bybit_parse_kline_rows((payload.get("result") or {}).get("list"))
            if not rows:
                raise ValueError("No kline rows returned")
            row = rows[-1]
            if len(row) < 4:
                raise ValueError("Kline row missing OHLC fields")
            open_price = float(row[1]); high = float(row[2]); low = float(row[3])
            if open_price <= 0:
                raise ValueError(f"Open price <= 0 ({open_price})")
            out[field] = (high - low) / open_price
        except Exception as exc:
            warnings.append({"scope": "range", "symbol": symbol, "field": field, "message": str(exc)})
    return out, warnings


def _is_bitcoin_bybit_symbol(symbol: str, resolved_inst: Dict[str, object]) -> bool:
    base_coin = str((resolved_inst or {}).get("baseCoin") or "").upper()
    sym = str(symbol or "").upper()
    return base_coin == "BTC" or sym.startswith("BTC")


def _btc_reference_symbol_for_category(category: str, quote_coin: Optional[str] = None) -> str:
    cat = str(category or "").lower()
    quote = str(quote_coin or "").upper()
    if cat == "inverse":
        return "BTCUSD"
    if cat == "linear" and quote == "USDC":
        return "BTCUSDC"
    return "BTCUSDT"


async def _bybit_resolve_and_fetch_specs(query: str, *, include_btc_reference: bool = True) -> Optional[Dict[str, object]]:
    want_key = _normalize_instrument_key(query)
    if not want_key:
        return None
    creds = resolve_bybit_credentials_for("default")
    base_url = (creds.get("base_url") if isinstance(creds, dict) else None) or BYBIT_BASE
    resolved_inst = await _bybit_lookup_symbol(base_url, want_key)
    if not resolved_inst:
        return None
    category = str(resolved_inst.get("_category") or "")
    symbol = str(resolved_inst.get("symbol") or "")
    warnings: List[Dict[str, str]] = []
    ticker = None
    try:
        payload = await _bybit_get_async(base_url, "/v5/market/tickers", {"category": category, "symbol": symbol})
        ticker_row = _extract_valid_bybit_ticker_row(payload, symbol)
        if ticker_row:
            _cache_bybit_ticker_payload(base_url, category, symbol, payload, "instrument_specs")
            ticker = ticker_row
        else:
            items = (payload.get("result") or {}).get("list") or []
            if isinstance(items, list) and items and isinstance(items[0], dict):
                ticker = items[0]
            warnings.append({"scope": "ticker", "symbol": symbol, "field": "tickers", "message": f"Bybit ticker payload invalid for {symbol}"})
    except Exception as exc:
        warnings.append({"scope": "ticker", "symbol": symbol, "field": "tickers", "message": str(exc)})
    specs: Dict[str, object] = {
        "source": "bybit", "query": query, "resolved_symbol": (ticker or {}).get("symbol") or symbol,
        "category": category, "lastPrice": (ticker or {}).get("lastPrice"), "fundingRate": (ticker or {}).get("fundingRate"),
        "nextFundingTime": (ticker or {}).get("nextFundingTime"), "launchTime": resolved_inst.get("launchTime"),
        "openInterest": (ticker or {}).get("openInterest"), "openInterestValue": (ticker or {}).get("openInterestValue"),
        "volume24hUsd": (ticker or {}).get("turnover24h"),
        "contractType": resolved_inst.get("contractType"), "status": resolved_inst.get("status"),
        "baseCoin": resolved_inst.get("baseCoin"), "quoteCoin": resolved_inst.get("quoteCoin"),
    }
    price_filter = resolved_inst.get("priceFilter") if isinstance(resolved_inst.get("priceFilter"), dict) else {}
    lot_filter = resolved_inst.get("lotSizeFilter") if isinstance(resolved_inst.get("lotSizeFilter"), dict) else {}
    leverage_filter = resolved_inst.get("leverageFilter") if isinstance(resolved_inst.get("leverageFilter"), dict) else {}
    specs.update(
        {
            "tickSize": price_filter.get("tickSize"),
            "minPrice": price_filter.get("minPrice"),
            "maxPrice": price_filter.get("maxPrice"),
            "qtyStep": lot_filter.get("qtyStep"),
            "minOrderQty": lot_filter.get("minOrderQty"),
            "maxOrderQty": lot_filter.get("maxOrderQty"),
            "maxMktOrderQty": lot_filter.get("maxMktOrderQty"),
            "minNotionalValue": lot_filter.get("minNotionalValue"),
            "minLeverage": leverage_filter.get("minLeverage"),
            "maxLeverage": leverage_filter.get("maxLeverage"),
            "leverageStep": leverage_filter.get("leverageStep"),
        }
    )
    avg7d = await _bybit_avg_7d_turnover_usd_async(base_url, str((ticker or {}).get("symbol") or symbol), category)
    if avg7d is not None: specs["avg7dTurnoverUsd"] = avg7d
    range_specs, range_warnings = await _bybit_fetch_range_specs_async(base_url, category, symbol)
    specs.update(range_specs); warnings.extend(range_warnings)
    units = {"fundingRate":"fraction","lastPrice":"price","launchTime":"timestamp_ms","nextFundingTime":"timestamp_ms","openInterest":"contracts","openInterestValue":"usd_value","volume24hUsd":"usd_value_24h","avg7dTurnoverUsd":"usd_value_per_day_avg_7d"}
    for field,_ in _BYBIT_RANGE_INTERVALS: units[field] = "fraction"
    specs["_units"] = units
    if include_btc_reference and not _is_bitcoin_bybit_symbol(symbol, resolved_inst):
        btc_symbol = _btc_reference_symbol_for_category(category, resolved_inst.get("quoteCoin"))
        btc_exact = await _bybit_get_async(base_url, "/v5/market/instruments-info", {"category": category, "symbol": btc_symbol})
        btc_rows = ((btc_exact.get("result") or {}).get("list") or []) if isinstance(btc_exact, dict) else []
        btc_inst = next((r for r in btc_rows if isinstance(r, dict) and str(r.get("symbol") or "").upper() == btc_symbol), None)
        btc_specs = None
        if btc_inst:
            btc_ticker = None
            try:
                p = await _bybit_get_async(base_url, "/v5/market/tickers", {"category": category, "symbol": btc_symbol})
                lst = (p.get("result") or {}).get("list") or []
                if isinstance(lst, list) and lst and isinstance(lst[0], dict):
                    btc_ticker = lst[0]
            except Exception:
                btc_ticker = None
            btc_specs = {
                "source": "bybit",
                "query": btc_symbol,
                "resolved_symbol": btc_symbol,
                "category": category,
                "lastPrice": (btc_ticker or {}).get("lastPrice"),
                "volume24hUsd": (btc_ticker or {}).get("turnover24h"),
            }
            btc_avg7d = await _bybit_avg_7d_turnover_usd_async(base_url, btc_symbol, category)
            if btc_avg7d is not None:
                btc_specs["avg7dTurnoverUsd"] = btc_avg7d
            btc_ranges, _btc_warnings = await _bybit_fetch_range_specs_async(base_url, category, btc_symbol)
            btc_specs.update(btc_ranges)
        if btc_specs:
            specs["_btc_reference"] = {k: v for k, v in btc_specs.items() if not str(k).startswith("_")}
            warnings.extend(btc_specs.get("_spec_warnings") or [])
    if warnings:
        specs["_spec_warnings"] = warnings
    return {k: v for k, v in specs.items() if v is not None}


async def _fetch_instrument_specs(
    query: str,
    prefer: Optional[str] = None,
    *,
    include_scanner: bool = False,
) -> Dict[str, object]:
    q = str(query or "").strip()
    if not q:
        raise HTTPException(status_code=400, detail="query is required")

    pref = str(prefer or "").strip().lower()
    specs: Optional[Dict[str, object]] = None
    if pref in {"bybit", "crypto", "perp", "perpetual"}:
        specs = await _bybit_resolve_and_fetch_specs(q)
    elif pref in {"oanda", "fx", "forex"}:
        specs = await _oanda_resolve_and_fetch_specs(q)
    elif _is_likely_fx_pair(q):
        specs = await _oanda_resolve_and_fetch_specs(q)
    elif _is_likely_bybit_symbol(q):
        specs = await _bybit_resolve_and_fetch_specs(q)
    else:
        specs = await _oanda_resolve_and_fetch_specs(q)
        if not specs and not _is_likely_fx_pair(q):
            specs = await _bybit_resolve_and_fetch_specs(q)

    if not specs:
        raise HTTPException(status_code=404, detail=f"Instrument not found for query: {q}")

    if include_scanner:
        try:
            await _attach_scanner_metrics(specs)
        except Exception:
            pass

    return specs


async def _resolve_symbol_payload(
    raw_symbol: str, prefer: str = "bybit", scope: str = "all"
) -> Optional[Dict[str, object]]:
    raw = str(raw_symbol or "")
    normalized = _norm_symbol(raw)
    if not normalized:
        return None

    pref = str(prefer or "bybit").strip().lower()
    selected_scope = str(scope or "all").strip().lower()

    if pref == "oanda":
        resolved = normalize_oanda_symbol_query(raw)
        return {
            "input": raw,
            "normalized": normalized,
            "resolved_symbol": resolved,
            "source": "oanda",
        }

    if pref != "bybit":
        return None

    creds = resolve_bybit_credentials_for("default")
    base_url = (creds.get("base_url") if isinstance(creds, dict) else None) or BYBIT_BASE
    categories = ("linear",) if selected_scope == "linear" else ("linear", "spot", "inverse")
    for category in categories:
        try:
            symbols = await _bybit_get_symbols_by_category_cached(base_url, category)
        except Exception:
            symbols = []
        resolved = resolve_bybit_symbol_from_choices(
            raw,
            symbols,
            preferred_quotes=("USDT", "USDC", "USD"),
            exact_first=True,
        )
        if not resolved or not resolved.get("resolved_symbol"):
            name_aliases = await _bybit_name_aliases_for_choices(base_url, set(symbols))
            if name_aliases:
                resolved = resolve_bybit_symbol_from_choices(
                    raw,
                    symbols,
                    preferred_quotes=("USDT", "USDC", "USD"),
                    exact_first=True,
                    extra_aliases=name_aliases,
                )
        if resolved and resolved.get("resolved_symbol"):
            return resolved
    return None


def _truthy_query_param(value: Optional[str]) -> bool:
    if value is None:
        return False
    return str(value).strip().lower() in {"1", "true", "yes", "y", "on"}


def _percentile_rank(values: List[float], current: float) -> float:
    arr = list(values) + [current]
    if not arr:
        return 0.0
    cur = float(current)
    less = 0
    equal = 0
    for v in arr:
        fv = float(v)
        if fv < cur:
            less += 1
        elif fv == cur:
            equal += 1
    if equal <= 0:
        equal = 1
    first = less + 1
    last = less + equal
    avg_rank = (first + last) / 2.0
    return float(avg_rank) / float(len(arr))


def _pearson_corr(xs: List[float], ys: List[float]) -> float:
    if not xs or not ys or len(xs) != len(ys):
        return 0.0
    n = len(xs)
    mx = sum(xs) / n
    my = sum(ys) / n
    cov = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    vx = sum((x - mx) ** 2 for x in xs)
    vy = sum((y - my) ** 2 for y in ys)
    if vx <= 0 or vy <= 0:
        return 0.0
    return float(cov / math.sqrt(vx * vy))


async def _bybit_public_get_json(
    base_url: str, path: str, params: Dict[str, object]
) -> Dict[str, object]:
    async with httpx.AsyncClient(timeout=20) as client:
        res = await client.get(f"{base_url}{path}", params=params)
    res.raise_for_status()
    return res.json() or {}


def _bybit_parse_kline_rows(rows: object) -> List[List[str]]:
    out: List[List[str]] = []
    if not isinstance(rows, list):
        return out
    for row in rows:
        if isinstance(row, list) and len(row) >= 7:
            out.append([str(x) for x in row])
    out.sort(key=lambda r: int(float(r[0])))
    return out


def _ma_window_changes(values: List[float], window: int = 20) -> List[float]:
    changes: List[float] = []
    if len(values) <= window:
        return changes
    for i in range(window, len(values)):
        prev = values[i - window : i]
        avg_prev = sum(prev) / float(len(prev)) if prev else 0.0
        cur = values[i]
        if avg_prev <= 0:
            changes.append(0.0)
        else:
            changes.append((cur - avg_prev) / avg_prev)
    return changes



_BYBIT_RANGE_INTERVALS = [
    ("range.1m", "1"),
    ("range.5m", "5"),
    ("range.15m", "15"),
    ("range.30m", "30"),
    ("range.1h", "60"),
    ("range.4h", "240"),
    ("range.1d", "D"),
    ("range.1w", "W"),
    ("range.1mo", "M"),
]

_BYBIT_VOLUME_INTERVALS = {
    "5M": "5",
    "15M": "15",
    "30M": "30",
    "1H": "60",
    "4H": "240",
}

_BYBIT_OI_INTERVALS = {
    "5M": ("5min", 2),
    "15M": ("15min", 2),
    "30M": ("30min", 2),
    "1H": ("1h", 2),
    "4H": ("4h", 2),
    "1D": ("1d", 2),
    "1W": ("1d", 7),
    "1M": ("1d", 30),
}

_BYBIT_FUNDING_LOOKBACK_MINUTES = {
    "5M": 5,
    "15M": 15,
    "30M": 30,
    "1H": 60,
    "4H": 240,
    "1D": 1440,
    "1W": 10080,
    "1M": 43200,
}


async def _attach_bybit_scanner_metrics(specs: Dict[str, object]) -> None:
    base_url = BYBIT_BASE
    symbol = str(specs.get("resolved_symbol") or "").strip().upper()
    category = str(specs.get("category") or "linear").strip().lower() or "linear"
    if not symbol:
        return

    units = specs.get("_units")
    if not isinstance(units, dict):
        units = {}
        specs["_units"] = units

    for tf, interval in _BYBIT_VOLUME_INTERVALS.items():
        try:
            payload = await _bybit_public_get_json(
                base_url,
                "/v5/market/kline",
                {"category": category, "symbol": symbol, "interval": interval, "limit": 220},
            )
            rows = _bybit_parse_kline_rows((payload.get("result") or {}).get("list"))
            vols = [float(r[5]) for r in rows if len(r) > 5]
            changes = _ma_window_changes(vols, window=20)
            if not changes:
                continue
            latest = float(changes[-1])
            percentile = (
                _percentile_rank([float(x) for x in changes[:-1]], latest)
                if len(changes) > 1
                else 0.0
            )
            specs[f"scan.volumeMA.{tf}"] = latest
            specs[f"scan.volumeMA_percentile.{tf}"] = percentile
            units[f"scan.volumeMA.{tf}"] = "fraction"
            units[f"scan.volumeMA_percentile.{tf}"] = "fraction"
        except Exception:
            continue

    if category in {"linear", "inverse"}:
        for tf, (interval_time, window) in _BYBIT_OI_INTERVALS.items():
            try:
                payload = await _bybit_public_get_json(
                    base_url,
                    "/v5/market/open-interest",
                    {
                        "category": category,
                        "symbol": symbol,
                        "intervalTime": interval_time,
                        "limit": 200,
                    },
                )
                rows = (payload.get("result") or {}).get("list") or []
                if not isinstance(rows, list) or len(rows) < (window + 2):
                    continue
                rows_sorted = sorted(
                    [r for r in rows if isinstance(r, dict)],
                    key=lambda r: int(float(r.get("timestamp", 0) or 0)),
                )
                vals = [float(r.get("openInterest", 0) or 0) for r in rows_sorted]
                changes: List[float] = []
                for i in range(window, len(vals)):
                    first = vals[i - window]
                    last = vals[i]
                    changes.append(0.0 if first <= 0 else (last - first) / first)
                if not changes:
                    continue
                latest = float(changes[-1])
                percentile = (
                    _percentile_rank([float(x) for x in changes[:-1]], latest)
                    if len(changes) > 1
                    else 0.0
                )
                specs[f"scan.openInterestChange.{tf}"] = latest
                specs[f"scan.openInterestChange_percentile.{tf}"] = percentile
                units[f"scan.openInterestChange.{tf}"] = "fraction"
                units[f"scan.openInterestChange_percentile.{tf}"] = "fraction"
            except Exception:
                continue

        try:
            now_ms = int(time.time() * 1000)
            hist = await _bybit_public_get_json(
                base_url,
                "/v5/market/funding/history",
                {"category": category, "symbol": symbol, "limit": 200},
            )
            rows = (hist.get("result") or {}).get("list") or []
            rows_sorted = sorted(
                [r for r in rows if isinstance(r, dict)],
                key=lambda r: int(float(r.get("fundingRateTimestamp", 0) or 0)),
            )
            cur = specs.get("fundingRate")
            if cur is not None:
                specs["scan.fundingRate.current"] = float(cur)
                units["scan.fundingRate.current"] = "fraction"
            for tf, minutes in _BYBIT_FUNDING_LOOKBACK_MINUTES.items():
                target = now_ms - int(minutes * 60 * 1000)
                val = None
                for row in reversed(rows_sorted):
                    ts = int(float(row.get("fundingRateTimestamp", 0) or 0))
                    if ts <= target:
                        val = float(row.get("fundingRate", 0) or 0)
                        break
                if val is None:
                    continue
                specs[f"scan.fundingRate.{tf}"] = val
                units[f"scan.fundingRate.{tf}"] = "fraction"
        except Exception:
            pass

        try:
            if symbol != "BTCUSDT":
                payload_s = await _bybit_public_get_json(
                    base_url,
                    "/v5/market/kline",
                    {"category": category, "symbol": symbol, "interval": "1", "limit": 600},
                )
                payload_b = await _bybit_public_get_json(
                    base_url,
                    "/v5/market/kline",
                    {
                        "category": category,
                        "symbol": "BTCUSDT",
                        "interval": "1",
                        "limit": 600,
                    },
                )
                rows_s = _bybit_parse_kline_rows((payload_s.get("result") or {}).get("list"))
                rows_b = _bybit_parse_kline_rows((payload_b.get("result") or {}).get("list"))
                closes_s = [float(r[4]) for r in rows_s if len(r) > 4]
                closes_b = [float(r[4]) for r in rows_b if len(r) > 4]
                for tf, minutes in {"5M": 5, "15M": 15, "30M": 30, "1H": 60, "4H": 240}.items():
                    if len(closes_s) < minutes + 1 or len(closes_b) < minutes + 1:
                        continue
                    s_seg = closes_s[-(minutes + 1) :]
                    b_seg = closes_b[-(minutes + 1) :]
                    s_ret = [
                        (s_seg[i + 1] - s_seg[i]) / s_seg[i]
                        for i in range(minutes)
                        if s_seg[i] != 0
                    ]
                    b_ret = [
                        (b_seg[i + 1] - b_seg[i]) / b_seg[i]
                        for i in range(minutes)
                        if b_seg[i] != 0
                    ]
                    if len(s_ret) != minutes or len(b_ret) != minutes:
                        continue
                    corr = _pearson_corr(s_ret, b_ret)
                    specs[f"scan.corrToBTC.{tf}"] = corr
                    units[f"scan.corrToBTC.{tf}"] = "ratio"
        except Exception:
            pass


_OANDA_SCAN_TIMEFRAMES = {
    "5M": "M5",
    "15M": "M15",
    "30M": "M30",
    "1H": "H1",
    "4H": "H4",
}


async def _oanda_get_json(
    path: str, *, params: Optional[Dict[str, object]] = None
) -> Optional[Dict[str, object]]:
    token = _oanda_token()
    if not token:
        return None
    headers = {"Authorization": f"Bearer {token}"}
    url = f"{_oanda_base_url()}{path}"
    async with httpx.AsyncClient(timeout=20) as client:
        res = await client.get(url, headers=headers, params=params)
    if res.status_code != 200:
        return None
    return res.json() or {}


async def _attach_oanda_scanner_metrics(specs: Dict[str, object]) -> None:
    symbol = str(specs.get("resolved_symbol") or "").strip().upper()
    if not symbol:
        return

    units = specs.get("_units")
    if not isinstance(units, dict):
        units = {}
        specs["_units"] = units

    for label, granularity in _OANDA_SCAN_TIMEFRAMES.items():
        payload = await _oanda_get_json(
            f"/v3/instruments/{symbol}/candles",
            params={"granularity": granularity, "count": 3, "price": "M"},
        )
        if not payload:
            continue
        candles = payload.get("candles") or []
        if not isinstance(candles, list):
            continue
        complete = [c for c in candles if isinstance(c, dict) and c.get("complete")]
        if len(complete) < 2:
            continue
        last2 = complete[-2:]
        try:
            o = float(((last2[0].get("mid") or {}).get("o")))
            c = float(((last2[-1].get("mid") or {}).get("c")))
            h = max(float(((x.get("mid") or {}).get("h"))) for x in last2)
            l = min(float(((x.get("mid") or {}).get("l"))) for x in last2)
        except Exception:
            continue
        if o <= 0:
            continue
        specs[f"scan.priceChange.{label}"] = (c - o) / o
        specs[f"scan.priceRange.{label}"] = (h - l) / o
        units[f"scan.priceChange.{label}"] = "fraction"
        units[f"scan.priceRange.{label}"] = "fraction"

    account_id = _oanda_account_id_for_specs()
    if account_id:
        pricing = await _oanda_get_json(
            f"/v3/accounts/{account_id}/pricing",
            params={"instruments": symbol},
        )
        if pricing and isinstance(pricing.get("prices"), list) and pricing["prices"]:
            item = pricing["prices"][0]
            try:
                bid = float(item.get("closeoutBid", 0) or 0)
                ask = float(item.get("closeoutAsk", 0) or 0)
            except Exception:
                bid = 0.0
                ask = 0.0
            if bid > 0 and ask > 0:
                specs["scan.spread"] = (ask - bid) / ask
                specs["scan.bid"] = bid
                specs["scan.ask"] = ask
                units["scan.spread"] = "fraction"
                units["scan.bid"] = "price"
                units["scan.ask"] = "price"


async def _attach_scanner_metrics(specs: Dict[str, object]) -> None:
    src = str(specs.get("source") or "").strip().lower()
    if src == "bybit":
        await _attach_bybit_scanner_metrics(specs)
    elif src == "oanda":
        await _attach_oanda_scanner_metrics(specs)


def _specs_to_lines(specs: Dict[str, object]) -> List[str]:
    ordered = ["resolved_symbol","category","lastPrice","fundingRate","nextFundingTime","launchTime","openInterestValue","volume24hUsd","turnover24h","avg7dTurnoverUsd","range.1m","range.5m","range.15m","range.30m","range.1h","range.4h","range.1d","range.1w","range.1mo"]
    labels = {"volume24hUsd":"volume24h (USD)","turnover24h":"volume24h (USD)","avg7dTurnoverUsd":"avg7dVolume (USD)","range.1m":"range 1m (%)","range.5m":"range 5m (%)","range.15m":"range 15m (%)","range.30m":"range 30m (%)","range.1h":"range 1h (%)","range.4h":"range 4h (%)","range.1d":"range daily (%)","range.1w":"range weekly (%)","range.1mo":"range monthly (%)"}
    hidden={"_units","_btc_reference","_spec_warnings","source","query","volume24h"}
    btc = specs.get("_btc_reference") if isinstance(specs.get("_btc_reference"), dict) else {}
    def fmt(k,v):
        try:
            if k.startswith("range.") or k=="fundingRate": return f"{float(v)*100:.2f}%"
            if k in {"volume24hUsd","turnover24h","openInterestValue","avg7dTurnoverUsd"}: return f"${float(v):,.2f}"
        except Exception:
            pass
        return str(v)
    keys=[k for k in ordered if k in specs and k not in hidden]+[k for k in specs.keys() if k not in hidden and k not in ordered]
    lines=[]
    for k in keys:
        lines.append(f"{labels.get(k,k)}: {fmt(k,specs.get(k))}")
        if k in btc:
            lines.append(f"BTC {labels.get(k,k)}: {fmt(k,btc.get(k))}")
    warnings = specs.get("_spec_warnings") or []
    if isinstance(warnings,list) and warnings:
        lines.append("")
        lines.append("Warnings:")
        for w in warnings:
            if isinstance(w,dict): lines.append(f"- {w.get('field','spec')} {w.get('symbol','')}: {w.get('message','')}")
    return lines


def _render_specs_jpg_bytes(specs: Dict[str, object]) -> bytes:
    lines = ["Instrument Specs", ""] + _specs_to_lines(specs)
    try:
        font = ImageFont.truetype("DejaVuSansMono.ttf", 16)
    except Exception:
        font = ImageFont.load_default()

    wrapped: List[str] = []
    for line in lines:
        if len(line) <= 120:
            wrapped.append(line)
            continue
        while line:
            wrapped.append(line[:120])
            line = line[120:]

    pad = 24
    line_h = 22
    max_w = 1400
    height = pad * 2 + line_h * (len(wrapped) + 1)
    img = Image.new("RGB", (max_w, max(400, height)), (11, 18, 32))
    draw = ImageDraw.Draw(img)
    for idx, line in enumerate(wrapped):
        draw.text((pad, pad + idx * line_h), line, font=font, fill=(226, 232, 240))

    out = io.BytesIO()
    img.save(out, format="JPEG", quality=92)
    return out.getvalue()


def _load_watchlist() -> List[str]:
    if not WATCHLIST_PATH.exists():
        return []
    try:
        payload = json.loads(WATCHLIST_PATH.read_text(encoding="utf-8"))
    except Exception:  # pragma: no cover - defensive
        return []
    if not isinstance(payload, list):
        return []
    return _normalize_watchlist(payload)


def _get_watchlist() -> List[str]:
    global _WATCHLIST_CACHE
    if _WATCHLIST_CACHE is None:
        _WATCHLIST_CACHE = _load_watchlist()
    return list(_WATCHLIST_CACHE)


def _save_watchlist(items: List[str]) -> None:
    WATCHLIST_PATH.write_text(json.dumps(items, indent=2, sort_keys=True), encoding="utf-8")


def _set_watchlist(items: Iterable[object]) -> List[str]:
    global _WATCHLIST_CACHE, _WATCHLIST_UPDATED_AT
    normalized = _normalize_watchlist(items)
    _WATCHLIST_CACHE = normalized
    _save_watchlist(normalized)
    _WATCHLIST_UPDATED_AT = _utc_now_iso()
    return list(normalized)


def _set_watchlist_local_mirror(items: Iterable[object]) -> List[str]:
    return _set_watchlist(items)


def state_file_path_for_key(key: str) -> Path:
    mapping = {
        "watchlist": WATCHLIST_PATH,
        "bybit_alerts": BYBIT_CUSTOM_ALERTS_PATH,
        "oanda_alerts": OANDA_CUSTOM_ALERTS_PATH,
        "bybit_settings": BYBIT_SETTINGS_PATH,
        "oanda_settings": OANDA_SETTINGS_PATH,
        "fxweekend_settings": FXWEEKEND_SETTINGS_PATH,
        "fxweekend_status": FXWEEKEND_STATUS_PATH,
        "state_manifest": STATE_MANIFEST_PATH,
    }
    if key not in mapping:
        raise KeyError(f"Unknown repo state key: {key}")
    return mapping[key]


def _load_state_manifest() -> Dict[str, Any]:
    if STATE_MANIFEST_PATH.exists():
        payload = json.loads(STATE_MANIFEST_PATH.read_text(encoding="utf-8"))
        return payload if isinstance(payload, dict) else {}
    if LEGACY_STATE_MANIFEST_CAMEL_PATH.exists():
        legacy = json.loads(LEGACY_STATE_MANIFEST_CAMEL_PATH.read_text(encoding="utf-8"))
        manifest = legacy if isinstance(legacy, dict) else {}
        write_json_file(STATE_MANIFEST_PATH, manifest, sort_keys=True)
        return manifest
    return {}


def _state_manifest_declares_payload(key: str, payload: object) -> bool:
    """Return whether the durable manifest records this exact state payload."""

    try:
        manifest = _load_state_manifest()
    except Exception:
        return False
    entry = manifest.get(key)
    if not isinstance(entry, dict):
        return False
    recorded_hash = str(entry.get("sha256") or "").strip().lower()
    if not recorded_hash:
        return False
    blob = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hmac.compare_digest(recorded_hash, hashlib.sha256(blob).hexdigest())


def _update_repo_state_manifest_entry(key: str, payload: object) -> None:
    manifest = _load_state_manifest()
    blob = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    manifest[key] = {
        "key": key,
        "updated_at": _utc_now_iso(),
        "sha256": hashlib.sha256(blob).hexdigest(),
        "source_host": socket.gethostname(),
        "app_profile": APP_PROFILE,
    }
    write_json_file(STATE_MANIFEST_PATH, manifest, sort_keys=True)


def read_repo_state_json(key: str) -> object:
    path = state_file_path_for_key(key)
    return json.loads(path.read_text(encoding="utf-8"))


def _is_valid_repo_state_value(key: str, value: object) -> bool:
    if key in {"watchlist", "bybit_alerts", "oanda_alerts"}:
        return isinstance(value, list)
    if key in {
        "bybit_settings",
        "oanda_settings",
        "fxweekend_settings",
        "fxweekend_status",
        "state_manifest",
    }:
        return isinstance(value, dict)
    return False


def write_repo_state_json_and_verify(key: str, payload: object) -> Dict[str, object]:
    path = state_file_path_for_key(key)
    write_json_file(path, payload, sort_keys=True)
    roundtrip = json.loads(path.read_text(encoding="utf-8"))
    if roundtrip != payload:
        raise RuntimeError(f"Repo-local state verification failed for key '{key}' at {path}")
    if key != "state_manifest":
        _update_repo_state_manifest_entry(key, payload)
    return {"ok": True, "path": str(path), "verified": True}


def _load_trading_journal() -> List[Dict[str, object]]:
    if not TRADING_JOURNAL_PATH.exists():
        return []
    try:
        payload = json.loads(TRADING_JOURNAL_PATH.read_text(encoding="utf-8"))
    except Exception:  # pragma: no cover - defensive
        return []

    items: object
    if isinstance(payload, dict):
        items = payload.get("items")
    else:
        items = payload

    if not isinstance(items, list):
        return []

    rows: List[Dict[str, object]] = []
    for entry in items:
        if isinstance(entry, dict):
            rows.append(_normalize_journal_profit_fields(entry))
    return rows


def _get_trading_journal() -> List[Dict[str, object]]:
    return _get_trading_journal_rows()


def _save_trading_journal(
    rows: List[Dict[str, object]],
    *,
    invalidate_view_snapshot: bool = True,
    schedule_state_backup: bool = True,
) -> None:
    global _TRADING_JOURNAL_CACHE, _TRADING_JOURNAL_CACHE_KEY
    with _TRADING_JOURNAL_ROWS_LOCK:
        sorted_rows = sorted(
            rows,
            key=lambda item: str(item.get("close_time") or item.get("open_time") or ""),
            reverse=True,
        )
        _save_json_file(TRADING_JOURNAL_PATH, {"items": sorted_rows, "updated_at": _utc_now_iso()})
        _TRADING_JOURNAL_CACHE = copy.deepcopy(sorted_rows)
        _TRADING_JOURNAL_CACHE_KEY = _trading_journal_file_cache_key()
    if invalidate_view_snapshot:
        _invalidate_trading_journal_view_snapshot()
    if schedule_state_backup:
        _schedule_dropbox_upload_state_backup()


