def _normalize_trading_journal_edit_payload(
    payload: object,
    *,
    for_create: bool,
    existing: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    if not isinstance(payload, dict):
        raise HTTPException(status_code=422, detail="Payload must be a JSON object.")
    if not payload:
        raise HTTPException(status_code=422, detail="Payload is empty.")

    allowed = _editable_trading_journal_fields()
    normalized: Dict[str, object] = {}
    protected = {"id", "row_type", "raw_refs", "source", "status", "is_manual", "created_at", "updated_at"}
    protected_identity = {
        "provider",
        "provider_account",
        "provider_trade_id",
        "provider_order_id",
        "provider_position_id",
    }
    numeric_fields = {
        "qty",
        "entry_price",
        "exit_price",
        "stop_loss",
        "take_profit",
        "commission",
        "net_profit",
        "balance_after_trade",
    }
    timestamp_fields = {"open_time", "close_time"}

    for key, raw_value in payload.items():
        field = str(key or "").strip()
        if not field:
            continue
        if field in protected or field in protected_identity:
            raise HTTPException(status_code=422, detail=f"Field '{field}' cannot be edited.")
        if field not in allowed:
            raise HTTPException(status_code=422, detail=f"Field '{field}' is not editable.")
        value = raw_value
        if field in timestamp_fields:
            if value in (None, ""):
                normalized[field] = None
            else:
                parsed = _epoch_or_iso_to_iso(value)
                if not parsed:
                    raise HTTPException(status_code=422, detail=f"Invalid timestamp for '{field}'.")
                normalized[field] = parsed
            continue
        if field in numeric_fields:
            if value in (None, ""):
                normalized[field] = None
            else:
                parsed_num = _to_float(value)
                if parsed_num is None:
                    raise HTTPException(status_code=422, detail=f"Invalid number for '{field}'.")
                normalized[field] = parsed_num
            continue
        if field == "timeframe":
            normalized[field] = _normalize_timeframe(value)
            continue
        if field == "is_test_trade":
            normalized[field] = _normalize_test_trade_flag(value)
            continue
        if field == "vwap":
            try:
                normalized[field] = _normalize_vwap(value)
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc)) from exc
            continue
        if field == "symbol":
            symbol = str(value or "").strip()
            if symbol:
                normalized[field] = _norm_symbol(symbol) or symbol.upper()
            else:
                normalized[field] = ""
            continue
        if field == "side":
            side_text = str(value or "").strip().lower()
            if side_text in {"buy", "long"}:
                normalized[field] = "Buy"
            elif side_text in {"sell", "short"}:
                normalized[field] = "Sell"
            elif side_text:
                normalized[field] = str(value).strip()
            else:
                normalized[field] = ""
            continue
        if field == "breakeven":
            if value in (None, ""):
                normalized[field] = ""
            elif isinstance(value, bool):
                normalized[field] = "Yes" if value else "No"
            else:
                lowered = str(value).strip().lower()
                normalized[field] = "Yes" if lowered in {"1", "true", "yes", "y"} else "No"
            continue
        normalized[field] = str(value).strip() if isinstance(value, str) else value

    # Account/currency fields are only editable on manual rows.
    if not for_create:
        target = existing if isinstance(existing, dict) else {}
        is_manual = bool(target.get("is_manual")) or str(target.get("source") or "").lower() == "manual"
        if not is_manual:
            forbidden = sorted(
                set(normalized.keys()).intersection({"account", "account_label", "currency", "qty_unit"})
            )
            if forbidden:
                raise HTTPException(
                    status_code=409,
                    detail=f"Fields {', '.join(forbidden)} can only be edited for manual rows.",
                )
    return normalized


def _apply_trading_journal_manual_overrides(
    row: Dict[str, object], overrides: Dict[str, object]
) -> Dict[str, object]:
    updated = dict(row)
    safe_overrides = {k: v for k, v in overrides.items() if k in _editable_trading_journal_fields()}
    for key, value in safe_overrides.items():
        updated[key] = value
    updated["manual_overrides"] = dict(safe_overrides)
    updated["manual_override_fields"] = sorted(safe_overrides.keys())
    updated["manual_updated_at"] = _utc_now_iso()
    return updated


def _reapply_trading_journal_manual_overrides(row: Dict[str, object]) -> Dict[str, object]:
    overrides = row.get("manual_overrides")
    if not isinstance(overrides, dict) or not overrides:
        return row
    return _apply_trading_journal_manual_overrides(row, overrides)


def _find_journal_row_index(row_id: str) -> int:
    want = str(row_id or "").strip()
    if not want:
        return -1
    rows = _get_trading_journal_rows()
    for idx, row in enumerate(rows):
        if str((row or {}).get("id") or "").strip() == want:
            return idx
    return -1


def _upsert_trading_journal_rows(
    rows: Iterable[Dict[str, object]],
    *,
    allow_broker_rows_in_single_file: bool = False,
    invalidate_view_snapshot: bool = True,
    schedule_state_backup: bool = True,
    preserve_unaffected_rows: bool = False,
) -> int:
    incoming_rows = [dict(row) for row in rows if isinstance(row, dict)]
    if _trading_journal_local_excel_authoritative():
        blocked = 0
        allow_broker = bool(allow_broker_rows_in_single_file and _master_journal_single_file_mode())
        for raw in incoming_rows:
            src = str(raw.get("source") or "").strip().lower()
            acct = str(raw.get("account") or raw.get("account_label") or "").strip().lower()
            if src == "local_excel":
                continue
            if allow_broker and src.startswith("bybit") and acct in {"demo", "live", "practice", "bybit demo", "bybit live"}:
                continue
            if allow_broker and src.startswith("oanda") and acct in {"demo", "live", "practice", "oanda demo", "oanda live"}:
                continue
            blocked += 1
        if blocked:
            BYBIT_LOGGER.info("trading_journal upsert blocked in local authoritative mode blocked_rows=%s", blocked)
            return 0
    with _TRADING_JOURNAL_ROWS_LOCK:
        existing = _get_trading_journal_rows()
        incoming_rows, stale_oanda_ids = _prepare_oanda_canonical_replacements(existing, incoming_rows)
        if preserve_unaffected_rows:
            incoming_ids = {
                str(row.get("id") or "").strip()
                for row in incoming_rows
                if str(row.get("id") or "").strip()
            }
            affected_existing = [
                row
                for row in existing
                if str(row.get("id") or "").strip() in incoming_ids
            ]
            sanitized_affected = {
                str(row.get("id") or "").strip(): row
                for row in _sanitize_oanda_commission_fields(
                    affected_existing,
                    raw_export_rows=incoming_rows,
                )
                if str(row.get("id") or "").strip()
            }
            existing = [
                sanitized_affected.get(
                    str(row.get("id") or "").strip(),
                    row,
                )
                for row in existing
            ]
        else:
            existing = _sanitize_oanda_commission_fields(
                existing,
                raw_export_rows=incoming_rows,
            )
        by_id: Dict[str, Dict[str, object]] = {}
        for row in existing:
            row_id = str(row.get("id") or "").strip()
            if row_id and row_id not in stale_oanda_ids:
                by_id[row_id] = row
        changed = 0
        for raw in incoming_rows:
            row = _normalize_journal_profit_fields(dict(raw))
            row_id = str(row.get("id") or "").strip()
            if not row_id:
                continue
            row["id"] = row_id
            row["updated_at"] = datetime.now(timezone.utc).isoformat()
            if row_id in by_id:
                by_id[row_id] = _merge_trading_journal_row(by_id[row_id], row)
            else:
                by_id[row_id] = row
            refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
            status = str(row.get("status") or "").strip().lower()
            if status in {"closed", "filled", "complete", "completed"}:
                _mark_trade_context_closed_or_cancelled(
                    order_id=str(refs.get("orderId") or refs.get("orderID") or "").strip() or None,
                    trade_id=str(refs.get("tradeId") or refs.get("tradeID") or "").strip() or None,
                    status="CLOSED",
                )
            changed += 1
        if changed:
            _save_trading_journal(
                list(by_id.values()),
                invalidate_view_snapshot=invalidate_view_snapshot,
                schedule_state_backup=schedule_state_backup,
            )
    return changed


def _merge_trading_journal_row(
    existing: Dict[str, object], incoming: Dict[str, object]
) -> Dict[str, object]:
    incoming_status = str(incoming.get("status") or "").strip().lower()
    incoming_type = str(incoming.get("row_type") or "").strip().lower()
    existing_status = str(existing.get("status") or "").strip().lower()
    if incoming_status == "invalid_time_order" or incoming_type == "quarantine":
        if existing_status in {"closed", "filled", "complete", "completed"}:
            return _normalize_journal_profit_fields(dict(existing))
    merged = _normalize_journal_profit_fields(dict(existing))
    preserve_when_incoming_null = {
        "stop_loss",
        "take_profit",
        "open_time",
        "entry_price",
        "balance_after_trade",
        "timeframe",
        "is_test_trade",
        "r_multiple",
        "raw_refs",
    }
    for key, value in incoming.items():
        if key == "raw_refs":
            existing_refs = merged.get("raw_refs") if isinstance(merged.get("raw_refs"), dict) else {}
            incoming_refs = value if isinstance(value, dict) else {}
            if existing_refs and not incoming_refs:
                continue
            merged[key] = {**existing_refs, **incoming_refs}
            continue
        if key == "metrics" and isinstance(value, dict):
            existing_metrics = merged.get("metrics") if isinstance(merged.get("metrics"), dict) else {}
            incoming_metrics = dict(value)
            if not _normalize_timeframe(incoming_metrics.get("timeframe")) and _normalize_timeframe(existing_metrics.get("timeframe")):
                incoming_metrics["timeframe"] = existing_metrics.get("timeframe")
            merged[key] = {**existing_metrics, **incoming_metrics}
            continue
        if key in preserve_when_incoming_null:
            if (value is None or (isinstance(value, str) and value.strip() == "")) and merged.get(key) is not None:
                continue
        merged[key] = value
    return _normalize_journal_profit_fields(_reapply_trading_journal_manual_overrides(merged))


def _load_trading_journal_state() -> Dict[str, object]:
    if not TRADING_JOURNAL_STATE_PATH.exists():
        return {}
    try:
        payload = json.loads(TRADING_JOURNAL_STATE_PATH.read_text(encoding="utf-8"))
    except Exception:  # pragma: no cover - defensive
        return {}
    return payload if isinstance(payload, dict) else {}


def _save_trading_journal_state(state: Dict[str, object]) -> None:
    TRADING_JOURNAL_STATE_PATH.write_text(
        json.dumps(state, indent=2, sort_keys=True),
        encoding="utf-8",
    )


def _stable_registry_key(parts: Iterable[object]) -> str:
    return "|".join(str(part or "").strip() for part in parts)


def _update_unresolved_registry(
    *,
    family: str,
    key: str,
    details: Optional[Dict[str, object]] = None,
    resolved: bool,
    resolution_source: Optional[str] = None,
) -> Tuple[bool, Dict[str, object]]:
    if not family or not key:
        return False, {}
    state = _load_trading_journal_state()
    registry = state.get("unresolved_registry")
    if not isinstance(registry, dict):
        registry = {}
    family_map = registry.get(family)
    if not isinstance(family_map, dict):
        family_map = {}
    now_iso = _utc_now_iso()
    detail_payload = details if isinstance(details, dict) else {}
    detail_signature = json.dumps(detail_payload, sort_keys=True, default=str)
    existing = family_map.get(key)
    should_warn = False
    if isinstance(existing, dict):
        entry = dict(existing)
        entry["last_seen_at"] = now_iso
        entry["count"] = int(_to_float(entry.get("count")) or 0) + 1
        was_resolved = bool(entry.get("resolved"))
        previous_signature = str(entry.get("last_signature") or "")
        if resolved:
            entry["resolved"] = True
            if resolution_source:
                entry["resolution_source"] = resolution_source
            if not was_resolved:
                should_warn = False
        else:
            entry["resolved"] = False
            if was_resolved or previous_signature != detail_signature:
                should_warn = True
        entry["last_signature"] = detail_signature
        entry["details"] = detail_payload
    else:
        entry = {
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "count": 1,
            "resolved": bool(resolved),
            "resolution_source": resolution_source or None,
            "last_signature": detail_signature,
            "details": detail_payload,
        }
        should_warn = not resolved
    family_map[key] = entry
    registry[family] = family_map
    state["unresolved_registry"] = registry
    _save_trading_journal_state(state)
    return should_warn, entry


def _restore_bybit_closed_pnl_last_seen_from_state() -> None:
    state = _load_trading_journal_state()
    persisted = state.get("bybit_closed_pnl_last_seen") if isinstance(state, dict) else None
    if not isinstance(persisted, dict):
        return
    for mode in ("demo", "live"):
        value = persisted.get(mode)
        if value in (None, ""):
            continue
        parsed = int(_to_float(value) or 0)
        if parsed > 0:
            _BYBIT_CLOSED_PNL_LAST_SEEN[mode] = parsed


def _persist_bybit_closed_pnl_last_seen() -> None:
    state = _load_trading_journal_state()
    state["bybit_closed_pnl_last_seen"] = {
        "demo": int(_BYBIT_CLOSED_PNL_LAST_SEEN.get("demo") or 0) or None,
        "live": int(_BYBIT_CLOSED_PNL_LAST_SEEN.get("live") or 0) or None,
    }
    _save_trading_journal_state(state)


def _persist_oanda_fill_state() -> None:
    payload = {
        "last_seen_transaction_id": {
            "live": _OANDA_TX_LAST_SEEN.get("live"),
            "demo": _OANDA_TX_LAST_SEEN.get("demo"),
        },
        "open_trade_legs": _OANDA_OPEN_TRADE_LEGS,
        "diagnostics": _OANDA_FILL_DIAGNOSTICS,
        "updated_at": _utc_now_iso(),
    }
    _save_json_file(OANDA_FILL_STATE_PATH, payload)


def _restore_oanda_fill_state_on_startup() -> None:
    payload = _load_json_file(OANDA_FILL_STATE_PATH, {})
    if not isinstance(payload, dict):
        return
    last_seen = payload.get("last_seen_transaction_id")
    if isinstance(last_seen, dict):
        for account in ("live", "demo"):
            candidate = str(last_seen.get(account) or "").strip()
            if candidate:
                _OANDA_TX_LAST_SEEN[account] = candidate
    open_legs = payload.get("open_trade_legs")
    if isinstance(open_legs, dict):
        for account in ("live", "demo"):
            legs = open_legs.get(account)
            if isinstance(legs, dict):
                _OANDA_OPEN_TRADE_LEGS[account] = {
                    str(k): dict(v) for k, v in legs.items() if isinstance(v, dict)
                }
    diagnostics = payload.get("diagnostics")
    if isinstance(diagnostics, dict):
        for account in ("live", "demo"):
            node = diagnostics.get(account)
            if isinstance(node, dict):
                _OANDA_FILL_DIAGNOSTICS[account] = dict(node)


def _record_oanda_fill_diagnostic(account: str, **updates: object) -> None:
    merged = dict(_OANDA_FILL_DIAGNOSTICS.get(account, {}))
    merged.update(updates)
    merged["updated_at"] = _utc_now_iso()
    _OANDA_FILL_DIAGNOSTICS[account] = merged
    _persist_oanda_fill_state()


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _json_safe(value: object) -> object:
    if value is None or isinstance(value, (str, bool, int)):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    if isinstance(value, Decimal):
        if value.is_finite():
            try:
                number = float(value)
            except Exception:
                return str(value)
            return number if math.isfinite(number) else None
        return None
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, datetime):
        return value.isoformat()
    if hasattr(value, "isoformat") and value.__class__.__module__.startswith(("datetime", "pandas")):
        try:
            return value.isoformat()
        except Exception:
            pass
    if isinstance(value, dict):
        return {str(k): _json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_json_safe(item) for item in value]
    if hasattr(value, "item") and callable(getattr(value, "item")):
        try:
            return _json_safe(value.item())
        except Exception:
            pass
    return str(value)


def _resolve_base_path_env(env_name: str, default_path: Path) -> Path:
    raw = str(os.getenv(env_name, "") or "").strip()
    if not raw:
        return default_path
    candidate = Path(raw).expanduser()
    if not candidate.is_absolute():
        candidate = (BASE_DIR / candidate).resolve()
    return candidate


def _sanitize_calc_context_obj(obj: object) -> object:
    return _json_safe(obj)


def _load_json_file(path: Path, default):
    try:
        if not path.exists():
            return default
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _save_json_file(path: Path, payload: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    write_json_file(
        path,
        payload,
        retries=10,
        backoff=0.05,
        sort_keys=False,
        ensure_ascii=False,
    )


def _derived_refresh_default_state() -> Dict[str, object]:
    return {
        "status": "idle",
        "queued": False,
        "running": False,
        "pending": False,
        "refresh_required": False,
        "ok": None,
        "error": None,
        "generation": 0,
        "completed_generation": 0,
        "affected_row_ids": [],
        "queued_at": None,
        "started_at": None,
        "finished_at": None,
        "updated_at": None,
        "not_before": None,
        "rerun_requested": False,
        "recovered": False,
        "attempt_count": 0,
        "max_attempts": TRADING_JOURNAL_DERIVED_REFRESH_MAX_ATTEMPTS,
        "last_error": None,
        "result": None,
        "intent_kind": "derived_refresh",
        "incremental_recovery": None,
    }


def _normalize_trading_journal_incremental_recovery_payload(
    payload: object,
) -> Dict[str, object]:
    if not isinstance(payload, dict):
        raise ValueError("Incremental recovery payload is missing.")
    version = int(payload.get("version") or 0)
    if version != TRADING_JOURNAL_INCREMENTAL_RECOVERY_VERSION:
        raise ValueError(
            f"Unsupported incremental recovery payload version: {version}."
        )
    phase = str(payload.get("phase") or "").strip().lower()
    if phase not in {
        "prepared",
        "json_committed",
        "workbook_committed",
        "incremental_committed",
    }:
        raise ValueError(f"Invalid incremental recovery phase: {phase or '<blank>'}.")

    def _validated_rows(value: object, label: str) -> List[Dict[str, object]]:
        if not isinstance(value, list):
            raise ValueError(f"Incremental recovery {label} must be a list.")
        if len(value) > TRADING_JOURNAL_INCREMENTAL_RECOVERY_MAX_ROWS:
            raise ValueError(
                f"Incremental recovery {label} exceeds the bounded row limit."
            )
        rows: List[Dict[str, object]] = []
        seen_ids: Set[str] = set()
        for raw in value:
            if not isinstance(raw, dict):
                raise ValueError(f"Incremental recovery {label} contains a non-row value.")
            row = _json_safe(dict(raw))
            if not isinstance(row, dict):
                raise ValueError(f"Incremental recovery {label} row is not JSON-safe.")
            row_id = str(row.get("id") or "").strip()
            if not row_id:
                raise ValueError(f"Incremental recovery {label} row is missing an ID.")
            if row_id in seen_ids:
                raise ValueError(f"Incremental recovery {label} contains duplicate IDs.")
            row["id"] = row_id
            seen_ids.add(row_id)
            rows.append(row)
        return rows

    json_rows = _validated_rows(payload.get("json_rows"), "JSON rows")
    workbook_rows = _validated_rows(
        payload.get("workbook_rows"), "workbook rows"
    )
    json_ids = {str(row["id"]) for row in json_rows}
    workbook_ids = {str(row["id"]) for row in workbook_rows}
    if not workbook_ids.issubset(json_ids):
        raise ValueError(
            "Incremental recovery workbook rows must be included in the JSON rows."
        )
    balance = _json_safe(payload.get("account_balance"))
    if not isinstance(balance, dict) or _to_float(balance.get("balance")) is None:
        raise ValueError("Incremental recovery account balance is invalid.")
    normalized: Dict[str, object] = {
        "version": version,
        "transaction_id": str(payload.get("transaction_id") or "").strip()
        or f"incremental-{uuid4().hex[:12]}",
        "phase": phase,
        "json_rows": json_rows,
        "workbook_rows": workbook_rows,
        "account_balance": balance,
        "created_at": str(payload.get("created_at") or "").strip()
        or _utc_now_iso(),
        "phase_updated_at": str(payload.get("phase_updated_at") or "").strip()
        or _utc_now_iso(),
    }
    encoded = json.dumps(
        normalized,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    if len(encoded) > TRADING_JOURNAL_INCREMENTAL_RECOVERY_MAX_BYTES:
        raise ValueError("Incremental recovery payload exceeds the durable size limit.")
    return normalized


def _set_trading_journal_incremental_recovery_phase(
    phase: str,
) -> Dict[str, object]:
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        state = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
        payload = _normalize_trading_journal_incremental_recovery_payload(
            state.get("incremental_recovery")
        )
        payload["phase"] = str(phase or "").strip().lower()
        payload["phase_updated_at"] = _utc_now_iso()
        payload = _normalize_trading_journal_incremental_recovery_payload(payload)
        next_state = {
            **state,
            "intent_kind": "incremental_commit",
            "incremental_recovery": payload,
        }
        _commit_trading_journal_derived_refresh_state_locked(next_state)
        return copy.deepcopy(TRADING_JOURNAL_DERIVED_REFRESH_STATE)


def _trading_journal_incremental_recovery_summary(
    payload: object,
) -> Optional[Dict[str, object]]:
    if payload is None:
        return None
    try:
        normalized = _normalize_trading_journal_incremental_recovery_payload(
            payload
        )
    except Exception:
        return {
            "version": None,
            "transaction_id": None,
            "phase": "invalid",
            "created_at": None,
            "phase_updated_at": None,
            "json_row_count": 0,
            "json_row_ids": [],
            "workbook_row_count": 0,
            "workbook_row_ids": [],
        }
    json_row_ids = [
        str(row.get("id") or "").strip()
        for row in (normalized.get("json_rows") or [])
        if isinstance(row, dict) and str(row.get("id") or "").strip()
    ]
    workbook_row_ids = [
        str(row.get("id") or "").strip()
        for row in (normalized.get("workbook_rows") or [])
        if isinstance(row, dict) and str(row.get("id") or "").strip()
    ]
    return {
        "version": normalized.get("version"),
        "transaction_id": normalized.get("transaction_id"),
        "phase": normalized.get("phase"),
        "created_at": normalized.get("created_at"),
        "phase_updated_at": normalized.get("phase_updated_at"),
        "json_row_count": len(json_row_ids),
        "json_row_ids": json_row_ids,
        "workbook_row_count": len(workbook_row_ids),
        "workbook_row_ids": workbook_row_ids,
    }


def _public_trading_journal_derived_refresh_state(
    state: Dict[str, object],
) -> Dict[str, object]:
    public_state = copy.deepcopy(dict(state))
    public_state["incremental_recovery"] = (
        _trading_journal_incremental_recovery_summary(
            state.get("incremental_recovery")
        )
    )
    return public_state


def _commit_trading_journal_derived_refresh_state_locked(
    next_state: Dict[str, object],
) -> None:
    payload = {**_derived_refresh_default_state(), **dict(next_state)}
    payload["affected_row_ids"] = sorted(
        {
            str(row_id or "").strip()
            for row_id in (payload.get("affected_row_ids") or [])
            if str(row_id or "").strip()
        }
    )
    payload["updated_at"] = _utc_now_iso()
    _save_json_file(TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH, payload)
    TRADING_JOURNAL_DERIVED_REFRESH_STATE.clear()
    TRADING_JOURNAL_DERIVED_REFRESH_STATE.update(payload)


def _arm_trading_journal_derived_refresh_timer_locked(
    delay_seconds: Optional[float] = None,
) -> None:
    global TRADING_JOURNAL_DERIVED_REFRESH_TIMER
    if bool(TRADING_JOURNAL_DERIVED_REFRESH_STATE.get("running")):
        return
    current = TRADING_JOURNAL_DERIVED_REFRESH_TIMER
    if isinstance(current, threading.Timer) and current.is_alive():
        current.cancel()
    if delay_seconds is None:
        not_before = _to_float(
            TRADING_JOURNAL_DERIVED_REFRESH_STATE.get("not_before")
        )
        delay_seconds = max(
            0.0,
            (not_before - time.time()) if not_before is not None else 0.0,
        )
    timer = threading.Timer(
        max(0.0, float(delay_seconds or 0.0)),
        _run_trading_journal_derived_refresh_worker,
    )
    timer.daemon = True
    TRADING_JOURNAL_DERIVED_REFRESH_TIMER = timer
    timer.start()


def _recover_trading_journal_derived_refresh_state_if_needed() -> None:
    global TRADING_JOURNAL_DERIVED_REFRESH_LOADED_PATH
    path_key = str(TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH)
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        if TRADING_JOURNAL_DERIVED_REFRESH_LOADED_PATH == path_key:
            return
        current_timer = TRADING_JOURNAL_DERIVED_REFRESH_TIMER
        if isinstance(current_timer, threading.Timer) and current_timer.is_alive():
            current_timer.cancel()
        loaded = _load_json_file(TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH, {})
        state = _derived_refresh_default_state()
        loaded_without_intent_kind = False
        if isinstance(loaded, dict):
            state.update(loaded)
            loaded_without_intent_kind = bool(loaded and "intent_kind" not in loaded)
        recovered_status = str(state.get("status") or "").strip().lower()
        recovered_pending = bool(
            state.get("queued")
            or state.get("running")
            or (
                state.get("pending")
                and str(state.get("status") or "").strip().lower()
                in {"queued", "retrying", "running"}
            )
        )
        if recovered_pending:
            if loaded_without_intent_kind:
                state["intent_kind"] = "legacy_incremental_unknown"
            state.update(
                {
                    "status": (
                        "retrying" if recovered_status == "retrying" else "queued"
                    ),
                    "queued": True,
                    "running": False,
                    "pending": True,
                    "refresh_required": True,
                    "ok": None,
                    "error": None,
                    "rerun_requested": False,
                    "recovered": True,
                    "not_before": max(
                        time.time(),
                        _to_float(state.get("not_before")) or 0.0,
                    ),
                }
            )
        TRADING_JOURNAL_DERIVED_REFRESH_STATE.clear()
        TRADING_JOURNAL_DERIVED_REFRESH_STATE.update(state)
        TRADING_JOURNAL_DERIVED_REFRESH_LOADED_PATH = path_key
        if recovered_pending:
            _commit_trading_journal_derived_refresh_state_locked(state)
            _arm_trading_journal_derived_refresh_timer_locked()


def _queue_trading_journal_derived_refresh(
    affected_row_ids: Iterable[object],
    *,
    incremental_recovery: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    _recover_trading_journal_derived_refresh_state_if_needed()
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        state = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
        existing_recovery = (
            _normalize_trading_journal_incremental_recovery_payload(
                state.get("incremental_recovery")
            )
            if state.get("incremental_recovery") is not None
            else None
        )
        incoming_recovery = (
            _normalize_trading_journal_incremental_recovery_payload(
                incremental_recovery
            )
            if incremental_recovery is not None
            else None
        )
        if existing_recovery is not None and incoming_recovery is not None:
            existing_phase = str(existing_recovery.get("phase") or "")
            existing_transaction_id = str(
                existing_recovery.get("transaction_id") or ""
            )
            incoming_transaction_id = str(
                incoming_recovery.get("transaction_id") or ""
            )
            if (
                existing_phase != "incremental_committed"
                and existing_transaction_id != incoming_transaction_id
            ):
                raise RuntimeError(
                    "A different incremental import transaction is still awaiting "
                    f"crash recovery (transaction_id={existing_transaction_id}, "
                    f"phase={existing_phase}); retry after recovery completes."
                )
            if existing_transaction_id == incoming_transaction_id and any(
                existing_recovery.get(key) != incoming_recovery.get(key)
                for key in ("json_rows", "workbook_rows", "account_balance")
            ):
                raise RuntimeError(
                    "An incremental recovery transaction ID was reused with a "
                    "different staged payload."
                )
            normalized_recovery = (
                existing_recovery
                if existing_transaction_id == incoming_transaction_id
                else incoming_recovery
            )
        else:
            normalized_recovery = incoming_recovery or existing_recovery
        already_pending = bool(
            state.get("queued") or state.get("running") or state.get("pending")
        )
        merged_ids = (
            {
                str(row_id or "").strip()
                for row_id in (state.get("affected_row_ids") or [])
                if str(row_id or "").strip()
            }
            if already_pending
            else set()
        )
        merged_ids.update(
            str(row_id or "").strip()
            for row_id in (affected_row_ids or [])
            if str(row_id or "").strip()
        )
        running = bool(state.get("running"))
        next_state = {
            **state,
            "status": "running" if running else "queued",
            "queued": True,
            "running": running,
            "pending": True,
            "refresh_required": True,
            "ok": None,
            "error": None,
            "generation": int(state.get("generation") or 0) + 1,
            "affected_row_ids": sorted(merged_ids),
            "queued_at": _utc_now_iso(),
            "not_before": time.time()
            + float(TRADING_JOURNAL_DERIVED_REFRESH_DEBOUNCE_SECONDS),
            "rerun_requested": running,
            "recovered": False,
            "attempt_count": 0,
            "max_attempts": TRADING_JOURNAL_DERIVED_REFRESH_MAX_ATTEMPTS,
            "last_error": None,
            "intent_kind": (
                "incremental_commit"
                if normalized_recovery is not None
                else str(state.get("intent_kind") or "derived_refresh")
            ),
            "incremental_recovery": normalized_recovery,
        }
        _commit_trading_journal_derived_refresh_state_locked(next_state)
        if not running:
            _arm_trading_journal_derived_refresh_timer_locked(
                TRADING_JOURNAL_DERIVED_REFRESH_DEBOUNCE_SECONDS
            )
        return copy.deepcopy(TRADING_JOURNAL_DERIVED_REFRESH_STATE)


def _defer_trading_journal_derived_refresh_after_incremental_commit() -> Dict[str, object]:
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        state = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
        if not bool(state.get("queued") or state.get("pending")):
            return copy.deepcopy(state)
        next_state = {
            **state,
            "not_before": time.time()
            + float(TRADING_JOURNAL_DERIVED_REFRESH_DEBOUNCE_SECONDS),
        }
        _commit_trading_journal_derived_refresh_state_locked(next_state)
        if not bool(next_state.get("running")):
            _arm_trading_journal_derived_refresh_timer_locked(
                TRADING_JOURNAL_DERIVED_REFRESH_DEBOUNCE_SECONDS
            )
        return copy.deepcopy(TRADING_JOURNAL_DERIVED_REFRESH_STATE)


def _replay_trading_journal_incremental_recovery(
    state: Dict[str, object],
) -> Optional[Dict[str, object]]:
    intent_kind = str(state.get("intent_kind") or "").strip().lower()
    raw_payload = state.get("incremental_recovery")
    if raw_payload is None:
        if intent_kind == "legacy_incremental_unknown":
            raise RuntimeError(
                "A legacy incremental import intent cannot be safely recovered "
                "because it has no staged row payload; refusing a stale workbook rebuild."
            )
        return None
    payload = _normalize_trading_journal_incremental_recovery_payload(raw_payload)
    phase = str(payload.get("phase") or "").strip().lower()
    if phase == "incremental_committed":
        return {
            "ok": True,
            "replayed": False,
            "phase": phase,
            "transaction_id": payload.get("transaction_id"),
        }

    json_rows = [
        dict(row)
        for row in (payload.get("json_rows") or [])
        if isinstance(row, dict)
    ]
    workbook_rows = [
        dict(row)
        for row in (payload.get("workbook_rows") or [])
        if isinstance(row, dict)
    ]
    account_balance = dict(payload.get("account_balance") or {})
    replay_state = dict(state)
    if phase != "workbook_committed":
        _upsert_trading_journal_rows(
            json_rows,
            allow_broker_rows_in_single_file=True,
            invalidate_view_snapshot=False,
            schedule_state_backup=False,
            preserve_unaffected_rows=True,
        )
        replay_state = _set_trading_journal_incremental_recovery_phase(
            "json_committed"
        )

        workbook_path = _master_journal_path()
        if not workbook_path.exists():
            raise RuntimeError(
                "Incremental recovery cannot continue because Trading Journal.xlsx is missing."
            )
        source = read_master_journal_source(workbook_path) or {}
        survivor_ids = {
            str((row or {}).get("id") or "").strip()
            for row in (source.get("items") or [])
            if isinstance(row, dict) and str((row or {}).get("id") or "").strip()
        }
        survivor_ids.update(
            str(row.get("id") or "").strip()
            for row in workbook_rows
            if str(row.get("id") or "").strip()
        )
        sync_id = f"mjsync-incremental-recovery-{uuid4().hex[:12]}"
        rejected = _reserve_master_journal_workbook_sync(
            workbook_path,
            sync_id,
            "incremental_import_recovery",
        )
        if rejected is not None:
            raise RuntimeError(_master_journal_sync_error(rejected))
        try:
            result = update_master_journal_workbook_incremental(
                workbook_path,
                workbook_rows,
                account_balance=account_balance,
                expected_survivor_row_ids=sorted(survivor_ids),
            )
        finally:
            _release_master_journal_workbook_sync()
        if not bool((result or {}).get("ok")):
            raise RuntimeError(
                "Incremental recovery workbook update failed: "
                f"{_master_journal_sync_error(result)}"
            )
    else:
        result = {"ok": True, "affected_row_ids": [row["id"] for row in workbook_rows]}
    expected_affected_ids = sorted(
        str(row.get("id") or "").strip()
        for row in workbook_rows
        if str(row.get("id") or "").strip()
    )
    actual_affected_ids = sorted(
        str(row_id or "").strip()
        for row_id in ((result or {}).get("affected_row_ids") or [])
        if str(row_id or "").strip()
    )
    if actual_affected_ids != expected_affected_ids:
        raise RuntimeError(
            "Incremental recovery workbook update affected an unexpected row set."
        )
    if phase != "workbook_committed":
        diagnostics = (
            dict((result or {}).get("diagnostics") or {})
            if isinstance((result or {}).get("diagnostics"), dict)
            else {}
        )
        verified_balance = (
            dict(diagnostics.get("verified_account_balance") or {})
            if isinstance(diagnostics.get("verified_account_balance"), dict)
            else {}
        )
        expected_balance = _to_float(account_balance.get("balance"))
        actual_balance = _to_float(verified_balance.get("balance"))
        if (
            not bool((result or {}).get("account_balance_updated"))
            or expected_balance is None
            or actual_balance is None
            or not math.isclose(
                expected_balance,
                actual_balance,
                rel_tol=1e-12,
                abs_tol=1e-9,
            )
        ):
            raise RuntimeError(
                "Incremental recovery did not verify the staged account balance."
            )
        replay_state = _set_trading_journal_incremental_recovery_phase(
            "workbook_committed"
        )
    _persist_trading_journal_sqlite_incremental(
        workbook_rows,
        account_balance,
        import_meta={
            "source_mode": "manual_upload_incremental_recovery",
            "workbooks_scanned": 1,
            "workbooks_changed": 1,
            "rows_imported": len(workbook_rows),
            "warnings": [],
            "errors": [],
        },
        derived_refresh_state=replay_state,
    )
    committed_state = _set_trading_journal_incremental_recovery_phase(
        "incremental_committed"
    )
    try:
        _schedule_dropbox_upload_state_backup()
    except Exception as exc:
        APP_LOGGER.warning(
            "trading_journal_incremental_recovery_backup_schedule_failed error=%s",
            exc,
        )
    return {
        "ok": True,
        "replayed": True,
        "phase": "incremental_committed",
        "transaction_id": payload.get("transaction_id"),
        "affected_row_ids": expected_affected_ids,
        "generation": committed_state.get("generation"),
    }


def _run_trading_journal_derived_refresh_worker() -> None:
    global TRADING_JOURNAL_DERIVED_REFRESH_TIMER
    acquired_import_lock = TRADING_JOURNAL_IMPORT_LOCK.acquire(blocking=False)
    if not acquired_import_lock:
        with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
            TRADING_JOURNAL_DERIVED_REFRESH_TIMER = None
            state = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
            if bool(state.get("queued")) and not bool(state.get("running")):
                _arm_trading_journal_derived_refresh_timer_locked(
                    max(
                        float(TRADING_JOURNAL_DERIVED_REFRESH_DEBOUNCE_SECONDS),
                        float(
                            TRADING_JOURNAL_DERIVED_REFRESH_IMPORT_LOCK_RETRY_SECONDS
                        ),
                    )
                )
        return
    try:
        with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
            TRADING_JOURNAL_DERIVED_REFRESH_TIMER = None
            state = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
            if bool(state.get("running")) or not bool(state.get("queued")):
                return
            not_before = _to_float(state.get("not_before"))
            if not_before is not None and not_before > time.time():
                _arm_trading_journal_derived_refresh_timer_locked(
                    not_before - time.time()
                )
                return
            run_generation = int(state.get("generation") or 0)
            run_ids = list(state.get("affected_row_ids") or [])
            running_state = {
                **state,
                "status": "running",
                "queued": False,
                "running": True,
                "pending": True,
                "refresh_required": True,
                "ok": None,
                "error": None,
                "started_at": _utc_now_iso(),
                "finished_at": None,
                "rerun_requested": False,
                "attempt_count": int(state.get("attempt_count") or 0) + 1,
                "max_attempts": max(
                    1,
                    int(
                        state.get("max_attempts")
                        or TRADING_JOURNAL_DERIVED_REFRESH_MAX_ATTEMPTS
                    ),
                ),
            }
            _commit_trading_journal_derived_refresh_state_locked(running_state)

        try:
            recovery_result = _replay_trading_journal_incremental_recovery(
                running_state
            )
            raw_result = _sync_master_journal_workbook(
                sync_caller="incremental_import_derived_refresh"
            )
            result = dict(raw_result or {}) if isinstance(raw_result, dict) else {}
            if recovery_result is not None:
                result["incremental_recovery"] = _json_safe(recovery_result)
            ok = _master_journal_sync_ok(result)
            error = "" if ok else _master_journal_sync_error(result)
        except Exception as exc:
            result = {
                "ok": False,
                "master_journal_ok": False,
                "master_journal_error": str(exc),
                "master_journal_error_type": type(exc).__name__,
            }
            ok = False
            error = str(exc)

        with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
            latest = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
            rerun = bool(
                int(latest.get("generation") or 0) > run_generation
                or latest.get("queued")
                or latest.get("rerun_requested")
            )
            if rerun:
                next_state = {
                    **latest,
                    "status": "queued",
                    "queued": True,
                    "running": False,
                    "pending": True,
                    "refresh_required": True,
                    "ok": None,
                    "error": None,
                    "finished_at": _utc_now_iso(),
                    "rerun_requested": False,
                    "result": _json_safe(result),
                    "not_before": max(
                        time.time(),
                        _to_float(latest.get("not_before")) or 0.0,
                    ),
                }
                _commit_trading_journal_derived_refresh_state_locked(next_state)
                _arm_trading_journal_derived_refresh_timer_locked()
            else:
                attempt_count = max(
                    1,
                    int(
                        latest.get("attempt_count")
                        or running_state.get("attempt_count")
                        or 1
                    ),
                )
                max_attempts = max(
                    1,
                    int(
                        latest.get("max_attempts")
                        or TRADING_JOURNAL_DERIVED_REFRESH_MAX_ATTEMPTS
                    ),
                )
                if not ok and attempt_count < max_attempts:
                    retry_delay = min(
                        float(TRADING_JOURNAL_DERIVED_REFRESH_RETRY_MAX_SECONDS),
                        float(TRADING_JOURNAL_DERIVED_REFRESH_RETRY_BASE_SECONDS)
                        * (2 ** max(0, attempt_count - 1)),
                    )
                    retry_state = {
                        **latest,
                        "status": "retrying",
                        "queued": True,
                        "running": False,
                        "pending": True,
                        "refresh_required": True,
                        "ok": None,
                        "error": error or "Derived refresh failed.",
                        "last_error": error or "Derived refresh failed.",
                        "affected_row_ids": run_ids,
                        "finished_at": _utc_now_iso(),
                        "rerun_requested": False,
                        "result": _json_safe(result),
                        "not_before": time.time() + retry_delay,
                        "attempt_count": attempt_count,
                        "max_attempts": max_attempts,
                    }
                    _commit_trading_journal_derived_refresh_state_locked(
                        retry_state
                    )
                    _arm_trading_journal_derived_refresh_timer_locked(retry_delay)
                else:
                    completed_state = {
                        **latest,
                        "status": "succeeded" if ok else "failed",
                        "queued": False,
                        "running": False,
                        "pending": False,
                        "refresh_required": not ok,
                        "ok": bool(ok),
                        "error": None
                        if ok
                        else (error or "Derived refresh failed."),
                        "last_error": None
                        if ok
                        else (error or "Derived refresh failed."),
                        "completed_generation": (
                            run_generation
                            if ok
                            else int(latest.get("completed_generation") or 0)
                        ),
                        "affected_row_ids": run_ids,
                        "finished_at": _utc_now_iso(),
                        "rerun_requested": False,
                        "result": _json_safe(result),
                        "not_before": None,
                        "attempt_count": attempt_count,
                        "max_attempts": max_attempts,
                        "incremental_recovery": None if ok else latest.get("incremental_recovery"),
                    }
                    _commit_trading_journal_derived_refresh_state_locked(
                        completed_state
                    )
    finally:
        if acquired_import_lock:
            TRADING_JOURNAL_IMPORT_LOCK.release()


def _trading_journal_derived_refresh_status_snapshot() -> Dict[str, object]:
    _recover_trading_journal_derived_refresh_state_if_needed()
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        timer = TRADING_JOURNAL_DERIVED_REFRESH_TIMER
        if (
            bool(TRADING_JOURNAL_DERIVED_REFRESH_STATE.get("queued"))
            and not bool(TRADING_JOURNAL_DERIVED_REFRESH_STATE.get("running"))
            and not (isinstance(timer, threading.Timer) and timer.is_alive())
        ):
            try:
                _arm_trading_journal_derived_refresh_timer_locked()
            except Exception as exc:
                APP_LOGGER.warning(
                    "trading_journal_derived_refresh_timer_rearm_failed error=%s",
                    exc,
                )
        status = _public_trading_journal_derived_refresh_state(
            TRADING_JOURNAL_DERIVED_REFRESH_STATE
        )
        timer = TRADING_JOURNAL_DERIVED_REFRESH_TIMER
        status["timer_scheduled"] = bool(
            isinstance(timer, threading.Timer) and timer.is_alive()
        )
        return status


def _mark_trading_journal_derived_refresh_generation_succeeded(
    generation: int,
    *,
    result: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Complete durable intent after an in-request full refresh and GitHub sync."""
    global TRADING_JOURNAL_DERIVED_REFRESH_TIMER
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        state = dict(TRADING_JOURNAL_DERIVED_REFRESH_STATE)
        target_generation = max(0, int(generation or 0))
        current_generation = int(state.get("generation") or 0)
        if target_generation <= 0:
            return copy.deepcopy(state)
        if current_generation > target_generation:
            next_state = {
                **state,
                "completed_generation": max(
                    int(state.get("completed_generation") or 0),
                    target_generation,
                ),
            }
            _commit_trading_journal_derived_refresh_state_locked(next_state)
            return copy.deepcopy(TRADING_JOURNAL_DERIVED_REFRESH_STATE)

        timer = TRADING_JOURNAL_DERIVED_REFRESH_TIMER
        if isinstance(timer, threading.Timer):
            timer.cancel()
        TRADING_JOURNAL_DERIVED_REFRESH_TIMER = None
        completed_state = {
            **state,
            "status": "succeeded",
            "queued": False,
            "running": False,
            "pending": False,
            "refresh_required": False,
            "ok": True,
            "error": None,
            "last_error": None,
            "completed_generation": target_generation,
            "finished_at": _utc_now_iso(),
            "rerun_requested": False,
            "result": _json_safe(result or {}),
            "not_before": None,
            "incremental_recovery": None,
        }
        _commit_trading_journal_derived_refresh_state_locked(completed_state)
        return copy.deepcopy(TRADING_JOURNAL_DERIVED_REFRESH_STATE)


def _restore_trading_journal_derived_refresh_state(
    *,
    had_original: bool,
    backup_bytes: Optional[bytes],
    memory_state: Optional[Dict[str, object]],
) -> None:
    global TRADING_JOURNAL_DERIVED_REFRESH_TIMER
    with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
        timer = TRADING_JOURNAL_DERIVED_REFRESH_TIMER
        if isinstance(timer, threading.Timer):
            timer.cancel()
        TRADING_JOURNAL_DERIVED_REFRESH_TIMER = None
        if had_original and backup_bytes is not None:
            _atomic_write_bytes(TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH, backup_bytes)
        elif TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH.exists():
            TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH.unlink()
        restored = (
            dict(memory_state)
            if isinstance(memory_state, dict)
            else _derived_refresh_default_state()
        )
        TRADING_JOURNAL_DERIVED_REFRESH_STATE.clear()
        TRADING_JOURNAL_DERIVED_REFRESH_STATE.update(restored)
        if bool(restored.get("queued")) and not bool(restored.get("running")):
            _arm_trading_journal_derived_refresh_timer_locked()


def _trading_journal_file_cache_key() -> Tuple[object, ...]:
    path = Path(TRADING_JOURNAL_PATH)
    try:
        resolved = str(path.resolve())
    except Exception:
        resolved = str(path.absolute())
    try:
        stat = path.stat()
    except OSError:
        return (resolved, None, None, None, None)
    return (
        resolved,
        getattr(stat, "st_dev", None),
        getattr(stat, "st_ino", None),
        int(stat.st_size),
        int(stat.st_mtime_ns),
    )


def _get_trading_journal_rows() -> List[Dict[str, object]]:
    global _TRADING_JOURNAL_CACHE, _TRADING_JOURNAL_CACHE_KEY
    with _TRADING_JOURNAL_ROWS_LOCK:
        cache_key = _trading_journal_file_cache_key()
        if (
            _TRADING_JOURNAL_CACHE is not None
            and _TRADING_JOURNAL_CACHE_KEY == cache_key
        ):
            return copy.deepcopy(_TRADING_JOURNAL_CACHE)
        data = _load_json_file(TRADING_JOURNAL_PATH, {"items": []})
        if isinstance(data, list):
            rows = [
                _normalize_journal_profit_fields(row)
                for row in data
                if isinstance(row, dict)
            ]
        else:
            items = data.get("items") if isinstance(data, dict) else []
            rows = (
                [
                    _normalize_journal_profit_fields(row)
                    for row in items
                    if isinstance(row, dict)
                ]
                if isinstance(items, list)
                else []
            )
        _TRADING_JOURNAL_CACHE = copy.deepcopy(rows)
        _TRADING_JOURNAL_CACHE_KEY = cache_key
        return copy.deepcopy(rows)


def _set_trading_journal_rows(
    rows: List[Dict[str, object]],
    *,
    invalidate_view_snapshot: bool = True,
    schedule_state_backup: bool = True,
) -> None:
    global _TRADING_JOURNAL_CACHE, _TRADING_JOURNAL_CACHE_KEY
    with _TRADING_JOURNAL_ROWS_LOCK:
        normalized_rows = [_normalize_journal_profit_fields(dict(item)) for item in rows if isinstance(item, dict)]
        _save_json_file(TRADING_JOURNAL_PATH, {"items": normalized_rows, "updated_at": _utc_now_iso()})
        _TRADING_JOURNAL_CACHE = copy.deepcopy(normalized_rows)
        _TRADING_JOURNAL_CACHE_KEY = _trading_journal_file_cache_key()
    if invalidate_view_snapshot:
        _invalidate_trading_journal_view_snapshot()
    if schedule_state_backup:
        _schedule_dropbox_upload_state_backup()


def _get_monthly_aud_revaluation_rows() -> List[Dict[str, object]]:
    data = _load_json_file(MONTHLY_AUD_REVALUATION_PATH, {"items": []})
    if isinstance(data, list):
        return [row for row in data if isinstance(row, dict)]
    items = data.get("items") if isinstance(data, dict) else []
    return items if isinstance(items, list) else []




def _monthly_aud_revaluation_rows_for_journal_view() -> List[Dict[str, object]]:
    dedup: Dict[str, Dict[str, object]] = {}
    for row in _get_monthly_aud_revaluation_rows():
        if not isinstance(row, dict) or str(row.get("row_type") or "").strip().lower() != "monthly_aud_reval":
            continue
        row_id = str(row.get("id") or "").strip()
        symbol = str(row.get("symbol") or "").strip().upper()
        close_time = row.get("close_time")
        result_cash = _to_float(row.get("result_cash"))
        result_currency = str(row.get("result_currency") or "").strip().upper()
        account = _canonical_journal_account_label(
            row.get("account"),
            source=row.get("source"),
            account_mode=row.get("account_mode"),
        )
        account_label = _canonical_journal_account_label(
            row.get("account_label"),
            source=row.get("source"),
            account_mode=row.get("account_mode"),
        )
        if not row_id or not close_time or result_cash is None or not math.isfinite(result_cash):
            continue
        if result_currency != "AUD" or symbol != "MONTHLY AUD P/L":
            continue
        acct_keys = {
            _norm_account_key(account),
            _norm_account_key(account_label),
            str(account or "").strip().upper(),
            str(account_label or "").strip().upper(),
        }
        if not any("BYBIT" in k for k in acct_keys if k):
            continue
        out = dict(row)
        out["id"] = row_id
        out["row_type"] = "monthly_aud_reval"
        out["source"] = out.get("source") or "bybit_monthly_aud_reval"
        out["symbol"] = out.get("symbol") or "MONTHLY AUD P/L"
        out["account"] = "BYBIT"
        out["account_label"] = "BYBIT"
        out["result_currency"] = "AUD"
        out["result_cash"] = float(result_cash)
        out["raw_refs"] = out.get("raw_refs") if isinstance(out.get("raw_refs"), dict) else {}
        out["close_time"] = out.get("close_time") or close_time
        out["setup"] = ""
        out["notes"] = out.get("notes") or "Monthly BYBIT AUD P/L note; excluded from trading metrics."
        out["chart_available"] = False
        out.pop("net_profit", None)
        out.pop("realized_pnl", None)
        existing = dedup.get(row_id)
        if not existing:
            dedup[row_id] = out
            continue
        curr_key = str(out.get("updated_at") or out.get("close_time") or "")
        prev_key = str(existing.get("updated_at") or existing.get("close_time") or "")
        if curr_key >= prev_key:
            dedup[row_id] = out
    return list(dedup.values())
def _set_monthly_aud_revaluation_rows(rows: List[Dict[str, object]]) -> None:
    _save_json_file(MONTHLY_AUD_REVALUATION_PATH, {"items": rows, "updated_at": _utc_now_iso()})
    _schedule_dropbox_upload_state_backup()


def _canonical_trade_epoch_second(value: object) -> Optional[int]:
    if value in (None, ""):
        return None
    try:
        return int(round(pd.to_datetime(value, utc=True).timestamp()))
    except Exception:
        return None


def _canonical_oanda_account_label(row: Dict[str, object]) -> str:
    account = str(row.get("account_label") or row.get("account") or "").strip().upper()
    source = str(row.get("source") or "").strip().lower()
    if "OANDA" in account:
        if "DEMO" in account or "PRACTICE" in account:
            return "OANDA DEMO"
        if "LIVE" in account:
            return "OANDA LIVE"
    if source.startswith("oanda"):
        if account in {"DEMO", "PRACTICE"}:
            return "OANDA DEMO"
        if account == "LIVE":
            return "OANDA LIVE"
    return ""


_OANDA_CANONICAL_ACCOUNT_LABELS = {"OANDA DEMO", "OANDA LIVE"}
_OANDA_COMMISSION_SANITIZER_SOURCES = {
    "",
    "oanda_transaction_export",
    "oanda",
    "master_journal",
    "excel",
    "local_excel",
}


def _canonical_oanda_trade_fingerprint(row: Dict[str, object]) -> Optional[str]:
    if not isinstance(row, dict) or _row_type(row) != "trade":
        return None
    account = _canonical_oanda_account_label(row)
    if not account:
        return None
    symbol = _canonical_symbol(row.get("symbol") or row.get("instrument") or row.get("symbol_raw"))
    open_second = _canonical_trade_epoch_second(row.get("open_time") or row.get("opened_at") or row.get("entry_time"))
    close_second = _canonical_trade_epoch_second(row.get("close_time") or row.get("closed_at") or row.get("exit_time"))
    if not symbol or open_second is None or close_second is None:
        return None

    qty_raw = _to_float(row.get("qty_raw"))
    if qty_raw is None:
        qty_raw = _to_float(row.get("qty"))
        if qty_raw is not None and (
            str(row.get("qty_unit") or "").strip().lower() == "lots"
            or abs(qty_raw) < 1000
        ):
            qty_raw *= 100000.0

    def _rounded(value: object, dp: int = 8) -> str:
        number = _to_float(value)
        return "" if number is None else f"{number:.{dp}f}"

    return "|".join(
        [
            account,
            symbol,
            str(open_second),
            str(close_second),
            _rounded(abs(qty_raw) if qty_raw is not None else None, 4),
            _rounded(row.get("entry_price")),
            _rounded(row.get("exit_price")),
            _rounded(row.get("net_profit") if row.get("net_profit") is not None else row.get("realized_pnl")),
            _rounded(row.get("balance_after_trade")),
        ]
    )


_JOURNAL_WORKBOOK_MANUAL_PRESERVE_FIELDS = {
    "is_test_trade",
    "trade_number",
    "setup",
    "timeframe",
    "pattern",
    "ema",
    "vwap",
    "aths_atls",
    "order_type",
    "round_number",
    "spiked_out",
    "close_stopout",
    "close_stop_out",
    "stop_out",
    "near_perfect_entry",
    "near_win",
    "early_close",
    "breakeven",
    "notes",
    "result_pct",
    "r_multiple",
    "move_to_break_even_time",
    "move_to_break_even_duration",
    "move_to_break_even_trigger_price",
    "move_to_break_even_distance_from_entry_pct",
    "move_to_break_even_distance_from_exit_pct",
    "move_to_profit_time",
    "move_to_profit_duration",
    "move_to_profit_trigger_price",
    "move_to_profit_distance_from_entry_pct",
    "move_to_profit_distance_from_exit_pct",
    "manual_overrides",
    "manual_override_fields",
    "manual_updated_at",
}
_OANDA_MANUAL_PRESERVE_FIELDS = _JOURNAL_WORKBOOK_MANUAL_PRESERVE_FIELDS


def _preserve_workbook_manual_fields(
    current: Dict[str, object], workbook_row: Dict[str, object]
) -> Dict[str, object]:
    merged = dict(current)
    for field in _JOURNAL_WORKBOOK_MANUAL_PRESERVE_FIELDS:
        if field not in workbook_row:
            continue
        value = workbook_row.get(field)
        merged[field] = copy.deepcopy(value)
    return merged


def _preserve_oanda_manual_fields(
    canonical: Dict[str, object], legacy: Dict[str, object]
) -> Dict[str, object]:
    merged = dict(canonical)
    for field in _OANDA_MANUAL_PRESERVE_FIELDS:
        if field not in legacy:
            continue
        value = legacy.get(field)
        if field == "notes" and value in (None, ""):
            continue
        merged[field] = copy.deepcopy(value)
    return merged


def _oanda_qty_raw_for_match(row: Dict[str, object]) -> Optional[float]:
    qty_raw = _to_float(row.get("qty_raw"))
    if qty_raw is not None:
        return abs(qty_raw)
    qty = _to_float(row.get("qty"))
    if qty is None:
        return None
    if (
        str(row.get("qty_unit") or "").strip().lower() == "lots"
        or abs(qty) < 1000
    ):
        qty *= 100000.0
    return abs(qty)


def _numbers_close_for_oanda_match(
    left: object,
    right: object,
    *,
    abs_tol: float,
    rel_tol: float = 0.0,
) -> bool:
    left_num = _to_float(left)
    right_num = _to_float(right)
    if left_num is None or right_num is None:
        return False
    return math.isclose(left_num, right_num, abs_tol=abs_tol, rel_tol=rel_tol)


def _oanda_match_epoch_candidates(value: object) -> List[int]:
    candidates: List[int] = []
    canonical = _canonical_trade_epoch_second(value)
    if canonical is not None:
        candidates.append(canonical)
    if value in (None, ""):
        return candidates
    try:
        parsed = pd.to_datetime(value)
    except Exception:
        return candidates
    try:
        if pd.isna(parsed):
            return candidates
    except Exception:
        pass
    try:
        dt = parsed.to_pydatetime()
    except Exception:
        return candidates
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=JOURNAL_DISPLAY_TZ)
    else:
        dt = dt.astimezone(JOURNAL_DISPLAY_TZ)
    local_epoch = int(round(dt.timestamp()))
    if local_epoch not in candidates:
        candidates.append(local_epoch)
    return candidates


def _oanda_epoch_candidates_close(
    left_values: List[int],
    right_values: List[int],
    *,
    tolerance_seconds: int,
) -> bool:
    if not left_values or not right_values:
        return False
    return any(abs(left - right) <= tolerance_seconds for left in left_values for right in right_values)


def _oanda_rows_match_for_canonical_replacement(
    candidate: Dict[str, object],
    canonical: Dict[str, object],
) -> bool:
    if not isinstance(candidate, dict) or not isinstance(canonical, dict):
        return False
    if _row_type(candidate) != "trade" or _row_type(canonical) != "trade":
        return False
    account = _canonical_oanda_account_label(candidate)
    if account not in _OANDA_CANONICAL_ACCOUNT_LABELS:
        return False
    if account != _canonical_oanda_account_label(canonical):
        return False
    candidate_id = str(candidate.get("id") or "").strip()
    canonical_id = str(canonical.get("id") or "").strip()
    if candidate_id and candidate_id == canonical_id:
        return False

    exact_candidate = _canonical_oanda_trade_fingerprint(candidate)
    exact_canonical = _canonical_oanda_trade_fingerprint(canonical)
    if exact_candidate and exact_canonical and exact_candidate == exact_canonical:
        return True

    candidate_symbol = _canonical_symbol(
        candidate.get("symbol") or candidate.get("instrument") or candidate.get("symbol_raw")
    )
    canonical_symbol = _canonical_symbol(
        canonical.get("symbol") or canonical.get("instrument") or canonical.get("symbol_raw")
    )
    if not candidate_symbol or candidate_symbol != canonical_symbol:
        return False

    candidate_open = _oanda_match_epoch_candidates(
        candidate.get("open_time") or candidate.get("opened_at") or candidate.get("entry_time")
    )
    canonical_open = _oanda_match_epoch_candidates(
        canonical.get("open_time") or canonical.get("opened_at") or canonical.get("entry_time")
    )
    candidate_close = _oanda_match_epoch_candidates(
        candidate.get("close_time") or candidate.get("closed_at") or candidate.get("exit_time")
    )
    canonical_close = _oanda_match_epoch_candidates(
        canonical.get("close_time") or canonical.get("closed_at") or canonical.get("exit_time")
    )
    if not _oanda_epoch_candidates_close(candidate_open, canonical_open, tolerance_seconds=90):
        return False
    if not _oanda_epoch_candidates_close(candidate_close, canonical_close, tolerance_seconds=90):
        return False

    candidate_qty = _oanda_qty_raw_for_match(candidate)
    canonical_qty = _oanda_qty_raw_for_match(canonical)
    if candidate_qty is None or canonical_qty is None:
        return False
    if not math.isclose(candidate_qty, canonical_qty, abs_tol=1.0, rel_tol=0.00005):
        return False

    price_checks = (
        ("entry_price", 0.0001),
        ("exit_price", 0.0001),
    )
    for field, tolerance in price_checks:
        if not _numbers_close_for_oanda_match(
            candidate.get(field),
            canonical.get(field),
            abs_tol=tolerance,
            rel_tol=0.00001,
        ):
            return False

    if not _numbers_close_for_oanda_match(
        candidate.get("net_profit") if candidate.get("net_profit") is not None else candidate.get("realized_pnl"),
        canonical.get("net_profit") if canonical.get("net_profit") is not None else canonical.get("realized_pnl"),
        abs_tol=0.05,
    ):
        return False
    if not _numbers_close_for_oanda_match(
        candidate.get("balance_after_trade"),
        canonical.get("balance_after_trade"),
        abs_tol=0.05,
    ):
        return False
    return True


def _prepare_oanda_canonical_replacements(
    existing_rows: Iterable[Dict[str, object]],
    incoming_rows: Iterable[Dict[str, object]],
) -> Tuple[List[Dict[str, object]], Set[str]]:
    existing_by_fingerprint: Dict[str, List[Dict[str, object]]] = defaultdict(list)
    existing_candidates: List[Dict[str, object]] = []
    for row in existing_rows:
        if not isinstance(row, dict):
            continue
        if _canonical_oanda_account_label(row) in _OANDA_CANONICAL_ACCOUNT_LABELS:
            existing_candidates.append(row)
        fingerprint = _canonical_oanda_trade_fingerprint(row)
        if fingerprint:
            existing_by_fingerprint[fingerprint].append(row)

    prepared: List[Dict[str, object]] = []
    stale_ids: Set[str] = set()
    for raw in incoming_rows:
        if not isinstance(raw, dict):
            continue
        row = dict(raw)
        row_id = str(row.get("id") or "").strip()
        source = str(row.get("source") or "").strip().lower()
        is_canonical_export = row_id.startswith("oanda_export:") or source == "oanda_transaction_export"
        if is_canonical_export:
            fingerprint = _canonical_oanda_trade_fingerprint(row)
            matches = [
                candidate
                for candidate in existing_by_fingerprint.get(fingerprint or "", [])
                if str(candidate.get("id") or "").strip() != row_id
            ]
            if not matches:
                matches = [
                    candidate
                    for candidate in existing_candidates
                    if _oanda_rows_match_for_canonical_replacement(candidate, row)
                ]
            if len(matches) == 1:
                legacy = matches[0]
                legacy_id = str(legacy.get("id") or "").strip()
                if legacy_id:
                    stale_ids.add(legacy_id)
                row = _preserve_oanda_manual_fields(row, legacy)
            elif len(matches) > 1:
                APP_LOGGER.warning(
                    "oanda_canonical_replacement_ambiguous row_id=%s candidates=%s",
                    row_id,
                    [str(candidate.get("id") or "") for candidate in matches[:5]],
                )
        prepared.append(row)
    return _sanitize_oanda_commission_fields(prepared), stale_ids


def _sanitize_oanda_commission_fields(
    rows: Iterable[Dict[str, object]],
    *,
    raw_export_rows: Optional[Iterable[Dict[str, object]]] = None,
) -> List[Dict[str, object]]:
    authoritative_by_fingerprint: Dict[str, Dict[str, object]] = {}
    authoritative_rows: List[Dict[str, object]] = []
    for raw in raw_export_rows or []:
        if not isinstance(raw, dict) or _canonical_oanda_account_label(raw) not in _OANDA_CANONICAL_ACCOUNT_LABELS:
            continue
        authoritative_rows.append(raw)
        fingerprint = _canonical_oanda_trade_fingerprint(raw)
        if fingerprint:
            authoritative_by_fingerprint[fingerprint] = raw

    sanitized: List[Dict[str, object]] = []
    for raw in rows:
        if not isinstance(raw, dict):
            continue
        row = dict(raw)
        if _canonical_oanda_account_label(row) not in _OANDA_CANONICAL_ACCOUNT_LABELS:
            sanitized.append(row)
            continue
        source = str(row.get("source") or "").strip().lower()
        if source not in _OANDA_COMMISSION_SANITIZER_SOURCES:
            sanitized.append(row)
            continue

        metrics = dict(row.get("metrics") or {}) if isinstance(row.get("metrics"), dict) else {}
        open_spread = _to_float(metrics.get("oanda_open_spread_cost"))
        close_spread = _to_float(metrics.get("oanda_close_spread_cost"))
        if open_spread is not None or close_spread is not None:
            metrics["oanda_total_spread_cost"] = (open_spread or 0.0) + (close_spread or 0.0)

        authoritative = authoritative_by_fingerprint.get(_canonical_oanda_trade_fingerprint(row) or "")
        if authoritative is None and authoritative_rows:
            fuzzy = [
                candidate
                for candidate in authoritative_rows
                if _oanda_rows_match_for_canonical_replacement(row, candidate)
            ]
            if len(fuzzy) == 1:
                authoritative = fuzzy[0]
        commission_source = authoritative if authoritative is not None else row
        source_metrics = (
            dict(commission_source.get("metrics") or {})
            if isinstance(commission_source.get("metrics"), dict)
            else {}
        )

        financing_raw: Optional[float] = None
        for key in (
            "oanda_export_financing_allocated",
            "oanda_export_funding_allocated",
            "oanda_api_financing",
            "oanda_api_funding",
            "oanda_api_swap",
        ):
            if key in source_metrics:
                candidate = _to_float(source_metrics.get(key))
                if candidate is not None:
                    financing_raw = candidate
                    break
        if financing_raw is None:
            for key in ("financing", "funding", "swap"):
                if key in commission_source:
                    candidate = _to_float(commission_source.get(key))
                    if candidate is not None:
                        financing_raw = candidate
                        break
        financing_charge = abs(financing_raw) if financing_raw is not None else 0.0

        broker_charge: Optional[float] = None
        for key in ("oanda_broker_commission_total", "oanda_actual_commission_total"):
            if key in source_metrics:
                candidate = _to_float(source_metrics.get(key))
                if candidate is not None:
                    broker_charge = abs(candidate)
                    break
        if broker_charge is None:
            raw_charge_keys = (
                "oanda_raw_commission",
                "oanda_raw_gsl_fee",
                "oanda_raw_gsl_premium",
                "oanda_api_commission_charge",
                "oanda_api_guaranteed_execution_fee",
                "oanda_api_guaranteed_execution_premium",
                "oanda_api_other_trading_charges",
            )
            if any(key in source_metrics for key in raw_charge_keys):
                broker_charge = sum(
                    abs(_to_float(source_metrics.get(key)) or 0.0)
                    for key in raw_charge_keys
                )

        row_id = str(row.get("id") or "").strip().lower()
        canonical_persisted_row = row_id.startswith(("oanda_export:", "oanda:"))
        existing_display = _to_float(commission_source.get("commission"))
        already_includes_financing = bool(
            source_metrics.get("oanda_commission_includes_financing")
        )
        if broker_charge is not None:
            displayed_commission = broker_charge + financing_charge
        elif already_includes_financing and existing_display is not None:
            displayed_commission = abs(existing_display)
            broker_charge = max(displayed_commission - financing_charge, 0.0)
        elif source in {"oanda_transaction_export", "oanda"}:
            broker_charge = abs(existing_display) if existing_display is not None else 0.0
            displayed_commission = broker_charge + financing_charge
        elif canonical_persisted_row:
            # The workbook only persists the combined Commission column, not Swap or
            # row metrics. Preserve that canonical displayed total on the next read.
            displayed_commission = abs(existing_display) if existing_display is not None else financing_charge
            broker_charge = max(displayed_commission - financing_charge, 0.0)
        else:
            # Legacy workbook rows sometimes stored spread cost as Commission. Keep
            # clearing that unsupported value, while retaining proven financing.
            broker_charge = 0.0
            displayed_commission = financing_charge

        metrics["oanda_broker_commission_total"] = broker_charge
        metrics["oanda_financing_commission_total"] = financing_charge
        metrics["oanda_displayed_commission_total"] = displayed_commission
        metrics["oanda_commission_includes_financing"] = bool(financing_charge)
        row["metrics"] = metrics
        row["commission"] = (
            None
            if math.isclose(displayed_commission, 0.0, abs_tol=1e-12)
            else displayed_commission
        )
        row["fees"] = row["commission"]
        sanitized.append(row)
    return sanitized


def _sanitize_oanda_demo_commission_fields(
    rows: Iterable[Dict[str, object]],
    *,
    raw_export_rows: Optional[Iterable[Dict[str, object]]] = None,
) -> List[Dict[str, object]]:
    return _sanitize_oanda_commission_fields(rows, raw_export_rows=raw_export_rows)


def _canonical_bybit_demo_trade_signature(row: Dict[str, object]) -> Optional[str]:
    if not isinstance(row, dict):
        return None
    if not _is_bybit_demo_trade_row(row):
        return None
    if _row_type(row) != "trade":
        return None
    status = str(row.get("status") or row.get("state") or "").strip().lower()
    if status and status not in {"closed", "close", "filled", "complete", "completed"}:
        return None

    opened = row.get("open_time") or row.get("opened_at") or row.get("entry_time")
    closed = row.get("close_time") or row.get("closed_at") or row.get("exit_time") or row.get("date")
    symbol = str(row.get("symbol") or row.get("instrument") or row.get("symbol_raw") or "").strip().upper()
    qty = row.get("qty") if row.get("qty") is not None else row.get("qty_raw")

    if not symbol or not opened or not closed:
        return None

    def _rounded_num(value: object, dp: int = 8) -> str:
        num = _to_float(value)
        if num is None:
            return ""
        return f"{num:.{dp}f}"

    fees = row.get("fees") if row.get("fees") is not None else row.get("commission")
    realized_pnl = row.get("realized_pnl") if row.get("realized_pnl") is not None else row.get("net_profit")
    account_label = str(row.get("account_label") or row.get("account") or "").strip().lower()
    account_norm = re.sub(r"\s+", " ", account_label)
    return "|".join(
        [
            account_norm,
            symbol,
            str(_canonical_trade_epoch_second(opened) or ""),
            str(_canonical_trade_epoch_second(closed) or ""),
            _rounded_num(qty, 8),
            _rounded_num(row.get("entry_price")),
            _rounded_num(row.get("exit_price")),
            _rounded_num(fees, 6),
            _rounded_num(realized_pnl, 6),
        ]
    )


def _is_bybit_demo_trade_row(row: Dict[str, object]) -> bool:
    if not isinstance(row, dict):
        return False
    if _row_type(row) != "trade":
        return False
    status = str(row.get("status") or row.get("state") or "").strip().lower()
    if status and status not in {"closed", "close", "filled", "complete", "completed", "finalized"}:
        return False

    source = str(row.get("source") or "").strip().lower()
    account = str(row.get("account") or "").strip().lower()
    account_label = str(row.get("account_label") or row.get("account") or "").strip()
    if _is_bybit_demo_account_label(account_label):
        return True
    if source == "bybit":
        return account in {"demo", "practice"} or _is_bybit_demo_account_label(account_label)
    if source in {"excel", "local_excel"}:
        if _is_bybit_demo_account_label(account_label):
            return True
        refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        dbx_path = refs.get("dropbox_path") or refs.get("workbook_path")
        workbook_source = row.get("_workbook_source")
        row_id = str(row.get("id") or "").strip().lower()
        return (
            _is_bybit_demo_source_path(dbx_path)
            or _is_bybit_demo_source_path(workbook_source)
            or row_id.startswith("bybitdemo:")
        )
    return False


def _purge_bybit_demo_rows(rows: List[Dict[str, object]]) -> Tuple[List[Dict[str, object]], int]:
    filtered: List[Dict[str, object]] = []
    purged = 0
    for row in rows:
        if isinstance(row, dict) and _is_bybit_demo_trade_row(row):
            purged += 1
            continue
        filtered.append(row)
    return filtered, purged


def _merge_row_notes_comments(target: Dict[str, object], incoming: Dict[str, object]) -> Dict[str, object]:
    merged = dict(target)
    text_fields = ["notes", "pre_trade_comments", "entry_comments", "trade_management", "exit_comments"]
    for field in text_fields:
        left = str(merged.get(field) or "").strip()
        right = str(incoming.get(field) or "").strip()
        if left and right and right not in left:
            merged[field] = f"{left}\n{right}"
        elif (not left) and right:
            merged[field] = right
    return merged


def _bybit_demo_order_identity(row: Dict[str, object]) -> str:
    refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
    return str(refs.get("orderId") or row.get("order_id") or "").strip()


def _is_bybit_execution_history_row(row: Dict[str, object]) -> bool:
    source = str(row.get("source") or "").strip().lower()
    if source == "bybit_execution_history":
        return True
    rid = str(row.get("id") or "").strip().lower()
    if rid.startswith("bybit:demo:execution:") or rid.startswith("bybit:live:execution:"):
        return True
    refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
    return bool(str(refs.get("execId") or refs.get("exec_id") or "").strip())


def _bybit_demo_trade_score(row: Dict[str, object]) -> Tuple[int, int, int, int, int, int]:
    refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
    has_order_id = int(bool(_bybit_demo_order_identity(row)))
    side_norm = _normalize_side_for_comparison(row.get("side") or row.get("direction"))
    side_source = str(refs.get("side_backfill_source") or refs.get("side_source") or "").strip().lower()
    has_corrected_side = int(bool(side_norm and side_source and side_source not in {"unresolved"}))
    has_tpsl = int(row.get("stop_loss") is not None or row.get("take_profit") is not None)
    has_balance = int(row.get("balance_after_trade") is not None)
    has_notes = int(any(str(row.get(f) or "").strip() for f in ["notes", "pre_trade_comments", "entry_comments", "trade_management", "exit_comments"]))
    updated = _canonical_trade_epoch_second(row.get("updated_at")) or -1
    return has_order_id, has_corrected_side, has_tpsl, has_balance, has_notes, updated


def _sanitize_bybit_demo_rows(rows: List[Dict[str, object]]) -> tuple[List[Dict[str, object]], Dict[str, int]]:
    if not rows:
        return [], {"repaired_sides": 0, "deduped_by_order_id": 0, "deduped_by_fingerprint": 0, "trade_group_merged": 0, "quarantined_invalid_time": 0, "workbook_invalid_time_order": 0, "changed": 0}

    repaired_rows, repaired_count = _repair_persisted_bybit_demo_sides(rows)
    passthrough: List[Dict[str, object]] = []
    bybit_rows: List[Dict[str, object]] = []
    quarantined_rows: List[Dict[str, object]] = []
    workbook_invalid_time_order = 0
    for row in repaired_rows:
        if isinstance(row, dict) and _is_bybit_demo_trade_row(row):
            close_ts = _canonical_trade_epoch_second(row.get("close_time"))
            open_ts = _canonical_trade_epoch_second(row.get("open_time"))
            is_exec_row = _is_bybit_execution_history_row(row)
            if close_ts is not None and open_ts is not None and close_ts <= open_ts:
                if is_exec_row and close_ts == open_ts:
                    kept = dict(row)
                    kept["status"] = str(kept.get("status") or "closed")
                    kept["row_type"] = "trade"
                    if kept.get("trade_duration_seconds") is None:
                        kept["trade_duration_seconds"] = 0
                    bybit_rows.append(kept)
                    continue
                source = str(row.get("source") or "").strip().lower()
                if source in {"bybit", "excel", "local_excel"}:
                    swapped_open = row.get("close_time")
                    swapped_close = row.get("open_time")
                    swapped_open_ts = _canonical_trade_epoch_second(swapped_open)
                    swapped_close_ts = _canonical_trade_epoch_second(swapped_close)
                    if swapped_open_ts is not None and swapped_close_ts is not None and swapped_close_ts > swapped_open_ts:
                        kept = dict(row)
                        refs = dict(kept.get("raw_refs") or {}) if isinstance(kept.get("raw_refs"), dict) else {}
                        metrics = dict(kept.get("metrics") or {}) if isinstance(kept.get("metrics"), dict) else {}
                        refs["time_order_repaired"] = "swapped_open_close"
                        refs["time_order_original_open_time"] = row.get("open_time")
                        refs["time_order_original_close_time"] = row.get("close_time")
                        metrics["time_order_repaired"] = True
                        metrics.pop("invalid_time_order", None)
                        kept["raw_refs"] = refs
                        kept["metrics"] = metrics
                        kept["open_time"] = swapped_open
                        kept["close_time"] = swapped_close
                        kept["status"] = "closed"
                        kept["row_type"] = "trade"
                        kept["trade_duration_seconds"] = max(0, swapped_close_ts - swapped_open_ts)
                        bybit_rows.append(kept)
                        continue
                    workbook_invalid_time_order += 1
                q = dict(row)
                q["status"] = "invalid_time_order"
                q["row_type"] = "quarantine"
                quarantined_rows.append(q)
                continue
            bybit_rows.append(dict(row))
        else:
            passthrough.append(row)

    dedup_order: Dict[str, Dict[str, object]] = {}
    order_dropped = 0
    orderless: List[Dict[str, object]] = []
    execution_rows: List[Dict[str, object]] = []
    for row in bybit_rows:
        if _is_bybit_execution_history_row(row):
            execution_rows.append(row)
            continue
        order_id = _bybit_demo_order_identity(row)
        if not order_id:
            orderless.append(row)
            continue
        prev = dedup_order.get(order_id)
        if prev is None:
            dedup_order[order_id] = row
            continue
        winner, loser = (row, prev) if _bybit_demo_trade_score(row) > _bybit_demo_trade_score(prev) else (prev, row)
        dedup_order[order_id] = _merge_row_notes_comments(winner, loser)
        order_dropped += 1

    after_order = list(dedup_order.values()) + orderless + execution_rows
    dedup_fallback: Dict[str, Dict[str, object]] = {}
    fallback_dropped = 0
    for row in after_order:
        if _is_bybit_execution_history_row(row):
            refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
            execution_id = str(
                refs.get("execId")
                or refs.get("exec_id")
                or row.get("id")
                or ""
            ).strip()
            key = f"execution:{execution_id}" if execution_id else None
        else:
            key = _canonical_bybit_demo_trade_signature(row)
        if not key:
            key = f"rowid:{str(row.get('id') or '')}"
        prev = dedup_fallback.get(key)
        if prev is None:
            dedup_fallback[key] = row
            continue
        winner, loser = (row, prev) if _bybit_demo_trade_score(row) > _bybit_demo_trade_score(prev) else (prev, row)
        dedup_fallback[key] = _merge_row_notes_comments(winner, loser)
        fallback_dropped += 1

    grouped: Dict[str, Dict[str, object]] = {}
    trade_group_merged = 0
    for row in dedup_fallback.values():
        gk = "|".join(
            [
                str(row.get("account") or row.get("account_label") or "").strip().lower(),
                str(row.get("symbol") or "").strip().upper(),
                _normalize_side_for_comparison(row.get("side")),
                str(_canonical_trade_epoch_second(row.get("open_time")) or ""),
                _num_bucket(row.get("entry_price"), 8),
                _num_bucket(row.get("qty"), 8),
            ]
        )
        if _is_bybit_execution_history_row(row):
            gk = f"{gk}|{str((row.get('raw_refs') or {}).get('execId') or row.get('id') or '')}"
        prev = grouped.get(gk)
        if prev is None:
            grouped[gk] = row
            continue
        merged = _merge_row_notes_comments(prev, row)
        merged["realized_pnl"] = (_to_float(prev.get("realized_pnl")) or 0.0) + (_to_float(row.get("realized_pnl")) or 0.0)
        merged["net_profit"] = (_to_float(prev.get("net_profit")) or _to_float(prev.get("realized_pnl")) or 0.0) + (_to_float(row.get("net_profit")) or _to_float(row.get("realized_pnl")) or 0.0)
        merged["fees"] = (_to_float(prev.get("fees")) or _to_float(prev.get("commission")) or 0.0) + (_to_float(row.get("fees")) or _to_float(row.get("commission")) or 0.0)
        merged["commission"] = (_to_float(prev.get("commission")) or _to_float(prev.get("fees")) or 0.0) + (_to_float(row.get("commission")) or _to_float(row.get("fees")) or 0.0)
        merged["open_time"] = min(str(prev.get("open_time") or ""), str(row.get("open_time") or ""))
        merged["close_time"] = max(str(prev.get("close_time") or ""), str(row.get("close_time") or ""))
        grouped[gk] = merged
        trade_group_merged += 1

    sanitized_rows = sorted(list(grouped.values()) + passthrough, key=_row_sort_dt, reverse=True)
    changed_total = int(
        repaired_count > 0
        or order_dropped > 0
        or fallback_dropped > 0
        or trade_group_merged > 0
        or workbook_invalid_time_order > 0
        or len(sanitized_rows) != len(rows)
    )
    stats = {
        "repaired_sides": repaired_count,
        "deduped_by_order_id": order_dropped,
        "deduped_by_fingerprint": fallback_dropped,
        "trade_group_merged": trade_group_merged,
        "quarantined_invalid_time": len(quarantined_rows),
        "workbook_invalid_time_order": workbook_invalid_time_order,
        "changed": changed_total,
    }
    return sanitized_rows, stats


def _dedupe_legacy_bybit_demo_rows() -> int:
    rows = _get_trading_journal_rows()
    if not rows:
        return 0
    sanitized, stats = _sanitize_bybit_demo_rows(rows)
    removed = int(stats.get("deduped_by_order_id", 0)) + int(stats.get("deduped_by_fingerprint", 0))
    if int(stats.get("changed", 0)):
        _set_trading_journal_rows(sanitized)
    return removed


def _repair_persisted_bybit_demo_sides(rows: List[Dict[str, object]]) -> tuple[List[Dict[str, object]], int]:
    repaired: List[Dict[str, object]] = []
    change_count = 0
    for row in rows:
        if not isinstance(row, dict):
            repaired.append(row)
            continue
        if not _is_bybit_demo_trade_row(row):
            repaired.append(row)
            continue

        inferred_side = _infer_side_from_tpsl_geometry(
            entry_price=_to_float(row.get("entry_price")),
            stop_loss=_to_float(row.get("stop_loss")),
            take_profit=_to_float(row.get("take_profit")),
        )
        backfill_source = "tpsl_geometry"
        if not inferred_side:
            inferred_side = _infer_side_from_exit_and_pnl(
                entry_price=_to_float(row.get("entry_price")),
                exit_price=_to_float(row.get("exit_price")),
                realized_pnl=_to_float(row.get("realized_pnl"))
                if row.get("realized_pnl") is not None
                else _to_float(row.get("net_profit")),
            )
            backfill_source = "price_move_vs_pnl"

        current_side_norm = _normalize_side_for_comparison(row.get("side") or row.get("direction"))
        inferred_norm = _normalize_side_for_comparison(inferred_side)
        if not inferred_norm or inferred_norm == current_side_norm:
            repaired.append(row)
            continue

        updated = dict(row)
        updated["side"] = inferred_side
        refs = updated.get("raw_refs") if isinstance(updated.get("raw_refs"), dict) else {}
        next_refs = dict(refs)
        next_refs["side_backfill_source"] = backfill_source
        updated["raw_refs"] = next_refs
        repaired.append(updated)
        change_count += 1

    return repaired, change_count


def _repair_persisted_bybit_demo_journal_sides() -> int:
    rows = _get_trading_journal_rows()
    if not rows:
        return 0
    repaired_rows, changed = _repair_persisted_bybit_demo_sides(rows)
    if changed:
        _set_trading_journal_rows(repaired_rows)
    return changed


def _repair_persisted_oanda_trade_rows() -> int:
    rows = _get_trading_journal_rows()
    if not rows:
        return 0
    sanitized_rows = _sanitize_oanda_commission_fields(rows)
    changed = sum(1 for before, after in zip(rows, sanitized_rows) if before != after)
    rows = sanitized_rows
    contexts = _load_trade_contexts()
    inserted = 0
    updated = 0
    repaired: List[Dict[str, object]] = []
    for row in rows:
        if not isinstance(row, dict) or str(row.get("source") or "").strip().lower() != "oanda":
            repaired.append(row)
            continue
        missing = not row.get("stop_loss") or not row.get("take_profit") or not _normalize_timeframe(row.get("timeframe"))
        if not missing:
            repaired.append(row)
            continue
        refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        candidates = [
            ctx
            for ctx in contexts
            if (
                str(refs.get("tradeId") or "").strip()
                and str(ctx.get("trade_id") or "").strip() == str(refs.get("tradeId") or "").strip()
            )
            or (
                str(refs.get("orderId") or "").strip()
                and str(ctx.get("order_id") or "").strip() == str(refs.get("orderId") or "").strip()
            )
            or (
                str(refs.get("transactionId") or "").strip()
                and str(ctx.get("transaction_id") or "").strip() == str(refs.get("transactionId") or "").strip()
            )
        ]
        if len(candidates) != 1:
            if len(candidates) > 1:
                BYBIT_LOGGER.warning("OANDA_ROW_REPAIR_AMBIGUOUS row_id=%s candidates=%s", row.get("id"), len(candidates))
            else:
                BYBIT_LOGGER.info("OANDA_ROW_REPAIR_SKIPPED row_id=%s reason=no_context_match", row.get("id"))
            repaired.append(row)
            continue
        ctx = candidates[0]
        updated = dict(row)
        if not updated.get("stop_loss") and ctx.get("stop_loss"):
            updated["stop_loss"] = ctx.get("stop_loss")
        if not updated.get("take_profit") and ctx.get("take_profit"):
            updated["take_profit"] = ctx.get("take_profit")
        tf = _normalize_timeframe(updated.get("timeframe"))
        if not tf:
            tf = _normalize_timeframe(ctx.get("timeframe"))
            if tf:
                updated["timeframe"] = tf
        if tf:
            metrics = updated.get("metrics") if isinstance(updated.get("metrics"), dict) else {}
            metrics = dict(metrics)
            metrics["timeframe"] = tf
            updated["metrics"] = metrics
        if updated != row:
            changed += 1
        repaired.append(updated)
    if changed:
        _set_trading_journal_rows(repaired)
    return changed


def _repair_persisted_bybit_trade_context_fields() -> int:
    rows = _get_trading_journal_rows()
    if not rows:
        return 0
    changed = 0
    repaired: List[Dict[str, object]] = []
    for row in rows:
        if not isinstance(row, dict):
            repaired.append(row)
            continue
        source = str(row.get("source") or "").strip().lower()
        if source not in {"bybit", "bybit_execution_history_grouped"}:
            repaired.append(row)
            continue
        if (
            _normalize_timeframe(row.get("timeframe"))
            and row.get("stop_loss") not in (None, "")
            and row.get("take_profit") not in (None, "")
        ):
            repaired.append(row)
            continue
        patched = _backfill_trade_row_context_fields(row)
        if patched != row:
            changed += 1
        repaired.append(patched)
    if changed:
        _set_trading_journal_rows(repaired)
    return changed


def _repair_persisted_bybit_open_times(rows: List[Dict[str, object]]) -> tuple[List[Dict[str, object]], int]:
    repaired: List[Dict[str, object]] = []
    changed = 0
    for row in rows:
        if not isinstance(row, dict):
            repaired.append(row)
            continue
        if str(row.get("source") or "").strip().lower() != "bybit":
            repaired.append(row)
            continue
        open_iso = _epoch_or_iso_to_iso(row.get("open_time") or row.get("opened_at") or row.get("entry_time"))
        close_iso = _epoch_or_iso_to_iso(row.get("close_time") or row.get("closed_at") or row.get("exit_time") or row.get("date"))
        open_sec = _canonical_trade_epoch_second(open_iso)
        close_sec = _canonical_trade_epoch_second(close_iso)
        open_time_valid = bool(
            open_iso
            and close_iso
            and open_sec is not None
            and close_sec is not None
            and int(open_sec) < int(close_sec)
        )
        if open_time_valid:
            repaired.append(row)
            continue

        ctx = _lookup_trade_context_for_journal_row(row)
        if not isinstance(ctx, dict):
            ctx = _resolve_bybit_closed_pnl_trade_context(
                account_mode=str(row.get("account") or "").strip().lower() or "demo",
                symbol=str(row.get("symbol") or row.get("instrument") or "").strip().upper(),
                side=row.get("side"),
                close_time=close_iso,
            )
        if not isinstance(ctx, dict):
            repaired.append(row)
            continue
        candidate_open = _epoch_or_iso_to_iso(ctx.get("open_time")) or _epoch_or_iso_to_iso(ctx.get("created_at"))
        if not candidate_open:
            repaired.append(row)
            continue
        if close_iso and _canonical_trade_epoch_second(candidate_open) is not None and _canonical_trade_epoch_second(close_iso) is not None:
            if int(_canonical_trade_epoch_second(candidate_open) or 0) >= int(_canonical_trade_epoch_second(close_iso) or 0):
                repaired.append(row)
                continue
        updated = dict(row)
        updated["open_time"] = candidate_open
        timeframe = _normalize_timeframe(updated.get("timeframe"))
        if not timeframe:
            timeframe = _normalize_journal_timeframe(ctx.get("timeframe"))
            if timeframe:
                updated["timeframe"] = timeframe
        if timeframe:
            metrics = updated.get("metrics") if isinstance(updated.get("metrics"), dict) else {}
            metrics = dict(metrics)
            metrics["timeframe"] = timeframe
            updated["metrics"] = metrics
        duration = _trade_duration_seconds(
            {
                "row_type": "trade",
                "open_time": updated.get("open_time"),
                "close_time": close_iso,
            }
        )
        if duration is not None:
            updated["trade_duration_seconds"] = duration
        repaired.append(updated)
        changed += 1
    return repaired, changed


def _backfill_persisted_bybit_trade_fields(rows: List[Dict[str, object]]) -> tuple[List[Dict[str, object]], int]:
    repaired: List[Dict[str, object]] = []
    changed = 0
    for row in rows:
        if not isinstance(row, dict):
            repaired.append(row)
            continue
        source = str(row.get("source") or "").strip().lower()
        if source not in {"bybit", "bybit_execution_history_grouped"}:
            repaired.append(row)
            continue
        updated = _backfill_trade_row_context_fields(dict(row))
        ctx = _lookup_trade_context_for_journal_row(updated)
        timeframe = _normalize_timeframe(updated.get("timeframe"))
        if not timeframe and isinstance(ctx, dict):
            timeframe = _normalize_journal_timeframe(ctx.get("timeframe"))
            if timeframe:
                updated["timeframe"] = timeframe
        if timeframe:
            metrics = updated.get("metrics") if isinstance(updated.get("metrics"), dict) else {}
            metrics = dict(metrics)
            metrics["timeframe"] = timeframe
            updated["metrics"] = metrics
        duration = _trade_duration_seconds(
            {
                "row_type": "trade",
                "open_time": updated.get("open_time") or updated.get("opened_at") or updated.get("entry_time"),
                "close_time": updated.get("close_time") or updated.get("closed_at") or updated.get("exit_time") or updated.get("date"),
            }
        )
        if duration is not None and duration != updated.get("trade_duration_seconds"):
            updated["trade_duration_seconds"] = duration
        if updated != row:
            changed += 1
        repaired.append(updated)
    return repaired, changed


def _exclude_bybit_demo_row(row: Dict[str, object]) -> bool:
    """Return True if this journal row should be excluded (Bybit Demo)."""
    if ENABLE_BYBIT_DEMO_JOURNAL:
        return False

    src = str(row.get("source") or "").strip().lower()
    acc = str(row.get("account") or "").strip().lower()
    label = str(row.get("account_label") or row.get("account") or "").strip()
    if src == "bybit" and acc == "demo":
        return True
    return _is_bybit_demo_account_label(label)


def _purge_bybit_demo_journal_state() -> int:
    """Remove any Bybit Demo rows/balances already persisted on disk."""
    if ENABLE_BYBIT_DEMO_JOURNAL:
        return 0

    removed = 0
    try:
        rows = _get_trading_journal_rows()
        kept = [r for r in rows if isinstance(r, dict) and not _exclude_bybit_demo_row(r)]
        removed = max(0, len(rows) - len(kept))
        if removed:
            _set_trading_journal_rows(kept)
            global _TRADING_JOURNAL_CACHE
            _TRADING_JOURNAL_CACHE = [dict(r) for r in kept]
    except Exception:
        # Defensive: never break startup or API endpoints for a cleanup.
        removed = 0

    try:
        state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
        if isinstance(state, dict):
            bals = state.get("excel_account_balances")
            if isinstance(bals, list):
                kept_bals: List[Dict[str, object]] = []
                removed_bals = 0
                for b in bals:
                    if not isinstance(b, dict):
                        continue
                    label = b.get("label") or b.get("account")
                    if _is_bybit_demo_account_label(label):
                        removed_bals += 1
                        continue
                    kept_bals.append(b)
                if removed_bals:
                    state["excel_account_balances"] = kept_bals
                    _save_trading_journal_state(state)
    except Exception:
        pass

    return removed


def _load_trading_journal_import_cache() -> Dict[str, object]:
    data = _load_json_file(TRADING_JOURNAL_IMPORT_CACHE_PATH, {})
    return data if isinstance(data, dict) else {}


def _save_trading_journal_import_cache(cache: Dict[str, object]) -> None:
    _save_json_file(TRADING_JOURNAL_IMPORT_CACHE_PATH, cache)


def _norm_col(name: object) -> str:
    value = str(name or "").strip().lower()
    value = re.sub(r"\s+", " ", value)
    value = value.replace("/", " ").replace("?", " ")
    for char in [" ", "-", "(", ")", "[", "]", ".", ":"]:
        value = value.replace(char, "_")
    while "__" in value:
        value = value.replace("__", "_")
    return value.strip("_")


def _excel_cell_to_python(value: object) -> object:
    if value is None:
        return None
    try:
        if pd.isna(value):  # type: ignore[arg-type]
            return None
    except Exception:
        pass
    if isinstance(value, (pd.Timestamp, datetime)):
        try:
            return pd.to_datetime(value).isoformat()
        except Exception:
            return str(value)
    try:
        if hasattr(value, "item"):
            value = value.item()
    except Exception:
        pass
    return value


def _canonical_symbol(symbol: str) -> str:
    symbol_norm = (symbol or "").strip().upper().replace("/", "")
    symbol_norm = re.sub(r"\.[A-Z0-9]+$", "", symbol_norm)
    symbol_norm = symbol_norm.replace("_", "")
    return symbol_norm


def _is_fx_account_label(account_label: str) -> bool:
    text = (account_label or "").upper()
    return any(token in text for token in ("OANDA", "PEPPERSTONE", "FOREX", " FX"))


def _infer_asset_class(
    account_label: str,
    symbol: str,
    row: pd.Series,
    metrics: Dict[str, object],
) -> str:
    account_txt = (account_label or "").upper()
    symbol_txt = _canonical_symbol(symbol or "").upper()
    if any(token in account_txt for token in ("OANDA", "PEPPERSTONE", "FOREX", " FX")):
        return "fx"
    if symbol_txt and (is_likely_oanda_pair(symbol_txt) or bool(re.fullmatch(r"[A-Z]{3}_[A-Z]{3}", str(symbol or "").upper()))):
        return "fx"
    if any(token in symbol_txt for token in ("USDT", "USDC", "BTC", "ETH", "PERP")):
        return "crypto"

    hints: List[str] = []
    for key, value in (metrics or {}).items():
        key_txt = str(key or "").lower()
        if any(k in key_txt for k in ("asset", "class", "market", "instrument", "product", "type", "account", "currency")):
            hints.append(str(value or "").lower())
    if isinstance(row, pd.Series):
        for col_name in row.index:
            col_txt = str(col_name or "").lower()
            if any(k in col_txt for k in ("asset", "class", "market", "instrument", "product", "type", "account", "currency")):
                hints.append(str(row.get(col_name) or "").lower())

    joined = " ".join(hints)
    if re.search(r"\b(forex|fx|currency)\b", joined):
        return "fx"
    if re.search(r"\b(crypto|perp|perpetual)\b", joined):
        return "crypto"
    return "fx" if _is_fx_account_label(account_label) else "crypto"


def _normalize_fx_qty_for_display(
    account_label: str, symbol: str, raw_qty: Optional[float]
) -> Optional[float]:
    if raw_qty is None:
        return None
    if "OANDA" in (account_label or "").upper():
        return raw_qty / 100000.0
    return raw_qty


def _safe_float_from_row(row: pd.Series, col: Optional[str]) -> Optional[float]:
    if not col:
        return None
    value = row.get(col)
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    try:
        return float(value)
    except Exception:
        pass
    text = str(value or "").strip()
    if not text:
        return None
    negative = text.startswith("(") and text.endswith(")")
    if negative:
        text = text[1:-1].strip()
    text = re.sub(r"[^0-9+\-eE.]", "", text)
    if not text:
        return None
    try:
        num = float(text)
        return -num if negative else num
    except Exception:
        return None


def _norm_account_key(name: object) -> str:
    text = str(name or "").upper().strip()
    if not text:
        return ""
    text = re.sub(r"[_\-/]+", " ", text)
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[^A-Z0-9 ]", "", text)
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(r"(?:\s+|^)#\s*\d+$", "", text).strip()
    text = re.sub(r"\s+DEMO\s*\d+$", " DEMO", text).strip()
    return text


def _safe_str_from_row(row: pd.Series, col: Optional[str]) -> str:
    if not col:
        return ""
    value = row.get(col)
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    return str(value).strip()


def _boolish_text(value: object) -> str:
    return str(value or "").strip()


def _infer_account_currency(account_label: str) -> str:
    text = (account_label or "").upper()
    if any(part in text for part in ("BYBIT", "BINANCE")):
        return "USDT"
    if "COINSPOT" in text:
        return "AUD"
    if any(part in text for part in ("OANDA", "PEPPERSTONE")):
        return "AUD"
    return ""


def _is_empty_cell(value: object) -> bool:
    if value is None:
        return True
    try:
        if pd.isna(value):
            return True
    except Exception:
        pass
    if isinstance(value, str):
        return value.strip() == ""
    return False


def _cell_to_str(value: object) -> str:
    if _is_empty_cell(value):
        return ""
    if isinstance(value, datetime):
        return value.isoformat()
    return str(value).strip()


def _cell_to_float(value: object) -> Optional[float]:
    if _is_empty_cell(value):
        return None
    if isinstance(value, (int, float)):
        try:
            return float(value)
        except Exception:
            return None
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        neg = False
        if text.startswith("(") and text.endswith(")"):
            neg = True
            text = text[1:-1].strip()
        text = text.replace(",", "")
        text = re.sub(r"(?i)\b(AUD|USD|USDT|EUR|GBP|JPY|CHF|NZD|CAD)\b", "", text).strip()
        text = text.replace("$", "").strip()
        text = re.sub(r"[^0-9+\-\.eE]", "", text).strip()
        if not text:
            return None
        try:
            val = float(text)
            return -val if neg else val
        except Exception:
            return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _cell_to_iso(value: object) -> Optional[str]:
    if _is_empty_cell(value):
        return None
    try:
        return pd.to_datetime(value, utc=True).isoformat()
    except Exception:
        text = _cell_to_str(value)
        return text or None


def _first_present(df: pd.DataFrame, candidates: List[str]) -> Optional[str]:
    cols = {_norm_col(col): col for col in df.columns}
    for candidate in candidates:
        if candidate in cols:
            return cols[candidate]
    return None


def _is_bybit_demo_account_label(label: object) -> bool:
    text = str(label or "").strip().upper()
    return bool(text) and ("BYBIT" in text) and ("DEMO" in text)


def _is_bybit_demo_workbook_name(name_or_path: object) -> bool:
    text = str(name_or_path or "").strip().lower()
    if not text:
        return False
    base = Path(text).name
    return base == BYBIT_DEMO_WORKBOOK_NAME.lower()


def _is_bybit_demo_source_path(path: object) -> bool:
    text = str(path or "").strip().lower()
    if not text:
        return False
    return text.endswith(f"/{BYBIT_DEMO_WORKBOOK_NAME.lower()}") or _is_bybit_demo_workbook_name(text)


def _is_oanda_transaction_history_frame(df: pd.DataFrame) -> bool:
    required = {"TICKET", "TRANSACTION DATE", "TRANSACTION TYPE", "DETAILS", "BALANCE"}
    cols = {str(c).strip().upper() for c in df.columns}
    return required.issubset(cols)


def _to_journal_display_iso(value: object) -> Optional[str]:
    iso = _epoch_or_iso_to_iso(value)
    if not iso:
        return None
    try:
        dt = datetime.fromisoformat(iso.replace("Z", "+00:00"))
    except Exception:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(JOURNAL_DISPLAY_TZ).isoformat()


def _parse_oanda_datetime_to_epoch_and_journal_iso(value: object) -> Tuple[float, Optional[str]]:
    raw = str(value or "").strip()
    if not raw:
        return float("-inf"), None
    normalized = raw.replace(" AEST", " +10:00").replace(" AEDT", " +11:00")
    try:
        parsed_utc = pd.to_datetime(normalized, utc=True)
    except Exception:
        return float("-inf"), None
    epoch = float(parsed_utc.timestamp())
    local_iso = parsed_utc.to_pydatetime().astimezone(JOURNAL_DISPLAY_TZ).isoformat()
    return epoch, local_iso


def _journal_rows_from_oanda_transaction_history_frame(
    df: pd.DataFrame, *, account_mode: str, account_label: str, source_path: str
) -> Dict[str, object]:
    def _parse_dt(value: object) -> Tuple[float, Optional[str]]:
        return _parse_oanda_datetime_to_epoch_and_journal_iso(value)

    opening_order_types = {"MARKET_ORDER", "MARKET_IF_TOUCHED_ORDER"}
    opening_fill_details = {"MARKET_ORDER", "MARKET_IF_TOUCHED_ORDER"}
    closing_fill_details = {
        "MARKET_ORDER_TRADE_CLOSE",
        "MARKET_ORDER_POSITION_CLOSEOUT",
        "TAKE_PROFIT_ORDER",
        "STOP_LOSS_ORDER",
    }

    rows: List[Dict[str, object]] = []
    warnings: List[str] = []
    unmatched_open: List[str] = []
    unmatched_close: List[str] = []
    frame = df.copy()
    frame["_ticket_num"] = pd.to_numeric(frame.get("TICKET"), errors="coerce")
    frame["_dt_parsed"] = frame.get("TRANSACTION DATE").map(_parse_dt)
    frame["_dt_epoch"] = frame["_dt_parsed"].map(
        lambda value: value[0] if isinstance(value, tuple) else float("-inf")
    )
    frame["_dt"] = frame["_dt_parsed"].map(
        lambda value: value[1] if isinstance(value, tuple) else None
    )
    frame = frame.sort_values(by=["_dt_epoch", "_ticket_num"], kind="stable")
    open_legs: Dict[Tuple[str, int], List[Dict[str, object]]] = defaultdict(list)
    pending_client: Dict[Tuple[str, int, str], List[Dict[str, object]]] = defaultdict(list)
    financing_events: List[Dict[str, object]] = []
    closed_trades: List[Dict[str, object]] = []
    latest_balance = None
    latest_asof = None
    for _, r in frame.iterrows():
        tx_type = str(r.get("TRANSACTION TYPE") or "").strip().upper()
        details = str(r.get("DETAILS") or "").strip().upper()
        symbol = str(r.get("INSTRUMENT") or "").strip().upper()
        direction = str(r.get("DIRECTION") or "").strip().title()
        ticket = str(r.get("TICKET") or "").strip()
        when = r.get("_dt")
        when_epoch = _to_float(r.get("_dt_epoch"))
        pl = _to_float(r.get("PL"))
        bal = _to_float(r.get("BALANCE"))
        if bal is not None and when:
            latest_balance = bal
            latest_asof = when
        if tx_type in opening_order_types and details == "CLIENT_ORDER" and symbol:
            units_value = _to_float(r.get("UNITS"))
            units = int(abs(units_value)) if units_value is not None else 0
            if units > 0:
                pending_client[(symbol, units, direction.lower())].append(
                    {
                        "sl": _to_float(r.get("STOP LOSS")),
                        "tp": _to_float(r.get("TAKE PROFIT")),
                        "ticket": ticket,
                    }
                )
            continue
        if tx_type == "ORDER_FILL" and details in opening_fill_details and symbol:
            units_value = _to_float(r.get("UNITS"))
            units = int(abs(units_value)) if units_value is not None else 0
            if units <= 0:
                continue
            pending = pending_client.get((symbol, units, direction.lower())) or []
            pending_context = pending.pop(0) if pending else {}
            open_conversion_rate = _positive_float(r.get("CONVERSION RATE"))
            open_legs[(symbol, units)].append(
                {
                    "ticket": ticket,
                    "open_time": when,
                    "open_epoch": when_epoch,
                    "symbol": _canonical_symbol(symbol),
                    "side": direction,
                    "units": units,
                    "entry": _to_float(r.get("PRICE")),
                    "sl": _to_float(r.get("STOP LOSS")) or pending_context.get("sl"),
                    "tp": _to_float(r.get("TAKE PROFIT")) or pending_context.get("tp"),
                    "spread_cost": _to_float(r.get("SPREAD COST")),
                    "commission_raw": _to_float(r.get("COMMISSION")) or 0.0,
                    "gsl_fee_raw": _to_float(r.get("GSL FEE")) or 0.0,
                    "gsl_premium_raw": _to_float(r.get("GSL PREMIUM")) or 0.0,
                    "original_loss_conversion_factor": open_conversion_rate,
                    "opening_loss_conversion_factor": open_conversion_rate,
                    "oanda_export_open_conversion_rate": open_conversion_rate,
                    "original_loss_conversion_factor_source": (
                        "oanda_export_open_conversion_rate" if open_conversion_rate is not None else None
                    ),
                    "original_loss_conversion_factor_time": when if open_conversion_rate is not None else None,
                    "original_open_transaction_id": ticket if open_conversion_rate is not None else None,
                }
            )
            continue
        if tx_type in {"DAILY_FINANCING", "DAILY_FUNDING", "FUNDING", "SWAP"}:
            financing = next(
                (
                    candidate
                    for key in ("FINANCING", "FUNDING", "SWAP")
                    if (candidate := _to_float(r.get(key))) is not None
                ),
                None,
            )
            if financing is not None and when_epoch is not None:
                financing_events.append(
                    {"ticket": ticket, "epoch": when_epoch, "amount": financing}
                )
            continue
        if (
            tx_type == "ORDER_FILL"
            and details in closing_fill_details
            and symbol
        ):
            units_value = _to_float(r.get("UNITS"))
            units = int(abs(units_value)) if units_value is not None else 0
            if units <= 0:
                continue
            bucket = open_legs.get((symbol, units)) or []
            if not bucket:
                unmatched_close.append(ticket)
                continue
            opened = bucket.pop(0)
            closed_trades.append(
                {
                    "opened": opened,
                    "close_ticket": ticket,
                    "close_units": units,
                    "close_time": when,
                    "close_epoch": when_epoch,
                    "close_details": details,
                    "exit_price": _to_float(r.get("PRICE")),
                    "close_spread_cost": _to_float(r.get("SPREAD COST")),
                    "close_conversion_rate": _to_float(r.get("CONVERSION RATE")),
                    "pl": pl,
                    "balance": bal,
                    "commission_raw": _to_float(r.get("COMMISSION")) or 0.0,
                    "gsl_fee_raw": _to_float(r.get("GSL FEE")) or 0.0,
                    "gsl_premium_raw": _to_float(r.get("GSL PREMIUM")) or 0.0,
                    "financing": 0.0,
                }
            )

    for event in financing_events:
        event_epoch = _to_float(event.get("epoch"))
        candidates = [
            trade
            for trade in closed_trades
            if event_epoch is not None
            and _to_float((trade.get("opened") or {}).get("open_epoch")) is not None
            and _to_float(trade.get("close_epoch")) is not None
            and _to_float((trade.get("opened") or {}).get("open_epoch")) <= event_epoch <= _to_float(trade.get("close_epoch"))
        ]
        if len(candidates) == 1:
            candidates[0]["financing"] = (_to_float(candidates[0].get("financing")) or 0.0) + (
                _to_float(event.get("amount")) or 0.0
            )
        elif not candidates:
            warnings.append(f"unallocated_oanda_financing:{event.get('ticket')}")
        else:
            warnings.append(f"ambiguous_oanda_financing_allocation:{event.get('ticket')}")

    for trade in closed_trades:
        opened = trade.get("opened") if isinstance(trade.get("opened"), dict) else {}
        allocated_financing = _to_float(trade.get("financing")) or 0.0
        open_commission_raw = _to_float(opened.get("commission_raw")) or 0.0
        close_commission_raw = _to_float(trade.get("commission_raw")) or 0.0
        open_gsl_fee_raw = _to_float(opened.get("gsl_fee_raw")) or 0.0
        close_gsl_fee_raw = _to_float(trade.get("gsl_fee_raw")) or 0.0
        open_gsl_premium_raw = _to_float(opened.get("gsl_premium_raw")) or 0.0
        close_gsl_premium_raw = _to_float(trade.get("gsl_premium_raw")) or 0.0
        commission_raw = open_commission_raw + close_commission_raw
        gsl_fee_raw = open_gsl_fee_raw + close_gsl_fee_raw
        gsl_premium_raw = open_gsl_premium_raw + close_gsl_premium_raw
        actual_commission = sum(
            abs(value)
            for value in (
                open_commission_raw,
                close_commission_raw,
                open_gsl_fee_raw,
                close_gsl_fee_raw,
                open_gsl_premium_raw,
                close_gsl_premium_raw,
            )
        )
        financing_commission = abs(allocated_financing)
        displayed_commission = actual_commission + financing_commission
        commission = None if math.isclose(displayed_commission, 0.0, abs_tol=1e-12) else displayed_commission
        open_spread = _to_float(opened.get("spread_cost"))
        close_spread = _to_float(trade.get("close_spread_cost"))
        total_spread = (open_spread or 0.0) + (close_spread or 0.0)
        open_conversion_rate = _positive_float(opened.get("original_loss_conversion_factor"))
        close_conversion_rate = _positive_float(trade.get("close_conversion_rate"))
        conversion_rate = open_conversion_rate
        conversion_source = opened.get("original_loss_conversion_factor_source")
        conversion_time = opened.get("original_loss_conversion_factor_time")
        open_transaction_id = opened.get("original_open_transaction_id") or opened.get("ticket")
        opened_units = _to_float(opened.get("units")) or 0.0
        closed_units = _to_float(trade.get("close_units")) or 0.0
        single_complete_exit = bool(opened_units and closed_units and abs(opened_units) == abs(closed_units))
        net = (
            (_to_float(trade.get("pl")) or 0.0)
            + allocated_financing
            - actual_commission
        )
        rows.append(
            _normalize_journal_profit_fields(
                {
                    "id": f"oanda_export:{account_mode}:{opened.get('ticket')}:{trade.get('close_ticket')}",
                    "source": "oanda_transaction_export",
                    "account": account_mode,
                    "account_label": account_label,
                    "asset_class": "forex",
                    "symbol": opened.get("symbol"),
                    "side": opened.get("side"),
                    "status": "closed",
                    "open_time": opened.get("open_time"),
                    "close_time": trade.get("close_time"),
                    "qty": (_to_float(opened.get("units")) or 0.0) / 100000.0,
                    "qty_raw": opened.get("units"),
                    "qty_unit": "lots",
                    "entry_price": opened.get("entry"),
                    "exit_price": trade.get("exit_price"),
                    "stop_loss": opened.get("sl"),
                    "take_profit": opened.get("tp"),
                    "swap": allocated_financing or None,
                    "commission": commission,
                    "fees": commission,
                    "net_profit": net,
                    "realized_pnl": net,
                    "balance_after_trade": trade.get("balance"),
                    "balance_after_trade_currency": "AUD",
                    "original_loss_conversion_factor": conversion_rate,
                    "opening_loss_conversion_factor": conversion_rate,
                    "original_loss_conversion_factor_source": conversion_source,
                    "original_loss_conversion_factor_time": conversion_time,
                    "original_open_transaction_id": open_transaction_id,
                    "opening_units": opened_units,
                    "closing_units": closed_units,
                    "oanda_single_complete_exit": single_complete_exit,
                    "entry_exit_prices_executed": True,
                    "oanda_export_open_conversion_rate": open_conversion_rate,
                    "metrics": {
                        "oanda_export_pl": trade.get("pl"),
                        "oanda_export_financing_allocated": allocated_financing,
                        "oanda_open_spread_cost": open_spread,
                        "oanda_close_spread_cost": close_spread,
                        "oanda_total_spread_cost": total_spread,
                        "oanda_raw_commission": commission_raw,
                        "oanda_raw_gsl_fee": gsl_fee_raw,
                        "oanda_raw_gsl_premium": gsl_premium_raw,
                        "oanda_open_raw_commission": open_commission_raw,
                        "oanda_close_raw_commission": close_commission_raw,
                        "oanda_open_raw_gsl_fee": open_gsl_fee_raw,
                        "oanda_close_raw_gsl_fee": close_gsl_fee_raw,
                        "oanda_open_raw_gsl_premium": open_gsl_premium_raw,
                        "oanda_close_raw_gsl_premium": close_gsl_premium_raw,
                        "oanda_actual_commission_total": actual_commission,
                        "oanda_broker_commission_total": actual_commission,
                        "oanda_financing_commission_total": financing_commission,
                        "oanda_displayed_commission_total": displayed_commission,
                        "oanda_commission_includes_financing": bool(financing_commission),
                        "oanda_export_conversion_rate": conversion_rate,
                        "oanda_open_conversion_rate": open_conversion_rate,
                        "oanda_close_conversion_rate": close_conversion_rate,
                        "original_loss_conversion_factor": conversion_rate,
                        "original_loss_conversion_factor_source": conversion_source,
                        "original_loss_conversion_factor_time": conversion_time,
                        "original_open_transaction_id": open_transaction_id,
                        "opening_units": opened_units,
                        "closing_units": closed_units,
                        "oanda_single_complete_exit": single_complete_exit,
                        "entry_exit_prices_executed": True,
                    },
                    "raw_refs": {
                        "source_path": source_path,
                        "open_ticket": opened.get("ticket"),
                        "close_ticket": trade.get("close_ticket"),
                        "close_details": trade.get("close_details"),
                        "transaction_date": trade.get("close_time"),
                        "transactionId": trade.get("close_ticket"),
                        "original_loss_conversion_factor": conversion_rate,
                        "original_loss_conversion_factor_source": conversion_source,
                        "original_loss_conversion_factor_time": conversion_time,
                        "original_open_transaction_id": open_transaction_id,
                        "opening_units": opened_units,
                        "closing_units": closed_units,
                        "oanda_single_complete_exit": single_complete_exit,
                        "entry_exit_prices_executed": True,
                        "oanda_open_conversion_rate": open_conversion_rate,
                        "oanda_export_open_conversion_rate": open_conversion_rate,
                        "close_conversion_rate": close_conversion_rate,
                    },
                    "updated_at": _utc_now_iso(),
                }
            )
        )
    for legs in open_legs.values():
        unmatched_open.extend(
            [str(leg.get("ticket") or "") for leg in legs if str(leg.get("ticket") or "")]
        )
    return {
        "rows": _sanitize_oanda_commission_fields(rows),
        "account_balance": {
            "source": "oanda_transaction_export_balance",
            "balance_source": "oanda_transaction_export_balance",
            "account": account_label,
            "label": account_label,
            "balance": latest_balance,
            "currency": "AUD",
            "as_of": latest_asof,
            "dropbox_path": source_path,
        },
        "warnings": warnings,
        "unmatched_open_fills": unmatched_open,
        "unmatched_close_fills": unmatched_close,
    }


def _parse_excel_account_workbook(
    file_name: str, dbx_path: str, payload: bytes
) -> Tuple[List[Dict[str, object]], Optional[Dict[str, object]]]:
    def _parse_oanda_export_datetime(value: object) -> Tuple[float, Optional[str]]:
        return _parse_oanda_datetime_to_epoch_and_journal_iso(value)
    bio = io.BytesIO(payload)
    try:
        xls = pd.ExcelFile(bio, engine="openpyxl")
    except Exception:
        bio.seek(0)
        xls = pd.ExcelFile(bio, engine="xlrd")

    all_rows: List[Dict[str, object]] = []
    account_balance: Optional[Dict[str, object]] = None
    account_label = Path(file_name).stem.strip() or file_name

    for sheet in xls.sheet_names:
        df = pd.read_excel(xls, sheet_name=sheet)
        if df is None or df.empty:
            continue
        df.columns = [str(col) for col in df.columns]
        norm_to_orig = {_norm_col(col): col for col in df.columns}

        open_time_col = _first_present(df, ["opening_time", "open_time", "entry_time", "time_open"])
        close_time_col = _first_present(df, ["closing_time", "close_time", "exit_time", "time_close", "closed_at"])
        side_col = _first_present(df, ["type_buy_sell", "side", "direction", "buy_sell", "type"])
        symbol_col = _first_present(df, ["symbol", "instrument", "pair", "market"])
        account_col = _first_present(df, ["account", "account_label", "portfolio", "book"])
        account_ccy_col = _first_present(df, ["account_currency", "currency", "ccy", "deposit_currency"])
        setup_col = _first_present(df, ["setup"])
        qty_col = _first_present(df, ["size_quantity", "qty", "quantity", "size", "units", "volume"])
        entry_col = _first_present(df, ["entry_price", "entry", "open_price", "price_open"])
        exit_col = _first_present(df, ["closing_price", "exit_price", "exit", "close_price", "price_close"])
        swap_col = _first_present(df, ["swap", "financing", "funding"])
        commission_col = _first_present(df, ["commission", "fee", "fees", "cost"])
        pnl_col = _first_present(df, ["net_profit", "realized_pnl", "pnl", "profit", "pl", "net_pnl"])
        is_oanda_export_sheet = _is_oanda_transaction_history_frame(df)
        balance_after_trade_aliases = ["balance_after_trade", "bal_after_trade", "balance_after", "bal_after"]
        if is_oanda_export_sheet:
            balance_after_trade_aliases.append("balance")
        balance_after_trade_col = _first_present(df, balance_after_trade_aliases)
        sl_col = _first_present(df, ["stop_loss_optional", "stop_loss", "sl"])
        tp_col = _first_present(df, ["take_profit_optional", "take_profit", "tp"])
        high_col = _first_present(df, ["highest_price_optional", "highest_price"])
        low_col = _first_present(df, ["lowest_price_optional", "lowest_price"])
        notes_col = _first_present(df, ["notes"])
        pre_trade_col = _first_present(df, ["pre_trade_comments"])
        entry_comments_col = _first_present(df, ["entry_comments"])
        trade_mgmt_col = _first_present(df, ["trade_management"])
        exit_comments_col = _first_present(df, ["exit_comments"])
        breakeven_col = _first_present(df, ["breakeven"])

        extra_aliases = {
            "error": ["error"],
            "ath_atl": ["ath_atl"],
            "ema_bounce": ["ema_bounce"],
            "timeframe": ["timeframe"],
            "pattern": ["pattern"],
            "held_through_news": ["held_through_news"],
            "early_close": ["early_close"],
            "near_perfect_entry": ["near_perfect_entry"],
            "near_win": ["near_win"],
            "near_round_number": ["near_round_number"],
            "close_stopout": ["close_stopout", "close_stop_out", "stop_out"],
            "spiked_out": ["spiked_out"],
            "suggestions": ["suggestions"],
        }
        extra_cols = {key: _first_present(df, aliases) for key, aliases in extra_aliases.items()}

        trade_signal_count = sum(
            col is not None
            for col in [symbol_col, side_col, entry_col, exit_col, pnl_col, open_time_col, close_time_col]
        )
        if symbol_col and trade_signal_count >= 3 and not is_oanda_export_sheet:
            for idx, row in df.iterrows():
                symbol_raw = _safe_str_from_row(row, symbol_col)
                if not symbol_raw or symbol_raw.lower() == "nan":
                    continue

                row_account_label = _safe_str_from_row(row, account_col) or account_label
                account_currency = _safe_str_from_row(row, account_ccy_col) or _infer_account_currency(row_account_label)
                symbol_canon = _canonical_symbol(symbol_raw)

                open_time_iso = None
                close_time_iso = None
                for col_name, target in ((open_time_col, "open"), (close_time_col, "close")):
                    if not col_name:
                        continue
                    raw_t = row.get(col_name)
                    try:
                        if pd.isna(raw_t):
                            continue
                    except Exception:
                        pass
                    try:
                        iso = pd.to_datetime(raw_t).isoformat()
                    except Exception:
                        iso = str(raw_t)
                    if target == "open":
                        open_time_iso = iso
                    else:
                        close_time_iso = iso

                raw_qty = _safe_float_from_row(row, qty_col)
                qty_display = _normalize_fx_qty_for_display(row_account_label, symbol_canon, raw_qty)
                entry_price = _safe_float_from_row(row, entry_col)
                exit_price = _safe_float_from_row(row, exit_col)
                commission = _safe_float_from_row(row, commission_col)
                swap = _safe_float_from_row(row, swap_col)
                net_profit = _safe_float_from_row(row, pnl_col)
                balance_after_trade = _safe_float_from_row(row, balance_after_trade_col)
                stop_loss = _safe_float_from_row(row, sl_col)
                take_profit = _safe_float_from_row(row, tp_col)
                highest_price = _safe_float_from_row(row, high_col)
                lowest_price = _safe_float_from_row(row, low_col)

                raw_excel: Dict[str, object] = {}
                for col_name in df.columns:
                    value = _excel_cell_to_python(row.get(col_name))
                    if value is None or (isinstance(value, str) and not value.strip()):
                        continue
                    raw_excel[str(col_name)] = value

                metrics: Dict[str, object] = {}
                for key, col_name in extra_cols.items():
                    if not col_name:
                        continue
                    value = _excel_cell_to_python(row.get(col_name))
                    if value is None or (isinstance(value, str) and not str(value).strip()):
                        continue
                    metrics[key] = value
                timeframe = _normalize_timeframe(metrics.get("timeframe"))
                if timeframe:
                    metrics["timeframe"] = timeframe
                asset_class = _infer_asset_class(row_account_label, symbol_canon, row, metrics)

                used_norm = {
                    _norm_col(x)
                    for x in [
                        open_time_col, close_time_col, side_col, symbol_col, setup_col, qty_col,
                        entry_col, exit_col, swap_col, commission_col, pnl_col, balance_after_trade_col, sl_col, tp_col,
                        high_col, low_col, notes_col, pre_trade_col, entry_comments_col,
                        trade_mgmt_col, exit_comments_col, breakeven_col,
                    ] if x
                }
                used_norm.update(_norm_col(c) for c in extra_cols.values() if c)
                for norm_name, orig_name in norm_to_orig.items():
                    if norm_name in used_norm:
                        continue
                    value = _excel_cell_to_python(row.get(orig_name))
                    if value is None or (isinstance(value, str) and not str(value).strip()):
                        continue
                    metrics.setdefault(norm_name, value)

                workbook_is_bybit_demo = file_name.strip().lower() == BYBIT_DEMO_WORKBOOK_NAME.lower()
                order_id_col = _first_present(df, ["order_id", "orderid"])
                order_id_raw = _safe_str_from_row(row, order_id_col)
                row_id = f"excel:{account_label}:{sheet}:{idx}:{symbol_canon}:{close_time_iso or ''}"
                if workbook_is_bybit_demo and order_id_raw:
                    row_id = _journal_id_for_bybit_demo_row(symbol_canon, order_id_raw)
                side_txt = _safe_str_from_row(row, side_col).upper()
                if workbook_is_bybit_demo:
                    corrected = _infer_side_from_tpsl_geometry(
                        entry_price=entry_price,
                        stop_loss=stop_loss,
                        take_profit=take_profit,
                    ) or _infer_side_from_exit_and_pnl(
                        entry_price=entry_price,
                        exit_price=exit_price,
                        realized_pnl=net_profit,
                    )
                    if corrected:
                        side_txt = corrected.upper()
                setup_txt = _safe_str_from_row(row, setup_col)
                breakeven_txt = _boolish_text(_safe_str_from_row(row, breakeven_col))
                status = "closed" if exit_price is not None else "unknown"
                notional = (
                    abs((qty_display or 0.0) * (entry_price or 0.0))
                    if (qty_display is not None and entry_price is not None)
                    else None
                )

                source_tag = "excel"
                lower_name = str(file_name or "").strip().lower()
                if "pepperstone" in lower_name or "mt5" in lower_name:
                    source_tag = "pepperstone_mt5_statement"
                if source_tag == "pepperstone_mt5_statement":
                    pnl_key = _norm_col(pnl_col) if pnl_col else ""
                    has_trusted_explicit_net = pnl_key in {"net_profit", "realized_pnl", "net_pnl"}
                    if not has_trusted_explicit_net:
                        profit_v = _safe_float_from_row(row, _first_present(df, ["profit", "pnl", "pl"]))
                        if profit_v is not None:
                            net_profit = profit_v + (_safe_float_from_row(row, commission_col) or 0.0) + (_safe_float_from_row(row, swap_col) or 0.0)
                all_rows.append(_normalize_journal_profit_fields({
                    "id": row_id,
                    "source": source_tag,
                    "account": row_account_label,
                    "account_label": row_account_label,
                    "sheet": sheet,
                    "asset_class": asset_class,
                    "currency": account_currency,
                    "symbol": symbol_canon,
                    "symbol_raw": symbol_raw,
                    "side": side_txt,
                    "setup": setup_txt,
                    "timeframe": timeframe,
                    "open_time": open_time_iso,
                    "close_time": close_time_iso,
                    "qty": qty_display,
                    "qty_raw": raw_qty,
                    "qty_unit": "lots" if asset_class == "fx" else "native",
                    "entry_price": entry_price,
                    "exit_price": exit_price,
                    "swap": swap,
                    "commission": commission,
                    "commission_currency": "AUD" if asset_class == "fx" else "USDT",
                    "fees": commission,
                    "fee_currency": "AUD" if asset_class == "fx" else "USDT",
                    "realized_pnl": net_profit,
                    "realized_pnl_currency": account_currency,
                    "net_profit": net_profit,
                    "balance_after_trade": balance_after_trade,
                    "balance_after_trade_currency": account_currency,
                    "stop_loss": stop_loss,
                    "take_profit": take_profit,
                    "highest_price": highest_price,
                    "lowest_price": lowest_price,
                    "breakeven": breakeven_txt,
                    "notes": _safe_str_from_row(row, notes_col),
                    "pre_trade_comments": _safe_str_from_row(row, pre_trade_col),
                    "entry_comments": _safe_str_from_row(row, entry_comments_col),
                    "trade_management": _safe_str_from_row(row, trade_mgmt_col),
                    "exit_comments": _safe_str_from_row(row, exit_comments_col),
                    "notional_usd": notional,
                    "status": status,
                    "metrics": metrics,
                    "raw_excel": raw_excel,
                    "raw_refs": {
                        "dropbox_path": dbx_path,
                        "sheet": sheet,
                        "row_index": int(idx),
                        "orderId": order_id_raw or None,
                    },
                    "updated_at": _utc_now_iso(),
                }))

        if is_oanda_export_sheet:
            mode = "demo" if "demo" in account_label.lower() else "live"
            parsed = _journal_rows_from_oanda_transaction_history_frame(
                df,
                account_mode=mode,
                account_label=account_label,
                source_path=dbx_path,
            )
            all_rows.extend(parsed.get("rows") or [])
            account_balance = parsed.get("account_balance") or account_balance
            continue

        bal_col = _first_present(
            df,
            [
                "balance",
                "account_balance",
                "cash_balance",
                "balance_after_trade",
                "bal_after_trade",
                "bal_after",
                "balance_after",
            ],
        )
        nav_col = _first_present(df, ["nav", "equity", "account_equity"])
        ccy_col = _first_present(df, ["currency", "ccy", "account_currency"])
        if bal_col or nav_col:
            latest_bal_row: Optional[pd.Series] = None
            latest_bal_ts = float("-inf")
            ts_col = close_time_col or open_time_col
            if ts_col:
                for _, row in df.iterrows():
                    bal_val = row.get(bal_col) if bal_col else None
                    nav_val = row.get(nav_col) if nav_col else None
                    if _is_empty_cell(bal_val) and _is_empty_cell(nav_val):
                        continue
                    ts_raw = row.get(ts_col)
                    if _is_empty_cell(ts_raw):
                        continue
                    try:
                        ts = float(pd.to_datetime(ts_raw, utc=True).timestamp())
                    except Exception:
                        continue
                    if ts >= latest_bal_ts:
                        latest_bal_ts = ts
                        latest_bal_row = row
            chosen_row = latest_bal_row
            if chosen_row is None:
                # Fallback when timestamps are unavailable: use latest physical non-empty balance-like row.
                for _, row in df.iloc[::-1].iterrows():
                    bal_val = row.get(bal_col) if bal_col else None
                    nav_val = row.get(nav_col) if nav_col else None
                    if _is_empty_cell(bal_val) and _is_empty_cell(nav_val):
                        continue
                    chosen_row = row
                    break
            if chosen_row is not None:
                bal_val = chosen_row.get(bal_col) if bal_col else None
                nav_val = chosen_row.get(nav_col) if nav_col else None
                account_balance = {
                    "source": "excel",
                    "account": account_label,
                    "label": account_label,
                    "balance": _cell_to_float(bal_val),
                    "nav": _cell_to_float(nav_val),
                    "currency": _cell_to_str(chosen_row.get(ccy_col)) if ccy_col else _infer_account_currency(account_label),
                    "dropbox_path": dbx_path,
                }

    return _sanitize_oanda_commission_fields(all_rows), account_balance
def _resolve_trading_journal_dropbox_folder() -> Tuple[str, List[Dict[str, Any]]]:
    if not TRADING_JOURNAL_DROPBOX_FOLDER:
        raise HTTPException(status_code=500, detail="TRADING_JOURNAL_DROPBOX_FOLDER is not set.")

    configured = TRADING_JOURNAL_DROPBOX_FOLDER.strip()
    candidates: List[str] = []
    if configured:
        candidates.append(configured)

    prefix = "/Apps/alexpsym_render"
    if configured.lower().startswith(prefix.lower()):
        stripped = configured[len(prefix) :]
        if not stripped:
            stripped = "/"
        if not stripped.startswith("/"):
            stripped = "/" + stripped
        candidates.append(stripped)

    if configured.startswith("/") and not configured.lower().startswith("/apps/"):
        candidates.append(f"{prefix}{configured}")

    entries: Optional[List[Dict[str, Any]]] = None
    active_folder = configured
    last_exc: Optional[Exception] = None
    for candidate in dict.fromkeys(candidates):
        try:
            entries = list_excel_files(candidate, recursive=TRADING_JOURNAL_DROPBOX_RECURSIVE)
            active_folder = candidate
            break
        except Exception as exc:
            last_exc = exc

    if entries is None:
        if last_exc is not None:
            raise last_exc
        raise FileNotFoundError(f"Dropbox folder not found: {configured}")

    return active_folder, entries


def _join_dropbox_path(folder: str, name: str) -> str:
    root = (folder or "").rstrip("/")
    if not root:
        root = "/"
    if root == "/":
        return f"/{name.lstrip('/')}"
    return f"{root}/{name.lstrip('/')}"


def _cashflow_template_bytes() -> bytes:
    buffer = io.BytesIO()
    cols = ["account", "date", "amount", "new_balance", "currency", "reason"]
    template = pd.DataFrame(columns=cols)
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        template.to_excel(writer, sheet_name="Cashflows", index=False)
    return buffer.getvalue()


def _bybit_demo_workbook_bytes() -> bytes:
    buffer = io.BytesIO()
    template = pd.DataFrame(columns=BYBIT_DEMO_WORKBOOK_COLUMNS)
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        template.to_excel(writer, sheet_name=BYBIT_DEMO_WORKBOOK_SHEET, index=False)
    return buffer.getvalue()


def _resolve_local_journal_file(name: str, base_dir: Optional[Path] = None) -> Path:
    root = base_dir or TRADING_JOURNAL_LOCAL_DIR
    target = root / str(name or "").strip()
    if target.exists():
        return target
    try:
        expected = target.name.lower()
        for candidate in root.iterdir():
            if candidate.is_file() and candidate.name.lower() == expected:
                return candidate
    except Exception:
        pass
    return target


def _local_journal_workbook_path(name: str) -> Path:
    return _resolve_local_journal_file(name, TRADING_JOURNAL_LOCAL_DIR)


def _write_excel_atomic(path: Path, sheet_name: str, frame: pd.DataFrame) -> None:
    parent = path.parent
    parent.mkdir(parents=True, exist_ok=True)
    tmp = parent / f".{path.name}.{uuid4().hex}.tmp.xlsx"
    try:
        with pd.ExcelWriter(tmp, engine="openpyxl") as writer:
            frame.to_excel(writer, sheet_name=sheet_name, index=False)
        os.replace(tmp, path)
    except Exception:
        try:
            if tmp != path and tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        raise


def _atomic_write_bytes(path: Path, data: bytes) -> None:
    path = path.expanduser()
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.tmp-{uuid4().hex}")
    with open(tmp, "wb") as fh:
        fh.write(data)
        fh.flush()
        os.fsync(fh.fileno())
    replace_error: Optional[BaseException] = None
    for attempt in range(5):
        try:
            os.replace(tmp, path)
            return
        except Exception as exc:
            winerror = int(getattr(exc, "winerror", 0) or 0)
            if not isinstance(exc, (PermissionError, OSError)) or winerror not in (5, 32):
                raise
            replace_error = exc
            if attempt >= 4:
                break
            time.sleep(0.05 * (attempt + 1))
    try:
        with open(path, "wb") as out:
            out.write(data)
            out.flush()
            os.fsync(out.fileno())
    finally:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
    if replace_error is not None:
        APP_LOGGER.warning("Atomic replace failed for %s; direct write fallback used: %s", path, replace_error)


def _read_excel_sheet_or_empty(path: Path, sheet_name: str, columns: List[str]) -> pd.DataFrame:
    if not path.exists():
        return pd.DataFrame(columns=columns)
    try:
        frame = pd.read_excel(path, sheet_name=sheet_name)
    except Exception as exc:
        raise RuntimeError(f"Failed to read workbook '{path}' sheet '{sheet_name}': {exc}") from exc
    if not isinstance(frame, pd.DataFrame):
        return pd.DataFrame(columns=columns)
    return frame


def _calc_context_uses_repo_local() -> bool:
    return bool(LOCAL_STATE_ONLY or APP_PROFILE == "local" or _master_journal_authoritative_enabled() or _master_journal_single_file_mode() or _trading_journal_local_excel_authoritative())


def _bybit_demo_calc_context_path(active_folder: Optional[str] = None) -> str:
    if _calc_context_uses_repo_local():
        return str(BYBIT_DEMO_CALC_CONTEXT_LOCAL_PATH)
    override = BYBIT_DEMO_CALC_CONTEXT_DROPBOX_PATH
    if override:
        return override
    folder = active_folder or _resolve_trading_journal_dropbox_folder()[0]
    return _join_dropbox_path(folder, BYBIT_DEMO_CALC_CONTEXT_NAME)


def _normalize_bybit_demo_calc_context_payload(payload: object) -> Dict[str, object]:
    base = {"version": BYBIT_DEMO_CALC_CONTEXT_VERSION, "updated_at": _utc_now_iso(), "items": []}
    if not isinstance(payload, dict):
        return base
    items = payload.get("items") if isinstance(payload.get("items"), list) else []
    base["items"] = items
    return base


def _load_bybit_demo_calc_contexts(active_folder: Optional[str] = None) -> Dict[str, object]:
    if _calc_context_uses_repo_local():
        src = BYBIT_DEMO_CALC_CONTEXT_LOCAL_PATH
        if not src.exists() and BYBIT_DEMO_CALC_CONTEXT_LEGACY_LOCAL_PATH.exists():
            src.parent.mkdir(parents=True, exist_ok=True)
            src.write_text(BYBIT_DEMO_CALC_CONTEXT_LEGACY_LOCAL_PATH.read_text(encoding="utf-8"), encoding="utf-8")
        if src.exists():
            return _normalize_bybit_demo_calc_context_payload(json.loads(src.read_text(encoding="utf-8")))
        return _normalize_bybit_demo_calc_context_payload({})
    dbx = _dropbox_client_or_none()
    if dbx is None:
        return _normalize_bybit_demo_calc_context_payload({})
    path = _bybit_demo_calc_context_path(active_folder)
    try:
        _meta, resp = dbx.files_download(path)
        return _normalize_bybit_demo_calc_context_payload(json.loads(resp.content.decode("utf-8")))
    except Exception:
        return _normalize_bybit_demo_calc_context_payload({})

def _save_bybit_demo_calc_contexts(payload: Dict[str, object], active_folder: Optional[str] = None) -> None:
    payload = _normalize_bybit_demo_calc_context_payload(payload)
    payload["updated_at"] = _utc_now_iso()
    if _calc_context_uses_repo_local():
        path = BYBIT_DEMO_CALC_CONTEXT_LOCAL_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        _atomic_write_bytes(path, json.dumps(_sanitize_calc_context_obj(payload), ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        return
    path = _bybit_demo_calc_context_path(active_folder)
    _dropbox_upload_bytes(path, json.dumps(_sanitize_calc_context_obj(payload), ensure_ascii=False, separators=(",", ":")).encode("utf-8"))


def _ensure_bybit_demo_dropbox_files(active_folder: str) -> Dict[str, bool]:
    created = {
        "trade_history_template_created": False,
        "demo_workbook_created": False,
    }

    template_path = _join_dropbox_path(active_folder, BYBIT_DEMO_TEMPLATE_NAME)
    try:
        _dropbox_download_bytes(template_path)
    except FileNotFoundError:
        if bybit_history_fetcher is None:
            raise RuntimeError("Bybit history exporter module not available.")
        buffer = io.StringIO()
        bybit_history_fetcher.write_blank_trade_history_template(buffer)
        _dropbox_upload_bytes(template_path, buffer.getvalue().encode("utf-8"))
        created["trade_history_template_created"] = True

    workbook_path = _join_dropbox_path(active_folder, BYBIT_DEMO_WORKBOOK_NAME)
    try:
        _dropbox_download_bytes(workbook_path)
    except FileNotFoundError:
        _dropbox_upload_bytes(workbook_path, _bybit_demo_workbook_bytes())
        created["demo_workbook_created"] = True

    return created


async def _ensure_trading_journal_dropbox_templates() -> None:
    try:
        active_folder, _entries = await asyncio.to_thread(_resolve_trading_journal_dropbox_folder)
        await asyncio.to_thread(_ensure_cashflow_template, active_folder)
        await asyncio.to_thread(_ensure_bybit_demo_dropbox_files, active_folder)
    except Exception as exc:  # pragma: no cover - startup safeguard
        _record_bybit_demo_sync_status(last_checked_at=_utc_now_iso(), last_error=str(exc))
        BYBIT_LOGGER.error("Dropbox journal template ensure failed: %s", exc)


def _ensure_cashflow_template(active_folder: str) -> bool:
    cashflow_path = _join_dropbox_path(active_folder, "account_cashflows.xlsx")
    try:
        _dropbox_download_bytes(cashflow_path)
        return False
    except Exception:
        pass
    _dropbox_upload_bytes(cashflow_path, _cashflow_template_bytes())
    return True


# 30s default unless CASHFLOW_CACHE_TTL_SECONDS is configured.
_CASHFLOW_CACHE_TTL_SECONDS = int(os.getenv("CASHFLOW_CACHE_TTL_SECONDS", "30"))
_CASHFLOW_CACHE: Dict[str, Tuple[float, Dict[str, List[Dict[str, object]]]]] = {}  # keyed by active Dropbox folder
_CASHFLOW_CACHE_LOCK = threading.Lock()


def _parse_cashflow_workbook_payload(payload: bytes) -> Dict[str, List[Dict[str, object]]]:
    out: Dict[str, List[Dict[str, object]]] = defaultdict(list)
    bio = io.BytesIO(payload)
    try:
        df = pd.read_excel(bio, sheet_name="Cashflows")
    except Exception:
        return dict(out)
    if df is None or df.empty:
        return dict(out)
    df.columns = [str(c) for c in df.columns]
    acct_col = _first_present(df, ["account"])
    date_col = _first_present(df, ["date"])
    amount_col = _first_present(df, ["amount"])
    bal_col = _first_present(df, ["new_balance", "newbalance"])
    ccy_col = _first_present(df, ["currency"])
    reason_col = _first_present(df, ["reason"])
    if not acct_col or not date_col or not bal_col:
        return dict(out)

    for _, row in df.iterrows():
        account = _safe_str_from_row(row, acct_col)
        account_key = _norm_account_key(account)
        if not account_key:
            continue
        raw_date = row.get(date_col)
        try:
            if pd.isna(raw_date):
                continue
        except Exception:
            pass
        try:
            dt_iso = pd.to_datetime(raw_date).isoformat()
        except Exception:
            dt_iso = str(raw_date)
        out[account_key].append(
            {
                "account": account,
                "date": dt_iso,
                "amount": _safe_float_from_row(row, amount_col),
                "new_balance": _safe_float_from_row(row, bal_col),
                "currency": _safe_str_from_row(row, ccy_col),
                "reason": _safe_str_from_row(row, reason_col),
            }
        )

    for account_key in list(out.keys()):
        out[account_key] = sorted(out[account_key], key=lambda x: str(x.get("date") or ""))
    return dict(out)


def _load_cashflows_from_local(local_dir: Path) -> Dict[str, List[Dict[str, object]]]:
    cashflow_path = (local_dir / "account_cashflows.xlsx") if isinstance(local_dir, Path) else Path("account_cashflows.xlsx")
    if not cashflow_path.exists() or not cashflow_path.is_file():
        return {}
    try:
        payload = cashflow_path.read_bytes()
    except Exception:
        return {}
    return _parse_cashflow_workbook_payload(payload)


def _ensure_local_cashflow_template(local_dir: Path) -> bool:
    target = local_dir / "account_cashflows.xlsx"
    if target.exists():
        return False
    local_dir.mkdir(parents=True, exist_ok=True)
    target.write_bytes(_cashflow_template_bytes())
    return True


def _ensure_local_bybit_demo_files(local_dir: Path) -> Dict[str, bool]:
    created = {"trade_history_template_created": False, "demo_workbook_created": False}
    local_dir.mkdir(parents=True, exist_ok=True)
    template_path = local_dir / BYBIT_DEMO_TEMPLATE_NAME
    if not template_path.exists():
        if bybit_history_fetcher is None:
            raise RuntimeError("Bybit history exporter module not available.")
        bybit_history_fetcher.write_blank_trade_history_template(str(template_path))
        created["trade_history_template_created"] = True
    workbook_path = _resolve_local_journal_file(BYBIT_DEMO_WORKBOOK_NAME, local_dir)
    if not workbook_path.exists():
        workbook_path.write_bytes(_bybit_demo_workbook_bytes())
        created["demo_workbook_created"] = True
    return created


def _ensure_trading_journal_local_templates() -> Dict[str, object]:
    result: Dict[str, object] = {
        "cashflow_template_created": False,
        "trade_history_template_created": False,
        "demo_workbook_created": False,
        "errors": [],
    }
    local_dir = TRADING_JOURNAL_LOCAL_DIR
    try:
        result["cashflow_template_created"] = _ensure_local_cashflow_template(local_dir)
    except Exception as exc:
        result["errors"].append(f"account_cashflows.xlsx create failed: {exc}")
    try:
        bybit = _ensure_local_bybit_demo_files(local_dir)
        result.update(bybit)
    except Exception as exc:
        result["errors"].append(f"Bybit local template create failed: {exc}")
    return result


def _load_cashflows_from_dropbox(active_folder: str) -> Dict[str, List[Dict[str, object]]]:
    folder_key = str(active_folder or "").strip()
    if folder_key:
        now = time.time()
        with _CASHFLOW_CACHE_LOCK:
            cached = _CASHFLOW_CACHE.get(folder_key)
        if cached and (now - cached[0] < _CASHFLOW_CACHE_TTL_SECONDS):
            return cached[1]

    out: Dict[str, List[Dict[str, object]]] = defaultdict(list)

    def _cache_and_return() -> Dict[str, List[Dict[str, object]]]:
        # Cache successful, empty, and error fallbacks to avoid retry storms during Dropbox issues.
        payload: Dict[str, List[Dict[str, object]]] = dict(out)
        if folder_key:
            with _CASHFLOW_CACHE_LOCK:
                _CASHFLOW_CACHE[folder_key] = (time.time(), payload)
        return payload

    cashflow_path = _join_dropbox_path(active_folder, "account_cashflows.xlsx")
    try:
        payload = _dropbox_download_bytes(cashflow_path)
    except Exception:
        return _cache_and_return()
    out.update(_parse_cashflow_workbook_payload(payload))
    return _cache_and_return()


def _load_cashflows_for_active_journal_source(state: dict) -> Dict[str, List[Dict[str, object]]]:
    source_mode = str(os.getenv("TRADING_JOURNAL_SOURCE", TRADING_JOURNAL_SOURCE) or "").strip().lower()
    state_source = str((state or {}).get("source_mode") or "").strip().lower()
    active_source = state_source or source_mode or "both"
    local_dir = TRADING_JOURNAL_LOCAL_DIR
    local_cashflow_path = local_dir / "account_cashflows.xlsx"

    if active_source == "local":
        return _load_cashflows_from_local(local_dir)
    if active_source == "dropbox":
        active_folder = str((state or {}).get("source_folder") or "")
        return _load_cashflows_from_dropbox(active_folder) if active_folder else {}
    if active_source in {"both", "auto"}:
        if local_cashflow_path.exists():
            return _load_cashflows_from_local(local_dir)
        active_folder = str((state or {}).get("source_folder") or "")
        return _load_cashflows_from_dropbox(active_folder) if active_folder else {}
    if local_cashflow_path.exists():
        return _load_cashflows_from_local(local_dir)
    active_folder = str((state or {}).get("source_folder") or "")
    return _load_cashflows_from_dropbox(active_folder) if active_folder else {}


def _build_journal_balance_timelines(
    rows: List[Dict[str, object]],
    cashflow_ledger: Dict[str, List[Dict[str, object]]],
    excel_balances: List[Dict[str, object]],
) -> Dict[str, object]:
    def _authoritative_balance_after_trade(row: Dict[str, object]) -> Optional[float]:
        bal = _to_float(row.get("balance_after_trade"))
        if bal is None:
            return None
        source = str(row.get("source") or "").strip().lower()
        if source in {"oanda", "oanda_transaction_export", "excel", "local_excel", "master_journal"}:
            return bal
        bal_source = str(row.get("balance_after_trade_source") or "").strip().lower()
        if bal_source == "master_journal":
            return bal
        raw_refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        raw_excel = row.get("raw_excel") if isinstance(row.get("raw_excel"), dict) else {}
        refs_text = " ".join(str(raw_refs.get(k) or "") for k in ("transaction_type", "details", "sheet", "workbook"))
        excel_keys = {str(k).strip().upper() for k in raw_excel.keys()}
        if "ORDER_FILL" in refs_text.upper() or ("BALANCE" in excel_keys and "TRANSACTION DATE" in excel_keys):
            return bal
        return None

    def _is_authoritative_account_balance_seed(seed: Dict[str, object]) -> bool:
        source = str(seed.get("balance_source") or seed.get("source") or "").strip().lower()
        if source in {"oanda_transaction_export_balance", "oanda_account_summary", "broker_account_summary", "account_summary"}:
            return True
        if source in {"excel", "local_excel"}:
            raw_refs = seed.get("raw_refs") if isinstance(seed.get("raw_refs"), dict) else {}
            refs_text = " ".join(str(raw_refs.get(k) or "") for k in ("transaction_type", "details", "sheet", "workbook"))
            if "ORDER_FILL" in refs_text.upper() or "TRANSACTION" in refs_text.upper():
                return True
        return False
    def _prefer_seed_on_tie(seed_source: str, seed_as_of: object) -> bool:
        if not str(seed_as_of or "").strip():
            return False
        return str(seed_source or "").strip().lower() in {
            "oanda_transaction_export_balance", "oanda_account_summary", "broker_account_summary", "account_summary"
        }
    ts_cache: Dict[str, float] = {}
    def _to_ts(value: object) -> float:
        return _timestamp_epoch_seconds(value, cache=ts_cache)
    def _apply_pnl_to_balance(row: Dict[str, object], pnl: Optional[float]) -> bool:
        if pnl is None:
            return False
        source = str(row.get("source") or "").strip().lower()
        if source in {"bybit", "bybit_execution_history", "bybit_execution_history_grouped"}:
            return True
        return not _is_test_trade_row(row)

    out_rows: List[Dict[str, object]] = []
    for source_row in rows:
        clean_row = dict(source_row)
        clean_row.pop("analysis_balance_before_trade", None)
        clean_row.pop("analysis_balance_after_trade", None)
        clean_row.pop("analysis_balance_before_trade_source", None)
        out_rows.append(clean_row)
    by_account: Dict[str, Dict[str, object]] = defaultdict(lambda: {"trade_indices": [], "labels": [], "currencies": []})

    for idx, row in enumerate(out_rows):
        if not _is_trade_row(row):
            continue
        label = str(row.get("account_label") or row.get("account") or "").strip()
        key = _norm_account_key(label)
        if not key:
            continue
        by_account[key]["trade_indices"].append(idx)
        if label:
            by_account[key]["labels"].append((label, _to_ts(row.get("close_time") or row.get("open_time"))))
        ccy = str(row.get("balance_after_trade_currency") or row.get("currency") or "").strip()
        if ccy:
            by_account[key]["currencies"].append((ccy, _to_ts(row.get("close_time") or row.get("open_time"))))

    for bal in excel_balances or []:
        if not isinstance(bal, dict):
            continue
        label = str(bal.get("label") or bal.get("account") or "").strip()
        key = _norm_account_key(label)
        if not key:
            continue
        by_account[key]["excel_balance"] = _to_float(bal.get("balance"))
        by_account[key]["excel_label"] = label
        by_account[key]["excel_currency"] = str(bal.get("currency") or "").strip()
        by_account[key]["excel_balance_source"] = str(bal.get("balance_source") or bal.get("source") or "excel_account_balance")
        excel_as_of = bal.get("as_of")
        raw_refs = bal.get("raw_refs") if isinstance(bal.get("raw_refs"), dict) else {}
        if not excel_as_of:
            excel_as_of = raw_refs.get("transaction_date")
        by_account[key]["excel_balance_as_of"] = excel_as_of
        excel_timeline_as_of = bal.get("timeline_as_of") or excel_as_of
        by_account[key]["excel_balance_timeline_as_of"] = excel_timeline_as_of
        by_account[key]["excel_balance_ts"] = _to_ts(excel_timeline_as_of)
        by_account[key]["excel_balance_authoritative"] = _is_authoritative_account_balance_seed(bal)

    diagnostics: Dict[str, Dict[str, object]] = {}
    balances: List[Dict[str, object]] = []

    for account_key in sorted(set([*by_account.keys(), *((cashflow_ledger or {}).keys())])):
        bucket = by_account.get(account_key) or {"trade_indices": [], "labels": [], "currencies": []}
        trade_indices = sorted(
            bucket.get("trade_indices") or [],
            key=lambda i: _to_ts(out_rows[i].get("close_time") or out_rows[i].get("open_time")),
        )
        raw_events = sorted((cashflow_ledger or {}).get(account_key) or [], key=lambda e: _to_ts(e.get("date")))
        events = [e for e in raw_events if _to_float(e.get("new_balance")) is not None]
        ignored_cashflow_anchor_count = len(raw_events) - len(events)
        event_ts = [_to_ts(e.get("date")) for e in events]
        has_cashflow = len(events) > 0
        segment_running: Dict[int, float] = {}
        last_known_balance: Optional[float] = None
        last_known_ts = float("-inf")

        for row_idx in trade_indices:
            row = out_rows[row_idx]
            trade_ts = _to_ts(row.get("close_time") or row.get("open_time"))
            pnl = _row_pnl(row)
            authoritative_after = _authoritative_balance_after_trade(row)

            if has_cashflow:
                anchor_idx = -1
                for i, _ev in enumerate(events):
                    if event_ts[i] <= trade_ts:
                        anchor_idx = i
                    else:
                        break
                if authoritative_after is not None:
                    before = authoritative_after - pnl if _apply_pnl_to_balance(row, pnl) else authoritative_after
                    row["analysis_balance_before_trade"] = before
                    row["analysis_balance_after_trade"] = authoritative_after
                    row["analysis_balance_before_trade_source"] = (
                        "authoritative_after_minus_trade_result"
                    )
                    last_known_balance = authoritative_after
                    last_known_ts = trade_ts
                    continue
                if anchor_idx >= 0:
                    if anchor_idx not in segment_running:
                        anchor_balance = _to_float(events[anchor_idx].get("new_balance"))
                        if anchor_balance is None:
                            continue
                        segment_running[anchor_idx] = anchor_balance
                    before = segment_running[anchor_idx]
                    after = before
                    if _apply_pnl_to_balance(row, pnl):
                        after = before + pnl
                    segment_running[anchor_idx] = after
                    row["analysis_balance_before_trade"] = before
                    row["analysis_balance_after_trade"] = after
                    row["analysis_balance_before_trade_source"] = (
                        "cashflow_anchor_plus_trade_results"
                    )
                    last_known_balance = after
                    last_known_ts = trade_ts
                    continue
                continue

            if authoritative_after is not None:
                before = authoritative_after - pnl if _apply_pnl_to_balance(row, pnl) else authoritative_after
                row["analysis_balance_before_trade"] = before
                row["analysis_balance_after_trade"] = authoritative_after
                row["analysis_balance_before_trade_source"] = (
                    "authoritative_after_minus_trade_result"
                )
                last_known_balance = authoritative_after
                last_known_ts = trade_ts
                continue

            if last_known_balance is not None:
                before = last_known_balance
                after = before
                if _apply_pnl_to_balance(row, pnl):
                    after = before + pnl
                row["analysis_balance_before_trade"] = before
                row["analysis_balance_after_trade"] = after
                row["analysis_balance_before_trade_source"] = (
                    "prior_verified_trade_balance_plus_results"
                )
                last_known_balance = after
                last_known_ts = trade_ts

        latest_trade_authoritative_balance: Optional[float] = None
        latest_trade_authoritative_ts = float("-inf")
        latest_trade_authoritative_as_of: Optional[object] = None
        for row_idx in trade_indices:
            row = out_rows[row_idx]
            value = _authoritative_balance_after_trade(row)
            if value is None:
                continue
            ts = _to_ts(row.get("close_time") or row.get("open_time"))
            if ts >= latest_trade_authoritative_ts:
                latest_trade_authoritative_ts = ts
                latest_trade_authoritative_balance = value
                latest_trade_authoritative_as_of = row.get("close_time") or row.get("open_time")

        authoritative_seed_balance = _to_float(bucket.get("excel_balance")) if bool(bucket.get("excel_balance_authoritative")) else None
        authoritative_seed_ts = _to_ts(
            bucket.get("excel_balance_timeline_as_of")
            or bucket.get("excel_balance_as_of")
        ) if authoritative_seed_balance is not None else float("-inf")
        authoritative_seed_source = str(bucket.get("excel_balance_source") or "excel_account_balance")

        display_balance: Optional[float] = None
        balance_source = "timeline_missing"
        as_of: Optional[object] = None
        authoritative_balance_used: Optional[float] = None
        authoritative_balance_source: Optional[str] = None
        latest_authoritative_at: Optional[object] = None
        selected_authoritative_balance: Optional[float] = latest_trade_authoritative_balance
        selected_authoritative_source: Optional[str] = "authoritative_trade_balance" if latest_trade_authoritative_balance is not None else None
        selected_authoritative_ts = latest_trade_authoritative_ts if latest_trade_authoritative_balance is not None else float("-inf")
        selected_authoritative_as_of: Optional[object] = latest_trade_authoritative_as_of
        if authoritative_seed_balance is not None:
            if (
                authoritative_seed_ts > selected_authoritative_ts
                or (
                    authoritative_seed_ts == selected_authoritative_ts
                    and _prefer_seed_on_tie(authoritative_seed_source, bucket.get("excel_balance_as_of"))
                )
            ):
                selected_authoritative_balance = authoritative_seed_balance
                selected_authoritative_source = authoritative_seed_source
                selected_authoritative_ts = authoritative_seed_ts
                selected_authoritative_as_of = bucket.get("excel_balance_as_of")
        latest_authoritative_at = selected_authoritative_as_of

        if has_cashflow:
            latest_event_idx = len(events) - 1
            base = _to_float(events[latest_event_idx].get("new_balance"))
            latest_cashflow_ts = _to_ts(events[latest_event_idx].get("date"))
            if base is not None and latest_cashflow_ts > selected_authoritative_ts:
                display_balance = segment_running.get(latest_event_idx, base)
                balance_source = "cashflow_anchor_plus_trades"
                as_of = events[latest_event_idx].get("date")
            elif selected_authoritative_balance is not None:
                display_balance = selected_authoritative_balance
                balance_source = str(selected_authoritative_source or "authoritative_trade_balance")
                as_of = selected_authoritative_as_of
                authoritative_balance_used = selected_authoritative_balance
                authoritative_balance_source = balance_source
                latest_authoritative_at = as_of
        elif last_known_balance is not None:
            if (
                selected_authoritative_balance is not None
                and (
                    selected_authoritative_ts > last_known_ts
                    or (
                        selected_authoritative_ts == last_known_ts
                        and str(selected_authoritative_source or "")
                        != "authoritative_trade_balance"
                    )
                )
            ):
                display_balance = selected_authoritative_balance
                balance_source = str(
                    selected_authoritative_source or "authoritative_trade_balance"
                )
                as_of = selected_authoritative_as_of
            else:
                display_balance = last_known_balance
                balance_source = "trade_timeline"
                as_of = next((out_rows[i].get("close_time") or out_rows[i].get("open_time") for i in reversed(trade_indices) if _to_ts(out_rows[i].get("close_time") or out_rows[i].get("open_time")) == last_known_ts), None)
            authoritative_balance_used = selected_authoritative_balance
            authoritative_balance_source = selected_authoritative_source
            latest_authoritative_at = selected_authoritative_as_of if selected_authoritative_balance is not None else latest_authoritative_at
        elif selected_authoritative_balance is not None:
            display_balance = selected_authoritative_balance
            balance_source = str(selected_authoritative_source or "authoritative_trade_balance")
            as_of = selected_authoritative_as_of
            authoritative_balance_used = selected_authoritative_balance
            authoritative_balance_source = selected_authoritative_source
            latest_authoritative_at = as_of
        elif _to_float(bucket.get("excel_balance")) is not None and bool(bucket.get("excel_balance_authoritative")):
            display_balance = _to_float(bucket.get("excel_balance"))
            balance_source = str(bucket.get("excel_balance_source") or "excel_account_balance")

        latest_cashflow = events[-1] if events else {}
        label = str(latest_cashflow.get("account") or bucket.get("excel_label") or (bucket.get("labels")[-1][0] if bucket.get("labels") else account_key))
        currency = str(latest_cashflow.get("currency") or bucket.get("excel_currency") or (bucket.get("currencies")[-1][0] if bucket.get("currencies") else _infer_account_currency(label)))
        missing_balance = display_balance is None
        if (not ENABLE_BYBIT_DEMO_JOURNAL) and _is_bybit_demo_account_label(label):
            continue
        balances.append(
            {
                "account": label,
                "label": label,
                "balance": display_balance,
                "currency": currency,
                "source": balance_source,
                "balance_source": balance_source,
                "as_of": as_of,
                "missing_balance": missing_balance,
                "last_trade_at": (out_rows[trade_indices[-1]].get("close_time") or out_rows[trade_indices[-1]].get("open_time")) if trade_indices else None,
                "stale_cashflow_overridden": bool(events and display_balance is not None and balance_source != "cashflow_anchor_plus_trades" and _to_ts(events[-1].get("date")) <= selected_authoritative_ts),
            }
        )
        diagnostics[account_key] = {
            "account_key": account_key,
            "cashflow_events": len(events),
            "ignored_cashflow_anchors_without_new_balance": ignored_cashflow_anchor_count,
            "trade_rows": len(trade_indices),
            "missing_balance": missing_balance,
            "latest_cashflow_at": events[-1].get("date") if events else None,
            "latest_authoritative_balance_at": latest_authoritative_at,
            "balance_source": balance_source,
            "stale_cashflow_overridden": bool(events and display_balance is not None and balance_source != "cashflow_anchor_plus_trades" and _to_ts(events[-1].get("date")) <= selected_authoritative_ts),
            "previous_cashflow_balance": _to_float(events[-1].get("new_balance")) if events else None,
            "authoritative_balance_used": authoritative_balance_used if authoritative_balance_used is not None else (selected_authoritative_balance if balance_source != "cashflow_anchor_plus_trades" else None),
            "authoritative_balance_source": authoritative_balance_source if authoritative_balance_used is not None else (selected_authoritative_source if balance_source != "cashflow_anchor_plus_trades" else None),
            "warning": "No cashflow or authoritative trade balance anchor found." if missing_balance else "",
        }
    balances = sorted(balances, key=lambda x: str(x.get("label") or x.get("account") or ""))
    return {"rows": out_rows, "balances": balances, "diagnostics": diagnostics}


def _latest_balances_from_cashflows(ledger: Dict[str, List[Dict[str, object]]]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    for account_key, events in ledger.items():
        if not events:
            continue
        latest = events[-1]
        label = str(latest.get("account") or account_key)
        items.append(
            {
                "account": label,
                "label": label,
                "balance": _to_float(latest.get("new_balance")),
                "nav": None,
                "currency": str(latest.get("currency") or _infer_account_currency(label)),
                "source": "cashflow_ledger",
                "as_of": latest.get("date"),
            }
        )
    return sorted(items, key=lambda x: str(x.get("label") or ""))




def _canonical_journal_account_label(label: object, *, source: object=None, account_mode: object=None) -> str:
    raw = str(label or "").strip()
    low = raw.lower().replace("_", " ").replace("-", " ")
    src = str(source or "").strip().lower()
    mode = str(account_mode or "").strip().lower()
    parts = {p for p in low.split() if p}
    has_bybit = "bybit" in parts
    has_demo = "demo" in parts
    has_live = "live" in parts
    if (has_bybit and has_demo) or ("bybit" in src and mode == "demo"):
        return "Bybit Demo"
    if (has_bybit and not has_demo and (has_live or len(parts) == 1)) or ("bybit" in src and mode == "live"):
        return "BYBIT"
    return raw

def _merge_display_balances(*groups: List[Dict[str, object]]) -> List[Dict[str, object]]:
    merged: Dict[str, Dict[str, object]] = {}
    for group in groups:
        for item in group or []:
            if not isinstance(item, dict):
                continue
            label = _canonical_journal_account_label(item.get("label") or item.get("account"), source=item.get("source"), account_mode=item.get("account_mode"))
            if not label:
                continue
            if _is_bybit_demo_account_label(label) and not ENABLE_BYBIT_DEMO_JOURNAL:
                continue
            key = _norm_account_key(label)
            existing = merged.get(key) or {}
            balance = _to_float(item.get("balance"))
            if balance is None:
                balance = _to_float(item.get("nav"))
            payload = dict(existing)
            payload["account"] = _canonical_journal_account_label(item.get("account") or existing.get("account") or label, source=item.get("source"), account_mode=item.get("account_mode"))
            payload["label"] = _canonical_journal_account_label(item.get("label") or existing.get("label") or label, source=item.get("source"), account_mode=item.get("account_mode"))
            if balance is not None:
                payload["balance"] = balance
            payload["currency"] = str(item.get("currency") or existing.get("currency") or _infer_account_currency(label))
            payload["source"] = str(item.get("source") or item.get("balance_source") or existing.get("source") or "unknown")
            payload["balance_source"] = str(item.get("balance_source") or item.get("source") or existing.get("balance_source") or payload["source"])
            if item.get("as_of"):
                payload["as_of"] = item.get("as_of")
            elif existing.get("as_of"):
                payload["as_of"] = existing.get("as_of")
            payload["missing_balance"] = payload.get("balance") is None
            merged[key] = payload
    return sorted(merged.values(), key=lambda x: str(x.get("label") or x.get("account") or ""))


def _merge_missing_timeline_balances_with_broker(
    balances: List[Dict[str, object]],
    broker_balances: List[Dict[str, object]],
) -> List[Dict[str, object]]:
    merged: List[Dict[str, object]] = []
    by_key: Dict[str, int] = {}
    for item in (balances or []):
        if not isinstance(item, dict):
            continue
        normalized = dict(item)
        canonical = _canonical_journal_account_label(
            normalized.get("label") or normalized.get("account"),
            source=normalized.get("source"),
            account_mode=normalized.get("account_mode"),
        )
        if canonical:
            normalized["label"] = canonical
            normalized["account"] = canonical
            normalized["account_label"] = canonical
        merged.append(normalized)
    for idx, item in enumerate(merged):
        label = _canonical_journal_account_label(item.get("label") or item.get("account"), source=item.get("source"), account_mode=item.get("account_mode"))
        if _is_bybit_demo_account_label(label) and not ENABLE_BYBIT_DEMO_JOURNAL:
            continue
        key = _norm_account_key(label)
        if key:
            by_key[key] = idx
    for broker in broker_balances or []:
        if not isinstance(broker, dict):
            continue
        label = _canonical_journal_account_label(broker.get("label") or broker.get("account"), source=broker.get("source"), account_mode=broker.get("account_mode"))
        if not label:
            continue
        if _is_bybit_demo_account_label(label) and not ENABLE_BYBIT_DEMO_JOURNAL:
            continue
        key = _norm_account_key(label)
        broker_balance = _to_float(broker.get("balance"))
        if broker_balance is None:
            broker_balance = _to_float(broker.get("nav"))
        existing_idx = by_key.get(key)
        if existing_idx is None:
            broker_payload = dict(broker)
            broker_payload["label"] = label
            broker_payload["account"] = label
            broker_payload["account_label"] = label
            broker_payload["missing_balance"] = _to_float(broker_payload.get("balance")) is None
            merged.append(broker_payload)
            by_key[key] = len(merged) - 1
            continue
        existing = dict(merged[existing_idx])
        existing_balance = _to_float(existing.get("balance"))
        if broker_balance is None:
            continue
        existing_as_of_ts = _to_float(pd.to_datetime(existing.get("as_of"), utc=True).timestamp()) if existing.get("as_of") else None
        broker_as_of_ts = _to_float(pd.to_datetime(broker.get("as_of"), utc=True).timestamp()) if broker.get("as_of") else None
        if existing_balance is not None and not bool(existing.get("missing_balance")):
            existing_source = str(existing.get("balance_source") or existing.get("source") or "").lower()
            broker_source = str(broker.get("balance_source") or broker.get("source") or "").lower()
            trusted_broker_sources = {"oanda_account_summary", "broker_account_summary", "bybit_wallet_balance", "bybit_demo_wallet_balance_anchor"}
            can_override = "cashflow" in existing_source or existing_source in {"timeline_missing", "excel_account_balance", "trade_timeline"}
            if existing_source == "authoritative_trade_balance":
                can_override = broker_source in trusted_broker_sources
            if key == _norm_account_key('BYBIT') and broker_source == 'bybit_wallet_balance':
                existing["label"] = "BYBIT"
                existing["account"] = "BYBIT"
                existing["account_label"] = "BYBIT"
                existing['skipped_broker_balance_reason'] = 'existing_bybit_balance_preserved'
                merged[existing_idx] = existing
                continue
            if not can_override:
                continue
            if existing_as_of_ts is not None and broker_as_of_ts is not None and existing_as_of_ts > broker_as_of_ts:
                continue
        resolved = dict(existing)
        resolved["previous_balance"] = existing_balance
        resolved["balance"] = broker_balance
        resolved["label"] = label
        resolved["account"] = label
        resolved["account_label"] = label
        resolved["currency"] = str(broker.get("currency") or existing.get("currency") or _infer_account_currency(label))
        source = str(broker.get("source") or broker.get("balance_source") or "bybit_wallet_balance")
        resolved["source"] = source
        resolved["balance_source"] = str(broker.get("balance_source") or broker.get("source") or source)
        resolved["missing_balance"] = False
        resolved["resolved_missing_balance_with_broker"] = True
        resolved["resolved_or_overridden_with_broker"] = True
        resolved["previous_balance_source"] = str(existing.get("balance_source") or existing.get("source") or "timeline_missing")
        resolved["broker_balance_as_of"] = broker.get("as_of")
        if broker.get("as_of"):
            resolved["as_of"] = broker.get("as_of")
        merged[existing_idx] = resolved
    return sorted(merged, key=lambda x: str(x.get("label") or x.get("account") or ""))


def _cashflow_rows_for_journal(ledger: Dict[str, List[Dict[str, object]]]) -> List[Dict[str, object]]:
    rows: List[Dict[str, object]] = []
    for account_key, events in ledger.items():
        for idx, ev in enumerate(events or []):
            event_dt = str(ev.get("date") or "")
            if not event_dt:
                continue
            account_label = str(ev.get("account") or account_key or "").strip()
            amount = _to_float(ev.get("amount"))
            new_balance = _to_float(ev.get("new_balance"))
            currency = str(ev.get("currency") or _infer_account_currency(account_label))
            reason = str(ev.get("reason") or "").strip()
            if amount is None and new_balance is None:
                continue
            flow_type = "cashflow"
            if amount is not None:
                if amount > 0:
                    flow_type = "deposit"
                elif amount < 0:
                    flow_type = "withdrawal"
            else:
                preserved_type = str(ev.get("side") or "").strip().lower()
                if preserved_type in {"deposit", "withdrawal", "adjustment", "cashflow"}:
                    flow_type = preserved_type
            rows.append(
                {
                    "id": str(ev.get("id") or f"cashflow:{account_key}:{event_dt}:{idx}"),
                    "row_type": "cashflow",
                    "cashflow_type": flow_type,
                    "cashflow_reason": reason,
                    "cashflow_amount": amount,
                    "cashflow_new_balance": new_balance,
                    "source": "cashflow_ledger",
                    "account": account_label,
                    "account_label": account_label,
                    "sheet": "Cashflows",
                    "asset_class": "fx" if _is_fx_account_label(account_label) else "crypto",
                    "currency": currency,
                    "symbol": "CASHFLOW",
                    "symbol_raw": "CASHFLOW",
                    "side": flow_type.upper(),
                    "setup": "",
                    "open_time": event_dt,
                    "close_time": event_dt,
                    "qty": None,
                    "qty_raw": None,
                    "qty_unit": "",
                    "entry_price": None,
                    "exit_price": None,
                    "swap": None,
                    "commission": None,
                    "commission_currency": currency,
                    "fees": None,
                    "fee_currency": currency,
                    "realized_pnl": None,
                    "realized_pnl_currency": currency,
                    "net_profit": None,
                    "stop_loss": None,
                    "take_profit": None,
                    "highest_price": None,
                    "lowest_price": None,
                    "breakeven": "",
                    "notes": reason,
                    "status": "cashflow",
                    "balance_after_trade": new_balance,
                    "balance_after_trade_currency": currency,
                    "updated_at": _utc_now_iso(),
                }
            )
    return sorted(rows, key=_row_sort_dt, reverse=True)


def _list_local_trading_journal_workbooks() -> List[Path]:
    root = TRADING_JOURNAL_LOCAL_DIR
    if not root.exists() or not root.is_dir():
        return []
    found: List[Path] = []
    for candidate in root.iterdir():
        if not candidate.is_file():
            continue
        if candidate.suffix.lower() not in {".xls", ".xlsx", ".xlsm"}:
            continue
        candidate_name = candidate.name.strip().lower()
        if candidate_name in {
            "account_cashflows.xlsx",
            BYBIT_DEMO_TEMPLATE_NAME.strip().lower(),
            "master journal.xlsx",
            "tradingjournal_android_replica.xlsx",
        } or candidate_name.startswith("~$") or candidate_name.endswith(".tmp.xlsx") or candidate_name.endswith(".pending.xlsx"):
            continue
        found.append(candidate)
    # Prefer canonical xlsx workbooks when both legacy xls and xlsx exist.
    xlsx_stems = {p.stem.strip().lower() for p in found if p.suffix.lower() == ".xlsx"}
    filtered: List[Path] = []
    for candidate in found:
        if candidate.suffix.lower() == ".xls" and candidate.stem.strip().lower() in xlsx_stems:
            continue
        filtered.append(candidate)
    return sorted(filtered, key=lambda p: p.name.lower())


def _list_local_oanda_history_exports() -> List[Path]:
    root = TRADING_JOURNAL_LOCAL_DIR
    if not root.exists() or not root.is_dir():
        return []
    hits: List[Path] = []
    for candidate in root.iterdir():
        if not candidate.is_file() or candidate.suffix.lower() != ".csv":
            continue
        name = candidate.name.strip().lower()
        if "oanda" in name and "history" in name:
            hits.append(candidate)
    export_root = OANDA_HISTORY_EXPORT_ROOT
    try:
        include_global_export_root = root.resolve() in {
            (BASE_DIR / "journal").resolve(),
            export_root.resolve(),
        }
    except Exception:
        include_global_export_root = False
    if include_global_export_root and export_root.exists() and export_root.is_dir():
        for candidate in export_root.iterdir():
            if not candidate.is_file() or candidate.suffix.lower() != ".csv":
                continue
            name = candidate.name.strip().lower()
            if name.startswith("oanda_history_") and ("demo" in name or "live" in name):
                hits.append(candidate)
    return sorted(hits, key=lambda p: p.name.lower())


def _local_journal_import_enabled() -> bool:
    return TRADING_JOURNAL_ENABLE_LOCAL_IMPORT or TRADING_JOURNAL_LOCAL_DIR_EXPLICIT


def _is_default_local_workbook(path: Path) -> bool:
    try:
        return path.resolve().parent == (BASE_DIR / "journal").resolve()
    except Exception:
        return False


def _num_bucket(value: object, digits: int = 6) -> str:
    num = _to_float(value)
    if num is None:
        return ""
    return f"{num:.{digits}f}"


def _workbook_row_dedupe_fingerprint(row: Dict[str, object]) -> Optional[str]:
    if not isinstance(row, dict) or _row_type(row) != "trade":
        return None
    source = str(row.get("source") or "").strip().lower()
    if source in {"manual", "cashflow_ledger"}:
        return None
    if row.get("cashflow_type") or str(row.get("symbol") or "").strip().upper() == "CASHFLOW":
        return None
    return _trade_execution_fingerprint(row)


def _row_source_rank(row: Dict[str, object]) -> int:
    return _trade_row_source_rank(row)


def _merge_duplicate_import_rows(primary: Dict[str, object], incoming: Dict[str, object]) -> Dict[str, object]:
    merged = dict(primary)
    for field in [
        "manual_overrides",
        "manual_override_fields",
        "notes",
        "pre_trade_comments",
        "entry_comments",
        "trade_management",
        "exit_comments",
        "flags",
    ]:
        if merged.get(field) in (None, "", [], {}) and incoming.get(field) not in (None, "", [], {}):
            merged[field] = incoming.get(field)
    for k, v in incoming.items():
        if merged.get(k) in (None, "") and v not in (None, ""):
            merged[k] = v
    return merged




BYBIT_TRADE_HISTORY_REQUIRED_HEADERS = ["contracts","Order No.","Direction","Order Type","Filled Qty","Filled Price","Order Price","Filled Type","Trading Fee Rate","Fees Paid","Trasaction ID","Transaction Time(UTC+10)","Final Balance (USDT)"]

def _is_bybit_trade_history_csv(path_or_headers: object) -> bool:
    headers=[]
    if isinstance(path_or_headers, Path):
        import pandas as _pd
        try:
            headers=[str(h).strip() for h in (_pd.read_csv(path_or_headers, nrows=0, encoding='utf-8-sig').columns.tolist())]
        except Exception:
            return False
    elif isinstance(path_or_headers, (list, tuple, set)):
        headers=[str(h).strip() for h in path_or_headers]
    else:
        return False
    hs={h.lower() for h in headers}
    req={h.lower() for h in BYBIT_TRADE_HISTORY_REQUIRED_HEADERS}
    req.add('transaction id')
    req.discard('trasaction id')
    return req.issubset(hs | {'transaction id' if 'trasaction id' in hs else ''})

def _normalize_bybit_execution_history_row(raw: Dict[str, object], account_mode: str, source_path: Optional[str]=None, source_row: Optional[int]=None) -> Optional[Dict[str, object]]:
    symbol=str(raw.get('contracts') or raw.get('symbol') or '').strip().upper()
    side=str(raw.get('Direction') or raw.get('side') or '').strip().title()
    order_id=str(raw.get('Order No.') or raw.get('orderId') or '').strip()
    exec_id=str(raw.get('Trasaction ID') or raw.get('Transaction ID') or raw.get('execId') or '').strip()
    qty=_to_float(raw.get('Filled Qty') if raw.get('Filled Qty') not in (None,'') else raw.get('execQty'))
    price=_to_float(raw.get('Filled Price') if raw.get('Filled Price') not in (None,'') else raw.get('execPrice'))
    if not symbol or (not exec_id and not order_id):
        return None
    t = raw.get('Transaction Time(UTC+10)') if raw.get('Transaction Time(UTC+10)') not in (None,'') else raw.get('execTime')
    open_time = _epoch_or_iso_to_iso(t)
    if raw.get('Transaction Time(UTC+10)') not in (None, '') and isinstance(t, str):
        ts = str(t).strip()
        if ts:
            try:
                parsed = pd.to_datetime(ts, errors="coerce", dayfirst=True)
                if pd.notna(parsed):
                    brisbane = ZoneInfo("Australia/Brisbane")
                    if getattr(parsed, "tzinfo", None) is None:
                        parsed = parsed.tz_localize(brisbane)
                    else:
                        parsed = parsed.tz_convert(brisbane)
                    open_time = parsed.isoformat()
            except Exception:
                pass
    if isinstance(t,str) and '+' in t and 'T' not in t:
        try:
            open_time=t.replace(' ','T')
        except Exception:
            pass
    fee=_to_float(raw.get('Fees Paid') if raw.get('Fees Paid') not in (None,'') else raw.get('execFee'))
    fee_rate=_to_float(raw.get('Trading Fee Rate') if raw.get('Trading Fee Rate') not in (None,'') else raw.get('feeRate'))
    bal=_to_float(raw.get('Final Balance (USDT)')) if str(raw.get('Final Balance (USDT)') or '').strip() else None
    mode='demo' if str(account_mode).lower().strip()=='demo' else 'live'
    rid = f'bybit:{mode}:execution:{symbol}:{exec_id}' if exec_id else f"bybit:{mode}:execution:{symbol}:{order_id}:{open_time}:{side}:{qty}:{price}"
    return {'id': rid,'row_type':'trade','asset_class':'crypto','account':_canonical_journal_account_label('Bybit Demo' if mode=='demo' else 'Bybit Live', source='bybit', account_mode=mode),'account_label':_canonical_journal_account_label('Bybit Demo' if mode=='demo' else 'Bybit Live', source='bybit', account_mode=mode),'symbol':symbol,'side':side,'qty':qty,'entry_price':price,'exit_price':price,'open_time':open_time,'close_time':open_time,'commission':fee,'fee_rate':fee_rate,'net_profit':None,'balance_after_trade':bal,'currency':'USDT' if symbol.endswith('USDT') else '', 'source':'bybit_execution_history','notes':'Bybit execution-history row; Net P/L may be inferred from explicit P/L fields or balance continuity when provable.','raw_refs':{'orderId':order_id or None,'execId':exec_id or None,'source_file':source_path,'source_row':source_row}}

def _group_bybit_execution_history_rows_into_completed_trades(records: List[Dict[str, object]], account_mode: str, source_path: str) -> Tuple[List[Dict[str, object]], List[str], Dict[str, object]]:
    mode = "demo" if str(account_mode).lower().strip() == "demo" else "live"
    account_label = _canonical_journal_account_label("Bybit Demo" if mode == "demo" else "Bybit Live", source="bybit", account_mode=mode)
    normalized: List[Dict[str, object]] = []
    for rec in records or []:
        if not isinstance(rec, dict):
            continue
        row = _normalize_bybit_execution_history_row(rec.get("raw") or rec, mode, source_path, rec.get("_source_row"))
        if row:
            row["_source_row"] = rec.get("_source_row")
            row["_ts"] = _parse_iso_datetime(row.get("open_time"))
            normalized.append(row)
    normalized.sort(key=lambda r: ((r.get("_ts").timestamp() if isinstance(r.get("_ts"), datetime) else float("inf")), int(r.get("_source_row") or 10**9)))
    trades: List[Dict[str, object]] = []
    unmatched: List[str] = []
    reversal_rows: List[str] = []
    by_symbol: Dict[str, List[Dict[str, object]]] = defaultdict(list)
    for r in normalized:
        by_symbol[str(r.get("symbol") or "").upper()].append(r)
    for symbol, exec_rows in by_symbol.items():
        seg: List[Dict[str, object]] = []
        pos = 0.0
        for ex in exec_rows:
            qty = abs(_to_float(ex.get("qty")) or 0.0)
            if qty <= 0:
                continue
            side = str(ex.get("side") or "").strip().lower()
            signed = qty if side == "buy" else -qty
            if not seg:
                seg = [ex]; pos = signed
            else:
                if (pos > 0 and signed < 0 and abs(signed) > abs(pos)) or (pos < 0 and signed > 0 and abs(signed) > abs(pos)):
                    reversal_rows.append(str((ex.get("raw_refs") or {}).get("execId") or ex.get("id") or ""))
                    seg.append(ex)
                    break
                seg.append(ex); pos += signed
            if abs(pos) < 1e-12:
                open_side = str(seg[0].get("side") or "").strip().title()
                open_qty = sum(abs(_to_float(s.get("qty")) or 0.0) for s in seg if str(s.get("side") or "").strip().lower() == open_side.lower())
                close_qty = sum(abs(_to_float(s.get("qty")) or 0.0) for s in seg if str(s.get("side") or "").strip().lower() != open_side.lower())
                closed = min(open_qty, close_qty)
                entry_notional = sum((abs(_to_float(s.get("qty")) or 0.0) * (_to_float(s.get("entry_price")) or 0.0)) for s in seg if str(s.get("side") or "").strip().lower() == open_side.lower())
                exit_notional = sum((abs(_to_float(s.get("qty")) or 0.0) * (_to_float(s.get("entry_price")) or 0.0)) for s in seg if str(s.get("side") or "").strip().lower() != open_side.lower())
                fees = sum(_to_float(s.get("commission")) or 0.0 for s in seg)
                exec_ids = [str(((s.get("raw_refs") or {}).get("execId") or "")).strip() for s in seg if str(((s.get("raw_refs") or {}).get("execId") or "")).strip()]
                src_rows = [int(s.get("_source_row")) for s in seg if s.get("_source_row")]
                digest = hashlib.sha256("|".join(exec_ids + [str(x) for x in src_rows]).encode("utf-8")).hexdigest()[:16]
                gross = (exit_notional - entry_notional) if open_side.lower() == "buy" else (entry_notional - exit_notional)
                open_ts = seg[0].get("open_time"); close_ts = seg[-1].get("close_time") or seg[-1].get("open_time")
                open_dt = _parse_iso_datetime(open_ts)
                close_dt = _parse_iso_datetime(close_ts)
                dur = _round_trade_duration_seconds((close_dt - open_dt).total_seconds()) if open_dt and close_dt else 1
                trades.append({
                    "id": f"bybit:{mode}:trade:{symbol}:{digest}", "row_type": "trade", "asset_class": "crypto", "account": account_label, "account_label": account_label,
                    "symbol": symbol, "side": open_side, "qty": closed, "entry_price": (entry_notional / open_qty) if open_qty else None, "exit_price": (exit_notional / close_qty) if close_qty else None,
                    "open_time": open_ts, "close_time": close_ts, "commission": fees, "net_profit": gross - fees, "currency": "USDT" if symbol.endswith("USDT") else "",
                    "trade_duration_seconds": dur, "source": "bybit_execution_history_grouped",
                    "raw_refs": {"source_file": source_path, "source_rows": src_rows, "order_ids": sorted({str(((s.get("raw_refs") or {}).get("orderId") or "")).strip() for s in seg if str(((s.get("raw_refs") or {}).get("orderId") or "")).strip()}), "exec_ids": exec_ids, "execution_count": len(seg), "parser": "bybit_execution_history_grouped"}
                })
                seg = []; pos = 0.0
        if seg:
            unmatched.extend([str((s.get("raw_refs") or {}).get("execId") or s.get("id") or "") for s in seg])
    diag = {
        "bybit_execution_rows_seen": len(normalized),
        "bybit_completed_trades_imported": len(trades),
        "bybit_unmatched_execution_rows": len(unmatched),
        "bybit_reversal_execution_rows_seen": len(reversal_rows),
        "bybit_reversal_import_blocked": bool(reversal_rows),
        "bybit_reversal_row_ids": reversal_rows,
    }
    return trades, unmatched, diag

def _parse_bybit_trade_history_csv_with_diagnostics(path: Path, account_mode: str='demo') -> Tuple[List[Dict[str, object]], List[str], Dict[str, object]]:
    df = pd.read_csv(path, encoding='utf-8-sig')
    records = []
    for i, rec in enumerate(df.to_dict(orient='records'), start=2):
        rec = dict(rec); rec["_source_row"] = i; rec["raw"] = dict(rec)
        records.append(rec)
    return _group_bybit_execution_history_rows_into_completed_trades(records, account_mode, str(path))

def _parse_bybit_trade_history_csv(path: Path, account_mode: str='demo') -> List[Dict[str, object]]:
    rows, unmatched, _diag = _parse_bybit_trade_history_csv_with_diagnostics(path, account_mode=account_mode)
    if unmatched:
        raise ValueError(f"Unmatched Bybit execution rows remain open; count={len(unmatched)}")
    return rows


def _infer_realized_net_profit_from_balance_continuity(
    imported_rows: List[Dict[str, object]],
    existing_rows: List[Dict[str, object]],
) -> Tuple[List[Dict[str, object]], List[str], Dict[str, object]]:
    out = [dict(r) for r in (imported_rows or [])]
    unresolved: List[str] = []
    unresolved_reasons: Dict[str, str] = {}
    warnings: List[str] = []
    explicit_normalized = 0
    inferred = 0
    unresolved_ids: List[str] = []
    cashflow_blocked = 0

    def _is_non_trade_balance_event(row: Dict[str, object]) -> bool:
        texts = [
            str(row.get("row_type") or ""),
            str(row.get("cashflow_type") or ""),
            str(row.get("transaction_type") or ""),
            str(row.get("type") or ""),
            str(row.get("source") or ""),
            str(row.get("symbol") or ""),
            str(row.get("notes") or ""),
        ]
        raw_refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        for k in ("event", "event_type", "transaction_type", "type", "details"):
            texts.append(str(raw_refs.get(k) or ""))
        blob = " ".join(texts).lower()
        if "cashflow" in blob:
            return True
        block_terms = {
            "deposit", "withdrawal", "transfer", "funding", "rebate", "bonus",
            "interest", "dividend", "monthly revaluation", "monthly_aud_reval",
            "balance adjustment", "manual adjustment",
        }
        return any(term in blob for term in block_terms)

    def _sort_key(row: Dict[str, object]) -> Tuple[float, int, str]:
        ts = _parse_iso_datetime(
            row.get("close_time")
            or row.get("execution_time")
            or row.get("transaction_time")
            or row.get("open_time")
        )
        tsv = ts.timestamp() if isinstance(ts, datetime) else float("-inf")
        refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        src_row = refs.get("source_row")
        try:
            src_ord = int(src_row)
        except Exception:
            src_ord = 10**9
        return (tsv, src_ord, str(row.get("id") or ""))

    timeline = sorted([dict(r) for r in (existing_rows or [])] + out, key=_sort_key)
    imported_ids = {str(r.get("id") or "") for r in out}
    idx_by_id = {str(r.get("id") or ""): i for i, r in enumerate(out)}

    by_account: Dict[str, List[Dict[str, object]]] = defaultdict(list)
    for row in timeline:
        acct_key = _norm_account_key(row.get("account_label") or row.get("account"))
        by_account[acct_key].append(row)

    chains: Dict[Tuple[str, str], List[Dict[str, object]]] = defaultdict(list)
    for acct_key, rows in by_account.items():
        known_ccy = sorted({str(r.get("currency") or r.get("balance_after_trade_currency") or "").strip().upper() for r in rows if str(r.get("currency") or r.get("balance_after_trade_currency") or "").strip()})
        for r in rows:
            ccy = str(r.get("currency") or r.get("balance_after_trade_currency") or "").strip().upper()
            if not ccy:
                if len(known_ccy) == 1:
                    ccy = known_ccy[0]
                else:
                    ccy = "__AMBIG__"
            chains[(acct_key, ccy)].append(r)

    for (_acct_key, chain_ccy), chain_rows in chains.items():
        for i, row in enumerate(chain_rows):
            rid = str(row.get("id") or "")
            if rid not in imported_ids:
                continue
            if str(row.get("row_type") or "trade").strip().lower() != "trade":
                continue
            if _to_float(row.get("net_profit")) is not None:
                continue
            explicit = _to_float(row.get("realized_pnl"))
            if explicit is None:
                for alias in ("closed_pnl", "net_pnl"):
                    explicit = _to_float(row.get(alias))
                    if explicit is not None:
                        break
            source_txt = str(row.get("source") or "").strip().lower()
            refs_txt = str((row.get("raw_refs") or {}).get("source_file") or "").strip().lower() if isinstance(row.get("raw_refs"), dict) else ""
            is_mt5_like = (
                "mt5" in source_txt
                or "pepperstone" in source_txt
                or "mt5" in refs_txt
                or "pepperstone" in refs_txt
            )
            if explicit is None and is_mt5_like and _to_float(row.get("profit")) is not None:
                profit_v = _to_float(row.get("profit")) or 0.0
                commission_v = _to_float(row.get("commission")) or 0.0
                swap_v = _to_float(row.get("swap")) or 0.0
                explicit = profit_v + commission_v + swap_v
            if explicit is not None:
                out_idx = idx_by_id.get(rid)
                if out_idx is not None:
                    out[out_idx]["net_profit"] = explicit
                    if _to_float(out[out_idx].get("realized_pnl")) is None:
                        out[out_idx]["realized_pnl"] = explicit
                    explicit_normalized += 1
                continue
            if chain_ccy == "__AMBIG__":
                unresolved.append(f"{rid}:pnl_inference_ambiguous_currency")
                unresolved_reasons[rid] = "pnl_inference_ambiguous_currency"
                unresolved_ids.append(rid)
                continue
            bal = _to_float(row.get("balance_after_trade"))
            if bal is None:
                # allow immediate post-trade anchor
                nxt_bal = None
                nxt_i = None
                for j in range(i + 1, len(chain_rows)):
                    if _is_non_trade_balance_event(chain_rows[j]):
                        break
                    b2 = _to_float(chain_rows[j].get("balance_after_trade"))
                    if b2 is not None:
                        nxt_bal = b2
                        nxt_i = j
                        break
                if nxt_bal is None or nxt_i is None or nxt_i != i + 1:
                    unresolved.append(f"{rid}:pnl_inference_missing_balance_after_trade")
                    unresolved_reasons[rid] = "pnl_inference_missing_balance_after_trade"
                    unresolved_ids.append(rid)
                    continue
                nxt = chain_rows[nxt_i]
                nxt_is_trade = str(nxt.get("row_type") or "trade").strip().lower() == "trade"
                same_order = False
                refs_cur = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
                refs_nxt = nxt.get("raw_refs") if isinstance(nxt.get("raw_refs"), dict) else {}
                for key in ("orderId", "order_id", "execId", "tradeId"):
                    if refs_cur.get(key) and refs_cur.get(key) == refs_nxt.get(key):
                        same_order = True
                        break
                nxt_anchor_marked = str(nxt.get("row_type") or "").strip().lower() in {"balance", "account_balance"}
                if nxt_is_trade and not same_order:
                    unresolved.append(f"{rid}:pnl_inference_post_trade_anchor_ambiguous")
                    unresolved_reasons[rid] = "pnl_inference_post_trade_anchor_ambiguous"
                    unresolved_ids.append(rid)
                    continue
                if (not nxt_is_trade) and (not nxt_anchor_marked) and (not same_order):
                    unresolved.append(f"{rid}:pnl_inference_post_trade_anchor_ambiguous")
                    unresolved_reasons[rid] = "pnl_inference_post_trade_anchor_ambiguous"
                    unresolved_ids.append(rid)
                    continue
                bal = nxt_bal
            prev = None
            prev_index = -1
            for j in range(i - 1, -1, -1):
                pb = _to_float(chain_rows[j].get("balance_after_trade"))
                if pb is not None:
                    prev = chain_rows[j]
                    prev_index = j
                    break
            if not prev:
                unresolved.append(f"{rid}:pnl_inference_missing_previous_balance_anchor")
                unresolved_reasons[rid] = "pnl_inference_missing_previous_balance_anchor"
                unresolved_ids.append(rid)
                continue
            intervening = chain_rows[prev_index + 1:i]
            if any(_is_non_trade_balance_event(r) for r in intervening):
                unresolved.append(f"{rid}:pnl_inference_blocked_by_non_trade_balance_event")
                unresolved_reasons[rid] = "pnl_inference_blocked_by_non_trade_balance_event"
                unresolved_ids.append(rid)
                cashflow_blocked += 1
                continue
            prev_bal = _to_float(prev.get("balance_after_trade"))
            if prev_bal is None:
                unresolved.append(f"{rid}:pnl_inference_missing_previous_balance_anchor")
                unresolved_reasons[rid] = "pnl_inference_missing_previous_balance_anchor"
                unresolved_ids.append(rid)
                continue
            fee = abs(_to_float(row.get("commission")) or 0.0)
            delta = bal - prev_bal
            side_text = str(row.get("side") or "").strip().lower()
            status_text = str(row.get("status") or "").strip().lower()
            has_close_marker = bool(row.get("close_time")) or status_text in {"closed", "close", "completed", "filled"}
            is_bybit_execution_history = str(row.get("source") or "").strip().lower() == "bybit_execution_history"
            has_explicit_realized = _to_float(row.get("realized_pnl")) is not None or _to_float(row.get("closed_pnl")) is not None
            if is_bybit_execution_history and not has_explicit_realized and math.isclose(delta, -fee, abs_tol=1e-9):
                has_close_marker = False
            likely_opening = (not has_close_marker) and side_text in {"buy", "sell"}
            if likely_opening and math.isclose(delta, -fee, abs_tol=1e-9):
                unresolved.append(f"{rid}:pnl_inference_open_fill_fee_only_no_closing_proof")
                unresolved_reasons[rid] = "pnl_inference_open_fill_fee_only_no_closing_proof"
                unresolved_ids.append(rid)
                continue
            out_idx = idx_by_id.get(rid)
            if out_idx is not None:
                out[out_idx]["net_profit"] = delta
            inferred += 1
    if unresolved:
        warnings.extend(unresolved)
    diag = {
        "pnl_explicit_normalized_count": explicit_normalized,
        "pnl_inferred_count": inferred,
        "pnl_unresolved_count": len(unresolved_ids),
        "pnl_unresolved_row_ids": unresolved_ids,
        "pnl_unresolved_reasons": unresolved_reasons,
        "pnl_unresolved_cashflow_blocked_count": cashflow_blocked,
    }
    return out, warnings, diag


def _parse_local_trading_journal_workbook(path: Path, *, original_name: Optional[str] = None, account_mode: Optional[str] = None) -> Tuple[List[Dict[str, object]], Optional[Dict[str, object]]]:
    if path.suffix.lower() == ".csv":
        df = pd.read_csv(path, encoding="utf-8-sig")
        stem = Path(str(original_name or path.name)).stem.lower()
        tokens = {t for t in re.split(r"[^a-z0-9]+", stem) if t}
        hinted_mode = "demo" if "demo" in tokens else ("live" if "live" in tokens else "")
        explicit_mode = str(account_mode or "").strip().lower()
        resolved_mode = explicit_mode if explicit_mode in {"demo", "live"} else hinted_mode
        if _is_bybit_trade_history_csv(list(df.columns)):
            if not resolved_mode:
                raise ValueError("Bybit history CSV account is ambiguous. Select Demo or Live before importing.")
            return _parse_bybit_trade_history_csv(path, account_mode=resolved_mode), None
        if _is_oanda_transaction_history_frame(df):
            if not resolved_mode:
                raise ValueError("OANDA CSV account is ambiguous; include demo/live in filename.")
            account_mode = resolved_mode
            account_label = "OANDA DEMO" if account_mode == "demo" else "OANDA LIVE"
            parsed = _journal_rows_from_oanda_transaction_history_frame(
                df,
                account_mode=account_mode,
                account_label=account_label,
                source_path=str(path),
            )
            return parsed.get("rows") or [], parsed.get("account_balance")
        return [], None
    payload = path.read_bytes()
    rows, balance = _parse_excel_account_workbook(str(original_name or path.name), str(path), payload)
    for row in rows:
        if isinstance(row, dict):
            if not str(row.get("source") or "").strip():
                row["source"] = "local_excel"
            row["import_source"] = "local_excel"
    if isinstance(balance, dict):
        balance["import_source"] = "local_excel"
        if not str(balance.get("balance_source") or "").strip():
            balance["source"] = "local_excel"
    return _sanitize_oanda_commission_fields(rows), balance


def _import_trading_journal_from_dropbox_excel(
    progress_cb: Optional[Callable[[int, str], None]] = None,
) -> Dict[str, object]:
    if progress_cb:
        progress_cb(2, "Resolving Dropbox folder…")
    active_folder, entries = _resolve_trading_journal_dropbox_folder()
    configured = TRADING_JOURNAL_DROPBOX_FOLDER.strip()
    cashflow_template_created = False
    bybit_demo_templates = {
        "trade_history_template_created": False,
        "demo_workbook_created": False,
    }
    if progress_cb:
        progress_cb(6, "Checking cashflow template…")
    try:
        cashflow_template_created = _ensure_cashflow_template(active_folder)
    except Exception:
        cashflow_template_created = False
    try:
        bybit_demo_templates = _ensure_bybit_demo_dropbox_files(active_folder)
    except Exception as exc:
        errors = [{"file": BYBIT_DEMO_WORKBOOK_NAME, "path": active_folder, "error": str(exc)}]
        _save_json_file(
            TRADING_JOURNAL_STATE_PATH,
            {
                "updated_at": _utc_now_iso(),
                "excel_account_balances": [],
                "source_folder": active_folder,
                "configured_folder": configured,
                "cashflow_template_created": cashflow_template_created,
                **bybit_demo_templates,
                "errors": errors,
            },
        )
        raise

    # Refresh entries after possibly creating the cashflow template.
    # Exclude the cashflow ledger file itself from workbook imports.
    used_recursive_fallback = False
    try:
        refreshed = list_excel_files(active_folder, recursive=TRADING_JOURNAL_DROPBOX_RECURSIVE)
        if (not refreshed) and (not TRADING_JOURNAL_DROPBOX_RECURSIVE):
            # If the user keeps workbooks in subfolders, do a one-shot recursive scan.
            refreshed = list_excel_files(active_folder, recursive=True)
            used_recursive_fallback = bool(refreshed)
        entries = refreshed if isinstance(refreshed, list) else entries
    except Exception:
        pass
    entries = [
        e
        for e in (entries or [])
        if str((e or {}).get("name") or "").strip().lower() != "account_cashflows.xlsx"
    ]

    existing_rows = _get_trading_journal_rows()
    existing_count = len(existing_rows)

    workbook_count = 0
    reused_count = 0
    rows: List[Dict[str, object]] = []
    balances: List[Dict[str, object]] = []
    errors: List[Dict[str, str]] = []
    cache = _load_trading_journal_import_cache()
    cache_version = 0
    if isinstance(cache, dict):
        try:
            cache_version = int(cache.get("version") or 0)
        except Exception:
            cache_version = 0
    files_cache_raw = cache.get("files") if isinstance(cache, dict) else None
    files_cache: Dict[str, Dict[str, object]] = files_cache_raw if isinstance(files_cache_raw, dict) else {}
    if cache_version != TRADING_JOURNAL_IMPORT_CACHE_VERSION:
        files_cache = {}
    next_files_cache: Dict[str, Dict[str, object]] = {}

    total_files = len(entries)
    if progress_cb:
        progress_cb(10, f"Found {total_files} workbook(s)…")

    if total_files == 0:
        msg = (
            f"No Excel workbooks found in Dropbox folder {active_folder!r} "
            f"(configured {configured!r})."
        )
        # Don't wipe an existing journal just because Dropbox is empty / misconfigured.
        _save_json_file(
            TRADING_JOURNAL_STATE_PATH,
            {
                "updated_at": _utc_now_iso(),
                "excel_account_balances": balances,
                "source_folder": active_folder,
                "configured_folder": configured,
                "cashflow_template_created": cashflow_template_created,
                **bybit_demo_templates,
                "workbooks_seen": 0,
                "used_recursive_fallback": used_recursive_fallback,
                "errors": [{"file": "", "path": active_folder, "error": msg}],
            },
        )
        return {
            "ok": False,
            "message": msg,
            "source_folder": active_folder,
            "configured_folder": configured,
            "cashflow_template_created": cashflow_template_created,
            **bybit_demo_templates,
            "workbooks_seen": 0,
            "rows_imported": 0,
            "balances_found": 0,
            "used_recursive_fallback": used_recursive_fallback,
            "errors": [{"file": "", "path": active_folder, "error": msg}],
        }

    bybit_demo_workbook_seen = False
    bybit_demo_rows_imported = 0
    for entry_index, entry in enumerate(entries, start=1):
        name = str(entry.get("name") or "")
        dbx_path = str(entry.get("path_lower") or entry.get("path_display") or "")
        dbx_rev = str(entry.get("rev") or "")
        if not dbx_path:
            continue
        if _is_bybit_demo_workbook_name(name) or _is_bybit_demo_source_path(dbx_path):
            bybit_demo_workbook_seen = True
        try:
            if progress_cb:
                pct = 10 + int(80 * (entry_index / max(total_files, 1)))
                progress_cb(pct, f"Importing {entry_index}/{total_files}: {name}")

            cached = files_cache.get(dbx_path) if dbx_rev else None
            cached_rev = str(cached.get("rev") or "") if isinstance(cached, dict) else ""
            if cached and dbx_rev and cached_rev == dbx_rev:
                cached_rows = cached.get("rows")
                cached_balance = cached.get("balance")
                parsed_rows = cached_rows if isinstance(cached_rows, list) else []
                parsed_balance = cached_balance if isinstance(cached_balance, dict) else None
                reused_count += 1
            else:
                payload = _dropbox_download_bytes(dbx_path)
                parsed_rows, parsed_balance = _parse_excel_account_workbook(name, dbx_path, payload)

            rows.extend(parsed_rows)
            if _is_bybit_demo_workbook_name(name) or _is_bybit_demo_source_path(dbx_path):
                bybit_demo_rows_imported += sum(1 for r in parsed_rows if isinstance(r, dict) and _is_bybit_demo_trade_row(r))
            if parsed_balance:
                balances.append(parsed_balance)
            workbook_count += 1
            next_files_cache[dbx_path] = {
                "rev": dbx_rev,
                "rows": parsed_rows,
                "balance": parsed_balance,
                "name": name,
                "updated_at": _utc_now_iso(),
            }
        except Exception as exc:
            errors.append({"file": name, "path": dbx_path, "error": str(exc)})

    dedup: Dict[str, Dict[str, object]] = {}
    for row in rows:
        row_id = str(row.get("id") or "")
        if row_id:
            dedup[row_id] = row

    final_rows = sorted(dedup.values(), key=_row_sort_dt, reverse=True)

    if progress_cb:
        progress_cb(95, "Finalising…")

    bybit_demo_workbook_cleared = bool(bybit_demo_workbook_seen and bybit_demo_rows_imported == 0)
    bybit_demo_rows_purged = 0
    if bybit_demo_workbook_cleared:
        kept, bybit_demo_rows_purged = _purge_bybit_demo_rows(existing_rows)
        _set_trading_journal_rows(kept)
        existing_rows = kept
        existing_count = len(existing_rows)

    if (not final_rows) and existing_count and (not bybit_demo_workbook_cleared):
        # Keep prior data if the import produced no rows (common when folder is wrong or parsing failed).
        msg = "Imported 0 rows; keeping existing journal data."
        errors.append({"file": "", "path": active_folder, "error": msg})
    else:
        if existing_count:
            # Merge Excel-imported rows into the existing journal so webhook-fed rows are not wiped.
            combined: Dict[str, Dict[str, object]] = {}
            for r in existing_rows:
                rid = str(r.get("id") or "")
                if rid:
                    combined[rid] = r
            for r in final_rows:
                rid = str(r.get("id") or "")
                if rid:
                    combined[rid] = r
            merged_rows = sorted(combined.values(), key=_row_sort_dt, reverse=True)
            _set_trading_journal_rows(merged_rows)
        else:
            _set_trading_journal_rows(final_rows)

    ok_flag = bool(final_rows) or bool(balances) or bool(bybit_demo_workbook_cleared and bybit_demo_rows_purged >= 0)
    message = (
        "Done"
        if ok_flag
        else (
            "No trade rows imported from Excel workbooks. "
            "Check your TRADING_JOURNAL_DROPBOX_FOLDER and ensure your journal workbooks (xlsx/xlsm/xls) are inside it."
        )
    )

    _save_json_file(
        TRADING_JOURNAL_STATE_PATH,
        {
            "updated_at": _utc_now_iso(),
            "excel_account_balances": balances,
            "source_folder": active_folder,
            "configured_folder": configured,
            "cashflow_template_created": cashflow_template_created,
            **bybit_demo_templates,
            "workbooks_seen": workbook_count,
            "workbooks_reused": reused_count,
            "used_recursive_fallback": used_recursive_fallback,
            "errors": errors,
        },
    )
    _save_trading_journal_import_cache(
        {
            "version": TRADING_JOURNAL_IMPORT_CACHE_VERSION,
            "updated_at": _utc_now_iso(),
            "source_folder": active_folder,
            "files": next_files_cache,
        }
    )
    sanitized_rows, sanitize_stats = _sanitize_bybit_demo_rows(_get_trading_journal_rows())
    if int(sanitize_stats.get("changed", 0)):
        _set_trading_journal_rows(sanitized_rows)
    workbook_stats = _sanitize_bybit_demo_workbook(active_folder, None)
    _schedule_dropbox_upload_state_backup()

    return {
        "ok": ok_flag,
        "message": message,
        "source_folder": active_folder,
        "configured_folder": configured,
        "cashflow_template_created": cashflow_template_created,
        **bybit_demo_templates,
        "workbooks_seen": workbook_count,
        "workbooks_reused": reused_count,
        "rows_imported": len(final_rows),
        "bybit_demo_workbook_seen": bybit_demo_workbook_seen,
        "bybit_demo_rows_imported": bybit_demo_rows_imported,
        "bybit_demo_workbook_cleared": bybit_demo_workbook_cleared,
        "bybit_demo_rows_purged": bybit_demo_rows_purged,
        "rows_deduped": int(sanitize_stats.get("deduped_by_order_id", 0)) + int(sanitize_stats.get("deduped_by_fingerprint", 0)),
        "workbook_rows_deduped": int(workbook_stats.get("deduped_by_order_id", 0)) + int(workbook_stats.get("deduped_by_fingerprint", 0)),
        "balances_found": len(balances),
        "used_recursive_fallback": used_recursive_fallback,
        "errors": errors,
    }


def _import_trading_journal_from_sources(
    progress_cb: Optional[Callable[[int, str], None]] = None,
) -> Dict[str, object]:
    started_at = _utc_now_iso()
    source_mode = _trading_journal_source_mode()
    local_authoritative = _trading_journal_local_excel_authoritative()
    single_file_mode = _master_journal_single_file_mode()
    include_dropbox = (source_mode in {"dropbox", "both", "auto"}) and not local_authoritative
    include_local = source_mode in {"local", "both", "auto"}
    local_enabled = _local_journal_import_enabled()
    template_result: Dict[str, object] = {"errors": []}
    warnings: List[str] = []

    if include_local and local_enabled and (source_mode == "local" or local_authoritative) and not single_file_mode:
        template_result = _ensure_trading_journal_local_templates()
        for err in template_result.get("errors") or []:
            warnings.append(str(err))

    existing_rows = _get_trading_journal_rows()
    all_rows: Dict[str, Dict[str, object]] = {}
    if not local_authoritative:
        for row in existing_rows:
            if isinstance(row, dict):
                rid = str(row.get("id") or "")
                if rid:
                    all_rows[rid] = dict(row)

    diagnostics = _default_journal_diagnostics()
    diagnostics["dropbox_workbooks_seen"] = 0
    errors: List[Dict[str, str]] = []
    balances: List[Dict[str, object]] = []
    imported_any = False
    imported_rows_total = 0
    bybit_demo_workbook_cleared = False
    bybit_demo_rows_purged = 0

    if single_file_mode:
        pre = _enforce_single_master_journal_xlsx(TRADING_JOURNAL_LOCAL_DIR, cleanup_known_generated=True)
        if not pre.get("ok"):
            msg = "Unknown extra Excel files in journal directory: " + ", ".join(pre.get("unknown_extra_excel_files") or []) + ". Move legacy backups outside journal/. Keep only journal/Trading Journal.xlsx."
            return {"ok": False, "source_mode": "master_journal", "source": "master_journal", "errors": [{"path": str(TRADING_JOURNAL_LOCAL_DIR), "error": msg}], "warnings": warnings, "started_at": started_at, "finished_at": _utc_now_iso()}
        source_payload = read_master_journal_source(_master_journal_path())
        raw_rows = [dict(r) for r in (source_payload.get("items") or []) if isinstance(r, dict)]
        trade_rows = _enrich_trade_row_metrics([r for r in raw_rows if _row_type(r) == "trade"])
        non_trade_rows = [r for r in raw_rows if _row_type(r) != "trade"]
        rows = sorted([*trade_rows, *non_trade_rows], key=_row_sort_dt, reverse=True)
        _set_trading_journal_rows(rows)
        diagnostics["source_mode"] = "master_journal"
        diagnostics["local_dir"] = str(TRADING_JOURNAL_LOCAL_DIR)
        diagnostics["local_workbooks_seen"] = 1 if _master_journal_path().exists() else 0
        _set_trading_journal_diagnostics(diagnostics)
        post = _enforce_single_master_journal_xlsx(TRADING_JOURNAL_LOCAL_DIR, cleanup_known_generated=True)
        if not post.get("ok"):
            msg = "Unknown extra Excel files in journal directory after import: " + ", ".join(post.get("unknown_extra_excel_files") or []) + ". Move legacy backups outside journal/. Keep only journal/Trading Journal.xlsx."
            return {"ok": False, "source_mode": "master_journal", "source": "master_journal", "errors": [{"path": str(TRADING_JOURNAL_LOCAL_DIR), "error": msg}], "warnings": warnings, "started_at": started_at, "finished_at": _utc_now_iso()}
        return {"ok": True, "source_mode": "master_journal", "source": "master_journal", "rows_imported": len(rows), "balances_found": len(source_payload.get("balances") or []), "errors": [], "warnings": warnings, "started_at": started_at, "finished_at": _utc_now_iso(), "diagnostics": diagnostics}

    if include_dropbox:
        try:
            dropbox_result = _import_trading_journal_from_dropbox_excel(progress_cb=progress_cb)
            diagnostics["dropbox_workbooks_seen"] = int(dropbox_result.get("workbooks_seen") or 0)
            errors.extend(dropbox_result.get("errors") or [])
            imported_any = imported_any or bool(dropbox_result.get("rows_imported"))
            imported_rows_total += int(dropbox_result.get("rows_imported") or 0)
            if bool(dropbox_result.get("bybit_demo_workbook_cleared")):
                bybit_demo_workbook_cleared = True
                bybit_demo_rows_purged += int(dropbox_result.get("bybit_demo_rows_purged") or 0)
            rows_now = _get_trading_journal_rows()
            for row in rows_now:
                if isinstance(row, dict):
                    rid = str(row.get("id") or "")
                    if rid:
                        all_rows[rid] = dict(row)
            balances = list(_get_excel_account_balances())
        except Exception as exc:
            errors.append({"file": "", "path": "dropbox", "error": str(exc)})

    local_files = _list_local_trading_journal_workbooks() if (include_local and not single_file_mode) else []
    local_oanda_csvs = _list_local_oanda_history_exports() if include_local else []
    for csv_path in local_oanda_csvs:
        if csv_path not in local_files:
            local_files.append(csv_path)
    diagnostics["local_workbooks_seen"] = len(local_files)
    diagnostics["local_workbook_names"] = [p.name for p in local_files]
    diagnostics["source_mode"] = source_mode
    diagnostics["local_dir"] = str(TRADING_JOURNAL_LOCAL_DIR)
    ignored_local_workbooks: List[str] = []
    if include_local and (not local_enabled) and local_files:
        ignored_local_workbooks = [p.name for p in local_files]
        local_files = []
    requires_xls_engine = [str(p) for p in local_files if p.suffix.lower() == ".xls"]
    if requires_xls_engine:
        try:
            import xlrd as _xlrd  # noqa: F401
        except Exception:
            requirements_path = str((BASE_DIR / "render" / "requirements.txt").resolve())
            warnings.append({
                "code": "MISSING_XLRD_FOR_XLS",
                "message": (
                    "Local .xls journal workbooks require xlrd. "
                    f'Install into the same Python executable that launches the journal: python -m pip install -r "{requirements_path}"'
                ),
                "files": requires_xls_engine,
            })
    local_rows_parsed_total = 0
    local_rows_imported_total = 0
    local_balances: List[Dict[str, object]] = []
    oanda_export_trades_seen = 0
    oanda_export_trades_backfilled = 0
    oanda_export_target_workbook = ""
    oanda_export_source_path = ""
    oanda_export_latest_balance = None
    oanda_export_latest_balance_as_of = None
    oanda_export_account_label = ""
    oanda_export_trades_failed = 0
    oanda_export_append_failed = False
    oanda_export_append_error = ""
    oanda_export_balance_parsed = None
    oanda_export_balance_parsed_as_of = None
    oanda_export_balance_applied = False
    oanda_export_rows_persisted = False
    known_oanda_accounts: set[str] = set()
    try:
        _state_for_mapping = _load_trading_journal_state()
        _ledger_for_mapping = _load_cashflows_for_active_journal_source(
            _state_for_mapping if isinstance(_state_for_mapping, dict) else {}
        )
        for acct in (_ledger_for_mapping or {}).keys():
            label = str(acct or "").strip().upper()
            if label in {"OANDA DEMO", "OANDA LIVE"}:
                known_oanda_accounts.add(label)
    except Exception:
        pass
    for existing in existing_rows:
        label = str((existing or {}).get("account_label") or (existing or {}).get("account") or "").strip().upper()
        if label in {"OANDA DEMO", "OANDA LIVE"}:
            known_oanda_accounts.add(label)
    for wb in local_files:
        base = wb.stem.strip().upper()
        if base in {"OANDA DEMO", "OANDA LIVE"}:
            known_oanda_accounts.add(base)
    for local_file in local_files:
        try:
            local_rows, local_balance = _parse_local_trading_journal_workbook(local_file)
            if isinstance(local_balance, dict) and str(local_balance.get("balance_source") or "").strip().lower() == "oanda_transaction_export_balance":
                oanda_export_balance_parsed = local_balance.get("balance")
                oanda_export_balance_parsed_as_of = local_balance.get("as_of")
            if _is_bybit_demo_workbook_name(local_file.name) and not local_rows:
                current_rows = [r for r in _get_trading_journal_rows() if isinstance(r, dict)]
                kept_rows, purged = _purge_bybit_demo_rows(current_rows)
                _set_trading_journal_rows(kept_rows)
                bybit_demo_workbook_cleared = True
                bybit_demo_rows_purged += purged
            local_kind = "explicit" if local_enabled else "default"
            local_rows_parsed_total += len(local_rows)
            is_oanda_history_csv = local_file.suffix.lower() == ".csv" and "oanda" in local_file.name.lower() and "history" in local_file.name.lower()
            has_oanda_export_rows = any(
                str((r or {}).get("source") or "").strip().lower() == "oanda_transaction_export"
                for r in local_rows
            )
            has_oanda_export_balance = (
                isinstance(local_balance, dict)
                and str(local_balance.get("balance_source") or "").strip().lower() == "oanda_transaction_export_balance"
            )
            mapped_rows_for_state: List[Dict[str, object]] = []
            skip_csv_rows_from_state = False
            if is_oanda_history_csv and (has_oanda_export_rows or has_oanda_export_balance):
                oanda_export_trades_seen += len([r for r in local_rows if str((r or {}).get("source") or "").strip().lower() == "oanda_transaction_export"])
                lower_name = local_file.name.lower()
                mapped_label: Optional[str] = None
                explicit_mode = ""
                try:
                    sidecar_candidates = [local_file.with_suffix(".json")]
                    for candidate in sidecar_candidates:
                        if candidate.exists():
                            meta = _load_json_file(candidate, {})
                            explicit_mode = str((meta or {}).get("account_mode") or "").strip().lower()
                            if explicit_mode in {"demo", "live"}:
                                break
                except Exception:
                    explicit_mode = ""
                if explicit_mode == "demo":
                    mapped_label = "OANDA DEMO"
                elif explicit_mode == "live":
                    mapped_label = "OANDA LIVE"
                elif "demo" in lower_name:
                    mapped_label = "OANDA DEMO"
                elif "live" in lower_name:
                    mapped_label = "OANDA LIVE"
                elif len(known_oanda_accounts) == 1:
                    mapped_label = list(known_oanda_accounts)[0]
                elif len(known_oanda_accounts) > 1:
                    warnings.append("ambiguous_oanda_export_account_mapping")
                    skip_csv_rows_from_state = True
                if mapped_label:
                    mapped_mode = "live" if mapped_label.upper().endswith("LIVE") else "demo"
                    mapped_rows: List[Dict[str, object]] = []
                    for row in local_rows:
                        if str((row or {}).get("source") or "").strip().lower() == "oanda_transaction_export":
                            row["account"] = mapped_mode
                            row["account_label"] = mapped_label
                            mapped_rows.append(row)
                    if mapped_rows:
                        workbook_name = _canonical_local_oanda_workbook_name(mapped_mode)
                        workbook_path = _local_journal_workbook_path(workbook_name)
                        before = _read_excel_sheet_or_empty(workbook_path, "Trades", ["transaction_id"])
                        backfilled = _append_oanda_export_rows_to_local_workbook(mapped_mode, mapped_rows, str(local_file))
                        after = _read_excel_sheet_or_empty(workbook_path, "Trades", ["transaction_id"])
                        before_ids = set(before.get("transaction_id", pd.Series(dtype=str)).fillna("").astype(str))
                        after_ids = set(after.get("transaction_id", pd.Series(dtype=str)).fillna("").astype(str))
                        inserted = len([x for x in after_ids if x and x not in before_ids])
                        oanda_export_trades_backfilled += int(inserted)
                        diagnostics["oanda_export_trades_updated"] = int(backfilled) - int(inserted)
                        oanda_export_target_workbook = _canonical_local_oanda_workbook_name(mapped_mode)
                        oanda_export_source_path = str(local_file)
                        oanda_export_account_label = mapped_label
                        oanda_export_rows_persisted = True
                        oanda_export_balance_applied = True
                        reread_rows, _reread_balance = _parse_local_trading_journal_workbook(workbook_path)
                        mapped_rows_for_state = [r for r in reread_rows if str((r or {}).get("source") or "").strip().lower() in {"local_excel", "excel"}]
                        skip_csv_rows_from_state = True
                    else:
                        oanda_export_trades_failed += len(local_rows)
            for row in local_rows:
                if skip_csv_rows_from_state and str((row or {}).get("source") or "").strip().lower() == "oanda_transaction_export":
                    continue
                if str((row or {}).get("account_label") or "").strip() == "__UNRESOLVED_OANDA_EXPORT__":
                    continue
                rid = str(row.get("id") or "")
                if rid:
                    if str(row.get("source") or "").strip().lower() != "oanda_transaction_export":
                        row["source"] = "local_excel"
                    row["import_source"] = "local_excel"
                    row["_local_import_kind"] = local_kind
                    row["_workbook_source"] = str(local_file)
                    refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
                    refs["local_path"] = str(local_file)
                    refs["workbook_path"] = str(local_file)
                    row["raw_refs"] = refs
                    all_rows[rid] = row
                    local_rows_imported_total += 1
            for row in mapped_rows_for_state:
                rid = str(row.get("id") or "")
                if rid:
                    row["source"] = "local_excel"
                    row["import_source"] = "local_excel"
                    all_rows[rid] = row
                    local_rows_imported_total += 1
            if local_balance:
                if has_oanda_export_balance:
                    oanda_export_latest_balance = local_balance.get("balance")
                    oanda_export_latest_balance_as_of = local_balance.get("as_of")
                if skip_csv_rows_from_state and has_oanda_export_balance:
                    pass
                else:
                    local_balances.append(local_balance)
        except Exception as exc:
            err_payload: Dict[str, object] = {"file": local_file.name, "path": str(local_file), "error": str(exc)}
            if local_file.suffix.lower() == ".csv" and "MISSING_XLRD_FOR_XLS" in str(exc):
                err_payload["code"] = "MISSING_XLRD_FOR_XLS"
                oanda_export_append_failed = True
                oanda_export_append_error = "MISSING_XLRD_FOR_XLS"
                oanda_export_balance_applied = False
                oanda_export_rows_persisted = False
            if local_file.suffix.lower() == ".xls" and "xlrd" in str(exc).lower():
                err_payload["code"] = "MISSING_XLRD_FOR_XLS"
                requirements_path = str((BASE_DIR / "render" / "requirements.txt").resolve())
                err_payload["message"] = (
                    "Local .xls journal workbooks require xlrd. "
                    f'Install into the same Python executable that launches the journal: python -m pip install -r "{requirements_path}"'
                )
            errors.append(err_payload)
    imported_any = imported_any or local_rows_imported_total > 0
    imported_rows_total += int(local_rows_imported_total)
    diagnostics["local_rows_parsed_total"] = int(local_rows_parsed_total)
    diagnostics["local_rows_imported_total"] = int(local_rows_imported_total)
    diagnostics["oanda_export_trades_seen"] = int(oanda_export_trades_seen)
    diagnostics["oanda_export_trades_backfilled"] = int(oanda_export_trades_backfilled)
    diagnostics["oanda_export_target_workbook"] = oanda_export_target_workbook
    diagnostics["oanda_export_source_path"] = oanda_export_source_path
    diagnostics["oanda_export_latest_balance"] = oanda_export_latest_balance
    diagnostics["oanda_export_latest_balance_as_of"] = oanda_export_latest_balance_as_of
    diagnostics["oanda_export_account_label"] = oanda_export_account_label
    diagnostics["oanda_export_trades_failed"] = int(oanda_export_trades_failed)
    diagnostics["oanda_export_append_failed"] = bool(oanda_export_append_failed)
    diagnostics["oanda_export_append_error"] = oanda_export_append_error
    diagnostics["oanda_export_balance_parsed"] = oanda_export_balance_parsed
    diagnostics["oanda_export_balance_parsed_as_of"] = oanda_export_balance_parsed_as_of
    diagnostics["oanda_export_balance_applied"] = bool(oanda_export_balance_applied)
    diagnostics["oanda_export_rows_persisted"] = bool(oanda_export_rows_persisted)
    diagnostics["oanda_export_failure_blocks_balance_update"] = bool(oanda_export_append_failed)

    deduped_rows, dedupe_details = _dedupe_trade_rows_by_execution(list(all_rows.values()))
    dedupe_groups = int(dedupe_details.get("duplicate_execution_groups_removed") or 0)
    duplicate_rows_dropped = int(dedupe_details.get("duplicate_execution_rows_removed") or 0)
    source_duplicate_rows_dropped = duplicate_rows_dropped
    diagnostics["ambiguous_duplicate_execution_groups"] = dedupe_details.get("ambiguous_duplicate_execution_groups") or []
    final_rows = sorted(deduped_rows, key=_row_sort_dt, reverse=True)
    final_rows, sanitize_stats = _sanitize_bybit_demo_rows(final_rows)
    pruned_source_counts: Dict[str, int] = {}
    non_local_rows_pruned = 0
    stale_rows_removed = 0
    if local_authoritative:
        for row in existing_rows:
            if not isinstance(row, dict):
                continue
            src = str(row.get("source") or "unknown").strip().lower()
            if src != "local_excel":
                non_local_rows_pruned += 1
                pruned_source_counts[src or "unknown"] = pruned_source_counts.get(src or "unknown", 0) + 1
        _set_trading_journal_rows(final_rows)
        stale_rows_removed = max(0, len(existing_rows) - len(final_rows))
        state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
        if isinstance(state, dict):
            broker_balances = state.get("broker_account_balances")
            if isinstance(broker_balances, list):
                state["broker_account_balances"] = []
            if local_balances:
                state["excel_account_balances"] = local_balances
            _save_json_file(TRADING_JOURNAL_STATE_PATH, state)
    elif final_rows:
        _set_trading_journal_rows(final_rows)
        if local_balances:
            state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
            excel_bal = state.get("excel_account_balances") if isinstance(state, dict) else []
            merged_balances = [*([b for b in excel_bal if isinstance(b, dict)] if isinstance(excel_bal, list) else []), *local_balances]
            state["excel_account_balances"] = merged_balances
            _save_json_file(TRADING_JOURNAL_STATE_PATH, state)
            balances = merged_balances
    elif not local_authoritative:
        errors.append({"file": "", "path": "sources", "error": "Imported 0 rows; keeping existing journal data."})

    persisted_rows = [row for row in _get_trading_journal_rows() if isinstance(row, dict)]
    visible_rows = [row for row in persisted_rows if _is_visible_trading_journal_row(row)]
    visible_trade_rows = [row for row in visible_rows if _row_type(row) == "trade"]
    stats_trade_rows = [row for row in visible_trade_rows if not _is_test_trade_row(row)]
    rows_by_source: Dict[str, int] = defaultdict(int)
    rows_by_asset_class: Dict[str, int] = defaultdict(int)
    rows_by_account: Dict[str, int] = defaultdict(int)
    for row in visible_rows:
        rows_by_source[str(row.get("source") or "unknown")] += 1
        rows_by_asset_class[str(row.get("asset_class") or "unknown")] += 1
        rows_by_account[str(row.get("account_label") or row.get("account") or "unknown")] += 1
    quarantined_rows = sum(
        1
        for row in persisted_rows
        if str(row.get("status") or "").strip().lower() == "invalid_time_order"
    )
    excluded_bybit_demo_rows = sum(1 for row in persisted_rows if _exclude_bybit_demo_row(row))
    excluded_rows_total = max(0, len(persisted_rows) - len(visible_rows))
    excluded_test_trade_rows = sum(1 for row in visible_trade_rows if _is_test_trade_row(row))
    blank_pnl_trade_rows = sum(1 for row in visible_trade_rows if _row_pnl(row) is None)
    cashflow_rows_total = sum(1 for row in visible_rows if _row_type(row) == "cashflow")
    diagnostics.update(
        {
            "rows_total": len(visible_rows),
            "raw_workbook_rows_total": imported_rows_total,
            "visible_trade_rows_total": len(visible_trade_rows),
            "stats_included_trade_rows_total": len(stats_trade_rows),
            "excluded_test_trade_rows": excluded_test_trade_rows,
            "quarantined_invalid_time_rows": int(sanitize_stats.get("quarantined_invalid_time", 0)) + quarantined_rows,
            "workbook_invalid_time_order_rows": int(sanitize_stats.get("workbook_invalid_time_order", 0)),
            "blank_pnl_trade_rows": blank_pnl_trade_rows,
            "cashflow_rows_total": cashflow_rows_total,
            "raw_rows_total": len(persisted_rows),
            "visible_rows_total": len(visible_rows),
            "excluded_rows_total": excluded_rows_total,
            "excluded_bybit_demo_rows": excluded_bybit_demo_rows,
            "rows_by_source": dict(rows_by_source),
            "rows_by_account": dict(rows_by_account),
            "rows_by_asset_class": dict(rows_by_asset_class),
            "duplicate_rows_dropped": duplicate_rows_dropped,
            "source_duplicate_rows_dropped": source_duplicate_rows_dropped,
            "dedupe_groups": dedupe_groups,
            "ignored_local_workbooks": ignored_local_workbooks,
            "quarantined_rows": quarantined_rows,
            "errors": errors,
            "authoritative_source": "local_excel" if local_authoritative else "",
            "source_enforcement_ok": (True if not local_authoritative else all(str(r.get("source") or "").lower() == "local_excel" for r in persisted_rows if _row_type(r) == "trade")),
            "non_local_rows_pruned": non_local_rows_pruned,
            "non_excel_rows_removed": non_local_rows_pruned,
            "stale_rows_removed": stale_rows_removed if local_authoritative else 0,
            "unmatched_manual_rows_ignored": pruned_source_counts.get("manual", 0),
            "workbook_rows_imported": imported_rows_total,
            "pruned_source_counts": pruned_source_counts,
            "bybit_demo_workbook_cleared": bybit_demo_workbook_cleared,
            "bybit_demo_rows_purged": bybit_demo_rows_purged,
            "last_sync": {
                "source_mode": source_mode,
                "updated_at": _utc_now_iso(),
                "ok": bool(imported_any) and not bool(oanda_export_append_failed),
                "balances_found": len(balances),
                "local_import_enabled": local_enabled,
            },
        }
    )
    _set_trading_journal_diagnostics(diagnostics)
    snapshot_payload: Optional[Dict[str, object]] = None
    snapshot_error: Optional[str] = None
    try:
        snapshot_payload = _build_trading_journal_view_snapshot(force=True)
    except Exception as exc:
        snapshot_error = f"Snapshot build failed after import: {exc}"
        warnings.append(snapshot_error)
    if snapshot_payload is not None:
        try:
            _persist_trading_journal_sqlite(
                snapshot_payload,
                {
                    "started_at": started_at,
                    "source_mode": source_mode,
                    "workbooks_scanned": int(diagnostics["local_workbooks_seen"]) + int(diagnostics["dropbox_workbooks_seen"]),
                    "workbooks_changed": int(imported_rows_total > 0),
                    "rows_imported": imported_rows_total,
                    "cashflow_rows_loaded": int(sum(1 for r in (snapshot_payload.get("items") or []) if _row_type(r) == "cashflow")),
                    "warnings": warnings,
                    "errors": errors,
                },
            )
        except Exception as exc:
            snapshot_error = f"Snapshot persistence failed after import: {exc}"
            warnings.append(snapshot_error)
    ok_after_snapshot = bool(imported_any) and not snapshot_error
    if oanda_export_append_failed:
        ok_after_snapshot = False
    if local_authoritative and not imported_any:
        ok_after_snapshot = False
    oanda_failure_message = (
        f"OANDA export parsed but not written to {oanda_export_target_workbook or 'canonical workbook'}: "
        f"{oanda_export_append_error or 'append_failed'}."
    )
    return {
        "ok": ok_after_snapshot,
        "message": (
            snapshot_error
            if snapshot_error
            else (
                oanda_failure_message
                if oanda_export_append_failed
                else ("Done" if imported_any
                else (
                    "No local Excel trade rows imported; local Excel is authoritative, stale journal rows were cleared."
                    if local_authoritative
                    else "No rows imported from configured sources; existing journal data was retained."
                ))
            )
        ),
        "source_mode": source_mode,
        "rows_imported": imported_rows_total,
        "cashflow_rows_loaded": int(cashflow_rows_total),
        "balances_found": len(balances),
        "templates_created": {
            "cashflow_template_created": bool(template_result.get("cashflow_template_created")),
            "trade_history_template_created": bool(template_result.get("trade_history_template_created")),
            "demo_workbook_created": bool(template_result.get("demo_workbook_created")),
        },
        "local_workbooks_seen": diagnostics["local_workbooks_seen"],
        "local_workbook_names": diagnostics.get("local_workbook_names") if isinstance(diagnostics.get("local_workbook_names"), list) else [],
        "workbooks_scanned": int(diagnostics["local_workbooks_seen"]) + int(diagnostics["dropbox_workbooks_seen"]),
        "workbooks_changed": int(imported_rows_total > 0),
        "dropbox_workbooks_seen": diagnostics["dropbox_workbooks_seen"],
        "duplicate_rows_dropped": duplicate_rows_dropped,
        "source_duplicate_rows_dropped": source_duplicate_rows_dropped,
        "dedupe_groups": dedupe_groups,
        "ignored_local_workbooks": ignored_local_workbooks,
        "errors": errors,
        "warnings": warnings,
        "snapshot_generated": snapshot_payload is not None,
        "snapshot_error": snapshot_error,
        "diagnostics": diagnostics,
    }
def _get_excel_account_balances() -> List[Dict[str, object]]:
    state = _load_json_file(TRADING_JOURNAL_STATE_PATH, {})
    items = state.get("excel_account_balances") if isinstance(state, dict) else []
    return items if isinstance(items, list) else []


def _to_float(value: object) -> Optional[float]:
    try:
        if value is None:
            return None
        if pd.isna(value):
            return None
        if isinstance(value, str) and not value.strip():
            return None
        num = float(value)
        if not math.isfinite(num):
            return None
        return num
    except (TypeError, ValueError):
        return None


def _positive_float(value: object) -> Optional[float]:
    parsed = _to_float(value)
    if parsed is not None and math.isfinite(parsed) and parsed > 0:
        return parsed
    return None


def _oanda_loss_quote_home_factor(payload: object) -> Optional[float]:
    value, _source = _oanda_loss_quote_home_factor_with_source(payload)
    return value


def _oanda_loss_quote_home_factor_with_source(
    payload: object,
    *,
    source_prefix: str = "",
) -> Tuple[Optional[float], Optional[str]]:
    if not isinstance(payload, dict):
        return None, None
    factors = payload.get("homeConversionFactors")
    if isinstance(factors, dict):
        loss_quote_home = factors.get("lossQuoteHome") or factors.get("loss_quote_home")
        if isinstance(loss_quote_home, dict):
            value = _positive_float(loss_quote_home.get("factor"))
            if value is not None:
                return value, f"{source_prefix}homeConversionFactors.lossQuoteHome.factor"
        value = _positive_float(factors.get("lossQuoteHomeFactor") or factors.get("loss_quote_home_factor"))
        if value is not None:
            return value, f"{source_prefix}homeConversionFactors.lossQuoteHomeFactor"
    value = _positive_float(payload.get("lossQuoteHomeConversionFactor"))
    if value is not None:
        return value, f"{source_prefix}lossQuoteHomeConversionFactor"
    return None, None


def _oanda_abs_charge(value: object) -> float:
    parsed = _to_float(value)
    return abs(parsed) if parsed is not None else 0.0


def _normalize_journal_profit_fields(row: Dict[str, object]) -> Dict[str, object]:
    normalized = dict(row)
    net_profit = _to_float(normalized.get("net_profit"))
    realized_pnl = _to_float(normalized.get("realized_pnl"))
    if net_profit is None and realized_pnl is not None:
        normalized["net_profit"] = realized_pnl
    if realized_pnl is None and net_profit is not None:
        normalized["realized_pnl"] = net_profit
    return normalized


def _row_pnl(row: Dict[str, object]) -> Optional[float]:
    net_profit = _to_float(row.get("net_profit"))
    if net_profit is not None:
        return net_profit
    return _to_float(row.get("realized_pnl"))


def _row_pnl_currency(row: Dict[str, object]) -> str:
    ccy = str(
        row.get("realized_pnl_currency")
        or row.get("currency")
        or row.get("account_currency")
        or row.get("balance_after_trade_currency")
        or ""
    ).strip().upper()
    if ccy:
        return ccy
    return _infer_account_currency(str(row.get("account_label") or row.get("account") or "")).strip().upper()


def _ms_to_iso(value: object) -> Optional[str]:
    try:
        ms = int(float(value))
    except (TypeError, ValueError):
        return None
    if ms <= 0:
        return None
    return datetime.fromtimestamp(ms / 1000, tz=timezone.utc).isoformat()

def _ts_to_iso(value: object) -> Optional[str]:
    try:
        sec = int(float(value))
    except (TypeError, ValueError):
        return None
    if sec <= 0:
        return None
    return datetime.fromtimestamp(sec, tz=timezone.utc).isoformat()


def _epoch_or_iso_to_iso(value: object) -> Optional[str]:
    if value in (None, ""):
        return None
    if isinstance(value, (int, float)):
        raw = float(value)
        if raw <= 0:
            return None
        if raw >= 1_000_000_000_000:
            return datetime.fromtimestamp(raw / 1000.0, tz=timezone.utc).isoformat()
        if raw >= 1_000_000_000:
            return datetime.fromtimestamp(raw, tz=timezone.utc).isoformat()
    text = str(value).strip()
    if not text:
        return None
    numeric = _to_float(text)
    if numeric is not None:
        return _epoch_or_iso_to_iso(numeric)
    try:
        if re.search(r"\b\d{1,2}/\d{1,2}/\d{4}\b", text):
            return pd.to_datetime(text, utc=True, dayfirst=True).isoformat()
        return pd.to_datetime(text, utc=True).isoformat()
    except Exception:
        return None


def _journal_rows_from_bybit_execution(entry: Dict[str, object]) -> List[Dict[str, object]]:
    account = str(entry.get("account") or "unknown").strip().lower()
    category = str(entry.get("category") or "").strip().lower()
    symbol = str(entry.get("symbol") or "").strip().upper()
    order_id = str(entry.get("orderId") or "")
    exec_id = str(entry.get("execId") or "")
    if not symbol or not order_id or not exec_id:
        return []
    qty = _to_float(entry.get("execQty")) or 0.0
    exec_price = _to_float(entry.get("execPrice"))
    exec_fee = _to_float(entry.get("execFee")) or 0.0
    exec_pnl = _to_float(entry.get("execPnl"))
    exec_time_raw = _to_float(entry.get("execTime"))
    close_time = None
    if exec_time_raw:
        close_time = datetime.fromtimestamp(exec_time_raw / 1000, tz=timezone.utc).isoformat()
    side = str(entry.get("side") or "")
    timeframe = _normalize_timeframe(entry.get("timeframe"))
    is_test_trade = _normalize_test_trade_flag(
        entry.get("is_test_trade", entry.get("test_trade", entry.get("test")))
    )
    setup = _safe_normalize_setup(entry.get("setup"))
    pattern = _safe_normalize_pattern(entry.get("pattern"))
    ema = str(entry.get("ema") or "").strip()
    vwap = str(entry.get("vwap") or "").strip()
    aths_atls = str(entry.get("aths_atls") or "").strip()
    round_number = str(entry.get("round_number") or "").strip()
    if not timeframe or is_test_trade is None or not setup or not pattern or not ema or not vwap or not aths_atls or not round_number:
        ctx = _lookup_trade_context_for_journal_row(
            {"raw_refs": {"orderId": order_id, "orderLinkId": entry.get("orderLinkId")}}
        )
        if isinstance(ctx, dict):
            if not timeframe:
                timeframe = _normalize_timeframe(ctx.get("timeframe"))
            if is_test_trade is None:
                is_test_trade = _normalize_test_trade_flag(ctx.get("is_test_trade"))
            if not setup:
                setup = _safe_normalize_setup(ctx.get("setup"))
            if not pattern:
                pattern = _safe_normalize_pattern(ctx.get("pattern"))
            if not ema:
                ema = str(ctx.get("ema") or "").strip()
            if not vwap:
                vwap = str(ctx.get("vwap") or "").strip()
            if not aths_atls:
                aths_atls = str(ctx.get("aths_atls") or "").strip()
            if not round_number:
                round_number = str(ctx.get("round_number") or "").strip()
    if exec_pnl in (None, 0.0):
        return []
    return [
        _normalize_journal_profit_fields({
            "id": f"bybit:{account}:{category}:{symbol}:{order_id}:{exec_id}",
            "source": "bybit",
            "account": account,
            "account_label": f"Bybit {account.title()}",
            "asset_class": "crypto",
            "symbol": symbol,
            "side": side.title() if side else "",
            "status": "closed",
            "open_time": close_time,
            "close_time": close_time,
            "entry_price": exec_price,
            "exit_price": exec_price,
            "qty": qty,
            "qty_unit": "native",
            "notional_usd": (exec_price or 0.0) * qty,
            "commission": exec_fee,
            "commission_currency": "USDT",
            "fees": exec_fee,
            "fee_currency": "USDT",
            "realized_pnl": exec_pnl,
            "net_profit": exec_pnl,
            "realized_pnl_currency": str(entry.get("currency") or "USDT"),
            "strategy_tag": "",
            "notes": "",
            "timeframe": timeframe,
            "is_test_trade": is_test_trade,
            "setup": setup,
            "pattern": pattern,
            "ema": ema,
            "vwap": vwap,
            "aths_atls": aths_atls,
            "round_number": round_number,
            "metrics": {k: v for k, v in {"timeframe": timeframe, "is_test_trade": is_test_trade}.items() if v not in ("", None)},
            "raw_refs": {"orderId": order_id, "execIds": [exec_id]},
        })
    ]


def _journal_rows_from_oanda_order_fill(entry: Dict[str, object]) -> List[Dict[str, object]]:
    account = str(entry.get("account") or "unknown").strip().lower()
    tx_id = str(entry.get("id") or "").strip()
    symbol = str(entry.get("instrument") or "").strip().upper()
    if not tx_id or not symbol:
        return []
    legs = _OANDA_OPEN_TRADE_LEGS.setdefault(account, {})
    close_time = _to_journal_display_iso(entry.get("time")) or str(entry.get("time") or "")
    tx_order_id = str(entry.get("orderID") or "").strip()
    tx_id = str(entry.get("id") or "").strip()

    context_cache: Dict[Tuple[str, str, str, str], Optional[Dict[str, object]]] = {}
    contexts = _load_trade_contexts()
    def _context_registry_key(trade_id: Optional[str] = None) -> str:
        return _stable_registry_key([account, tx_id, tx_order_id, trade_id or "", symbol])

    def _resolve_context_for_fill(trade_id: Optional[str] = None, warn: bool = True) -> Optional[Dict[str, object]]:
        warning_key = (account, tx_id, tx_order_id, str(trade_id or "").strip())
        if warning_key in context_cache:
            return context_cache[warning_key]
        if not contexts:
            unresolved_key = _context_registry_key(trade_id)
            should_warn, _ = _update_unresolved_registry(
                family="oanda_context",
                key=unresolved_key,
                details={"reason": "missing"},
                resolved=False,
            )
            runtime_key = f"missing:{unresolved_key}"
            if (should_warn or runtime_key not in _OANDA_CONTEXT_WARNED_RUNTIME) and warn:
                BYBIT_LOGGER.warning(
                    "OANDA_CONTEXT_MISSING account=%s symbol=%s tx_id=%s order_id=%s trade_id=%s",
                    account,
                    symbol,
                    tx_id,
                    tx_order_id,
                    trade_id or "",
                )
                _OANDA_CONTEXT_WARNED_RUNTIME.add(runtime_key)
            context_cache[warning_key] = None
            return None
        refs = {"orderId": tx_order_id, "transactionId": tx_id}
        if trade_id:
            refs["tradeId"] = trade_id
        ctx = _lookup_trade_context_for_journal_row({"raw_refs": refs})
        if isinstance(ctx, dict):
            _update_unresolved_registry(
                family="oanda_context",
                key=_context_registry_key(trade_id),
                details={"status": "resolved"},
                resolved=True,
                resolution_source="direct_refs",
            )
            context_cache[warning_key] = ctx
            return ctx
        side_hint = _normalize_side_for_comparison("buy" if (_to_float(entry.get("units")) or 0.0) >= 0 else "sell")
        open_leg = legs.get(str(trade_id or "").strip()) if trade_id else None
        if isinstance(open_leg, dict) and str(open_leg.get("symbol") or "").strip().upper() != symbol:
            open_leg = None
        if isinstance(open_leg, dict):
            open_refs = {
                "orderId": open_leg.get("order_id"),
                "transactionId": open_leg.get("transaction_id"),
                "tradeId": trade_id,
            }
            ctx = _lookup_trade_context_for_journal_row({"raw_refs": open_refs})
            if isinstance(ctx, dict):
                _update_unresolved_registry(
                    family="oanda_context",
                    key=_context_registry_key(trade_id),
                    details={"status": "resolved"},
                    resolved=True,
                    resolution_source="open_leg_refs",
                )
                context_cache[warning_key] = ctx
                return ctx
        ctx = _lookup_trade_context_by_market_window(
            {
                "broker": "oanda",
                "account": account,
                "instrument": symbol,
                "side": side_hint,
                "close_time": close_time,
            },
            include_inactive=True,
            max_window_seconds=6 * 60 * 60,
        )
        if isinstance(ctx, dict):
            persisted = _upsert_trade_context(
                {
                    "broker": "oanda",
                    "account": account,
                    "instrument": symbol,
                    "side": ctx.get("side") or side_hint,
                    "status": ctx.get("status") or "ACTIVE",
                    "order_id": tx_order_id or ctx.get("order_id"),
                    "trade_id": trade_id or ctx.get("trade_id"),
                    "transaction_id": tx_id or ctx.get("transaction_id"),
                    "timeframe": _normalize_timeframe(ctx.get("timeframe")),
                    "stop_loss": ctx.get("stop_loss"),
                    "take_profit": ctx.get("take_profit"),
                }
            )
            _update_unresolved_registry(
                family="oanda_context",
                key=_context_registry_key(trade_id),
                details={"status": "resolved"},
                resolved=True,
                resolution_source="market_window",
            )
            context_cache[warning_key] = persisted
            return persisted

        candidates = []
        for item in contexts:
            if str(item.get("broker") or "").strip().lower() != "oanda":
                continue
            if str(item.get("account") or "").strip().lower() != account:
                continue
            if str(item.get("instrument") or "").strip().upper() != symbol:
                continue
            if side_hint and _normalize_side_for_comparison(item.get("side")) not in {"", side_hint}:
                continue
            refs_hit = (
                (tx_order_id and str(item.get("order_id") or "").strip() == tx_order_id)
                or (trade_id and str(item.get("trade_id") or "").strip() == str(trade_id).strip())
                or (tx_id and str(item.get("transaction_id") or "").strip() == tx_id)
            )
            has_ctx_refs = bool(
                str(item.get("order_id") or "").strip()
                or str(item.get("trade_id") or "").strip()
                or str(item.get("transaction_id") or "").strip()
            )
            if refs_hit or not has_ctx_refs or not (tx_order_id or trade_id or tx_id):
                candidates.append(item)
        if len(candidates) == 1:
            persisted = _upsert_trade_context(
                {
                    "broker": "oanda",
                    "account": account,
                    "instrument": symbol,
                    "side": candidates[0].get("side") or side_hint,
                    "status": candidates[0].get("status") or "ACTIVE",
                    "order_id": tx_order_id or candidates[0].get("order_id"),
                    "trade_id": trade_id or candidates[0].get("trade_id"),
                    "transaction_id": tx_id or candidates[0].get("transaction_id"),
                    "timeframe": _normalize_timeframe(candidates[0].get("timeframe")),
                    "stop_loss": candidates[0].get("stop_loss"),
                    "take_profit": candidates[0].get("take_profit"),
                }
            )
            _update_unresolved_registry(
                family="oanda_context",
                key=_context_registry_key(trade_id),
                details={"status": "resolved"},
                resolved=True,
                resolution_source="cross_link_inference",
            )
            context_cache[warning_key] = persisted
            return persisted
        unresolved_key = _context_registry_key(trade_id)
        if len(candidates) > 1:
            should_warn, _ = _update_unresolved_registry(
                family="oanda_context",
                key=unresolved_key,
                details={"reason": "ambiguous", "candidates": len(candidates)},
                resolved=False,
            )
            runtime_key = f"ambiguous:{unresolved_key}"
            if (should_warn or runtime_key not in _OANDA_CONTEXT_WARNED_RUNTIME) and warn:
                BYBIT_LOGGER.warning(
                    "OANDA_CONTEXT_AMBIGUOUS account=%s symbol=%s side=%s tx_id=%s order_id=%s trade_id=%s candidates=%s",
                    account,
                    symbol,
                    side_hint,
                    tx_id,
                    tx_order_id,
                    trade_id or "",
                    len(candidates),
                )
                _OANDA_CONTEXT_WARNED_RUNTIME.add(runtime_key)
        else:
            should_warn, _ = _update_unresolved_registry(
                family="oanda_context",
                key=unresolved_key,
                details={"reason": "missing"},
                resolved=False,
            )
            runtime_key = f"missing:{unresolved_key}"
            if (should_warn or runtime_key not in _OANDA_CONTEXT_WARNED_RUNTIME) and warn:
                BYBIT_LOGGER.warning(
                    "OANDA_CONTEXT_MISSING account=%s symbol=%s tx_id=%s order_id=%s trade_id=%s",
                    account,
                    symbol,
                    tx_id,
                    tx_order_id,
                    trade_id or "",
                )
                _OANDA_CONTEXT_WARNED_RUNTIME.add(runtime_key)
        context_cache[warning_key] = None
        return None

    trade_opened = entry.get("tradeOpened") if isinstance(entry.get("tradeOpened"), dict) else None
    if isinstance(trade_opened, dict):
        trade_id = str(trade_opened.get("tradeID") or "").strip()
        opened_units = _to_float(trade_opened.get("units"))
        trade_ctx = _resolve_context_for_fill(trade_id)
        if trade_id and opened_units not in (None, 0):
            opening_factor, opening_factor_source = _oanda_loss_quote_home_factor_with_source(
                trade_opened,
                source_prefix="tradeOpened.",
            )
            if opening_factor is None:
                opening_factor, opening_factor_source = _oanda_loss_quote_home_factor_with_source(entry)
            legs[trade_id] = {
                "open_time": close_time,
                "entry_price": _to_float(trade_opened.get("price")) or _to_float(entry.get("price")),
                "units": opened_units,
                "side": "Buy" if opened_units >= 0 else "Sell",
                "symbol": symbol,
                "account": account,
                "timeframe": _normalize_timeframe((trade_ctx or {}).get("timeframe")),
                "calculation_context_id": (trade_ctx or {}).get("calculation_context_id") or (trade_ctx or {}).get("context_id"),
                "is_test_trade": _normalize_test_trade_flag((trade_ctx or {}).get("is_test_trade")),
                "stop_loss": (trade_ctx or {}).get("stop_loss"),
                "take_profit": (trade_ctx or {}).get("take_profit"),
                "order_id": tx_order_id,
                "transaction_id": tx_id,
                "original_loss_conversion_factor": opening_factor,
                "opening_loss_conversion_factor": opening_factor,
                "original_loss_conversion_factor_source": opening_factor_source,
                "original_loss_conversion_factor_time": close_time if opening_factor is not None else None,
                "original_open_transaction_id": tx_id if opening_factor is not None else None,
                "homeConversionFactors": (
                    trade_opened.get("homeConversionFactors")
                    or entry.get("homeConversionFactors")
                ),
                "plHomeConversionFactors": (
                    trade_opened.get("plHomeConversionFactors")
                    or entry.get("plHomeConversionFactors")
                ),
            }

    close_legs: List[Dict[str, object]] = []
    trades_closed = entry.get("tradesClosed")
    if isinstance(trades_closed, list):
        close_legs.extend(item for item in trades_closed if isinstance(item, dict))
    trade_reduced = entry.get("tradeReduced")
    if isinstance(trade_reduced, dict):
        close_legs.append(trade_reduced)
    if not close_legs:
        _persist_oanda_fill_state()
        return []

    base_ctx = _resolve_context_for_fill(None, warn=(len(close_legs) > 1))
    timeframe = _normalize_timeframe(entry.get("timeframe")) or _normalize_timeframe((base_ctx or {}).get("timeframe"))
    base_is_test_trade = _normalize_test_trade_flag(
        entry.get("is_test_trade", entry.get("test_trade", entry.get("test")))
    )
    if base_is_test_trade is None:
        base_is_test_trade = _normalize_test_trade_flag((base_ctx or {}).get("is_test_trade"))
    stop_loss = (base_ctx or {}).get("stop_loss")
    take_profit = (base_ctx or {}).get("take_profit")
    rows: List[Dict[str, object]] = []
    total_close_units = sum(abs(_to_float(item.get("units")) or 0.0) for item in close_legs)
    close_count = max(len(close_legs), 1)
    api_commission_total = _oanda_abs_charge(entry.get("commission"))
    api_gsl_fee_total = _oanda_abs_charge(entry.get("guaranteedExecutionFee"))
    api_gsl_premium_total = _oanda_abs_charge(entry.get("guaranteedExecutionPremium"))
    api_other_charge_total = sum(
        _oanda_abs_charge(entry.get(key))
        for key in ("otherCharge", "otherCharges", "otherFee", "otherFees", "tradingCharge", "tradingCharges")
    )
    for idx, close_leg in enumerate(close_legs):
        trade_id = str(close_leg.get("tradeID") or "").strip()
        leg_units = abs(_to_float(close_leg.get("units")) or 0.0)
        open_leg = legs.get(trade_id) if trade_id else None
        if isinstance(open_leg, dict) and str(open_leg.get("symbol") or "").strip().upper() != symbol:
            open_leg = None
        leg_ctx = _resolve_context_for_fill(trade_id) or base_ctx
        entry_price = _to_float((open_leg or {}).get("entry_price"))
        open_time = str((open_leg or {}).get("open_time") or "") or None
        side = str((open_leg or {}).get("side") or ("Buy" if (_to_float(entry.get("units")) or 0.0) >= 0 else "Sell"))
        row_timeframe = _normalize_timeframe((open_leg or {}).get("timeframe")) or timeframe or _normalize_timeframe((leg_ctx or {}).get("timeframe"))
        row_stop_loss = (open_leg or {}).get("stop_loss") or stop_loss or (leg_ctx or {}).get("stop_loss")
        row_take_profit = (open_leg or {}).get("take_profit") or take_profit or (leg_ctx or {}).get("take_profit")
        row_is_test_trade = _normalize_test_trade_flag((open_leg or {}).get("is_test_trade"))
        if row_is_test_trade is None:
            row_is_test_trade = _normalize_test_trade_flag((leg_ctx or {}).get("is_test_trade"))
        if row_is_test_trade is None:
            row_is_test_trade = base_is_test_trade
        exit_price = _to_float(close_leg.get("price")) or _to_float(entry.get("price"))
        gross_realized_pl = _to_float(close_leg.get("realizedPL")) or 0.0
        charge_share = (leg_units / total_close_units) if total_close_units > 0 else (1.0 / close_count)
        financing = next(
            (
                candidate
                for key in ("financing", "funding", "swap")
                if (candidate := _to_float(close_leg.get(key))) is not None
            ),
            None,
        )
        if financing is None:
            transaction_financing = next(
                (
                    candidate
                    for key in ("financing", "funding", "swap")
                    if (candidate := _to_float(entry.get(key))) is not None
                ),
                0.0,
            )
            financing = transaction_financing * charge_share
        commission_charge = (api_commission_total * charge_share) + _oanda_abs_charge(close_leg.get("commission"))
        gsl_fee_charge = (api_gsl_fee_total * charge_share) + _oanda_abs_charge(close_leg.get("guaranteedExecutionFee"))
        gsl_premium_charge = (api_gsl_premium_total * charge_share) + _oanda_abs_charge(close_leg.get("guaranteedExecutionPremium"))
        other_charge = (api_other_charge_total * charge_share) + sum(
            _oanda_abs_charge(close_leg.get(key))
            for key in ("otherCharge", "otherCharges", "otherFee", "otherFees", "tradingCharge", "tradingCharges")
        )
        broker_fees = commission_charge + gsl_fee_charge + gsl_premium_charge + other_charge
        displayed_commission = broker_fees + abs(financing)
        net_profit = gross_realized_pl + financing - broker_fees
        spread_cost = abs(_to_float(entry.get("halfSpreadCost")) or 0.0)
        home_conversion_factors = (open_leg or {}).get("homeConversionFactors")
        pl_home_conversion_factors = (open_leg or {}).get("plHomeConversionFactors")
        opening_factor = _positive_float((open_leg or {}).get("original_loss_conversion_factor"))
        opening_factor_source = (open_leg or {}).get("original_loss_conversion_factor_source")
        if opening_factor is None and isinstance(open_leg, dict):
            opening_factor, opening_factor_source = _oanda_loss_quote_home_factor_with_source(
                open_leg,
                source_prefix="open_leg.",
            )
        opening_factor_time = (open_leg or {}).get("original_loss_conversion_factor_time")
        open_transaction_id = (open_leg or {}).get("original_open_transaction_id") or (open_leg or {}).get("transaction_id")
        row_id_suffix = trade_id or f"{tx_id}:{idx}"
        row: Dict[str, object] = {
            "id": f"oanda:{account}:{symbol}:{row_id_suffix}:close",
            "source": "oanda",
            "account": account,
            "account_label": f"OANDA {account.title()}",
            "asset_class": "forex",
            "symbol": symbol,
            "side": side,
            "status": "closed",
            "open_time": open_time,
            "close_time": close_time,
            "entry_price": entry_price,
            "exit_price": exit_price,
            "qty": leg_units / 100000.0,
            "qty_raw": leg_units,
            "qty_unit": "lots",
            "notional_usd": None,
            "swap": financing or None,
            "commission": displayed_commission or None,
            "commission_currency": "AUD",
            "fees": displayed_commission or None,
            "fee_currency": "AUD",
            "realized_pnl": net_profit,
            "net_profit": net_profit,
            "realized_pnl_currency": str(entry.get("accountCurrency") or ""),
            "balance_after_trade": _to_float(entry.get("accountBalance")),
            "strategy_tag": "",
            "notes": "" if entry_price is not None and open_time else "partial_oanda_close_missing_open_leg",
            "timeframe": row_timeframe,
            "stop_loss": row_stop_loss,
            "take_profit": row_take_profit,
            "is_test_trade": row_is_test_trade,
            "original_loss_conversion_factor": opening_factor,
            "opening_loss_conversion_factor": opening_factor,
            "original_loss_conversion_factor_source": opening_factor_source,
            "original_loss_conversion_factor_time": opening_factor_time,
            "original_open_transaction_id": open_transaction_id,
            "oanda_open_conversion_rate": opening_factor,
            "metrics": {
                k: v
                for k, v in {
                    "timeframe": row_timeframe,
                    "is_test_trade": row_is_test_trade,
                    "oanda_api_realized_pl": gross_realized_pl,
                    "oanda_api_financing": financing,
                    "oanda_half_spread_cost": spread_cost or None,
                    "oanda_actual_commission_total": broker_fees,
                    "oanda_broker_commission_total": broker_fees,
                    "oanda_financing_commission_total": abs(financing),
                    "oanda_displayed_commission_total": displayed_commission,
                    "oanda_commission_includes_financing": bool(financing),
                    "oanda_api_commission_charge": commission_charge,
                    "oanda_api_guaranteed_execution_fee": gsl_fee_charge,
                    "oanda_api_guaranteed_execution_premium": gsl_premium_charge,
                    "oanda_api_other_trading_charges": other_charge,
                    "original_loss_conversion_factor": opening_factor,
                    "original_loss_conversion_factor_source": opening_factor_source,
                    "original_loss_conversion_factor_time": opening_factor_time,
                    "original_open_transaction_id": open_transaction_id,
                    "oanda_open_conversion_rate": opening_factor,
                    "homeConversionFactors": home_conversion_factors,
                    "plHomeConversionFactors": pl_home_conversion_factors,
                }.items()
                if v not in ("", None)
            },
            "raw_refs": {
                "transactionId": tx_id,
                "orderId": entry.get("orderID"),
                "tradeId": trade_id,
                "original_loss_conversion_factor": opening_factor,
                "original_loss_conversion_factor_source": opening_factor_source,
                "original_loss_conversion_factor_time": opening_factor_time,
                "original_open_transaction_id": open_transaction_id,
                "oanda_open_conversion_rate": opening_factor,
                "homeConversionFactors": home_conversion_factors,
                "plHomeConversionFactors": pl_home_conversion_factors,
            },
        }
        rows.append(_normalize_journal_profit_fields(row))
        if trade_id and open_leg and leg_units >= abs(_to_float(open_leg.get("units")) or 0.0):
            legs.pop(trade_id, None)
    _persist_oanda_fill_state()
    return rows


def _build_state_backup_payload() -> bytes:
    alerts_payload = {
        "bybit": {"alerts": bybit_monitor.get_custom_alerts(force=True)},
        "oanda": {"alerts": oanda_monitor.get_custom_alerts(force=True)},
    }
    machine_hint = os.getenv("COMPUTERNAME") or socket.gethostname() or "unknown-host"
    safe_machine_hint = re.sub(r"[^a-zA-Z0-9._-]", "-", str(machine_hint))[:80]
    trading_journal_payload = _load_json_file(TRADING_JOURNAL_PATH, {"items": []})
    if _trading_journal_local_excel_authoritative():
        journal_items = trading_journal_payload.get("items") if isinstance(trading_journal_payload, dict) else []
        if isinstance(journal_items, list):
            trading_journal_payload = {
                **(trading_journal_payload if isinstance(trading_journal_payload, dict) else {}),
                "items": [
                    r for r in journal_items
                    if isinstance(r, dict) and (_row_type(r) != "trade" or str(r.get("source") or "").strip().lower() == "local_excel")
                ],
            }
    payload = {
        "version": 4,
        "savedAt": _utc_now_iso(),
        "source_profile": APP_PROFILE,
        "source_host": safe_machine_hint,
        "watchlist_updated_at": _WATCHLIST_UPDATED_AT,
        "alerts": alerts_payload,
        "watchlist": _get_watchlist(),
        "pending_webhooks": _load_pending_webhooks(),
        "trade_contexts": _load_trade_contexts(),
        "trading_journal": trading_journal_payload,
        "trading_journal_state": _load_json_file(TRADING_JOURNAL_STATE_PATH, {}),
        "trading_journal_import_cache": _load_json_file(TRADING_JOURNAL_IMPORT_CACHE_PATH, {}),
        "monthly_aud_revaluation": _load_json_file(MONTHLY_AUD_REVALUATION_PATH, {"items": []}),
        "monthly_aud_revaluation_state": _load_json_file(MONTHLY_AUD_REVALUATION_STATE_PATH, {}),
        "oanda_fill_state": _load_json_file(OANDA_FILL_STATE_PATH, {}),
    }
    if APP_PROFILE == "render":
        payload["fxweekend_settings"] = _load_json_file(
            FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
        )
        payload["fxweekend_status"] = _load_json_file(FXWEEKEND_STATUS_PATH, {})
    return json.dumps(payload, indent=2, sort_keys=True).encode("utf-8")


def _dropbox_download_bytes(path: str) -> bytes:
    payload = download_bytes(path)
    _record_outbound_traffic(
        "dropbox",
        bytes_sent=len(path),
        bytes_received=len(payload),
        context=f"download:{path}",
    )
    return payload


def _dropbox_upload_bytes(path: str, payload: bytes) -> None:
    upload_bytes(path, payload)
    _record_outbound_traffic(
        "dropbox",
        bytes_sent=len(path) + len(payload),
        bytes_received=0,
        context=f"upload:{path}",
    )


def _state_sync_status_snapshot() -> Dict[str, object]:
    with _STATE_SYNC_STATUS_LOCK:
        _STATE_SYNC_STATUS["env_loaded_file"] = _MASTER_ENV_INFO.get("loaded_file") or ""
        _STATE_SYNC_STATUS["effective_local_state_mode"] = (
            "local-only"
            if (APP_PROFILE == "local" and (LOCAL_STATE_ONLY or not DROPBOX_SYNC_ENABLED))
            else "dropbox-required"
            if APP_PROFILE == "local"
            else "profile-managed"
        )
        if APP_PROFILE == "local" and not DROPBOX_SYNC_ENABLED and not LOCAL_STATE_ONLY:
            _STATE_SYNC_STATUS["restore_status"] = "failed"
            _STATE_SYNC_STATUS["restore_complete"] = True
            _STATE_SYNC_STATUS["restore_error"] = "Dropbox sync is disabled; set LOCAL_STATE_ONLY=1 for explicit local-only mode."
        return dict(_STATE_SYNC_STATUS)


def _update_state_sync_status(**updates: object) -> Dict[str, object]:
    with _STATE_SYNC_STATUS_LOCK:
        _STATE_SYNC_STATUS.update(updates)
        return dict(_STATE_SYNC_STATUS)

def _calendar_missing_expected_pl_cells(
    cal_ws,
    expected_year_months: Set[Tuple[int, int]],
) -> List[Tuple[int, int]]:
    def _has_pl_cell_value(value: object) -> bool:
        if isinstance(value, (int, float)):
            return True
        text = str(value or "").strip()
        return bool(re.match(r"^-?\d+(?:\.\d+)?%,\s+\d+\s+trades?$", text, flags=re.IGNORECASE))

    month_to_col_default: Dict[int, int] = {}
    month_to_col_custom: Dict[int, int] = {}
    for cc in range(1, cal_ws.max_column + 1):
        token = str(cal_ws.cell(1, cc).value or "").strip().lower()
        for mm in range(1, 13):
            name = calendar.month_name[mm].lower()
            if token == name:
                month_to_col_custom[mm] = cc
            if token == f"{name} p/l %":
                month_to_col_default[mm] = cc
    transposed_year_cols: Dict[int, int] = {}
    for cc in range(2, cal_ws.max_column + 1):
        year_value = _safe_float(cal_ws.cell(1, cc).value)
        if year_value is None:
            continue
        year = int(year_value)
        if 1900 <= year <= 3000:
            transposed_year_cols[year] = cc
    transposed_month_rows: Dict[int, int] = {}
    for rr in range(2, cal_ws.max_row + 1):
        token = str(cal_ws.cell(rr, 1).value or "").strip().lower()
        for mm in range(1, 13):
            if token == calendar.month_name[mm].lower():
                transposed_month_rows[mm] = rr
    default_year_rows: Dict[int, int] = {}
    custom_year_rows: Dict[int, int] = {}
    for rr in range(2, cal_ws.max_row + 1):
        yv = _safe_float(cal_ws.cell(rr, 1).value)
        if yv is None:
            continue
        year = int(yv)
        default_year_rows.setdefault(year, rr)
        if str(cal_ws.cell(rr, 2).value or "").strip().lower() == "p/l %":
            custom_year_rows[year] = rr
    missing: List[Tuple[int, int]] = []
    for year, month in expected_year_months:
        found_numeric = False
        col_default = month_to_col_default.get(month)
        row_default = default_year_rows.get(year)
        if col_default and row_default:
            if _has_pl_cell_value(cal_ws.cell(row_default, col_default).value):
                found_numeric = True
        col_custom = month_to_col_custom.get(month)
        row_custom = custom_year_rows.get(year)
        if col_custom and row_custom:
            if _has_pl_cell_value(cal_ws.cell(row_custom, col_custom).value):
                found_numeric = True
        if col_custom and row_default:
            if _has_pl_cell_value(cal_ws.cell(row_default, col_custom).value):
                found_numeric = True
        col_transposed = transposed_year_cols.get(year)
        row_transposed = transposed_month_rows.get(month)
        if col_transposed and row_transposed:
            if _has_pl_cell_value(cal_ws.cell(row_transposed, col_transposed).value):
                found_numeric = True
        if not found_numeric:
            missing.append((year, month))
    return sorted(missing)


def _calendar_has_expected_pl_cells(
    cal_ws,
    expected_year_months: Set[Tuple[int, int]],
) -> bool:
    return not _calendar_missing_expected_pl_cells(
        cal_ws,
        expected_year_months,
    )


def _mark_primary_state_verified(key: str, payload: object) -> Dict[str, object]:
    now = _utc_now_iso()
    status = _state_sync_status_snapshot()
    missing_keys = [str(item) for item in (status.get("missing_state_keys") or []) if str(item)]
    if key in missing_keys:
        missing_keys = [item for item in missing_keys if item != key]
    updates: Dict[str, object] = {
        "last_upload_at": now,
        "last_upload_error": None,
        "pending_upload": False,
        "missing_state_keys": missing_keys,
        "per_file_state_ready": not bool(missing_keys),
    }
    if key == "watchlist":
        updates["last_verified_at"] = now
        updates["last_verified_watchlist"] = _normalize_watchlist(payload if isinstance(payload, list) else [])
    return _update_state_sync_status(**updates)

def _mark_primary_state_local_committed(key: str, payload: object, *, pending_upload: bool) -> Dict[str, object]:
    now = _utc_now_iso()
    status = _state_sync_status_snapshot()
    missing_keys = [str(item) for item in (status.get("missing_state_keys") or []) if str(item)]
    if key in missing_keys:
        missing_keys = [item for item in missing_keys if item != key]
    updates: Dict[str, object] = {
        "last_local_write_at": now,
        "pending_upload": bool(pending_upload),
        "missing_state_keys": missing_keys,
        "per_file_state_ready": not bool(missing_keys),
    }
    return _update_state_sync_status(**updates)


def _raise_if_watchlist_state_indeterminate() -> None:
    status = _state_sync_status_snapshot()
    if not (
        bool(status.get("watchlist_indeterminate"))
        or bool(status.get("watchlist_mutation_blocked"))
    ):
        return
    raise HTTPException(
        status_code=503,
        detail={
            "error": "watchlist_state_indeterminate",
            "message": (
                "The last watchlist rollback could not be round-trip verified. "
                "Watchlist reads and writes are blocked until authoritative state "
                "is restored or reconciled."
            ),
            "rollback_error": status.get("watchlist_rollback_error"),
            "state_sync": status,
        },
    )


async def _wait_for_state_restore_or_error(timeout: float = 20.0) -> Dict[str, object]:
    status = _state_sync_status_snapshot()
    local_mode = _state_backup_uses_local_repo_file()
    restore_failed_error = "repo_local_restore_failed" if local_mode else "dropbox_restore_failed"
    restore_failed_message = "Repo-local state restore failed during startup." if local_mode else "Dropbox restore failed during startup."
    restore_timeout_error = "repo_local_restore_timeout" if local_mode else "dropbox_restore_timeout"
    restore_timeout_message = "Repo-local state restore is still pending." if local_mode else "Dropbox restore is still pending."
    if APP_PROFILE == "local" and not bool(status.get("enabled")) and not LOCAL_STATE_ONLY:
        raise HTTPException(
            status_code=503,
            detail={
                "error": "dropbox_sync_required",
                "message": "Dropbox sync is disabled; repo deletion will lose watchlist/custom alerts.",
                "state_sync": status,
            },
        )
    if not bool(status.get("enabled")):
        if not _STARTUP_STATE_RESTORE_DONE.is_set():
            _STARTUP_STATE_RESTORE_DONE.set()
        return status
    if status.get("restore_status") == "failed":
        raise HTTPException(
            status_code=503,
            detail={
                "error": restore_failed_error,
                "message": restore_failed_message,
                "state_sync": status,
            },
        )
    if _STARTUP_STATE_RESTORE_DONE.is_set():
        return _state_sync_status_snapshot()
    try:
        await asyncio.wait_for(_STARTUP_STATE_RESTORE_DONE.wait(), timeout=max(0.1, float(timeout)))
    except asyncio.TimeoutError as exc:
        raise HTTPException(
            status_code=503,
            detail={
                "error": restore_timeout_error,
                "message": restore_timeout_message,
                "state_sync": _state_sync_status_snapshot(),
            },
        ) from exc
    status = _state_sync_status_snapshot()
    if status.get("restore_status") == "failed":
        raise HTTPException(
            status_code=503,
            detail={
                "error": restore_failed_error,
                "message": restore_failed_message,
                "state_sync": status,
            },
        )
    return status


async def _upload_state_backup_now(timeout: float = 10.0) -> Dict[str, object]:
    return await _upload_and_verify_state_backup_now(timeout=timeout)




def _state_backup_uses_local_repo_file() -> bool:
    return bool(LOCAL_STATE_ONLY or APP_PROFILE == "local" or _master_journal_authoritative_enabled() or _master_journal_single_file_mode() or _trading_journal_local_excel_authoritative())


def _state_backup_display_path() -> str:
    return str(STATE_BACKUP_LOCAL_PATH) if _state_backup_uses_local_repo_file() else DROPBOX_BACKUP_PATH


def _state_source_label() -> str:
    if _state_backup_uses_local_repo_file():
        return "repo_local"
    if bool(DROPBOX_SYNC_ENABLED):
        return "dropbox"
    return "local"


def _load_local_state_backup() -> bytes:
    return STATE_BACKUP_LOCAL_PATH.read_bytes()


def _write_local_state_backup_bytes_or_payload(payload: object) -> None:
    STATE_BACKUP_LOCAL_PATH.parent.mkdir(parents=True, exist_ok=True)
    raw = payload if isinstance(payload, (bytes, bytearray)) else json.dumps(_json_safe(payload), ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    _atomic_write_bytes(STATE_BACKUP_LOCAL_PATH, bytes(raw))
def _extract_remote_backup_summary(raw: bytes) -> Dict[str, object]:
    try:
        data = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise ValueError(f"Remote backup JSON invalid: {exc}") from exc
    if not isinstance(data, dict):
        raise ValueError("Remote backup payload must be an object.")
    alerts = data.get("alerts") if isinstance(data.get("alerts"), dict) else {}
    bybit_alerts = []
    oanda_alerts = []
    bybit_block = alerts.get("bybit") if isinstance(alerts.get("bybit"), dict) else {}
    oanda_block = alerts.get("oanda") if isinstance(alerts.get("oanda"), dict) else {}
    if isinstance(bybit_block.get("alerts"), list):
        bybit_alerts = [item for item in bybit_block.get("alerts", []) if isinstance(item, dict)]
    if isinstance(oanda_block.get("alerts"), list):
        oanda_alerts = [item for item in oanda_block.get("alerts", []) if isinstance(item, dict)]
    watchlist_present = "watchlist" in data
    watchlist_valid = isinstance(data.get("watchlist"), list)
    watchlist = (
        _normalize_watchlist(data.get("watchlist", []))
        if watchlist_valid
        else []
    )
    fxweekend_settings_present = "fxweekend_settings" in data
    fxweekend_settings_valid = isinstance(data.get("fxweekend_settings"), dict)
    fxweekend_status_present = "fxweekend_status" in data
    fxweekend_status_valid = isinstance(data.get("fxweekend_status"), dict)
    summary = {
        "ok": True,
        "backup_path": _state_backup_display_path(),
        "savedAt": data.get("savedAt"),
        "updatedAt": data.get("updatedAt"),
        "watchlist": watchlist,
        "watchlist_present": watchlist_present,
        "watchlist_valid": watchlist_valid,
        "bybit_alert_count": len(bybit_alerts),
        "oanda_alert_count": len(oanda_alerts),
        "bybit_alert_ids": sorted(str(item.get("id") or "") for item in bybit_alerts),
        "oanda_alert_ids": sorted(str(item.get("id") or "") for item in oanda_alerts),
        "fxweekend_settings_present": fxweekend_settings_present,
        "fxweekend_settings_valid": fxweekend_settings_valid,
        "fxweekend_settings": (
            copy.deepcopy(data.get("fxweekend_settings"))
            if fxweekend_settings_valid
            else None
        ),
        "fxweekend_status_present": fxweekend_status_present,
        "fxweekend_status_valid": fxweekend_status_valid,
        "fxweekend_status": (
            copy.deepcopy(data.get("fxweekend_status"))
            if fxweekend_status_valid
            else None
        ),
        "hash": hashlib.sha256(raw).hexdigest(),
        "downloaded_at": _utc_now_iso(),
    }
    return summary


async def _download_remote_backup_summary(timeout: float = 10.0) -> Dict[str, object]:
    raw = await asyncio.wait_for(
        asyncio.to_thread(_load_local_state_backup if _state_backup_uses_local_repo_file() else _dropbox_download_bytes, *([] if _state_backup_uses_local_repo_file() else [DROPBOX_BACKUP_PATH])),
        timeout=max(0.1, float(timeout)),
    )
    return _extract_remote_backup_summary(raw)


async def _upload_and_verify_state_backup_now(
    *,
    expected_watchlist: Optional[List[str]] = None,
    expected_alert_probe: Optional[Dict[str, object]] = None,
    expected_fxweekend_settings: Optional[Dict[str, object]] = None,
    expected_fxweekend_status: Optional[Dict[str, object]] = None,
    timeout: float = 10.0,
) -> Dict[str, object]:
    status = _state_sync_status_snapshot()
    if not bool(status.get("enabled")):
        if APP_PROFILE == "local" and not LOCAL_STATE_ONLY:
            status = _update_state_sync_status(
                last_upload_error="Dropbox sync is disabled; repo deletion will lose watchlist/custom alerts.",
            )
            raise HTTPException(
                status_code=503,
                detail={
                    "error": "dropbox_sync_disabled",
                    "message": "Dropbox sync is disabled; repo deletion will lose watchlist/custom alerts.",
                    "state_sync": status,
                },
            )
        return status
    _update_state_sync_status(pending_upload=True, last_upload_error=None)
    try:
        payload = await asyncio.to_thread(_build_state_backup_payload)
        await asyncio.wait_for(
            asyncio.to_thread(
                _write_local_state_backup_bytes_or_payload if _state_backup_uses_local_repo_file() else _dropbox_upload_bytes,
                payload if _state_backup_uses_local_repo_file() else DROPBOX_BACKUP_PATH,
                *([] if _state_backup_uses_local_repo_file() else [payload]),
            ),
            timeout=max(0.1, float(timeout)),
        )
        remote_summary = await _download_remote_backup_summary(timeout=timeout)
        if expected_watchlist is not None:
            expected_norm = _normalize_watchlist(expected_watchlist)
            if remote_summary.get("watchlist_present") is False:
                raise ValueError(
                    "Remote watchlist verification mismatch; watchlist key is missing."
                )
            if remote_summary.get("watchlist_valid") is False or not isinstance(
                remote_summary.get("watchlist"), list
            ):
                raise ValueError(
                    "Remote watchlist verification mismatch; watchlist must be a list."
                )
            remote_watchlist = _normalize_watchlist(remote_summary.get("watchlist", []))
            if remote_watchlist != expected_norm:
                raise ValueError(
                    "Remote watchlist verification mismatch; "
                    f"expected exact sequence {expected_norm!r}, got {remote_watchlist!r}"
                )
        if isinstance(expected_alert_probe, dict):
            expected_bybit = sorted(str(v) for v in (expected_alert_probe.get("bybit_alert_ids") or []))
            expected_oanda = sorted(str(v) for v in (expected_alert_probe.get("oanda_alert_ids") or []))
            if expected_bybit != list(remote_summary.get("bybit_alert_ids") or []):
                raise ValueError("Remote Bybit alert verification mismatch.")
            if expected_oanda != list(remote_summary.get("oanda_alert_ids") or []):
                raise ValueError("Remote OANDA alert verification mismatch.")
        if isinstance(expected_fxweekend_settings, dict):
            if remote_summary.get("fxweekend_settings_present") is not True:
                raise ValueError(
                    "Remote FX Weekend settings verification mismatch; key is missing."
                )
            if remote_summary.get("fxweekend_settings_valid") is not True:
                raise ValueError(
                    "Remote FX Weekend settings verification mismatch; value must be an object."
                )
            if remote_summary.get("fxweekend_settings") != expected_fxweekend_settings:
                raise ValueError(
                    "Remote FX Weekend settings verification mismatch."
                )
        if isinstance(expected_fxweekend_status, dict):
            if remote_summary.get("fxweekend_status_present") is not True:
                raise ValueError(
                    "Remote FX Weekend status verification mismatch; key is missing."
                )
            if remote_summary.get("fxweekend_status_valid") is not True:
                raise ValueError(
                    "Remote FX Weekend status verification mismatch; value must be an object."
                )
            if remote_summary.get("fxweekend_status") != expected_fxweekend_status:
                raise ValueError("Remote FX Weekend status verification mismatch.")
        status = _update_state_sync_status(
            pending_upload=False,
            last_upload_at=_utc_now_iso(),
            last_upload_error=None,
            last_verified_at=_utc_now_iso(),
            last_verified_watchlist=list(remote_summary.get("watchlist") or []),
            remote_backup_hash=remote_summary.get("hash"),
        )
        BYBIT_LOGGER.info("State backup saved to %s", _state_backup_display_path())
        return status
    except Exception as exc:
        status = _update_state_sync_status(
            pending_upload=False,
            last_upload_error=str(exc),
        )
        BYBIT_LOGGER.error("%s backup failed: %s", "Local state" if _state_backup_uses_local_repo_file() else "Dropbox", exc)
        raise HTTPException(
            status_code=502,
            detail={
                "error": "local_backup_write_failed" if _state_backup_uses_local_repo_file() else "dropbox_upload_failed",
                "message": (
                    f"Repo-local state backup write failed: {exc}"
                    if _state_backup_uses_local_repo_file()
                    else f"Dropbox backup upload failed: {exc}"
                ),
                "state_sync": status,
            },
        ) from exc


def _schedule_dropbox_upload_state_backup() -> None:
    if (not DROPBOX_SYNC_ENABLED) and (not _state_backup_uses_local_repo_file()):
        return

    global _DROPBOX_UPLOAD_TIMER
    with _DROPBOX_UPLOAD_TIMER_LOCK:
        if _DROPBOX_UPLOAD_TIMER is not None:
            try:
                _DROPBOX_UPLOAD_TIMER.cancel()
            except Exception:
                pass
            _DROPBOX_UPLOAD_TIMER = None

        def _run_upload() -> None:
            _update_state_sync_status(pending_upload=True, last_upload_error=None)
            try:
                payload = _build_state_backup_payload()
                _write_local_state_backup_bytes_or_payload(payload) if _state_backup_uses_local_repo_file() else _dropbox_upload_bytes(DROPBOX_BACKUP_PATH, payload)
                _update_state_sync_status(
                    pending_upload=False,
                    last_upload_at=_utc_now_iso(),
                    last_upload_error=None,
                )
                BYBIT_LOGGER.info("State backup saved to %s", _state_backup_display_path())
            except Exception as exc:  # pragma: no cover - network failure
                _update_state_sync_status(
                    pending_upload=False,
                    last_upload_error=str(exc),
                )
                BYBIT_LOGGER.error("%s backup failed: %s", "Repo-local state" if _state_backup_uses_local_repo_file() else "Dropbox", exc)

        t = threading.Timer(DROPBOX_SYNC_DEBOUNCE_SECONDS, _run_upload)
        t.daemon = True
        _DROPBOX_UPLOAD_TIMER = t
        t.start()


def _restore_alerts_payload(data: Dict[str, object]) -> Dict[str, object]:
    if not isinstance(data, dict):
        raise HTTPException(status_code=400, detail="Backup payload must be a JSON object.")
    alerts_payload = data
    if "alerts" in data:
        alerts_payload = data.get("alerts")
        if not isinstance(alerts_payload, dict):
            raise HTTPException(status_code=400, detail="Backup missing alerts section.")
    bybit_block = alerts_payload.get("bybit") if isinstance(alerts_payload, dict) else None
    oanda_block = alerts_payload.get("oanda") if isinstance(alerts_payload, dict) else None
    if not isinstance(bybit_block, dict) or not isinstance(oanda_block, dict):
        raise HTTPException(status_code=400, detail="Backup alerts format invalid.")
    if not isinstance(bybit_block.get("alerts"), list) or not isinstance(
        oanda_block.get("alerts"), list
    ):
        raise HTTPException(status_code=400, detail="Backup alerts list missing.")

    watchlist_items: List[str] = []
    if "watchlist" in data:
        if not isinstance(data["watchlist"], list):
            raise HTTPException(status_code=400, detail="Backup watchlist must be a list.")
        watchlist_items = _normalize_watchlist(data["watchlist"])

    pending_restored: List[Dict[str, object]] = []
    if "pending_webhooks" in data:
        pending_restored = _replace_pending_webhooks(data["pending_webhooks"])
    trade_contexts_restored = 0
    if "trade_contexts" in data and isinstance(data["trade_contexts"], (list, dict)):
        trade_context_items = data["trade_contexts"]
        if isinstance(trade_context_items, dict):
            trade_context_items = trade_context_items.get("items", [])
        if isinstance(trade_context_items, list):
            cleaned = [dict(entry) for entry in trade_context_items if isinstance(entry, dict)]
            pruned = _prune_trade_contexts(cleaned)
            _save_trade_contexts(pruned)
            trade_contexts_restored = len(pruned)
    if pending_restored:
        pending_restored, pending_reconcile_diag = _reconcile_pending_webhooks_registry()
        pruned_count = sum(
            int(value)
            for key, value in pending_reconcile_diag.items()
            if key.endswith("_pruned")
        )
        if pruned_count:
            BYBIT_LOGGER.info(
                "PENDING_WEBHOOK_RESTORE_RECONCILE active=%s pruned=%s diagnostics=%s",
                len(pending_restored),
                pruned_count,
                pending_reconcile_diag,
            )

    journal_restored = 0
    journal_sanitized = 0
    if (not _trading_journal_local_excel_authoritative()) and "trading_journal" in data and isinstance(data["trading_journal"], (dict, list)):
        _save_json_file(TRADING_JOURNAL_PATH, data["trading_journal"])
        rows = _get_trading_journal_rows()
        journal_restored = len(rows)
        sanitized_rows, sanitize_stats = _sanitize_bybit_demo_rows(rows)
        if int(sanitize_stats.get("changed", 0)):
            _set_trading_journal_rows(sanitized_rows)
            journal_sanitized = int(sanitize_stats.get("deduped_by_order_id", 0)) + int(
                sanitize_stats.get("deduped_by_fingerprint", 0)
            )

    if "trading_journal_state" in data and isinstance(data["trading_journal_state"], dict):
        _save_json_file(TRADING_JOURNAL_STATE_PATH, data["trading_journal_state"])

    if (not _trading_journal_local_excel_authoritative()) and "trading_journal_import_cache" in data and isinstance(data["trading_journal_import_cache"], dict):
        _save_json_file(TRADING_JOURNAL_IMPORT_CACHE_PATH, data["trading_journal_import_cache"])

    monthly_rows_restored = 0
    if "monthly_aud_revaluation" in data and isinstance(data["monthly_aud_revaluation"], (dict, list)):
        _save_json_file(MONTHLY_AUD_REVALUATION_PATH, data["monthly_aud_revaluation"])
        monthly_rows_restored = len(_get_monthly_aud_revaluation_rows())
    if "monthly_aud_revaluation_state" in data and isinstance(data["monthly_aud_revaluation_state"], dict):
        _save_json_file(MONTHLY_AUD_REVALUATION_STATE_PATH, data["monthly_aud_revaluation_state"])
    oanda_fill_state_restored = False
    if (not _trading_journal_local_excel_authoritative()) and "oanda_fill_state" in data and isinstance(data["oanda_fill_state"], dict):
        _save_json_file(OANDA_FILL_STATE_PATH, data["oanda_fill_state"])
        _restore_oanda_fill_state_on_startup()
        oanda_fill_state_restored = True
    bybit_restored = bybit_monitor.replace_custom_alerts(bybit_block["alerts"], strict=False)
    oanda_restored = oanda_monitor.replace_custom_alerts(oanda_block["alerts"])
    invalid_bybit_restored = max(0, len(bybit_block["alerts"]) - len(bybit_restored))
    _set_watchlist(watchlist_items)
    return {
        "bybit_restored": len(bybit_restored),
        "bybit_invalid_skipped": invalid_bybit_restored,
        "oanda_restored": len(oanda_restored),
        "watchlist_restored": len(watchlist_items),
        "pending_webhooks_restored": len(pending_restored),
        "trade_contexts_restored": trade_contexts_restored,
        "oanda_fill_state_restored": oanda_fill_state_restored,
        "journal_rows_restored": journal_restored,
        "journal_rows_sanitized": journal_sanitized,
        "monthly_aud_revaluation_rows_restored": monthly_rows_restored,
    }


async def _dropbox_restore_state_backup_on_startup() -> None:
    local_repo_mode = _state_backup_uses_local_repo_file()
    if (not DROPBOX_SYNC_ENABLED) and (not local_repo_mode):
        _update_state_sync_status(
            enabled=False,
            restore_complete=True,
            restore_status="skipped",
            restore_error=None,
            backup_path=DROPBOX_BACKUP_PATH,
        )
        _STARTUP_STATE_RESTORE_DONE.set()
        return
    _update_state_sync_status(
        enabled=True,
        restore_complete=False,
        restore_status="pending",
        restore_error=None,
        fxweekend_settings_schema_version=None,
        fxweekend_settings_schema_migrated=False,
        fxweekend_durable_verified=False,
        backup_path=(str(STATE_BACKUP_LOCAL_PATH) if local_repo_mode else DROPBOX_BACKUP_PATH),
    )
    def _legacy_local_state_for_key(key: str) -> object:
        if key == "watchlist":
            return _normalize_watchlist(_load_watchlist())
        if key == "bybit_alerts":
            return bybit_monitor.get_custom_alerts(force=True)
        if key == "oanda_alerts":
            return oanda_monitor.get_custom_alerts(force=True)
        if key == "bybit_settings":
            return _read_bybit_settings()
        if key == "oanda_settings":
            return _read_oanda_settings()
        if key == "fxweekend_settings":
            return _load_json_file(FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS)
        if key == "fxweekend_status":
            return _load_json_file(FXWEEKEND_STATUS_PATH, {})
        return None

    def _backup_state_for_key(backup: dict, key: str) -> object:
        alerts_block = backup.get("alerts") if isinstance(backup.get("alerts"), dict) else {}
        if key == "watchlist":
            if "watchlist" not in backup:
                return None
            if not isinstance(backup.get("watchlist"), list):
                raise ValueError("Backup watchlist must be a list.")
            return _normalize_watchlist(backup.get("watchlist", []))
        if key == "bybit_alerts":
            return ((alerts_block.get("bybit") or {}).get("alerts") or [])
        if key == "oanda_alerts":
            return ((alerts_block.get("oanda") or {}).get("alerts") or [])
        if key == "bybit_settings":
            return backup.get("bybit_settings") if isinstance(backup.get("bybit_settings"), dict) else None
        if key == "oanda_settings":
            return backup.get("oanda_settings") if isinstance(backup.get("oanda_settings"), dict) else None
        if key == "fxweekend_settings":
            return backup.get("fxweekend_settings") if isinstance(backup.get("fxweekend_settings"), dict) else None
        if key == "fxweekend_status":
            return backup.get("fxweekend_status") if isinstance(backup.get("fxweekend_status"), dict) else None
        return None

    async def _bootstrap_dropbox_primary_state(keys: Optional[List[str]] = None) -> Dict[str, object]:
        required_keys = keys or [
            "watchlist",
            "bybit_alerts",
            "oanda_alerts",
            "bybit_settings",
            "oanda_settings",
        ]
        if keys is None and APP_PROFILE == "render":
            required_keys.extend(["fxweekend_settings", "fxweekend_status"])
        missing: List[str] = []
        migrated: List[str] = []
        invalid: List[str] = []
        restored_values: Dict[str, object] = {}
        remote_backup: dict = {}
        try:
            payload = await asyncio.to_thread(_load_local_state_backup) if _state_backup_uses_local_repo_file() else await asyncio.to_thread(download_bytes, DROPBOX_BACKUP_PATH)
            remote_backup = json.loads(payload.decode("utf-8")) if payload else {}
        except FileNotFoundError:
            remote_backup = {}
        for key in required_keys:
            existing = None
            local_existing = None
            repo_local_invalid = False
            if _state_backup_uses_local_repo_file():
                try:
                    local_existing = read_repo_state_json(key)
                except FileNotFoundError:
                    # The manifest is also the deletion tombstone for an empty
                    # watchlist. If an installer/update preserved the verified
                    # manifest but the small mirror is temporarily absent, do
                    # not replay an older aggregate list and resurrect symbols.
                    state_path = state_file_path_for_key(key)
                    local_existing = (
                        []
                        if (
                            key == "watchlist"
                            and not state_path.exists()
                            and _state_manifest_declares_payload(key, [])
                        )
                        else None
                    )
                except Exception as exc:
                    BYBIT_LOGGER.warning("Repo-local state for key '%s' is unreadable: %s", key, exc)
                    invalid.append(key)
                    repo_local_invalid = True
                    local_existing = None
                if repo_local_invalid:
                    continue
                if local_existing is not None and _is_valid_repo_state_value(key, local_existing):
                    existing = local_existing
                    restored_values[key] = copy.deepcopy(existing)
                    if key == "watchlist":
                        _set_watchlist_local_mirror(existing if isinstance(existing, list) else [])
                    elif key == "bybit_alerts":
                        bybit_monitor.replace_custom_alerts(existing if isinstance(existing, list) else [], strict=False)
                    elif key == "oanda_alerts":
                        oanda_monitor.replace_custom_alerts(existing if isinstance(existing, list) else [])
                    elif key == "fxweekend_settings" and isinstance(existing, dict):
                        _save_json_file(FXWEEKEND_SETTINGS_PATH, existing)
                    elif key == "fxweekend_status" and isinstance(existing, dict):
                        _save_json_file(FXWEEKEND_STATUS_PATH, existing)
                    continue
                if local_existing is not None and not _is_valid_repo_state_value(key, local_existing):
                    BYBIT_LOGGER.warning("Repo-local state for key '%s' has invalid type: %s", key, type(local_existing).__name__)
                    invalid.append(key)
                    continue
            else:
                existing = dropbox_state_store.download_json(key, default=None, required=False)
                if existing is not None:
                    if not _is_valid_repo_state_value(key, existing):
                        BYBIT_LOGGER.warning(
                            "Dropbox state for key '%s' has invalid type: %s",
                            key,
                            type(existing).__name__,
                        )
                        invalid.append(key)
                        continue
                    restored_values[key] = copy.deepcopy(existing)
                    if key == "watchlist" and isinstance(existing, list):
                        _set_watchlist_local_mirror(existing)
                    elif key == "bybit_alerts" and isinstance(existing, list):
                        bybit_monitor.replace_custom_alerts(existing, strict=False)
                    elif key == "oanda_alerts" and isinstance(existing, list):
                        oanda_monitor.replace_custom_alerts(existing)
                    elif key == "fxweekend_settings" and isinstance(existing, dict):
                        _save_json_file(FXWEEKEND_SETTINGS_PATH, existing)
                    elif key == "fxweekend_status" and isinstance(existing, dict):
                        _save_json_file(FXWEEKEND_STATUS_PATH, existing)
                    continue
            from_backup = _backup_state_for_key(remote_backup, key)
            candidate = from_backup
            candidate_missing = candidate is None or (
                key != "watchlist"
                and (
                    candidate == []
                    or (isinstance(candidate, dict) and not candidate)
                )
            )
            if candidate_missing:
                legacy = _legacy_local_state_for_key(key)
                if legacy not in (None, []) and not (
                    isinstance(legacy, dict) and not legacy
                ):
                    candidate = legacy
            if candidate is None:
                if key in {"watchlist", "bybit_alerts", "oanda_alerts"}:
                    candidate = []
                elif key == "bybit_settings":
                    candidate = _read_bybit_settings()
                elif key == "oanda_settings":
                    candidate = _read_oanda_settings()
                elif key == "fxweekend_settings":
                    candidate = _load_json_file(
                        FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
                    )
                elif key == "fxweekend_status":
                    candidate = _load_json_file(FXWEEKEND_STATUS_PATH, {})
            if _state_backup_uses_local_repo_file():
                write_repo_state_json_and_verify(key, candidate)
            else:
                if key == "watchlist":
                    expected_watchlist = _normalize_watchlist(
                        candidate if isinstance(candidate, list) else []
                    )
                    dropbox_state_store.upload_json_and_verify(
                        key,
                        expected_watchlist,
                        verifier=lambda value: _watchlist_roundtrip_matches(
                            value, expected_watchlist
                        ),
                    )
                    candidate = expected_watchlist
                else:
                    dropbox_state_store.upload_json_and_verify(key, candidate)
            migrated.append(key)
            existing = candidate
            if existing is None:
                missing.append(key)
                continue
            restored_values[key] = copy.deepcopy(existing)
            if key == "watchlist":
                _set_watchlist_local_mirror(existing if isinstance(existing, list) else [])
            elif key == "bybit_alerts":
                bybit_monitor.replace_custom_alerts(existing if isinstance(existing, list) else [], strict=False)
            elif key == "oanda_alerts":
                oanda_monitor.replace_custom_alerts(existing if isinstance(existing, list) else [])
            elif key == "fxweekend_settings" and isinstance(existing, dict):
                _save_json_file(FXWEEKEND_SETTINGS_PATH, existing)
            elif key == "fxweekend_status" and isinstance(existing, dict):
                _save_json_file(FXWEEKEND_STATUS_PATH, existing)
        return {
            "missing": missing,
            "migrated": migrated,
            "invalid": invalid,
            "restored_values": restored_values,
        }

    try:
        bootstrap = await _bootstrap_dropbox_primary_state()
        fxweekend_durability: Dict[str, object] = {
            "schema_version": None,
            "schema_migrated": False,
            "durable_verified": False,
        }
        if APP_PROFILE == "render" and not list(bootstrap.get("invalid") or []):
            fxweekend_durability = (
                await _upgrade_and_verify_fxweekend_settings_after_restore(
                    bootstrap
                )
            )
        if local_repo_mode:
            try:
                payload = await asyncio.to_thread(_load_local_state_backup)
                remote_hash = hashlib.sha256(payload).hexdigest() if payload else None
            except FileNotFoundError:
                payload = b""
                remote_hash = None
        else:
            try:
                payload = await asyncio.to_thread(download_bytes, DROPBOX_BACKUP_PATH)
                remote_hash = hashlib.sha256(payload).hexdigest() if payload else None
            except FileNotFoundError:
                # Per-file state is authoritative. A missing legacy aggregate backup
                # must not invalidate successfully restored per-file settings.
                payload = b""
                remote_hash = None
        restored = {
            "bybit_restored": 0,
            "bybit_invalid_skipped": 0,
            "oanda_restored": 0,
            "watchlist_restored": 0,
            "pending_webhooks_restored": 0,
            "trade_contexts_restored": 0,
            "oanda_fill_state_restored": False,
            "journal_rows_restored": 0,
            "journal_rows_sanitized": 0,
        }
        if not local_repo_mode and payload:
            data = json.loads(payload.decode("utf-8"))
            restored_values = bootstrap.get("restored_values")
            primary_watchlist = (
                restored_values.get("watchlist")
                if isinstance(restored_values, dict)
                else None
            )
            if isinstance(primary_watchlist, list):
                data = dict(data)
                data["watchlist"] = list(primary_watchlist)
            restored = _restore_alerts_payload(data)
        workbook_stats: Dict[str, object] = {}
        if not _master_journal_single_file_mode():
            active_folder, _ = await asyncio.to_thread(_resolve_trading_journal_dropbox_folder)
            workbook_stats = await asyncio.to_thread(_sanitize_bybit_demo_workbook, active_folder)
        oanda_repaired_rows = _repair_persisted_oanda_trade_rows()
        invalid_keys = list(bootstrap.get("invalid") or [])
        if invalid_keys:
            BYBIT_LOGGER.warning(
                "State backup rewrite skipped because authoritative state is invalid "
                "for keys: %s",
                ", ".join(invalid_keys),
            )
        else:
            _schedule_dropbox_upload_state_backup()
        BYBIT_LOGGER.info(
            "Dropbox restore complete: bybit=%s skipped_invalid_bybit=%s oanda=%s watchlist=%s pending=%s trade_contexts_restored=%s oanda_fill_state_restored=%s journal_rows=%s journal_sanitized=%s workbook_deduped=%s oanda_rows_repaired=%s",
            restored["bybit_restored"],
            restored.get("bybit_invalid_skipped", 0),
            restored["oanda_restored"],
            restored["watchlist_restored"],
            restored["pending_webhooks_restored"],
            restored.get("trade_contexts_restored", 0),
            restored.get("oanda_fill_state_restored", False),
            restored.get("journal_rows_restored", 0),
            restored.get("journal_rows_sanitized", 0),
            int(workbook_stats.get("deduped_by_order_id", 0)) + int(workbook_stats.get("deduped_by_fingerprint", 0)),
            oanda_repaired_rows,
        )
        _update_state_sync_status(
            restore_complete=True,
            restore_status="failed" if invalid_keys else "done",
            restore_error=(f"Invalid repo-local state for keys: {', '.join(invalid_keys)}" if invalid_keys else None),
            last_restore_at=_utc_now_iso(),
            remote_backup_hash=remote_hash,
            per_file_state_ready=(not bool(bootstrap.get("missing"))) and (not bool(invalid_keys)),
            missing_state_keys=list(bootstrap.get("missing") or []),
            migrated_state_keys=list(bootstrap.get("migrated") or []),
            watchlist_indeterminate=False,
            watchlist_mutation_blocked=False,
            watchlist_rollback_error=None,
            fxweekend_state_indeterminate=False,
            fxweekend_rollback_error=None,
            fxweekend_settings_schema_version=fxweekend_durability.get(
                "schema_version"
            ),
            fxweekend_settings_schema_migrated=bool(
                fxweekend_durability.get("schema_migrated")
            ),
            fxweekend_durable_verified=bool(
                fxweekend_durability.get("durable_verified")
            ),
        )
    except FileNotFoundError:
        BYBIT_LOGGER.info("Dropbox restore skipped; no backup found at %s", DROPBOX_BACKUP_PATH)
        _update_state_sync_status(
            restore_complete=True,
            restore_status="done",
            restore_error=None,
            last_restore_at=_utc_now_iso(),
            remote_backup_hash=None,
            per_file_state_ready=False,
            fxweekend_durable_verified=False,
        )
    except Exception as exc:  # pragma: no cover - startup failure
        BYBIT_LOGGER.error("Dropbox restore failed: %s", exc)
        _update_state_sync_status(
            restore_complete=True,
            restore_status="failed",
            restore_error=str(exc),
            last_restore_at=_utc_now_iso(),
            per_file_state_ready=False,
            fxweekend_durable_verified=False,
        )
    finally:
        _STARTUP_STATE_RESTORE_DONE.set()


@dataclass
class ManagedScript:
    """Represents a runnable Python script managed by the service."""

    name: str
    path: Path
    category: str = "Other"
    log_file: Optional[Path] = None
    process: Optional[asyncio.subprocess.Process] = None
    port: Optional[int] = None
    _log_lines: List[str] = field(default_factory=list)
    last_output_at: Optional[float] = None
    last_start_attempt_at: Optional[float] = None
    last_start_error: Optional[str] = None
    last_exit_code: Optional[int] = None
    last_exit_reason: Optional[str] = None
    last_spawn_command: Optional[List[str]] = None
    last_spawn_cwd: Optional[str] = None
    is_starting: bool = False
    startup_started_at: Optional[float] = None
    startup_completed_at: Optional[float] = None
    pid: Optional[int] = None
    executor_instance_id: Optional[str] = None
    heartbeat_confirmed_pid: Optional[int] = None
    operational_started_pid: Optional[int] = None
    startup_task: Optional[asyncio.Task] = field(default=None, repr=False, compare=False)
    _lifecycle_lock: asyncio.Lock = field(
        default_factory=asyncio.Lock,
        init=False,
        repr=False,
        compare=False,
    )

    @property
    def is_running(self) -> bool:
        return self.process is not None and self.process.returncode is None

    def to_summary(self) -> Dict[str, object]:
        startup_pending = bool(self.startup_task is not None and not self.startup_task.done())
        return {
            "id": self.name,
            "name": self.name,
            "label": friendly_script_label(self.name),
            "path": str(self.path),
            "category": self.category,
            "running": self.is_running,
            "starting": self.is_starting or startup_pending,
            "port": self.port,
            "pid": self.pid,
            "executor_instance_id": self.executor_instance_id,
            "return_code": None if self.process is None else self.process.returncode,
            "open_url": script_open_url(self),
            "logs_url": script_logs_url(self.name),
            "last_output_at": self.last_output_at,
            "last_start_attempt_at": self.last_start_attempt_at,
            "last_start_error": self.last_start_error,
            "last_exit_code": self.last_exit_code,
            "last_exit_reason": self.last_exit_reason,
            "last_spawn_command": self.last_spawn_command,
            "last_spawn_cwd": self.last_spawn_cwd,
            "startup_started_at": self.startup_started_at,
            "startup_completed_at": self.startup_completed_at,
            "heartbeat_confirmed_pid": self.heartbeat_confirmed_pid,
            "operational_started_pid": self.operational_started_pid,
            "standalone": self.name in STANDALONE_SCRIPTS,
        }

    def add_log(self, line: str) -> None:
        cleaned = line.rstrip("\n")
        if cleaned:
            if not re.match(r"^\[\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\]\s", cleaned):
                try:
                    now = datetime.now(ZoneInfo(APP_TIMEZONE))
                except Exception:
                    now = datetime.now(ZoneInfo("Australia/Brisbane"))
                cleaned = f"[{now.strftime('%Y-%m-%d %H:%M:%S')}] {cleaned}"
            self._log_lines.append(cleaned)
            if len(self._log_lines) > MAX_LOG_LINES:
                self._log_lines = self._log_lines[-MAX_LOG_LINES :]
            self.last_output_at = time.time()

    def logs(self) -> List[str]:
        if self.log_file is not None:
            try:
                if self.log_file.exists():
                    stat = self.log_file.stat()
                    content = self.log_file.read_text(encoding="utf-8", errors="replace")
                    lines = content.splitlines()
                    if lines:
                        self.last_output_at = stat.st_mtime
                    return lines[-MAX_LOG_LINES :]
            except Exception as exc:  # pragma: no cover - defensive fallback
                return [f"Unable to read log file {self.log_file}: {exc}"]

        return list(self._log_lines)

    def log_snapshot(self, cursor: int = 0) -> Dict[str, object]:
        lines = self.logs()
        safe_cursor = max(0, min(cursor, len(lines)))
        new_lines = lines[safe_cursor:]
        return {
            "lines": new_lines,
            "cursor": safe_cursor + len(new_lines),
            "total": len(lines),
            "last_output_at": self.last_output_at,
        }

    async def start(self, *, ignore_starting: bool = False) -> None:
        # Serialize the complete spawn transaction with stop(). In particular,
        # stop() waits on a child process and must not dereference mutable
        # self.process state after a concurrent start has installed a new child.
        async with self._lifecycle_lock:
            await self._start_locked(ignore_starting=ignore_starting)

    async def _start_locked(self, *, ignore_starting: bool = False) -> None:
        if self.is_running:
            return
        # Never bypass the in-flight guard. The legacy flag remains in the
        # signature for caller compatibility, but allowing it to override
        # `is_starting` can spawn two children during restore/supervisor races.
        if self.is_starting:
            return
        if not self.path.exists():
            raise FileNotFoundError(f"Script not found: {self.path}")

        restart_reason = str(
            self.last_exit_reason or self.last_start_error or "initial autostart"
        ).strip()
        self.last_start_attempt_at = time.time()
        self.last_start_error = None
        self.last_exit_code = None
        self.last_exit_reason = None
        self.is_starting = True
        self.startup_started_at = self.last_start_attempt_at
        self.startup_completed_at = None
        self.pid = None
        self.executor_instance_id = (
            uuid4().hex if self.name == "fxweekend-clone" else None
        )
        self.heartbeat_confirmed_pid = None
        self.operational_started_pid = None
        if self.name == "fxweekend-clone":
            AUTOSTART_LOGGER.info(
                "FX_WEEKEND_START_REQUESTED reason=%s",
                restart_reason,
            )
        self.add_log("Starting script...")
        self.add_log("Spawning subprocess...")
        env = os.environ.copy()
        env.setdefault("PYTHONUNBUFFERED", "1")
        if self.executor_instance_id:
            env["FXWEEKEND_EXECUTOR_INSTANCE_ID"] = self.executor_instance_id
        current_pythonpath = env.get("PYTHONPATH", "")
        env["PYTHONPATH"] = (
            f"{BASE_DIR}:{current_pythonpath}" if current_pythonpath else str(BASE_DIR)
        )
        if self.name in WEB_APPS:
            if self.port is None:
                self.port = _allocate_port()
            env["PORT"] = str(self.port)
            env["HOST"] = "127.0.0.1"
            env["APP_BASE_PATH"] = f"/apps/{quote(self.name)}"

        command = [os.getenv("PYTHON", "python"), "-u", str(self.path)]
        self.last_spawn_command = command
        self.last_spawn_cwd = str(self.path.parent)
        self.add_log(f"Command: {' '.join(command)}")
        self.add_log(f"Working directory: {self.last_spawn_cwd}")
        creationflags = 0
        if os.name == "nt":
            creationflags = subprocess.CREATE_NEW_PROCESS_GROUP
        try:
            self.process = await asyncio.wait_for(
                asyncio.create_subprocess_exec(
                    *command,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.STDOUT,
                    cwd=self.last_spawn_cwd,
                    env=env,
                    creationflags=creationflags,
                ),
                timeout=30,
            )
        except asyncio.TimeoutError as exc:
            self.last_start_error = "Timed out waiting for subprocess spawn."
            self.is_starting = False
            self.startup_completed_at = time.time()
            self.add_log(self.last_start_error)
            raise RuntimeError(self.last_start_error) from exc
        except Exception as exc:
            self.last_start_error = str(exc)
            self.is_starting = False
            self.startup_completed_at = time.time()
            self.add_log(f"Failed to start: {exc}")
            raise

        self.pid = self.process.pid
        self.add_log(f"Spawned PID {self.pid}. Waiting for monitor output...")
        if self.name == "fxweekend-clone":
            AUTOSTART_LOGGER.info(
                "FX_WEEKEND_CHILD_SPAWNED pid=%s cwd=%s",
                self.pid,
                self.last_spawn_cwd,
            )
        asyncio.create_task(self._capture_output())

    async def _capture_output(self) -> None:
        assert self.process is not None
        process = self.process
        if process.stdout is None:
            return

        saw_output = False
        try:
            while True:
                line = await process.stdout.readline()
                if not line:
                    break
                if not saw_output:
                    saw_output = True
                    self.is_starting = False
                    self.startup_completed_at = time.time()
                self.add_log(line.decode("utf-8", errors="replace"))
        finally:
            await process.wait()
            if self.process is not process:
                if self.name == "fxweekend-clone":
                    AUTOSTART_LOGGER.warning(
                        "FX_WEEKEND_TERMINATED pid=%s exit_code=%s "
                        "reason=superseded process cleanup",
                        process.pid,
                        process.returncode,
                    )
                return
            self.last_exit_code = process.returncode
            if not saw_output and process.returncode is not None:
                self.last_exit_reason = "Process exited before producing startup output."
                self.add_log(
                    f"Process exited before producing startup output (exit code {process.returncode})."
                )
            elif self.last_exit_reason is None:
                self.last_exit_reason = (
                    "Process exited unexpectedly." if process.returncode else None
                )
            if self.name == "fxweekend-clone":
                AUTOSTART_LOGGER.warning(
                    "FX_WEEKEND_TERMINATED pid=%s exit_code=%s reason=%s",
                    process.pid,
                    process.returncode,
                    self.last_exit_reason or "process exited normally",
                )
            self.is_starting = False
            self.startup_completed_at = self.startup_completed_at or time.time()
            self.pid = None
            self.executor_instance_id = None
            self.heartbeat_confirmed_pid = None
            self.operational_started_pid = None
            self.port = None

    async def stop(self) -> None:
        # Keep the old child identity stable across every await below. A start
        # requested while termination is in progress waits for cleanup, then
        # installs its new process and lifecycle metadata after this lock exits.
        async with self._lifecycle_lock:
            await self._stop_locked()

    async def _stop_locked(self) -> None:
        if not self.is_running:
            return
        assert self.process is not None
        if self.name == "fxweekend-clone":
            AUTOSTART_LOGGER.warning(
                "FX_WEEKEND_TERMINATION_REQUESTED pid=%s reason=%s",
                self.process.pid,
                self.last_exit_reason or "stop requested",
            )
        if os.name == "nt" and self.process.pid:
            try:
                os.kill(self.process.pid, signal.CTRL_BREAK_EVENT)
                await asyncio.wait_for(self.process.wait(), timeout=10)
            except Exception:
                self.process.terminate()
        else:
            self.process.terminate()
        try:
            await asyncio.wait_for(self.process.wait(), timeout=10)
        except asyncio.TimeoutError:
            self.process.kill()
            await self.process.wait()
        self.is_starting = False
        self.startup_completed_at = time.time()
        self.pid = None
        self.executor_instance_id = None
        self.heartbeat_confirmed_pid = None
        self.operational_started_pid = None


