def _fxweekend_status_signature(payload: object) -> str:
    data = payload if isinstance(payload, dict) else {}
    durable = {
        key: data.get(key)
        for key in (
            "state",
            "state_detail",
            "selected_accounts",
            "last_access_check_at",
            "last_attempt_at",
            "last_verified_flat_at",
            "last_verified_window_cutoff",
            "next_news_release",
            "next_news_liquidation_cutoff",
            "news_status",
            "news_last_result",
            "news_audit",
            "last_error",
            "consecutive_failures",
            "accounts",
        )
    }
    return hashlib.sha256(
        json.dumps(durable, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _persist_fxweekend_state_key(key: str, payload: Dict[str, object]) -> None:
    if key not in {"fxweekend_settings", "fxweekend_status"}:
        raise ValueError(f"Unsupported FX Weekend state key: {key}")
    if _state_backup_uses_local_repo_file():
        write_repo_state_json_and_verify(key, payload)
    else:
        dropbox_state_store.upload_json_and_verify(
            key,
            payload,
            verifier=lambda roundtrip: roundtrip == payload,
        )


async def _persist_fxweekend_config_with_rollback(
    previous_settings: Dict[str, object],
    previous_status: Dict[str, object],
    *,
    timeout: float = 10.0,
) -> Dict[str, object]:
    durable_settings = _load_json_file(
        FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
    )
    durable_status = _load_json_file(FXWEEKEND_STATUS_PATH, {})
    try:
        if not isinstance(durable_settings, dict):
            raise ValueError("FX Weekend settings response did not produce an object.")
        if not isinstance(durable_status, dict):
            raise ValueError("FX Weekend status response did not produce an object.")
        _persist_fxweekend_state_key("fxweekend_settings", durable_settings)
        _persist_fxweekend_state_key("fxweekend_status", durable_status)
        await _upload_and_verify_state_backup_now(
            expected_fxweekend_settings=durable_settings,
            expected_fxweekend_status=durable_status,
            timeout=timeout,
        )
        _update_state_sync_status(
            fxweekend_state_indeterminate=False,
            fxweekend_rollback_error=None,
        )
        return {"ok": True, "durable_verified": True}
    except Exception as primary_exc:
        rollback_errors: List[str] = []
        try:
            _save_json_file(FXWEEKEND_SETTINGS_PATH, previous_settings)
            _save_json_file(FXWEEKEND_STATUS_PATH, previous_status)
        except Exception as exc:
            rollback_errors.append(f"local rollback failed: {exc}")
        for key, payload in (
            ("fxweekend_settings", previous_settings),
            ("fxweekend_status", previous_status),
        ):
            try:
                _persist_fxweekend_state_key(key, payload)
            except Exception as exc:
                rollback_errors.append(f"{key} rollback failed: {exc}")
        try:
            await _upload_and_verify_state_backup_now(
                expected_fxweekend_settings=previous_settings,
                expected_fxweekend_status=previous_status,
                timeout=timeout,
            )
        except Exception as exc:
            rollback_errors.append(f"aggregate rollback failed: {exc}")
        rollback_verified = not rollback_errors
        rollback_error = "; ".join(rollback_errors) or None
        _update_state_sync_status(
            fxweekend_state_indeterminate=not rollback_verified,
            fxweekend_rollback_error=rollback_error,
        )
        detail = getattr(primary_exc, "detail", None)
        message = (
            str((detail or {}).get("message") or (detail or {}).get("error"))
            if isinstance(detail, dict)
            else str(primary_exc)
        )
        return {
            "ok": False,
            "error": "fxweekend_durable_state_failed",
            "message": message,
            "settings_restored": not any(
                item.startswith("local rollback failed") for item in rollback_errors
            ),
            "durable_rollback_verified": rollback_verified,
            "rollback_error": rollback_error,
        }


async def _upgrade_and_verify_fxweekend_settings_after_restore(
    bootstrap: Dict[str, object],
    *,
    timeout: float = 10.0,
) -> Dict[str, object]:
    """Upgrade authoritative FX settings and verify both durable stores.

    Account selection changes only for legacy schemas. Current-version choices
    are preserved, but every Render startup still verifies the per-file state
    and aggregate backup before the executor gate can open.
    """

    restored_values = bootstrap.get("restored_values")
    restored_values = (
        restored_values if isinstance(restored_values, dict) else {}
    )
    authoritative = restored_values.get("fxweekend_settings")
    if not isinstance(authoritative, dict):
        authoritative = _load_json_file(
            FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
        )
    if not isinstance(authoritative, dict):
        raise RuntimeError(
            "Authoritative FX Weekend settings did not produce an object."
        )

    previous_settings = copy.deepcopy(authoritative)
    upgraded, schema_migrated = upgrade_fxweekend_settings_schema(
        authoritative
    )
    previous_status = _load_json_file(FXWEEKEND_STATUS_PATH, {})
    if not isinstance(previous_status, dict):
        raise RuntimeError(
            "Authoritative FX Weekend status did not produce an object."
        )

    _save_json_file(FXWEEKEND_SETTINGS_PATH, upgraded)
    durability = await _persist_fxweekend_config_with_rollback(
        previous_settings,
        copy.deepcopy(previous_status),
        timeout=timeout,
    )
    if durability.get("ok") is not True:
        raise RuntimeError(
            str(
                durability.get("message")
                or durability.get("error")
                or "FX Weekend durable settings verification failed."
            )
        )

    local_roundtrip = _load_json_file(FXWEEKEND_SETTINGS_PATH, None)
    if local_roundtrip != upgraded:
        raise RuntimeError(
            "FX Weekend local settings verification failed after migration."
        )
    restored_values["fxweekend_settings"] = copy.deepcopy(upgraded)
    bootstrap["restored_values"] = restored_values
    try:
        schema_version = int(upgraded.get("schema_version") or 0)
    except (TypeError, ValueError):
        schema_version = 0
    return {
        "settings": upgraded,
        "schema_version": schema_version,
        "schema_migrated": schema_migrated,
        "durable_verified": True,
    }


def _persist_fxweekend_status_if_changed() -> None:
    global _FXWEEKEND_LAST_PERSISTED_STATUS_SIGNATURE
    payload = _load_json_file(FXWEEKEND_STATUS_PATH, {})
    if not isinstance(payload, dict) or not payload:
        return
    signature = _fxweekend_status_signature(payload)
    if signature == _FXWEEKEND_LAST_PERSISTED_STATUS_SIGNATURE:
        return
    _persist_fxweekend_state_key("fxweekend_status", payload)
    _FXWEEKEND_LAST_PERSISTED_STATUS_SIGNATURE = signature


def _fxweekend_start_gate() -> Tuple[bool, str]:
    """Require a successful authoritative restore before any FX executor start."""

    if APP_PROFILE != "render":
        return False, "FX Weekend execution is Render-owned; no local fallback is permitted."
    status = _state_sync_status_snapshot()
    restore_status = str(status.get("restore_status") or "").strip().lower()
    restore_complete = bool(status.get("restore_complete")) and _STARTUP_STATE_RESTORE_DONE.is_set()
    restore_error = str(status.get("restore_error") or "").strip()
    if not restore_complete:
        return False, "Authoritative FX Weekend state restore is still pending."
    if restore_status in {"failed", "error"} or restore_error:
        return False, restore_error or "Authoritative FX Weekend state restore failed."
    if not bool(status.get("enabled")):
        return False, "Durable state synchronization is not enabled for the Render FX Weekend executor."
    if restore_status != "done":
        return False, f"Authoritative FX Weekend state restore is not ready ({restore_status or 'unknown'})."
    if not bool(status.get("per_file_state_ready")):
        missing = ", ".join(str(item) for item in (status.get("missing_state_keys") or []))
        suffix = f": {missing}" if missing else "."
        return False, f"Authoritative FX Weekend per-file state is incomplete{suffix}"
    if bool(status.get("fxweekend_state_indeterminate")):
        return (
            False,
            str(status.get("fxweekend_rollback_error") or "")
            or "FX Weekend durable settings state is indeterminate after rollback failure.",
        )
    if not bool(status.get("fxweekend_durable_verified")):
        return (
            False,
            "FX Weekend per-file and aggregate settings verification is incomplete.",
        )
    settings = _load_json_file(
        FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
    )
    try:
        schema_version = int(
            settings.get("schema_version") if isinstance(settings, dict) else 0
        )
    except (TypeError, ValueError):
        schema_version = 0
    if schema_version < FXWEEKEND_SETTINGS_SCHEMA_VERSION:
        return (
            False,
            "FX Weekend settings schema migration is incomplete.",
        )
    return True, ""


def _compute_autostart_scripts() -> List[str]:
    """Resolve autostart script names from env.

    AUTOSTART_SCRIPTS supports:
      - comma-separated script names
      - ALL or * to start every discovered script
    AUTOSTART_EXCLUDE may contain a comma-separated list of script names to skip.
    """

    global _LAST_AUTOSTART_UNAVAILABLE
    _LAST_AUTOSTART_UNAVAILABLE = {}
    raw_value = os.getenv("AUTOSTART_SCRIPTS")
    if APP_PROFILE != "render" and _is_scanner_local_ui_mode():
        return []
    if raw_value is None:
        raw_value = (
            DEFAULT_LOCAL_AUTOSTART_SCRIPTS
            if APP_PROFILE == "local"
            else DEFAULT_RENDER_AUTOSTART_SCRIPTS
        )

    normalized = (raw_value or "").strip()
    if normalized.upper() in {"NONE", "OFF", "DISABLED"}:
        normalized = ""

    autostart_raw = [name.strip() for name in normalized.split(",") if name.strip()]
    autostart_exclude = {
        name.strip()
        for name in (os.getenv("AUTOSTART_EXCLUDE") or "").split(",")
        if name.strip()
    }

    want_all = any(token.upper() == "ALL" or token == "*" for token in autostart_raw)
    names = list(script_manager.names) if want_all else list(autostart_raw)

    if autostart_exclude:
        names = [name for name in names if name not in autostart_exclude]
    if APP_PROFILE == "render" and "fxweekend-clone" not in names:
        # Render is the sole execution authority. Environment convenience
        # overrides may tune other children but cannot silently remove this
        # executor; its durable `enabled` setting still controls all actions.
        names.append("fxweekend-clone")
    filtered: List[str] = []
    seen: Set[str] = set()
    for name in names:
        if APP_PROFILE != "render" and str(name).strip() == "fxweekend-clone":
            AUTOSTART_LOGGER.warning(
                "Ignoring local FX Weekend autostart target; execution is Render-owned."
            )
            continue
        try:
            script = script_manager.get(name)
        except HTTPException as exc:
            reason = str(getattr(exc, "detail", "") or exc)
            _LAST_AUTOSTART_UNAVAILABLE[str(name)] = reason
            AUTOSTART_LOGGER.error(
                "AUTOSTART_TARGET_UNAVAILABLE target=%s reason=%s",
                name,
                reason,
            )
            continue
        if script.name in seen:
            continue
        seen.add(script.name)
        filtered.append(script.name)
    return filtered


def _script_startup_error(script: "ManagedScript") -> str:
    return str(script.last_start_error or script.last_exit_reason or "").strip()


def _fxweekend_enabled() -> bool:
    settings = _load_json_file(
        FXWEEKEND_SETTINGS_PATH,
        FXWEEKEND_DEFAULT_SETTINGS,
    )
    return bool(
        settings.get("enabled", True)
        if isinstance(settings, dict)
        else True
    )


def _fxweekend_heartbeat_fresh(
    settings: Optional[Dict[str, object]] = None,
    runtime: Optional[Dict[str, object]] = None,
    *,
    now: Optional[datetime] = None,
    expected_pid: Optional[int] = None,
    expected_instance_id: Optional[str] = None,
) -> bool:
    return bool(
        _fxweekend_heartbeat_diagnostics(
            settings,
            runtime,
            now=now,
            expected_pid=expected_pid,
            expected_instance_id=expected_instance_id,
        )["fresh"]
    )


def _fxweekend_heartbeat_diagnostics(
    settings: Optional[Dict[str, object]] = None,
    runtime: Optional[Dict[str, object]] = None,
    *,
    now: Optional[datetime] = None,
    expected_pid: Optional[int] = None,
    expected_instance_id: Optional[str] = None,
) -> Dict[str, object]:
    settings_payload = (
        settings
        if isinstance(settings, dict)
        else _load_json_file(
            FXWEEKEND_SETTINGS_PATH,
            FXWEEKEND_DEFAULT_SETTINGS,
        )
    )
    runtime_payload = (
        runtime
        if isinstance(runtime, dict)
        else _load_json_file(FXWEEKEND_STATUS_PATH, {})
    )
    heartbeat_raw = str(
        (runtime_payload or {}).get("heartbeat_at") or ""
    ).strip()
    runtime_pid_raw = (runtime_payload or {}).get("executor_pid")
    try:
        runtime_pid = (
            int(runtime_pid_raw)
            if runtime_pid_raw not in (None, "")
            else None
        )
    except (TypeError, ValueError):
        runtime_pid = None
    try:
        normalized_expected_pid = (
            int(expected_pid) if expected_pid not in (None, "") else None
        )
    except (TypeError, ValueError):
        normalized_expected_pid = None
    pid_matches = (
        normalized_expected_pid is None
        or runtime_pid == normalized_expected_pid
    )
    runtime_instance_id = str(
        (runtime_payload or {}).get("executor_instance_id") or ""
    ).strip()
    normalized_expected_instance_id = str(
        expected_instance_id or ""
    ).strip()
    instance_matches = (
        not normalized_expected_instance_id
        or runtime_instance_id == normalized_expected_instance_id
    )
    try:
        check_interval = max(
            1.0,
            float((settings_payload or {}).get("check_interval_seconds") or 60),
        )
    except (TypeError, ValueError):
        check_interval = 60.0
    try:
        maximum_backoff = max(
            check_interval,
            float(
                (settings_payload or {}).get("max_retry_backoff_seconds")
                or check_interval
            ),
        )
    except (TypeError, ValueError):
        maximum_backoff = check_interval
    stale_after = max(
        FXWEEKEND_HEARTBEAT_MIN_STALE_SECONDS,
        check_interval * 3.0,
        maximum_backoff
        + max(FXWEEKEND_HEARTBEAT_MIN_MARGIN_SECONDS, check_interval * 2.0),
    )
    diagnostics: Dict[str, object] = {
        "fresh": False,
        "timestamp_fresh": False,
        "heartbeat_at": heartbeat_raw or None,
        "heartbeat_age_seconds": None,
        "stale_after_seconds": stale_after,
        "check_interval_seconds": check_interval,
        "max_retry_backoff_seconds": maximum_backoff,
        "expected_pid": normalized_expected_pid,
        "executor_pid": runtime_pid,
        "pid_matches": pid_matches,
        "expected_instance_id": normalized_expected_instance_id or None,
        "executor_instance_id": runtime_instance_id or None,
        "instance_matches": instance_matches,
    }
    if not heartbeat_raw:
        return diagnostics
    try:
        heartbeat_dt = datetime.fromisoformat(
            heartbeat_raw.replace("Z", "+00:00")
        )
        if heartbeat_dt.tzinfo is None:
            heartbeat_dt = heartbeat_dt.replace(tzinfo=timezone.utc)
        current = now or datetime.now(timezone.utc)
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        age_seconds = (
            current.astimezone(timezone.utc)
            - heartbeat_dt.astimezone(timezone.utc)
        ).total_seconds()
        diagnostics["heartbeat_age_seconds"] = max(0.0, age_seconds)
        diagnostics["timestamp_fresh"] = age_seconds <= stale_after
        diagnostics["fresh"] = bool(
            diagnostics["timestamp_fresh"]
            and pid_matches
            and instance_matches
        )
        return diagnostics
    except Exception:
        return diagnostics


def _fxweekend_heartbeat_startup_grace(
    summary: Dict[str, object],
    *,
    now_epoch: Optional[float] = None,
) -> Dict[str, object]:
    started_raw = summary.get("startup_started_at")
    try:
        started_at = float(started_raw)
    except (TypeError, ValueError):
        started_at = 0.0
    current = time.time() if now_epoch is None else float(now_epoch)
    age_seconds = max(0.0, current - started_at) if started_at > 0 else None
    remaining = (
        max(0.0, FXWEEKEND_HEARTBEAT_STARTUP_GRACE_SECONDS - age_seconds)
        if age_seconds is not None
        else 0.0
    )
    active = bool(
        summary.get("running")
        and summary.get("pid")
        and age_seconds is not None
        and age_seconds <= FXWEEKEND_HEARTBEAT_STARTUP_GRACE_SECONDS
    )
    return {
        "active": active,
        "age_seconds": age_seconds,
        "remaining_seconds": remaining,
        "grace_seconds": FXWEEKEND_HEARTBEAT_STARTUP_GRACE_SECONDS,
    }


def _autostart_component_readiness(
    name: str,
    *,
    summary_override: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    try:
        script = script_manager.get(name)
    except HTTPException as exc:
        reason = str(getattr(exc, "detail", "") or exc).strip() or f"Script not found: {name}"
        return {
            "name": name,
            "label": friendly_script_label(name),
            "ready": False,
            "running": False,
            "starting": False,
            "blocking": False,
            "phase": "autostart_unavailable",
            "reason": reason,
        }

    summary = (
        dict(summary_override)
        if isinstance(summary_override, dict)
        else script.to_summary()
    )
    starting = bool(summary.get("starting"))
    running = bool(summary.get("running"))
    reason = str(
        summary.get("last_start_error")
        or summary.get("last_exit_reason")
        or _script_startup_error(script)
        or ""
    ).strip()
    component: Dict[str, object] = {
        "name": script.name,
        "label": friendly_script_label(script.name),
        "ready": False,
        "running": running,
        "starting": starting,
        "blocking": False,
        "phase": "autostart_pending",
        "reason": "",
    }

    if script.name in {"bybit_monitor", "oanda_monitor"}:
        runtime = _scanner_status_payload(
            BYBIT_RUNTIME_STATUS_PATH if script.name == "bybit_monitor" else OANDA_RUNTIME_STATUS_PATH
        )
        runtime_live = runtime.get("ui_status") == "running"
        ready = bool(running or runtime_live)
        component.update(
            {
                "ready": ready,
                "running": ready,
                "runtime_live": runtime_live,
                "managed_running": running,
                "heartbeat_fresh": runtime.get("heartbeat_fresh"),
                "phase": "ready" if ready else ("autostart_starting" if starting else "autostart_failed" if reason else "autostart_pending"),
            }
        )
        if not ready:
            component["reason"] = reason or f"{friendly_script_label(script.name)} is not running yet."
        return component

    enabled = True
    if script.name == "fxweekend-clone":
        raw_settings = _load_json_file(
            FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
        )
        settings, _schema_migrated = upgrade_fxweekend_settings_schema(
            raw_settings
        )
        enabled = bool(settings.get("enabled", True))
        component["enabled"] = enabled
        component["blocking"] = bool(enabled and APP_PROFILE == "render")
        selected_set = {
            str(item).strip().lower()
            for item in (settings.get("account_modes") or [])
        }
        selected_accounts = [
            mode
            for mode in FXWEEKEND_DEFAULT_ACCOUNT_MODES
            if mode in selected_set
        ]
        runtime = _load_json_file(FXWEEKEND_STATUS_PATH, {})
        runtime = runtime if isinstance(runtime, dict) else {}
        runtime_selected_set = {
            str(item).strip().lower()
            for item in (runtime.get("selected_accounts") or [])
        }
        runtime_selected_accounts = [
            mode
            for mode in FXWEEKEND_DEFAULT_ACCOUNT_MODES
            if mode in runtime_selected_set
        ]
        runtime_accounts = (
            runtime.get("accounts")
            if isinstance(runtime.get("accounts"), dict)
            else {}
        )
        component["selected_accounts"] = selected_accounts
        component["runtime_selected_accounts"] = runtime_selected_accounts
        component["heartbeat_at"] = runtime.get("heartbeat_at")
        component["executor_pid"] = runtime.get("executor_pid")
        component["executor_instance_id"] = runtime.get(
            "executor_instance_id"
        )
        component["executor_started_at"] = runtime.get("executor_started_at")
        component["process_pid"] = summary.get("pid")
        component["process_instance_id"] = summary.get(
            "executor_instance_id"
        )
        component["last_access_check_at"] = runtime.get("last_access_check_at")
        component["last_verified_flat_at"] = runtime.get("last_verified_flat_at")
        component["accounts"] = runtime_accounts
        news_events = [
            item
            for item in (settings.get("news_events") or [])
            if isinstance(item, dict)
        ]
        active_news_ids = {
            str(item.get("id") or "") for item in news_events if item.get("id")
        }
        news_last_result = (
            runtime.get("news_last_result")
            if isinstance(runtime.get("news_last_result"), dict)
            else {}
        )
        component["next_news_release"] = runtime.get("next_news_release")
        component["next_news_liquidation_cutoff"] = runtime.get(
            "next_news_liquidation_cutoff"
        )
        component["news_status"] = runtime.get("news_status")
        component["news_last_result"] = news_last_result or None
        state_sync = _state_sync_status_snapshot()
        component["durable_state_indeterminate"] = bool(
            state_sync.get("fxweekend_state_indeterminate")
        )
        credential_errors: List[str] = []
        for mode in selected_accounts:
            try:
                resolve_oanda_account_config(mode)
            except OandaAPIError as exc:
                credential_errors.append(f"{mode}: {exc}")
        component["credential_errors"] = credential_errors
        missing_runtime_accounts = [
            mode
            for mode in selected_accounts
            if not isinstance(runtime_accounts.get(mode), dict)
        ]
        pending_runtime_accounts: List[str] = []
        account_errors: List[str] = []
        account_warnings: List[str] = []
        account_failure_state: Optional[str] = None
        account_failure_states = {
            "credential failure",
            "api failure",
            "partial closure failure",
            "retry pending",
        }
        account_warning_states = {"missed cutoff/market closed"}
        for mode in selected_accounts:
            account = runtime_accounts.get(mode)
            if not isinstance(account, dict):
                continue
            account_state = str(account.get("state") or "").strip()
            account_state_normalized = account_state.lower()
            if account_state_normalized in {"", "checking"}:
                pending_runtime_accounts.append(mode)
            if account_state_normalized in account_failure_states:
                account_failure_state = account_failure_state or account_state
                account_errors.append(
                    f"{mode}: "
                    + str(
                        account.get("last_error")
                        or runtime.get("last_error")
                        or account_state
                        or "account check failed"
                    )
                )
            if account_state_normalized in account_warning_states:
                account_warnings.append(
                    f"{mode}: "
                    + str(
                        account.get("last_error")
                        or account_state
                        or "the cutoff was missed or the market was closed"
                    )
                )
        component["missing_runtime_accounts"] = missing_runtime_accounts
        component["pending_runtime_accounts"] = pending_runtime_accounts
        component["account_errors"] = account_errors
        component["account_warnings"] = account_warnings
        heartbeat = _fxweekend_heartbeat_diagnostics(
            settings,
            runtime,
            expected_pid=summary.get("pid"),
            expected_instance_id=summary.get("executor_instance_id"),
        )
        heartbeat_fresh = bool(heartbeat["fresh"])
        component["heartbeat_fresh"] = heartbeat_fresh
        component["heartbeat_timestamp_fresh"] = heartbeat[
            "timestamp_fresh"
        ]
        component["heartbeat_pid_matches"] = heartbeat["pid_matches"]
        component["heartbeat_instance_matches"] = heartbeat[
            "instance_matches"
        ]
        component["heartbeat_age_seconds"] = heartbeat["heartbeat_age_seconds"]
        component["heartbeat_stale_after_seconds"] = heartbeat[
            "stale_after_seconds"
        ]
        startup_grace = _fxweekend_heartbeat_startup_grace(summary)
        component["heartbeat_startup_grace_active"] = startup_grace["active"]
        component["heartbeat_startup_grace_remaining_seconds"] = (
            startup_grace["remaining_seconds"]
        )
        runtime_state = str(runtime.get("state") or "").strip()
        runtime_state_normalized = runtime_state.lower()
        last_news_event_ids = {
            str(item)
            for item in (news_last_result.get("event_ids") or [])
            if str(item)
        }
        active_news_result = bool(
            active_news_ids.intersection(last_news_event_ids)
        )
        news_result_state = str(
            news_last_result.get("state") or ""
        ).strip()
        news_failure = bool(
            active_news_result
            and news_last_result.get("verified_flat") is not True
            and news_result_state
        )
        news_warning = bool(
            active_news_result
            and news_last_result.get("verified_flat") is True
            and news_last_result.get("cutoff_met") is False
        )
        runtime_failure = runtime_state_normalized in {
            "credential failure",
            "api failure",
            "partial closure failure",
            "retry pending",
        } or news_failure
        runtime_warning = (
            runtime_state_normalized in account_warning_states
            or bool(account_warnings)
            or news_warning
        )
        if not enabled:
            component.update(
                {
                    "ready": True,
                    "phase": "disabled",
                    "reason": "FX Weekend execution is durably disabled.",
                    "health_state": "disabled",
                    "health_reason": "FX Weekend execution is durably disabled.",
                }
            )
            return component
        if component["durable_state_indeterminate"]:
            component.update(
                {
                    "ready": False,
                    "phase": "durable_state_indeterminate",
                    "reason": str(
                        state_sync.get("fxweekend_rollback_error")
                        or "FX Weekend durable settings rollback could not be verified."
                    ),
                    "health_state": "red",
                    "health_reason": str(
                        state_sync.get("fxweekend_rollback_error")
                        or "FX Weekend durable settings rollback could not be verified."
                    ),
                }
            )
            return component
        if not selected_accounts:
            component.update(
                {
                    "ready": False,
                    "phase": "account_configuration_failed",
                    "reason": "No OANDA account mode is selected.",
                    "health_state": "red",
                    "health_reason": "No OANDA account mode is selected.",
                }
            )
            return component
        if credential_errors:
            component.update(
                {
                    "ready": False,
                    "phase": "credential_failure",
                    "reason": "; ".join(credential_errors),
                    "health_state": "red",
                    "health_reason": "; ".join(credential_errors),
                }
            )
            return component
        if not running:
            stopped_reason = (
                "FX Weekend is still starting."
                if starting
                else reason or "FX Weekend executor is not running."
            )
            component.update(
                {
                    "ready": False,
                    "phase": (
                        "autostart_starting"
                        if starting
                        else "autostart_pending"
                    ),
                    "reason": stopped_reason,
                    "health_state": "amber" if starting else "red",
                    "health_reason": stopped_reason,
                }
            )
            return component
        if not heartbeat_fresh and bool(startup_grace["active"]):
            pending_reason = (
                "FX Weekend is waiting for the current child process to "
                "publish its first heartbeat."
            )
            component.update(
                {
                    "ready": False,
                    "phase": "heartbeat_pending_for_process",
                    "reason": pending_reason,
                    "health_state": "amber",
                    "health_reason": pending_reason,
                }
            )
            return component
        if not heartbeat_fresh:
            if bool(heartbeat["timestamp_fresh"]) and (
                not bool(heartbeat["pid_matches"])
                or not bool(heartbeat["instance_matches"])
            ):
                stale_reason = (
                    "FX Weekend heartbeat belongs to a previous child "
                    "process instance."
                )
            else:
                stale_reason = (
                    "FX Weekend heartbeat is missing or genuinely stale."
                )
            component.update(
                {
                    "ready": False,
                    "phase": "heartbeat_stale",
                    "reason": stale_reason,
                    "health_state": "red",
                    "health_reason": stale_reason,
                }
            )
            return component
        if runtime_failure:
            failure_reason = str(
                news_last_result.get("error")
                or (news_result_state if news_failure else "")
                or runtime.get("last_error")
                or runtime_state
                or "FX Weekend account check failed."
            )
            component.update(
                {
                    "ready": False,
                    "phase": str(runtime_state or "executor_failed").replace(" ", "_"),
                    "reason": failure_reason,
                    "health_state": "red",
                    "health_reason": failure_reason,
                }
            )
            return component
        if starting:
            component.update(
                {
                    "ready": False,
                    "phase": "autostart_starting",
                    "reason": "FX Weekend is still starting.",
                    "health_state": "amber",
                    "health_reason": "FX Weekend is still starting.",
                }
            )
            return component
        if runtime_selected_accounts != selected_accounts:
            pending_reason = (
                "FX Weekend runtime has not loaded the current selected "
                "accounts yet."
            )
            component.update(
                {
                    "ready": False,
                    "phase": "account_selection_pending",
                    "reason": pending_reason,
                    "health_state": "amber",
                    "health_reason": pending_reason,
                }
            )
            return component
        if account_errors:
            component.update(
                {
                    "ready": False,
                    "phase": str(
                        account_failure_state or "account_failure"
                    ).replace(" ", "_"),
                    "reason": "; ".join(account_errors),
                    "health_state": "red",
                    "health_reason": "; ".join(account_errors),
                }
            )
            return component
        if missing_runtime_accounts or pending_runtime_accounts:
            pending_modes = [
                *missing_runtime_accounts,
                *[
                    mode
                    for mode in pending_runtime_accounts
                    if mode not in missing_runtime_accounts
                ],
            ]
            pending_reason = (
                "FX Weekend has not completed a current account check "
                f"for: {', '.join(pending_modes)}."
            )
            component.update(
                {
                    "ready": False,
                    "phase": "account_checks_pending",
                    "reason": pending_reason,
                    "health_state": "amber",
                    "health_reason": pending_reason,
                }
            )
            return component
        if runtime_warning:
            warning_reason = (
                (news_result_state if news_warning else "")
                or str(runtime.get("state_detail") or "").strip()
                or "; ".join(account_warnings)
                or "The executor is healthy, but the prior cutoff was missed or the market was closed."
            )
            component.update(
                {
                    "ready": True,
                    "phase": "operational_warning",
                    "reason": warning_reason,
                    "health_state": "amber",
                    "health_reason": warning_reason,
                }
            )
            return component
        component.update(
            {
                "ready": True,
                "phase": "ready",
                "reason": "",
                "health_state": "green",
                "health_reason": "FX Weekend executor is running with a fresh heartbeat.",
            }
        )
        return component

    ready = bool(running and not starting and enabled)
    component["ready"] = ready
    if ready:
        component["phase"] = "ready"
        return component

    if starting:
        component["phase"] = "autostart_starting"
        component["reason"] = f"{friendly_script_label(script.name)} is still starting."
    elif not enabled:
        component["phase"] = "autostart_disabled"
        component["reason"] = f"{friendly_script_label(script.name)} is configured for autostart but disabled."
    elif reason:
        component["phase"] = "autostart_failed"
        component["reason"] = reason
    else:
        component["phase"] = "autostart_pending"
        component["reason"] = f"{friendly_script_label(script.name)} is not running yet."
    return component


def _startup_readiness_status() -> Dict[str, object]:
    state_sync = _state_sync_status_snapshot()
    autostart_targets = _compute_autostart_scripts()
    unavailable = dict(_LAST_AUTOSTART_UNAVAILABLE)
    components: List[Dict[str, object]] = []
    background_warnings: List[Dict[str, object]] = []
    payload: Dict[str, object] = {
        "ready": False,
        "core_ready": False,
        "background_ready": False,
        "background_warnings": background_warnings,
        "background_warning": None,
        "startup_phase": "checking",
        "blocking_component": None,
        "failure_reason": None,
        "state_sync": state_sync,
        "autostart_targets": autostart_targets,
        "components": components,
        "updated_at": _utc_now_iso(),
    }

    restore_status = str(state_sync.get("restore_status") or "").strip().lower()
    restore_enabled = bool(state_sync.get("enabled"))
    restore_complete = bool(state_sync.get("restore_complete")) or _STARTUP_STATE_RESTORE_DONE.is_set()
    restore_error = str(state_sync.get("restore_error") or "").strip()
    restore_component = {
        "name": "state_restore",
        "label": "Startup state restore",
        "ready": (not restore_enabled) or (restore_complete and restore_status not in {"failed", "error"}),
        "running": restore_enabled and not restore_complete,
        "starting": restore_enabled and not restore_complete,
        "blocking": False,
        "phase": restore_status or ("skipped" if not restore_enabled else "pending"),
        "reason": restore_error,
    }
    components.append(restore_component)

    if unavailable:
        for target_name, reason in sorted(unavailable.items()):
            blocking = bool(
                APP_PROFILE == "render"
                and target_name == "fxweekend-clone"
                and _fxweekend_enabled()
            )
            component = {
                "name": target_name,
                "label": friendly_script_label(target_name),
                "ready": False,
                "running": False,
                "starting": False,
                "blocking": blocking,
                "phase": "autostart_unavailable",
                "reason": reason,
            }
            components.append(component)
            background_warnings.append(dict(component))

    for name in autostart_targets:
        component = _autostart_component_readiness(name)
        components.append(component)
        if not bool(component.get("ready")):
            background_warnings.append(dict(component))

    payload["background_ready"] = not background_warnings
    if background_warnings:
        payload["background_warning"] = "; ".join(
            f"{warning.get('name')}: {warning.get('reason')}"
            for warning in background_warnings
        )

    if restore_status in {"failed", "error"}:
        restore_component["blocking"] = True
        payload.update(
            {
                "startup_phase": "state_restore_failed",
                "blocking_component": "state_restore",
                "failure_reason": restore_error or "Startup state restore failed.",
            }
        )
        return payload
    if restore_enabled and not restore_complete:
        restore_component["blocking"] = True
        payload.update(
            {
                "startup_phase": "state_restore_pending",
                "blocking_component": "state_restore",
                "failure_reason": "Startup state restore is still pending.",
            }
        )
        return payload

    blocking_background = [
        warning for warning in background_warnings if bool(warning.get("blocking"))
    ]
    if blocking_background:
        failure = blocking_background[0]
        payload.update(
            {
                "ready": False,
                "core_ready": True,
                "startup_phase": "background_executor_failed",
                "blocking_component": failure.get("name"),
                "failure_reason": failure.get("reason")
                or f"{failure.get('label') or failure.get('name')} is unavailable.",
            }
        )
        return payload

    payload.update(
        {
            "ready": True,
            "core_ready": True,
            "startup_phase": "ready",
            "blocking_component": None,
            "failure_reason": None,
        }
    )
    return payload


async def _run_startup_recovery_import_if_needed() -> None:
    if _is_scanner_local_ui_mode() or _master_journal_single_file_mode():
        return
    _set_trading_journal_sync_state(
        running=True,
        progress=10,
        message="Startup journal sync running…",
        ok=None,
        error=None,
        result=None,
    )
    oanda_recovery: Dict[str, object] = {}
    if _master_journal_single_file_mode():
        pass
    elif _trading_journal_excel_only_mode():
        _set_trading_journal_sync_state(message="Importing local journal workbooks…")
    elif not _trading_journal_local_excel_authoritative():
        for account in ("live", "demo"):
            try:
                oanda_recovery[account] = await _recover_oanda_recent_fills(account)
            except Exception as exc:
                oanda_recovery[account] = {"ok": False, "error": str(exc)}
        if ENABLE_BYBIT_DEMO_JOURNAL:
            try:
                await _run_bybit_closed_pnl_sync(account_mode="demo", reason="startup_recovery")
            except Exception:
                pass
    try:
        result = await asyncio.to_thread(_import_trading_journal_from_sources)
        workbook_sync = await asyncio.to_thread(_sync_master_journal_workbook, sync_caller="startup_recovery")
        if isinstance(result, dict):
            result.update(workbook_sync)
        else:
            result = dict(workbook_sync or {})
        import_ok = bool(result.get("ok", False)) if isinstance(result, dict) else False
        workbook_ok = bool((workbook_sync or {}).get("master_journal_ok"))
        github_sync_failed = bool(
            isinstance(workbook_sync, dict)
            and workbook_sync.get("github_sync_enabled")
            and workbook_sync.get("github_sync_ok") is False
        )
        ok_flag = bool(import_ok and workbook_ok and not github_sync_failed)
        startup_error = (
            str((workbook_sync or {}).get("master_journal_error") or (workbook_sync or {}).get("github_sync_error") or "").strip()
            or str((result or {}).get("message") or "Startup import failed.")
        )
        final_message = (
            "Startup journal sync complete. Trading Journal.xlsx created."
            if ok_flag
            else startup_error
        )
        diagnostics = result.get("diagnostics") if isinstance(result, dict) else {}
        rows_by_asset_class = diagnostics.get("rows_by_asset_class") if isinstance(diagnostics, dict) else {}
        _record_daily_trade_sync_status(
            last_attempt_at=_utc_now_iso(),
            last_success_at=_utc_now_iso() if ok_flag else None,
            last_error=None if ok_flag else startup_error,
            last_reason="startup_recovery",
            last_result={**(result or {}), "oanda_recovery": oanda_recovery},
        )
        _set_trading_journal_sync_state(
            running=False,
            progress=100,
            message=final_message,
            ok=ok_flag,
            error=None if ok_flag else startup_error,
            result=result,
            rows_imported=int((result or {}).get("rows_imported") or 0),
            rows_by_asset_class=rows_by_asset_class if isinstance(rows_by_asset_class, dict) else {},
            local_workbooks_seen=int((result or {}).get("local_workbooks_seen") or 0),
            dropbox_workbooks_seen=int((result or {}).get("dropbox_workbooks_seen") or 0),
            finished_at=_utc_now_iso(),
        )
    except Exception as exc:
        _record_daily_trade_sync_status(
            last_attempt_at=_utc_now_iso(),
            last_error=f"Startup import failed: {exc}",
            last_reason="startup_recovery",
            last_result={"oanda_recovery": oanda_recovery},
        )
        _set_trading_journal_sync_state(
            running=False,
            progress=100,
            message=f"Failed: {exc}",
            ok=False,
            error=str(exc),
            result={"oanda_recovery": oanda_recovery},
            rows_imported=0,
            rows_by_asset_class={},
            local_workbooks_seen=0,
            dropbox_workbooks_seen=0,
            finished_at=_utc_now_iso(),
        )


MONTHLY_AUD_REVAL_SYNC_INTERVAL_SECONDS = max(300, int(os.getenv("MONTHLY_AUD_REVAL_SYNC_INTERVAL_SECONDS", "3600") or "3600"))
STARTUP_RESTORE_WAIT_TIMEOUT_SECONDS = 120.0


async def _wait_for_startup_restore_signal(*, timeout: float, timeout_warning: str) -> bool:
    try:
        await asyncio.wait_for(_STARTUP_STATE_RESTORE_DONE.wait(), timeout=timeout)
        return True
    except asyncio.TimeoutError:
        BYBIT_LOGGER.warning(timeout_warning)
        return False


async def _run_monthly_aud_revaluation_sync(*, reason: str) -> Dict[str, object]:
    started_at = _utc_now_iso()
    try:
        result = await sync_monthly_aud_revaluation(
            data_path=MONTHLY_AUD_REVALUATION_PATH,
            state_path=MONTHLY_AUD_REVALUATION_STATE_PATH,
            bybit_live_credentials=resolve_bybit_credentials_for("live"),
            oanda_config_provider=_get_oanda_config,
            logger=BYBIT_LOGGER,
        )
        if result.get("changed"):
            _invalidate_trading_journal_view_snapshot()
            _TRADING_JOURNAL_VIEW_CACHE["key"] = None
            _TRADING_JOURNAL_VIEW_CACHE["payload"] = None
            _schedule_dropbox_upload_state_backup()
        state_snapshot = _load_json_file(MONTHLY_AUD_REVALUATION_STATE_PATH, {})
        return {"ok": True, "reason": reason, "started_at": started_at, "finished_at": _utc_now_iso(), "state": state_snapshot, **result}
    except MonthlyAudRevalError as exc:
        state_snapshot = _load_json_file(MONTHLY_AUD_REVALUATION_STATE_PATH, {})
        BYBIT_LOGGER.error("%s reason=%s stage=%s detail=%s", exc.code, reason, getattr(exc, "stage", None), exc)
        return {
            "ok": False,
            "reason": reason,
            "code": exc.code,
            "stage": getattr(exc, "stage", None),
            "error": str(exc),
            "state": state_snapshot,
            "started_at": started_at,
            "finished_at": _utc_now_iso(),
        }
    except Exception as exc:
        state_snapshot = _load_json_file(MONTHLY_AUD_REVALUATION_STATE_PATH, {})
        BYBIT_LOGGER.error("MONTHLY_AUD_REVAL_BYBIT_BALANCE_ERROR reason=%s detail=%s", reason, exc)
        return {
            "ok": False,
            "reason": reason,
            "code": "MONTHLY_AUD_REVAL_BYBIT_BALANCE_ERROR",
            "error": str(exc),
            "state": state_snapshot,
            "started_at": started_at,
            "finished_at": _utc_now_iso(),
        }


async def _schedule_monthly_aud_revaluation_sync() -> None:
    await _wait_for_startup_restore_signal(
        timeout=STARTUP_RESTORE_WAIT_TIMEOUT_SECONDS,
        timeout_warning="MONTHLY_AUD_REVAL_STARTUP_WAIT_TIMEOUT proceeding without restore signal",
    )
    await _run_monthly_aud_revaluation_sync(reason="startup")
    while True:
        await asyncio.sleep(MONTHLY_AUD_REVAL_SYNC_INTERVAL_SECONDS)
        await _run_monthly_aud_revaluation_sync(reason="hourly")


async def _start_bybit_demo_closed_pnl_poll_after_restore() -> None:
    await _wait_for_startup_restore_signal(
        timeout=STARTUP_RESTORE_WAIT_TIMEOUT_SECONDS,
        timeout_warning="BYBIT_DEMO_CLOSED_PNL_STARTUP_WAIT_TIMEOUT proceeding without restore signal",
    )
    await _poll_bybit_demo_closed_pnl()


async def _start_startup_recovery_import_after_restore() -> None:
    source_mode = str(TRADING_JOURNAL_SOURCE or "").strip().lower()
    if not (APP_PROFILE == "journal" or source_mode == "local" or (source_mode in {"both", "auto"} and not DROPBOX_SYNC_ENABLED)):
        await _wait_for_startup_restore_signal(
            timeout=STARTUP_RESTORE_WAIT_TIMEOUT_SECONDS,
            timeout_warning="STARTUP_RECOVERY_WAIT_TIMEOUT proceeding without restore signal",
        )
    await _run_startup_recovery_import_if_needed()


async def _run_daily_trade_history_sync(*, reason: str) -> Dict[str, object]:
    async with _DAILY_TRADE_SYNC_LOCK:
        started_at = _utc_now_iso()
        bybit_result: Dict[str, object] = {}
        oanda_result: Dict[str, object] = {}
        import_result: Optional[Dict[str, object]] = None
        errors: List[str] = []
        _record_daily_trade_sync_status(
            running=True,
            last_attempt_at=started_at,
            last_reason=reason,
            last_error=None,
        )

        if not _trading_journal_local_excel_authoritative() and not _master_journal_single_file_mode():
            for account in ("live", "demo"):
                try:
                    oanda_result[account] = await _recover_oanda_recent_fills(account)
                except Exception as exc:
                    errors.append(f"OANDA {account} recovery failed: {exc}")
                    oanda_result[account] = {"ok": False, "error": str(exc)}
            if ENABLE_BYBIT_DEMO_JOURNAL and not _master_journal_single_file_mode():
                try:
                    bybit_result["demo"] = await _run_bybit_closed_pnl_sync(account_mode="demo", reason=reason)
                except Exception as exc:
                    errors.append(f"Bybit demo sync failed: {exc}")
                    bybit_result["demo"] = {"ok": False, "error": str(exc)}
            if not _master_journal_single_file_mode():
                try:
                    bybit_result["live"] = await _run_bybit_closed_pnl_sync(account_mode="live", reason=reason)
                except Exception as exc:
                    errors.append(f"Bybit live sync failed: {exc}")
                    bybit_result["live"] = {"ok": False, "error": str(exc)}

        try:
            import_result = await asyncio.to_thread(_import_trading_journal_from_sources)
        except Exception as exc:
            errors.append(f"Dropbox workbook import failed: {exc}")
            import_result = {"ok": False, "error": str(exc)}

        import_ok = bool(import_result.get("ok", False)) if isinstance(import_result, dict) else False
        bybit_ok = all(bool(v.get("ok", False)) for v in bybit_result.values() if isinstance(v, dict))
        ok_flag = import_ok and bybit_ok and not errors
        monthly_result = await _run_monthly_aud_revaluation_sync(reason=f"daily:{reason}")

        finished_at = _utc_now_iso()
        _record_daily_trade_sync_status(
            running=False,
            last_reason=reason,
            last_attempt_at=started_at,
            last_success_at=finished_at if ok_flag else None,
            last_error="; ".join(errors) if errors else None,
            last_result={
                "ok": ok_flag,
                "bybit": bybit_result,
                "oanda": oanda_result,
                "import": import_result,
                "errors": errors,
                "monthly_aud_revaluation": monthly_result,
                "started_at": started_at,
                "finished_at": finished_at,
            },
        )
        return {
            "ok": ok_flag,
            "bybit": bybit_result,
            "oanda": oanda_result,
            "import": import_result,
            "errors": errors,
            "started_at": started_at,
            "finished_at": finished_at,
        }


async def _schedule_daily_trade_history_sync() -> None:
    if not DAILY_TRADE_SYNC_ENABLED:
        _record_daily_trade_sync_status(running=False, last_reason="disabled")
        return
    while True:
        try:
            now_local = datetime.now(ZoneInfo(DAILY_TRADE_SYNC_TIMEZONE))
        except Exception:
            now_local = datetime.now(ZoneInfo("Australia/Brisbane"))
        target_local = now_local.replace(
            hour=DAILY_TRADE_SYNC_HOUR,
            minute=DAILY_TRADE_SYNC_MINUTE,
            second=0,
            microsecond=0,
        )
        if target_local <= now_local:
            target_local = target_local + timedelta(days=1)
        sleep_seconds = max(5.0, (target_local - now_local).total_seconds())
        await asyncio.sleep(sleep_seconds)
        try:
            await _run_daily_trade_history_sync(reason="daily")
        except Exception as exc:
            _record_daily_trade_sync_status(
                running=False,
                last_attempt_at=_utc_now_iso(),
                last_error=f"Daily sync failed: {exc}",
                last_reason="daily",
            )


_SCANNER_SUPERVISOR_BACKOFF: Dict[str, float] = {}
_SCANNER_SUPERVISOR_BACKOFF_WINDOW: Dict[str, float] = {}
_SCANNER_SUPERVISOR_BASE_SECONDS = float(os.getenv("SCANNER_SUPERVISOR_BASE_SECONDS", "20") or 20)
_SCANNER_SUPERVISOR_MAX_BACKOFF_SECONDS = float(os.getenv("SCANNER_SUPERVISOR_MAX_BACKOFF_SECONDS", "300") or 300)


def _scanner_has_external_live_runtime(script_name: str) -> bool:
    if script_name == "bybit_monitor":
        payload = _scanner_status_payload(BYBIT_RUNTIME_STATUS_PATH)
    elif script_name == "oanda_monitor":
        payload = _scanner_status_payload(OANDA_RUNTIME_STATUS_PATH)
    else:
        return False
    if str(payload.get("ui_status")) != "running":
        return False
    runtime_pid = payload.get("pid")
    script_pid = None
    try:
        script_pid = script_manager.get(script_name).pid
    except Exception:
        pass
    return runtime_pid is not None and runtime_pid != script_pid


def _managed_script_log(script: object, message: str) -> None:
    add_log = getattr(script, "add_log", None)
    if callable(add_log):
        add_log(message)


def _managed_script_summary(script: object) -> Dict[str, object]:
    to_summary = getattr(script, "to_summary", None)
    if callable(to_summary):
        summary = to_summary()
        if isinstance(summary, dict):
            return summary
    return {
        "running": bool(getattr(script, "is_running", False)),
        "starting": bool(getattr(script, "is_starting", False)),
        "pid": getattr(script, "pid", None),
        "startup_started_at": getattr(script, "startup_started_at", None),
    }


def _confirm_fxweekend_operational_lifecycle(
    script: ManagedScript,
    *,
    settings: Dict[str, object],
    runtime: Dict[str, object],
    heartbeat: Dict[str, object],
) -> None:
    """Emit each successful FX executor lifecycle milestone once per PID."""

    pid = getattr(script, "pid", None)
    if not pid:
        return
    if getattr(script, "heartbeat_confirmed_pid", None) != pid:
        script.heartbeat_confirmed_pid = pid
        if getattr(script, "is_starting", False):
            script.is_starting = False
            script.startup_completed_at = time.time()
        AUTOSTART_LOGGER.info(
            "FX_WEEKEND_HEARTBEAT_CONFIRMED pid=%s heartbeat_at=%s "
            "age_seconds=%s stale_after_seconds=%s",
            pid,
            heartbeat.get("heartbeat_at"),
            heartbeat.get("heartbeat_age_seconds"),
            heartbeat.get("stale_after_seconds"),
        )
        _managed_script_log(
            script,
            "Scheduler heartbeat confirmed "
            f"for PID {pid} at {heartbeat.get('heartbeat_at')}.",
        )

    component = _autostart_component_readiness(
        "fxweekend-clone",
        summary_override=_managed_script_summary(script),
    )
    if (
        bool(settings.get("enabled", True))
        and bool(component.get("ready"))
        and getattr(script, "operational_started_pid", None) != pid
    ):
        script.operational_started_pid = pid
        AUTOSTART_LOGGER.info(
            "FX_WEEKEND_OPERATIONAL_STARTUP pid=%s executor_started_at=%s "
            "health_state=%s runtime_state=%s",
            pid,
            runtime.get("executor_started_at"),
            component.get("health_state"),
            runtime.get("state"),
        )
        _managed_script_log(
            script,
            "FX Weekend operational startup confirmed "
            f"for PID {pid} ({component.get('health_state')}).",
        )


async def _supervise_autostart_scripts_once(
    autostart_targets: List[str],
) -> None:
    for name in autostart_targets:
        try:
            script = script_manager.get(name)
        except HTTPException:
            continue
        if name == "fxweekend-clone":
            allowed, gate_error = _fxweekend_start_gate()
            if not allowed:
                if script.is_running:
                    stop_reason = (
                        "authoritative-state gate blocked execution: "
                        f"{gate_error}"
                    )
                    script.last_exit_reason = stop_reason
                    _managed_script_log(
                        script,
                        "FX Weekend termination requested: "
                        f"{stop_reason}",
                    )
                    AUTOSTART_LOGGER.error(
                        "FX_WEEKEND_RESTART_REQUIRED pid=%s reason=%s",
                        getattr(script, "pid", None),
                        stop_reason,
                    )
                    await script.stop()
                if script.last_start_error != gate_error:
                    _managed_script_log(
                        script,
                        "FX Weekend executor start blocked by "
                        f"authoritative-state gate: {gate_error}",
                    )
                    AUTOSTART_LOGGER.error(
                        "FX_WEEKEND_START_BLOCKED reason=%s",
                        gate_error,
                    )
                script.last_start_error = gate_error
                continue
            try:
                await asyncio.to_thread(_persist_fxweekend_status_if_changed)
            except Exception as exc:
                AUTOSTART_LOGGER.error(
                    "FX Weekend durable status persistence failed: %s", exc
                )
            if script.is_running and _fxweekend_enabled():
                settings = _load_json_file(
                    FXWEEKEND_SETTINGS_PATH,
                    FXWEEKEND_DEFAULT_SETTINGS,
                )
                runtime = _load_json_file(FXWEEKEND_STATUS_PATH, {})
                settings = settings if isinstance(settings, dict) else {}
                runtime = runtime if isinstance(runtime, dict) else {}
                heartbeat = _fxweekend_heartbeat_diagnostics(
                    settings if isinstance(settings, dict) else None,
                    runtime if isinstance(runtime, dict) else None,
                    expected_pid=getattr(script, "pid", None),
                    expected_instance_id=getattr(
                        script, "executor_instance_id", None
                    ),
                )
                if not bool(heartbeat["fresh"]):
                    startup_grace = _fxweekend_heartbeat_startup_grace(
                        _managed_script_summary(script)
                    )
                    if bool(startup_grace["active"]):
                        _managed_script_log(
                            script,
                            "Waiting for the current FX Weekend child "
                            f"PID {getattr(script, 'pid', None)} to publish "
                            "its first heartbeat "
                            f"(startup grace remaining "
                            f"{startup_grace.get('remaining_seconds')}s).",
                        )
                        continue
                    stale_reason = (
                        "scheduler heartbeat missing, stale, or owned by a "
                        "different executor instance "
                        f"(heartbeat_at={heartbeat.get('heartbeat_at')}, "
                        f"age_seconds={heartbeat.get('heartbeat_age_seconds')}, "
                        f"stale_after_seconds={heartbeat.get('stale_after_seconds')}, "
                        f"managed_pid={getattr(script, 'pid', None)}, "
                        f"runtime_pid={heartbeat.get('executor_pid')}, "
                        f"pid_matches={heartbeat.get('pid_matches')}, "
                        f"instance_matches={heartbeat.get('instance_matches')})"
                    )
                    script.last_exit_reason = stale_reason
                    _managed_script_log(
                        script,
                        "FX Weekend termination requested: "
                        f"{stale_reason}",
                    )
                    AUTOSTART_LOGGER.error(
                        "FX_WEEKEND_RESTART_REQUIRED pid=%s reason=%s",
                        getattr(script, "pid", None),
                        stale_reason,
                    )
                    await script.stop()
                    _SCANNER_SUPERVISOR_BACKOFF.pop(name, None)
                    _SCANNER_SUPERVISOR_BACKOFF_WINDOW.pop(name, None)
                    continue
                _confirm_fxweekend_operational_lifecycle(
                    script,
                    settings=settings,
                    runtime=runtime,
                    heartbeat=heartbeat,
                )
        if script.is_running:
            _SCANNER_SUPERVISOR_BACKOFF.pop(name, None)
            continue
        startup_task = getattr(script, "startup_task", None)
        if startup_task is not None and not startup_task.done():
            continue
        is_scanner = name in {"bybit_monitor", "oanda_monitor"}
        if is_scanner and _scanner_has_external_live_runtime(name):
            continue
        now = time.time()
        retry_after = _SCANNER_SUPERVISOR_BACKOFF.get(name, 0.0)
        if retry_after and now < retry_after:
            continue
        supervisor_label = "Alerts supervisor" if is_scanner else "Autostart supervisor"
        restart_reason = str(
            getattr(script, "last_exit_reason", None)
            or getattr(script, "last_start_error", None)
            or "managed child is not running"
        ).strip()
        if name == "fxweekend-clone":
            _managed_script_log(
                script,
                "FX Weekend restart requested: "
                f"{restart_reason}",
            )
            AUTOSTART_LOGGER.warning(
                "FX_WEEKEND_RESTART_REQUESTED reason=%s",
                restart_reason,
            )
        else:
            AUTOSTART_LOGGER.warning("%s restarting %s", supervisor_label, name)
        try:
            await script.start()
            _SCANNER_SUPERVISOR_BACKOFF.pop(name, None)
            _SCANNER_SUPERVISOR_BACKOFF_WINDOW.pop(name, None)
        except Exception as exc:
            prev_wait = _SCANNER_SUPERVISOR_BACKOFF_WINDOW.get(name, 0.0)
            current_wait = 15.0 if prev_wait <= 0 else min(_SCANNER_SUPERVISOR_MAX_BACKOFF_SECONDS, prev_wait * 2.0)
            _SCANNER_SUPERVISOR_BACKOFF_WINDOW[name] = current_wait
            _SCANNER_SUPERVISOR_BACKOFF[name] = now + current_wait
            AUTOSTART_LOGGER.error("%s failed to restart %s: %s", supervisor_label, name, exc)


async def _supervise_autostart_scripts(names: List[str]) -> None:
    supervised_names = (
        {"bybit_monitor", "oanda_monitor"}
        if APP_PROFILE == "local"
        else {"fxweekend-clone"}
        if APP_PROFILE == "render"
        else set()
    )
    autostart_targets = [
        name
        for name in dict.fromkeys(names)
        if name in supervised_names
    ]
    if not autostart_targets:
        return
    while True:
        await asyncio.sleep(max(15.0, _SCANNER_SUPERVISOR_BASE_SECONDS))
        await _supervise_autostart_scripts_once(autostart_targets)


@app.on_event("startup")
async def _autostart_scripts() -> None:
    AUTOSTART_LOGGER.info(format_env_bootstrap_log(_MASTER_ENV_INFO))
    AUTOSTART_LOGGER.info(
        "Local state mode: LOCAL_STATE_ONLY=%s effective_mode=%s env_loaded_file=%s",
        LOCAL_STATE_ONLY,
        _state_sync_status_snapshot().get("effective_local_state_mode"),
        _MASTER_ENV_INFO.get("loaded_file") or "<none>",
    )
    if APP_PROFILE == "local" and not DROPBOX_SYNC_ENABLED and not LOCAL_STATE_ONLY:
        _update_state_sync_status(
            enabled=False,
            restore_complete=True,
            restore_status="failed",
            restore_error="Dropbox sync is disabled; set LOCAL_STATE_ONLY=1 for explicit local-only mode.",
        )
        _STARTUP_STATE_RESTORE_DONE.set()
        raise RuntimeError("Dropbox sync is disabled; set LOCAL_STATE_ONLY=1 for explicit local-only mode.")
    AUTOSTART_LOGGER.info(
        "State sync startup: DROPBOX_SYNC_ENABLED=%s DROPBOX_BACKUP_PATH=%s env_loaded_file=%s",
        DROPBOX_SYNC_ENABLED,
        DROPBOX_BACKUP_PATH,
        _MASTER_ENV_INFO.get("loaded_file") or "<none>",
    )
    calc_host = _render_calculator_host()
    calc_mode = "remote_render" if (APP_PROFILE == "local" and calc_host and not _is_local_host(calc_host)) else "same_instance"
    calc_endpoint = (str(os.getenv("RENDER_CALCULATOR_BASE_URL") or "").strip().rstrip("/") + "/api/calculator/webhook") if calc_mode == "remote_render" else "<same-instance>"
    AUTOSTART_LOGGER.info(
        "CALCULATOR_WEBHOOK_MODE mode=%s endpoint=%s owner=%s env_loaded_file=%s",
        calc_mode,
        calc_endpoint,
        "remote_render" if calc_mode == "remote_render" else "same_instance",
        _MASTER_ENV_INFO.get("loaded_file") or "<none>",
    )
    if _is_scanner_local_ui_mode():
        local_state_mode = _state_backup_uses_local_repo_file()
        _update_state_sync_status(
            enabled=bool(DROPBOX_SYNC_ENABLED or local_state_mode),
            restore_complete=not bool(DROPBOX_SYNC_ENABLED or local_state_mode),
            restore_status="pending" if bool(DROPBOX_SYNC_ENABLED or local_state_mode) else "skipped",
            restore_error=None,
            backup_path=_state_backup_display_path(),
        )
        if DROPBOX_SYNC_ENABLED or local_state_mode:
            asyncio.create_task(_dropbox_restore_state_backup_on_startup())
        else:
            _STARTUP_STATE_RESTORE_DONE.set()
        AUTOSTART_LOGGER.info(
            "SCANNER_LOCAL_UI_MODE=1: skipping non-scanner startup tasks and script autostart."
        )
        asyncio.create_task(_log_outbound_traffic_summary())
        asyncio.create_task(_poll_pending_webhook_invalidations())
        return

    _restore_bybit_closed_pnl_last_seen_from_state()
    _restore_oanda_fill_state_on_startup()
    _set_trading_journal_sync_state(
        running=True,
        progress=0,
        message="Startup journal sync queued…",
        ok=None,
        error=None,
        started_at=_utc_now_iso(),
        finished_at=None,
    )
    _update_state_sync_status(
        enabled=bool(DROPBOX_SYNC_ENABLED or _state_backup_uses_local_repo_file()),
        restore_complete=not bool(DROPBOX_SYNC_ENABLED or _state_backup_uses_local_repo_file()),
        restore_status="pending" if bool(DROPBOX_SYNC_ENABLED or _state_backup_uses_local_repo_file()) else "skipped",
        restore_error=None,
        backup_path=_state_backup_display_path(),
    )
    if (not DROPBOX_SYNC_ENABLED) and (not _state_backup_uses_local_repo_file()):
        _STARTUP_STATE_RESTORE_DONE.set()
    asyncio.create_task(_dropbox_restore_state_backup_on_startup())
    if _master_journal_single_file_mode():
        pass
    elif TRADING_JOURNAL_SOURCE == "local":
        try:
            _ensure_trading_journal_local_templates()
        except Exception as exc:
            BYBIT_LOGGER.error("Local journal template ensure failed: %s", exc)
    else:
        asyncio.create_task(_ensure_trading_journal_dropbox_templates())
    asyncio.create_task(_log_outbound_traffic_summary())
    global TRADING_JOURNAL_SYNC_TASK
    if _master_journal_single_file_mode():
        _set_trading_journal_sync_state(
            running=False,
            progress=100,
            message="Startup workbook sync skipped; equity cache build queued.",
            ok=True,
            error=None,
            result={
                "startup_sync_skipped": True,
                "equity_cache_queued": True,
                "reason": "master_journal_single_file_mode",
            },
            finished_at=_utc_now_iso(),
        )
        TRADING_JOURNAL_SYNC_TASK = None
        asyncio.create_task(_start_master_journal_equity_cache_after_restore())
    else:
        TRADING_JOURNAL_SYNC_TASK = asyncio.create_task(_start_startup_recovery_import_after_restore())
    if (not _trading_journal_excel_only_mode()) and (not _master_journal_single_file_mode()):
        asyncio.create_task(_schedule_daily_trade_history_sync())
    asyncio.create_task(_schedule_monthly_aud_revaluation_sync())
    asyncio.create_task(_poll_pending_webhook_invalidations())
    if (not _trading_journal_excel_only_mode()) and (not _master_journal_single_file_mode()) and ENABLE_BYBIT_DEMO_JOURNAL and ENABLE_BYBIT_DEMO_CLOSED_PNL_POLL:
        asyncio.create_task(_start_bybit_demo_closed_pnl_poll_after_restore())
    if not ENABLE_BYBIT_DEMO_JOURNAL:
        _purge_bybit_demo_journal_state()
    if (not _trading_journal_excel_only_mode()) and (not _master_journal_single_file_mode()) and os.getenv("ENABLE_BYBIT_FILL_POLL", "0") == "1":
        asyncio.create_task(_poll_bybit_fills())
    if (not _master_journal_single_file_mode()) and os.getenv("ENABLE_OANDA_FILL_POLL", "0") == "1":
        asyncio.create_task(_start_oanda_fill_poll_after_delay())
    _start_manual_save_github_sync_watcher_if_needed()
    autostart_targets = _compute_autostart_scripts()
    AUTOSTART_LOGGER.info(
        "Resolved autostart scripts: %s",
        ", ".join(autostart_targets) if autostart_targets else "(none)",
    )
    for name in autostart_targets:
        try:
            script = script_manager.get(name)
        except HTTPException:
            continue

        if script.is_running:
            continue

        if script.name in WEB_APPS and script.port is None:
            script.port = _allocate_port()

        if script.startup_task is None or script.startup_task.done():
            starter = (
                _background_start_after_state_restore(script)
                if script.name == "fxweekend-clone"
                else _background_start(script)
            )
            script.startup_task = asyncio.create_task(starter)
    asyncio.create_task(_supervise_autostart_scripts(autostart_targets))


@app.on_event("shutdown")
async def _log_local_master_shutdown() -> None:
    _stop_manual_save_github_sync_watcher()
    AUTOSTART_LOGGER.error(
        "LOCAL_MASTER_SHUTDOWN profile=%s scripts=%s",
        APP_PROFILE,
        script_manager.list_scripts(),
    )


def _log_local_master_atexit() -> None:
    try:
        for handler in getattr(AUTOSTART_LOGGER, "handlers", []):
            stream = getattr(handler, "stream", None)
            if stream is not None and getattr(stream, "closed", False):
                return
        AUTOSTART_LOGGER.error("LOCAL_MASTER_ATEXIT profile=%s", APP_PROFILE)
    except Exception:
        pass


if os.getenv("LOCAL_MASTER_LOG_ATEXIT", "").strip().lower() in {"1", "true", "yes"}:
    atexit.register(_log_local_master_atexit)


async def _start_oanda_fill_poll_after_delay() -> None:
    await asyncio.sleep(5)
    await _poll_oanda_fills()


async def _fetch_oanda_transactions_window(
    *, account_id: str, api_key: str, base_url: str, start: str, end: str
) -> List[Dict[str, object]]:
    if oanda_history_exporter is None:
        raise RuntimeError("OANDA history exporter module not available.")
    return await asyncio.to_thread(
        oanda_history_exporter.fetch_transactions,
        account_id,
        api_key,
        start,
        end,
        base_url,
    )


async def _collect_oanda_history_complete(
    *, account_id: str, api_key: str, base_url: str
) -> List[Dict[str, object]]:
    created_time = await _fetch_oanda_account_created_time(
        base_url=base_url,
        account_id=account_id,
        api_key=api_key,
    )
    now = datetime.now(timezone.utc)
    end = now
    transactions: List[Dict[str, object]] = []
    seen_ids: set[object] = set()
    window = timedelta(days=365)

    def append_unique(items: List[Dict[str, object]]) -> None:
        for item in items:
            tx_id = item.get("id")
            if tx_id is not None:
                if tx_id in seen_ids:
                    continue
                seen_ids.add(tx_id)
            transactions.append(item)

    while end > created_time:
        start = max(created_time, end - window)
        batch = await _fetch_oanda_transactions_window(
            account_id=account_id,
            api_key=api_key,
            base_url=base_url,
            start=_format_oanda_timestamp(start),
            end=_format_oanda_timestamp(end),
        )
        append_unique(batch)
        end = start

    return transactions


async def _collect_oanda_history_range(
    *,
    account_id: str,
    api_key: str,
    base_url: str,
    start: datetime,
    end: datetime,
) -> List[Dict[str, object]]:
    """Collect OANDA transactions over an arbitrary time range by splitting into <=365-day windows."""
    transactions: List[Dict[str, object]] = []
    seen_ids: set[object] = set()
    window = timedelta(days=365)
    current_end = end

    def append_unique(items: List[Dict[str, object]]) -> None:
        for item in items:
            tx_id = item.get("id")
            if tx_id is not None:
                if tx_id in seen_ids:
                    continue
                seen_ids.add(tx_id)
            transactions.append(item)

    while current_end > start:
        current_start = max(start, current_end - window)
        batch = await _fetch_oanda_transactions_window(
            account_id=account_id,
            api_key=api_key,
            base_url=base_url,
            start=_format_oanda_timestamp(current_start),
            end=_format_oanda_timestamp(current_end),
        )
        append_unique(batch)
        current_end = current_start

    return transactions


async def _run_oanda_history_export(job: OandaHistoryJob) -> None:
    job.status = "running"
    job.updated_at = time.time()
    try:
        if oanda_history_exporter is None:
            raise RuntimeError("OANDA history exporter module not available.")
        account_mode = str(job.params.get("account") or "").strip().lower()
        if account_mode not in {"live", "demo"}:
            raise ValueError("Bybit export requires explicit account=live|demo.")
        config = _get_oanda_history_config(account_mode)

        period = _normalize_period(job.params.get("period"))
        complete = bool(job.params.get("complete")) or period == "complete"

        if complete:
            transactions = await _collect_oanda_history_complete(
                account_id=config["account_id"],
                api_key=config["api_key"],
                base_url=config["base_url"],
            )
        else:
            end_dt = datetime.now(timezone.utc)

            if period:
                delta = OANDA_PERIOD_DELTAS.get(period)
                if delta is None:
                    raise ValueError(f"Unsupported period: {period}")
                start_dt = end_dt - delta
            else:
                days_value = job.params.get("days", 0)
                try:
                    days = int(days_value)
                except (TypeError, ValueError) as exc:
                    raise ValueError("Export days must be a positive integer.") from exc
                if days <= 0:
                    raise ValueError("Export days must be a positive integer.")
                start_dt = end_dt - timedelta(days=days)

            # OANDA's time-based transactions query supports a maximum window of 365 days.
            # Split larger periods into yearly windows (same approach as "complete").
            if end_dt - start_dt > timedelta(days=365):
                transactions = await _collect_oanda_history_range(
                    account_id=config["account_id"],
                    api_key=config["api_key"],
                    base_url=config["base_url"],
                    start=start_dt,
                    end=end_dt,
                )
            else:
                transactions = await _fetch_oanda_transactions_window(
                    account_id=config["account_id"],
                    api_key=config["api_key"],
                    base_url=config["base_url"],
                    start=_format_oanda_timestamp(start_dt),
                    end=_format_oanda_timestamp(end_dt),
                )

        output_path = OANDA_HISTORY_EXPORT_ROOT / f"oanda_history_{account_mode}_{job.job_id}.csv"
        await asyncio.to_thread(oanda_history_exporter.save_to_csv, transactions, output_path)
        if not output_path.exists():
            raise RuntimeError("OANDA history export failed to write CSV output.")
        sidecar_path = output_path.with_suffix(".json")
        _save_json_file(
            sidecar_path,
            {
                "job_id": job.job_id,
                "account_mode": account_mode,
                "account_label": "OANDA DEMO" if account_mode == "demo" else "OANDA LIVE",
                "created_at": _utc_now_iso(),
                "source": "oanda_history_export",
                "csv_filename": output_path.name,
            },
        )
        job.output_path = output_path
        job.status = "done"
    except Exception as exc:
        BYBIT_LOGGER.exception("OANDA history export job failed id=%s error=%s", job.job_id, exc)
        job.status = "error"
        job.error = _sanitize_oanda_history_error(exc)
    finally:
        job.updated_at = time.time()


def _date_range_for_days(days: int) -> tuple[str, str]:
    end = datetime.now(timezone.utc)
    start = end - timedelta(days=days)
    return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")


OANDA_PERIOD_DELTAS: Dict[str, relativedelta] = {
    "day": relativedelta(days=1),
    "week": relativedelta(days=7),
    "month": relativedelta(months=1),
    "year": relativedelta(years=1),
    "3y": relativedelta(years=3),
}

BYBIT_PERIOD_DELTAS: Dict[str, relativedelta] = {
    "day": relativedelta(days=1),
    "week": relativedelta(days=7),
    "month": relativedelta(months=1),
    "year": relativedelta(years=1),
    "3y": relativedelta(years=3),
}


def _normalize_period(value: object) -> Optional[str]:
    if value is None:
        return None
    if not isinstance(value, str):
        return None
    period = value.strip().casefold()
    if period in {"day", "week", "month", "year", "3y", "complete"}:
        return period
    return None


def _date_range_for_period(period: str, *, max_days: Optional[int] = None) -> tuple[str, str]:
    """Return YYYY-MM-DD start/end for a named period.

    - period: day | week | month | year | 3y | complete
    - max_days: optional clamp for providers with a hard retention limit (e.g. Bybit 2 years).
    """
    end = datetime.now(timezone.utc)
    if period == "complete":
        if max_days is None:
            # Caller will handle true "complete" (e.g. OANDA uses account creation time).
            start = end
        else:
            start = end - timedelta(days=max_days)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    delta = OANDA_PERIOD_DELTAS.get(period)
    if delta is None:
        raise ValueError(f"Unknown period: {period}")
    start = end - delta

    if max_days is not None:
        earliest = end - timedelta(days=max_days)
        if start < earliest:
            start = earliest

    return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")


async def _run_bybit_history_export(job: BybitHistoryJob) -> None:
    job.status = "running"
    job.updated_at = time.time()
    try:
        if bybit_history_fetcher is None:
            raise RuntimeError("Bybit history exporter module not available.")

        account_mode = str(job.params.get("account") or "").strip().lower()
        if account_mode not in {"live", "demo"}:
            raise ValueError("Bybit export requires explicit account=live|demo.")
        period = _normalize_period(job.params.get("period"))
        complete = bool(job.params.get("complete")) or period == "complete"

        # Bybit Demo Trading only retains ~7 days of orders/executions.
        # Live/Testnet supports up to ~2 years.
        max_days = 730
        if account_mode == "demo":
            max_days = 7

        if complete:
            start_date, end_date = _date_range_for_period("complete", max_days=max_days)
        elif period:
            start_date, end_date = _date_range_for_period(period, max_days=max_days)
        else:
            days_value = job.params.get("days")
            if days_value is None:
                raise ValueError("days is required unless complete is true.")
            try:
                days = int(days_value)
            except (TypeError, ValueError) as exc:
                raise ValueError("days must be an integer.") from exc
            if days <= 0:
                raise ValueError("days must be greater than zero.")
            # Clamp to the Bybit API retention window.
            if days > max_days:
                days = max_days
            start_date, end_date = _date_range_for_days(days)

        def _export() -> Path:
            import shutil
            import tempfile
            from pathlib import Path

            with tempfile.TemporaryDirectory() as tmp:
                tmp_path = Path(tmp)
                prev_cwd = os.getcwd()
                prev_env = os.environ.get("BYBIT_ENV")
                if account_mode in {"demo", "testnet", "paper"}:
                    os.environ["BYBIT_ENV"] = account_mode
                else:
                    os.environ["BYBIT_ENV"] = "live"
                os.chdir(tmp)
                try:
                    target_mode = os.environ["BYBIT_ENV"]
                    _mode, _key, _secret, _base_url, key_source = (
                        resolve_bybit_credentials_for(target_mode)
                    )
                    if target_mode in {"testnet", "demo", "paper"} and key_source == "LEGACY":
                        raise RuntimeError(
                            "DEMO/Testnet export requires BYBIT_API_KEY2 and "
                            "BYBIT_API_SECRET2 (testnet keypair). Live/legacy keys "
                            "cannot authenticate on testnet."
                        )
                    filename = bybit_history_fetcher.download_history(
                        "linear",
                        start_date,
                        end_date,
                        None,
                        True,
                    )
                finally:
                    os.chdir(prev_cwd)
                    if prev_env is None:
                        os.environ.pop("BYBIT_ENV", None)
                    else:
                        os.environ["BYBIT_ENV"] = prev_env
                if filename is None:
                    raise RuntimeError("No transactions found for the selected timeframe.")
                src = tmp_path / filename
                if not src.exists():
                    raise RuntimeError("Export was generated but could not be found on disk.")
                dest = BYBIT_HISTORY_EXPORT_ROOT / f"bybit_history_{job.job_id}.csv"
                shutil.move(str(src), dest)
                return dest

        output_path = await asyncio.to_thread(_export)
        job.output_path = output_path
        job.status = "done"
    except Exception as exc:
        job.status = "error"
        job.error = str(exc)
    finally:
        job.updated_at = time.time()


async def _run_coinspot_history_export(job: CoinspotHistoryJob) -> None:
    job.status = "running"
    job.updated_at = time.time()
    try:
        if coinspot_history_exporter is None:
            raise RuntimeError("CoinSpot history exporter module not available.")

        period = _normalize_period(job.params.get("period"))
        complete = bool(job.params.get("complete")) or period == "complete"

        if complete:
            start_date, end_date = None, None
        elif period:
            start_date, end_date = _date_range_for_period(period)
        else:
            days_value = job.params.get("days")
            if days_value is None:
                raise ValueError("days is required unless complete is true.")
            try:
                days = int(days_value)
            except (TypeError, ValueError) as exc:
                raise ValueError("days must be an integer.") from exc
            if days <= 0:
                raise ValueError("days must be greater than zero.")
            start_date, end_date = _date_range_for_days(days)

        def _export() -> Path:
            import shutil
            import tempfile
            from pathlib import Path

            dest = COINSPOT_HISTORY_EXPORT_ROOT / f"coinspot_history_{job.job_id}.zip"
            with tempfile.TemporaryDirectory() as tmp:
                tmp_path = Path(tmp)
                zip_path = tmp_path / dest.name
                coinspot_history_exporter.export_zip(
                    start_date,
                    end_date,
                    output_path=zip_path,
                )
                shutil.move(str(zip_path), dest)
            return dest

        output_path = await asyncio.to_thread(_export)
        job.output_path = output_path
        job.status = "done"
    except Exception as exc:
        job.status = "error"
        job.error = str(exc)
    finally:
        job.updated_at = time.time()


