PROXY_METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "HEAD"]
PROXY_HOP_HEADERS = {
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailers",
    "transfer-encoding",
    "upgrade",
}
PROXY_STRIP_HEADERS = {"content-encoding", "content-length"}
PROXY_LOGGER = logging.getLogger("uvicorn.error")
try:
    FXWEEKEND_RUN_NOW_PROXY_TIMEOUT_SECONDS = max(
        30.0,
        float(
            os.getenv(
                "FXWEEKEND_RUN_NOW_PROXY_TIMEOUT_SECONDS",
                "600",
            )
            or 600
        ),
    )
except (TypeError, ValueError):
    FXWEEKEND_RUN_NOW_PROXY_TIMEOUT_SECONDS = 600.0


def _app_proxy_timeout_seconds(
    script_name: str,
    path: str,
    method: str,
) -> float:
    if (
        str(script_name).strip() == "fxweekend-clone"
        and str(path).strip("/") == "api/run_now"
        and str(method).strip().upper() == "POST"
    ):
        return FXWEEKEND_RUN_NOW_PROXY_TIMEOUT_SECONDS
    return 30.0


def _normalize_bybit_recv_window_ms(raw_value: Optional[str]) -> int:
    fallback = 15000
    try:
        parsed = int(str(raw_value or fallback).strip())
    except (TypeError, ValueError):
        parsed = fallback
    return max(1000, min(60000, parsed))


def _safe_int_env(raw_value: Optional[str], default: int) -> int:
    try:
        return int(str(raw_value or default).strip())
    except (TypeError, ValueError):
        return default


BYBIT_RECV_WINDOW_MS = _normalize_bybit_recv_window_ms(os.getenv("BYBIT_RECV_WINDOW", "15000"))
BYBIT_SIGNED_REQUEST_MAX_RETRIES = max(
    1,
    min(3, _safe_int_env(os.getenv("BYBIT_SIGNED_REQUEST_MAX_RETRIES", "2"), 2)),
)
BYBIT_TIME_OFFSET_TTL_SECONDS = max(
    10,
    _safe_int_env(os.getenv("BYBIT_TIME_OFFSET_TTL_SECONDS", "300"), 300),
)
_BYBIT_TIME_OFFSET_CACHE: Dict[str, Dict[str, int]] = {}
BYBIT_OPTIONS_TAKER_FEE_RATE = float(os.getenv("BYBIT_OPTIONS_TAKER_FEE_RATE", "0.0003"))
BYBIT_OPTIONS_MAKER_FEE_RATE = float(os.getenv("BYBIT_OPTIONS_MAKER_FEE_RATE", "0.0002"))


def _instrument_lookup_key(value: str) -> str:
    return "".join(ch for ch in (value or "").upper() if ch.isalnum())


def _normalize_oanda_symbol_query(user_value: str, available_instruments: Optional[List[str]] = None) -> str:
    if not user_value or not user_value.strip():
        raise ValueError("Instrument is required")

    raw = user_value.strip().upper()
    if "_" in raw and len(raw) >= 7:
        return raw

    lookup = _instrument_lookup_key(raw)
    if available_instruments:
        mapping = {_instrument_lookup_key(inst): inst for inst in available_instruments if inst}
        if lookup in mapping:
            return mapping[lookup]

    if len(lookup) == 6 and lookup.isalpha():
        return f"{lookup[:3]}_{lookup[3:]}"
    return raw


def _oanda_base_url() -> str:
    raw = (
        os.getenv("OANDA_BASE_URL")
        or os.getenv("OANDA_URL")
        or os.getenv("OANDA_API_URL")
        or ""
    ).strip()
    if raw:
        return _normalize_oanda_base_url(raw)

    env = (os.getenv("OANDA_ENV") or "live").strip().lower()
    if env in {"practice", "demo", "test"}:
        return "https://api-fxpractice.oanda.com"
    return "https://api-fxtrade.oanda.com"


def _normalize_oanda_base_url(value: Optional[str]) -> str:
    base = (value or "").strip().rstrip("/")
    if base.endswith("/v3"):
        base = base[: -len("/v3")]
    return base


def _normalize_oanda_v3_base_url(value: Optional[str]) -> tuple[str, bool]:
    base = _normalize_oanda_base_url(value)
    parsed = urlparse(base)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ValueError(f"Invalid OANDA API base URL: {value or '(empty)'}")
    normalized_base = f"{parsed.scheme}://{parsed.netloc}{parsed.path.rstrip('/')}"
    return f"{normalized_base}/v3", base != normalized_base


def _build_oanda_v3_url(base_url: str, endpoint: str, **path_params: object) -> str:
    raw_base = (base_url or "").strip().rstrip("/")
    parsed = urlparse(raw_base)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ValueError(f"Invalid OANDA API base URL: {base_url or '(empty)'}")

    normalized_path = parsed.path.rstrip("/")
    while normalized_path.endswith("/v3"):
        normalized_path = normalized_path[: -len("/v3")]

    raw_endpoint = endpoint or ""
    formatted_endpoint = raw_endpoint.format(**path_params) if path_params else raw_endpoint
    formatted_endpoint = formatted_endpoint.strip()
    if not formatted_endpoint.startswith("/"):
        formatted_endpoint = f"/{formatted_endpoint}"
    if formatted_endpoint == "/v3":
        formatted_endpoint = "/"
    elif formatted_endpoint.startswith("/v3/"):
        formatted_endpoint = formatted_endpoint[len("/v3") :]

    normalized_base = f"{parsed.scheme}://{parsed.netloc}{normalized_path}"
    return f"{normalized_base}/v3{formatted_endpoint}"


def _resolve_oanda_api_base_url(mode: str) -> tuple[str, str]:
    normalized_mode = (mode or "live").strip().lower()
    if normalized_mode not in {"live", "demo", "practice"}:
        raise ValueError("OANDA mode must be live or demo.")

    if normalized_mode in {"demo", "practice"}:
        raw = (
            _clean_env("OANDA_API_URL_DEMO")
            or _clean_env("OANDA_BASE_URL_DEMO")
            or _clean_env("OANDA_BASE_URL")
            or "https://api-fxpractice.oanda.com"
        )
        resolved_mode = "demo"
    else:
        raw = (
            _clean_env("OANDA_API_URL_LIVE")
            or _clean_env("OANDA_BASE_URL_LIVE")
            or _clean_env("OANDA_API_URL")
            or _clean_env("OANDA_BASE_URL")
            or "https://api-fxtrade.oanda.com"
        )
        resolved_mode = "live"
    base_url_v3, trimmed_path = _normalize_oanda_v3_base_url(raw)
    parsed = urlparse(base_url_v3)
    BYBIT_LOGGER.info(
        "Resolved OANDA history API mode=%s host=%s normalized_to_v3=true trimmed_path=%s",
        resolved_mode,
        parsed.netloc,
        trimmed_path,
    )
    return base_url_v3, resolved_mode


def _sanitize_oanda_history_error(exc: Exception) -> str:
    message = str(exc).strip() or exc.__class__.__name__
    status_match = re.search(r"\b(\d{3})\b", message)
    status_code = status_match.group(1) if status_match else "unknown"
    lowered = message.lower()
    if "<html" in lowered or "cloudflare" in lowered or "attention required" in lowered:
        return (
            f"OANDA history export failed with HTTP {status_code} from upstream. "
            "Check OANDA history base URL and credentials."
        )
    return message if len(message) <= 240 else message[:237] + "..."


def _format_decimal_value(value: float) -> str:
    text = f"{value:.10f}"
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def _parse_optional_float(value: object, field_name: str) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"OANDA payload {field_name} must be numeric.") from exc


_OANDA_INSTRUMENT_META_CACHE: Dict[tuple[str, str], Dict[str, object]] = {}
_OANDA_INSTRUMENT_META_CACHE_TS: Dict[tuple[str, str], float] = {}
_OANDA_INSTRUMENT_META_TTL_SECONDS = 12 * 60 * 60  # 12 hours


def _quantize_oanda_units(value: float, precision: int) -> str:
    normalized = max(0, int(precision))
    quantizer = Decimal("1").scaleb(-normalized)
    quantized = Decimal(str(value)).quantize(quantizer, rounding=ROUND_HALF_UP)
    return f"{quantized:.{normalized}f}"


def _quantize_oanda_price(value: float, precision: int) -> str:
    normalized = max(0, precision)
    quantizer = Decimal("1").scaleb(-normalized)
    quantized = Decimal(str(value)).quantize(quantizer, rounding=ROUND_HALF_UP)
    return f"{quantized:.{normalized}f}"


async def _fetch_oanda_instrument_meta(
    *,
    base_url: str,
    account_id: str,
    api_key: str,
    symbol: str,
    mode: str,
) -> Dict[str, object]:
    if not symbol:
        raise ValueError("OANDA instrument name missing; cannot determine precision.")

    cache_key = (mode.strip().lower(), symbol.upper())
    now = time.time()
    cached = _OANDA_INSTRUMENT_META_CACHE.get(cache_key)
    cached_ts = _OANDA_INSTRUMENT_META_CACHE_TS.get(cache_key, 0.0)
    if cached and (now - cached_ts) < _OANDA_INSTRUMENT_META_TTL_SECONDS:
        return cached

    try:
        payload = await _fetch_oanda_json(
            base_url=base_url,
            account_id=account_id,
            api_key=api_key,
            endpoint=f"/accounts/{{account_id}}/instruments?instruments={symbol}",
            mode=mode,
        )
    except Exception as exc:
        if cached:
            BYBIT_LOGGER.warning(
                "OANDA instrument lookup failed; using cached meta symbol=%s mode=%s error=%s",
                symbol,
                mode,
                exc,
            )
            return cached
        raise ValueError(
            f"OANDA instrument lookup failed for {symbol} (mode={mode}). "
            "Refusing to place the order to avoid precision errors. "
            "Check OANDA connectivity/credentials."
        ) from exc
    instruments = payload.get("instruments") or []
    for instrument in instruments:
        name = str(instrument.get("name", "")).upper()
        if name and name == symbol.upper():
            try:
                meta = {
                    "displayPrecision": int(instrument.get("displayPrecision")),
                    "tradeUnitsPrecision": int(instrument.get("tradeUnitsPrecision", 0)),
                    "pipLocation": int(instrument.get("pipLocation", 0)),
                    "minimumTradeSize": str(instrument.get("minimumTradeSize") or "0"),
                    "maximumOrderUnits": str(instrument.get("maximumOrderUnits") or "0"),
                    "maximumPositionSize": str(instrument.get("maximumPositionSize") or "0"),
                    "marginRate": str(instrument.get("marginRate") or "0"),
                }
                _OANDA_INSTRUMENT_META_CACHE[cache_key] = meta
                _OANDA_INSTRUMENT_META_CACHE_TS[cache_key] = now
                return meta
            except (TypeError, ValueError):
                break

    if cached:
        BYBIT_LOGGER.warning(
            "OANDA instrument meta missing/unparseable; using cached meta symbol=%s mode=%s",
            symbol,
            mode,
        )
        return cached
    raise ValueError(
        f"OANDA instrument meta missing/unparseable for {symbol} (mode={mode}). "
        "Refusing to place the order to avoid precision errors."
    )


async def _fetch_oanda_display_precision(
    *,
    base_url: str,
    account_id: str,
    api_key: str,
    symbol: str,
    mode: str,
) -> int:
    meta = await _fetch_oanda_instrument_meta(
        base_url=base_url,
        account_id=account_id,
        api_key=api_key,
        symbol=symbol,
        mode=mode,
    )
    return int(meta["displayPrecision"])


def _clean_env(key: str) -> Optional[str]:
    value = os.getenv(key)
    if value is None:
        return None
    cleaned = value.strip().strip('"').strip("'")
    return cleaned or None


def _get_oanda_config(account: Optional[str]) -> Dict[str, str]:
    acct = (account or "").strip().lower()
    if acct in ("demo", "practice"):
        token = _clean_env("OANDA_API_KEY_DEMO")
        account_id = _clean_env("OANDA_ACCOUNT_ID_DEMO")
        base_url = _normalize_oanda_base_url(
            _clean_env("OANDA_API_URL_DEMO")
            or _clean_env("OANDA_BASE_URL_DEMO")
            or _clean_env("OANDA_BASE_URL")
            or "https://api-fxpractice.oanda.com"
        )
        missing = []
        if not token:
            missing.append("OANDA_API_KEY_DEMO")
        if not account_id:
            missing.append("OANDA_ACCOUNT_ID_DEMO")
        if missing:
            raise ValueError(
                f"OANDA demo credentials missing: {', '.join(missing)} ({_env_source_hint()})"
            )
        return {
            "mode": "demo",
            "token": token,
            "account_id": account_id,
            "base_url": base_url,
        }

    token = _clean_env("OANDA_API_KEY")
    account_id = _clean_env("OANDA_ACCOUNT_ID")
    base_url = _normalize_oanda_base_url(
        _clean_env("OANDA_API_URL_LIVE")
        or _clean_env("OANDA_BASE_URL_LIVE")
        or _clean_env("OANDA_BASE_URL")
        or "https://api-fxtrade.oanda.com"
    )
    missing = []
    if not token:
        missing.append("OANDA_API_KEY")
    if not account_id:
        missing.append("OANDA_ACCOUNT_ID")
    if missing:
        raise ValueError(
            f"OANDA live credentials missing: {', '.join(missing)} ({_env_source_hint()})"
        )
    return {"mode": "live", "token": token, "account_id": account_id, "base_url": base_url}


def _get_oanda_history_config(mode: str = "live") -> Dict[str, str]:
    acct = (mode or "live").strip().lower()
    base_url, resolved_mode = _resolve_oanda_api_base_url(acct)
    if resolved_mode == "demo":
        account_id = _clean_env("OANDA_ACCOUNT_ID_DEMO")
        api_key = _clean_env("OANDA_API_KEY_DEMO")
        missing = []
        if not api_key:
            missing.append("OANDA_API_KEY_DEMO")
        if not account_id:
            missing.append("OANDA_ACCOUNT_ID_DEMO")
        if missing:
            raise ValueError(f"OANDA demo export credentials missing: {', '.join(missing)}")
        return {
            "account_id": account_id,
            "api_key": api_key,
            "base_url": base_url,
            "mode": "demo",
        }

    account_id = _clean_env("OANDA_ACCOUNT_ID")
    api_key = _clean_env("OANDA_API_KEY")
    missing = []
    if not api_key:
        missing.append("OANDA_API_KEY")
    if not account_id:
        missing.append("OANDA_ACCOUNT_ID")
    if missing:
        raise ValueError(f"OANDA export credentials missing: {', '.join(missing)}")
    return {
        "account_id": account_id,
        "api_key": api_key,
        "base_url": base_url,
        "mode": "live",
    }


def _oanda_account_context(base_url: str) -> str:
    lowered = base_url.lower()
    if "fxpractice" in lowered or "practice" in lowered or "sandbox" in lowered:
        return "demo"
    return "live"


def _format_source_exception(
    exc: Exception,
    *,
    broker: str,
    account: str,
    endpoint: Optional[str] = None,
    account_id: Optional[str] = None,
) -> str:
    endpoint_label = endpoint or "endpoint"
    account_label = account or "unknown"
    account_id_label = account_id or "unknown"
    broker_label = broker or "source"

    if isinstance(exc, OandaUpstreamError):
        return (
            f"{broker_label} {endpoint_label} failed for "
            f"{account_label}/{account_id_label}: {str(exc)}"
        )

    if isinstance(exc, OandaUpstreamHTTPError):
        return (
            f"{broker_label} {endpoint_label} failed with HTTP {exc.status_code} "
            f"for {account_label}/{account_id_label}: {exc.body_summary}"
        )

    if isinstance(exc, httpx.TimeoutException):
        return (
            f"Timeout contacting {broker_label} {endpoint_label} "
            f"for {account_label}/{account_id_label}"
        )

    if isinstance(exc, httpx.RequestError):
        req_url = str(exc.request.url) if getattr(exc, "request", None) is not None else None
        detail = req_url or endpoint_label
        return (
            f"{exc.__class__.__name__} contacting {broker_label} {detail} "
            f"for {account_label}/{account_id_label}"
        )

    if isinstance(exc, httpx.HTTPStatusError):
        status = exc.response.status_code if exc.response is not None else "unknown"
        body = _summarize_upstream_body(exc.response.text if exc.response is not None else "")
        suffix = f": {body}" if body else ""
        return (
            f"{broker_label} {endpoint_label} failed with HTTP {status} "
            f"for {account_label}/{account_id_label}{suffix}"
        )

    text = str(exc).strip()
    if not text:
        return f"{exc.__class__.__name__} with empty message"
    return _safe_bybit_diagnostic_text(text)


def _summarize_upstream_body(body: str, *, limit: int = 240) -> str:
    raw = body or ""
    collapsed = re.sub(r"\s+", " ", raw).strip()
    lowered = collapsed.lower()

    if "<html" in lowered or "<!doctype" in lowered:
        title_match = re.search(
            r"<title[^>]*>(.*?)</title>",
            raw,
            flags=re.IGNORECASE | re.DOTALL,
        )
        title = "HTML error response"
        if title_match:
            title = re.sub(r"\s+", " ", html.unescape(title_match.group(1))).strip() or title
        return f"{title} (HTML response, {len(raw)} bytes)"

    if not collapsed:
        return "empty response body"

    if len(collapsed) > limit:
        return f"{collapsed[:limit]}... ({len(raw)} bytes)"

    return collapsed


async def _fetch_oanda_json(
    *,
    base_url: str,
    account_id: str,
    api_key: str,
    endpoint: str,
    mode: str,
    timeout_s: float = 6.0,
) -> Dict[str, object]:
    token = (api_key or "").strip().strip('"').strip("'")
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    url = _build_oanda_v3_url(base_url, endpoint, account_id=account_id)
    timeout = httpx.Timeout(timeout_s, connect=min(3.0, timeout_s), read=timeout_s, write=timeout_s, pool=2.0)
    max_attempts = 3
    transient_statuses = _OANDA_TRANSIENT_HTTP_STATUS_CODES
    resp: Optional[httpx.Response] = None

    async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
        for attempt in range(1, max_attempts + 1):
            try:
                resp = await client.get(url, headers=headers)
                resp.raise_for_status()
                _record_outbound_traffic(
                    "oanda",
                    bytes_sent=len(url) + sum(len(str(v)) for v in headers.values()),
                    bytes_received=len(resp.content),
                    context=endpoint,
                )
                break
            except httpx.TimeoutException as exc:
                should_retry = attempt < max_attempts
                BYBIT_LOGGER.warning(
                    "OANDA_TIMEOUT mode=%s account=%s endpoint=%s attempt=%s/%s retry=%s err=%s",
                    mode,
                    account_id,
                    endpoint,
                    attempt,
                    max_attempts,
                    should_retry,
                    exc,
                )
                if not should_retry:
                    raise OandaUpstreamError(
                        f"OANDA request timed out after {timeout_s:.1f}s",
                        upstream_status=None,
                        upstream_error_message=str(exc),
                        endpoint=endpoint,
                        mode=mode,
                        retry_exhausted=True,
                        maintenance_detected=False,
                    ) from exc
            except httpx.RequestError as exc:
                should_retry = attempt < max_attempts
                BYBIT_LOGGER.warning(
                    "OANDA_REQUEST_ERR mode=%s account=%s endpoint=%s attempt=%s/%s retry=%s err=%s",
                    mode,
                    account_id,
                    endpoint,
                    attempt,
                    max_attempts,
                    should_retry,
                    exc,
                )
                if not should_retry:
                    raise OandaUpstreamError(
                        f"OANDA transport error: {exc}",
                        upstream_status=None,
                        upstream_error_message=str(exc),
                        endpoint=endpoint,
                        mode=mode,
                        retry_exhausted=True,
                        maintenance_detected=False,
                    ) from exc
            except httpx.HTTPStatusError as exc:
                status = exc.response.status_code
                body_summary = _safe_bybit_diagnostic_text(
                    _summarize_upstream_body(exc.response.text),
                    api_key=token,
                    fallback="empty response body",
                )
                should_retry = status in transient_statuses and attempt < max_attempts
                log_fn = BYBIT_LOGGER.warning if should_retry else BYBIT_LOGGER.error
                log_fn(
                    "OANDA_HTTP_ERR mode=%s account=%s endpoint=%s status=%s attempt=%s/%s retry=%s body=%s",
                    mode,
                    account_id,
                    endpoint,
                    status,
                    attempt,
                    max_attempts,
                    should_retry,
                    body_summary,
                )
                if not should_retry:
                    raise OandaUpstreamHTTPError(
                        status_code=status,
                        mode=mode,
                        account_id=account_id,
                        endpoint=endpoint,
                        body_summary=body_summary,
                        transient=status in transient_statuses,
                    ) from exc

            backoff = min(0.2 * (2 ** (attempt - 1)), 0.8) + (0.05 * attempt)
            await asyncio.sleep(backoff)
        else:
            raise OandaUpstreamError(
                "OANDA request failed after retries",
                upstream_status=resp.status_code if resp is not None else None,
                upstream_error_message=(
                    _safe_bybit_diagnostic_text(
                        resp.text,
                        api_key=token,
                        fallback="empty response body",
                        limit=500,
                    )
                    if resp is not None
                    else ""
                ),
                endpoint=endpoint,
                mode=mode,
                retry_exhausted=True,
                maintenance_detected=False,
            )

    if resp is None:
        raise ValueError("OANDA request failed with no response")
    try:
        return resp.json()
    except json.JSONDecodeError as exc:
        body = _safe_bybit_diagnostic_text(
            _summarize_upstream_body(resp.text),
            api_key=token,
            fallback="empty response body",
        )
        raise ValueError(
            f"OANDA returned non-JSON success response mode={mode} account={account_id} "
            f"endpoint={endpoint}: {body}"
        ) from exc


def _parse_oanda_timestamp(value: str) -> datetime:
    cleaned = value.replace("Z", "+00:00")
    parsed = datetime.fromisoformat(cleaned)
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed


def _format_oanda_timestamp(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


async def _fetch_oanda_account_created_time(
    *, base_url: str, account_id: str, api_key: str
) -> datetime:
    payload = await _fetch_oanda_json(
        base_url=base_url,
        account_id=account_id,
        api_key=api_key,
        endpoint="/accounts/{account_id}",
        mode="history",
    )
    account = payload.get("account", {})
    created_time = account.get("createdTime")
    if not isinstance(created_time, str) or not created_time:
        raise ValueError("OANDA account createdTime missing from response.")
    return _parse_oanda_timestamp(created_time)


async def _oanda_preflight(
    *, base_url: str, account_id: str, api_key: str, mode: str
) -> None:
    token = (api_key or "").strip().strip('"').strip("'")
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    url = _build_oanda_v3_url(base_url, "/accounts")
    BYBIT_LOGGER.info(
        "OANDA_CFG mode=%s base=%s account_id=%s token_configured=%s",
        mode,
        base_url,
        account_id,
        bool(token),
    )
    BYBIT_LOGGER.info(
        "OANDA_CALL mode=%s base=%s account_id=%s token_configured=%s url=%s",
        mode,
        base_url,
        account_id,
        bool(token),
        url,
    )
    async with httpx.AsyncClient(timeout=10, follow_redirects=True) as client:
        try:
            resp = await client.get(url, headers=headers)
            BYBIT_LOGGER.info(
                "OANDA_RESP mode=%s status=%s endpoint=%s",
                mode,
                resp.status_code,
                "/v3/accounts",
            )
            if 300 <= resp.status_code < 400:
                BYBIT_LOGGER.info(
                    "OANDA_REDIRECT mode=%s status=%s endpoint=%s location=%s",
                    mode,
                    resp.status_code,
                    "/v3/accounts",
                    _safe_bybit_diagnostic_text(
                        resp.headers.get("location"),
                        api_key=token,
                        fallback="not supplied",
                    ),
                )
            resp.raise_for_status()
        except httpx.HTTPStatusError as exc:
            safe_body = _safe_bybit_diagnostic_text(
                _summarize_upstream_body(exc.response.text),
                api_key=token,
                fallback="empty response body",
                limit=500,
            )
            BYBIT_LOGGER.error(
                "OANDA_HTTP_ERR mode=%s status=%s endpoint=%s body=%s",
                mode,
                exc.response.status_code,
                "/v3/accounts",
                safe_body,
            )
            raise ValueError(
                f"OANDA preflight failed ({exc.response.status_code}): {safe_body}"
            ) from exc
    payload = resp.json()
    accounts = [acct.get("id") for acct in payload.get("accounts", [])]
    if account_id not in accounts:
        raise ValueError(
            "OANDA account mismatch: token does not own account "
            f"{account_id}. Available accounts: {accounts}"
        )


async def _collect_oanda_open_items(
    *, base_url: str, account_id: str, api_key: str, account_context: str
) -> Dict[str, object]:
    trades_task = _fetch_oanda_json(
        base_url=base_url,
        account_id=account_id,
        api_key=api_key,
        endpoint="/accounts/{account_id}/openTrades",
        mode=account_context,
        timeout_s=5.0,
    )
    orders_task = _fetch_oanda_json(
        base_url=base_url,
        account_id=account_id,
        api_key=api_key,
        endpoint="/accounts/{account_id}/pendingOrders",
        mode=account_context,
        timeout_s=5.0,
    )

    trades_result, orders_result = await asyncio.gather(
        trades_task,
        orders_task,
        return_exceptions=True,
    )

    trades_payload: Dict[str, object] = {}
    orders_payload: Dict[str, object] = {}
    fetch_errors: List[Dict[str, str]] = []

    if isinstance(trades_result, Exception):
        fetch_errors.append(
            {
                "endpoint": "/v3/accounts/{accountID}/openTrades",
                "message": _format_source_exception(
                    trades_result,
                    broker="OANDA",
                    account=account_context,
                    endpoint="/v3/accounts/{accountID}/openTrades",
                    account_id=account_id,
                ),
            }
        )
    else:
        trades_payload = trades_result

    if isinstance(orders_result, Exception):
        fetch_errors.append(
            {
                "endpoint": "/v3/accounts/{accountID}/pendingOrders",
                "message": _format_source_exception(
                    orders_result,
                    broker="OANDA",
                    account=account_context,
                    endpoint="/v3/accounts/{accountID}/pendingOrders",
                    account_id=account_id,
                ),
            }
        )
    else:
        orders_payload = orders_result

    items: List[Dict[str, object]] = []
    for trade in trades_payload.get("trades", []):
        units = trade.get("currentUnits") or trade.get("units")
        side = "Long"
        size = None
        if units is not None:
            try:
                units_val = float(units)
                side = "Long" if units_val >= 0 else "Short"
                size = abs(units_val)
            except (TypeError, ValueError):
                size = units
        items.append(
            {
                "broker": "OANDA",
                "account": account_context,
                "category": "forex",
                "instrument": trade.get("instrument"),
                "type": "Position",
                "side": side,
                "size": size,
                "entry_price": trade.get("price"),
                "order_price": None,
                "current_price": trade.get("currentPrice"),
                "stop_loss": (trade.get("stopLossOrder") or {}).get("price"),
                "take_profit": (trade.get("takeProfitOrder") or {}).get("price"),
                "leverage": trade.get("marginUsed"),
                "opened_at": trade.get("openTime"),
                "id": trade.get("id"),
                "trade_id": trade.get("id"),
                "status": trade.get("state") or "OPEN",
            }
        )

    for order in orders_payload.get("orders", []):
        units = order.get("units")
        side = "Buy"
        size = None
        if units is not None:
            try:
                units_val = float(units)
                side = "Buy" if units_val >= 0 else "Sell"
                size = abs(units_val)
            except (TypeError, ValueError):
                size = units
        items.append(
            {
                "broker": "OANDA",
                "account": account_context,
                "category": "forex",
                "instrument": order.get("instrument"),
                "type": "Order",
                "side": side,
                "size": size,
                "entry_price": None,
                "order_price": order.get("price"),
                "current_price": order.get("triggerPrice"),
                "stop_loss": (order.get("stopLossOnFill") or {}).get("price"),
                "take_profit": (order.get("takeProfitOnFill") or {}).get("price"),
                "leverage": order.get("marginUsed"),
                "opened_at": order.get("createTime"),
                "id": order.get("id"),
                "status": order.get("state") or "PENDING",
            }
        )
    for item in items:
        ctx = _lookup_trade_context_for_open_item(item)
        _enrich_open_item_with_trade_context(item, ctx)
    return {"items": items, "errors": fetch_errors}


async def _list_oanda_accounts(*, base_url: str, api_key: str) -> List[Dict[str, object]]:
    token = (api_key or "").strip().strip('"').strip("'")
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    url = _build_oanda_v3_url(base_url, "/accounts")
    timeout_s = 6.0
    timeout = httpx.Timeout(timeout_s, connect=min(3.0, timeout_s), read=timeout_s, write=timeout_s, pool=2.0)
    max_attempts = 3
    transient_statuses = _OANDA_TRANSIENT_HTTP_STATUS_CODES
    account_context = _oanda_account_context(base_url)
    resp: Optional[httpx.Response] = None

    async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
        for attempt in range(1, max_attempts + 1):
            attempt_started = time.monotonic()
            try:
                resp = await client.get(url, headers=headers)
                resp.raise_for_status()
                BYBIT_LOGGER.info(
                    "OANDA_ACCOUNTS_OK account=%s endpoint=%s attempt=%s/%s elapsed=%.3fs",
                    account_context,
                    "/v3/accounts",
                    attempt,
                    max_attempts,
                    time.monotonic() - attempt_started,
                )
                break
            except httpx.TimeoutException as exc:
                should_retry = attempt < max_attempts
                BYBIT_LOGGER.warning(
                    "OANDA_ACCOUNTS_TIMEOUT account=%s endpoint=%s attempt=%s/%s retry=%s "
                    "timeout=%.1fs elapsed=%.3fs error_type=%s",
                    account_context,
                    "/v3/accounts",
                    attempt,
                    max_attempts,
                    should_retry,
                    timeout_s,
                    time.monotonic() - attempt_started,
                    exc.__class__.__name__,
                )
                if not should_retry:
                    raise OandaAccountDiscoveryError(
                        failure_kind="timeout",
                        attempts=attempt,
                        timeout_s=timeout_s,
                        error_type=exc.__class__.__name__,
                    )
            except httpx.RequestError as exc:
                error_text = str(exc or "")
                is_dns = bool(
                    re.search(
                        r"(?:getaddrinfo|name or service not known|nodename nor servname|"
                        r"temporary failure in name resolution|dns)",
                        error_text,
                        flags=re.IGNORECASE,
                    )
                )
                should_retry = attempt < max_attempts
                BYBIT_LOGGER.warning(
                    "OANDA_ACCOUNTS_REQUEST_ERR account=%s endpoint=%s attempt=%s/%s retry=%s "
                    "elapsed=%.3fs failure_kind=%s error_type=%s",
                    account_context,
                    "/v3/accounts",
                    attempt,
                    max_attempts,
                    should_retry,
                    time.monotonic() - attempt_started,
                    "dns" if is_dns else "transport",
                    exc.__class__.__name__,
                )
                if not should_retry:
                    raise OandaAccountDiscoveryError(
                        failure_kind="dns" if is_dns else "transport",
                        attempts=attempt,
                        timeout_s=timeout_s,
                        error_type=exc.__class__.__name__,
                    )
            except httpx.HTTPStatusError as exc:
                status = exc.response.status_code
                should_retry = status in transient_statuses and attempt < max_attempts
                log_fn = BYBIT_LOGGER.warning if should_retry else BYBIT_LOGGER.error
                log_fn(
                    "OANDA_ACCOUNTS_HTTP_ERR account=%s endpoint=%s status=%s attempt=%s/%s "
                    "retry=%s elapsed=%.3fs body=%s",
                    account_context,
                    "/v3/accounts",
                    status,
                    attempt,
                    max_attempts,
                    should_retry,
                    time.monotonic() - attempt_started,
                    _safe_bybit_diagnostic_text(
                        _summarize_upstream_body(exc.response.text),
                        api_key=token,
                        fallback="empty response body",
                    ),
                )
                if not should_retry:
                    raise OandaAccountDiscoveryError(
                        failure_kind="rate_limit" if status == 429 else "http",
                        attempts=attempt,
                        timeout_s=timeout_s,
                        error_type=exc.__class__.__name__,
                        http_status=status,
                    )

            backoff = min(0.2 * (2 ** (attempt - 1)), 0.8) + (0.05 * attempt)
            await asyncio.sleep(backoff)
        else:
            raise OandaAccountDiscoveryError(
                failure_kind="transport",
                attempts=max_attempts,
                timeout_s=timeout_s,
                error_type="retry_exhausted",
            )

    if resp is None:
        raise OandaAccountDiscoveryError(
            failure_kind="invalid_response",
            attempts=max_attempts,
            timeout_s=timeout_s,
            error_type="missing_response",
        )
    try:
        payload = resp.json()
    except (json.JSONDecodeError, ValueError) as exc:
        raise OandaAccountDiscoveryError(
            failure_kind="invalid_response",
            attempts=attempt,
            timeout_s=timeout_s,
            error_type=exc.__class__.__name__,
        ) from exc
    accounts = payload.get("accounts", []) if isinstance(payload, dict) else []
    return [dict(account) for account in accounts if isinstance(account, dict)]


def _oanda_discovery_failure_allows_stale(
    exc: Exception, *, allow_auth_anomaly: bool = False
) -> bool:
    if isinstance(exc, OandaAccountDiscoveryError):
        if allow_auth_anomaly and exc.failure_kind == "http" and exc.http_status == 401:
            return True
        if exc.failure_kind in {"timeout", "rate_limit", "dns", "transport"}:
            return True
        return bool(
            exc.failure_kind == "http"
            and exc.http_status in _OANDA_TRANSIENT_HTTP_STATUS_CODES
        )
    return isinstance(exc, (httpx.TimeoutException, httpx.RequestError))


def _oanda_discovery_is_http_401(exc: Optional[Exception]) -> bool:
    return bool(
        isinstance(exc, OandaAccountDiscoveryError)
        and exc.failure_kind == "http"
        and exc.http_status == 401
    )


async def _get_cached_oanda_accounts(
    *,
    base_url: str,
    api_key: str,
    allow_auth_anomaly_stale: bool = False,
) -> OandaAccountDiscoveryResult:
    token = (api_key or "").strip().strip('"').strip("'")
    cache_key = hashlib.sha256(
        f"{base_url.rstrip('/')}|{token}".encode("utf-8")
    ).hexdigest()
    now = time.time()
    cached = _OANDA_ACCOUNTS_CACHE.get(cache_key)
    if cached and float(cached.get("fresh_until") or 0.0) > now:
        return OandaAccountDiscoveryResult(
            accounts=list(cached.get("accounts") or []),
            cache_state="fresh",
            fetched_at=float(cached.get("fetched_at") or now),
        )

    refresh_task = _OANDA_ACCOUNTS_INFLIGHT.get(cache_key)
    if refresh_task is None or refresh_task.done():
        refresh_task = asyncio.create_task(
            _list_oanda_accounts(base_url=base_url, api_key=api_key)
        )
        _OANDA_ACCOUNTS_INFLIGHT[cache_key] = refresh_task
    try:
        accounts = await asyncio.shield(refresh_task)
    except Exception as exc:
        stale_cached = _OANDA_ACCOUNTS_CACHE.get(cache_key)
        if (
            _oanda_discovery_failure_allows_stale(
                exc, allow_auth_anomaly=allow_auth_anomaly_stale
            )
            and stale_cached
            and float(stale_cached.get("stale_until") or 0.0) > time.time()
        ):
            return OandaAccountDiscoveryResult(
                accounts=list(stale_cached.get("accounts") or []),
                cache_state="stale",
                fetched_at=float(stale_cached.get("fetched_at") or now),
                discovery_error=exc,
            )
        raise
    finally:
        if refresh_task.done() and _OANDA_ACCOUNTS_INFLIGHT.get(cache_key) is refresh_task:
            _OANDA_ACCOUNTS_INFLIGHT.pop(cache_key, None)

    fetched_at = time.time()
    _OANDA_ACCOUNTS_CACHE[cache_key] = {
        "fetched_at": fetched_at,
        "fresh_until": fetched_at + _OANDA_ACCOUNTS_CACHE_TTL_SECONDS,
        "stale_until": fetched_at + _OANDA_ACCOUNTS_STALE_TTL_SECONDS,
        "accounts": list(accounts),
    }
    return OandaAccountDiscoveryResult(
        accounts=list(accounts),
        cache_state="refreshed",
        fetched_at=fetched_at,
    )


def _oanda_discovery_warning(
    *,
    account: str,
    exc: Exception,
    stale_fetched_at: Optional[float],
    configured_account_refreshed: bool,
) -> Dict[str, str]:
    if isinstance(exc, OandaAccountDiscoveryError):
        diagnostic = str(exc).replace(
            "OANDA account discovery",
            "Additional owned-account discovery",
            1,
        )
        error_type = exc.error_type
    elif isinstance(exc, httpx.TimeoutException):
        diagnostic = "Additional owned-account discovery timed out"
        error_type = exc.__class__.__name__
    elif isinstance(exc, httpx.RequestError):
        diagnostic = "Additional owned-account discovery had a transport failure"
        error_type = exc.__class__.__name__
    else:
        diagnostic = (
            "Additional owned-account discovery failed "
            f"({exc.__class__.__name__ or 'unknown error type'})"
        )
        error_type = exc.__class__.__name__

    if stale_fetched_at is not None:
        age_seconds = max(0, int(time.time() - stale_fetched_at))
        if age_seconds < 120:
            age_label = f"{age_seconds} seconds old"
        elif age_seconds < 7200:
            age_label = f"{max(1, age_seconds // 60)} minutes old"
        else:
            age_label = f"{max(1, age_seconds // 3600)} hours old"
        scope = (
            f"A last-known-good owned-account list ({age_label}) was used, and current "
            "open trades and pending orders were requested for those account IDs."
        )
    elif configured_account_refreshed:
        scope = (
            "No last-known-good owned-account list was available; only the configured "
            "account's current open trades and pending orders were confirmed."
        )
    else:
        scope = (
            "No last-known-good owned-account list was available; only the configured "
            "account ID could be attempted."
        )
    return {
        "broker": "OANDA",
        "account": account,
        "category": "forex",
        "source_type": "account discovery",
        "endpoint": "/v3/accounts",
        "error_type": error_type,
        "message": f"{diagnostic}. {scope}",
    }


def _build_bybit_query(params: Dict[str, str]) -> str:
    if not params:
        return ""
    return "&".join(f"{key}={value}" for key, value in sorted(params.items()))


def _normalize_bybit_base_url(base_url: str) -> str:
    return str(base_url or "").strip().rstrip("/")


def _bybit_recv_window_str() -> str:
    return str(BYBIT_RECV_WINDOW_MS)


def _bybit_timestamp_window_error(ret_code: object, ret_msg: object) -> bool:
    code = str(ret_code).strip()
    msg = str(ret_msg or "").lower()
    return code == "10002" or "timestamp" in msg or "recv_window" in msg


def _extract_bybit_timestamp_diag(ret_msg: object) -> str:
    msg = str(ret_msg or "")
    req_match = re.search(r"req_timestamp\[(\d+)\]", msg)
    server_match = re.search(r"server_timestamp\[(\d+)\]", msg)
    recv_match = re.search(r"recv_window\[(\d+)\]", msg)
    if not req_match and not server_match and not recv_match:
        return ""
    req_ts = int(req_match.group(1)) if req_match else None
    server_ts = int(server_match.group(1)) if server_match else None
    recv_window = recv_match.group(1) if recv_match else _bybit_recv_window_str()
    delta = None
    if req_ts is not None and server_ts is not None:
        delta = req_ts - server_ts
    diag_parts = [f"recv_window={recv_window}"]
    if delta is not None:
        diag_parts.append(f"server_delta_ms={delta}")
    return " ".join(diag_parts)


def _build_bybit_error_diagnostic(*, base_url: str, path: str, error_text: str) -> str:
    ret_code_match = re.search(r"retCode=([^\s]+)", error_text)
    ret_msg_match = re.search(r"retMsg=(.+)$", error_text)
    ret_code = ret_code_match.group(1) if ret_code_match else "unknown"
    ret_msg = ret_msg_match.group(1) if ret_msg_match else error_text
    diag = _extract_bybit_timestamp_diag(ret_msg)
    offset_ms = 0
    cached = _BYBIT_TIME_OFFSET_CACHE.get(_normalize_bybit_base_url(base_url))
    if isinstance(cached, dict):
        offset_ms = int(cached.get("offset_ms", 0) or 0)
    return (
        f"Bybit sync failed path={path} retCode={ret_code} retMsg={ret_msg} "
        f"recv_window={_bybit_recv_window_str()} offset_ms={offset_ms}"
        + (f" {diag}" if diag else "")
    )


async def _fetch_bybit_server_time_ms(base_url: str) -> int:
    normalized_base = _normalize_bybit_base_url(base_url)
    url = f"{normalized_base}/v5/market/time"
    async with httpx.AsyncClient(timeout=10) as client:
        req = client.get(url)
        if hasattr(req, "__aenter__"):
            async with req as resp:
                response = resp
        else:
            response = await req
    _record_outbound_traffic(
        "bybit",
        bytes_sent=len(url),
        bytes_received=len(getattr(response, "content", b"") or b""),
        context="/v5/market/time",
    )
    payload: Dict[str, object] = {}
    try:
        payload = response.json()
    except Exception:
        payload = {}
    if response.status_code >= 400:
        raise ValueError(
            f"Bybit server time request failed http_status={response.status_code} retCode={payload.get('retCode')} retMsg={payload.get('retMsg') or response.text}"
        )
    if not payload:
        raise ValueError("Bybit server time response is unparseable.")
    if payload.get("retCode") not in (0, "0", None):
        raise ValueError(
            f"Bybit server time request failed retCode={payload.get('retCode')} retMsg={payload.get('retMsg')}"
        )
    result = payload.get("result")
    server_ms: Optional[int] = None
    if isinstance(result, dict):
        time_nano = _to_float(result.get("timeNano"))
        if time_nano:
            server_ms = int(time_nano / 1_000_000)
        if server_ms is None:
            time_second = _to_float(result.get("timeSecond"))
            if time_second:
                server_ms = int(time_second * 1000)
    if server_ms is None:
        top_time = _to_float(payload.get("time"))
        if top_time:
            server_ms = int(top_time)
    if not server_ms or server_ms <= 0:
        raise ValueError("Bybit server time response is unparseable.")
    return server_ms


async def _refresh_bybit_time_offset_ms(base_url: str) -> int:
    normalized_base = _normalize_bybit_base_url(base_url)
    local_before = int(time.time() * 1000)
    server_ms = await _fetch_bybit_server_time_ms(normalized_base)
    local_after = int(time.time() * 1000)
    local_midpoint = (local_before + local_after) // 2
    rtt_ms = max(0, local_after - local_before)
    offset_ms = int(server_ms - local_midpoint)
    _BYBIT_TIME_OFFSET_CACHE[normalized_base] = {
        "synced_at": local_after,
        "offset_ms": offset_ms,
        "rtt_ms": rtt_ms,
    }
    BYBIT_LOGGER.info(
        "BYBIT_TIME_SYNC base_url=%s offset_ms=%s rtt_ms=%s",
        normalized_base,
        offset_ms,
        rtt_ms,
    )
    if abs(offset_ms) > 3000:
        BYBIT_LOGGER.warning(
            "BYBIT_TIME_SYNC offset drift detected base_url=%s offset_ms=%s",
            normalized_base,
            offset_ms,
        )
    return offset_ms


async def _get_bybit_time_offset_ms(base_url: str, force_refresh: bool = False) -> int:
    normalized_base = _normalize_bybit_base_url(base_url)
    now_ms = int(time.time() * 1000)
    cached = _BYBIT_TIME_OFFSET_CACHE.get(normalized_base)
    if (
        not force_refresh
        and isinstance(cached, dict)
        and now_ms - int(cached.get("synced_at", 0) or 0) <= (BYBIT_TIME_OFFSET_TTL_SECONDS * 1000)
    ):
        return int(cached.get("offset_ms", 0) or 0)
    try:
        return await _refresh_bybit_time_offset_ms(normalized_base)
    except Exception as exc:
        BYBIT_LOGGER.warning("BYBIT_TIME_SYNC refresh failed base_url=%s err=%s", normalized_base, exc)
        if isinstance(cached, dict):
            return int(cached.get("offset_ms", 0) or 0)
        return 0


async def _bybit_timestamp_ms(base_url: str, force_time_sync: bool = False) -> str:
    offset_ms = await _get_bybit_time_offset_ms(base_url, force_refresh=force_time_sync)
    return str(int(time.time() * 1000) + int(offset_ms))


def _is_bybit_open_order(status: Optional[str]) -> bool:
    if not status:
        return True
    normalized = status.strip().lower()
    open_statuses = {
        "new",
        "untriggered",
        "partiallyfilled",
        "triggered",
        "active",
        "working",
        "created",
        "open",
    }
    closed_statuses = {
        "filled",
        "cancelled",
        "canceled",
        "rejected",
        "deactivated",
        "expired",
        "done",
    }
    if normalized in closed_statuses:
        return False
    if normalized in open_statuses:
        return True
    return normalized not in closed_statuses

async def _build_bybit_signed_headers(
    *, normalized_base: str, api_key: str, api_secret: str, data_str: str, recv_window: str, force_time_sync: bool
) -> Dict[str, str]:
    timestamp = await _bybit_timestamp_ms(normalized_base, force_time_sync=force_time_sync)
    signature = _bybit_sign_request(timestamp, api_key, api_secret, data_str, recv_window=recv_window)
    return {
        "X-BAPI-API-KEY": api_key,
        "X-BAPI-SIGN": signature,
        "X-BAPI-TIMESTAMP": timestamp,
        "X-BAPI-RECV-WINDOW": recv_window,
        "X-BAPI-SIGN-TYPE": "2",
    }


def _safe_bybit_endpoint(path: object) -> str:
    raw = str(path or "").strip()
    if not raw:
        return "unknown"
    try:
        parsed = urlparse(raw)
        if parsed.scheme or parsed.netloc:
            return parsed.path or "/"
    except Exception:
        pass
    return raw.split("?", 1)[0].split("#", 1)[0] or "unknown"


def _safe_bybit_diagnostic_text(
    value: object,
    *,
    api_key: str = "",
    api_secret: str = "",
    fallback: str = "no diagnostic message supplied",
    limit: int = 300,
) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    for secret in (api_key, api_secret):
        secret_text = str(secret or "").strip()
        if secret_text:
            text = text.replace(secret_text, "[redacted]")
    text = re.sub(
        r"(?i)\b(api[_-]?key|api[_-]?secret|secret|signature|x-bapi-api-key|x-bapi-sign)"
        r"\s*[\"']?\s*([=:])\s*(?:\"[^\"]*\"|'[^']*'|[^,\s;&}]+)",
        r"\1\2[redacted]",
        text,
    )
    text = re.sub(r"(?i)\bBearer\s+[^\s,;\"']+", "Bearer [redacted]", text)
    text = re.sub(
        r"(?i)\b(access[_-]?token|token|authorization)"
        r"\s*[\"']?\s*([=:])\s*(?:\"[^\"]*\"|'[^']*'|[^,\s;&}]+)",
        r"\1\2[redacted]",
        text,
    )
    text = re.sub(r"https?://[^\s]+", "[redacted URL]", text, flags=re.IGNORECASE)
    if not text:
        return fallback
    if len(text) > limit:
        return f"{text[:limit]}..."
    return text


class BybitSignedGETError(ValueError):
    def __init__(
        self,
        *,
        path: str,
        failure_kind: str,
        attempts: int,
        http_status: Optional[int] = None,
        ret_code: object = None,
        ret_msg: object = None,
        error_type: Optional[str] = None,
        timeout_s: Optional[float] = None,
    ) -> None:
        self.path = _safe_bybit_endpoint(path)
        self.failure_kind = str(failure_kind or "request_failure")
        self.attempts = max(1, int(attempts or 1))
        self.http_status = int(http_status) if http_status is not None else None
        self.ret_code = ret_code
        self.ret_msg = str(ret_msg or "").strip()
        self.error_type = str(error_type or "").strip()
        self.timeout_s = float(timeout_s) if timeout_s is not None else None

        parts = [
            "Bybit signed GET failed",
            f"path={self.path}",
            f"reason={self.failure_kind}",
            f"attempts={self.attempts}",
        ]
        if self.timeout_s is not None:
            parts.append(f"timeout={self.timeout_s:g}s")
        if self.error_type:
            parts.append(f"error_type={self.error_type}")
        if self.http_status is not None:
            parts.append(f"http_status={self.http_status}")
        if self.ret_code not in (None, ""):
            parts.append(f"retCode={self.ret_code}")
        if self.ret_msg:
            parts.append(f"retMsg={self.ret_msg}")
        super().__init__(" ".join(parts))


def _bybit_open_source_error(
    exc: Exception,
    *,
    account: str,
    category: str,
    source_type: str,
    endpoint: str,
    settlement_coin: Optional[str] = None,
    api_key: str = "",
    api_secret: str = "",
) -> Dict[str, str]:
    safe_endpoint = _safe_bybit_endpoint(endpoint)
    error_type = (
        str(getattr(exc, "error_type", "") or "").strip()
        or exc.__class__.__name__
    )
    failure_kind = str(getattr(exc, "failure_kind", "") or "").strip()
    http_status: object = getattr(exc, "http_status", None)
    ret_code: object = getattr(exc, "ret_code", None)
    ret_msg: object = getattr(exc, "ret_msg", None)

    if isinstance(exc, httpx.TimeoutException):
        reason = (
            f"timeout contacting endpoint={safe_endpoint} "
            f"error_type={error_type}"
        )
    elif isinstance(exc, httpx.RequestError):
        detail = _safe_bybit_diagnostic_text(
            str(exc),
            api_key=api_key,
            api_secret=api_secret,
            fallback=error_type,
        )
        reason = (
            f"request failure contacting endpoint={safe_endpoint} "
            f"error_type={error_type} detail={detail}"
        )
    else:
        reason = _safe_bybit_diagnostic_text(
            str(exc),
            api_key=api_key,
            api_secret=api_secret,
            fallback=f"{error_type} raised without a message",
        )

    if isinstance(exc, httpx.HTTPStatusError):
        response = getattr(exc, "response", None)
        if response is not None:
            http_status = getattr(response, "status_code", http_status)
            try:
                payload = response.json()
            except Exception:
                payload = {}
            if isinstance(payload, dict):
                ret_code = payload.get("retCode", ret_code)
                ret_msg = payload.get("retMsg", ret_msg)

    entry: Dict[str, str] = {
        "broker": "Bybit",
        "account": str(account or "unknown").strip() or "unknown",
        "category": str(category or "unknown").strip() or "unknown",
        "source_type": str(source_type or "request").strip() or "request",
        "endpoint": safe_endpoint,
        "settlement_coin": str(settlement_coin or "n/a").strip() or "n/a",
        "error_type": error_type,
        "message": reason,
    }
    if failure_kind:
        entry["failure_kind"] = failure_kind
    if http_status not in (None, ""):
        entry["http_status"] = str(http_status)
    if ret_code not in (None, ""):
        entry["retCode"] = _safe_bybit_diagnostic_text(
            ret_code,
            api_key=api_key,
            api_secret=api_secret,
            fallback="unknown",
        )
    if ret_msg not in (None, ""):
        entry["retMsg"] = _safe_bybit_diagnostic_text(
            ret_msg,
            api_key=api_key,
            api_secret=api_secret,
            fallback="Bybit request failed",
        )
    return entry


def _bybit_credential_fingerprint(api_key: str, api_secret: str) -> str:
    if not api_key or not api_secret:
        return "unavailable"
    return hashlib.sha256(f"{api_key}\0{api_secret}".encode("utf-8")).hexdigest()[:12]


def _bybit_auth_failure_classification(exc: Exception) -> str:
    http_status = getattr(exc, "http_status", None)
    ret_code = str(getattr(exc, "ret_code", "") or "").strip()
    ret_msg = str(getattr(exc, "ret_msg", "") or "").lower()
    if ret_code == "10002" or _bybit_timestamp_window_error(ret_code, ret_msg):
        return "timestamp_window_error"
    if ret_code == "10003":
        return "invalid_credentials_or_wrong_environment_domain"
    if ret_code in {"-2015", "33004"} or "expired" in ret_msg:
        return "expired_api_key"
    if ret_code == "10005" or "permission" in ret_msg:
        return "missing_api_permission"
    if ret_code == "10010" or "unmatched ip" in ret_msg:
        return "ip_restriction"
    if ret_code in {"10004", "10007"}:
        return "invalid_credentials_or_signature"
    if ret_code in {"10009", "10024"}:
        return "regional_or_compliance_restriction"
    if http_status == 401:
        return "invalid_credentials_or_auth_headers"
    if http_status == 403:
        return "ip_permission_or_region_restriction"
    failure_kind = str(getattr(exc, "failure_kind", "") or "").strip()
    return failure_kind or "auth_preflight_failed"


async def _bybit_read_only_auth_preflight(
    *,
    base_url: str,
    api_key: str,
    api_secret: str,
    account_context: str,
    key_source: str,
) -> Dict[str, object]:
    """Authenticate once before category fan-out using Bybit's read-only key-info API."""

    host = str(urlparse(base_url).hostname or "unknown")
    fingerprint = _bybit_credential_fingerprint(api_key, api_secret)
    pair_complete = bool(api_key and api_secret)
    BYBIT_LOGGER.info(
        "BYBIT_AUTH_PREFLIGHT mode=%s host=%s credential_source=%s pair_complete=%s fingerprint=%s",
        account_context,
        host,
        key_source or "unknown",
        str(pair_complete).lower(),
        fingerprint,
    )
    try:
        payload = await _bybit_signed_get(
            base_url=base_url,
            api_key=api_key,
            api_secret=api_secret,
            path="/v5/user/query-api",
            params={},
        )
    except Exception as exc:
        classification = _bybit_auth_failure_classification(exc)
        source_error = _bybit_open_source_error(
            exc,
            account=account_context,
            category="account",
            source_type="auth preflight",
            endpoint="/v5/user/query-api",
            settlement_coin="n/a",
            api_key=api_key,
            api_secret=api_secret,
        )
        source_error.update(
            {
                "auth_failure": "true",
                "auth_classification": classification,
                "mode": account_context,
                "base_host": host,
                "credential_source": key_source or "unknown",
                "pair_complete": str(pair_complete).lower(),
                "credential_fingerprint": fingerprint,
            }
        )
        upstream_detail = str(source_error.get("message") or "").strip()
        source_error["message"] = (
            f"Bybit read-only authentication preflight failed: {classification}; "
            f"mode={account_context} host={host} credential_source={key_source or 'unknown'} "
            f"pair_complete={str(pair_complete).lower()} fingerprint={fingerprint}. "
            f"{upstream_detail}"
        )
        raise BybitAuthPreflightError(source_error) from exc

    result = payload.get("result") if isinstance(payload, dict) else {}
    result = result if isinstance(result, dict) else {}
    permissions = result.get("permissions") if isinstance(result.get("permissions"), dict) else {}
    permission_groups = sorted(str(name) for name in permissions.keys())
    ips = result.get("ips") if isinstance(result.get("ips"), list) else []
    diagnostic = {
        "mode": account_context,
        "base_host": host,
        "credential_source": key_source or "unknown",
        "pair_complete": pair_complete,
        "credential_fingerprint": fingerprint,
        "read_only": result.get("readOnly"),
        "ip_binding_count": len(ips),
        "permission_groups": permission_groups,
    }
    BYBIT_LOGGER.info(
        "BYBIT_AUTH_PREFLIGHT_OK mode=%s host=%s credential_source=%s fingerprint=%s "
        "read_only=%s ip_binding_count=%s permission_groups=%s",
        account_context,
        host,
        key_source or "unknown",
        fingerprint,
        result.get("readOnly"),
        len(ips),
        permission_groups,
    )
    return diagnostic


class BybitAuthPreflightError(ValueError):
    def __init__(self, diagnostic: Dict[str, str]) -> None:
        self.diagnostic = dict(diagnostic)
        super().__init__(str(self.diagnostic.get("message") or "Bybit auth preflight failed"))


async def _bybit_signed_get(
    *,
    base_url: str,
    api_key: str,
    api_secret: str,
    path: str,
    params: Dict[str, str],
    timeout_s: float = 10.0,
    connect_s: float = 2.0,
    read_s: Optional[float] = None,
) -> Dict[str, object]:
    query = _build_bybit_query(params)
    normalized_base = _normalize_bybit_base_url(base_url)
    recv_window = _bybit_recv_window_str()
    safe_path = _safe_bybit_endpoint(path)
    url = f"{normalized_base}{safe_path}"
    if query:
        url = f"{url}?{query}"
    force_time_sync = False
    transient_statuses = {408, 425, 429, 500, 502, 503, 504}
    for attempt in range(1, BYBIT_SIGNED_REQUEST_MAX_RETRIES + 1):
        try:
            headers = await _build_bybit_signed_headers(
                normalized_base=normalized_base,
                api_key=api_key,
                api_secret=api_secret,
                data_str=query,
                recv_window=recv_window,
                force_time_sync=force_time_sync,
            )
            timeout = httpx.Timeout(
                timeout_s,
                connect=connect_s,
                read=(read_s if read_s is not None else timeout_s),
                write=timeout_s,
                pool=2.0,
            )
        except Exception as exc:
            safe_detail = _safe_bybit_diagnostic_text(
                str(exc),
                api_key=api_key,
                api_secret=api_secret,
                fallback=exc.__class__.__name__,
            )
            BYBIT_LOGGER.error(
                "BYBIT_SIGNED_GET_SETUP_ERROR path=%s error_type=%s detail=%s",
                safe_path,
                exc.__class__.__name__,
                safe_detail,
            )
            raise BybitSignedGETError(
                path=safe_path,
                failure_kind="request_setup_error",
                attempts=attempt,
                error_type=exc.__class__.__name__,
                ret_msg=safe_detail,
            ) from exc
        force_time_sync = False
        try:
            async with httpx.AsyncClient(timeout=timeout) as client:
                resp = await client.get(url, headers=headers)
        except httpx.TimeoutException as exc:
            should_retry = attempt < BYBIT_SIGNED_REQUEST_MAX_RETRIES
            BYBIT_LOGGER.warning(
                "BYBIT_SIGNED_GET_TIMEOUT path=%s error_type=%s attempt=%s/%s retry=%s",
                safe_path,
                exc.__class__.__name__,
                attempt,
                BYBIT_SIGNED_REQUEST_MAX_RETRIES,
                should_retry,
            )
            if should_retry:
                await asyncio.sleep(min(0.2 * attempt, 0.5))
                continue
            raise BybitSignedGETError(
                path=safe_path,
                failure_kind="timeout",
                attempts=attempt,
                error_type=exc.__class__.__name__,
                timeout_s=timeout_s,
                ret_msg="request timed out",
            ) from exc
        except httpx.RequestError as exc:
            should_retry = attempt < BYBIT_SIGNED_REQUEST_MAX_RETRIES
            safe_detail = _safe_bybit_diagnostic_text(
                str(exc),
                api_key=api_key,
                api_secret=api_secret,
                fallback=exc.__class__.__name__,
            )
            BYBIT_LOGGER.warning(
                "BYBIT_SIGNED_GET_REQUEST_ERROR path=%s error_type=%s attempt=%s/%s retry=%s detail=%s",
                safe_path,
                exc.__class__.__name__,
                attempt,
                BYBIT_SIGNED_REQUEST_MAX_RETRIES,
                should_retry,
                safe_detail,
            )
            if should_retry:
                await asyncio.sleep(min(0.2 * attempt, 0.5))
                continue
            raise BybitSignedGETError(
                path=safe_path,
                failure_kind="request_error",
                attempts=attempt,
                error_type=exc.__class__.__name__,
                ret_msg=safe_detail,
            ) from exc
        except Exception as exc:
            safe_detail = _safe_bybit_diagnostic_text(
                str(exc),
                api_key=api_key,
                api_secret=api_secret,
                fallback=f"{exc.__class__.__name__} raised without a message",
            )
            BYBIT_LOGGER.error(
                "BYBIT_SIGNED_GET_UNEXPECTED_ERROR path=%s error_type=%s detail=%s",
                safe_path,
                exc.__class__.__name__,
                safe_detail,
            )
            raise BybitSignedGETError(
                path=safe_path,
                failure_kind="unexpected_request_error",
                attempts=attempt,
                error_type=exc.__class__.__name__,
                ret_msg=safe_detail,
            ) from exc
        _record_outbound_traffic(
            "bybit",
            bytes_sent=len(url) + sum(len(str(v)) for v in headers.values()),
            bytes_received=len(getattr(resp, "content", b"") or b""),
            context=safe_path,
        )
        payload: Dict[str, object] = {}
        try:
            raw_payload = resp.json()
            if isinstance(raw_payload, dict):
                payload = raw_payload
        except Exception:
            payload = {}
        ret_code = payload.get("retCode")
        safe_ret_code: object = (
            ret_code
            if isinstance(ret_code, (int, float))
            else _safe_bybit_diagnostic_text(
                ret_code,
                api_key=api_key,
                api_secret=api_secret,
                fallback="unknown",
            )
        )
        raw_ret_msg = payload.get("retMsg") or _summarize_upstream_body(resp.text)
        ret_msg = _safe_bybit_diagnostic_text(
            raw_ret_msg,
            api_key=api_key,
            api_secret=api_secret,
            fallback="Bybit returned no error message",
        )
        if resp.status_code >= 400:
            should_retry = (
                resp.status_code in transient_statuses
                and attempt < BYBIT_SIGNED_REQUEST_MAX_RETRIES
            )
            log_fn = BYBIT_LOGGER.warning if should_retry else BYBIT_LOGGER.error
            log_fn(
                "BYBIT_SIGNED_GET_HTTP_ERROR path=%s http_status=%s retCode=%s retMsg=%s attempt=%s/%s retry=%s",
                safe_path,
                resp.status_code,
                safe_ret_code,
                ret_msg,
                attempt,
                BYBIT_SIGNED_REQUEST_MAX_RETRIES,
                should_retry,
            )
            if should_retry:
                await asyncio.sleep(min(0.2 * attempt, 0.5))
                continue
            raise BybitSignedGETError(
                path=safe_path,
                failure_kind="http_error",
                attempts=attempt,
                http_status=resp.status_code,
                ret_code=safe_ret_code,
                ret_msg=ret_msg,
            )
        if ret_code in (0, "0"):
            return payload
        if _bybit_timestamp_window_error(ret_code, ret_msg) and attempt < BYBIT_SIGNED_REQUEST_MAX_RETRIES:
            BYBIT_LOGGER.warning(
                "BYBIT_SIGNED_RETRY path=%s attempt=%s/%s reason=timestamp_window recv_window=%s",
                safe_path,
                attempt,
                BYBIT_SIGNED_REQUEST_MAX_RETRIES,
                recv_window,
            )
            force_time_sync = True
            continue
        diag = _extract_bybit_timestamp_diag(ret_msg)
        raise BybitSignedGETError(
            path=safe_path,
            failure_kind="api_error",
            attempts=attempt,
            http_status=resp.status_code,
            ret_code=safe_ret_code,
            ret_msg=f"{ret_msg}{(' ' + diag) if diag else ''}",
        )
    raise BybitSignedGETError(
        path=safe_path,
        failure_kind="retry_exhausted",
        attempts=BYBIT_SIGNED_REQUEST_MAX_RETRIES,
        ret_msg="request attempts exhausted",
    )


async def _bybit_signed_post(
    *, base_url: str, api_key: str, api_secret: str, path: str, body: Dict[str, object]
) -> Dict[str, object]:
    body_json = json.dumps(body, separators=(",", ":"))
    normalized_base = _normalize_bybit_base_url(base_url)
    recv_window = _bybit_recv_window_str()
    url = f"{normalized_base}{path}"
    for attempt in range(1, BYBIT_SIGNED_REQUEST_MAX_RETRIES + 1):
        timestamp = await _bybit_timestamp_ms(
            normalized_base, force_time_sync=(attempt > 1)
        )
        signature = _bybit_sign_request(
            timestamp, api_key, api_secret, body_json, recv_window=recv_window
        )
        headers = {
            "Content-Type": "application/json",
            "X-BAPI-API-KEY": api_key,
            "X-BAPI-SIGN": signature,
            "X-BAPI-TIMESTAMP": timestamp,
            "X-BAPI-RECV-WINDOW": recv_window,
            "X-BAPI-SIGN-TYPE": "2",
        }
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                resp = await client.post(url, headers=headers, content=body_json)
        except httpx.TimeoutException:
            raise
        response_content = getattr(resp, "content", b"") or b""
        _record_outbound_traffic(
            "bybit",
            bytes_sent=len(url) + len(body_json) + sum(len(str(v)) for v in headers.values()),
            bytes_received=len(response_content),
            context=path,
        )
        resp.raise_for_status()
        payload = resp.json()
        ret_code = payload.get("retCode")
        ret_msg = payload.get("retMsg") or "Bybit request failed"
        if ret_code in (0, "0"):
            return payload
        if _bybit_timestamp_window_error(ret_code, ret_msg) and attempt < BYBIT_SIGNED_REQUEST_MAX_RETRIES:
            BYBIT_LOGGER.warning(
                "BYBIT_SIGNED_RETRY path=%s attempt=%s/%s reason=timestamp_window recv_window=%s",
                path,
                attempt,
                BYBIT_SIGNED_REQUEST_MAX_RETRIES,
                recv_window,
            )
            continue
        diag = _extract_bybit_timestamp_diag(ret_msg)
        full_msg = f"{ret_msg}{(' ' + diag) if diag else ''}"
        raise BybitSignedAPIError(
            path=path,
            ret_code=ret_code,
            ret_msg=full_msg,
            recv_window=recv_window,
            http_status=getattr(resp, "status_code", None),
            response_body=payload if isinstance(payload, dict) else None,
        )
    raise BybitSignedAPIError(path=path, ret_code="unknown", ret_msg="unknown", recv_window=recv_window, http_status=None, response_body=None)


async def _fetch_bybit_positions_for_category(
    *,
    base_url: str,
    api_key: str,
    api_secret: str,
    category: str,
    account_context: str = "unknown",
) -> tuple[List[Dict[str, object]], List[Dict[str, str]]]:
    endpoint = "/v5/position/list"
    if category == "linear":
        combined: List[Dict[str, object]] = []
        errors: List[Dict[str, str]] = []
        for settle_coin in ("USDT", "USDC"):
            try:
                payload = await _bybit_signed_get(
                    base_url=base_url,
                    api_key=api_key,
                    api_secret=api_secret,
                    path=endpoint,
                    params={"category": "linear", "settleCoin": settle_coin},
                )
                result = payload.get("result")
                rows = result.get("list") if isinstance(result, dict) else None
                if not isinstance(rows, list):
                    raise ValueError("Bybit positions response did not contain result.list")
                combined.extend(row for row in rows if isinstance(row, dict))
            except Exception as exc:
                errors.append(
                    _bybit_open_source_error(
                        exc,
                        account=account_context,
                        category=category,
                        source_type="positions",
                        endpoint=endpoint,
                        settlement_coin=settle_coin,
                        api_key=api_key,
                        api_secret=api_secret,
                    )
                )
        return combined, errors
    try:
        payload = await _bybit_signed_get(
            base_url=base_url,
            api_key=api_key,
            api_secret=api_secret,
            path=endpoint,
            params={"category": category},
        )
        result = payload.get("result")
        rows = result.get("list") if isinstance(result, dict) else None
        if not isinstance(rows, list):
            raise ValueError("Bybit positions response did not contain result.list")
    except Exception as exc:
        return [], [
            _bybit_open_source_error(
                exc,
                account=account_context,
                category=category,
                source_type="positions",
                endpoint=endpoint,
                settlement_coin="n/a",
                api_key=api_key,
                api_secret=api_secret,
            )
        ]
    return [row for row in rows if isinstance(row, dict)], []


async def _confirm_bybit_position_still_open(
    *,
    base_url: str,
    api_key: str,
    api_secret: str,
    category: str,
    symbol: str,
) -> bool:
    symbol_norm = str(symbol or "").strip().upper()
    if not symbol_norm:
        return False
    payload = await _bybit_signed_get(
        base_url=base_url,
        api_key=api_key,
        api_secret=api_secret,
        path="/v5/position/list",
        params={"category": category, "symbol": symbol_norm},
    )
    rows = (payload.get("result") or {}).get("list") or []
    for row in rows:
        if not isinstance(row, dict):
            continue
        side = str(row.get("side") or "").strip().lower()
        size = _to_float(row.get("size")) or 0.0
        if side in {"buy", "sell"} and abs(size) > 0:
            return True
    return False


