async def _collect_bybit_open_items(
    *,
    base_url: str,
    api_key: str,
    api_secret: str,
    account_context: str,
    key_source: str = "unknown",
) -> Dict[str, object]:
    items: List[Dict[str, object]] = []
    errors: List[Dict[str, object]] = []
    try:
        auth_diagnostic = await _bybit_read_only_auth_preflight(
            base_url=base_url,
            api_key=api_key,
            api_secret=api_secret,
            account_context=account_context,
            key_source=key_source,
        )
    except BybitAuthPreflightError as exc:
        return {
            "items": [],
            "errors": [dict(exc.diagnostic)],
            "auth_failed": True,
            "auth_diagnostic": {
                key: exc.diagnostic.get(key)
                for key in (
                    "mode",
                    "base_host",
                    "credential_source",
                    "pair_complete",
                    "credential_fingerprint",
                    "auth_classification",
                )
            },
        }
    confirmed_demo_linear_symbols: Set[str] = set()
    stale_demo_linear_symbols: Set[str] = set()
    position_categories = ["linear", "inverse", "option"]
    order_categories = ["linear", "inverse", "spot", "option"]

    for category in position_categories:
        positions, position_errors = await _fetch_bybit_positions_for_category(
            base_url=base_url,
            api_key=api_key,
            api_secret=api_secret,
            category=category,
            account_context=account_context,
        )
        for source_error in position_errors:
            if isinstance(source_error, dict):
                entry = dict(source_error)
                entry.setdefault("broker", "Bybit")
                entry.setdefault("account", account_context)
                entry.setdefault("category", category)
                entry.setdefault("source_type", "positions")
                entry.setdefault("endpoint", "/v5/position/list")
                entry.setdefault("settlement_coin", "n/a")
                entry["message"] = _safe_bybit_diagnostic_text(
                    entry.get("message"),
                    api_key=api_key,
                    api_secret=api_secret,
                    fallback=f"{entry.get('error_type') or 'Bybit positions request'} failed without a message",
                )
                errors.append(entry)
            else:
                errors.append(
                    _bybit_open_source_error(
                        ValueError(str(source_error or "")),
                        account=account_context,
                        category=category,
                        source_type="positions",
                        endpoint="/v5/position/list",
                        settlement_coin="n/a",
                        api_key=api_key,
                        api_secret=api_secret,
                    )
                )
        for position in positions:
            symbol = str(position.get("symbol") or "").strip().upper()
            size_raw = position.get("size")
            size = None
            try:
                size_val = float(size_raw)
                if size_val == 0:
                    continue
                size = abs(size_val)
            except (TypeError, ValueError):
                size = size_raw
            if account_context == "demo" and category == "linear" and symbol:
                try:
                    still_open = await _confirm_bybit_position_still_open(
                        base_url=base_url,
                        api_key=api_key,
                        api_secret=api_secret,
                        category=category,
                        symbol=symbol,
                    )
                except Exception as exc:
                    confirm_error = _bybit_open_source_error(
                        exc,
                        account=account_context,
                        category=category,
                        source_type="positions confirmation",
                        endpoint="/v5/position/list",
                        settlement_coin="n/a",
                        api_key=api_key,
                        api_secret=api_secret,
                    )
                    confirm_error["instrument"] = symbol
                    errors.append(confirm_error)
                    still_open = True
                if not still_open:
                    stale_demo_linear_symbols.add(symbol)
                    continue
                confirmed_demo_linear_symbols.add(symbol)
            items.append(
                {
                    "broker": "Bybit",
                    "account": account_context,
                    "category": category,
                    "instrument": symbol or position.get("symbol"),
                    "type": "Position",
                    "side": position.get("side"),
                    "size": size,
                    "entry_price": position.get("avgPrice") or position.get("entryPrice"),
                    "order_price": None,
                    "current_price": position.get("markPrice"),
                    "stop_loss": position.get("stopLoss"),
                    "take_profit": position.get("takeProfit"),
                    "leverage": position.get("leverage")
                    or position.get("positionMargin"),
                    # updatedTime is mutable and cannot establish the original
                    # position-open window used for calculator-context linkage.
                    "opened_at": position.get("createdTime"),
                    "id": position.get("positionId") or position.get("positionIdx"),
                    "position_idx": position.get("positionIdx"),
                    "order_id": position.get("orderId"),
                    "order_link_id": position.get("orderLinkId"),
                    "status": "OPEN",
                }
            )

    for category in order_categories:
        orders, order_errors = await _fetch_bybit_orders_for_category(
            base_url=base_url,
            api_key=api_key,
            api_secret=api_secret,
            category=category,
            account_context=account_context,
        )
        for source_error in order_errors:
            if isinstance(source_error, dict):
                entry = dict(source_error)
                entry.setdefault("broker", "Bybit")
                entry.setdefault("account", account_context)
                entry.setdefault("category", category)
                entry.setdefault("source_type", "orders")
                entry.setdefault("endpoint", "/v5/order/realtime")
                entry.setdefault("settlement_coin", "n/a")
                entry["message"] = _safe_bybit_diagnostic_text(
                    entry.get("message"),
                    api_key=api_key,
                    api_secret=api_secret,
                    fallback=f"{entry.get('error_type') or 'Bybit orders request'} failed without a message",
                )
                errors.append(entry)
            else:
                errors.append(
                    _bybit_open_source_error(
                        ValueError(str(source_error or "")),
                        account=account_context,
                        category=category,
                        source_type="orders",
                        endpoint="/v5/order/realtime",
                        settlement_coin="n/a",
                        api_key=api_key,
                        api_secret=api_secret,
                    )
                )
        for order in orders:
            status = order.get("orderStatus")
            if not _is_bybit_open_order(status):
                continue
            symbol = str(order.get("symbol") or "").strip().upper()
            stop_order_type = str(order.get("stopOrderType") or "").strip().lower()
            if (
                account_context == "demo"
                and category == "linear"
                and symbol
                and stop_order_type in {"stoploss", "takeprofit", "partialstoploss", "partialtakeprofit"}
            ):
                if symbol in stale_demo_linear_symbols:
                    continue
                if confirmed_demo_linear_symbols and symbol not in confirmed_demo_linear_symbols:
                    continue
            items.append(
                {
                    "broker": "Bybit",
                    "account": account_context,
                    "category": category,
                    "instrument": symbol or order.get("symbol"),
                    "type": "Order",
                    "side": order.get("side"),
                    "size": order.get("qty"),
                    "entry_price": None,
                    "order_price": order.get("price"),
                    "current_price": order.get("triggerPrice"),
                    "stop_loss": order.get("stopLoss"),
                    "take_profit": order.get("takeProfit"),
                    "leverage": order.get("leverage"),
                    "opened_at": order.get("createdTime"),
                    "id": order.get("orderId"),
                    "order_link_id": order.get("orderLinkId"),
                    "stop_order_type": order.get("stopOrderType"),
                    "status": status or "OPEN",
                }
            )
    for item in items:
        ctx = _lookup_trade_context_for_open_item(item)
        _enrich_open_item_with_trade_context(item, ctx)
    return {
        "items": items,
        "errors": errors,
        "auth_failed": False,
        "auth_diagnostic": auth_diagnostic,
    }


def _load_bounce_traders() -> List[Dict[str, object]]:
    if not BOUNCE_TRADERS_PATH.exists():
        return []
    try:
        payload = json.loads(BOUNCE_TRADERS_PATH.read_text(encoding="utf-8"))
    except Exception:
        return []
    if not isinstance(payload, list):
        return []
    rows: List[Dict[str, object]] = []
    for entry in payload:
        if isinstance(entry, dict):
            rows.append(dict(entry))
    return rows


def _save_bounce_traders(items: List[Dict[str, object]]) -> None:
    BOUNCE_TRADERS_PATH.parent.mkdir(parents=True, exist_ok=True)
    BOUNCE_TRADERS_PATH.write_text(json.dumps(items, indent=2, sort_keys=True), encoding="utf-8")
    _invalidate_open_orders_cache()


def _to_dt_utc(value: object) -> Optional[datetime]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        dt = datetime.fromisoformat(text)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _load_pending_webhooks() -> List[Dict[str, object]]:
    if not PENDING_WEBHOOKS_PATH.exists():
        return []
    try:
        payload = json.loads(PENDING_WEBHOOKS_PATH.read_text(encoding="utf-8"))
    except Exception as exc:  # pragma: no cover - defensive
        raise HTTPException(
            status_code=500,
            detail=f"Unable to read pending webhooks: {exc}",
        ) from exc
    if not isinstance(payload, list):
        raise HTTPException(status_code=500, detail="Pending webhooks data must be a list.")
    cleaned: List[Dict[str, object]] = []
    for entry in payload:
        if isinstance(entry, dict):
            cleaned.append(entry)
    return cleaned


def _save_pending_webhooks(items: List[Dict[str, object]]) -> None:
    PENDING_WEBHOOKS_PATH.write_text(
        json.dumps(items, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    _schedule_dropbox_upload_state_backup()


def _normalize_pending_webhooks(items: object) -> List[Dict[str, object]]:
    if not isinstance(items, list):
        raise HTTPException(status_code=400, detail="Pending webhooks must be a list.")
    now_ts = int(time.time())
    cleaned: List[Dict[str, object]] = []
    for entry in items:
        if not isinstance(entry, dict):
            continue
        payload = dict(entry)
        webhook_id = str(payload.get("id", "")).strip() or f"wh_{uuid4().hex[:12]}"
        payload["id"] = webhook_id
        payload["broker"] = "WEBHOOK"
        payload["type"] = "webhook"
        payload.setdefault("status", "WAITING")
        payload.setdefault("enabled", True)
        payload.setdefault("created_at", now_ts)
        payload["updated_at"] = now_ts
        payload["timeframe"] = _normalize_timeframe(payload.get("timeframe"))
        payload["is_test_trade"] = _normalize_test_trade_flag(
            payload.get("is_test_trade", payload.get("test_trade", payload.get("test")))
        )
        cancel_touch = _parse_pending_cancel_touch_price(payload)
        payload["cancel_if_touched_price"] = cancel_touch
        operator = str(payload.get("cancel_if_touched_operator") or "").strip().lower()
        if operator not in {"lte", "gte"}:
            payload["cancel_if_touched_operator"] = None
        else:
            payload["cancel_if_touched_operator"] = operator
        cleaned.append(payload)
    return cleaned


def _replace_pending_webhooks(items: object) -> List[Dict[str, object]]:
    normalized = _normalize_pending_webhooks(items)
    _save_pending_webhooks(normalized)
    normalized, _diagnostics = _reconcile_pending_webhooks_registry(
        prune_orphan_contexts=False,
        invalidate_cache=False,
    )
    _invalidate_open_orders_cache()
    return normalized


def _upsert_pending_webhook(
    payload: Dict[str, object],
    *,
    invalidate_cache: bool = True,
) -> Dict[str, object]:
    items = _load_pending_webhooks()
    if not isinstance(payload, dict):
        payload = {}

    webhook_id = str(payload.get("id", "")).strip()
    if not webhook_id:
        webhook_id = f"wh_{uuid4().hex[:12]}"

    now_ts = int(time.time())
    entry = dict(payload)
    entry["id"] = webhook_id
    entry["broker"] = "WEBHOOK"
    entry["type"] = "webhook"
    entry.setdefault("status", "WAITING")
    entry.setdefault("enabled", True)
    entry.setdefault("created_at", now_ts)
    entry["updated_at"] = now_ts
    entry["timeframe"] = _normalize_timeframe(entry.get("timeframe"))
    entry["is_test_trade"] = _normalize_test_trade_flag(
        entry.get("is_test_trade", entry.get("test_trade", entry.get("test")))
    )
    entry["cancel_if_touched_price"] = _parse_pending_cancel_touch_price(entry)
    operator = str(entry.get("cancel_if_touched_operator") or "").strip().lower()
    entry["cancel_if_touched_operator"] = operator if operator in {"lte", "gte"} else None

    replaced = False
    for idx, existing in enumerate(items):
        if str(existing.get("id", "")).strip() == webhook_id:
            items[idx] = entry
            replaced = True
            break
    if not replaced:
        items.append(entry)

    _save_pending_webhooks(items)
    opened_at_iso = _epoch_or_iso_to_iso(entry.get("opened_at"))
    raw_category = str(entry.get("category") or "").strip().lower()
    resolved_broker = str(
        entry.get("resolved_broker")
        or entry.get("venue")
        or (raw_category if raw_category in {"bybit", "oanda"} else "")
        or ("bybit" if str(entry.get("asset") or "").strip().lower() == "crypto" else "")
        or ("oanda" if str(entry.get("asset") or "").strip().lower() == "fx" else "")
    ).strip().lower()
    context_category = (
        "linear"
        if raw_category == "bybit"
        else "forex"
        if raw_category == "oanda"
        else raw_category
    )
    context_payload = {
        "pending_webhook_id": webhook_id,
        "broker": resolved_broker,
        "asset": entry.get("asset"),
        "account": str(entry.get("account") or "").strip().lower(),
        "category": context_category,
        "instrument": str(entry.get("instrument") or "").strip().upper(),
        "side": str(entry.get("side") or "").strip().lower(),
        "order_type": str(entry.get("order_type") or "").strip().lower(),
        "entry_price": entry.get("entry_price"),
        "stop_loss": entry.get("stop_loss"),
        "take_profit": entry.get("take_profit"),
        "timeframe": entry.get("timeframe"),
        "is_test_trade": entry.get("is_test_trade"),
        "webhook_mode": "Yes",
        "webhook_status": str(entry.get("status") or "WAITING").title(),
        "setup": entry.get("setup"),
        "pattern": entry.get("pattern"),
        "ema": entry.get("ema"),
        "vwap": entry.get("vwap"),
        "aths_atls": entry.get("aths_atls"),
        "round_number": entry.get("round_number"),
        "open_time": opened_at_iso,
        "status": "ACTIVE",
        "calculation_context_id": payload.get("calculation_context_id"),
        "quote_created_at_ms": payload.get("quote_created_at_ms"),
        "risk_mode": payload.get("risk_mode"),
        "risk_value": payload.get("risk_value"),
        "stop_loss_ticks": payload.get("stop_loss_ticks"),
        "take_profit_ticks": payload.get("take_profit_ticks"),
        "target_mode": payload.get("target_mode"),
        "risk_reward": payload.get("risk_reward"),
        "planned_entry_price": payload.get("planned_entry_price"),
        "planned_stop_price": payload.get("planned_stop_price"),
        "planned_target_price": payload.get("planned_target_price"),
        "cancel_if_touched_price": entry.get("cancel_if_touched_price"),
        "cancel_if_touched_operator": entry.get("cancel_if_touched_operator"),
        "setup_reference_price": entry.get("setup_reference_price"),
        "price_source": entry.get("price_source"),
        "cancel_reason": entry.get("cancel_reason"),
        "cancelled_at": entry.get("cancelled_at"),
    }
    try:
        _upsert_trade_context(context_payload)
    finally:
        # The registry write is already durable even if the companion context
        # write fails, so expose exactly one new version in either outcome.
        if invalidate_cache:
            _invalidate_open_orders_cache()
    return entry


def _update_pending_webhook(
    webhook_id: str,
    updates: Dict[str, object],
    *,
    invalidate_cache: bool = True,
) -> Optional[Dict[str, object]]:
    items = _load_pending_webhooks()
    for idx, entry in enumerate(items):
        if str(entry.get("id", "")).strip() == webhook_id:
            merged = {**entry, **updates, "updated_at": int(time.time())}
            # Prevent callers from converting a pending-webhook record into a broker order.
            merged["broker"] = "WEBHOOK"
            merged["type"] = "webhook"
            items[idx] = merged
            _save_pending_webhooks(items)
            if invalidate_cache:
                _invalidate_open_orders_cache()
            return merged
    return None


def _set_pending_webhook_enabled(webhook_id: str, enabled: bool) -> Dict[str, object]:
    items = _load_pending_webhooks()
    for idx, entry in enumerate(items):
        if str(entry.get("id", "")).strip() == webhook_id:
            items[idx] = {**entry, "enabled": enabled, "updated_at": int(time.time())}
            _save_pending_webhooks(items)
            _invalidate_open_orders_cache()
            return items[idx]
    raise HTTPException(status_code=404, detail="Pending webhook not found.")


def _delete_pending_webhook(
    webhook_id: str,
    *,
    invalidate_cache: bool = True,
) -> bool:
    items = _load_pending_webhooks()
    remaining = [entry for entry in items if str(entry.get("id", "")).strip() != webhook_id]
    if len(remaining) == len(items):
        return False
    _save_pending_webhooks(remaining)
    if invalidate_cache:
        _invalidate_open_orders_cache()
    return True


def _consume_pending_webhook(
    webhook_id: str, *, request_id: str, reason: str = "webhook_received"
) -> bool:
    pending_id = str(webhook_id or "").strip()
    if not pending_id:
        raise ValueError("pending_webhook_id is required to consume pending webhook.")
    now_iso = _utc_now_iso()
    deleted = _delete_pending_webhook(pending_id, invalidate_cache=False)
    BYBIT_LOGGER.info(
        "PENDING_WEBHOOK_CONSUME request_id=%s pending_webhook_id=%s deleted=%s reason=%s",
        request_id,
        pending_id,
        str(deleted).lower(),
        reason,
    )
    context_saved = False
    try:
        _upsert_trade_context(
            {
                "pending_webhook_id": pending_id,
                "status": "CONSUMED" if deleted else "TRIGGERING",
                "consumed_at": now_iso,
                "triggered_at": now_iso,
                "request_id": request_id,
                "consume_reason": str(reason or "").strip() or "webhook_received",
            }
        )
        context_saved = True
    finally:
        if deleted or context_saved:
            _invalidate_open_orders_cache()
    if not deleted:
        raise ValueError("Pending webhook missing or no longer active.")
    _schedule_dropbox_upload_state_backup()
    return True


def _normalize_timeframe(value: object, *, max_length: int = 64) -> str:
    text = " ".join(str(value or "").strip().split())
    if len(text) > max_length:
        text = text[:max_length].strip()
    return text


def _normalize_journal_timeframe(value: object, *, max_length: int = 64) -> str:
    text = _normalize_timeframe(value, max_length=max_length)
    key = " ".join(text.lower().replace("_", " ").replace("-", " ").split())
    aliases = {
        "1m": "1MIN", "1 min": "1MIN", "1 minute": "1MIN",
        "5m": "5MIN", "5 min": "5MIN", "5 minute": "5MIN",
        "15m": "15MIN", "15 min": "15MIN", "15 minute": "15MIN",
        "30m": "30MIN", "30 min": "30MIN", "30 minute": "30MIN",
        "1h": "1H", "1 hour": "1H",
        "4h": "4H", "4 hour": "4H",
        "1d": "1D", "1 day": "1D",
        "1w": "1W", "1 week": "1W",
        "1mo": "1MO", "1 month": "1MO",
    }
    return aliases.get(key, text)


def _normalize_setup(value: object) -> str:
    raw = " ".join(str(value or "").strip().split())
    if not raw:
        return ""
    key = raw.lower()
    mapping = {"pullback": "Pullback", "breakout": "Breakout", "news scalp": "News Scalp", "newsscalp": "News Scalp"}
    if key in mapping:
        return mapping[key]
    raise ValueError("Invalid setup. Expected one of: Pullback, Breakout, News Scalp.")


def _safe_normalize_setup(value: object) -> str:
    try:
        return _normalize_setup(value)
    except Exception:
        return ""


def _normalize_pattern(value: object) -> str:
    pattern = str(value or "").strip().lower()
    if pattern in {"", "range", "channel"}:
        return pattern
    raise ValueError("Invalid pattern. Expected one of: range, channel.")


def _safe_normalize_pattern(value: object) -> str:
    try:
        return _normalize_pattern(value)
    except Exception:
        return ""


def _normalize_yes_no_criterion(value: object, label: str) -> str:
    text = "" if value is None else str(value).strip().lower()
    if text in {"", "none"}:
        return ""
    if text in {"yes", "y", "true", "1"}:
        return "Yes"
    if text in {"no", "n", "false", "0"}:
        return "No"
    raise ValueError(f"Invalid {label}. Expected one of: Yes, No.")


def _normalize_ema(value: object) -> str:
    text = " ".join(str(value or "").strip().lower().replace("_", " ").replace("-", " ").split())
    if text in {"", "none"}:
        return ""
    if text in {"9", "9 ema", "ema 9"}:
        return "9"
    if text in {"20", "20 ema", "ema 20"}:
        return "20"
    if text in {"yes", "y", "true", "1"}:
        return "Yes"
    if text in {"no", "n", "false", "0"}:
        return "No"
    raise ValueError("Invalid EMA. Expected one of: None, Yes, No, 9, 20.")


def _normalize_round_number(value: object) -> str:
    return _normalize_yes_no_criterion(value, "round number")


def _normalize_vwap(value: object) -> str:
    return _normalize_yes_no_criterion(value, "VWAP")


def _normalize_aths_atls(value: object) -> str:
    text = " ".join(str(value or "").strip().lower().replace("_", " ").replace("-", " ").split())
    if text in {"", "none"}:
        return ""
    if text in {"all time high", "ath", "aths"}:
        return "All-Time High"
    if text in {"all time low", "atl", "atls"}:
        return "All-Time Low"
    raise ValueError("Invalid ATH/ATL criterion. Expected one of: All-Time High, All-Time Low.")


def _normalize_test_trade_flag(value: object) -> Optional[bool]:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        if value == 1:
            return True
        if value == 0:
            return False
        return None
    text = str(value).strip().lower()
    if not text:
        return None
    if text in {"yes", "y", "true", "1", "test"}:
        return True
    if text in {"no", "n", "false", "0"}:
        return False
    return None


def _is_test_trade_row(row: Dict[str, object]) -> bool:
    metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
    for key in ("is_test_trade", "test_trade", "test"):
        normalized = _normalize_test_trade_flag(row.get(key))
        if normalized is not None:
            return normalized
        normalized = _normalize_test_trade_flag(metrics.get(key))
        if normalized is not None:
            return normalized
    return False


def _display_test_trade(row: Dict[str, object]) -> str:
    metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
    value = (
        _normalize_test_trade_flag(row.get("is_test_trade"))
        if isinstance(row, dict)
        else None
    )
    if value is None:
        value = _normalize_test_trade_flag(metrics.get("is_test_trade"))
    if value is True:
        return "Yes"
    if value is False:
        return "No"
    return "—"


def _normalize_optional_price(value: object) -> Optional[str]:
    if value in (None, ""):
        return None
    parsed = _to_float(value)
    if parsed is None:
        return str(value).strip() or None
    return str(value).strip() or f"{parsed}"



_TRADE_CONTEXTS_CACHE: Dict[str, object] = {"fingerprint": None, "items": None}

def _trade_context_source_fingerprint() -> List[Dict[str, object]]:
    fingerprints = [_source_file_fingerprint(TRADE_CONTEXTS_PATH)]
    if _trade_context_backup_fallback_enabled():
        fingerprints.extend([
            _source_file_fingerprint(STATE_BACKUP_LOCAL_PATH),
            _source_file_fingerprint(Path(_bybit_demo_calc_context_path())),
        ])
    return fingerprints

def _trade_context_backup_fallback_enabled() -> bool:
    try:
        return Path(TRADE_CONTEXTS_PATH).resolve() == (BASE_DIR / "render" / "data" / "trade_contexts.json").resolve()
    except Exception:
        return False

def _load_trade_contexts() -> List[Dict[str, object]]:
    fingerprint = _trade_context_source_fingerprint()
    cached_fp = _TRADE_CONTEXTS_CACHE.get("fingerprint")
    cached_items = _TRADE_CONTEXTS_CACHE.get("items")
    if cached_fp == fingerprint and isinstance(cached_items, list):
        return [dict(entry) for entry in cached_items if isinstance(entry, dict)]

    payload = _load_json_file(TRADE_CONTEXTS_PATH, [])
    if isinstance(payload, dict):
        payload = payload.get("items", [])
    items = [dict(entry) for entry in payload if isinstance(payload, list) and isinstance(entry, dict)]
    allow_fallback = _trade_context_backup_fallback_enabled()
    if not items and allow_fallback:
        backup_payload = _load_json_file(STATE_BACKUP_LOCAL_PATH, {})
        if isinstance(backup_payload, dict):
            raw_backup_items = backup_payload.get("trade_contexts")
            if isinstance(raw_backup_items, list):
                items = [dict(entry) for entry in raw_backup_items if isinstance(entry, dict)]

    if not items and allow_fallback:
        calc_payload = _load_json_file(_bybit_demo_calc_context_path(), {})
        if isinstance(calc_payload, dict):
            raw_calc_items = calc_payload.get("items")
            if isinstance(raw_calc_items, list):
                items = [dict(entry) for entry in raw_calc_items if isinstance(entry, dict)]
        if not items and isinstance(calc_payload, list):
            items = [dict(entry) for entry in calc_payload if isinstance(entry, dict)]

    _TRADE_CONTEXTS_CACHE["fingerprint"] = fingerprint
    _TRADE_CONTEXTS_CACHE["items"] = [dict(entry) for entry in items]
    return [dict(entry) for entry in items]


def _save_trade_contexts(items: List[Dict[str, object]]) -> None:
    _save_json_file(TRADE_CONTEXTS_PATH, {"items": items, "updated_at": _utc_now_iso()})
    _TRADE_CONTEXTS_CACHE.clear()
    _TRADE_CONTEXTS_CACHE.update({"fingerprint": None, "items": None})
    _schedule_dropbox_upload_state_backup()

def _calculator_context_path() -> Path:
    return TRADE_CONTEXTS_PATH

def _load_calculator_trade_contexts() -> List[Dict[str, object]]:
    return _load_trade_contexts()

def _save_calculator_trade_contexts(items: List[Dict[str, object]]) -> None:
    _save_trade_contexts(items)

def _upsert_calculator_trade_context(
    payload: Dict[str, object],
    require_durable: bool = True,
    invalidate_cache: bool = True,
) -> Dict[str, object]:
    try:
        saved = _upsert_trade_context(payload)
        if invalidate_cache:
            _invalidate_open_orders_cache()
        return saved
    except Exception:
        if require_durable:
            raise
        return dict(payload or {})


def _load_webhook_attempts() -> List[Dict[str, object]]:
    payload = _load_json_file(WEBHOOK_ATTEMPTS_PATH, [])
    if isinstance(payload, dict):
        payload = payload.get("items", [])
    if not isinstance(payload, list):
        return []
    return [dict(entry) for entry in payload if isinstance(entry, dict)]


def _save_webhook_attempts(items: List[Dict[str, object]]) -> None:
    trimmed = [dict(entry) for entry in items if isinstance(entry, dict)][
        -max(1, WEBHOOK_ATTEMPTS_MAX_ITEMS) :
    ]
    _save_json_file(
        WEBHOOK_ATTEMPTS_PATH, {"items": trimmed, "updated_at": _utc_now_iso()}
    )
    _schedule_dropbox_upload_state_backup()


def _record_webhook_attempt(payload: Dict[str, object]) -> Dict[str, object]:
    attempt = dict(payload or {})
    request_id = str(attempt.get("request_id") or "").strip() or f"wh-attempt-{uuid4().hex[:12]}"
    now_iso = _utc_now_iso()
    attempt["request_id"] = request_id
    attempt.setdefault("received_at", now_iso)
    attempt["updated_at"] = now_iso
    items = _load_webhook_attempts()
    items = [entry for entry in items if str(entry.get("request_id") or "").strip() != request_id]
    items.append(attempt)
    _save_webhook_attempts(items)
    return dict(attempt)


def _update_webhook_attempt(request_id: str, updates: Dict[str, object]) -> Optional[Dict[str, object]]:
    attempt_id = str(request_id or "").strip()
    if not attempt_id:
        return None
    items = _load_webhook_attempts()
    for idx, item in enumerate(items):
        if str(item.get("request_id") or "").strip() != attempt_id:
            continue
        merged = {**item, **dict(updates or {}), "updated_at": _utc_now_iso()}
        items[idx] = merged
        _save_webhook_attempts(items)
        return dict(merged)
    return None


def _is_local_host(host: str) -> bool:
    raw = str(host or "").strip().lower()
    return raw in {"", "localhost", "127.0.0.1", "0.0.0.0", "::1"}


def _public_webhook_base_url(request: Request) -> str:
    configured = os.getenv("PUBLIC_WEBHOOK_BASE_URL", "").strip().rstrip("/")
    if configured:
        return configured
    render_url = os.getenv("RENDER_EXTERNAL_URL", "").strip().rstrip("/")
    if render_url:
        return render_url
    return str(request.base_url).rstrip("/")


def _calculator_webhook_capability(request: Request) -> Dict[str, object]:
    remote_base = str(os.getenv("RENDER_CALCULATOR_BASE_URL") or "").strip().rstrip("/")
    remote_parsed = urlparse(remote_base) if remote_base else None
    remote_host = str((remote_parsed.hostname if remote_parsed else "") or "").strip().lower()
    if APP_PROFILE == "local" and remote_base and remote_parsed and remote_parsed.scheme in {"http", "https"} and not _is_local_host(remote_host):
        return {
            "available": True,
            "mode": "remote_render",
            "app_profile": APP_PROFILE,
            "pending_owner": "remote_render",
            "public_webhook_base_url": remote_base,
            "webhook_origin_host": remote_host,
            "webhook_endpoint_url": f"{remote_base}/api/calculator/webhook",
            "quote_endpoint_url": f"{remote_base}/api/calculator/quote",
        }

    webhook_base_url = _public_webhook_base_url(request)
    webhook_endpoint_url = f"{webhook_base_url}/api/calculator/webhook"
    parsed_base = urlparse(webhook_base_url if "://" in webhook_base_url else f"https://{webhook_base_url}")
    webhook_origin_host = str(parsed_base.hostname or "").strip().lower() or None
    local_override_allowed = str(os.getenv("ALLOW_LOCAL_TRADINGVIEW_WEBHOOKS") or "").strip().lower() in {"1", "true", "yes", "on"}
    app_instance_id = str(os.getenv("APP_INSTANCE_ID") or os.getenv("RENDER_INSTANCE_ID") or os.getenv("RENDER_SERVICE_ID") or os.getenv("HOSTNAME") or "").strip() or None
    public_base_configured = bool(os.getenv("PUBLIC_WEBHOOK_BASE_URL", "").strip() or os.getenv("RENDER_EXTERNAL_URL", "").strip())
    available = not (_is_local_host(webhook_origin_host or "") and not local_override_allowed)
    capability: Dict[str, object] = {
        "available": available,
        "mode": "same_instance",
        "pending_owner": "same_instance",
        "public_webhook_base_url": webhook_base_url,
        "webhook_endpoint_url": webhook_endpoint_url,
        "webhook_origin_host": webhook_origin_host,
        "app_profile": APP_PROFILE,
        "app_instance_id": app_instance_id,
        "public_base_configured": public_base_configured,
        "local_override_allowed": local_override_allowed,
    }
    if not available:
        capability["unavailable_code"] = "LOCAL_WEBHOOK_UNREACHABLE"
        capability["unavailable_message"] = "Set RENDER_CALCULATOR_BASE_URL=https://<your-render-service>.onrender.com in C:\\GPT\\env.env, then restart run_local_master_control.bat."
        capability["resolution"] = "Use a non-local Render URL in RENDER_CALCULATOR_BASE_URL for local Webhook=Yes, or disable Webhook and calculate locally."
    return capability


def _render_calculator_host() -> str:
    remote_base = str(os.getenv("RENDER_CALCULATOR_BASE_URL") or "").strip().rstrip("/")
    parsed = urlparse(remote_base) if remote_base else None
    return str((parsed.hostname if parsed else "") or "").strip().lower()


def _calculator_js_fingerprint() -> Dict[str, str]:
    js_path = BASE_DIR / "render" / "static" / "calculator.js"
    try:
        raw = js_path.read_bytes()
        sha12 = hashlib.sha256(raw).hexdigest()[:12]
        mtime = str(int(js_path.stat().st_mtime))
    except Exception:
        sha12 = "unknown"
        mtime = "unknown"
    return {"sha12": sha12, "mtime": mtime, "path": str(js_path)}


def _prune_trade_contexts(items: List[Dict[str, object]]) -> List[Dict[str, object]]:
    cutoff = datetime.now(timezone.utc) - timedelta(days=30)
    kept: List[Dict[str, object]] = []
    for entry in items:
        status = str(entry.get("status") or "").strip().upper()
        updated_at = _parse_iso_datetime(entry.get("updated_at") or entry.get("closed_at"))
        if status in {"CLOSED", "CANCELLED"} and updated_at and updated_at < cutoff:
            continue
        kept.append(entry)
    return kept


def _upsert_bybit_demo_calc_context(
    context: Dict[str, object],
    active_folder: Optional[str] = None,
    require_durable: bool = True,
    invalidate_cache: bool = False,
) -> Dict[str, object]:
    now = _utc_now_iso()
    ctx = dict(_sanitize_calc_context_obj(context) if isinstance(context, dict) else {})
    ctx["calculation_context_id"] = str(ctx.get("calculation_context_id") or "").strip() or f"calcctx_bybit_demo_{uuid4().hex}"
    ctx.setdefault("created_at", now)
    ctx["updated_at"] = now
    state = _load_bybit_demo_calc_contexts(active_folder)
    items = [i for i in (state.get("items") or []) if isinstance(i, dict)]
    idx = next((n for n, i in enumerate(items) if str(i.get("calculation_context_id") or "") == ctx["calculation_context_id"]), None)
    if idx is None:
        items.append(ctx)
    else:
        merged = dict(items[idx]); merged.update({k: v for k, v in ctx.items() if v is not None}); items[idx] = merged; ctx = merged
    state["items"] = items[-1000:]
    try:
        _save_bybit_demo_calc_contexts(state, active_folder)
        if invalidate_cache:
            _invalidate_open_orders_cache()
    except Exception:
        if require_durable:
            raise
    return ctx


def _lookup_bybit_demo_calc_context_for_row(row_or_refs: Dict[str, object], active_folder: Optional[str] = None) -> Optional[Dict[str, object]]:
    try:
        state = _load_bybit_demo_calc_contexts(active_folder)
    except Exception:
        return None
    items = [i for i in (state.get("items") or []) if isinstance(i, dict)]
    calc_id = str(row_or_refs.get("calculation_context_id") or "").strip()
    oid = str(row_or_refs.get("order_id") or row_or_refs.get("orderId") or "").strip()
    for item in reversed(items):
        if calc_id and str(item.get("calculation_context_id") or "").strip() == calc_id:
            return dict(item)
        if oid and str(item.get("order_id") or "").strip() == oid:
            return dict(item)
    return None


def _merge_bybit_demo_calc_context_into_row(row: Dict[str, object], ctx: Dict[str, object]) -> Dict[str, object]:
    out = dict(row)
    if not out.get("stop_loss"): out["stop_loss"] = ctx.get("stop_loss")
    if not out.get("take_profit"): out["take_profit"] = ctx.get("take_profit")
    if not out.get("timeframe"): out["timeframe"] = ctx.get("timeframe")
    if out.get("is_test_trade") in (None, ""): out["is_test_trade"] = ctx.get("is_test_trade")
    if out.get("setup") in (None, ""):
        ctx_setup = _safe_normalize_setup(ctx.get("setup"))
        if ctx_setup:
            out["setup"] = ctx_setup
    for field in ("pattern", "ema", "vwap", "aths_atls", "round_number"):
        if out.get(field) in (None, "") and ctx.get(field) not in (None, ""):
            out[field] = ctx.get(field)
    out.setdefault("planned_entry_price", ctx.get("entry_price"))
    out.setdefault("planned_stop_price", ctx.get("stop_loss"))
    out.setdefault("planned_target_price", ctx.get("take_profit"))
    for k in ("risk_mode", "risk_value", "stop_loss_ticks", "take_profit_ticks", "target_mode", "risk_reward"):
        if out.get(k) in (None, "") and ctx.get(k) not in (None, ""):
            out[k] = ctx.get(k)
    out["calculation_context_id"] = out.get("calculation_context_id") or ctx.get("calculation_context_id")
    refs = out.get("raw_refs") if isinstance(out.get("raw_refs"), dict) else {}
    refs["calculation_context_source"] = "repo_calculation_context" if _calc_context_uses_repo_local() else "dropbox_calculation_context"
    out["raw_refs"] = refs
    return out


def _upsert_trade_context(payload: Dict[str, object]) -> Dict[str, object]:
    items = _load_trade_contexts()
    now_iso = _utc_now_iso()
    pending_id = str(payload.get("pending_webhook_id") or "").strip()
    order_id = str(payload.get("order_id") or "").strip()
    order_link_id = str(payload.get("order_link_id") or "").strip()
    parent_order_link_id = str(payload.get("parent_order_link_id") or "").strip()
    trade_id = str(payload.get("trade_id") or "").strip()
    transaction_id = str(payload.get("transaction_id") or "").strip()

    def _is_blank(value: object) -> bool:
        return value is None or (isinstance(value, str) and value.strip() == "")

    id_fields = ("calculation_context_id", "context_id", "pending_webhook_id", "order_id", "order_link_id", "parent_order_link_id", "trade_id", "transaction_id")
    incoming_ids = {
        "calculation_context_id": str(payload.get("calculation_context_id") or payload.get("context_id") or "").strip(),
        "context_id": str(payload.get("context_id") or payload.get("calculation_context_id") or "").strip(),
        "pending_webhook_id": pending_id,
        "order_id": order_id,
        "order_link_id": order_link_id,
        "parent_order_link_id": parent_order_link_id,
        "trade_id": trade_id,
        "transaction_id": transaction_id,
    }

    merged_payload = dict(payload)
    if "is_test_trade" in merged_payload or "test_trade" in merged_payload or "test" in merged_payload:
        merged_payload["is_test_trade"] = _normalize_test_trade_flag(
            merged_payload.get("is_test_trade", merged_payload.get("test_trade", merged_payload.get("test")))
        )
    if "timeframe" in merged_payload:
        merged_payload["timeframe"] = _normalize_timeframe(merged_payload.get("timeframe"))
    if "setup" in merged_payload:
        merged_payload["setup"] = _normalize_setup(merged_payload.get("setup"))
    if "pattern" in merged_payload:
        merged_payload["pattern"] = _normalize_pattern(merged_payload.get("pattern"))
    if "ema" in merged_payload:
        merged_payload["ema"] = _normalize_ema(merged_payload.get("ema"))
    if "vwap" in merged_payload:
        merged_payload["vwap"] = _normalize_vwap(merged_payload.get("vwap"))
    if "aths_atls" in merged_payload:
        merged_payload["aths_atls"] = _normalize_aths_atls(merged_payload.get("aths_atls"))
    if "round_number" in merged_payload:
        merged_payload["round_number"] = _normalize_round_number(merged_payload.get("round_number"))
    for field in ("entry_price", "stop_loss", "take_profit"):
        if field in merged_payload:
            merged_payload[field] = _normalize_optional_price(merged_payload.get(field))
    for field in (
        "broker",
        "account",
        "category",
        "instrument",
        "side",
        "order_type",
        "pending_webhook_id",
        "order_id",
        "order_link_id",
        "parent_order_link_id",
        "trade_id",
        "transaction_id",
    ):
        if field in merged_payload and merged_payload.get(field) is not None:
            merged_payload[field] = str(merged_payload.get(field)).strip()
    merged_payload["updated_at"] = now_iso
    merged_payload.setdefault("created_at", now_iso)
    if not merged_payload.get("status"):
        merged_payload["status"] = "ACTIVE"

    matched_indices: List[int] = []
    for idx, entry in enumerate(items):
        for id_field in id_fields:
            incoming_id = incoming_ids.get(id_field, "")
            if not incoming_id:
                continue
            if str(entry.get(id_field) or "").strip() == incoming_id:
                matched_indices.append(idx)
                break

    if matched_indices:
        base_idx = matched_indices[0]
        merged = dict(items[base_idx])
        for idx in matched_indices[1:]:
            for k, v in items[idx].items():
                if k in {"created_at", "updated_at"}:
                    continue
                if _is_blank(merged.get(k)) and not _is_blank(v):
                    merged[k] = v

        for k, v in merged_payload.items():
            if k == "created_at":
                if _is_blank(merged.get("created_at")):
                    merged["created_at"] = v
                continue
            if _is_blank(v):
                continue
            merged[k] = v
        if merged_payload.get("is_test_trade") is None and "is_test_trade" in merged and merged.get("is_test_trade") is not None:
            pass
        elif "is_test_trade" in merged_payload:
            merged["is_test_trade"] = merged_payload.get("is_test_trade")

        merged["updated_at"] = now_iso
        merged.setdefault("created_at", now_iso)
        for field in id_fields:
            if _is_blank(merged.get(field)) and incoming_ids.get(field):
                merged[field] = incoming_ids[field]

        deduped_items = [entry for idx, entry in enumerate(items) if idx not in matched_indices]
        deduped_items.insert(base_idx, merged)
        items = deduped_items
        merged_payload = merged
    else:
        items.append(merged_payload)

    pruned = _prune_trade_contexts(items)
    _save_trade_contexts(pruned)
    return merged_payload


def _mark_trade_context_closed_or_cancelled(*, pending_webhook_id: Optional[str] = None, order_id: Optional[str] = None, trade_id: Optional[str] = None, status: str = "CLOSED") -> None:
    items = _load_trade_contexts()
    now_iso = _utc_now_iso()
    changed = False
    for idx, entry in enumerate(items):
        matches = False
        if pending_webhook_id and str(entry.get("pending_webhook_id") or "").strip() == str(pending_webhook_id).strip():
            matches = True
        if order_id and str(entry.get("order_id") or "").strip() == str(order_id).strip():
            matches = True
        if trade_id and str(entry.get("trade_id") or "").strip() == str(trade_id).strip():
            matches = True
        if matches:
            entry = dict(entry)
            entry["status"] = status
            entry["closed_at"] = now_iso
            entry["updated_at"] = now_iso
            items[idx] = entry
            changed = True
    if changed:
        _save_trade_contexts(_prune_trade_contexts(items))


def _lookup_trade_context_for_open_item(item: Dict[str, object]) -> Optional[Dict[str, object]]:
    contexts = _load_trade_contexts()
    refs = item.get("raw_refs") if isinstance(item.get("raw_refs"), dict) else {}
    broker = str(item.get("broker") or "").strip().lower()
    account = str(item.get("account") or "").strip().lower()
    category = str(item.get("category") or "").strip().lower()
    instrument = str(item.get("instrument") or "").strip().upper()
    side = _normalize_side_for_comparison(item.get("side"))
    calculation_context_id = str(
        item.get("calculation_context_id")
        or item.get("context_id")
        or refs.get("calculation_context_id")
        or refs.get("context_id")
        or ""
    ).strip()
    item_type = str(item.get("type") or "").strip().lower()
    order_id = str(
        item.get("order_id")
        or (item.get("id") if item_type in {"order", "webhook"} else "")
        or ""
    ).strip()
    order_ids: List[str] = []
    raw_order_ids = refs.get("order_ids")
    if isinstance(raw_order_ids, list):
        order_ids = [str(v or "").strip() for v in raw_order_ids if str(v or "").strip()]
    order_link_id = str(item.get("order_link_id") or item.get("orderLinkId") or "").strip()
    parent_order_link_id = str(
        item.get("parent_order_link_id") or item.get("parentOrderLinkId") or ""
    ).strip()
    trade_id = str(item.get("trade_id") or "").strip()

    for ctx in contexts:
        if calculation_context_id and str(ctx.get("calculation_context_id") or ctx.get("context_id") or "").strip() == calculation_context_id:
            return ctx
    for ctx in contexts:
        if order_id and str(ctx.get("order_id") or "").strip() == order_id:
            return ctx
    if order_ids:
        order_id_matches: List[Dict[str, object]] = []
        seen_match_ids: Set[str] = set()
        for oid in order_ids:
            for ctx in contexts:
                if oid and str(ctx.get("order_id") or "").strip() == oid:
                    key = str(ctx.get("order_id") or "").strip() or str(ctx.get("calculation_context_id") or "").strip() or str(id(ctx))
                    if key not in seen_match_ids:
                        seen_match_ids.add(key)
                        order_id_matches.append(ctx)
        if len(order_id_matches) == 1:
            return order_id_matches[0]
        if len(order_id_matches) > 1:
            return None
    for ctx in contexts:
        if order_link_id and str(ctx.get("order_link_id") or "").strip() == order_link_id:
            return ctx
    for ctx in contexts:
        if parent_order_link_id and str(ctx.get("parent_order_link_id") or "").strip() == parent_order_link_id:
            return ctx
    for ctx in contexts:
        if trade_id and str(ctx.get("trade_id") or "").strip() == trade_id:
            return ctx

    candidates = [
        ctx
        for ctx in contexts
        if str(ctx.get("broker") or "").strip().lower() == broker
        and str(ctx.get("account") or "").strip().lower() == account
        and str(ctx.get("category") or "").strip().lower() == category
        and str(ctx.get("instrument") or "").strip().upper() == instrument
        and _normalize_side_for_comparison(ctx.get("side")) == side
        and str(ctx.get("status") or "ACTIVE").strip().upper()
        in {"ACTIVE", "PENDING_ENTRY", "SUBMITTED"}
    ]
    if not candidates or not all((broker, account, category, instrument, side)):
        return None
    opened_ts = _canonical_trade_epoch_second(item.get("opened_at") or item.get("created_at"))
    if opened_ts is None:
        return None
    window_candidates: List[Dict[str, object]] = []
    max_window_seconds = 90 * 60
    for ctx in candidates:
        ctx_opened_ts = (
            _canonical_trade_epoch_second(ctx.get("open_time"))
            or _canonical_trade_epoch_second(ctx.get("created_at"))
            or _canonical_trade_epoch_second(ctx.get("opened_at"))
        )
        if ctx_opened_ts is None:
            continue
        delta = abs(opened_ts - ctx_opened_ts)
        if delta <= max_window_seconds:
            window_candidates.append(ctx)
    if len(window_candidates) == 1:
        return window_candidates[0]
    return None


def _enrich_open_item_with_trade_context(
    item: Dict[str, object],
    context: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Attach calculator intent without inventing it for broker-originated rows."""

    ctx = context if isinstance(context, dict) else _lookup_trade_context_for_open_item(item)
    broker = str(item.get("broker") or "").strip()
    broker_norm = broker.lower()
    item["venue"] = broker or None
    if isinstance(ctx, dict):
        item["asset"] = (
            ctx.get("asset")
            or ("crypto" if broker_norm == "bybit" else "fx" if broker_norm == "oanda" else None)
        )
        order_type = str(ctx.get("order_type") or "").strip().lower()
        item["order_type"] = order_type.title() if order_type else None
        item["stop_loss_ticks"] = ctx.get("stop_loss_ticks")
        item["take_profit_ticks"] = ctx.get("take_profit_ticks")
        item["target_mode"] = ctx.get("target_mode")
        target_mode = str(ctx.get("target_mode") or "").strip().lower()
        item["target_mode_display"] = (
            "Risk/Reward" if target_mode == "rr" else "Ticks" if target_mode == "ticks" else None
        )
        item["risk_mode"] = ctx.get("risk_mode")
        risk_mode = str(ctx.get("risk_mode") or "").strip().lower()
        item["risk_mode_display"] = (
            "Percent" if risk_mode == "percent" else "Fixed AUD" if risk_mode == "fixed_aud" else None
        )
        item["risk_value"] = ctx.get("risk_value")
        item["risk_unit"] = "%" if risk_mode == "percent" else "AUD" if risk_mode == "fixed_aud" else None
        if ctx.get("risk_value") not in (None, ""):
            if risk_mode == "percent":
                item["risk_value_display"] = f"{ctx.get('risk_value')}%"
            elif risk_mode == "fixed_aud":
                item["risk_value_display"] = f"AUD {ctx.get('risk_value')}"
            else:
                item["risk_value_display"] = str(ctx.get("risk_value"))
        else:
            item["risk_value_display"] = None
        item["risk_reward"] = ctx.get("risk_reward")
        item["timeframe"] = _normalize_journal_timeframe(
            ctx.get("timeframe") or item.get("timeframe")
        )
        item["is_test_trade"] = _display_test_trade(ctx)
        item["setup"] = ctx.get("setup") or None
        pattern = _safe_normalize_pattern(ctx.get("pattern"))
        item["pattern"] = pattern.title() if pattern else "None"
        item["ema"] = ctx.get("ema") or None
        item["vwap"] = ctx.get("vwap") or None
        item["aths_atls"] = ctx.get("aths_atls") or None
        item["round_number"] = ctx.get("round_number") or None
        pending_webhook_id = str(ctx.get("pending_webhook_id") or "").strip()
        webhook_flag = _normalize_test_trade_flag(
            ctx.get("webhook_mode", ctx.get("webhook"))
        )
        if pending_webhook_id:
            item["webhook_mode"] = "Yes"
            item["webhook_status"] = (
                str(item.get("status") or "Waiting")
                if broker_norm == "webhook"
                else str(ctx.get("webhook_status") or "Triggered")
            )
        else:
            item["webhook_mode"] = "Yes" if webhook_flag is True else "No"
            item["webhook_status"] = (
                str(ctx.get("webhook_status") or "Not used")
                if webhook_flag is not True
                else str(ctx.get("webhook_status") or "Configured")
            )
        item["planned_entry_price"] = (
            ctx.get("planned_entry_price")
            if ctx.get("planned_entry_price") not in (None, "")
            else ctx.get("entry_price")
        )
        item["planned_stop_price"] = (
            ctx.get("planned_stop_price")
            if ctx.get("planned_stop_price") not in (None, "")
            else ctx.get("stop_loss")
        )
        item["planned_target_price"] = (
            ctx.get("planned_target_price")
            if ctx.get("planned_target_price") not in (None, "")
            else ctx.get("take_profit")
        )
        item["calculation_context_id"] = (
            item.get("calculation_context_id")
            or ctx.get("calculation_context_id")
            or ctx.get("context_id")
        )
        item["context_linked"] = True
    else:
        item["asset"] = "crypto" if broker_norm == "bybit" else "fx" if broker_norm == "oanda" else None
        item["timeframe"] = _normalize_journal_timeframe(item.get("timeframe"))
        item["is_test_trade"] = _display_test_trade(item)
        for field in (
            "order_type",
            "stop_loss_ticks",
            "take_profit_ticks",
            "target_mode",
            "target_mode_display",
            "risk_mode",
            "risk_mode_display",
            "risk_value",
            "risk_unit",
            "risk_value_display",
            "risk_reward",
            "setup",
            "pattern",
            "ema",
            "vwap",
            "aths_atls",
            "round_number",
            "webhook_mode",
            "webhook_status",
            "planned_entry_price",
            "planned_stop_price",
            "planned_target_price",
        ):
            item.setdefault(field, None)
        item["context_linked"] = False
    return item


def _lookup_trade_context_for_journal_row(row: Dict[str, object]) -> Optional[Dict[str, object]]:
    contexts = _load_trade_contexts()
    refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
    order_id = str(
        refs.get("orderId")
        or refs.get("orderID")
        or row.get("orderId")
        or row.get("orderID")
        or row.get("order_id")
        or ""
    ).strip()
    order_ids: List[str] = []
    raw_order_ids = refs.get("order_ids")
    if isinstance(raw_order_ids, list):
        order_ids = [str(v or "").strip() for v in raw_order_ids if str(v or "").strip()]
    trade_id = str(refs.get("tradeId") or refs.get("tradeID") or "").strip()
    transaction_id = str(refs.get("transactionId") or refs.get("transactionID") or "").strip()
    order_link_id = str(
        refs.get("orderLinkId")
        or refs.get("order_link_id")
        or refs.get("parentOrderLinkId")
        or refs.get("parent_order_link_id")
        or row.get("orderLinkId")
        or row.get("order_link_id")
        or ""
    ).strip()
    parent_order_link_id = str(
        refs.get("parentOrderLinkId")
        or refs.get("parent_order_link_id")
        or row.get("parentOrderLinkId")
        or row.get("parent_order_link_id")
        or ""
    ).strip()
    pending_webhook_id = str(refs.get("pending_webhook_id") or row.get("pending_webhook_id") or "").strip()
    calculation_context_id = str(refs.get("calculation_context_id") or row.get("calculation_context_id") or row.get("context_id") or "").strip()
    for ctx in contexts:
        if calculation_context_id and str(ctx.get("calculation_context_id") or ctx.get("context_id") or "").strip() == calculation_context_id:
            return ctx
    for ctx in contexts:
        if order_id and str(ctx.get("order_id") or "").strip() == order_id:
            return ctx
    if order_ids:
        order_id_matches: List[Dict[str, object]] = []
        seen_match_ids: Set[str] = set()
        for oid in order_ids:
            for ctx in contexts:
                if oid and str(ctx.get("order_id") or "").strip() == oid:
                    key = str(ctx.get("order_id") or "").strip() or str(ctx.get("calculation_context_id") or "").strip() or str(id(ctx))
                    if key not in seen_match_ids:
                        seen_match_ids.add(key)
                        order_id_matches.append(ctx)
        if len(order_id_matches) == 1:
            return order_id_matches[0]
        if len(order_id_matches) > 1:
            return None
    for ctx in contexts:
        if order_link_id and str(ctx.get("order_link_id") or "").strip() == order_link_id:
            return ctx
    for ctx in contexts:
        if parent_order_link_id and str(ctx.get("parent_order_link_id") or "").strip() == parent_order_link_id:
            return ctx
    for ctx in contexts:
        if trade_id and str(ctx.get("trade_id") or "").strip() == trade_id:
            return ctx
    for ctx in contexts:
        if transaction_id and str(ctx.get("transaction_id") or "").strip() == transaction_id:
            return ctx
    for ctx in contexts:
        if pending_webhook_id and str(ctx.get("pending_webhook_id") or "").strip() == pending_webhook_id:
            return ctx
    return None


def _lookup_trade_context_by_market_window(
    row: Dict[str, object],
    *,
    max_window_seconds: int = 90 * 60,
    include_inactive: bool = False,
) -> Optional[Dict[str, object]]:
    contexts = _load_trade_contexts()
    broker = str(row.get("broker") or row.get("source") or "").strip().lower()
    account = str(row.get("account") or "").strip().lower()
    instrument = str(row.get("instrument") or row.get("symbol") or "").strip().upper()
    side = _normalize_side_for_comparison(row.get("side"))
    target_sec = _canonical_trade_epoch_second(row.get("close_time") or row.get("open_time"))
    if not broker or not account or not instrument or not side or target_sec is None:
        return None

    candidates: List[Tuple[int, Dict[str, object]]] = []
    for ctx in contexts:
        if str(ctx.get("broker") or "").strip().lower() != broker:
            continue
        if str(ctx.get("account") or "").strip().lower() != account:
            continue
        if str(ctx.get("instrument") or "").strip().upper() != instrument:
            continue
        if _normalize_side_for_comparison(ctx.get("side")) != side:
            continue
        if not include_inactive and str(ctx.get("status") or "ACTIVE").strip().upper() != "ACTIVE":
            continue
        ctx_time_sec = (
            _canonical_trade_epoch_second(ctx.get("closed_at"))
            or _canonical_trade_epoch_second(ctx.get("updated_at"))
            or _canonical_trade_epoch_second(ctx.get("created_at"))
            or _canonical_trade_epoch_second(ctx.get("open_time"))
            or _canonical_trade_epoch_second(ctx.get("opened_at"))
        )
        if ctx_time_sec is None:
            continue
        delta = abs(ctx_time_sec - target_sec)
        if delta <= max_window_seconds:
            candidates.append((delta, ctx))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[0])
    return candidates[0][1]


def _resolve_bybit_closed_pnl_trade_context(
    *,
    account_mode: str,
    symbol: str,
    side: object,
    order_id: object = None,
    order_link_id: object = None,
    parent_order_link_id: object = None,
    trade_id: object = None,
    transaction_id: object = None,
    close_time: object = None,
    max_lookback_seconds: int = 7 * 24 * 60 * 60,
) -> Optional[Dict[str, object]]:
    refs = {
        "order_id": str(order_id or "").strip(),
        "order_link_id": str(order_link_id or "").strip(),
        "parent_order_link_id": str(parent_order_link_id or "").strip(),
        "trade_id": str(trade_id or "").strip(),
        "transaction_id": str(transaction_id or "").strip(),
    }
    contexts = _load_trade_contexts()
    close_ts = _canonical_trade_epoch_second(close_time)

    def _ctx_time_order_valid(ctx: Dict[str, object]) -> bool:
        if close_ts is None:
            return True
        ctx_open_ts = _canonical_trade_epoch_second(ctx.get("open_time")) or _canonical_trade_epoch_second(ctx.get("created_at"))
        if ctx_open_ts is None:
            return True
        return ctx_open_ts < close_ts

    for ref_field in ("order_id", "order_link_id", "parent_order_link_id", "trade_id", "transaction_id"):
        ref_value = refs[ref_field]
        if not ref_value:
            continue
        for ctx in contexts:
            if str(ctx.get(ref_field) or "").strip() == ref_value and _ctx_time_order_valid(ctx):
                return ctx
    broker = "bybit"
    account = "demo" if str(account_mode).strip().lower() == "demo" else "live"
    instrument = str(symbol or "").strip().upper()
    side_norm = _normalize_side_for_comparison(side)
    if not close_ts or not instrument or not side_norm:
        return None

    candidates: List[Tuple[int, int, Dict[str, object]]] = []
    for ctx in contexts:
        if str(ctx.get("broker") or "").strip().lower() != broker:
            continue
        if str(ctx.get("account") or "").strip().lower() != account:
            continue
        if str(ctx.get("instrument") or "").strip().upper() != instrument:
            continue
        if _normalize_side_for_comparison(ctx.get("side")) != side_norm:
            continue
        ctx_open_ts = _canonical_trade_epoch_second(ctx.get("open_time")) or _canonical_trade_epoch_second(ctx.get("created_at"))
        if ctx_open_ts is None or ctx_open_ts > close_ts:
            continue
        if close_ts - ctx_open_ts > max_lookback_seconds:
            continue
        status = str(ctx.get("status") or "").strip().upper()
        status_boost = 0 if status == "ACTIVE" else 1
        candidates.append((close_ts - ctx_open_ts, status_boost, ctx))
    if not candidates:
        return None
    candidates.sort(key=lambda item: (item[0], item[1]))
    return candidates[0][2]


def _oanda_credentials(mode: str) -> Dict[str, str]:
    suffix = "_DEMO" if mode == "demo" else ""
    api_key = os.getenv(f"OANDA_API_KEY{suffix}") or os.getenv(f"OANDA_TOKEN{suffix}")
    account_id = os.getenv(f"OANDA_ACCOUNT_ID{suffix}")
    base_url = (
        os.getenv(f"OANDA_BASE_URL{suffix}")
        or os.getenv(f"OANDA_URL{suffix}")
        or os.getenv(f"OANDA_API_URL{suffix}")
        or _oanda_base_url()
    )
    return {
        "api_key": api_key or "",
        "account_id": account_id or "",
        "base_url": base_url,
    }
APP_LOGGER = logging.getLogger("uvicorn.error")
BALANCE_LOGGER = logging.getLogger("uvicorn.error")
BYBIT_LOGGER = logging.getLogger("uvicorn.error")
CALCULATOR_LOGGER = logging.getLogger("uvicorn.error")
_OUTBOUND_METRICS_LOCK = threading.Lock()
_OUTBOUND_METRICS: Dict[str, Dict[str, object]] = {}


def _record_outbound_traffic(
    destination: str,
    *,
    request_count: int = 1,
    bytes_sent: int = 0,
    bytes_received: int = 0,
    context: Optional[str] = None,
) -> None:
    now = _utc_now_iso()
    with _OUTBOUND_METRICS_LOCK:
        node = _OUTBOUND_METRICS.setdefault(
            destination,
            {
                "requests": 0,
                "bytes_sent": 0,
                "bytes_received": 0,
                "last_context": None,
                "last_seen": None,
            },
        )
        node["requests"] = int(node.get("requests", 0)) + max(0, int(request_count))
        node["bytes_sent"] = int(node.get("bytes_sent", 0)) + max(0, int(bytes_sent))
        node["bytes_received"] = int(node.get("bytes_received", 0)) + max(0, int(bytes_received))
        if context:
            node["last_context"] = context
        node["last_seen"] = now


def _snapshot_outbound_traffic() -> Dict[str, Dict[str, object]]:
    with _OUTBOUND_METRICS_LOCK:
        return {
            key: {
                "requests": int(value.get("requests", 0)),
                "bytes_sent": int(value.get("bytes_sent", 0)),
                "bytes_received": int(value.get("bytes_received", 0)),
                "last_context": value.get("last_context"),
                "last_seen": value.get("last_seen"),
            }
            for key, value in _OUTBOUND_METRICS.items()
        }


async def _log_outbound_traffic_summary() -> None:
    while True:
        await asyncio.sleep(max(30.0, OUTBOUND_METRICS_LOG_SECONDS))
        snapshot = _snapshot_outbound_traffic()
        if not snapshot:
            if _is_scanner_local_ui_mode():
                BYBIT_LOGGER.info(
                    "OUTBOUND_TRAFFIC_UI_SERVICE no outbound traffic recorded yet (UI service only; not scanner health)."
                )
            else:
                BYBIT_LOGGER.info("OUTBOUND_TRAFFIC no outbound traffic recorded yet.")
            continue
        top_entries = sorted(
            snapshot.items(),
            key=lambda item: int(item[1].get("bytes_sent", 0)) + int(item[1].get("bytes_received", 0)),
            reverse=True,
        )[:8]
        summary = ", ".join(
            f"{dest}:req={vals['requests']} tx={vals['bytes_sent']} rx={vals['bytes_received']}"
            for dest, vals in top_entries
        )
        BYBIT_LOGGER.info("OUTBOUND_TRAFFIC %s", summary)


def _get_telegram_credentials() -> tuple[str, str]:
    token = os.getenv("TELEGRAM_BOT_TOKEN") or os.getenv("TELEGRAM_TOKEN") or ""
    chat_id = os.getenv("TELEGRAM_CHAT_ID") or ""
    return token, chat_id


async def _send_telegram_alert(message: str) -> None:
    token, chat_id = _get_telegram_credentials()
    if not token or not chat_id:
        BYBIT_LOGGER.info("Telegram alerts not configured; skipping alert.")
        return
    url = f"https://api.telegram.org/bot{token}/sendMessage"
    payload = {"chat_id": chat_id, "text": message}
    payload_raw = json.dumps(payload, separators=(",", ":"))
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            resp = await client.post(url, json=payload)
        _record_outbound_traffic(
            "telegram",
            bytes_sent=len(url) + len(payload_raw),
            bytes_received=len(resp.content),
            context="/sendMessage",
        )
    except Exception as exc:  # pragma: no cover - network failure
        BYBIT_LOGGER.error("Telegram alert failed: %s", exc)


def _format_trade_alert(
    payload: Dict[str, object],
    result: Optional[Dict[str, object]] = None,
    error: Optional[str] = None,
) -> str:
    symbol = str(payload.get("symbol", ""))
    action = str(payload.get("action", ""))
    qty = payload.get("quantity")
    account = str(payload.get("account", "live"))
    trade_mode = str(payload.get("trade_mode", "linear"))
    status = "FAILED" if error else "OK"
    lines = [
        f"Trade {status}",
        f"Account: {account}",
        f"Trade mode: {trade_mode}",
        f"Symbol: {symbol}",
        f"Side: {action}",
        f"Qty: {qty}",
    ]
    if result:
        order = result.get("order", {})
        if order:
            lines.append(f"Order ID: {order.get('orderId', '')}")
        tp_order = result.get("tp_order")
        tp_error = result.get("tp_error")
        if tp_order:
            lines.append(f"TP order: {tp_order.get('orderId', '')}")
        if tp_error:
            lines.append(f"TP error: {tp_error}")
    if error:
        lines.append(f"Error: {error}")
    return "\n".join(lines)


def _format_bybit_fill_alert(payload: Dict[str, object]) -> str:
    symbol = payload.get("symbol")
    side = payload.get("side")
