@app.post("/api/calculator/quote")
async def calculator_quote(request: Request, payload: Dict[str, object] = Body(default={})) -> JSONResponse:
    if isinstance(request, dict) and (not isinstance(payload, dict) or not payload):
        payload = request
        request = Request(
            {
                "type": "http",
                "http_version": "1.1",
                "method": "POST",
                "scheme": "http",
                "path": "/api/calculator/quote",
                "raw_path": b"/api/calculator/quote",
                "query_string": b"",
                "headers": [],
                "client": ("127.0.0.1", 0),
                "server": ("localhost", 80),
            }
        )
    quote_started = time.perf_counter()
    timings_ms: Dict[str, Any] = {}
    last_dependency_started: Dict[str, Optional[str]] = {"name": None}
    pending_dependencies: Set[str] = set()
    resolved_symbol_for_debug = ""
    submitted_debug: Dict[str, object] = {}
    try:
        asset = str(payload.get("asset") or "").strip().lower()
        account = str(payload.get("account") or "live").strip().lower()
        side = str(payload.get("side") or "buy").strip().lower()
        order_type = str(payload.get("order_type") or "market").strip().lower()
        risk_mode = str(payload.get("risk_mode") or "percent").strip().lower()
        broker = str(payload.get("broker") or "").strip().lower()
        symbol_in = str(payload.get("symbol") or "").strip()
        target_mode = str(payload.get("target_mode") or "").strip().lower()
        webhook_mode = str(payload.get("webhook") or payload.get("webhook_mode") or "no").strip().lower()
        is_test_trade = _normalize_test_trade_flag(payload.get("test", payload.get("test_trade", payload.get("is_test_trade"))))
        existing_pending_id = str(payload.get("pending_webhook_id") or "").strip()
        previous_pending_id = str(payload.get("previous_pending_webhook_id") or "").strip()
        if not symbol_in:
            raise HTTPException(status_code=400, detail="symbol is required.")
        if side not in {"buy", "sell"}:
            raise HTTPException(status_code=400, detail="side must be buy or sell.")
        if order_type not in {"market", "limit"}:
            raise HTTPException(status_code=400, detail="order_type must be market or limit.")
        if risk_mode not in {"fixed_aud", "percent"}:
            raise HTTPException(status_code=400, detail="risk_mode must be fixed_aud or percent.")
        if not target_mode:
            target_mode = "rr" if str(payload.get("risk_reward") or "").strip() else "ticks"
        if target_mode not in {"rr", "ticks"}:
            raise HTTPException(status_code=400, detail="target_mode must be rr or ticks.")
        if webhook_mode not in {"yes", "no", "true", "false", "1", "0"}:
            raise HTTPException(status_code=400, detail="webhook must be yes or no.")
        if asset == "fx":
            broker = broker or "oanda"
            if broker not in {"oanda", "pepperstone"}:
                raise HTTPException(status_code=400, detail="broker must be oanda or pepperstone for FX.")
        elif asset == "crypto":
            broker = "bybit"

        stop_ticks = _dec(payload.get("stop_loss_ticks"), "stop_loss_ticks")
        if stop_ticks <= 0:
            raise HTTPException(status_code=400, detail="stop_loss_ticks must be greater than zero.")

        risk_val = _dec(payload.get("risk_value"), "risk_value")
        if risk_val <= 0:
            raise HTTPException(status_code=400, detail="risk_value must be greater than zero.")
        limit_entry = payload.get("entry_price")
        if order_type == "limit" and (limit_entry is None or str(limit_entry).strip() == ""):
            raise HTTPException(status_code=400, detail="Limit orders require entry_price.")

        rr_requested: Optional[Decimal] = None
        tp_ticks: Optional[Decimal] = None
        if target_mode == "rr":
            rr_requested = _dec(payload.get("risk_reward"), "risk_reward")
            if rr_requested <= 0:
                raise HTTPException(status_code=400, detail="risk_reward must be greater than zero when target_mode=rr.")
        else:
            tp_ticks = _dec(payload.get("take_profit_ticks"), "take_profit_ticks")
            if tp_ticks <= 0:
                raise HTTPException(status_code=400, detail="take_profit_ticks must be greater than zero when target_mode=ticks.")

        webhook_enabled = webhook_mode in {"yes", "true", "1"}
        if asset == "fx" and broker == "pepperstone" and webhook_enabled:
            raise HTTPException(status_code=400, detail="Pepperstone .set export does not use webhook mode. Select Webhook=No and download the MT5 .set file.")
        quote_deadline = quote_started + CALCULATOR_QUOTE_TIMEOUT_S
        try:
            normalized_setup = _normalize_setup(payload.get("setup"))
            normalized_pattern = _normalize_pattern(payload.get("pattern"))
            normalized_ema = _normalize_ema(payload.get("ema"))
            normalized_vwap = _normalize_vwap(payload.get("vwap"))
            normalized_aths_atls = _normalize_aths_atls(payload.get("aths_atls"))
            normalized_round_number = _normalize_round_number(payload.get("round_number"))
        except ValueError as exc:
            raise HTTPException(status_code=422, detail=str(exc)) from exc

        submitted_debug = _calculator_safe_submitted_payload({"asset": asset, "broker": broker, "account": account, "submitted_symbol": symbol_in, "webhook": webhook_mode, "test": "yes" if is_test_trade else "no", "timeframe": _normalize_journal_timeframe(payload.get("timeframe") or ""), "risk_mode": risk_mode, "risk_value": str(payload.get("risk_value") or ""), "stop_loss_ticks": str(payload.get("stop_loss_ticks") or ""), "order_type": order_type, "side": side})
        webhook_capability = _calculator_webhook_capability(request)
        webhook_base_url = str(webhook_capability.get("public_webhook_base_url") or "").strip()
        webhook_endpoint_url = str(webhook_capability.get("webhook_endpoint_url") or "").strip()
        webhook_origin_host = webhook_capability.get("webhook_origin_host")
        webhook_origin_profile = webhook_capability.get("app_profile")
        webhook_origin_instance_id = webhook_capability.get("app_instance_id")
        if webhook_enabled and not bool(webhook_capability.get("available")):
                raise HTTPException(
                    status_code=400,
                    detail={
                        "code": "LOCAL_WEBHOOK_UNREACHABLE",
                        "message": webhook_capability.get("unavailable_message"),
                        "debug": {
                            "webhook": "yes",
                            "webhook_origin_host": webhook_origin_host,
                            "webhook_endpoint_url": webhook_endpoint_url,
                            "public_webhook_base_url": webhook_base_url,
                            "app_profile": APP_PROFILE,
                            "app_instance_id": webhook_origin_instance_id,
                            "resolution": webhook_capability.get("resolution"),
                        },
                    },
                )
        if webhook_enabled and str(webhook_capability.get("mode") or "") == "remote_render":
            remote_base = str(os.getenv("RENDER_CALCULATOR_BASE_URL") or "").strip().rstrip("/")
            remote_parsed = urlparse(remote_base) if remote_base else None
            remote_host = str((remote_parsed.hostname if remote_parsed else "") or "").strip().lower()
            req_host = str(getattr(request.url, "hostname", "") or "").strip().lower()
            if not (_is_local_host(req_host) and not _is_local_host(remote_host) and req_host != remote_host):
                raise HTTPException(status_code=400, detail={"code": "REMOTE_PROXY_GUARD", "message": "Remote calculator proxy guard blocked this request."})
            outbound_payload = dict(payload or {})
            outbound_payload["webhook"] = "yes"
            timeout = httpx.Timeout(4.8, connect=1.0)
            target_url = f"{remote_base}/api/calculator/quote"
            async with httpx.AsyncClient(timeout=timeout) as client:
                proxied = await client.post(target_url, json=outbound_payload)
            if proxied.status_code >= 400:
                detail_obj: object
                try:
                    detail_obj = proxied.json()
                except Exception:
                    detail_obj = {"message": proxied.text or "Remote calculator quote failed."}
                return JSONResponse(detail_obj, status_code=proxied.status_code)
            proxied_json = proxied.json()
            if isinstance(proxied_json, dict):
                pending_id = str(proxied_json.get("pending_webhook_id") or "").strip()
                if pending_id:
                    proxied_json.setdefault("pending_webhook_delete_url", f"/api/calculator/remote-pending-webhooks/{quote(pending_id, safe='')}")
                proxied_json.setdefault("quote_owner", "remote_render")
                proxied_json.setdefault("pending_webhook_owner", "remote_render")
                proxied_json.setdefault("proxied_by", "local_calculator")
            return JSONResponse(proxied_json, status_code=proxied.status_code)

        if asset == "crypto":
            if risk_mode == "fixed_aud":
                raise HTTPException(status_code=400, detail="fixed_aud risk mode is only supported for FX.")
            _mode, api_key, api_secret, base_url, _src = resolve_bybit_credentials_for(account)
            if not api_key or not api_secret:
                raise HTTPException(status_code=500, detail="Bybit credentials are missing for selected account.")
            resolved_symbol = ""
            resolved_inst_row: Optional[Dict[str, object]] = None
            symbol_resolution_started = time.perf_counter()
            raw_symbol = str(symbol_in or "").strip().upper()
            resolved_symbol, resolved_inst_row, resolution_debug = await _resolve_bybit_calculator_symbol_fast(base_url, raw_symbol, timings_ms, quote_deadline)
            if not resolved_symbol:
                symbol_list_started = time.perf_counter()
                choices = await _calculator_timed_dependency("bybit_symbol_list", _bybit_get_symbols_by_category_cached(base_url, "linear"), timings_ms, 1.2, "/v5/market/instruments-info", pending_dependencies=pending_dependencies, last_dependency_started=last_dependency_started, deadline=quote_deadline)
                timings_ms["bybit_symbol_list_ms"] = int((time.perf_counter() - symbol_list_started) * 1000)
                if not choices:
                    raise HTTPException(status_code=404, detail=_calculator_quote_error_detail("BYBIT_SYMBOL_UNRESOLVED", f"Could not resolve Bybit symbol: {symbol_in}", timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies))
                resolved = resolve_bybit_symbol_from_choices(symbol_in, choices)
                if not resolved or not resolved.get("resolved_symbol"):
                    name_aliases = await _calculator_timed_dependency("bybit_symbol_aliases", _bybit_name_aliases_for_choices(base_url, set(choices)), timings_ms, 1.0, "bybit_aliases", pending_dependencies=pending_dependencies, last_dependency_started=last_dependency_started, deadline=quote_deadline)
                    if name_aliases:
                        resolved = resolve_bybit_symbol_from_choices(symbol_in, choices, extra_aliases=name_aliases)
                resolved_symbol = str((resolved or {}).get("resolved_symbol") or "").upper()
                resolution_debug["resolution_status"] = "fallback_list" if resolved_symbol else "unresolved"
                if resolved_symbol:
                    resolved_inst_row = await _bybit_get_instrument_info_cached(base_url, "linear", resolved_symbol, timeout_s=_calculator_remaining_timeout_s(quote_deadline, 1.0), connect_s=0.5, read_s=1.0)
            timings_ms["symbol_resolution_ms"] = int((time.perf_counter() - symbol_resolution_started) * 1000)
            timings_ms["bybit_instrument_cache_hit"] = bool(resolved_inst_row)
            timings_ms["symbol_resolution_debug"] = resolution_debug
            resolved_symbol_for_debug = resolved_symbol or resolved_symbol_for_debug
            if not resolved_symbol:
                raise HTTPException(status_code=404, detail=_calculator_quote_error_detail("BYBIT_SYMBOL_UNRESOLVED", f"Could not resolve Bybit symbol: {symbol_in}", timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies))
            bybit_fetch_started = time.perf_counter()
            inst_task = None
            if not resolved_inst_row:
                inst_task = asyncio.create_task(_calculator_timed_dependency("bybit_instruments_info", _bybit_get_instrument_info_cached(base_url, "linear", resolved_symbol), timings_ms, 3.0, "/v5/market/instruments-info", pending_dependencies=pending_dependencies, last_dependency_started=last_dependency_started))
            ticker_task = asyncio.create_task(_calculator_timed_dependency("bybit_ticker", _fetch_bybit_ticker_cached(base_url, "linear", resolved_symbol, timeout_s=1.5, allow_stale_s=45.0, public_fallback_base_url=((os.getenv("BYBIT_PUBLIC_MARKET_BASE_URL") or "https://api.bybit.com") if account == "demo" else None)), timings_ms, 2.0, "/v5/market/tickers", pending_dependencies=pending_dependencies, last_dependency_started=last_dependency_started, deadline=quote_deadline))
            balance_task = asyncio.create_task(_calculator_timed_dependency("bybit_wallet_balance", _fetch_bybit_balance_usdt_cached(account, timeout_s=2.5, connect_s=1.0, read_s=2.5), timings_ms, 3.0, "/v5/account/wallet-balance", pending_dependencies=pending_dependencies, last_dependency_started=last_dependency_started, deadline=quote_deadline))
            async def _fetch_aud_usd_cached() -> Dict[str, float]:
                now = time.time()
                cached_val = _OANDA_AUD_USD_CACHE.get("value")
                if cached_val and (now - float(_OANDA_AUD_USD_CACHE.get("ts") or 0.0)) <= _OANDA_AUD_USD_CACHE_TTL_SECONDS:
                    return {"AUD_USD": float(cached_val)}
                prices = await _fetch_oanda_mid_prices_batch(cfg=_get_oanda_config("live"), instruments=["AUD_USD"], timeout_s=3.5, connect_s=1.5, read_s=3.0)
                px = float(prices.get("AUD_USD") or 0.0)
                if px > 0:
                    _OANDA_AUD_USD_CACHE.update({"ts": now, "value": px})
                return prices
            aud_task = None
            fee_task = None
            if account != "demo":
                fee_task = asyncio.create_task(_calculator_timed_dependency("bybit_fee_rate", _bybit_signed_get(base_url=base_url, api_key=api_key, api_secret=api_secret, path="/v5/account/fee-rate", params={"category": "linear", "symbol": resolved_symbol}, timeout_s=4.0, connect_s=2.0, read_s=4.0), timings_ms, 4.0, "/v5/account/fee-rate", pending_dependencies=pending_dependencies, last_dependency_started=last_dependency_started))
            required_tasks=[ticker_task,balance_task]+([inst_task] if inst_task else [])
            try:
                await asyncio.gather(*required_tasks)
            except Exception:
                await _cancel_pending_tasks(required_tasks + ([aud_task] if aud_task else []) + ([fee_task] if fee_task else []))
                raise
            optional_tasks=[t for t in [aud_task, fee_task] if t is not None]
            if optional_tasks:
                done, pending = await asyncio.wait(optional_tasks, timeout=0.2)
                for ptask in pending:
                    ptask.cancel()
            timings_ms["bybit_upstream_parallel_ms"] = int((time.perf_counter()-bybit_fetch_started)*1000)
            inst_started = time.perf_counter()
            inst = resolved_inst_row or (inst_task.result() if inst_task else None)
            timings_ms["bybit_instruments_info_ms"] = timings_ms.get("bybit_instruments_info_ms", 0) + int((time.perf_counter() - inst_started) * 1000)
            if not inst:
                raise HTTPException(status_code=502, detail="Bybit instrument meta fetch failed.")
            tick_size = Decimal(str(inst.get("priceFilter", {}).get("tickSize") or "0"))
            qty_step = Decimal(str(inst.get("lotSizeFilter", {}).get("qtyStep") or "0"))
            min_qty = Decimal(str(inst.get("lotSizeFilter", {}).get("minOrderQty") or "0"))
            max_qty = Decimal(str(inst.get("lotSizeFilter", {}).get("maxOrderQty") or "0"))
            max_mkt_qty = Decimal(str(inst.get("lotSizeFilter", {}).get("maxMktOrderQty") or "0"))
            min_notional = Decimal(str(inst.get("lotSizeFilter", {}).get("minNotionalValue") or "0"))
            max_leverage = Decimal(str((inst.get("leverageFilter") or {}).get("maxLeverage") or "0"))
            if tick_size <= 0 or qty_step <= 0:
                raise HTTPException(status_code=502, detail="Bybit instrument constraints are invalid.")
            ticker_started = time.perf_counter()
            ticker_wrapped = ticker_task.result()
            tickers = ticker_wrapped.get("payload") if isinstance(ticker_wrapped, dict) and "payload" in ticker_wrapped else ticker_wrapped
            if isinstance(ticker_wrapped, dict):
                timings_ms["ticker_cache_status"] = ticker_wrapped.get("cache_status")
                timings_ms["ticker_cache_age_ms"] = ticker_wrapped.get("cache_age_ms")
                timings_ms["ticker_source"] = ticker_wrapped.get("ticker_source")
            timings_ms["bybit_ticker_ms"] = int((time.perf_counter() - ticker_started) * 1000)
            row = _extract_valid_bybit_ticker_row(tickers, resolved_symbol)
            if not row:
                ticker_status_code = "BYBIT_TICKER_TIMEOUT"
                ticker_message = f"Bybit ticker timed out for {resolved_symbol}."
                ticker_cache_error = str((ticker_wrapped or {}).get("ticker_cache_error") or "") if isinstance(ticker_wrapped, dict) else ""
                if "payload invalid" in ticker_cache_error.lower():
                    ticker_status_code = "BYBIT_TICKER_INVALID"
                    ticker_message = f"Bybit ticker payload invalid for {resolved_symbol}."
                raise HTTPException(status_code=504, detail=_calculator_quote_error_detail(ticker_status_code, ticker_message, dependency="bybit_ticker", timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies))
            bid = Decimal(str(row.get("bid1Price") or "0"))
            ask = Decimal(str(row.get("ask1Price") or "0"))
            last = Decimal(str(row.get("lastPrice") or "0"))
            entry = _dec(limit_entry, "entry_price") if order_type == "limit" else (ask if side == "buy" else bid)
            if entry <= 0:
                raise HTTPException(status_code=400, detail="entry_price must be greater than zero.")
            stop_distance = stop_ticks * tick_size
            sl = (entry - stop_distance) if side == "buy" else (entry + stop_distance)
            warnings: List[str] = []
            if isinstance(ticker_wrapped, dict) and ticker_wrapped.get("cache_status") == "stale_fallback":
                warnings.append("Using recent cached Bybit ticker because live ticker fetch timed out.")
            fallback_taker = Decimal(str(os.getenv("CALCULATOR_BYBIT_TAKER_FEE_FALLBACK", "0.0006") or "0.0006"))
            fallback_maker = Decimal(str(os.getenv("CALCULATOR_BYBIT_MAKER_FEE_FALLBACK", "0.0006") or "0.0006"))
            maker = fallback_maker
            taker = fallback_taker
            if account == "demo":
                maker = fallback_maker
                taker = fallback_taker
            else:
                try:
                    fee_payload = fee_task.result() if fee_task else {}
                    fee_row = ((fee_payload.get("result") or {}).get("list") or [{}])[0]
                    maker = Decimal(str(fee_row.get("makerFeeRate") or fallback_maker))
                    taker = Decimal(str(fee_row.get("takerFeeRate") or fallback_taker))
                    timings_ms["bybit_fee_rate_status"] = "live"
                except Exception as exc:
                    exc_text = str(exc)
                    ret_code_match = re.search(r"retCode=([0-9-]+)", exc_text)
                    ret_code = ret_code_match.group(1) if ret_code_match else "unknown"
                    timings_ms["bybit_fee_rate_status"] = "fallback"
                    warnings.append(
                        f"Bybit fee rate unavailable (retCode {ret_code}). Using conservative fallback fees for this quote."
                    )
            open_fee = taker if order_type == "market" else max(maker, taker)
            close_fee = taker
            aud_started = time.perf_counter()
            aud_usd = Decimal("0")
            timings_ms["aud_conversion_status"] = "skipped_not_required_for_crypto_percent_risk"
            timings_ms["oanda_aud_usd_ms"] = 0
            balance_started = time.perf_counter()
            try:
                bal_wrapped = balance_task.result()
                if isinstance(bal_wrapped, tuple):
                    balance_snapshot, bal_meta = bal_wrapped
                    timings_ms.update(bal_meta or {})
                else:
                    balance_snapshot = bal_wrapped
            except HTTPException as exc:
                if isinstance(exc.detail, dict):
                    raise HTTPException(status_code=502, detail=exc.detail) from exc
                raise HTTPException(
                    status_code=502,
                    detail=f"Bybit risk sizing dependency failed path=/v5/account/wallet-balance: {exc.detail}",
                ) from exc
            timings_ms["bybit_wallet_balance_ms"] = int((time.perf_counter() - balance_started) * 1000)
            available_usdt = Decimal(str(balance_snapshot.get("available_usdt") or "0"))
            total_equity = Decimal(str(balance_snapshot.get("total_equity") or "0"))
            risk_usdt = available_usdt * (risk_val / Decimal("100"))
            risk_aud = (risk_usdt / aud_usd) if aud_usd > 0 else Decimal("0")
            spread_quote = max(Decimal("0"), ask - bid) if order_type == "market" else Decimal("0")
            loss_per_unit = abs(entry - sl) + spread_quote + (entry * open_fee) + (sl * close_fee)
            if loss_per_unit <= 0:
                raise HTTPException(status_code=400, detail="Invalid stop distance produced zero loss per unit.")

            requested_rr_net = None
            effective_rr_net = None
            fee_buffer_r = None
            if target_mode == "rr" and rr_requested is not None:
                desired_net_reward = loss_per_unit * rr_requested
                target_distance = stop_distance * rr_requested
                for _ in range(4):
                    tp_probe = (entry + target_distance) if side == "buy" else (entry - target_distance)
                    close_fee_cost = abs(tp_probe) * close_fee
                    fee_buffer = spread_quote + (entry * open_fee) + close_fee_cost
                    target_distance = desired_net_reward + fee_buffer
                tp = (entry + target_distance) if side == "buy" else (entry - target_distance)
                fee_buffer = spread_quote + (entry * open_fee) + (abs(tp) * close_fee)
                net_reward_per_unit = target_distance - fee_buffer
                requested_rr_net = rr_requested
                effective_rr_net = net_reward_per_unit / loss_per_unit if loss_per_unit > 0 else Decimal("0")
                fee_buffer_r = fee_buffer / loss_per_unit if loss_per_unit > 0 else Decimal("0")
            else:
                target_distance = (tp_ticks or Decimal("0")) * tick_size
                tp = (entry + target_distance) if side == "buy" else (entry - target_distance)

            qty_raw = risk_usdt / loss_per_unit
            raw_notional = qty_raw * entry
            if min_notional > 0 and raw_notional < min_notional:
                raise HTTPException(status_code=400, detail="Calculated notional is below Bybit minimum notional")
            qty = _floor_to_step(qty_raw, qty_step)
            if qty < min_qty:
                raise HTTPException(status_code=400, detail="Calculated quantity is below minimum order quantity")
            notional = qty * entry
            if order_type == "market" and max_mkt_qty > 0 and qty > max_mkt_qty:
                raise HTTPException(status_code=400, detail="Calculated quantity exceeds Bybit max market order quantity")
            if order_type == "limit" and max_qty > 0 and qty > max_qty:
                raise HTTPException(status_code=400, detail="Calculated quantity exceeds Bybit max order quantity")
            if max_leverage > 0:
                est_margin = notional / max_leverage
                available_for_margin = max(available_usdt, total_equity)
                margin_tolerance = Decimal("1.05")
                if available_for_margin > 0 and est_margin > (available_for_margin * margin_tolerance):
                    raise HTTPException(status_code=400, detail="Insufficient Bybit available margin for estimated initial margin")

            total_loss_usdt = qty * loss_per_unit
            reward_usdt = qty * max(Decimal("0"), target_distance - spread_quote - (entry * open_fee) - (abs(tp) * close_fee))
            snapped_entry = _snap_to_increment(entry, tick_size) or entry
            snapped_sl = _snap_to_increment(sl, tick_size) or sl
            requested_target_before_adjustment = _snap_to_increment(tp, tick_size) or tp
            snapped_tp = requested_target_before_adjustment
            take_profit_adjustment = None
            snapped_tp, take_profit_adjustment = _adjust_bybit_take_profit_for_last_price(
                symbol=resolved_symbol,
                side=side,
                entry_price=snapped_entry,
                take_profit=snapped_tp,
                last_price=last,
                tick_size=tick_size,
            )
            if take_profit_adjustment:
                warnings.append('Take profit was auto-adjusted to satisfy Bybit LastPrice trigger rules.')
            effective_target_distance = abs(snapped_tp - snapped_entry)
            snapped_target_distance = _snap_to_increment(effective_target_distance, tick_size) or effective_target_distance
            rr_value = (abs(snapped_tp - snapped_entry) / abs(snapped_entry - snapped_sl)) if abs(snapped_entry - snapped_sl) > 0 else Decimal('0')
            reward_usdt = qty * max(Decimal('0'), effective_target_distance - spread_quote - (snapped_entry * open_fee) - (abs(snapped_tp) * close_fee))
            effective_rr_net_value = None
            if requested_rr_net is not None:
                net_reward_per_unit = effective_target_distance - (spread_quote + (snapped_entry * open_fee) + (abs(snapped_tp) * close_fee))
                effective_rr_net_value = net_reward_per_unit / loss_per_unit if loss_per_unit > 0 else Decimal('0')
            try:
                _validate_bybit_linear_levels_before_submit(
                    symbol=resolved_symbol,
                    side=side,
                    order_type=order_type,
                    entry_price=snapped_entry,
                    stop_loss=snapped_sl,
                    take_profit=snapped_tp,
                    last_price=last,
                    tick_size=tick_size,
                    source_context="calculator_quote",
                )
            except BybitPreSubmitValidationError as exc:
                raise HTTPException(status_code=400, detail={"code": exc.code, "message": exc.message, "debug": exc.debug}) from exc
            response_payload: Dict[str, object] = {
                "broker": "bybit",
                "venue": "Bybit",
                "resolved_venue": "Bybit",
                "symbol": resolved_symbol,
                "tick_size": _fmt_dec(tick_size),
                "last_price": _fmt_dec(last),
                "submitted_order_type": order_type,
                "submitted_side": side,
                "entry_price": _fmt_dec(snapped_entry),
                "stop_price": _fmt_dec(snapped_sl),
                "target_price": _fmt_dec(snapped_tp),
                "target_distance": _fmt_dec(snapped_target_distance),
                "effective_target_distance": _fmt_dec(snapped_target_distance),
                "quantity": _fmt_dec(qty),
                "notional": _fmt_dec(notional),
                "estimated_fees_or_spread_aud": _fmt_dec((((qty * entry * open_fee) + (qty * sl * close_fee)) / aud_usd) if aud_usd > 0 else Decimal("0")),
                "estimated_total_loss_aud": _fmt_dec((total_loss_usdt / aud_usd) if aud_usd > 0 else Decimal("0")),
                "estimated_reward_aud": _fmt_dec(max(Decimal("0"), (reward_usdt / aud_usd) if aud_usd > 0 else Decimal("0"))),
                "display_currency": "USDT",
                "estimated_fees_or_spread": _fmt_dec((qty * entry * open_fee) + (qty * sl * close_fee)),
                "estimated_total_loss": _fmt_dec(total_loss_usdt),
                "estimated_reward": _fmt_dec(max(Decimal("0"), reward_usdt)),
                "rr": _fmt_dec_by_precision(rr_value, Decimal("0.01")),
                "effective_rr": _fmt_dec_by_precision(rr_value, Decimal("0.01")),
                "quote_created_at_ms": int(time.time() * 1000),
                "quote_last_price": _fmt_dec(last),
                "quote_tick_size": _fmt_dec(tick_size),
                "quote_valid_for_submit": True,
                "submit_validity_boundary": ("take_profit_price < latest LastPrice" if side == "sell" else "take_profit_price > latest LastPrice"),
                "target_mode": target_mode,
                "requested_rr_net": _fmt_dec_by_precision(requested_rr_net, Decimal("0.01")) if requested_rr_net is not None else None,
                "effective_rr_net": _fmt_dec_by_precision(effective_rr_net_value if effective_rr_net_value is not None else effective_rr_net, Decimal("0.01")) if (effective_rr_net_value is not None or effective_rr_net is not None) else None,
                "take_profit_adjusted": bool(take_profit_adjustment),
                "take_profit_adjustment": take_profit_adjustment,
                "requested_target_price_before_adjustment": _fmt_dec(requested_target_before_adjustment),
                "fee_buffer_r": _fmt_dec_by_precision(fee_buffer_r, Decimal("0.01")) if fee_buffer_r is not None else None,
            }
            if warnings:
                response_payload["warnings"] = warnings
            calculation_context_id = (
                str(payload.get("calculation_context_id") or "").strip()
                or f"calcctx_bybit_{account}_{uuid4().hex}"
            )
            response_payload["calculation_context_id"] = calculation_context_id
            quote_context_payload = {
                "calculation_context_id": calculation_context_id,
                "broker": "bybit",
                "venue": "Bybit",
                "account": account,
                "asset": "crypto",
                "category": "linear",
                "instrument": resolved_symbol,
                "symbol": resolved_symbol,
                "side": side,
                "order_type": order_type,
                "target_mode": target_mode,
                "risk_mode": risk_mode,
                "risk_value": _fmt_dec(risk_val),
                "stop_loss_ticks": _fmt_dec(stop_ticks),
                "take_profit_ticks": _fmt_dec(tp_ticks) if tp_ticks is not None else None,
                "risk_reward": _fmt_dec(rr_requested) if rr_requested is not None else None,
                "timeframe": _normalize_journal_timeframe(payload.get("timeframe") or ""),
                "is_test_trade": is_test_trade,
                "setup": normalized_setup,
                "pattern": normalized_pattern,
                "ema": normalized_ema,
                "vwap": normalized_vwap,
                "aths_atls": normalized_aths_atls,
                "round_number": normalized_round_number,
                "webhook_mode": "Yes" if webhook_enabled else "No",
                "webhook_status": "Waiting" if webhook_enabled else "Not used",
                "entry_price": response_payload.get("entry_price"),
                "planned_entry_price": response_payload.get("entry_price"),
                "stop_loss": response_payload.get("stop_price"),
                "planned_stop_price": response_payload.get("stop_price"),
                "take_profit": response_payload.get("target_price"),
                "planned_target_price": response_payload.get("target_price"),
                "quantity": response_payload.get("quantity"),
                "notional": response_payload.get("notional"),
                "last_price": response_payload.get("quote_last_price"),
                "tick_size": response_payload.get("quote_tick_size"),
                "quote_created_at_ms": response_payload.get("quote_created_at_ms"),
                "status": "QUOTED",
                "quote_payload": payload,
                "quote_result": response_payload,
            }
            try:
                if account == "demo":
                    _upsert_bybit_demo_calc_context(
                        quote_context_payload,
                        require_durable=True,
                        invalidate_cache=False,
                    )
                else:
                    _upsert_calculator_trade_context(
                        quote_context_payload,
                        require_durable=True,
                        invalidate_cache=False,
                    )
                response_payload["calculation_context_saved"] = True
            except Exception as exc:
                if account == "demo":
                    raise HTTPException(
                        status_code=502,
                        detail=_build_bybit_demo_calc_context_save_error(
                            error=exc,
                            resolved_symbol=resolved_symbol,
                            account="demo",
                            timings_ms=timings_ms,
                            quote_started=quote_started,
                            submitted_payload=submitted_debug,
                            pending_dependencies=pending_dependencies,
                        ),
                    ) from exc
                raise HTTPException(
                    status_code=502,
                    detail={
                        "code": "CALC_CONTEXT_SAVE_FAILED",
                        "message": (
                            "The quote was calculated, but its trade context could not be "
                            "saved durably. Retry the quote before submitting."
                        ),
                    },
                ) from exc

            quote_version_invalidated = False
            if webhook_enabled:
                pending_id = existing_pending_id or f"calc_bybit_{uuid4().hex[:16]}"
                webhook_payload = {
                    "asset": "crypto",
                    "account": account,
                    "symbol": resolved_symbol,
                    "action": side,
                    "order_type": order_type,
                    "quantity": _fmt_dec(qty),
                    "entry_price": _fmt_dec(snapped_entry),
                    "planned_entry_price": _fmt_dec(snapped_entry),
                    "stop_loss_price": _fmt_dec(snapped_sl),
                    "planned_stop_price": _fmt_dec(snapped_sl),
                    "take_profit_price": _fmt_dec(snapped_tp),
                    "planned_target_price": _fmt_dec(snapped_tp),
                    "level_anchor_mode": "actual_fill",
                    "timeframe": _normalize_journal_timeframe(payload.get("timeframe") or ""),
                    "is_test_trade": is_test_trade,
                    "risk_mode": risk_mode,
                    "risk_value": _fmt_dec(risk_val),
                    "stop_loss_ticks": _fmt_dec(stop_ticks),
                    "target_mode": target_mode,
                    "take_profit_ticks": _fmt_dec(tp_ticks) if tp_ticks is not None else None,
                    "risk_reward": _fmt_dec(rr_requested) if rr_requested is not None else None,
                    "quote_created_at_ms": response_payload.get("quote_created_at_ms"),
                    "setup": normalized_setup,
                    "pattern": normalized_pattern,
                    "ema": normalized_ema,
                    "vwap": normalized_vwap,
                    "aths_atls": normalized_aths_atls,
                    "round_number": normalized_round_number,
                    "pending_webhook_id": pending_id,
                    "calculation_context_id": calculation_context_id,
                    "webhook_endpoint_url": webhook_endpoint_url,
                    "webhook_origin_host": webhook_origin_host,
                    "webhook_origin_profile": webhook_origin_profile,
                    "webhook_origin_instance_id": webhook_origin_instance_id,
                }
                pending_item = _upsert_pending_webhook(
                    {
                        "id": pending_id,
                        "asset": "crypto",
                        "category": "linear",
                        "resolved_broker": "bybit",
                        "account": account,
                        "instrument": resolved_symbol,
                        "side": side,
                        "order_type": order_type,
                        "entry_price": _fmt_dec(snapped_entry),
                        "stop_loss": _fmt_dec(snapped_sl),
                        "take_profit": _fmt_dec(snapped_tp),
                        "size": _fmt_dec(qty),
                        "timeframe": webhook_payload.get("timeframe") or "",
                        "is_test_trade": is_test_trade,
                        "risk_mode": risk_mode,
                        "risk_value": _fmt_dec(risk_val),
                        "stop_loss_ticks": _fmt_dec(stop_ticks),
                        "target_mode": target_mode,
                        "take_profit_ticks": _fmt_dec(tp_ticks) if tp_ticks is not None else None,
                        "risk_reward": _fmt_dec(rr_requested) if rr_requested is not None else None,
                        "planned_entry_price": _fmt_dec(snapped_entry),
                        "planned_stop_price": _fmt_dec(snapped_sl),
                        "planned_target_price": _fmt_dec(snapped_tp),
                        "quote_created_at_ms": response_payload.get("quote_created_at_ms"),
                        "setup": normalized_setup,
                        "pattern": normalized_pattern,
                        "ema": normalized_ema,
                        "vwap": normalized_vwap,
                        "aths_atls": normalized_aths_atls,
                        "round_number": normalized_round_number,
                        "status": "WAITING",
                        "enabled": True,
                        "calculation_context_id": calculation_context_id,
                    }
                )
                quote_version_invalidated = True
                response_payload["pending_webhook_id"] = pending_item.get("id")
                response_payload["webhook_endpoint"] = "/api/calculator/webhook"
                response_payload["webhook_endpoint_url"] = webhook_endpoint_url
                response_payload["webhook_payload_json"] = json.dumps(webhook_payload, separators=(",", ":"))
                if previous_pending_id and previous_pending_id != pending_id:
                    _delete_pending_webhook(previous_pending_id, invalidate_cache=False)
            elif previous_pending_id:
                quote_version_invalidated = _delete_pending_webhook(previous_pending_id)
            if not quote_version_invalidated:
                _invalidate_open_orders_cache()

            response_payload["quote_latency_ms"] = int((time.perf_counter() - quote_started) * 1000)
            timings_ms["quote_total_ms"] = int(response_payload["quote_latency_ms"])
            response_payload["upstream_timings_ms"] = timings_ms
            CALCULATOR_LOGGER.info("CALCULATOR_QUOTE_TIMING asset=%s account=%s symbol=%s total_ms=%s timings=%s", asset, account, resolved_symbol, response_payload["quote_latency_ms"], timings_ms)
            return JSONResponse(response_payload)

        if asset == "fx":
            try:
                cfg = _get_oanda_config(account)
            except ValueError as exc:
                raise HTTPException(status_code=500, detail=str(exc)) from exc
            symbol = normalize_oanda_symbol_query(symbol_in)
            oanda_parallel_started = time.perf_counter()
            meta_task = asyncio.create_task(_fetch_oanda_instrument_meta(base_url=cfg["base_url"], account_id=cfg["account_id"], api_key=cfg["token"], symbol=symbol, mode=account))
            pricing_task = asyncio.create_task(_fetch_oanda_json(base_url=cfg["base_url"], account_id=cfg["account_id"], api_key=cfg["token"], endpoint=f"/accounts/{{account_id}}/pricing?instruments={symbol}&includeHomeConversions=true", mode=account))
            summary_task = asyncio.create_task(_fetch_oanda_account_summary(account))
            tasks=[meta_task,pricing_task,summary_task]
            try:
                await asyncio.gather(*tasks)
            except Exception:
                await _cancel_pending_tasks(tasks)
                raise
            timings_ms["oanda_upstream_parallel_ms"] = int((time.perf_counter()-oanda_parallel_started)*1000)
            try:
                meta = meta_task.result()
            except ValueError as exc:
                raise HTTPException(status_code=404, detail=str(exc)) from exc
            display_precision = int(meta["displayPrecision"])
            units_precision = int(meta.get("tradeUnitsPrecision", 0))
            min_trade_size = Decimal(str(meta.get("minimumTradeSize") or "0"))
            max_order_units = Decimal(str(meta.get("maximumOrderUnits") or "0"))
            max_position_size = Decimal(str(meta.get("maximumPositionSize") or "0"))
            margin_rate = Decimal(str(meta.get("marginRate") or "0"))
            tick_size = Decimal("1").scaleb(-display_precision)
            try:
                prices = pricing_task.result()
            except Exception as exc:
                raise HTTPException(status_code=502, detail=f"OANDA pricing/meta fetch failure: {exc}") from exc
            rows = prices.get("prices") or []
            if not rows:
                raise HTTPException(status_code=502, detail="OANDA pricing/meta fetch failure.")
            row = rows[0]
            bid = Decimal(str(((row.get("bids") or [{}])[0]).get("price") or "0"))
            ask = Decimal(str(((row.get("asks") or [{}])[0]).get("price") or "0"))
            if bid <= 0 or ask <= 0:
                raise HTTPException(status_code=502, detail="OANDA bid/ask unavailable.")
            entry = _dec(limit_entry, "entry_price") if order_type == "limit" else (ask if side == "buy" else bid)
            if entry <= 0:
                raise HTTPException(status_code=400, detail="Bad limit price.")
            sl = (entry - stop_ticks * tick_size) if side == "buy" else (entry + stop_ticks * tick_size)

            summary = summary_task.result()
            account_home_ccy = str(summary.get("currency") or "").strip().upper()
            quote_ccy = symbol.split("_", 1)[1]
            try:
                gain_factor, loss_factor, _position_value_factor = _get_oanda_quote_home_factors(
                    prices_payload=prices,
                    row=row,
                    quote_ccy=quote_ccy,
                    account_home_ccy=account_home_ccy,
                )
            except ValueError as exc:
                top_level_conversions = prices.get("homeConversions") if isinstance(prices, dict) else []
                available_top_level = sorted(
                    {
                        str(item.get("currency") or "").strip().upper()
                        for item in (top_level_conversions or [])
                        if isinstance(item, dict) and str(item.get("currency") or "").strip()
                    }
                )
                raise HTTPException(
                    status_code=502,
                    detail=(
                        f"OANDA pricing response missing usable home conversion for {quote_ccy}. "
                        f"includeHomeConversions=true, top_level_currencies={available_top_level}, "
                        f"row_keys={sorted(row.keys())}"
                    ),
                ) from exc

            risk_input_aud = risk_val
            if risk_mode == "percent":
                nav = Decimal(str(summary.get("nav") or "0"))
                if nav <= 0:
                    raise HTTPException(status_code=502, detail="OANDA NAV unavailable for percent risk.")
                risk_amount_home = nav * (risk_val / Decimal("100"))
            else:
                try:
                    risk_amount_home = await _convert_aud_to_home_currency(risk_input_aud, account_home_ccy, cfg)
                except ValueError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc
            spread_quote = max(Decimal("0"), ask - bid)
            loss_per_unit_home = (abs(entry - sl) + spread_quote) * loss_factor
            if loss_per_unit_home <= 0:
                raise HTTPException(status_code=400, detail="Invalid stop distance produced zero loss per unit.")

            requested_rr_net = None
            effective_rr_net = None
            fee_buffer_r = None
            if target_mode == "rr" and rr_requested is not None:
                desired_net_reward_home = loss_per_unit_home * rr_requested
                target_distance = (desired_net_reward_home / loss_factor) + spread_quote
                tp = (entry + target_distance) if side == "buy" else (entry - target_distance)
                reward_per_unit_home = max(Decimal("0"), (target_distance - spread_quote) * gain_factor)
                requested_rr_net = rr_requested
                effective_rr_net = reward_per_unit_home / loss_per_unit_home if loss_per_unit_home > 0 else Decimal("0")
                fee_buffer_r = ((spread_quote * loss_factor) / loss_per_unit_home) if loss_per_unit_home > 0 else Decimal("0")
            else:
                target_distance = (tp_ticks or Decimal("0")) * tick_size
                tp = (entry + target_distance) if side == "buy" else (entry - target_distance)

            units_raw = risk_amount_home / loss_per_unit_home
            units = _floor_to_precision(units_raw, units_precision)
            if units < min_trade_size:
                raise HTTPException(status_code=400, detail="Calculated units are below minimum trade size.")
            if max_order_units > 0 and units > max_order_units:
                raise HTTPException(status_code=400, detail="Calculated units exceed OANDA maximumOrderUnits.")
            if max_position_size > 0 and units > max_position_size:
                raise HTTPException(status_code=400, detail="Calculated units exceed OANDA maximumPositionSize.")
            margin_available = Decimal(str(summary.get("marginAvailable") or "0"))
            effective_margin_rate = margin_rate if margin_rate > 0 else Decimal(str(summary.get("marginRate") or "0"))
            estimated_position_value_home = units * entry * _position_value_factor
            estimated_initial_margin_home = estimated_position_value_home * max(Decimal("0"), effective_margin_rate)
            submitted_debug_payload = {
                "submitted_risk_mode": risk_mode,
                "submitted_risk_value": _fmt_dec(risk_val),
                "submitted_stop_loss_ticks": _fmt_dec(stop_ticks),
                "tick_size": _fmt_dec(tick_size),
                "entry_price_used": _fmt_dec_by_precision(entry, tick_size),
                "spread_quote": _fmt_dec(spread_quote),
                "loss_per_unit_home": _fmt_dec(loss_per_unit_home),
                "units_raw": _fmt_dec(units_raw),
                "units_final": _fmt_dec(units),
                "estimated_position_value_home": _fmt_dec(estimated_position_value_home),
                "estimated_initial_margin_home": _fmt_dec(estimated_initial_margin_home),
            }
            if effective_margin_rate > 0 and margin_available > 0:
                if estimated_initial_margin_home > margin_available:
                    raise HTTPException(
                        status_code=400,
                        detail={
                            "code": "oanda_margin_insufficient",
                            "message": "Insufficient OANDA marginAvailable for estimated initial margin.",
                            "debug": {
                                **submitted_debug_payload,
                                "required_margin_home": _fmt_dec(estimated_initial_margin_home),
                                "margin_available_home": _fmt_dec(margin_available),
                                "margin_rate": _fmt_dec(effective_margin_rate),
                                "position_value_factor": _fmt_dec(_position_value_factor),
                                "account_currency": account_home_ccy,
                                "risk_input_aud": _fmt_dec(risk_input_aud),
                                "risk_amount_home": _fmt_dec(risk_amount_home),
                            },
                        },
                    )
            spread_home = spread_quote * loss_factor * units
            reward_home = max(Decimal("0"), (abs(tp - entry) - spread_quote) * gain_factor * units)
            response_payload = {
                    "broker": broker,
                    "venue": "Pepperstone" if broker == "pepperstone" else "OANDA",
                    "resolved_venue": "Pepperstone" if broker == "pepperstone" else "OANDA",
                    "symbol": symbol,
                    "tick_size": _fmt_dec(tick_size),
                    "entry_price": _fmt_dec_by_precision(entry, tick_size),
                    "stop_price": _fmt_dec_by_precision(sl, tick_size),
                    "target_price": _fmt_dec_by_precision(tp, tick_size),
                    "target_distance": _fmt_dec_by_precision(target_distance, tick_size),
                    "quantity": _fmt_dec(units),
                    "notional": _fmt_dec(units * entry),
                    "estimated_fees_or_spread_aud": _fmt_dec(max(Decimal("0"), spread_home)),
                    "estimated_total_loss_aud": _fmt_dec(loss_per_unit_home * units),
                    "estimated_reward_aud": _fmt_dec(reward_home),
                    "display_currency": account_home_ccy,
                    "estimated_fees_or_spread": _fmt_dec(max(Decimal("0"), spread_home)),
                    "estimated_total_loss": _fmt_dec(loss_per_unit_home * units),
                    "estimated_reward": _fmt_dec(reward_home),
                    "account_currency": account_home_ccy,
                    "risk_input_aud": _fmt_dec(risk_input_aud),
                    "risk_amount_home": _fmt_dec(risk_amount_home),
                    "margin_rate": _fmt_dec(effective_margin_rate),
                    "position_value_factor": _fmt_dec(_position_value_factor),
                    "estimated_position_value_home": _fmt_dec(estimated_position_value_home),
                    "estimated_initial_margin_home": _fmt_dec(estimated_initial_margin_home),
                    "margin_available_home": _fmt_dec(margin_available),
                    "submitted_risk_mode": risk_mode,
                    "submitted_risk_value": _fmt_dec(risk_val),
                    "submitted_stop_loss_ticks": _fmt_dec(stop_ticks),
                    "entry_price_used": _fmt_dec_by_precision(entry, tick_size),
                    "spread_quote": _fmt_dec(spread_quote),
                    "loss_per_unit_home": _fmt_dec(loss_per_unit_home),
                    "units_raw": _fmt_dec(units_raw),
                    "units_final": _fmt_dec(units),
                    "rr": _fmt_dec_by_precision((abs(tp - entry) / abs(entry - sl)) if abs(entry - sl) > 0 else Decimal("0"), Decimal("0.01")),
                    "target_mode": target_mode,
                    "requested_rr_net": _fmt_dec_by_precision(requested_rr_net, Decimal("0.01")) if requested_rr_net is not None else None,
                    "effective_rr_net": _fmt_dec_by_precision(effective_rr_net, Decimal("0.01")) if effective_rr_net is not None else None,
                    "fee_buffer_r": _fmt_dec_by_precision(fee_buffer_r, Decimal("0.01")) if fee_buffer_r is not None else None,
                }
            calculation_context_id = (
                str(payload.get("calculation_context_id") or "").strip()
                or f"calcctx_{broker}_{account}_{uuid4().hex}"
            )
            response_payload["calculation_context_id"] = calculation_context_id
            response_payload["quote_created_at_ms"] = int(time.time() * 1000)
            try:
                _upsert_calculator_trade_context(
                    {
                        "calculation_context_id": calculation_context_id,
                        "broker": broker,
                        "venue": response_payload.get("venue"),
                        "asset": "fx",
                        "account": account,
                        "category": "forex",
                        "instrument": symbol,
                        "symbol": symbol,
                        "side": side,
                        "order_type": order_type,
                        "target_mode": target_mode,
                        "risk_mode": risk_mode,
                        "risk_value": _fmt_dec(risk_val),
                        "stop_loss_ticks": _fmt_dec(stop_ticks),
                        "take_profit_ticks": _fmt_dec(tp_ticks) if tp_ticks is not None else None,
                        "risk_reward": _fmt_dec(rr_requested) if rr_requested is not None else None,
                        "timeframe": _normalize_journal_timeframe(payload.get("timeframe") or ""),
                        "is_test_trade": is_test_trade,
                        "setup": normalized_setup,
                        "pattern": normalized_pattern,
                        "ema": normalized_ema,
                        "vwap": normalized_vwap,
                        "aths_atls": normalized_aths_atls,
                        "round_number": normalized_round_number,
                        "webhook_mode": "Yes" if webhook_enabled else "No",
                        "webhook_status": "Waiting" if webhook_enabled else "Not used",
                        "entry_price": response_payload.get("entry_price"),
                        "planned_entry_price": response_payload.get("entry_price"),
                        "stop_loss": response_payload.get("stop_price"),
                        "planned_stop_price": response_payload.get("stop_price"),
                        "take_profit": response_payload.get("target_price"),
                        "planned_target_price": response_payload.get("target_price"),
                        "quantity": response_payload.get("quantity"),
                        "quote_created_at_ms": response_payload.get("quote_created_at_ms"),
                        "status": "QUOTED",
                    },
                    require_durable=True,
                    invalidate_cache=False,
                )
                response_payload["calculation_context_saved"] = True
            except Exception as exc:
                raise HTTPException(
                    status_code=502,
                    detail={
                        "code": "CALC_CONTEXT_SAVE_FAILED",
                        "message": (
                            "The quote was calculated, but its trade context could not be "
                            "saved durably. Retry the quote before submitting."
                        ),
                    },
                ) from exc
            quote_version_invalidated = False
            if webhook_enabled:
                pending_id = existing_pending_id or f"calc_oanda_{uuid4().hex[:16]}"
                webhook_payload = {
                    "asset": "fx",
                    "account": account,
                    "symbol": symbol,
                    "action": side,
                    "order_type": order_type,
                    "quantity": _fmt_dec(units),
                    "entry_price": _fmt_dec(entry),
                    "planned_entry_price": _fmt_dec(entry),
                    "stop_loss_price": _fmt_dec(sl),
                    "planned_stop_price": _fmt_dec(sl),
                    "take_profit_price": _fmt_dec(tp),
                    "planned_target_price": _fmt_dec(tp),
                    "timeframe": _normalize_journal_timeframe(payload.get("timeframe") or ""),
                    "is_test_trade": is_test_trade,
                    "risk_mode": risk_mode,
                    "risk_value": _fmt_dec(risk_val),
                    "stop_loss_ticks": _fmt_dec(stop_ticks),
                    "target_mode": target_mode,
                    "take_profit_ticks": _fmt_dec(tp_ticks) if tp_ticks is not None else None,
                    "risk_reward": _fmt_dec(rr_requested) if rr_requested is not None else None,
                    "quote_created_at_ms": response_payload.get("quote_created_at_ms"),
                    "setup": normalized_setup,
                    "pattern": normalized_pattern,
                    "ema": normalized_ema,
                    "vwap": normalized_vwap,
                    "aths_atls": normalized_aths_atls,
                    "round_number": normalized_round_number,
                    "pending_webhook_id": pending_id,
                    "calculation_context_id": calculation_context_id,
                    "webhook_endpoint_url": webhook_endpoint_url,
                    "webhook_origin_host": webhook_origin_host,
                    "webhook_origin_profile": webhook_origin_profile,
                    "webhook_origin_instance_id": webhook_origin_instance_id,
                }
                pending_item = _upsert_pending_webhook(
                    {
                        "id": pending_id,
                        "asset": "fx",
                        "category": "forex",
                        "resolved_broker": "oanda",
                        "account": account,
                        "instrument": symbol,
                        "side": side,
                        "order_type": order_type,
                        "entry_price": _fmt_dec(entry),
                        "stop_loss": _fmt_dec(sl),
                        "take_profit": _fmt_dec(tp),
                        "size": _fmt_dec(units),
                        "timeframe": webhook_payload.get("timeframe") or "",
                        "is_test_trade": is_test_trade,
                        "risk_mode": risk_mode,
                        "risk_value": _fmt_dec(risk_val),
                        "stop_loss_ticks": _fmt_dec(stop_ticks),
                        "target_mode": target_mode,
                        "take_profit_ticks": _fmt_dec(tp_ticks) if tp_ticks is not None else None,
                        "risk_reward": _fmt_dec(rr_requested) if rr_requested is not None else None,
                        "planned_entry_price": _fmt_dec(entry),
                        "planned_stop_price": _fmt_dec(sl),
                        "planned_target_price": _fmt_dec(tp),
                        "quote_created_at_ms": response_payload.get("quote_created_at_ms"),
                        "setup": normalized_setup,
                        "pattern": normalized_pattern,
                        "ema": normalized_ema,
                        "vwap": normalized_vwap,
                        "aths_atls": normalized_aths_atls,
                        "round_number": normalized_round_number,
                        "status": "WAITING",
                        "enabled": True,
                        "calculation_context_id": calculation_context_id,
                    }
                )
                quote_version_invalidated = True
                response_payload["pending_webhook_id"] = pending_item.get("id")
                response_payload["webhook_endpoint"] = "/api/calculator/webhook"
                response_payload["webhook_endpoint_url"] = webhook_endpoint_url
                response_payload["webhook_payload_json"] = json.dumps(webhook_payload, separators=(",", ":"))
                if previous_pending_id and previous_pending_id != pending_id:
                    _delete_pending_webhook(previous_pending_id, invalidate_cache=False)
            elif previous_pending_id:
                quote_version_invalidated = _delete_pending_webhook(previous_pending_id)
            if not quote_version_invalidated:
                _invalidate_open_orders_cache()
            response_payload["quote_latency_ms"] = int((time.perf_counter() - quote_started) * 1000)
            response_payload["upstream_timings_ms"] = timings_ms
            CALCULATOR_LOGGER.info("CALCULATOR_QUOTE_TIMING asset=%s account=%s symbol=%s total_ms=%s timings=%s", asset, account, symbol, response_payload["quote_latency_ms"], timings_ms)
            return JSONResponse(response_payload)

        raise HTTPException(status_code=400, detail="asset must be crypto or fx.")
    except CalculatorDependencyTimeout as exc:
        CALCULATOR_LOGGER.warning("CALCULATOR_QUOTE_TIMEOUT asset=%s account=%s symbol=%s dependency=%s timings=%s", asset, account, resolved_symbol_for_debug, exc.dependency, timings_ms)
        raise HTTPException(status_code=504, detail=_calculator_quote_error_detail("QUOTE_DEPENDENCY_TIMEOUT", str(exc), dependency=exc.dependency, timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies))
    except asyncio.TimeoutError:
        CALCULATOR_LOGGER.warning("CALCULATOR_QUOTE_TIMEOUT asset=%s account=%s symbol=%s dependency=%s timings=%s", asset, account, resolved_symbol_for_debug, last_dependency_started.get("name"), timings_ms)
        raise HTTPException(status_code=504, detail=_calculator_quote_error_detail("QUOTE_TIMEOUT", "Calculator quote timed out.", dependency=last_dependency_started.get("name"), timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies))
    except HTTPException as exc:
        detail = exc.detail
        if isinstance(detail, dict):
            dbg = detail.setdefault("debug", {})
            dbg.setdefault("quote_latency_ms", _calculator_quote_elapsed_ms(quote_started))
            dbg.setdefault("upstream_timings_ms", timings_ms)
            dbg.setdefault("submitted_payload", submitted_debug)
            dbg.setdefault("resolved_symbol", resolved_symbol_for_debug)
            dbg.setdefault("pending_dependencies", sorted(pending_dependencies))
            raise HTTPException(status_code=exc.status_code, detail=detail)
        raise HTTPException(status_code=exc.status_code, detail=_calculator_quote_error_detail("QUOTE_FAILED", str(detail), timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies))
    except Exception as exc:
        raise HTTPException(status_code=502, detail=_calculator_quote_error_detail("INTERNAL_CALCULATOR_ERROR", str(exc), timings_ms=timings_ms, quote_started=quote_started, submitted_payload=submitted_debug, resolved_symbol=resolved_symbol_for_debug, pending_dependencies=pending_dependencies)) from exc


def _get_oanda_quote_home_factors(
    prices_payload: Dict[str, object],
    row: Dict[str, object],
    quote_ccy: str,
    account_home_ccy: str,
) -> Tuple[Decimal, Decimal, Decimal]:
    quote_code = str(quote_ccy or "").strip().upper()
    home_code = str(account_home_ccy or "").strip().upper()
    if quote_code and home_code and quote_code == home_code:
        one = Decimal("1")
        return one, one, one

    def _pick_from_home_conversions(conversions: object) -> Optional[Tuple[Decimal, Decimal, Decimal]]:
        if not isinstance(conversions, list):
            return None
        for item in conversions:
            if not isinstance(item, dict):
                continue
            if str(item.get("currency") or "").strip().upper() != quote_code:
                continue
            gain = Decimal(str(item.get("accountGain") or "0"))
            loss = Decimal(str(item.get("accountLoss") or "0"))
            position_value = Decimal(str(item.get("positionValue") or "0"))
            if gain > 0 and loss > 0 and position_value > 0:
                return gain, loss, position_value
        return None

    top_level = _pick_from_home_conversions(prices_payload.get("homeConversions"))
    if top_level is not None:
        return top_level

    row_level = _pick_from_home_conversions(row.get("homeConversions"))
    if row_level is not None:
        return row_level

    deprecated = row.get("quoteHomeConversionFactors")
    if isinstance(deprecated, dict):
        gain = Decimal(str(deprecated.get("positiveUnits") or "0"))
        loss = Decimal(str(deprecated.get("negativeUnits") or "0"))
        if gain > 0 and loss > 0:
            return gain, loss, gain

    raise ValueError(f"missing usable conversion factors for {quote_code or quote_ccy}")




@app.post("/api/calculator/webhook")
async def calculator_webhook(request: Request, payload: Dict[str, object] = Body(default={})) -> JSONResponse:
    if isinstance(request, dict) and (not isinstance(payload, dict) or not payload):
        payload = request
        request = Request(
            {
                "type": "http",
                "http_version": "1.1",
                "method": "POST",
                "scheme": "http",
                "path": "/api/calculator/webhook",
                "raw_path": b"/api/calculator/webhook",
                "query_string": b"",
                "headers": [],
                "client": ("127.0.0.1", 0),
                "server": ("localhost", 80),
            }
        )
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Webhook payload must be a JSON object.")
    pending_id = str(payload.get("pending_webhook_id") or "").strip()
    asset = str(payload.get("asset") or "crypto").strip().lower()
    request_id = f"calc-webhook-{uuid4().hex[:12]}"
    attempt = _record_webhook_attempt(
        {
            "request_id": request_id,
            "pending_webhook_id": pending_id or None,
            "received_at": _utc_now_iso(),
            "asset": asset,
            "broker": "bybit" if asset == "crypto" else ("oanda" if asset == "fx" else None),
            "account": str(payload.get("account") or "").strip().lower() or None,
            "symbol": str(payload.get("symbol") or "").strip().upper() or None,
            "action": str(payload.get("action") or payload.get("side") or "").strip().lower() or None,
            "status": "RECEIVED",
            "request_host": request.headers.get("host"),
            "request_url": str(request.url),
            "client": request.client.host if request.client else None,
            "payload_origin_host": payload.get("webhook_origin_host"),
            "payload_endpoint_url": payload.get("webhook_endpoint_url"),
            "payload": dict(payload),
        }
    )
    CALCULATOR_LOGGER.info(
        "WEBHOOK_RECEIVED request_id=%s pending_webhook_id=%s host=%s origin_host=%s endpoint_url=%s symbol=%s account=%s",
        request_id,
        pending_id or "<none>",
        request.headers.get("host") or "<none>",
        str(payload.get("webhook_origin_host") or "<none>"),
        str(payload.get("webhook_endpoint_url") or "<none>"),
        str(payload.get("symbol") or "").strip().upper() or "<none>",
        str(payload.get("account") or "").strip().lower() or "<none>",
    )

    try:
        _assert_pending_webhook_executable(payload)
        if pending_id:
            _update_pending_webhook(
                pending_id,
                {
                    "status": "TRIGGERING",
                    "triggered_at": _utc_now_iso(),
                    "request_id": request_id,
                },
            )
            _update_webhook_attempt(
                request_id,
                {
                    "status": "TRIGGERING",
                },
            )
        try:
            normalized_setup = _normalize_setup(payload.get("setup"))
            normalized_pattern = _normalize_pattern(payload.get("pattern"))
            normalized_ema = _normalize_ema(payload.get("ema"))
            normalized_vwap = _normalize_vwap(payload.get("vwap"))
            normalized_aths_atls = _normalize_aths_atls(payload.get("aths_atls"))
            normalized_round_number = _normalize_round_number(payload.get("round_number"))
        except ValueError as exc:
            raise HTTPException(status_code=422, detail=str(exc)) from exc

        canonical = {
            "account": payload.get("account"),
            "symbol": payload.get("symbol"),
            "action": payload.get("action") or payload.get("side"),
            "order_type": payload.get("order_type"),
            "entry_price": payload.get("entry_price") or payload.get("planned_entry_price"),
            "stop_loss_price": payload.get("stop_loss_price") or payload.get("planned_stop_price"),
            "take_profit_price": payload.get("take_profit_price") or payload.get("planned_target_price"),
            "quantity": payload.get("quantity"),
            "timeframe": _normalize_journal_timeframe(payload.get("timeframe")),
            "setup": normalized_setup,
            "pattern": normalized_pattern,
            "ema": normalized_ema,
            "vwap": normalized_vwap,
            "aths_atls": normalized_aths_atls,
            "round_number": normalized_round_number,
            "calculation_context_id": payload.get("calculation_context_id") or payload.get("context_id"),
        "quote_created_at_ms": payload.get("quote_created_at_ms"),
        "risk_mode": payload.get("risk_mode"),
        "risk_value": payload.get("risk_value"),
        "stop_loss_ticks": payload.get("stop_loss_ticks"),
        "take_profit_ticks": payload.get("take_profit_ticks"),
        "target_mode": payload.get("target_mode"),
        "risk_reward": payload.get("risk_reward"),
        "is_test_trade": _normalize_test_trade_flag(
                payload.get("is_test_trade", payload.get("test_trade", payload.get("test")))
            ),
            "pending_webhook_id": pending_id or None,
            "level_anchor_mode": payload.get("level_anchor_mode") or "actual_fill",
            "planned_entry_price": payload.get("planned_entry_price") or payload.get("entry_price"),
            "planned_stop_price": payload.get("planned_stop_price") or payload.get("stop_loss_price"),
            "planned_target_price": payload.get("planned_target_price") or payload.get("take_profit_price"),
        }

        if asset == "crypto":
            CALCULATOR_LOGGER.info(
                "WEBHOOK_BYBIT_SUBMIT request_id=%s account=%s category=%s symbol=%s order_type=%s qty=%s",
                request_id,
                str(canonical.get("account") or "").strip().lower() or "<none>",
                "linear",
                str(canonical.get("symbol") or "").strip().upper() or "<none>",
                str(canonical.get("order_type") or "market"),
                str(canonical.get("quantity") or "<none>"),
            )
            result = await _place_bybit_order(
                canonical,
                request_id=request_id,
                invalidate_cache=not bool(pending_id),
            )
            bybit_result = result.get("order") if isinstance(result, dict) else {}
            live_state_present = False
            try:
                live_payload = await list_open_orders(force=True)
                live_body = json.loads(live_payload.body.decode("utf-8"))
                live_items = live_body.get("items") if isinstance(live_body, dict) else []
                if isinstance(live_items, list):
                    order_id = str((bybit_result or {}).get("orderId") or "").strip()
                    order_link_id = str((bybit_result or {}).get("orderLinkId") or "").strip()
                    symbol = str(canonical.get("symbol") or "").strip().upper()
                    account = str(canonical.get("account") or "").strip().lower()
                    category = "linear"
                    for row in live_items:
                        if not isinstance(row, dict):
                            continue
                        if str(row.get("broker") or "").strip().lower() != "bybit":
                            continue
                        if account and str(row.get("account") or "").strip().lower() != account:
                            continue
                        if category and str(row.get("category") or "").strip().lower() != category:
                            continue
                        if symbol and str(row.get("instrument") or "").strip().upper() != symbol:
                            continue
                        row_order_id = str(row.get("id") or row.get("order_id") or "").strip()
                        row_order_link_id = str(row.get("order_link_id") or "").strip()
                        if order_id and row_order_id == order_id:
                            live_state_present = True
                            break
                        if order_link_id and row_order_link_id == order_link_id:
                            live_state_present = True
                            break
                        row_type = str(row.get("type") or "").strip().lower()
                        if row_type == "position":
                            live_state_present = True
                            break
            except Exception:
                live_state_present = False
            _update_webhook_attempt(
                request_id,
                {
                    "status": "BYBIT_ACCEPTED" if live_state_present else "BYBIT_ACCEPTED_NO_LIVE_STATE_YET",
                    "bybit_ret_code": 0,
                    "bybit_ret_msg": "OK",
                    "bybit_result": bybit_result if isinstance(bybit_result, dict) else {},
                    "order_id": str((bybit_result or {}).get("orderId") or "").strip() or None,
                    "order_link_id": str(
                        (bybit_result or {}).get("orderLinkId") or ""
                    ).strip()
                    or None,
                },
            )
            CALCULATOR_LOGGER.info(
                "WEBHOOK_BYBIT_RESPONSE request_id=%s retCode=%s retMsg=%s orderId=%s orderLinkId=%s",
                request_id,
                0,
                "OK",
                str((bybit_result or {}).get("orderId") or "<none>"),
                str((bybit_result or {}).get("orderLinkId") or "<none>"),
            )
            if pending_id:
                _consume_pending_webhook(
                    pending_id,
                    request_id=request_id,
                    reason="order_accepted",
                )
            return JSONResponse({
                "ok": True,
                "broker": "bybit",
                "venue": "Bybit",
                "resolved_venue": "Bybit",
                "result": result,
                "journal_context_saved": result.get("journal_context_saved", True),
                "warnings": result.get("warnings"),
                "context_save_error": result.get("context_save_error"),
            })
        if asset == "fx":
            result = await _place_oanda_order(
                canonical,
                request_id=request_id,
            )
            _update_webhook_attempt(request_id, {"status": "CONSUMED"})
            return JSONResponse({
                "ok": True,
                "broker": "oanda",
                "venue": "OANDA",
                "resolved_venue": "OANDA",
                "result": result,
                "journal_context_saved": result.get("journal_context_saved", True),
                "warnings": result.get("warnings"),
                "context_save_error": result.get("context_save_error"),
            })

        raise HTTPException(status_code=400, detail="asset must be crypto or fx.")
    except BybitPreSubmitValidationError as exc:
        if pending_id:
            _update_pending_webhook(
                pending_id,
                {
                    "status": "BYBIT_PRE_SUBMIT_BLOCKED",
                    "last_error": exc.message,
                    "last_attempt_at": _utc_now_iso(),
                    "request_id": request_id,
                },
            )
        _update_webhook_attempt(request_id, {"status": "FAILED_BEFORE_SUBMIT", "error": exc.message, "debug": exc.debug})
        raise HTTPException(status_code=400, detail={"code": exc.code, "message": exc.message, "debug": exc.debug}) from exc
    except ValueError as exc:
        if "pending_webhook_id is required" in str(exc):
            _update_webhook_attempt(
                request_id,
                {"status": "PENDING_NOT_FOUND", "error": str(exc)},
            )
            return JSONResponse(
                {
                    "ok": False,
                    "code": "PENDING_WEBHOOK_NOT_FOUND",
                    "message": "Webhook reached this server, but the pending_webhook_id does not exist on this instance.",
                    "pending_webhook_id": pending_id or None,
                    "current_host": request.headers.get("host"),
                    "payload_origin_host": payload.get("webhook_origin_host"),
                },
                status_code=409,
            )
        if "Pending webhook missing or no longer active." in str(exc):
            _update_webhook_attempt(
                request_id,
                {"status": "PENDING_NOT_FOUND", "error": str(exc)},
            )
            if pending_id:
                _update_pending_webhook(
                    pending_id,
                    {
                        "status": "PENDING_NOT_FOUND",
                        "last_error": str(exc),
                        "last_attempt_at": _utc_now_iso(),
                        "request_id": request_id,
                    },
                )
            return JSONResponse(
                {
                    "ok": False,
                    "code": "PENDING_WEBHOOK_NOT_FOUND",
                    "message": "Webhook reached this server, but the pending_webhook_id does not exist on this instance.",
                    "pending_webhook_id": pending_id or None,
                    "current_host": request.headers.get("host"),
                    "payload_origin_host": payload.get("webhook_origin_host"),
                },
                status_code=409,
            )
        raise HTTPException(status_code=400, detail=f"Calculator webhook execution failed: {exc}") from exc
    except BybitOrderRejected as exc:
        if pending_id:
            _update_pending_webhook(
                pending_id,
                {
                    "status": "BYBIT_REJECTED",
                    "last_error": str(exc),
                    "bybit_ret_code": exc.ret_code,
                    "bybit_ret_msg": exc.ret_msg,
                    "last_attempt_at": _utc_now_iso(),
                    "request_id": request_id,
                },
            )
        _update_webhook_attempt(
            request_id,
            {
                "status": "BYBIT_REJECTED",
                "bybit_request": exc.request_body,
                "bybit_http_status": exc.http_status,
                "bybit_ret_code": exc.ret_code,
                "bybit_ret_msg": exc.ret_msg,
                "bybit_ret_ext_info": exc.ret_ext_info,
                "bybit_result": exc.result,
                "error": str(exc),
                "stack": traceback.format_exc(),
            },
        )
        CALCULATOR_LOGGER.warning(
            "WEBHOOK_BYBIT_RESPONSE request_id=%s retCode=%s retMsg=%s orderId=%s orderLinkId=%s",
            request_id,
            exc.ret_code,
            exc.ret_msg,
            str((exc.result or {}).get("orderId") or "<none>"),
            str((exc.result or {}).get("orderLinkId") or "<none>"),
        )
        if pending_id:
            _upsert_trade_context(
                {
                    "pending_webhook_id": pending_id,
                    "status": "FAILED",
                    "failure_stage": "bybit_order_create",
                    "consume_reason": "webhook_received",
                    "request_id": request_id,
                    "last_error": str(exc),
                    "last_attempt_at": _utc_now_iso(),
                }
            )
        raise HTTPException(status_code=400, detail=f"Calculator webhook execution failed: {exc}") from exc
    except HTTPException:
        raise
    except RuntimeError as exc:
        message = str(exc)
        if pending_id:
            _update_pending_webhook(
                pending_id,
                {
                    "status": "ORDER_CREATED_TPSL_FAILED" if "created but TP/SL application failed" in message else "FAILED_BEFORE_SUBMIT",
                    "last_error": message,
                    "last_attempt_at": _utc_now_iso(),
                    "request_id": request_id,
                },
            )
        if "created but TP/SL application failed" in message:
            _update_webhook_attempt(
                request_id,
                {
                    "status": "ORDER_CREATED_TPSL_FAILED",
                    "error": message,
                    "stack": traceback.format_exc(),
                },
            )
        else:
            _update_webhook_attempt(
                request_id,
                {
                    "status": "FAILED_BEFORE_SUBMIT",
                    "error": message,
                    "stack": traceback.format_exc(),
                },
            )
        if pending_id:
            _upsert_trade_context(
                {
                    "pending_webhook_id": pending_id,
                    "status": "FAILED",
                    "failure_stage": "bybit_order_create",
                    "consume_reason": "webhook_received",
                    "request_id": request_id,
                    "last_error": message,
                    "last_attempt_at": _utc_now_iso(),
                },
            )
        raise HTTPException(status_code=400, detail=f"Calculator webhook execution failed: {message}") from exc
    except Exception as exc:
        if pending_id:
            _update_pending_webhook(
                pending_id,
                {
                    "status": "FAILED_BEFORE_SUBMIT",
                    "last_error": str(exc),
                    "last_attempt_at": _utc_now_iso(),
                    "request_id": request_id,
                },
            )
        _update_webhook_attempt(
            request_id,
            {
                "status": "FAILED_BEFORE_SUBMIT",
                "error": str(exc),
                "stack": traceback.format_exc(),
            },
        )
        if pending_id:
            _upsert_trade_context(
                {
                    "pending_webhook_id": pending_id,
                    "status": "FAILED",
                    "failure_stage": "bybit_order_create",
                    "consume_reason": "webhook_received",
                    "request_id": request_id,
                    "last_error": str(exc),
                    "last_attempt_at": _utc_now_iso(),
                },
            )
        raise HTTPException(status_code=400, detail=f"Calculator webhook execution failed: {exc}") from exc


@app.get("/api/calculator/webhook-attempts")
async def calculator_webhook_attempts(
    limit: int = Query(50, ge=1, le=500),
    pending_webhook_id: Optional[str] = Query(None),
    symbol: Optional[str] = Query(None),
    account: Optional[str] = Query(None),
    status: Optional[str] = Query(None),
) -> JSONResponse:
    def _plain_optional_query(value: Optional[str]) -> Optional[str]:
        return value if isinstance(value, str) else None
    pending_webhook_id = _plain_optional_query(pending_webhook_id)
    symbol = _plain_optional_query(symbol)
    account = _plain_optional_query(account)
    status = _plain_optional_query(status)
    items = list(reversed(_load_webhook_attempts()))
    if pending_webhook_id:
        needle = pending_webhook_id.strip()
        items = [it for it in items if str(it.get("pending_webhook_id") or "").strip() == needle]
    if symbol:
        needle = symbol.strip().upper()
        items = [it for it in items if str(it.get("symbol") or "").strip().upper() == needle]
    if account:
        needle = account.strip().lower()
        items = [it for it in items if str(it.get("account") or "").strip().lower() == needle]
    if status:
        needle = status.strip().upper()
        items = [it for it in items if str(it.get("status") or "").strip().upper() == needle]
    limited = items[: int(limit)]
    return JSONResponse(
        {
            "items": limited,
            "updated_at": _utc_now_iso(),
            "matched_count": len(items),
            "latest_status": str(limited[0].get("status") or "") if limited else None,
            "found_pending_id": bool(pending_webhook_id and items),
        }
    )


@app.get("/api/calculator/webhook-diagnostic/{pending_webhook_id}")
async def calculator_webhook_diagnostic(pending_webhook_id: str) -> JSONResponse:
    pid = str(pending_webhook_id or "").strip()
    attempts = [a for a in reversed(_load_webhook_attempts()) if str(a.get("pending_webhook_id") or "").strip() == pid]
    pending = next((p for p in _load_pending_webhooks() if str(p.get("id") or "").strip() == pid), None)
    trade = next((t for t in _load_trade_contexts() if str(t.get("pending_webhook_id") or "").strip() == pid), None)
    if pending and not attempts:
        status = "WAITING_NO_POST_RECEIVED"
    elif attempts:
        status = str(attempts[0].get("status") or "UNKNOWN")
    else:
        status = "NO_RENDER_ATTEMPT_RECORDED"
    latest = attempts[0] if attempts else {}
    return JSONResponse(
        {
            "ok": True,
            "status": status,
            "pending_webhook_id": pid,
            "pending_webhook_record": pending,
            "attempts": attempts,
            "trade_context": trade,
            "bybit_ret_code": latest.get("bybit_ret_code"),
            "bybit_ret_msg": latest.get("bybit_ret_msg"),
            "orderId": latest.get("order_id"),
            "orderLinkId": latest.get("order_link_id"),
            "current_instance": {
                "app_profile": APP_PROFILE,
                "app_instance_id": str(os.getenv("APP_INSTANCE_ID") or os.getenv("RENDER_INSTANCE_ID") or os.getenv("RENDER_SERVICE_ID") or os.getenv("HOSTNAME") or "").strip() or None,
                "host": str(os.getenv("HOSTNAME") or "").strip() or None,
                "render_calculator_base_url_configured": bool(str(os.getenv("RENDER_CALCULATOR_BASE_URL") or "").strip()),
                "render_calculator_base_url_host": _render_calculator_host() or None,
            },
        }
    )


@app.post("/api/calculator/submit")
async def calculator_submit(payload: Dict[str, object] = Body(default={})) -> JSONResponse:
    asset = str(payload.get("asset") or "").strip().lower()
    requested_broker = str(payload.get("broker") or "").strip().lower()
    if asset == "fx" and requested_broker == "pepperstone":
        raise HTTPException(
            status_code=400,
            detail="Pepperstone orders are user-mediated through a downloaded MT5 .set file; Render cannot submit them.",
        )
    try:
        normalized_setup = _normalize_setup(payload.get("setup"))
        normalized_pattern = _normalize_pattern(payload.get("pattern"))
        normalized_ema = _normalize_ema(payload.get("ema"))
        normalized_vwap = _normalize_vwap(payload.get("vwap"))
        normalized_aths_atls = _normalize_aths_atls(payload.get("aths_atls"))
        normalized_round_number = _normalize_round_number(payload.get("round_number"))
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    canonical = {
        "account": payload.get("account"),
        "symbol": payload.get("symbol"),
        "action": payload.get("action") or payload.get("side"),
        "order_type": payload.get("order_type"),
        "entry_price": payload.get("entry_price"),
        "stop_loss_price": payload.get("stop_loss_price"),
        "take_profit_price": payload.get("take_profit_price"),
        "quantity": payload.get("quantity"),
        "timeframe": _normalize_journal_timeframe(payload.get("timeframe")),
        "planned_entry_price": payload.get("planned_entry_price"),
        "planned_stop_price": payload.get("planned_stop_price"),
        "planned_target_price": payload.get("planned_target_price"),
        "level_anchor_mode": payload.get("level_anchor_mode"),
        "pending_webhook_id": payload.get("pending_webhook_id"),
        "previous_pending_webhook_id": payload.get("previous_pending_webhook_id"),
        "calculation_context_id": payload.get("calculation_context_id") or payload.get("context_id"),
        "quote_created_at_ms": payload.get("quote_created_at_ms"),
        "risk_mode": payload.get("risk_mode"),
        "risk_value": payload.get("risk_value"),
        "stop_loss_ticks": payload.get("stop_loss_ticks"),
        "take_profit_ticks": payload.get("take_profit_ticks"),
        "target_mode": payload.get("target_mode"),
        "risk_reward": payload.get("risk_reward"),
        "is_test_trade": _normalize_test_trade_flag(
            payload.get("is_test_trade", payload.get("test_trade", payload.get("test")))
        ),
        "setup": normalized_setup,
        "pattern": normalized_pattern,
        "ema": normalized_ema,
        "vwap": normalized_vwap,
        "aths_atls": normalized_aths_atls,
        "round_number": normalized_round_number,
    }
    request_id = f"calc-{uuid4().hex[:12]}"
    try:
        if asset == "crypto":
            result = await _place_bybit_order(
                canonical,
                request_id=request_id,
            )
            return JSONResponse({
                "ok": True,
                "broker": "bybit",
                "venue": "Bybit",
                "resolved_venue": "Bybit",
                "result": result,
                "submit_level_adjustments": canonical.get("_submit_level_adjustments"),
                "journal_context_saved": result.get("journal_context_saved", True),
                "warnings": result.get("warnings"),
                "context_save_error": result.get("context_save_error"),
            })
        if asset == "fx":
            result = await _place_oanda_order(
                canonical,
                request_id=request_id,
            )
            return JSONResponse({
                "ok": True,
                "broker": "oanda",
                "venue": "OANDA",
                "resolved_venue": "OANDA",
                "result": result,
                "journal_context_saved": result.get("journal_context_saved", True),
                "warnings": result.get("warnings"),
                "context_save_error": result.get("context_save_error"),
            })
        raise HTTPException(status_code=400, detail="asset must be crypto or fx.")
    except HTTPException:
        raise
    except BybitPreSubmitValidationError as exc:
        return JSONResponse({"ok": False, "code": exc.code, "message": exc.message, "debug": exc.debug}, status_code=400)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f"Order submit failed: {exc}") from exc
    except BybitOrderRejected as exc:
        return JSONResponse(
            {
                "ok": False,
                "code": "BYBIT_REJECTED",
                "message": "Bybit rejected the order.",
                "debug": {
                    "ret_code": exc.ret_code,
                    "ret_msg": exc.ret_msg,
                    "http_status": exc.http_status,
                    "request_body": exc.request_body,
                    "response_body": exc.response_body,
                    "result": exc.result,
                    "ret_ext_info": exc.ret_ext_info,
                },
            },
            status_code=400,
        )
    except BybitPostCreateProtectionError as exc:
        return JSONResponse(
            {
                "ok": False,
                "code": "BYBIT_ORDER_CREATED_TPSL_FAILED",
                "message": "Bybit order was created, but TP/SL application failed.",
                "debug": {
                    "order_id": exc.order_id,
                    "order_link_id": exc.order_link_id,
                    "symbol": exc.symbol,
                    "account": exc.account,
                    "category": exc.category,
                    "side": exc.side,
                    "stage": exc.stage,
                    "tpsl_error": exc.tpsl_error,
                    "request_body": exc.request_body,
                    "order_result": exc.order_result,
                },
            },
            status_code=409,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Order submit failed: {exc}") from exc


