def _compute_journal_period_stats(
    rows: List[Dict[str, object]],
    balances: List[Dict[str, object]],
    *,
    _recommendation_cache: Optional[
        Dict[Tuple[str, Tuple[str, ...]], Dict[str, object]]
    ] = None,
) -> Dict[str, object]:
    trade_rows = [dict(r) for r in rows or [] if isinstance(r, dict) and _is_trade_row(r)]
    recommendation_cache = (
        _recommendation_cache if isinstance(_recommendation_cache, dict) else {}
    )

    def _period_datetime(row: Dict[str, object]) -> Optional[datetime]:
        value = row.get("close_time") or row.get("open_time")
        if isinstance(value, datetime):
            return value
        if isinstance(value, _date):
            return datetime(value.year, value.month, value.day, tzinfo=timezone.utc)
        parsed = _parse_iso_datetime(value)
        return parsed if isinstance(parsed, datetime) else None

    def _move_duration_stats(rows_subset: List[Dict[str, object]], prefix: str) -> Dict[str, Optional[float]]:
        values: List[float] = []
        for row in rows_subset:
            if _is_test_trade_row(row):
                continue
            duration = _to_float(row.get(f"{prefix}_duration"))
            if duration is None:
                move_time = _parse_iso_datetime(row.get(f"{prefix}_time"))
                open_time = _parse_iso_datetime(row.get("open_time"))
                if move_time is not None and open_time is not None:
                    duration = (move_time - open_time).total_seconds()
            if duration is not None and duration >= 0:
                values.append(float(duration))
        return {
            "min": min(values) if values else None,
            "avg": (sum(values) / len(values)) if values else None,
            "max": max(values) if values else None,
        }

    def _stats_for(rows_subset: List[Dict[str, object]]) -> Dict[str, object]:
        try:
            stats = _compute_journal_stats(
                rows_subset,
                balances or [],
                _recommendation_cache=recommendation_cache,
            )
        except TypeError as exc:
            if "_recommendation_cache" not in str(exc):
                raise
            # Some focused tests replace the stats builder with a two-argument stub.
            stats = _compute_journal_stats(rows_subset, balances or [])
        move_break_even = _move_duration_stats(rows_subset, "move_to_break_even")
        move_profit = _move_duration_stats(rows_subset, "move_to_profit")
        totals = stats.get("totals") if isinstance(stats.get("totals"), dict) else {}
        groups = stats.get("groups") if isinstance(stats.get("groups"), dict) else {}
        by_market = groups.get("by_market") if isinstance(groups.get("by_market"), dict) else {}
        overall = by_market.get("overall") if isinstance(by_market.get("overall"), dict) else {}
        for target in (totals, overall):
            target["move_to_break_even_duration_seconds"] = move_break_even["avg"]
            target["min_move_to_break_even_duration_seconds"] = move_break_even["min"]
            target["avg_move_to_break_even_duration_seconds"] = move_break_even["avg"]
            target["max_move_to_break_even_duration_seconds"] = move_break_even["max"]
            target["move_to_profit_duration_seconds"] = move_profit["avg"]
            target["min_move_to_profit_duration_seconds"] = move_profit["min"]
            target["avg_move_to_profit_duration_seconds"] = move_profit["avg"]
            target["max_move_to_profit_duration_seconds"] = move_profit["max"]
        return stats

    years: Dict[int, List[Dict[str, object]]] = defaultdict(list)
    months: Dict[int, Dict[int, List[Dict[str, object]]]] = defaultdict(lambda: defaultdict(list))
    for row in trade_rows:
        dt = _period_datetime(row)
        if not dt:
            continue
        years[int(dt.year)].append(row)
        months[int(dt.year)][int(dt.month)].append(row)

    return {
        "years": {year: _stats_for(bucket) for year, bucket in sorted(years.items())},
        "months": {
            year: {month: _stats_for(bucket) for month, bucket in sorted(month_map.items())}
            for year, month_map in sorted(months.items())
        },
    }


def _compute_journal_stats_with_period_reports(
    rows: List[Dict[str, object]], balances: List[Dict[str, object]]
) -> Dict[str, object]:
    recommendation_cache: Dict[
        Tuple[str, Tuple[str, ...]], Dict[str, object]
    ] = {}
    try:
        stats = _compute_journal_stats(
            rows,
            balances,
            _recommendation_cache=recommendation_cache,
        )
    except TypeError as exc:
        if "_recommendation_cache" not in str(exc):
            raise
        stats = _compute_journal_stats(rows, balances)
    try:
        period_reports = _compute_journal_period_stats(
            rows,
            balances,
            _recommendation_cache=recommendation_cache,
        )
    except TypeError as exc:
        if "_recommendation_cache" not in str(exc):
            raise
        period_reports = _compute_journal_period_stats(rows, balances)
    stats["period_reports"] = period_reports
    return stats

def _read_bybit_settings() -> Dict[str, float]:
    try:
        settings = bybit_monitor.get_runtime_settings(force=True)
        settings["push_ready"] = bybit_monitor.push_notifications_ready()
        return settings
    except Exception as exc:  # pragma: no cover - defensive
        raise HTTPException(status_code=500, detail=f"Failed to load settings: {exc}") from exc


def _update_bybit_settings(payload: Dict[str, object]) -> Dict[str, float]:
    try:
        wait_seconds = payload.get("wait_seconds") if isinstance(payload, dict) else None
        percent_threshold = payload.get("percent_threshold") if isinstance(payload, dict) else None
        updated = bybit_monitor.update_runtime_settings(
            wait_seconds=int(wait_seconds) if wait_seconds is not None else None,
            percent_threshold=float(percent_threshold) if percent_threshold is not None else None,
        )
        write_repo_state_json_and_verify("bybit_settings", updated)
        return updated
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except Exception as exc:  # pragma: no cover - defensive
        raise HTTPException(status_code=500, detail=f"Failed to save settings: {exc}") from exc


def _read_oanda_settings() -> Dict[str, float]:
    try:
        settings = oanda_monitor.get_runtime_settings(force=True)
        settings["push_ready"] = oanda_monitor.push_notifications_ready()
        return settings
    except Exception as exc:  # pragma: no cover - defensive
        raise HTTPException(status_code=500, detail=f"Failed to load settings: {exc}") from exc


def _update_oanda_settings(payload: Dict[str, object]) -> Dict[str, float]:
    try:
        if not isinstance(payload, dict):
            raise HTTPException(status_code=400, detail="payload must be an object")
        updates: Dict[str, object] = {}
        for key in (
            "wait_seconds",
            "percent_threshold",
        ):
            if key in payload:
                updates[key] = payload.get(key)
        updated = oanda_monitor.update_runtime_settings(**updates)
        write_repo_state_json_and_verify("oanda_settings", updated)
        return updated
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except Exception as exc:  # pragma: no cover - defensive
        raise HTTPException(status_code=500, detail=f"Failed to save settings: {exc}") from exc



def _render_log_view(script_name: str) -> str:
    """Return the HTML log viewer for a known script."""

    safe_name = html.escape(script_name)
    return (
        LOG_VIEWER_TEMPLATE.replace("{script_name}", safe_name)
        .replace("{script_name_json}", json.dumps(script_name))
    )


@app.get("/logs/view/{script_name:path}", response_class=HTMLResponse)
async def view_logs(script_name: str) -> str:
    # Ensure the script exists so we don't render a viewer for an unknown path.
    script_manager.get(script_name)
    return _render_log_view(script_name)


@app.api_route("/apps/{script_name}", methods=PROXY_METHODS)
@app.api_route("/apps/{script_name}/{path:path}", methods=PROXY_METHODS)
async def proxy_app(script_name: str, request: Request, path: str = "") -> Response:
    if path == "" and not request.url.path.endswith("/"):
        suffix = f"?{request.url.query}" if request.url.query else ""
        return RedirectResponse(url=f"{request.url.path}/{suffix}", status_code=307)
    if APP_PROFILE == "render" and script_name in LOCAL_ONLY_APP_NAMES:
        accepts = str(request.headers.get("accept", "")).lower()
        wants_json = "application/json" in accepts
        return _local_only_disabled_response(f"/apps/{script_name}", as_json=wants_json)
    if script_name == "fxweekend-clone" and APP_PROFILE != "render":
        return JSONResponse(
            {
                "error": "render_owned_executor",
                "message": "FX Weekend execution is Render-owned; no local fallback is permitted.",
            },
            status_code=409,
        )

    script = script_manager.get(script_name)
    fx_previous_settings: Optional[Dict[str, object]] = None
    fx_previous_status: Optional[Dict[str, object]] = None
    if (
        APP_PROFILE == "render"
        and script.name == "fxweekend-clone"
        and request.method.upper() in {"POST", "PUT", "PATCH", "DELETE"}
        and (
            path.strip("/") == "api/config"
            or path.strip("/") == "api/news"
            or path.strip("/").startswith("api/news/")
        )
    ):
        current_settings = _load_json_file(
            FXWEEKEND_SETTINGS_PATH, FXWEEKEND_DEFAULT_SETTINGS
        )
        current_status = _load_json_file(FXWEEKEND_STATUS_PATH, {})
        fx_previous_settings = (
            dict(current_settings) if isinstance(current_settings, dict) else {}
        )
        fx_previous_status = (
            dict(current_status) if isinstance(current_status, dict) else {}
        )
    accept = request.headers.get("accept", "")
    wants_html = (
        "text/html" in accept
        and request.query_params.get("format") != "json"
        and request.method.upper() == "GET"
    )
    if not script.is_running:
        if script.name in WEB_APPS:
            if script.port is None:
                script.port = _allocate_port()
            if not script.last_start_attempt_at or script.last_start_error:
                if script.startup_task is None or script.startup_task.done():
                    starter = (
                        _background_start_after_state_restore(script)
                        if script.name == "fxweekend-clone"
                        else _background_start(script)
                    )
                    script.startup_task = asyncio.create_task(starter)
            if wants_html:
                target_url = f"/apps/{_encoded_script_name(script.name)}"
                return HTMLResponse(
                    LAUNCHER_TEMPLATE.replace(
                        "{script_name}", html.escape(script.name)
                    )
                    .replace("{target_url}", target_url)
                    .replace("{has_ui}", "true"),
                    status_code=200,
                )
            raise HTTPException(status_code=503, detail=f"{script_name} is starting.")
        if script.last_start_attempt_at:
            if script.last_start_error or script.last_exit_reason:
                detail = {
                    "error": script.last_start_error or script.last_exit_reason,
                    "exit_code": script.last_exit_code,
                    "spawn_command": script.last_spawn_command,
                    "spawn_cwd": script.last_spawn_cwd,
                    "stdout_tail": script.logs(),
                }
                raise HTTPException(status_code=500, detail=detail)
            if script.name in WEB_APPS and wants_html:
                target_url = f"/apps/{_encoded_script_name(script.name)}"
                return HTMLResponse(
                    LAUNCHER_TEMPLATE.replace(
                        "{script_name}", html.escape(script.name)
                    )
                    .replace("{target_url}", target_url)
                    .replace("{has_ui}", "true"),
                    status_code=200,
                )
            raise HTTPException(
                status_code=503, detail=f"{script_name} is starting."
            )
        raise HTTPException(status_code=404, detail=f"{script_name} is not running.")

    if script.port is None:
        raise HTTPException(
            status_code=502,
            detail=f"Upstream port not available for script: {script.name}",
        )

    target = f"http://127.0.0.1:{script.port}/{path}"
    if request.url.query:
        target = f"{target}?{request.url.query}"

    headers = {k: v for k, v in request.headers.items() if k.lower() != "host"}
    headers["X-Forwarded-Prefix"] = f"/apps/{_encoded_script_name(script.name)}"
    body = await request.body()
    PROXY_LOGGER.info(
        "Proxying app request script=%s subpath=%s port=%s url=%s",
        script.name,
        path,
        script.port,
        target,
    )

    proxy_timeout_seconds = _app_proxy_timeout_seconds(
        script.name,
        path,
        request.method,
    )
    timeout = httpx.Timeout(proxy_timeout_seconds, connect=2.0)
    async with httpx.AsyncClient(follow_redirects=False, timeout=timeout) as client:
        resp = None
        start_time = time.monotonic()
        for attempt in range(2):
            try:
                resp = await client.request(
                    request.method,
                    target,
                    content=body,
                    headers=headers,
                )
                break
            except httpx.TimeoutException as exc:
                duration = time.monotonic() - start_time
                PROXY_LOGGER.warning(
                    "Proxy timeout script=%s subpath=%s port=%s url=%s duration=%.2fs error=%s",
                    script.name,
                    path,
                    script.port,
                    target,
                    duration,
                    exc,
                )
                raise HTTPException(
                    status_code=504,
                    detail={
                        "error": "Upstream timeout",
                        "script": script.name,
                        "port": script.port,
                        "url": target,
                    },
                ) from exc
            except httpx.RequestError as exc:
                duration = time.monotonic() - start_time
                PROXY_LOGGER.warning(
                    "Proxy request error script=%s subpath=%s port=%s url=%s duration=%.2fs error=%s",
                    script.name,
                    path,
                    script.port,
                    target,
                    duration,
                    exc,
                )
                if isinstance(exc, httpx.ConnectError) and attempt < 1:
                    await asyncio.sleep(0.2)
                    continue
                raise HTTPException(
                    status_code=502,
                    detail={
                        "error": "Upstream request failed",
                        "script": script.name,
                        "port": script.port,
                        "url": target,
                    },
                ) from exc

    assert resp is not None
    PROXY_LOGGER.info(
        "Proxy response script=%s subpath=%s port=%s status=%s",
        script.name,
        path,
        script.port,
        resp.status_code,
    )
    filtered_headers = {
        k: v
        for k, v in resp.headers.items()
        if k.lower() not in PROXY_HOP_HEADERS | PROXY_STRIP_HEADERS
    }
    if fx_previous_settings is not None and resp.status_code < 400:
        durability = await _persist_fxweekend_config_with_rollback(
            fx_previous_settings,
            fx_previous_status or {},
            timeout=10.0,
        )
        if durability.get("ok") is not True:
            return JSONResponse(
                durability,
                status_code=502,
            )
    return Response(
        content=resp.content,
        status_code=resp.status_code,
        headers=filtered_headers,
    )


