async def _background_start(script: ManagedScript) -> None:
    """Start a script without tying its output or failures to the HTTP response."""

    try:
        await script.start()
    except Exception as exc:  # pragma: no cover - runtime protection
        # Capture failures in the per-script log instead of surfacing them to the caller.
        script.add_log(f"Failed to start: {exc}")
    finally:
        if script.startup_task is asyncio.current_task():
            script.startup_task = None


async def _background_start_after_state_restore(script: ManagedScript) -> None:
    _managed_script_log(
        script,
        "FX Weekend start requested; waiting for authoritative state "
        "restoration and durability verification.",
    )
    AUTOSTART_LOGGER.info(
        "FX_WEEKEND_START_COORDINATION state=waiting_for_authoritative_restore"
    )
    await _STARTUP_STATE_RESTORE_DONE.wait()
    AUTOSTART_LOGGER.info(
        "FX_WEEKEND_START_COORDINATION state=restore_signal_received"
    )
    allowed, gate_error = _fxweekend_start_gate()
    if not allowed:
        _managed_script_log(
            script,
            f"FX Weekend executor was not started: {gate_error}",
        )
        script.last_start_error = gate_error
        AUTOSTART_LOGGER.error(
            "FX_WEEKEND_START_BLOCKED reason=%s",
            gate_error,
        )
        return
    await _background_start(script)


@app.get("/scripts")
async def list_scripts() -> JSONResponse:
    runtime_render = _runtime_is_render()
    raw = script_manager.list_scripts()
    if runtime_render:
        raw = [s for s in raw if str(s.get("name")) not in {"bybit_monitor", "oanda_monitor"}]
    by_name = {str(s.get("name")): s for s in raw}

    merged: List[Dict[str, object]] = []
    autostart_targets = set(_compute_autostart_scripts())

    for btn in get_merged_script_buttons():
        if runtime_render and btn.get("name") == "monitor":
            continue
        row: Dict[str, object] = {
            "id": btn["id"],
            "name": btn["name"],
            "label": btn["label"],
            "category": "Merged",
            "running": False,
            "starting": False,
            "open_url": btn["open_url"],
            "standalone": False,
            "dashboard_main_view": bool(btn.get("dashboard_main_view")),
        }
        if bool(btn.get("remote_owned")):
            row["remote_owned"] = True
        if APP_PROFILE == "local" and bool(btn.get("remote_owned")):
            configured = bool(_configured_render_tools_base_url())
            row.update(
                {
                    "starting": False,
                    "running": configured if btn["name"] == "fxweekend" else False,
                    "enabled": configured,
                    "operational": configured,
                    "autostart_expected": False,
                    "status_detail": (
                        "Render destination configured"
                        if configured
                        else "Render Trading Tools base URL is not configured"
                    ),
                }
            )
        elif btn["name"] == "history":
            row["starting"] = bool(
                by_name.get("bybithistory-clone", {}).get("starting")
                or by_name.get("oanda_history-clone", {}).get("starting")
                or by_name.get("coinspot-clone", {}).get("starting")
            )
            row["running"] = bool(
                by_name.get("bybithistory-clone", {}).get("running")
                or by_name.get("oanda_history-clone", {}).get("running")
                or by_name.get("coinspot-clone", {}).get("running")
            )
        elif btn["name"] == "bounce-trader":
            row["starting"] = bool(by_name.get("bybit_trigger_bounce_trader", {}).get("starting"))
            row["running"] = bool(by_name.get("bybit_trigger_bounce_trader", {}).get("running"))
        elif btn["name"] == "fxweekend":
            fx_row = by_name.get("fxweekend-clone", {})
            row["starting"] = bool(fx_row.get("starting"))
            row["running"] = bool(fx_row.get("running"))
            row["pid"] = fx_row.get("pid")
            row["last_error"] = fx_row.get("last_error")
            row["last_start_error"] = fx_row.get("last_start_error")
            row["last_exit_reason"] = fx_row.get("last_exit_reason")

            fx_component = _autostart_component_readiness(
                "fxweekend-clone",
                summary_override=fx_row,
            )
            fx_enabled = bool(fx_component.get("enabled", True))
            row["enabled"] = fx_enabled
            row["autostart_expected"] = "fxweekend-clone" in autostart_targets
            for key in (
                "phase",
                "reason",
                "heartbeat_at",
                "heartbeat_fresh",
                "heartbeat_timestamp_fresh",
                "heartbeat_pid_matches",
                "heartbeat_instance_matches",
                "heartbeat_age_seconds",
                "heartbeat_stale_after_seconds",
                "heartbeat_startup_grace_active",
                "heartbeat_startup_grace_remaining_seconds",
                "executor_pid",
                "executor_instance_id",
                "executor_started_at",
                "process_pid",
                "process_instance_id",
                "last_access_check_at",
                "last_verified_flat_at",
                "selected_accounts",
                "runtime_selected_accounts",
                "accounts",
                "credential_errors",
                "account_errors",
                "account_warnings",
                "missing_runtime_accounts",
                "pending_runtime_accounts",
                "health_state",
                "health_reason",
            ):
                if key in fx_component:
                    row[key] = fx_component[key]

            running = bool(row["running"])
            starting = bool(row["starting"])
            row["operational"] = bool(
                fx_enabled and fx_component.get("ready")
            )

            if not fx_enabled:
                detail = "disabled"
            elif starting:
                detail = "starting"
            elif row["operational"]:
                detail = (
                    str(row.get("health_reason") or "").strip()
                    if row.get("health_state") == "amber"
                    else "running and enabled"
                )
            elif fx_enabled and str(fx_component.get("reason") or "").strip():
                component_reason = str(fx_component.get("reason"))
                detail = (
                    component_reason
                    if running
                    else f"stopped: {component_reason}"
                )
            else:
                stop_reason = str(row.get("last_start_error") or row.get("last_exit_reason") or "").strip()
                detail = f"stopped: {stop_reason}" if stop_reason else "stopped"
            row["status_detail"] = detail
            if (
                not row["operational"]
                and not row.get("last_error")
                and str(fx_component.get("reason") or "").strip()
            ):
                row["last_error"] = str(fx_component.get("reason"))
        elif btn["name"] == "monitor":
            row.update(_merged_monitor_row(by_name, autostart_targets))
        elif str(btn["name"]) in by_name:
            source_row = by_name[str(btn["name"])]
            for key in (
                "starting",
                "running",
                "last_error",
                "last_start_error",
                "last_exit_reason",
                "last_spawn_command",
                "last_spawn_cwd",
            ):
                if key in source_row:
                    row[key] = source_row[key]
        merged.append(row)

    merged_source_names = get_merged_source_names()
    extras = [s for s in raw if str(s.get("name")) not in merged_source_names]
    extras = [s for s in extras if str(s.get("name")) not in {"bybit_monitor", "oanda_monitor"}]
    extras = [s for s in extras if str(s.get("name")) not in {"open-orders", "pine"}]
    for item in extras:
        if str(item.get("name")) == "ivindicator-clone":
            item["dashboard_main_view"] = True
    extras.sort(key=lambda s: str(s.get("label") or s.get("name")).lower())
    existing_names = {
        str(item.get("name") or "")
        for item in [*merged, *extras]
        if str(item.get("name") or "")
    }
    for target_name, reason in sorted(_LAST_AUTOSTART_UNAVAILABLE.items()):
        if target_name in existing_names:
            continue
        extras.append(
            {
                "id": target_name,
                "name": target_name,
                "label": friendly_script_label(target_name),
                "category": "Autostart",
                "running": False,
                "starting": False,
                "standalone": False,
                "autostart_expected": True,
                "operational": False,
                "status_detail": f"configured autostart target unavailable: {reason}",
                "last_start_error": reason,
            }
        )

    return JSONResponse(merged + extras)


