def _safe_float(value: object) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _side_key(value: object, *, broker: str) -> str:
    raw = str(value or "").strip().lower()
    if raw in {"buy", "long"}:
        return "buy"
    if raw in {"sell", "short"}:
        return "sell"
    if broker.lower() == "oanda":
        if raw == "long":
            return "buy"
        if raw == "short":
            return "sell"
    return raw


def _qty_matches(a: object, b: object) -> bool:
    a_num = _safe_float(a)
    b_num = _safe_float(b)
    if a_num is None or b_num is None:
        return str(a or "").strip() == str(b or "").strip()
    return abs(abs(a_num) - abs(b_num)) <= max(1e-9, abs(a_num), abs(b_num)) * 1e-6


PENDING_WEBHOOK_TERMINAL_STATUSES = {
    "TRIGGERING",
    "CONSUMED",
    "TRIGGERED",
    "SUBMITTED",
    "FILLED",
    "CLOSED",
    "CANCELLED",
    "CANCELED",
    "REJECTED",
    "EXPIRED",
    "DISABLED",
    "BYBIT_REJECTED",
    "OANDA_REJECTED",
    "FAILED",
    "FAILED_BEFORE_SUBMIT",
    "FAILED_AFTER_SUBMIT",
}


def _pending_webhook_is_terminal(status: object) -> bool:
    return str(status or "").strip().upper() in PENDING_WEBHOOK_TERMINAL_STATUSES


def _pending_webhook_sort_ts(item: Dict[str, object]) -> float:
    for key in ("updated_at", "created_at", "opened_at"):
        value = item.get(key)
        num = _safe_float(value)
        if num is not None:
            return float(num)
        dt = _parse_iso_datetime(value)
        if dt is not None:
            return dt.timestamp()
    return 0.0


def _pending_webhook_fingerprint(item: Dict[str, object]) -> str:
    meaningful_fields = (
        "account",
        "category",
        "instrument",
        "side",
        "size",
        "entry_price",
        "order_price",
        "order_type",
        "stop_loss",
        "take_profit",
        "timeframe",
        "is_test_trade",
        "cancel_if_touched_price",
        "cancel_if_touched_operator",
        "setup_reference_price",
        "risk_mode",
        "risk_value",
        "stop_loss_ticks",
        "take_profit_ticks",
        "target_mode",
        "risk_reward",
        "planned_entry_price",
        "planned_stop_price",
        "planned_target_price",
    )
    normalized: Dict[str, object] = {}
    for field in meaningful_fields:
        value = item.get(field)
        if isinstance(value, str):
            value = value.strip()
            if field in {"account", "category", "instrument", "side", "order_type", "timeframe", "cancel_if_touched_operator", "risk_mode", "target_mode"}:
                value = value.lower()
            if field == "instrument":
                value = value.upper()
        elif isinstance(value, (int, float)):
            value = float(value)
        normalized[field] = value
    return json.dumps(normalized, sort_keys=True, separators=(",", ":"), default=str)


def _pending_context_matches(item: Dict[str, object], ctx: Dict[str, object]) -> bool:
    pending_id = str(item.get("id") or "").strip()
    calculation_context_id = str(item.get("calculation_context_id") or item.get("context_id") or "").strip()
    if pending_id and str(ctx.get("pending_webhook_id") or "").strip() == pending_id:
        return True
    if calculation_context_id and str(ctx.get("calculation_context_id") or ctx.get("context_id") or "").strip() == calculation_context_id:
        return True
    return False


def _pending_context_lifecycle_reason(
    item: Dict[str, object],
    trade_contexts: List[Dict[str, object]],
    *,
    prune_orphan_contexts: bool = True,
) -> Optional[str]:
    matching = [ctx for ctx in trade_contexts if isinstance(ctx, dict) and _pending_context_matches(item, ctx)]
    if not matching:
        if prune_orphan_contexts and str(item.get("calculation_context_id") or item.get("context_id") or "").strip():
            return "orphaned calculation context"
        return None
    has_active = False
    terminal_reasons: List[str] = []
    for ctx in matching:
        status = str(ctx.get("status") or "ACTIVE").strip().upper()
        if status == "ACTIVE":
            has_active = True
            continue
        if _pending_webhook_is_terminal(status) or status in {"CANCELLED", "CANCELED", "CLOSED", "CONSUMED", "TRIGGERED", "REJECTED", "EXPIRED"}:
            terminal_reasons.append(status)
            continue
        if ctx.get("closed_at") or ctx.get("consumed_at") or ctx.get("triggered_at") or ctx.get("cancelled_at"):
            terminal_reasons.append(status or "terminal context timestamp")
    if has_active:
        return None
    if terminal_reasons:
        return f"terminal trade context: {terminal_reasons[-1]}"
    return None


def _pending_superseded_ids(pending_items: List[Dict[str, object]]) -> Set[str]:
    superseded: Set[str] = set()
    fields = (
        "previous_pending_webhook_id",
        "superseded_pending_webhook_id",
        "supersedes_pending_webhook_id",
        "replaces_pending_webhook_id",
    )
    for item in pending_items:
        if not isinstance(item, dict):
            continue
        for field in fields:
            value = str(item.get(field) or "").strip()
            if value:
                superseded.add(value)
    return superseded


def _choose_active_pending_webhook(left: Dict[str, object], right: Dict[str, object]) -> Dict[str, object]:
    left_active = (
        str(left.get("status") or "").strip().upper() == "WAITING"
        and bool(left.get("enabled", True))
        and not (left.get("consumed_at") or left.get("triggered_at"))
    )
    right_active = (
        str(right.get("status") or "").strip().upper() == "WAITING"
        and bool(right.get("enabled", True))
        and not (right.get("consumed_at") or right.get("triggered_at"))
    )
    if left_active != right_active:
        return left if left_active else right
    return right if _pending_webhook_sort_ts(right) >= _pending_webhook_sort_ts(left) else left


def _pending_webhook_is_superseded(
    pending: Dict[str, object],
    open_items: List[Dict[str, object]],
    trade_contexts: Optional[List[Dict[str, object]]] = None,
    consumed_open_indices: Optional[Set[int]] = None,
) -> bool:
    pending_id = str(pending.get("id", "")).strip()
    pending_broker = str(pending.get("broker", "")).strip().lower()
    pending_category = str(pending.get("category", "")).strip().lower()
    pending_account = str(pending.get("account", "")).strip().lower()
    pending_order_id = str(pending.get("order_id", "")).strip()
    pending_order_link_id = str(pending.get("order_link_id", "")).strip()
    pending_trade_id = str(pending.get("trade_id", "")).strip()
    pending_instrument = str(pending.get("instrument", "")).strip().upper()
    pending_side = _side_key(pending.get("side"), broker=str(pending.get("broker", "")))
    pending_size = pending.get("size")
    contexts = trade_contexts if isinstance(trade_contexts, list) else _load_trade_contexts()

    exact_order_ids: Set[str] = set()
    exact_order_link_ids: Set[str] = set()
    exact_trade_ids: Set[str] = set()
    if pending_order_id:
        exact_order_ids.add(pending_order_id)
    if pending_order_link_id:
        exact_order_link_ids.add(pending_order_link_id)
    if pending_trade_id:
        exact_trade_ids.add(pending_trade_id)
    for ctx in contexts:
        if not isinstance(ctx, dict):
            continue
        if pending_id and str(ctx.get("pending_webhook_id") or "").strip() != pending_id:
            continue
        ctx_order_id = str(ctx.get("order_id") or "").strip()
        ctx_order_link_id = str(ctx.get("order_link_id") or "").strip()
        ctx_parent_order_link_id = str(ctx.get("parent_order_link_id") or "").strip()
        ctx_trade_id = str(ctx.get("trade_id") or "").strip()
        if ctx_order_id:
            exact_order_ids.add(ctx_order_id)
        if ctx_order_link_id:
            exact_order_link_ids.add(ctx_order_link_id)
        if ctx_parent_order_link_id:
            exact_order_link_ids.add(ctx_parent_order_link_id)
        if ctx_trade_id:
            exact_trade_ids.add(ctx_trade_id)
    has_exact_linkage = bool(exact_order_ids or exact_order_link_ids or exact_trade_ids)

    for idx, item in enumerate(open_items):
        if consumed_open_indices and idx in consumed_open_indices:
            continue
        if str(item.get("broker", "")).strip().upper() == "WEBHOOK":
            continue

        open_id = str(item.get("id") or "").strip()
        open_order_link_id = str(item.get("order_link_id") or "").strip()
        open_trade_id = str(item.get("trade_id") or "").strip()
        if open_id and open_id in exact_order_ids:
            if consumed_open_indices is not None:
                consumed_open_indices.add(idx)
            return True
        if open_order_link_id and open_order_link_id in exact_order_link_ids:
            if consumed_open_indices is not None:
                consumed_open_indices.add(idx)
            return True
        if open_trade_id and open_trade_id in exact_trade_ids:
            if consumed_open_indices is not None:
                consumed_open_indices.add(idx)
            return True

    if has_exact_linkage:
        return False

    matching_indices: List[int] = []
    pending_family = "oanda" if pending_broker == "oanda" or pending_category == "forex" else "bybit"
    for idx, item in enumerate(open_items):
        if consumed_open_indices and idx in consumed_open_indices:
            continue
        item_broker = str(item.get("broker") or "").strip().lower()
        if item_broker == "webhook":
            continue
        item_category = str(item.get("category") or "").strip().lower()
        item_family = "oanda" if item_broker == "oanda" or item_category == "forex" else "bybit"
        if item_family != pending_family:
            continue
        if pending_account and str(item.get("account") or "").strip().lower() != pending_account:
            continue
        instrument = str(item.get("instrument", "")).strip().upper()
        side = _side_key(item.get("side"), broker=str(item.get("broker", "")))
        size = item.get("size")
        if (
            pending_instrument
            and instrument == pending_instrument
            and side
            and side == pending_side
            and _qty_matches(pending_size, size)
        ):
            matching_indices.append(idx)

    if len(matching_indices) == 1:
        if consumed_open_indices is not None:
            consumed_open_indices.add(matching_indices[0])
        return True
    return False


def _clean_pending_webhooks_for_open_items(
    pending_items: List[Dict[str, object]],
    open_items: List[Dict[str, object]],
    diagnostics: Optional[Dict[str, int]] = None,
    *,
    prune_orphan_contexts: bool = True,
) -> Tuple[List[Dict[str, object]], bool]:
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    diagnostics.setdefault("input_records", len(pending_items))
    contexts = _load_trade_contexts()
    consumed_open_indices: Set[int] = set()
    active_candidates: List[Dict[str, object]] = []
    changed = False
    visible_statuses = {"WAITING"}
    superseded_ids = _pending_superseded_ids(pending_items)
    for pending in pending_items:
        pending_id = str(pending.get("id") or "").strip()
        status = str(pending.get("status") or "").strip().upper()
        if pending_id and pending_id in superseded_ids:
            diagnostics["superseded_pruned"] = int(diagnostics.get("superseded_pruned", 0)) + 1
            changed = True
            continue
        if _pending_webhook_is_terminal(status):
            diagnostics["terminal_pruned"] = int(diagnostics.get("terminal_pruned", 0)) + 1
            changed = True
            continue
        if status not in visible_statuses:
            diagnostics["non_waiting_pruned"] = int(diagnostics.get("non_waiting_pruned", 0)) + 1
            changed = True
            continue
        if not bool(pending.get("enabled", True)):
            diagnostics["disabled_pruned"] = int(diagnostics.get("disabled_pruned", 0)) + 1
            changed = True
            continue
        if status == "WAITING" and (pending.get("consumed_at") or pending.get("triggered_at")):
            diagnostics["consumed_waiting_pruned"] = int(diagnostics.get("consumed_waiting_pruned", 0)) + 1
            changed = True
            continue
        lifecycle_reason = _pending_context_lifecycle_reason(
            pending,
            contexts,
            prune_orphan_contexts=prune_orphan_contexts,
        )
        if lifecycle_reason:
            diagnostics["stale_context_pruned"] = int(diagnostics.get("stale_context_pruned", 0)) + 1
            changed = True
            continue
        active_candidates.append(pending)

    deduped_by_id: Dict[str, Dict[str, object]] = {}
    no_id_items: List[Dict[str, object]] = []
    for pending in active_candidates:
        pending_id = str(pending.get("id") or "").strip()
        if not pending_id:
            no_id_items.append(pending)
            continue
        previous = deduped_by_id.get(pending_id)
        if previous is None:
            deduped_by_id[pending_id] = pending
            continue
        deduped_by_id[pending_id] = _choose_active_pending_webhook(previous, pending)
        diagnostics["duplicate_id_pruned"] = int(diagnostics.get("duplicate_id_pruned", 0)) + 1
        changed = True

    by_fingerprint: Dict[str, Dict[str, object]] = {}
    for pending in no_id_items:
        fingerprint = _pending_webhook_fingerprint(pending)
        previous = by_fingerprint.get(fingerprint)
        if previous is None:
            by_fingerprint[fingerprint] = pending
            continue
        by_fingerprint[fingerprint] = _choose_active_pending_webhook(previous, pending)
        diagnostics["duplicate_fingerprint_pruned"] = int(diagnostics.get("duplicate_fingerprint_pruned", 0)) + 1
        changed = True

    filtered: List[Dict[str, object]] = []
    for pending in sorted([*deduped_by_id.values(), *by_fingerprint.values()], key=_pending_webhook_sort_ts):
        if _pending_webhook_is_superseded(
            pending,
            open_items,
            trade_contexts=contexts,
            consumed_open_indices=consumed_open_indices,
        ):
            diagnostics["live_broker_superseded_pruned"] = int(diagnostics.get("live_broker_superseded_pruned", 0)) + 1
            changed = True
            continue
        filtered.append(pending)
    diagnostics["active_records"] = len(filtered)
    return filtered, changed


def _reconcile_pending_webhooks_registry(
    open_items: Optional[List[Dict[str, object]]] = None,
    *,
    prune_orphan_contexts: bool = True,
    invalidate_cache: bool = True,
) -> Tuple[List[Dict[str, object]], Dict[str, int]]:
    diagnostics: Dict[str, int] = {}
    pending_items = _load_pending_webhooks()
    cleaned, changed = _clean_pending_webhooks_for_open_items(
        pending_items,
        open_items or [],
        diagnostics=diagnostics,
        prune_orphan_contexts=prune_orphan_contexts,
    )
    if changed:
        _save_pending_webhooks(cleaned)
        if invalidate_cache:
            _invalidate_open_orders_cache()
    return cleaned, diagnostics


def _filter_pending_webhooks(
    pending_items: List[Dict[str, object]], open_items: List[Dict[str, object]]
) -> List[Dict[str, object]]:
    filtered, _changed = _clean_pending_webhooks_for_open_items(pending_items, open_items)
    return filtered


@app.get("/api/open-orders/version")
async def open_orders_version() -> JSONResponse:
    if APP_PROFILE == "render":
        return _local_only_disabled_response("/api/open-orders/version", as_json=True)  # type: ignore[return-value]
    return JSONResponse(
        {
            "version": int(_OPEN_ORDERS_CACHE.get("version") or 0),
            "updated_at": _utc_now_iso(),
        }
    )


@app.get("/api/open-orders")
async def list_open_orders(force: bool = Query(False)) -> JSONResponse:
    if APP_PROFILE == "render":
        return _local_only_disabled_response("/api/open-orders", as_json=True)  # type: ignore[return-value]
    now = time.time()
    cached_payload = _OPEN_ORDERS_CACHE.get("payload")
    expires_at = float(_OPEN_ORDERS_CACHE.get("expires_at") or 0.0)
    if not force and isinstance(cached_payload, dict) and now < expires_at:
        fresh = dict(cached_payload)
        fresh["stale"] = bool(fresh.get("errors"))
        fresh.setdefault("updated_at", _utc_now_iso())
        fresh.setdefault("last_success_at", _OPEN_ORDERS_CACHE.get("last_success_at"))
        fresh["error_count"] = len(fresh.get("errors") or [])
        fresh["warning_count"] = len(fresh.get("warnings") or [])
        return JSONResponse(fresh)

    async with _OPEN_ORDERS_CACHE_LOCK:
        now = time.time()
        cached_payload = _OPEN_ORDERS_CACHE.get("payload")
        expires_at = float(_OPEN_ORDERS_CACHE.get("expires_at") or 0.0)
        if not force and isinstance(cached_payload, dict) and now < expires_at:
            fresh = dict(cached_payload)
            fresh["stale"] = bool(fresh.get("errors"))
            fresh.setdefault("updated_at", _utc_now_iso())
            fresh.setdefault("last_success_at", _OPEN_ORDERS_CACHE.get("last_success_at"))
            fresh["error_count"] = len(fresh.get("errors") or [])
            fresh["warning_count"] = len(fresh.get("warnings") or [])
            return JSONResponse(fresh)

        # This version describes the state for which this broker read began. If
        # another durable transition invalidates the cache while reads are in
        # flight, the returned payload keeps this older version and is not
        # cached. The browser will observe the newer version and render again.
        collection_version = int(_OPEN_ORDERS_CACHE.get("version") or 0)
        items: List[Dict[str, object]] = []
        errors: List[Dict[str, str]] = []
        warnings: List[Dict[str, str]] = []

        for account in ("live", "demo"):
            try:
                cfg = _get_oanda_config(account)
                account_ids: List[str] = []
                configured_account_id = str(cfg.get("account_id") or "").strip()
                if configured_account_id:
                    account_ids.append(configured_account_id)

                owned_accounts: List[Dict[str, object]] = []
                account_tags: Dict[str, List[str]] = {}
                discovery_exc: Optional[Exception] = None
                stale_discovery_fetched_at: Optional[float] = None
                try:
                    discovery_result = await _get_cached_oanda_accounts(
                        base_url=cfg["base_url"],
                        api_key=cfg["token"],
                    )
                    if isinstance(discovery_result, OandaAccountDiscoveryResult):
                        owned_accounts = list(discovery_result.accounts)
                        discovery_exc = discovery_result.discovery_error
                        if discovery_result.cache_state == "stale":
                            stale_discovery_fetched_at = discovery_result.fetched_at
                    else:
                        # Preserve compatibility with local test or extension shims that
                        # returned the pre-metadata list shape.
                        owned_accounts = list(discovery_result or [])
                except Exception as exc:
                    discovery_exc = exc

                for acct in owned_accounts:
                    acct_id = str(acct.get("id") or "").strip()
                    if not acct_id:
                        continue
                    account_ids.append(acct_id)
                    account_tags[acct_id] = [str(t).upper() for t in (acct.get("tags") or [])]

                deduped_ids: List[str] = []
                seen_account_ids: Set[str] = set()
                for acct_id in account_ids:
                    if acct_id in seen_account_ids:
                        continue
                    deduped_ids.append(acct_id)
                    seen_account_ids.add(acct_id)
                account_ids = deduped_ids
                if not account_ids:
                    raise ValueError(
                        f"No configured or discovered OANDA account IDs are available for {account}."
                    )

                tasks = [
                    _collect_oanda_open_items(
                        base_url=cfg["base_url"],
                        account_id=acct_id,
                        api_key=cfg["token"],
                        account_context=account,
                    )
                    for acct_id in account_ids
                ]
                results = await asyncio.gather(*tasks, return_exceptions=True)

                oanda_items: List[Dict[str, object]] = []
                oanda_errors: List[Dict[str, str]] = []
                account_error_counts: Dict[str, int] = {}
                refreshed_account_ids: Set[str] = set()
                for acct_id, result in zip(account_ids, results):
                    if isinstance(result, Exception):
                        account_error_counts[acct_id] = (
                            account_error_counts.get(acct_id, 0) + 1
                        )
                        oanda_errors.append(
                            {
                                "broker": "OANDA",
                                "account": account,
                                "category": "forex",
                                "source_type": "account data",
                                "endpoint": "/v3/accounts/{accountID}/openItems",
                                "account_id": acct_id,
                                "message": _format_source_exception(
                                    result,
                                    broker="OANDA",
                                    account=account,
                                    endpoint="/v3/accounts/{accountID}/openItems",
                                    account_id=acct_id,
                                ),
                            }
                        )
                        continue

                    if not isinstance(result, dict) or not {
                        "items",
                        "errors",
                    }.issubset(result):
                        account_error_counts[acct_id] = (
                            account_error_counts.get(acct_id, 0) + 1
                        )
                        oanda_errors.append(
                            {
                                "broker": "OANDA",
                                "account": account,
                                "category": "forex",
                                "source_type": "account data",
                                "endpoint": "/v3/accounts/{accountID}/openItems",
                                "account_id": acct_id,
                                "message": (
                                    "OANDA account refresh returned an invalid result "
                                    f"for {account}/{acct_id}"
                                ),
                            }
                        )
                        continue

                    refreshed_account_ids.add(acct_id)
                    result_items = result.get("items", [])
                    result_errors = result.get("errors", [])

                    for endpoint_error in result_errors:
                        account_error_counts[acct_id] = (
                            account_error_counts.get(acct_id, 0) + 1
                        )
                        if isinstance(endpoint_error, dict):
                            endpoint = str(
                                endpoint_error.get("endpoint")
                                or "/v3/accounts/{accountID}/openItems"
                            )
                            message = str(
                                endpoint_error.get("message")
                                or "Unknown OANDA endpoint error"
                            ).strip()
                        else:
                            endpoint = "/v3/accounts/{accountID}/openItems"
                            message = (
                                f"{acct_id}: "
                                f"{str(endpoint_error).strip() or 'Unknown OANDA endpoint error'}"
                            )
                        oanda_errors.append(
                            {
                                "broker": "OANDA",
                                "account": account,
                                "category": "forex",
                                "source_type": "account data",
                                "endpoint": endpoint,
                                "account_id": acct_id,
                                "message": message,
                            }
                        )

                    tags = account_tags.get(acct_id, [])
                    for row in result_items:
                        row["account_id"] = acct_id
                        if "MT4" in tags:
                            row["account_label_suffix"] = "MT4"
                    oanda_items.extend(result_items)

                items.extend(oanda_items)
                errors.extend(oanda_errors)
                configured_account_refreshed = bool(
                    configured_account_id
                    and configured_account_id in refreshed_account_ids
                    and account_error_counts.get(configured_account_id, 0) == 0
                )
                if configured_account_refreshed and _oanda_discovery_is_http_401(discovery_exc):
                    BYBIT_LOGGER.warning(
                        "OANDA_DISCOVERY_AUTH_ANOMALY mode=%s configured_account=%s "
                        "configured_endpoints_ok=true retry_delay=%.2fs",
                        account,
                        configured_account_id,
                        _OANDA_DISCOVERY_AUTH_ANOMALY_RETRY_DELAY_SECONDS,
                    )
                    await asyncio.sleep(_OANDA_DISCOVERY_AUTH_ANOMALY_RETRY_DELAY_SECONDS)
                    retry_owned_accounts: List[Dict[str, object]] = []
                    try:
                        retry_discovery = await _get_cached_oanda_accounts(
                            base_url=cfg["base_url"],
                            api_key=cfg["token"],
                            allow_auth_anomaly_stale=True,
                        )
                        if isinstance(retry_discovery, OandaAccountDiscoveryResult):
                            retry_owned_accounts = list(retry_discovery.accounts)
                            discovery_exc = retry_discovery.discovery_error
                            stale_discovery_fetched_at = (
                                retry_discovery.fetched_at
                                if retry_discovery.cache_state == "stale"
                                else None
                            )
                        else:
                            retry_owned_accounts = list(retry_discovery or [])
                            discovery_exc = None
                            stale_discovery_fetched_at = None
                    except Exception as retry_exc:
                        discovery_exc = retry_exc
                        stale_discovery_fetched_at = None

                    if discovery_exc is None:
                        BYBIT_LOGGER.info(
                            "OANDA_DISCOVERY_AUTH_ANOMALY_RECOVERED mode=%s configured_account=%s",
                            account,
                            configured_account_id,
                        )

                    retry_account_ids: List[str] = []
                    for acct in retry_owned_accounts:
                        acct_id = str(acct.get("id") or "").strip()
                        if not acct_id or acct_id in seen_account_ids:
                            continue
                        seen_account_ids.add(acct_id)
                        account_ids.append(acct_id)
                        retry_account_ids.append(acct_id)
                        account_tags[acct_id] = [
                            str(tag).upper() for tag in (acct.get("tags") or [])
                        ]

                    if retry_account_ids:
                        retry_tasks = [
                            _collect_oanda_open_items(
                                base_url=cfg["base_url"],
                                account_id=acct_id,
                                api_key=cfg["token"],
                                account_context=account,
                            )
                            for acct_id in retry_account_ids
                        ]
                        retry_results = await asyncio.gather(
                            *retry_tasks, return_exceptions=True
                        )
                        retry_items: List[Dict[str, object]] = []
                        retry_errors: List[Dict[str, str]] = []
                        for acct_id, retry_result in zip(retry_account_ids, retry_results):
                            if isinstance(retry_result, Exception):
                                retry_errors.append(
                                    {
                                        "broker": "OANDA",
                                        "account": account,
                                        "category": "forex",
                                        "source_type": "account data",
                                        "endpoint": "/v3/accounts/{accountID}/openItems",
                                        "account_id": acct_id,
                                        "message": _format_source_exception(
                                            retry_result,
                                            broker="OANDA",
                                            account=account,
                                            endpoint="/v3/accounts/{accountID}/openItems",
                                            account_id=acct_id,
                                        ),
                                    }
                                )
                                continue
                            if not isinstance(retry_result, dict):
                                retry_errors.append(
                                    {
                                        "broker": "OANDA",
                                        "account": account,
                                        "category": "forex",
                                        "source_type": "account data",
                                        "endpoint": "/v3/accounts/{accountID}/openItems",
                                        "account_id": acct_id,
                                        "message": "OANDA account refresh returned an invalid result after discovery retry.",
                                    }
                                )
                                continue
                            result_endpoint_errors = retry_result.get("errors") or []
                            for endpoint_error in result_endpoint_errors:
                                endpoint_error = endpoint_error if isinstance(endpoint_error, dict) else {"message": endpoint_error}
                                retry_errors.append(
                                    {
                                        "broker": "OANDA",
                                        "account": account,
                                        "category": "forex",
                                        "source_type": "account data",
                                        "endpoint": str(endpoint_error.get("endpoint") or "/v3/accounts/{accountID}/openItems"),
                                        "account_id": acct_id,
                                        "message": str(endpoint_error.get("message") or "Unknown OANDA endpoint error"),
                                    }
                                )
                            tags = account_tags.get(acct_id, [])
                            for row in retry_result.get("items") or []:
                                if not isinstance(row, dict):
                                    continue
                                row["account_id"] = acct_id
                                if "MT4" in tags:
                                    row["account_label_suffix"] = "MT4"
                                retry_items.append(row)
                        oanda_items.extend(retry_items)
                        oanda_errors.extend(retry_errors)
                        items.extend(retry_items)
                        errors.extend(retry_errors)

                if discovery_exc is not None:
                    warnings.append(
                        _oanda_discovery_warning(
                            account=account,
                            exc=discovery_exc,
                            stale_fetched_at=stale_discovery_fetched_at,
                            configured_account_refreshed=configured_account_refreshed,
                        )
                    )
                BYBIT_LOGGER.info(
                    "OPEN_ORDERS oanda account=%s owner_accounts=%s items=%s errors=%s "
                    "discovery_warning=%s discovery_cache=%s",
                    account,
                    len(account_ids),
                    len(oanda_items),
                    len(oanda_errors),
                    discovery_exc is not None,
                    "stale" if stale_discovery_fetched_at is not None else "current",
                )
            except Exception as exc:
                errors.append(
                    {
                        "broker": "OANDA",
                        "account": account,
                        "category": "forex",
                        "message": _format_source_exception(
                            exc,
                            broker="OANDA",
                            account=account,
                            endpoint="open-orders",
                            account_id="unknown",
                        ),
                    }
                )

        for account in ("live", "demo"):
            api_key = ""
            api_secret = ""
            try:
                _mode, api_key, api_secret, base_url, _key_source = resolve_bybit_credentials_for(
                    account
                )
                if not api_key or not api_secret:
                    raise ValueError("Bybit API credentials are not configured.")
                result = await _collect_bybit_open_items(
                    base_url=base_url,
                    api_key=api_key,
                    api_secret=api_secret,
                    account_context=account,
                    key_source=_key_source,
                )
                result_items = [
                    dict(row)
                    for row in (result.get("items", []) or [])
                    if isinstance(row, dict)
                ]
                result_errors = [
                    dict(row)
                    for row in (result.get("errors", []) or [])
                    if isinstance(row, dict)
                ]
                source_key = f"bybit:{account}"
                if bool(result.get("auth_failed")):
                    stale_items = [
                        dict(row)
                        for row in _OPEN_ORDERS_LAST_GOOD_ITEMS.get(source_key, [])
                        if isinstance(row, dict)
                    ]
                    for row in stale_items:
                        row["source_stale"] = True
                        row["stale_reason"] = (
                            "Bybit authentication failed; showing last-known-good broker state."
                        )
                    items.extend(stale_items)
                else:
                    items.extend(result_items)
                    if not result_errors:
                        _OPEN_ORDERS_LAST_GOOD_ITEMS[source_key] = [
                            dict(row) for row in result_items
                        ]
                errors.extend(result_errors)
                BYBIT_LOGGER.info(
                    "OPEN_ORDERS bybit account=%s items=%s errors=%s auth_failed=%s",
                    account,
                    len(result_items),
                    len(result_errors),
                    bool(result.get("auth_failed")),
                )
            except Exception as exc:
                source_error = _bybit_open_source_error(
                    exc,
                    account=account,
                    category="account",
                    source_type=(
                        "credential readiness"
                        if isinstance(exc, BybitCredentialConflictError)
                        else "collection"
                    ),
                    endpoint="open-orders collection",
                    settlement_coin="n/a",
                    api_key=api_key,
                    api_secret=api_secret,
                )
                if isinstance(exc, BybitCredentialConflictError):
                    source_error.update(
                        {
                            "auth_failure": "true",
                            "auth_classification": "credential_source_conflict",
                            "credential_source": "CONFLICT",
                            "pair_complete": "false",
                        }
                    )
                errors.append(source_error)
                stale_items = [
                    dict(row)
                    for row in _OPEN_ORDERS_LAST_GOOD_ITEMS.get(f"bybit:{account}", [])
                    if isinstance(row, dict)
                ]
                for row in stale_items:
                    row["source_stale"] = True
                    row["stale_reason"] = (
                        "Bybit authentication/configuration failed; showing last-known-good broker state."
                    )
                items.extend(stale_items)

        live_broker_items = list(items)
        pending_diagnostics: Dict[str, int] = {}
        pending = _load_pending_webhooks()
        if pending:
            pending, pending_changed = _clean_pending_webhooks_for_open_items(
                pending, items, diagnostics=pending_diagnostics
            )
            if pending_changed:
                _save_pending_webhooks(pending)
                _invalidate_open_orders_cache()
                _schedule_dropbox_upload_state_backup()
        else:
            pending_diagnostics["input_records"] = 0
            pending_diagnostics["active_records"] = 0

        live_broker_positions = sum(
            1
            for row in live_broker_items
            if str(row.get("broker") or "").strip().lower() not in {"webhook", "bounce"}
            and str(row.get("type") or "").strip().lower() in {"position", "trade"}
        )
        live_broker_orders = sum(
            1
            for row in live_broker_items
            if str(row.get("broker") or "").strip().lower() not in {"webhook", "bounce"}
            and str(row.get("type") or "").strip().lower() == "order"
        )
        pruned_pending = sum(
            int(value)
            for key, value in pending_diagnostics.items()
            if key.endswith("_pruned")
        )
        source_counts = {
            "live_broker_positions": live_broker_positions,
            "live_broker_orders": live_broker_orders,
            "active_pending_webhooks": len(pending),
            "duplicates_or_stale_pending_pruned": pruned_pending,
            "pending_reconciliation": dict(pending_diagnostics),
            "errors": len(errors),
            "warnings": len(warnings),
        }
        BYBIT_LOGGER.info(
            "OPEN_ORDERS source_counts live_positions=%s live_orders=%s active_pending=%s "
            "pruned_pending=%s diagnostics=%s errors=%s warnings=%s",
            live_broker_positions,
            live_broker_orders,
            len(pending),
            pruned_pending,
            pending_diagnostics,
            len(errors),
            len(warnings),
        )

        try:
            bounce_script_running = script_manager.get("bybit_trigger_bounce_trader").is_running
        except Exception:
            bounce_script_running = False

        if bounce_script_running:
            sessions = _load_bounce_traders()
            changed = False
            now_dt = datetime.now(timezone.utc)

            bybit_orders = [
                row
                for row in items
                if str(row.get("broker", "")).strip().lower() == "bybit"
                and str(row.get("type", "")).strip().lower() == "order"
            ]
            bybit_positions = [
                row
                for row in items
                if str(row.get("broker", "")).strip().lower() == "bybit"
                and str(row.get("type", "")).strip().lower() == "position"
            ]
            oanda_orders = [
                row
                for row in items
                if str(row.get("broker", "")).strip().lower() == "oanda"
                and str(row.get("type", "")).strip().lower() == "order"
            ]
            oanda_positions = [
                row
                for row in items
                if str(row.get("broker", "")).strip().lower() == "oanda"
                and str(row.get("type", "")).strip().lower() in {"position", "trade"}
            ]

            for session in sessions:
                if not bool(session.get("running")):
                    continue

                broker = str(session.get("broker") or "").strip().lower()
                market = str(session.get("market") or "").strip().lower()
                if broker not in {"bybit", "oanda"}:
                    broker = "oanda" if market == "fx" else "bybit"

                instrument = str(session.get("instrument") or "").strip().upper()
                side = str(session.get("side") or "").strip().title()
                account = str(session.get("account") or "").strip().lower() or "demo"
                category = str(session.get("category") or "").strip().lower() or ("forex" if broker == "oanda" else "linear")
                order_link_id = str(session.get("order_link_id") or "").strip()

                seen_order = bool(session.get("seen_order"))
                if broker == "bybit":
                    if order_link_id:
                        if any(
                            str(row.get("order_link_id") or "").strip() == order_link_id
                            and str(row.get("account") or "").strip().lower() == account
                            and str(row.get("category") or "").strip().lower() == category
                            for row in bybit_orders
                        ) and not seen_order:
                            session["seen_order"] = True
                            changed = True
                            seen_order = True

                    has_position = any(
                        str(row.get("instrument") or "").strip().upper() == instrument
                        and str(row.get("side") or "").strip().title() == side
                        and str(row.get("account") or "").strip().lower() == account
                        and str(row.get("category") or "").strip().lower() == category
                        for row in bybit_positions
                    )
                else:
                    if any(
                        str(row.get("instrument") or "").strip().upper() == instrument
                        and str(row.get("account") or "").strip().lower() == account
                        for row in oanda_orders
                    ) and not seen_order:
                        session["seen_order"] = True
                        changed = True
                        seen_order = True

                    target_side = "Long" if side == "Buy" else "Short"
                    has_position = any(
                        str(row.get("instrument") or "").strip().upper() == instrument
                        and str(row.get("account") or "").strip().lower() == account
                        and str(row.get("side") or "").strip().title() == target_side
                        for row in oanda_positions
                    )

                started_at = _to_dt_utc(session.get("started_at"))
                age_seconds = (now_dt - started_at).total_seconds() if started_at else 0.0

                if has_position and (seen_order or age_seconds >= 30):
                    if bool(session.get("show_in_open_orders", True)):
                        session["show_in_open_orders"] = False
                        session["status"] = "filled"
                        session["updated_at"] = now_dt.isoformat()
                        changed = True
                    continue

                if not bool(session.get("show_in_open_orders", True)):
                    continue

                # Bounce sessions are reconciled internally; this endpoint only exposes broker rows.
                continue

            if changed:
                _save_bounce_traders(sessions)

        def _same_price(a: object, b: object, tol: float = 1e-9) -> bool:
            try:
                return abs(float(a) - float(b)) <= tol
            except (TypeError, ValueError):
                return False

        def _is_child_exit_order(parent: Dict[str, object], child: Dict[str, object]) -> bool:
            if str(parent.get("broker", "")).strip().lower() != "bybit":
                return False
            if str(parent.get("type", "")).strip().lower() != "position":
                return False
            if str(child.get("type", "")).strip().lower() != "order":
                return False
            if str(child.get("broker", "")).strip().lower() != "bybit":
                return False
            if str(parent.get("account", "")).strip().lower() != str(child.get("account", "")).strip().lower():
                return False
            if str(parent.get("category", "")).strip().lower() != str(child.get("category", "")).strip().lower():
                return False
            if str(parent.get("instrument", "")).strip().upper() != str(child.get("instrument", "")).strip().upper():
                return False

            child_status = str(child.get("status", "")).strip().upper()
            if child_status not in {"UNTRIGGERED", "OPEN", "NEW", "CREATED"}:
                return False

            parent_side = str(parent.get("side", "")).strip().lower()
            child_side = str(child.get("side", "")).strip().lower()
            if parent_side in {"buy", "long"} and child_side not in {"sell", "short"}:
                return False
            if parent_side in {"sell", "short"} and child_side not in {"buy", "long"}:
                return False

            child_price = child.get("current_price") or child.get("order_price")
            return (
                _same_price(child_price, parent.get("stop_loss"))
                or _same_price(child_price, parent.get("take_profit"))
            )

        grouped: List[Dict[str, object]] = []
        used_child_indices: Set[int] = set()

        for _parent_idx, item in enumerate(items):
            if str(item.get("type", "")).strip().lower() != "position":
                continue
            parent = dict(item)
            parent["children"] = []
            for child_idx, child in enumerate(items):
                if child_idx in used_child_indices:
                    continue
                if _is_child_exit_order(parent, child):
                    parent["children"].append(dict(child))
                    used_child_indices.add(child_idx)
            grouped.append(parent)

        for idx, item in enumerate(items):
            if idx in used_child_indices:
                continue
            if str(item.get("type", "")).strip().lower() == "position":
                continue
            row = dict(item)
            row["children"] = []
            grouped.append(row)

        updated_at = _utc_now_iso()
        payload: Dict[str, object] = {
            "items": grouped,
            "errors": errors,
            "warnings": warnings,
            "error_count": len(errors),
            "warning_count": len(warnings),
            "source_counts": source_counts,
            "stale": bool(errors),
            "updated_at": updated_at,
            "last_success_at": _OPEN_ORDERS_CACHE.get("last_success_at"),
            "version": collection_version,
        }

        version_unchanged = int(_OPEN_ORDERS_CACHE.get("version") or 0) == collection_version
        payload["refresh_superseded"] = not version_unchanged
        if version_unchanged:
            _OPEN_ORDERS_CACHE["payload"] = dict(payload)
            _OPEN_ORDERS_CACHE["expires_at"] = time.time() + _OPEN_ORDERS_CACHE_TTL_SECONDS
        if not errors and version_unchanged:
            _OPEN_ORDERS_CACHE["last_success_at"] = updated_at
            payload["last_success_at"] = updated_at

        return JSONResponse(payload)


@app.get("/api/recent-trades")
async def recent_trades(limit: int = 25) -> JSONResponse:
    _repair_persisted_oanda_trade_rows()
    _repair_persisted_bybit_trade_context_fields()
    repaired_open_rows, repaired_open_count = _repair_persisted_bybit_open_times(_get_trading_journal_rows())
    if repaired_open_count:
        _set_trading_journal_rows(repaired_open_rows)
    backfilled_rows, backfilled_count = _backfill_persisted_bybit_trade_fields(repaired_open_rows)
    if backfilled_count:
        _set_trading_journal_rows(backfilled_rows)
    repaired_open_rows = backfilled_rows
    sanitized_rows, sanitize_stats = _sanitize_bybit_demo_rows(repaired_open_rows)
    if int(sanitize_stats.get("changed", 0)):
        _set_trading_journal_rows(sanitized_rows)
    rows = [
        r
        for r in sanitized_rows
        if isinstance(r, dict) and not _exclude_bybit_demo_row(r)
    ]
    rows = [_backfill_trade_row_context_fields(r) for r in rows]
    rows = _enrich_trade_row_metrics(
        _calc_balance_after_trade(rows, _get_excel_account_balances())
    )

    items: List[Dict[str, object]] = []
    for row in rows:
        if _row_type(row) != "trade":
            continue

        status = str(row.get("status") or row.get("state") or "").strip().lower()
        event = str(row.get("event") or row.get("type") or row.get("transaction_type") or "").strip().lower()
        if any(x in event for x in ("deposit", "withdraw")):
            continue
        if status and status not in {"closed", "close", "filled", "complete", "completed"}:
            continue

        closed_at = (
            row.get("close_time")
            or row.get("closed_at")
            or row.get("exit_time")
            or row.get("date")
        )
        if not closed_at:
            continue

        result_cash = (
            row.get("realized_pnl")
            if row.get("realized_pnl") is not None
            else row.get("net_profit")
        )
        pnl_num = _to_float(result_cash)
        balance_after = _to_float(row.get("balance_after_trade"))
        balance_before = None
        if balance_after is not None and pnl_num is not None:
            balance_before = balance_after - pnl_num

        result_pct = None
        if balance_before not in (None, 0) and pnl_num is not None:
            result_pct = (pnl_num / balance_before) * 100.0

        outcome = "Breakeven"
        if result_pct is not None:
            if result_pct > 0:
                outcome = "Win"
            elif result_pct < 0:
                outcome = "Loss"
        elif pnl_num is not None:
            if pnl_num > 0:
                outcome = "Win"
            elif pnl_num < 0:
                outcome = "Loss"

        refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
        opened_at = row.get("open_time") or row.get("opened_at") or row.get("entry_time")
        duration_seconds = _trade_duration_seconds(
            {
                "row_type": "trade",
                "open_time": opened_at,
                "close_time": closed_at,
            }
        )
        items.append(
            {
                "_row": row,
                "_row_id": row.get("id"),
                "_row_source": row.get("source"),
                "_row_order_id": refs.get("orderId"),
                "account": row.get("account_label") or row.get("account") or row.get("source"),
                "symbol": row.get("symbol") or row.get("instrument") or row.get("symbol_raw"),
                "side": row.get("side") or row.get("direction"),
                "timeframe": _normalize_timeframe(
                    row.get("timeframe")
                    or ((row.get("metrics") or {}).get("timeframe") if isinstance(row.get("metrics"), dict) else "")
                ),
                "opened_at": opened_at,
                "closed_at": closed_at,
                "stop_loss": row.get("stop_loss"),
                "take_profit": row.get("take_profit"),
                "entry_price": row.get("entry_price"),
                "exit_price": row.get("exit_price"),
                "fees": row.get("fees") if row.get("fees") is not None else row.get("commission"),
                "result_cash": pnl_num,
                "result_currency": row.get("realized_pnl_currency") or row.get("currency") or row.get("account_currency") or "USD",
                "result_pct": result_pct,
                "_row_balance_after_trade": row.get("balance_after_trade"),
                "_row_entry_price": row.get("entry_price"),
                "_row_exit_price": row.get("exit_price"),
                "_row_realized_pnl": row.get("realized_pnl")
                if row.get("realized_pnl") is not None
                else row.get("net_profit"),
                "_row_updated_at": row.get("updated_at"),
                "outcome": outcome,
                "duration_seconds": duration_seconds,
                "chart_row_id": row.get("id"),
                "chart_available": True,
            }
        )

    for row in _get_monthly_aud_revaluation_rows():
        if not isinstance(row, dict):
            continue
        closed_at = row.get("close_time") or row.get("closed_at")
        if not closed_at:
            continue
        result_cash = _to_float(row.get("result_cash"))
        items.append(
            {
                "_row": row,
                "_row_id": row.get("id"),
                "_row_source": row.get("source"),
                "_row_order_id": None,
                "row_type": row.get("row_type"),
                "account": row.get("account_label") or "Bybit Live",
                "symbol": row.get("symbol") or "MONTHLY AUD P/L",
                "side": row.get("side"),
                "timeframe": "",
                "opened_at": row.get("open_time") or row.get("opened_at"),
                "closed_at": closed_at,
                "stop_loss": row.get("stop_loss"),
                "take_profit": row.get("take_profit"),
                "entry_price": row.get("entry_price"),
                "exit_price": row.get("exit_price"),
                "fees": row.get("fees"),
                "result_cash": result_cash,
                "result_currency": row.get("result_currency") or "AUD",
                "result_pct": row.get("result_pct"),
                "_row_balance_after_trade": None,
                "_row_entry_price": row.get("entry_price"),
                "_row_exit_price": row.get("exit_price"),
                "_row_realized_pnl": result_cash,
                "_row_updated_at": row.get("updated_at"),
                "outcome": row.get("outcome"),
                "duration_seconds": row.get("duration_seconds") or None,
                "chart_row_id": row.get("id"),
                "chart_available": False,
            }
        )

    trade_items = [item for item in items if _row_type(item.get("_row") if isinstance(item.get("_row"), dict) else {}) == "trade"]
    non_trade_items = [item for item in items if item not in trade_items]

    def _norm_account(value: object) -> str:
        return re.sub(r"\s+", " ", str(value or "").strip().lower())

    def _norm_side(value: object) -> str:
        raw = str(value or "").strip().lower()
        if raw in {"buy", "long"}:
            return "buy"
        if raw in {"sell", "short"}:
            return "sell"
        return raw

    def _rounded_num(value: object, dp: int = 8) -> str:
        num = _to_float(value)
        if num is None:
            return ""
        return f"{num:.{dp}f}"

    def _trade_key(item: Dict[str, object]) -> str:
        order_id = str(item.get("_row_order_id") or "").strip()
        row_data = item.get("_row") if isinstance(item.get("_row"), dict) else {}
        if order_id and _is_bybit_demo_trade_row(row_data):
            return f"order:{order_id}"
        return "|".join(
            [
                _norm_account(item.get("account")),
                str(item.get("symbol") or "").strip().upper(),
                str(_canonical_trade_epoch_second(item.get("opened_at")) or ""),
                str(_canonical_trade_epoch_second(item.get("closed_at")) or ""),
                _rounded_num(row_data.get("qty"), 8),
                _rounded_num(item.get("_row_entry_price")),
                _rounded_num(item.get("_row_exit_price")),
                _rounded_num(item.get("fees"), 6),
                _rounded_num(item.get("_row_realized_pnl"), 6),
            ]
        )

    def _trade_score(item: Dict[str, object]) -> Tuple[int, int, int, int, int]:
        has_tpsl = int(item.get("stop_loss") is not None or item.get("take_profit") is not None)
        has_order_id = int(bool(str(item.get("_row_order_id") or "").strip()))
        has_balance = int(item.get("_row_balance_after_trade") is not None)
        src = str(item.get("_row_source") or "").strip().lower()
        source_rank = 1 if src == "bybit" else 0
        updated_rank = _canonical_trade_epoch_second(item.get("_row_updated_at")) or -1
        return has_tpsl, has_order_id, has_balance, source_rank, updated_rank

    deduped: Dict[str, Dict[str, object]] = {}
    for item in trade_items:
        key = _trade_key(item)
        prev = deduped.get(key)
        if prev is None or _trade_score(item) > _trade_score(prev):
            deduped[key] = item
    first_pass = list(deduped.values())

    second_pass: Dict[str, Dict[str, object]] = {}
    for item in first_pass:
        row_data = item.get("_row") if isinstance(item.get("_row"), dict) else {}
        if _is_bybit_demo_trade_row(row_data):
            key = "|".join(
                [
                    _norm_account(item.get("account")),
                    str(item.get("symbol") or "").strip().upper(),
                    str(_canonical_trade_epoch_second(item.get("opened_at")) or ""),
                    str(_canonical_trade_epoch_second(item.get("closed_at")) or ""),
                    _rounded_num(row_data.get("qty"), 8),
                    _rounded_num(item.get("_row_entry_price")),
                    _rounded_num(item.get("_row_exit_price")),
                    _rounded_num(item.get("fees"), 6),
                    _rounded_num(item.get("_row_realized_pnl"), 6),
                ]
            )
        else:
            key = _trade_key(item)
        prev = second_pass.get(key)
        if prev is None or _trade_score(item) > _trade_score(prev):
            second_pass[key] = item
    items = list(second_pass.values()) + non_trade_items

    def _sort_ts(value: object) -> float:
        try:
            return float(pd.to_datetime(value).timestamp())
        except Exception:
            return float("-inf")

    items.sort(
        key=lambda r: (
            1 if _row_type(r.get("_row") if isinstance(r.get("_row"), dict) else {}) == "trade" else 0,
            _sort_ts(r.get("closed_at")),
        ),
        reverse=True,
    )
    public_items = []
    for item in items[: max(1, min(limit, 200))]:
        copy = dict(item)
        copy["chart_row_id"] = item.get("_row_id")
        if item.get("chart_available") is None:
            copy["chart_available"] = _row_type(item.get("_row") if isinstance(item.get("_row"), dict) else {}) == "trade"
        copy.pop("_row_id", None)
        copy.pop("_row_source", None)
        copy.pop("_row_order_id", None)
        copy.pop("_row_balance_after_trade", None)
        copy.pop("_row_realized_pnl", None)
        copy.pop("_row_updated_at", None)
        copy.pop("_row", None)
        public_items.append(copy)
    return JSONResponse({"items": public_items})


