@app.get("/results/{script_name:path}/{result_path:path}")
async def read_script_results(script_name: str, result_path: str) -> FileResponse:
    safe_script_name = script_name.replace("..", "").strip("/")
    safe_result_path = result_path.replace("..", "").lstrip("/")

    script = None
    try:
        script = script_manager.get(safe_script_name)
    except HTTPException as exc:
        if exc.status_code == 404 and "/" in safe_script_name:
            parts = [part for part in safe_script_name.split("/") if part]
            resolved = False
            for cut in range(len(parts) - 1, 0, -1):
                candidate = "/".join(parts[:cut])
                extra = "/".join(parts[cut:])
                try:
                    script = script_manager.get(candidate)
                    safe_result_path = f"{extra}/{safe_result_path}" if extra else safe_result_path
                    resolved = True
                    break
                except HTTPException:
                    continue
            if not resolved:
                raise
        else:
            raise

    base_dir = script.last_spawn_cwd or str(script.path.parent) if script else None
    if not base_dir:
        raise HTTPException(status_code=404, detail="Script has not been started yet.")

    file_path = Path(base_dir) / safe_result_path
    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="Result file not found.")
    try:
        resolved = file_path.resolve()
        base_resolved = Path(base_dir).resolve()
    except RuntimeError as exc:
        raise HTTPException(status_code=400, detail=f"Invalid path: {exc}") from exc
    if not str(resolved).startswith(str(base_resolved)):
        raise HTTPException(status_code=403, detail="Access denied.")
    return FileResponse(resolved)


@app.post("/api/oanda-history/export")
async def start_oanda_history_export(request: Request) -> JSONResponse:
    if oanda_history_exporter is None:
        raise HTTPException(status_code=500, detail="OANDA history exporter not available.")
    payload = await request.json()

    account = str(payload.get("account") or "").strip().lower()
    if account not in {"live", "demo"}:
        raise HTTPException(status_code=400, detail="account must be live or demo.")
    period = _normalize_period(payload.get("period"))
    days = payload.get("days")
    complete = payload.get("complete")

    if period is not None:
        if days is not None or complete:
            raise HTTPException(status_code=400, detail="Specify only one of period, days, or complete.")
        if period == "complete":
            complete = True
            period = None

    params: Dict[str, object] = {"account": account}
    if complete:
        params.update({"complete": True})
    elif period is not None:
        params.update({"period": period, "complete": False})
    else:
        if days is None:
            raise HTTPException(status_code=400, detail="days is required unless complete is true.")
        try:
            days_int = int(days)
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="days must be an integer.") from exc
        if days_int <= 0:
            raise HTTPException(status_code=400, detail="days must be greater than zero.")
        params.update({"days": days_int, "complete": False})

    job_id = uuid4().hex
    job = OandaHistoryJob(
        job_id=job_id,
        status="queued",
        created_at=time.time(),
        updated_at=time.time(),
        params=params,
    )
    OANDA_HISTORY_JOBS[job_id] = job
    asyncio.create_task(_run_oanda_history_export(job))
    return JSONResponse({"job_id": job_id})

@app.get("/api/oanda-history/export/{job_id}")
async def oanda_history_export_status(job_id: str) -> JSONResponse:
    job = OANDA_HISTORY_JOBS.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Export job not found.")
    payload: Dict[str, object] = {
        "job_id": job.job_id,
        "status": job.status,
        "error": job.error,
        "account": job.params.get("account"),
    }
    if (
        job.status == "done"
        and job.output_path is not None
        and job.output_path.exists()
    ):
        payload["download_url"] = f"/api/oanda-history/export/{job.job_id}/download"
    return JSONResponse(payload)


@app.get("/api/oanda-history/export/{job_id}/download")
async def download_oanda_history_export(job_id: str) -> FileResponse:
    job = OANDA_HISTORY_JOBS.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Export job not found.")
    if job.status != "done" or job.output_path is None:
        raise HTTPException(status_code=400, detail="Export not ready.")
    if not job.output_path.exists():
        raise HTTPException(status_code=404, detail="Export file not found.")
    return FileResponse(
        job.output_path,
        filename=job.output_path.name,
        media_type="text/csv",
    )


@app.post("/api/oanda-history/export/{job_id}/backfill-journal")
async def backfill_oanda_history_export_to_journal(job_id: str) -> JSONResponse:
    def _coerce_append_stats(stats: object) -> Dict[str, object]:
        if isinstance(stats, dict):
            return {
                "changed": int(stats.get("changed") or 0),
                "inserted": int(stats.get("inserted") or 0),
                "updated": int(stats.get("updated") or 0),
                "legacy_rows_migrated": int(stats.get("legacy_rows_migrated") or 0),
                "legacy_migration_performed": bool(stats.get("legacy_migration_performed")),
            }
        changed = int(stats or 0)
        return {
            "changed": changed,
            "inserted": changed,
            "updated": 0,
            "legacy_rows_migrated": 0,
            "legacy_migration_performed": False,
        }

    def _response(
        *,
        ok: bool,
        target_workbook: str,
        source_path: str,
        trades_seen: int = 0,
        trades_backfilled: int = 0,
        trades_updated: int = 0,
        latest_balance: object = None,
        latest_balance_as_of: object = None,
        error: object = None,
        sync: object = None,
        rows_persisted: bool = False,
        balance_applied: bool = False,
        snapshot_visible: bool = False,
        status_code: int = 200,
    ) -> JSONResponse:
        payload = {
            "ok": bool(ok),
            "oanda_export_trades_seen": int(trades_seen),
            "oanda_export_trades_backfilled": int(trades_backfilled),
            "oanda_export_trades_updated": int(trades_updated),
            "oanda_export_target_workbook": str(target_workbook or ""),
            "oanda_export_source_path": str(source_path or ""),
            "oanda_export_latest_balance": latest_balance,
            "oanda_export_latest_balance_as_of": latest_balance_as_of,
            "oanda_export_balance_applied": bool(balance_applied),
            "oanda_export_rows_persisted": bool(rows_persisted),
            "error": None if error in (None, "") else str(error),
            "sync": sync if isinstance(sync, dict) else {},
            "snapshot_visible": bool(snapshot_visible),
        }
        return JSONResponse(_json_safe(payload), status_code=status_code)

    def _import_error(result: object) -> str:
        if not isinstance(result, dict):
            return "OANDA authoritative journal import returned an invalid response."
        for key in ("message", "master_journal_error", "error"):
            value = result.get(key)
            if value not in (None, ""):
                return str(value)
        errors = result.get("errors")
        if isinstance(errors, list) and errors:
            return "; ".join(str(item) for item in errors if item not in (None, ""))
        return "OANDA authoritative journal import failed."

    job = OANDA_HISTORY_JOBS.get(job_id)
    if job is None:
        return _response(
            ok=False,
            target_workbook="",
            source_path="",
            error="Export job not found.",
            sync={"ok": False, "message": "Export job not found."},
            status_code=404,
        )
    if job.status != "done" or job.output_path is None or not job.output_path.exists():
        return _response(
            ok=False,
            target_workbook="",
            source_path=str(job.output_path or ""),
            error="Export not ready.",
            sync={"ok": False, "message": "Export not ready."},
            status_code=400,
        )
    sidecar = _load_json_file(job.output_path.with_suffix(".json"), {})
    account_mode = str((sidecar or {}).get("account_mode") or job.params.get("account") or "").strip().lower()
    if account_mode not in {"demo", "live"}:
        return _response(
            ok=False,
            target_workbook="",
            source_path=str(job.output_path),
            error="Unable to resolve OANDA account mode for backfill.",
            sync={"ok": False, "message": "Unable to resolve OANDA account mode for backfill."},
            status_code=400,
        )
    target_workbook = (
        _master_journal_path().name
        if _master_journal_single_file_mode()
        else _canonical_local_oanda_workbook_name(account_mode)
    )
    try:
        rows, balance = _parse_local_trading_journal_workbook(
            job.output_path,
            original_name=job.output_path.name,
            account_mode=account_mode,
        )
    except Exception as exc:
        message = f"Failed to parse completed OANDA export for journal backfill: {exc}"
        return _response(
            ok=False,
            target_workbook=target_workbook,
            source_path=str(job.output_path),
            error=message,
            sync={"ok": False, "message": message, "errors": [str(exc)]},
        )
    mapped: List[Dict[str, object]] = []
    for row in rows:
        if str((row or {}).get("source") or "").strip().lower() != "oanda_transaction_export":
            continue
        mapped_row = dict(row)
        mapped_row["account"] = account_mode
        mapped_row["account_label"] = "OANDA DEMO" if account_mode == "demo" else "OANDA LIVE"
        mapped.append(mapped_row)
    latest_balance = (balance or {}).get("balance") if isinstance(balance, dict) else None
    latest_balance_as_of = (balance or {}).get("as_of") if isinstance(balance, dict) else None

    if _master_journal_single_file_mode():
        try:
            import_result = _import_uploaded_trading_journal_file(
                job.output_path.name,
                job.output_path.read_bytes(),
                account_mode=account_mode,
            )
        except Exception as exc:
            message = f"Authoritative Trading Journal backfill failed unexpectedly: {exc}"
            return _response(
                ok=False,
                target_workbook=target_workbook,
                source_path=str(job.output_path),
                trades_seen=len(mapped),
                latest_balance=latest_balance,
                latest_balance_as_of=latest_balance_as_of,
                error=message,
                sync={"ok": False, "message": message, "errors": [str(exc)]},
            )
        if not isinstance(import_result, dict) or not bool(import_result.get("ok")):
            return _response(
                ok=False,
                target_workbook=target_workbook,
                source_path=str(job.output_path),
                trades_seen=len(mapped),
                latest_balance=latest_balance,
                latest_balance_as_of=latest_balance_as_of,
                error=_import_error(import_result),
                sync=import_result,
                rows_persisted=bool(
                    isinstance(import_result, dict)
                    and import_result.get("rows_persisted")
                ),
                balance_applied=bool(
                    isinstance(import_result, dict)
                    and import_result.get("balance_applied")
                ),
                snapshot_visible=bool(
                    isinstance(import_result, dict)
                    and import_result.get("snapshot_visible")
                ),
            )

        rows_persisted = bool(import_result.get("rows_persisted"))
        balance_applied = bool(import_result.get("balance_applied"))
        snapshot_visible = bool(import_result.get("snapshot_visible"))
        parsed_ids = [
            str(row.get("id") or "").strip()
            for row in mapped
            if str(row.get("id") or "").strip()
        ]
        verification = _verify_trade_log_row_ids_in_workbook(_master_journal_path(), parsed_ids)
        import_result = {**import_result, "oanda_backfill_verification": verification}
        if not bool((verification or {}).get("ok")):
            missing_ids = list((verification or {}).get("missing_row_ids") or [])
            message = (
                "Trading Journal.xlsx verification failed after OANDA backfill. "
                f"Missing row IDs: {missing_ids}"
            )
            return _response(
                ok=False,
                target_workbook=target_workbook,
                source_path=str(job.output_path),
                trades_seen=len(mapped),
                latest_balance=latest_balance,
                latest_balance_as_of=latest_balance_as_of,
                error=message,
                sync=import_result,
                rows_persisted=rows_persisted,
                balance_applied=balance_applied,
                snapshot_visible=snapshot_visible,
            )
        rows_persisted = True

        rows_upserted = int(import_result.get("rows_upserted") or 0)
        duplicate_rows = int(import_result.get("duplicate_rows_merged") or 0)
        inserted = max(0, len(mapped) - duplicate_rows) if rows_upserted else 0
        updated = min(duplicate_rows, rows_upserted)
        _invalidate_trading_journal_view_snapshot()
        visibility_error = None
        try:
            snapshot_payload = _build_trading_journal_view_snapshot(force=True)
            balances_now = _snapshot_balance_items(snapshot_payload)
            label = "OANDA DEMO" if account_mode == "demo" else "OANDA LIVE"
            target_bal = next(
                (
                    item
                    for item in balances_now
                    if str((item or {}).get("label") or (item or {}).get("account") or "").strip().upper()
                    == label
                ),
                None,
            )
            snapshot_visible = isinstance(target_bal, dict)
            if not isinstance(target_bal, dict) or str(target_bal.get("balance_source") or "") == "cashflow_anchor_plus_trades":
                visibility_error = "OANDA_BACKFILL_NOT_VISIBLE_IN_JOURNAL_SNAPSHOT"
                balance_applied = False
            else:
                expected_balance = _to_float(latest_balance)
                snapshot_balance = _to_float(target_bal.get("balance"))
                expected_balance_source = str(
                    (balance or {}).get("balance_source")
                    or (balance or {}).get("source")
                    or ""
                ).strip()
                snapshot_balance_source = str(
                    target_bal.get("balance_source")
                    or target_bal.get("source")
                    or ""
                ).strip()
                if (
                    expected_balance_source
                    and snapshot_balance_source != expected_balance_source
                ):
                    visibility_error = (
                        "OANDA_BACKFILL_BALANCE_PROVENANCE_MISMATCH: "
                        f"export={expected_balance_source} "
                        f"snapshot={snapshot_balance_source}"
                    )
                    balance_applied = False
                elif expected_balance is not None and (
                    snapshot_balance is None
                    or abs(snapshot_balance - expected_balance) > 1e-6
                ):
                    visibility_error = (
                        "OANDA_BACKFILL_BALANCE_MISMATCH: "
                        f"export={expected_balance} snapshot={snapshot_balance}"
                    )
                    balance_applied = False
                elif expected_balance is not None:
                    balance_applied = True
        except Exception as exc:
            visibility_error = f"OANDA_BACKFILL_SNAPSHOT_VERIFICATION_FAILED: {exc}"
        if visibility_error:
            return _response(
                ok=False,
                target_workbook=target_workbook,
                source_path=str(job.output_path),
                trades_seen=len(mapped),
                trades_backfilled=inserted,
                trades_updated=updated,
                latest_balance=latest_balance,
                latest_balance_as_of=latest_balance_as_of,
                error=visibility_error,
                sync=import_result,
                rows_persisted=rows_persisted,
                balance_applied=balance_applied,
                snapshot_visible=snapshot_visible,
            )
        return _response(
            ok=True,
            target_workbook=target_workbook,
            source_path=str(job.output_path),
            trades_seen=len(mapped),
            trades_backfilled=inserted,
            trades_updated=updated,
            latest_balance=latest_balance,
            latest_balance_as_of=latest_balance_as_of,
            sync=import_result,
            rows_persisted=rows_persisted,
            balance_applied=balance_applied,
            snapshot_visible=snapshot_visible,
        )

    changed = 0
    inserted = 0
    updated = 0
    append_error = None
    try:
        stats_raw = _append_oanda_export_rows_to_local_workbook(account_mode, mapped, str(job.output_path), return_stats=True)
        stats = _coerce_append_stats(stats_raw)
        changed = int(stats.get("changed") or 0)
        inserted = int(stats.get("inserted") or 0)
        updated = int(stats.get("updated") or 0)
    except Exception as exc:
        append_error = str(exc)
    import_result = {"ok": False, "message": "Backfill append failed."}
    snapshot_payload = None
    target_bal = None
    visibility_error = None
    if append_error is None:
        _invalidate_trading_journal_view_snapshot()
        try:
            import_result = _import_trading_journal_from_sources()
        except Exception as exc:
            import_result = {"ok": False, "message": f"Legacy OANDA journal import failed: {exc}", "errors": [str(exc)]}
        try:
            snapshot_payload = _build_trading_journal_view_snapshot(force=True)
            balances_now = _snapshot_balance_items(snapshot_payload)
            label = "OANDA DEMO" if account_mode == "demo" else "OANDA LIVE"
            target_bal = next((b for b in balances_now if str((b or {}).get("label") or (b or {}).get("account") or "").strip().upper() == label), None)
            if not isinstance(target_bal, dict) or str(target_bal.get("balance_source") or "") == "cashflow_anchor_plus_trades":
                visibility_error = "OANDA_BACKFILL_NOT_VISIBLE_IN_JOURNAL_SNAPSHOT"
            else:
                expected_balance = _to_float(latest_balance)
                visible_balance = _to_float(target_bal.get("balance"))
                if expected_balance is not None and (
                    visible_balance is None
                    or abs(visible_balance - expected_balance) > 1e-6
                ):
                    visibility_error = (
                        "OANDA_BACKFILL_BALANCE_MISMATCH: "
                        f"export={expected_balance} snapshot={visible_balance}"
                    )
        except Exception:
            visibility_error = "OANDA_BACKFILL_NOT_VISIBLE_IN_JOURNAL_SNAPSHOT"
    ok_flag = bool(append_error is None and bool(import_result.get("ok")) and not visibility_error)
    return _response(
        ok=ok_flag,
        target_workbook=target_workbook,
        source_path=str(job.output_path),
        trades_seen=len(mapped),
        trades_backfilled=inserted,
        trades_updated=updated,
        latest_balance=latest_balance,
        latest_balance_as_of=latest_balance_as_of,
        error=append_error or visibility_error or (None if import_result.get("ok") else _import_error(import_result)),
        sync=import_result,
        rows_persisted=bool(append_error is None and mapped),
        balance_applied=bool(
            isinstance(target_bal, dict)
            and visibility_error is None
            and _to_float(latest_balance) is not None
        ),
        snapshot_visible=isinstance(target_bal, dict),
    )


@app.post("/api/trading-journal/oanda-demo/repair-balance")
async def trading_journal_repair_oanda_demo_balance() -> JSONResponse:
    demo_exports = [p for p in _list_local_oanda_history_exports() if "demo" in p.name.lower()]
    if not demo_exports:
        return JSONResponse({"ok": False, "error": "OANDA_DEMO_EXPORT_NOT_FOUND", "message": "OANDA DEMO balance is stale. Run/export OANDA demo history, then repair."}, status_code=400)
    source_path = sorted(demo_exports, key=lambda p: p.stat().st_mtime, reverse=True)[0]
    rows, balance = _parse_local_trading_journal_workbook(source_path)
    mapped = [r for r in rows if str((r or {}).get("source") or "").strip().lower() == "oanda_transaction_export"]
    for row in mapped:
        row["account"] = "demo"
        row["account_label"] = "OANDA DEMO"
    try:
        stats = _append_oanda_export_rows_to_local_workbook("demo", mapped, str(source_path), return_stats=True)
    except Exception as exc:
        err = str(exc)
        return JSONResponse({"ok": False, "error": err, "message": "Install dependencies in the same Python runtime used by run_trading_journal_local.bat, then restart." if "MISSING_XLRD_FOR_XLS" in err else err}, status_code=400)
    _invalidate_trading_journal_view_snapshot()
    sync = _import_trading_journal_from_sources()
    snap = _build_trading_journal_view_snapshot(force=True)
    balances = _snapshot_balance_items(snap)
    demo = next((b for b in balances if str((b or {}).get("label") or "").upper() == "OANDA DEMO"), None)
    if not isinstance(demo, dict) or str(demo.get("balance_source") or "") == "cashflow_anchor_plus_trades":
        return JSONResponse(_json_safe({"ok": False, "error": "OANDA_BACKFILL_NOT_VISIBLE_IN_JOURNAL_SNAPSHOT", "sync": sync}), status_code=409)
    return JSONResponse(_json_safe({"ok": True, "stats": stats, "source_path": str(source_path), "balance": balance, "sync": sync}))


@app.post("/api/coinspot-history/export")
async def start_coinspot_history_export(request: Request) -> JSONResponse:
    payload = await request.json()
    period = _normalize_period(payload.get("period"))
    days = payload.get("days")
    complete = payload.get("complete")

    if period is not None:
        if days is not None or complete:
            raise HTTPException(status_code=400, detail="Specify only one of period, days, or complete.")
        if period == "complete":
            complete = True
            period = None

    params: Dict[str, object] = {}
    if complete:
        params.update({"complete": True})
    elif period is not None:
        params.update({"period": period, "complete": False})
    else:
        if days is None:
            raise HTTPException(status_code=400, detail="days is required unless complete is true.")
        try:
            days_int = int(days)
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="days must be an integer.") from exc
        if days_int <= 0:
            raise HTTPException(status_code=400, detail="days must be greater than zero.")
        params.update({"days": days_int, "complete": False})

    job_id = uuid4().hex
    job = CoinspotHistoryJob(
        job_id=job_id,
        status="queued",
        created_at=time.time(),
        updated_at=time.time(),
        params=params,
    )
    COINSPOT_HISTORY_JOBS[job_id] = job
    asyncio.create_task(_run_coinspot_history_export(job))
    return JSONResponse({"job_id": job_id})


@app.get("/api/coinspot-history/export/{job_id}")
async def coinspot_history_export_status(job_id: str) -> JSONResponse:
    job = COINSPOT_HISTORY_JOBS.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Export job not found.")
    payload: Dict[str, object] = {
        "job_id": job.job_id,
        "status": job.status,
        "error": job.error,
    }
    if job.status == "done" and job.output_path is not None and job.output_path.exists():
        payload["download_url"] = f"/api/coinspot-history/export/{job.job_id}/download"
    return JSONResponse(payload)


