@app.get("/api/trading-journal")
async def trading_journal_items(filter: str = "") -> JSONResponse:
    snapshot = _TRADING_JOURNAL_VIEW_CACHE.get("payload") if _TRADING_JOURNAL_VIEW_CACHE.get("key") == "snapshot" else None
    if not isinstance(snapshot, dict):
        snapshot = _load_trading_journal_view_snapshot()
    fingerprint_now = _journal_source_fingerprint()
    freshness = _trading_journal_snapshot_freshness(snapshot, fingerprint_now)
    if freshness.get("current") is not True:
        derived_refresh = _trading_journal_derived_refresh_status_snapshot()
        derived_pending = bool(
            derived_refresh.get("queued")
            or derived_refresh.get("running")
            or derived_refresh.get("pending")
        )
        refresh_state = _trading_journal_equity_refresh_state_snapshot()
        pending = bool(refresh_state.get("running") or refresh_state.get("pending"))
        same_failed_fingerprint = bool(
            refresh_state.get("ok") is False
            and refresh_state.get("requested_source_fingerprints") == fingerprint_now
        )
        if not derived_pending and not pending and not same_failed_fingerprint:
            refresh_state = _queue_trading_journal_equity_refresh_if_idle(
                "missing_or_stale_api_snapshot",
                current_fingerprints=fingerprint_now,
            )
            pending = bool(refresh_state.get("running") or refresh_state.get("pending"))
        if derived_pending:
            pending = True
            warning = "Saved journal changes are awaiting the shared derived workbook refresh."
        else:
            warning = (
                "Building current equity data from Trading Journal.xlsx."
                if pending
                else "Current equity data is unavailable because the cache rebuild failed."
            )
        payload = {
            "ok": False,
            "pending": pending,
            "snapshot_current": False,
            "snapshot_stale": isinstance(snapshot, dict),
            "warning": warning,
            "error": None if pending else (
                refresh_state.get("error")
                or refresh_state.get("message")
                or "Equity cache build failed."
            ),
            "items": [],
            "count": 0,
            "stats": {},
            "balances": [],
            "freshness_reasons": freshness.get("reasons") or [],
            "refresh_id": (
                derived_refresh.get("generation")
                if derived_pending
                else refresh_state.get("refresh_id")
            ),
            "refresh_status": derived_refresh if derived_pending else refresh_state,
            "derived_refresh": derived_refresh,
            "status_url": (
                "/api/trading-journal/import/status"
                if derived_pending
                else "/api/trading-journal/equity/refresh/status"
            ),
        }
        return JSONResponse(_json_safe(payload), status_code=202 if pending else 503)
    is_stale = False
    items = list(snapshot.get("items") or [])
    stats = snapshot.get("stats") or {}
    if _trading_journal_local_excel_authoritative():
        filtered = [
            r for r in items
            if not (isinstance(r, dict) and _row_type(r) == "trade" and str(r.get("source") or "").strip().lower() != "local_excel")
        ]
        if len(filtered) != len(items):
            items = filtered
            balances_for_stats = snapshot.get("balances") if isinstance(snapshot.get("balances"), list) else []
            stats = _compute_journal_stats_with_period_reports(
                items, balances_for_stats
            )

    def _norm_search_text(value: object) -> str:
        text = str(value or "").lower()
        text = text.replace("_", " ").replace("-", " ")
        text = re.sub(r"\s+", " ", text)
        return text.strip()

    query = _norm_search_text((filter or "").strip())
    tokens = [t for t in query.split(" ") if t]
    if tokens:

        def match(row: Dict[str, object]) -> bool:
            searchable = [
                row.get("symbol"),
                row.get("symbol_raw"),
                row.get("account_label"),
                row.get("account"),
                row.get("source"),
                row.get("row_type"),
                row.get("result_currency"),
                row.get("result_cash"),
                ((row.get("raw_refs") or {}).get("period_month") if isinstance(row.get("raw_refs"), dict) else ""),
                row.get("id"),
                row.get("sheet"),
                row.get("timeframe"),
                _display_test_trade(row),
                row.get("setup"),
                row.get("breakeven"),
                row.get("notes"),
                row.get("pre_trade_comments"),
                row.get("entry_comments"),
                row.get("trade_management"),
                row.get("exit_comments"),
            ]
            metrics = row.get("metrics")
            if isinstance(metrics, dict):
                searchable.extend(metrics.values())
            hay = _norm_search_text(" ".join(str(x or "") for x in searchable))
            return all(tok in hay for tok in tokens)

        items = [r for r in items if match(r)]

    response_balances = (
        snapshot.get("balances")
        if isinstance(snapshot.get("balances"), list)
        else (stats.get("balances") if isinstance(stats, dict) else [])
    )
    response_equity_cache = (
        dict(snapshot.get("equity_cache"))
        if isinstance(snapshot.get("equity_cache"), dict)
        else {}
    )
    response_equity_cache["point_counts"] = _equity_point_counts(
        items,
        response_balances,
    )
    payload = {
        "ok": True,
        "items": items,
        "count": len(items),
        "stats": stats,
        "balances": response_balances,
        "generated_at": snapshot.get("generated_at"),
        "cache_version": snapshot.get("cache_version"),
        "snapshot_id": snapshot.get("snapshot_id"),
        "snapshot_fingerprint": snapshot.get("snapshot_fingerprint"),
        "snapshot_current": True,
        "snapshot_stale": False,
        "equity_cache": response_equity_cache,
        "source_mode": _trading_journal_source_mode(),
        "local_dir": str(TRADING_JOURNAL_LOCAL_DIR),
        "excel_only": _trading_journal_excel_only_mode(),
        "warning": "",
    }
    diag_errors = (snapshot.get("diagnostics") or {}).get("errors") if isinstance(snapshot.get("diagnostics"), dict) else []
    missing_demo_anchor = any("Missing balance anchor for accounts: BYBIT DEMO" in str(e) for e in (diag_errors or []))
    if missing_demo_anchor and _trading_journal_bybit_demo_balance_anchor_enabled():
        sync_status = _sync_state_snapshot()
        can_queue = _should_auto_queue_bybit_demo_anchor_repair()
        if can_queue and not bool(sync_status.get("running")):
            sync_status = _queue_trading_journal_sync_if_idle("bybit_demo_missing_balance_anchor")
        payload["pending"] = bool(can_queue)
        payload["snapshot_stale"] = bool(can_queue)
        payload["ok"] = False
        payload["warning"] = (
            "BYBIT DEMO balance anchor repair queued. Journal cache is rebuilding."
            if can_queue
            else "BYBIT DEMO balance anchor unresolved: wallet anchor fetch failed; check diagnostics."
        )
        payload["sync_status"] = sync_status
    _TRADING_JOURNAL_VIEW_CACHE["key"] = "snapshot"
    _TRADING_JOURNAL_VIEW_CACHE["payload"] = _json_safe(snapshot)
    return JSONResponse(_json_safe(payload))


@app.get("/api/trading-journal/diagnostics")
async def trading_journal_diagnostics() -> JSONResponse:
    snapshot = _TRADING_JOURNAL_VIEW_CACHE.get("payload") if _TRADING_JOURNAL_VIEW_CACHE.get("key") == "snapshot" else None
    if not isinstance(snapshot, dict):
        snapshot = _load_trading_journal_view_snapshot() or {}
    if not isinstance(snapshot, dict) or not snapshot:
        sync_status = _sync_state_snapshot()
        diagnostics = _build_trading_journal_diagnostics_snapshot()
        diagnostics["pending"] = bool(sync_status.get("running") or sync_status.get("ok") is None)
        diagnostics["sync_status"] = sync_status
        return JSONResponse(_json_safe(diagnostics), status_code=202 if diagnostics["pending"] else 503)
    payload = snapshot.get("diagnostics") if isinstance(snapshot.get("diagnostics"), dict) else _build_trading_journal_diagnostics_snapshot()
    payload["source_mode"] = _trading_journal_source_mode()
    payload["excel_only"] = _trading_journal_excel_only_mode()
    payload["local_dir"] = str(TRADING_JOURNAL_LOCAL_DIR)
    return JSONResponse(_json_safe(payload))
@app.get("/api/trading-journal/balances")
async def trading_journal_balances() -> JSONResponse:
    snapshot = _TRADING_JOURNAL_VIEW_CACHE.get("payload") if _TRADING_JOURNAL_VIEW_CACHE.get("key") == "snapshot" else None
    if not isinstance(snapshot, dict):
        snapshot = _load_trading_journal_view_snapshot() or {}
    if not isinstance(snapshot, dict) or not snapshot:
        sync_status = _sync_state_snapshot()
        pending = bool(sync_status.get("running") or sync_status.get("ok") is None)
        status_code = 202 if pending else 503
        return JSONResponse(_json_safe({"items": [], "pending": pending, "sync_status": sync_status}), status_code=status_code)
    items = snapshot.get("balances") if isinstance(snapshot.get("balances"), list) else []
    diagnostics = snapshot.get("diagnostics") if isinstance(snapshot.get("diagnostics"), dict) else {}
    errors = diagnostics.get("errors") if isinstance(diagnostics.get("errors"), list) else []
    missing_demo_anchor = any("Missing balance anchor for accounts: BYBIT DEMO" in str(e) for e in (errors or []))
    if missing_demo_anchor and _trading_journal_bybit_demo_balance_anchor_enabled():
        sync_status = _sync_state_snapshot()
        can_queue = _should_auto_queue_bybit_demo_anchor_repair()
        if can_queue and not bool(sync_status.get("running")):
            sync_status = _queue_trading_journal_sync_if_idle("bybit_demo_missing_balance_anchor")
        return JSONResponse(
            _json_safe({
                "items": items,
                "ok": False,
                "pending": bool(can_queue),
                "snapshot_stale": bool(can_queue),
                "warning": (
                    "BYBIT DEMO balance anchor repair queued. Journal cache is rebuilding."
                    if can_queue
                    else "BYBIT DEMO balance anchor unresolved: wallet anchor fetch failed; check diagnostics."
                ),
                "diagnostics": diagnostics,
                "errors": errors,
                "sync_status": sync_status,
            }),
            status_code=202 if can_queue else 200,
        )
    if items:
        return JSONResponse(_json_safe({"items": items, "ok": not bool(errors), "diagnostics": diagnostics, "errors": errors}), status_code=200)
    if errors:
        return JSONResponse(_json_safe({"items": items, "ok": False, "diagnostics": diagnostics, "errors": errors}), status_code=503)
    return JSONResponse(_json_safe({"items": items, "ok": True, "diagnostics": diagnostics}))


@app.post("/api/trading-journal/rows")
async def trading_journal_create_row(payload: Dict[str, object] = Body(...)) -> JSONResponse:
    if _trading_journal_excel_only_mode() and str(os.getenv("TRADING_JOURNAL_ALLOW_MANUAL_ROWS", "0")).strip().lower() not in {"1", "true", "yes", "on"}:
        raise HTTPException(status_code=409, detail="Local Excel-only journal mode only displays trades from local workbook files.")
    normalized = _normalize_trading_journal_edit_payload(payload, for_create=True)
    open_time = normalized.get("open_time")
    close_time = normalized.get("close_time")
    if not open_time or not close_time:
        raise HTTPException(status_code=422, detail="open_time and close_time are required.")
    row = {
        "id": f"manual:{uuid4().hex}",
        "row_type": "trade",
        "source": "manual",
        "status": "closed",
        "is_manual": True,
        "created_at": _utc_now_iso(),
        "updated_at": _utc_now_iso(),
        **normalized,
    }
    row = _apply_trading_journal_manual_overrides(row, normalized)
    rows = _get_trading_journal_rows()
    rows.append(row)
    _set_trading_journal_rows(rows)
    return JSONResponse({"ok": True, "row": row})


@app.patch("/api/trading-journal/rows/{row_id}")
async def trading_journal_patch_row(row_id: str, payload: Dict[str, object] = Body(...)) -> JSONResponse:
    idx = _find_journal_row_index(row_id)
    if idx < 0:
        raise HTTPException(status_code=404, detail="Journal row not found.")
    rows = _get_trading_journal_rows()
    existing = dict(rows[idx])
    row_type = _row_type(existing)
    if row_type == "cashflow":
        raise HTTPException(status_code=409, detail="Cashflow rows are read-only in trading journal.")
    if row_type != "trade":
        raise HTTPException(status_code=422, detail="Only trade rows can be edited.")
    normalized = _normalize_trading_journal_edit_payload(payload, for_create=False, existing=existing)
    if not normalized:
        raise HTTPException(status_code=422, detail="No editable fields supplied.")

    is_manual = bool(existing.get("is_manual")) or str(existing.get("source") or "").lower() == "manual"
    updated = dict(existing)
    updated.update(normalized)
    updated["updated_at"] = _utc_now_iso()
    if is_manual:
        # Manual rows are source-of-truth and can be updated directly.
        merged_overrides = dict(updated.get("manual_overrides") or {})
        merged_overrides.update(normalized)
        updated = _apply_trading_journal_manual_overrides(updated, merged_overrides)
    else:
        # Imported rows keep a manual override layer reapplied after future sync merges.
        merged_overrides = dict(existing.get("manual_overrides") or {})
        merged_overrides.update(normalized)
        updated = _apply_trading_journal_manual_overrides(updated, merged_overrides)
    rows[idx] = updated
    _set_trading_journal_rows(rows)
    return JSONResponse({"ok": True, "row": updated})


@app.delete("/api/trading-journal/rows/{row_id}")
async def trading_journal_delete_row(row_id: str) -> JSONResponse:
    idx = _find_journal_row_index(row_id)
    if idx < 0:
        raise HTTPException(status_code=404, detail="Journal row not found.")
    rows = _get_trading_journal_rows()
    row = dict(rows[idx])
    row_type = _row_type(row)
    if row_type == "cashflow":
        raise HTTPException(status_code=409, detail="Cashflow rows are read-only in trading journal.")
    if row_type != "trade":
        raise HTTPException(status_code=422, detail="Only trade rows can be deleted.")
    is_manual = bool(row.get("is_manual")) or str(row.get("source") or "").lower() == "manual"
    if not is_manual:
        raise HTTPException(status_code=409, detail="Only manual trade rows can be deleted.")
    removed = rows.pop(idx)
    _set_trading_journal_rows(rows)
    return JSONResponse({"ok": True, "row": removed})


@app.get("/api/trading-journal/sync/status")
async def trading_journal_sync_status() -> JSONResponse:
    if _resolve_app_profile() != "local":
        return JSONResponse({"ok": False, "message": "Local workbook synchronization diagnostics are unavailable in this profile."}, status_code=404)
    return JSONResponse({"ok": True, **_manual_save_state_snapshot()})

async def _legacy_trading_journal_sync_status() -> JSONResponse:
    global TRADING_JOURNAL_SYNC_TASK, TRADING_JOURNAL_SYNC_THREAD
    with TRADING_JOURNAL_SYNC_LOCK:
        snapshot = _sync_state_snapshot()
        TRADING_JOURNAL_SYNC_STATE.update(snapshot)
    started_at_raw = snapshot.get("started_at")
    started_dt = _parse_iso_datetime(started_at_raw)
    now_dt = datetime.now(timezone.utc)
    elapsed_seconds = max(0.0, (now_dt - started_dt).total_seconds()) if started_dt else 0.0
    snapshot["elapsed_seconds"] = float(elapsed_seconds)
    task = TRADING_JOURNAL_SYNC_TASK
    thread_active = isinstance(TRADING_JOURNAL_SYNC_THREAD, threading.Thread) and TRADING_JOURNAL_SYNC_THREAD.is_alive()
    task_active = bool(task is not None and hasattr(task, "done") and not bool(task.done()))
    active_task_known = bool(task_active or thread_active)
    snapshot["active_task_known"] = bool(active_task_known)
    hb_dt = _parse_iso_datetime(snapshot.get("heartbeat_at") or snapshot.get("last_progress_at") or snapshot.get("updated_at"))
    stale_seconds = max(0.0, (now_dt - hb_dt).total_seconds()) if hb_dt else float(elapsed_seconds)
    snapshot["stale_seconds"] = float(stale_seconds)
    if bool(snapshot.get("running")) and stale_seconds > float(TRADING_JOURNAL_SYNC_STALE_SECONDS):
        snapshot["stale_warning"] = f"No heartbeat/progress update for {int(stale_seconds)}s."
    else:
        snapshot["stale_warning"] = ""

    if bool(snapshot.get("running")) and bool(task is not None and hasattr(task, "done") and bool(task.done())):
        if bool(hasattr(task, "cancelled") and task.cancelled()):
            snapshot["stale_warning"] = snapshot.get("stale_warning") or "Sync task was cancelled; awaiting state reconciliation."
            snapshot.update(_manual_save_state_snapshot())
            return JSONResponse(_json_safe(snapshot))
        err = None
        try:
            err = task.exception()
        except asyncio.CancelledError:
            err = RuntimeError("Sync task was cancelled before completion.")
        except Exception as exc:
            err = exc
        msg = str(err or "Sync task ended without clearing running state.")
        snapshot.update({"running": False, "ok": False, "error": msg, "message": f"Failed: {msg}", "abandoned_running_state": False, "finished_at": _utc_now_iso()})
        _set_trading_journal_sync_state(**snapshot)
        _log_trading_journal_sync_event("failed", reason="task_done_state_stale", error=msg)
    elif bool(snapshot.get("running")) and not active_task_known and elapsed_seconds > float(TRADING_JOURNAL_SYNC_ABANDONED_SECONDS):
        msg = "Trading Journal sync was marked running, but no active sync task exists. Previous process likely exited or task died."
        snapshot.update({"running": False, "ok": False, "error": msg, "message": f"Failed: {msg}", "abandoned_running_state": True, "finished_at": _utc_now_iso()})
        _set_trading_journal_sync_state(**snapshot)
        _log_trading_journal_sync_event("failed", reason="abandoned_running_state", error=msg)
    state = _load_trading_journal_state()
    bybit_demo_sync = state.get("bybit_demo_sync")
    snapshot["bybit_demo_sync"] = bybit_demo_sync if isinstance(bybit_demo_sync, dict) else {}
    snapshot["oanda_fill_poll"] = {
        "enabled": os.getenv("ENABLE_OANDA_FILL_POLL", "0") == "1",
        "accounts": {
            "live": {
                **_OANDA_FILL_DIAGNOSTICS.get("live", {}),
                "last_seen_transaction_id": _OANDA_TX_LAST_SEEN.get("live"),
            },
            "demo": {
                **_OANDA_FILL_DIAGNOSTICS.get("demo", {}),
                "last_seen_transaction_id": _OANDA_TX_LAST_SEEN.get("demo"),
            },
        },
    }
    source_mode = _trading_journal_source_mode()
    snapshot["source_mode"] = source_mode
    snapshot["local_dir"] = str(TRADING_JOURNAL_LOCAL_DIR)
    snapshot["local_import_enabled"] = bool(_local_journal_import_enabled())
    snapshot["dropbox_sync_enabled"] = os.getenv("DROPBOX_SYNC_ENABLED", "").strip().lower() in {"1", "true", "yes", "on"}
    snapshot["uses_dropbox_journal_import"] = bool(_trading_journal_uses_dropbox_journal_import())
    snapshot["broker_refresh_enabled"] = bool(_trading_journal_broker_refresh_enabled())
    requirements_path = str((BASE_DIR / "render" / "requirements.txt").resolve())
    xlrd_installed = importlib.util.find_spec("xlrd") is not None
    snapshot["dependencies"] = {
        "xlrd_installed": bool(xlrd_installed),
        "local_xls_supported": bool(xlrd_installed),
        "requirements_file": requirements_path,
    }
    result = snapshot.get("result")
    if isinstance(result, dict) and result.get("master_journal_ok") is True:
        path_text = str(result.get("master_journal_path") or "").strip()
        if not path_text or not Path(path_text).exists():
            msg = (
                f"Trading Journal.xlsx is missing at {path_text or '<unknown path>'}. "
                "Click Sync Journal again and check the Local Master Control terminal."
            )
            result["master_journal_ok"] = False
            result["master_journal_exists"] = False
            result["master_journal_error"] = msg
            snapshot["ok"] = False
            snapshot["error"] = msg
    snapshot.update(_manual_save_state_snapshot())
    return JSONResponse(_json_safe(snapshot))


async def _run_trading_journal_sync_job() -> None:
    def _scan_trade_log_streaming(workbook_path: Path) -> Tuple[Set[str], Optional[int], Optional[str]]:
        wb = load_workbook(workbook_path, data_only=True, read_only=True)
        try:
            tl = _get_trade_log_sheet(wb, allow_legacy=False)
            header_map = _trade_log_header_map(tl)
            if "Row ID" not in header_map:
                raise RuntimeError(f"Trade Log Row ID header missing in workbook: {workbook_path}")
            ridx = header_map["Row ID"] - 1
            cidx = header_map.get("Close Time")
            cidx = cidx - 1 if cidx else None
            aidx = header_map.get("Account")
            aidx = aidx - 1 if aidx else None
            row_ids: Set[str] = set()
            latest_trade_time: Optional[int] = None
            latest_bybit_demo_close_time: Optional[int] = None
            for row in tl.iter_rows(min_row=_trade_log_data_start_row(tl), values_only=True):
                v = str((row[ridx] if ridx < len(row) else "") or "").strip()
                if v:
                    row_ids.add(v)
                if cidx is None or cidx >= len(row):
                    continue
                tsec = _canonical_trade_epoch_second(_epoch_or_iso_to_iso(row[cidx]))
                if tsec is not None and (latest_trade_time is None or tsec > latest_trade_time):
                    latest_trade_time = tsec
                if aidx is not None and aidx < len(row):
                    acct = str((row[aidx] or "")).strip()
                    if _is_bybit_demo_account_label(acct) and (latest_bybit_demo_close_time is None or tsec is not None and tsec > latest_bybit_demo_close_time):
                        latest_bybit_demo_close_time = tsec
            return row_ids, latest_trade_time, _ts_to_iso(latest_bybit_demo_close_time) if latest_bybit_demo_close_time is not None else None
        finally:
            wb.close()

    def _latest_bybit_demo_trade_log_close_iso() -> Optional[str]:
        try:
            _, _, latest = _scan_trade_log_streaming(_master_journal_path())
            return latest
        except Exception:
            return None

    def _verify_captured_rows_persisted_to_master_journal(
        captured_row_ids: List[str],
        *,
        workbook_path: Optional[Path] = None,
    ) -> Dict[str, object]:
        expected = [str(x).strip() for x in (captured_row_ids or []) if str(x).strip()]
        verify_path = Path(workbook_path or _master_journal_path())
        if not expected:
            return {
                "ok": True,
                "verification_path": str(verify_path),
                "verification_error": None,
                "workbook_row_ids_sample": [],
                "workbook_row_ids_count": 0,
                "expected_row_ids": [],
                "missing_row_ids": [],
                "persisted_row_ids": [],
                "workbook_latest_trade_time": None,
            }
        workbook_ids: Set[str] = set()
        latest_trade_time: Optional[int] = None
        verify_error: Optional[str] = None
        for _attempt in range(3):
            try:
                workbook_ids, latest_trade_time, _ = _scan_trade_log_streaming(verify_path)
                verify_error = None
                break
            except Exception as exc:
                verify_error = str(exc)
                time.sleep(0.05)
        missing = [rid for rid in expected if rid not in workbook_ids]
        persisted = [rid for rid in expected if rid in workbook_ids]
        return {
            "ok": (verify_error is None) and (len(missing) == 0),
            "verification_path": str(verify_path),
            "verification_error": verify_error,
            "workbook_row_ids_sample": sorted(workbook_ids)[:20],
            "workbook_row_ids_count": len(workbook_ids),
            "expected_row_ids": expected,
            "missing_row_ids": missing,
            "persisted_row_ids": persisted,
            "workbook_latest_trade_time": _ts_to_iso(latest_trade_time) if latest_trade_time is not None else None,
        }
    def _cb(progress: int, message: str) -> None:
        _set_trading_journal_sync_state(
            running=True,
            progress=int(progress),
            message=str(message or ""),
            stage=str((_sync_state_snapshot().get("stage") or "")),
            heartbeat_at=_utc_now_iso(),
            ok=None,
            error=None,
            result=None,
        )

    _set_trading_journal_sync_state(
        running=True,
        progress=0,
        message="Starting…",
        stage="started",
        ok=None,
        error=None,
        result=None,
        started_at=_utc_now_iso(),
        finished_at=None,
        source_mode=_trading_journal_source_mode(),
        local_dir=str(TRADING_JOURNAL_LOCAL_DIR),
    )
    _log_trading_journal_sync_event("started", source_mode=_trading_journal_source_mode(), local_dir=str(TRADING_JOURNAL_LOCAL_DIR))
    heartbeat_stop = asyncio.Event()
    async def _heartbeat() -> None:
        while not heartbeat_stop.is_set():
            await asyncio.sleep(TRADING_JOURNAL_SYNC_HEARTBEAT_SECONDS)
            st = _sync_state_snapshot()
            if not bool(st.get("running")):
                return
            _set_trading_journal_sync_state(heartbeat_at=_utc_now_iso(), stage=str(st.get("stage") or ""), message=str(st.get("message") or ""))
    hb_task = asyncio.create_task(_heartbeat())

    try:
        broker_balance_warnings: List[str] = []
        broker_account_balances: List[Dict[str, object]] = []
        broker_refresh_enabled = _trading_journal_broker_refresh_enabled()
        if broker_refresh_enabled:
            _set_trading_journal_sync_state(stage="fetching_broker_balances", message="Fetching broker balances…")
            for account_mode in ("demo", "live"):
                if account_mode == "demo" and not ENABLE_BYBIT_DEMO_JOURNAL:
                    continue
                label = "Bybit Demo" if account_mode == "demo" else "Bybit Live"
                try:
                    snapshot = await _fetch_bybit_balance_usdt(account_mode)
                    broker_account_balances.append(
                        {
                            "account": label,
                            "label": label,
                            "balance": _to_float(snapshot.get("available_usdt")),
                            "currency": "USDT",
                            "source": "bybit_wallet_balance",
                            "balance_source": "bybit_wallet_balance",
                            "account_mode": account_mode,
                            "as_of": _utc_now_iso(),
                        }
                    )
                except Exception as exc:
                    broker_balance_warnings.append(f"Bybit {account_mode} balance unavailable: {exc}")
            for account_mode in ("demo", "live"):
                label = "OANDA DEMO" if account_mode == "demo" else "OANDA LIVE"
                try:
                    summary = await _fetch_oanda_account_summary(account_mode)
                    broker_account_balances.append(
                        {
                            "account": label,
                            "label": label,
                            "balance": _to_float(summary.get("balance")),
                            "nav": _to_float(summary.get("nav")),
                            "currency": str(summary.get("currency") or "AUD"),
                            "source": "oanda_account_summary",
                            "balance_source": "oanda_account_summary",
                            "account_mode": account_mode,
                            "as_of": _utc_now_iso(),
                        }
                    )
                except Exception as exc:
                    broker_balance_warnings.append(f"OANDA {account_mode} account summary unavailable: {exc}")
        source_mode = _trading_journal_source_mode()
        if (
            source_mode == "local"
            and _trading_journal_bybit_demo_balance_anchor_enabled()
            and _trading_journal_local_excel_authoritative()
        ):
            _set_trading_journal_sync_state(stage="sanitizing_bybit_demo_workbook", message="Sanitizing Bybit Demo workbook…")
            try:
                workbook_path = _resolve_local_journal_file(BYBIT_DEMO_WORKBOOK_NAME, TRADING_JOURNAL_LOCAL_DIR)
                wb_frame = _coerce_bybit_demo_workbook_frame(
                    _read_excel_sheet_or_empty(workbook_path, BYBIT_DEMO_WORKBOOK_SHEET, BYBIT_DEMO_WORKBOOK_COLUMNS)
                )
                if _bybit_demo_workbook_has_rows_needing_balance(wb_frame):
                    try:
                        demo_snapshot = await _fetch_bybit_demo_current_balance_snapshot()
                        demo_balance = _to_float((demo_snapshot or {}).get("current_balance"))
                        if demo_balance is None:
                            broker_balance_warnings.append(
                                "Bybit demo wallet snapshot returned no numeric current_balance for workbook anchor reconstruction."
                            )
                            _record_bybit_demo_sync_status(
                                bybit_demo_balance_backfill_error=(
                                    "Bybit Demo workbook anchor reconstruction failed: wallet snapshot returned no numeric current_balance."
                                )
                            )
                        else:
                            broker_account_balances.append(
                                {
                                    "account": "Bybit Demo",
                                    "label": "Bybit Demo",
                                    "balance": demo_balance,
                                    "currency": "USDT",
                                    "source": "bybit_demo_wallet_balance_anchor",
                                    "balance_source": "bybit_demo_wallet_balance_anchor",
                                    "account_mode": "demo",
                                    "as_of": (demo_snapshot or {}).get("snapshot_at") or _utc_now_iso(),
                                }
                            )
                            await asyncio.to_thread(_sanitize_bybit_demo_local_workbook, TRADING_JOURNAL_LOCAL_DIR, demo_snapshot)
                    except Exception as exc:
                        broker_balance_warnings.append(
                            f"Bybit demo wallet snapshot unavailable for workbook anchor reconstruction: {exc}"
                        )
                        _record_bybit_demo_sync_status(
                            bybit_demo_balance_backfill_error=f"Bybit Demo workbook anchor reconstruction failed: {exc}"
                        )
            except Exception as exc:
                broker_balance_warnings.append(f"Bybit demo workbook pre-sanitize failed: {exc}")
        if broker_account_balances or broker_balance_warnings:
            _save_broker_balance_diagnostics_state(broker_account_balances, broker_balance_warnings)
        if source_mode == "local":
            _cb(25, "Importing local journal workbooks…")
        elif source_mode == "dropbox":
            _cb(25, "Importing Dropbox journal workbooks…")
        else:
            _cb(25, "Importing journal workbooks…")
        _set_trading_journal_sync_state(stage="importing_journal_workbooks")
        result = await asyncio.to_thread(_import_trading_journal_from_sources, progress_cb=_cb)
        bybit_demo = None
        bybit_live = None
        oanda_sync: Dict[str, object] = {}
        pending_rows_for_workbook: List[Dict[str, object]] = []
        bybit_demo_latest_trade_log_close_before = _latest_bybit_demo_trade_log_close_iso()
        bybit_demo_capture_default = _manual_sync_should_capture_bybit_demo_recent_history()
        bybit_demo_execution_capture_expected = bool(
            (_trading_journal_source_mode() == "master_journal")
            and (TRADING_JOURNAL_SYNC_CALCULATOR_TRADES_ON_MANUAL or bybit_demo_capture_default)
        )
        run_closed_trade_capture = bool(
            broker_refresh_enabled or TRADING_JOURNAL_SYNC_CALCULATOR_TRADES_ON_MANUAL or bybit_demo_capture_default
        )
        if run_closed_trade_capture:
            _set_trading_journal_sync_state(stage="syncing_broker_closed_pnl", message="Syncing broker closed P/L…")
            skip_demo = bool((result or {}).get("diagnostics", {}).get("bybit_demo_workbook_cleared"))
            if skip_demo:
                bybit_demo = {"ok": True, "skipped": True, "reason": "bybit_demo_workbook_cleared"}
            else:
                try:
                    bybit_demo = await _run_bybit_closed_pnl_sync(account_mode="demo", reason="manual", enforce_manual_cooldown=False)
                    if isinstance(bybit_demo, dict):
                        bybit_demo.setdefault("bybit_demo_execution_capture_expected", bybit_demo_execution_capture_expected)
                        bybit_demo.setdefault("bybit_demo_credentials_available", _bybit_demo_credentials_available())
                except Exception as exc:
                    cred_diag = describe_bybit_credentials_for("demo")
                    missing_vars: List[str] = [str(x) for x in (cred_diag.get("missing_env_vars") or [])]
                    bybit_demo = {
                        "ok": False,
                        "error": str(exc),
                        "bybit_demo_execution_capture_expected": bybit_demo_execution_capture_expected,
                        "bybit_demo_credentials_available": bool(cred_diag.get("credentials_available")),
                        "bybit_demo_credential_source": str(cred_diag.get("key_source") or "NONE"),
                        "bybit_demo_missing_env_vars": missing_vars,
                        "base_url": cred_diag.get("base_url"),
                        "execution_rows_seen": 0,
                        "latest_execution_time": None,
                    }
            try:
                bybit_live = await _run_bybit_closed_pnl_sync(account_mode="live", reason="manual", enforce_manual_cooldown=False)
            except Exception as exc:
                bybit_live = {"ok": False, "error": str(exc)}
            for acct in ("demo", "live"):
                try:
                    oanda_sync[acct] = await _recover_oanda_recent_fills(acct)
                except Exception as exc:
                    oanda_sync[acct] = {"ok": False, "error": str(exc)}
        for payload in [bybit_demo, bybit_live, *list(oanda_sync.values())]:
            if not isinstance(payload, dict):
                continue
            for row in (payload.get("captured_rows") or []):
                if isinstance(row, dict) and str(row.get("id") or "").strip():
                    pending_rows_for_workbook.append(dict(row))
        # Explicitly bridge Bybit Demo manual captured rows for master_journal single-file sync.
        if (
            isinstance(bybit_demo, dict)
            and _allow_manual_bybit_demo_broker_rows_in_single_file(account_mode="demo", reason="manual")
        ):
            for row in (bybit_demo.get("captured_rows") or []):
                if not isinstance(row, dict):
                    continue
                rid = str(row.get("id") or row.get("row_id") or "").strip()
                if not rid:
                    continue
                acct = str(row.get("account_label") or row.get("account") or "").strip()
                if not _is_bybit_demo_account_label(acct):
                    continue
                if str(row.get("row_type") or "").strip().lower() != "trade":
                    continue
                pending_rows_for_workbook.append(dict(row))
        if pending_rows_for_workbook:
            deduped_pending: Dict[str, Dict[str, object]] = {}
            for row in pending_rows_for_workbook:
                if not isinstance(row, dict):
                    continue
                rid = str(row.get("id") or row.get("row_id") or "").strip()
                if rid:
                    deduped_pending[rid] = dict(row)
            pending_rows_for_workbook = list(deduped_pending.values())
        global _PENDING_MANUAL_SYNC_ROWS
        _PENDING_MANUAL_SYNC_ROWS = pending_rows_for_workbook
        if _trading_journal_local_excel_authoritative() and run_closed_trade_capture and not _master_journal_single_file_mode():
            result = await asyncio.to_thread(_import_trading_journal_from_sources, progress_cb=_cb)
        _set_trading_journal_sync_state(stage="updating_master_journal", message="Updating Trading Journal.xlsx…")
        workbook_sync = await asyncio.to_thread(_sync_master_journal_workbook, sync_caller="manual_sync")
        _PENDING_MANUAL_SYNC_ROWS = []
        if isinstance(result, dict):
            result.update(workbook_sync)
        warnings: List[str] = list((result or {}).get("warnings") or [])
        if isinstance(workbook_sync, dict) and not workbook_sync.get('master_journal_ok'):
            warnings.append(str(workbook_sync.get('master_journal_error') or 'Trading Journal workbook generation failed'))
        if isinstance(workbook_sync, dict) and workbook_sync.get("github_sync_enabled") and workbook_sync.get("github_sync_ok") is False:
            warnings.append(str(workbook_sync.get("github_sync_error") or "GitHub sync failed"))
        warnings.extend(broker_balance_warnings)
        for mode_name, mode_payload in {"demo": bybit_demo, "live": bybit_live}.items():
            if isinstance(mode_payload, dict) and mode_payload.get("warning"):
                warnings.append(str(mode_payload.get("warning")))
            if isinstance(mode_payload, dict):
                if mode_payload.get("cooldown_active"):
                    warnings.append(f"Bybit {mode_name} skipped by cooldown")
                if mode_payload.get("ok") is False:
                    warnings.append(f"Bybit {mode_name} failed: {mode_payload.get('error') or mode_payload.get('message') or 'unknown'}")
        for acct, payload in oanda_sync.items():
            if isinstance(payload, dict) and payload.get("ok") is False:
                warnings.append(f"OANDA {acct} failed: {payload.get('error') or payload.get('message') or 'unknown'}")
        verify_workbook_path = Path(
            str((workbook_sync or {}).get("master_journal_path") or _master_journal_path())
        )
        def _verify_bybit_payload_row_ids(mode_name: str, payload: Dict[str, object]) -> None:
            verification = _verify_captured_rows_persisted_to_master_journal(
                payload.get("captured_row_ids") or [],
                workbook_path=verify_workbook_path,
            )
            expected_capture = bool(payload.get("bybit_demo_execution_capture_expected")) if mode_name == "demo" else False
            creds_available = bool(payload.get("bybit_demo_credentials_available", True)) if mode_name == "demo" else True
            verified = bool(verification.get("ok"))
            if expected_capture and (not creds_available):
                verified = False
            if expected_capture and int(payload.get("execution_rows_seen") or 0) <= 0 and str(payload.get("execution_fetch_error") or payload.get("error") or "").strip():
                verified = False
            payload["final_trade_log_row_ids_verified"] = verified
            payload["missing_execution_row_ids"] = verification.get("missing_row_ids") or []
            payload["persisted_execution_row_ids"] = verification.get("persisted_row_ids") or []
            payload["workbook_latest_trade_time"] = verification.get("workbook_latest_trade_time")
            payload["verification_path"] = verification.get("verification_path")
            payload["verification_error"] = verification.get("verification_error")
            payload["workbook_row_ids_sample"] = verification.get("workbook_row_ids_sample") or []
            payload["workbook_row_ids_count"] = int(verification.get("workbook_row_ids_count") or 0)
            payload["expected_row_ids"] = verification.get("expected_row_ids") or []
            if expected_capture:
                payload.setdefault("bybit_demo_execution_capture_expected", True)
                payload.setdefault("bybit_demo_credentials_available", creds_available)
                payload.setdefault("bybit_demo_credential_source", payload.get("bybit_demo_credential_source"))
                payload.setdefault("bybit_demo_missing_env_vars", payload.get("bybit_demo_missing_env_vars") or [])
            fetch_error = str(payload.get("execution_fetch_error") or "").strip()
            if expected_capture and fetch_error and int(payload.get("execution_rows_seen") or 0) <= 0:
                payload["ok"] = False
                payload["error"] = f"Bybit Demo execution history fetch failed: {fetch_error}"
                warnings.append(str(payload["error"]))
                return
            stale_persistence_error = str(payload.get("error") or "")
            if payload["final_trade_log_row_ids_verified"] and (
                "sanitized/removed before persistence" in stale_persistence_error
                or "captured rows that were not persisted" in stale_persistence_error.lower()
            ):
                payload["missing_execution_row_ids"] = []
                payload["persisted_execution_row_ids"] = verification.get("persisted_row_ids") or []
                payload["error"] = None
                if payload.get("ok") is False:
                    payload["ok"] = True
            if (payload.get("rows_seen", 0) > 0 or expected_capture) and not payload["final_trade_log_row_ids_verified"]:
                payload["ok"] = False
                payload["error"] = (
                    f"Bybit {mode_name.title()} sync captured rows that were not persisted to Trade Log. "
                    f"captured_count={len(payload.get('captured_row_ids') or [])} "
                    f"persisted_count={len(verification.get('persisted_row_ids') or [])} "
                    f"missing_row_ids={verification.get('missing_row_ids') or []} "
                    f"verification_path={verification.get('verification_path') or ''} "
                    f"verification_error={verification.get('verification_error') or ''} "
                    f"workbook_row_ids_sample={verification.get('workbook_row_ids_sample') or []}"
                )
                if expected_capture and not creds_available:
                    payload["error"] = "Bybit Demo API credentials are not configured for local manual sync"
                warnings.append(str(payload["error"]))

        for mode_name, mode_payload in {"demo": bybit_demo, "live": bybit_live}.items():
            if isinstance(mode_payload, dict):
                _verify_bybit_payload_row_ids(mode_name, mode_payload)
        if isinstance(bybit_demo, dict):
            bybit_demo["bybit_demo_capture_enabled_reason"] = (
                "manual_master_journal_single_file_default"
                if bybit_demo_capture_default
                else ("env_manual_override" if TRADING_JOURNAL_SYNC_CALCULATOR_TRADES_ON_MANUAL else "broker_refresh_gate")
            )
            bybit_demo["bybit_demo_pending_rows_for_workbook_count"] = len(
                [r for r in pending_rows_for_workbook if _is_bybit_demo_account_label(r.get("account_label") or r.get("account"))]
            )
            bybit_demo["bybit_demo_latest_trade_log_close_before"] = bybit_demo_latest_trade_log_close_before
            bybit_demo["bybit_demo_latest_trade_log_close_after"] = _latest_bybit_demo_trade_log_close_iso()
            bybit_demo["bybit_demo_execution_rows_seen"] = int(bybit_demo.get("execution_rows_seen") or 0)
            bybit_demo["bybit_demo_captured_rows_count"] = len(bybit_demo.get("captured_row_ids") or [])
            bybit_demo["bybit_demo_missing_captured_row_ids"] = bybit_demo.get("missing_execution_row_ids") or []
        def _verify_oanda_payload_row_ids(mode_name: str, payload: Dict[str, object]) -> None:
            captured_row_ids = set(str(x).strip() for x in (payload.get("captured_row_ids") or []) if str(x).strip())
            if not captured_row_ids:
                payload["final_trade_log_row_ids_verified"] = True
                return
            verified = True
            try:
                wb = load_workbook(_master_journal_path(), data_only=True)
                tl = _get_trade_log_sheet(wb, allow_legacy=False)
                trade_headers = _trade_log_header_map(tl)
                ridx = trade_headers.get("Row ID")
                workbook_ids = set()
                if ridx:
                    for rr in range(_trade_log_data_start_row(tl), tl.max_row + 1):
                        v = str(tl.cell(rr, ridx).value or "").strip()
                        if v:
                            workbook_ids.add(v)
                verified = captured_row_ids.issubset(workbook_ids)
            except Exception:
                verified = False
            payload["final_trade_log_row_ids_verified"] = verified
            if payload.get("rows_seen", 0) > 0 and not verified:
                payload["ok"] = False
                payload["error"] = f"OANDA {mode_name.title()} sync captured rows that were not persisted to Trade Log."
                warnings.append(str(payload["error"]))

        for mode_name, mode_payload in oanda_sync.items():
            if isinstance(mode_payload, dict):
                _verify_oanda_payload_row_ids(mode_name, mode_payload)
        if isinstance(result, dict):
            result["bybit"] = {"demo": bybit_demo, "live": bybit_live}
            result["oanda"] = oanda_sync
            result["warnings"] = list(dict.fromkeys([str(w) for w in warnings if str(w).strip()]))
        diagnostics = result.get("diagnostics") if isinstance(result, dict) else {}
        rows_by_asset_class = diagnostics.get("rows_by_asset_class") if isinstance(diagnostics, dict) else {}
        broker_payloads = [p for p in [bybit_demo, bybit_live, *list(oanda_sync.values())] if isinstance(p, dict)]
        def _is_optional_config_warning(payload: Dict[str, object]) -> bool:
            msg = str(payload.get("error") or payload.get("message") or "").lower()
            return any(
                x in msg
                for x in [
                    "credentials are not configured",
                    "api credentials are not configured",
                    "missing_env_vars",
                    "missing env vars",
                ]
            )
        broker_failed = any(
            (p.get("ok") is False)
            and (
                (not _is_optional_config_warning(p))
                or (p.get("final_trade_log_row_ids_verified") is False and bool(p.get("missing_execution_row_ids") or p.get("missing_row_ids")))
            )
            for p in broker_payloads
        )
        local_workbook_failed = any(
            any(tok in str(p.get("error") or p.get("message") or "").lower() for tok in ["permission", "openpyxl", "os.replace", "workbook", "excel", "failed to read workbook", "failed to write"])
            for p in broker_payloads
        ) or any("workbook" in str(w).lower() for w in warnings)
        has_warnings = bool(warnings)
        base_ok = bool(result.get("ok", True)) if isinstance(result, dict) else True
        github_sync_failed = bool(
            isinstance(workbook_sync, dict)
            and workbook_sync.get("github_sync_enabled")
            and workbook_sync.get("github_sync_ok") is False
        )
        ok_flag = bool(base_ok and not broker_failed and not local_workbook_failed)
        if not ok_flag:
            msg = f"Failed: {str((result or {}).get('message') or (result or {}).get('error') or '; '.join(warnings) or 'sync failed')}"
        elif has_warnings:
            msg = "Completed with warnings"
        else:
            if isinstance(workbook_sync, dict) and workbook_sync.get("github_sync_enabled"):
                msg = (
                    "Synced Trading Journal.xlsx and pushed to GitHub."
                    if not workbook_sync.get("github_sync_noop")
                    else "Trading Journal.xlsx is up to date; no GitHub changes to push."
                )
            else:
                msg = "Trading Journal.xlsx synced. GitHub sync disabled."
        _set_trading_journal_sync_state(
            running=False,
            progress=100,
            message=msg,
            ok=ok_flag,
            error=None if ok_flag else msg,
            result=result,
            rows_imported=int((result or {}).get("rows_imported") or 0),
            rows_by_asset_class=rows_by_asset_class if isinstance(rows_by_asset_class, dict) else {},
            local_workbooks_seen=int((result or {}).get("local_workbooks_seen") or 0),
            dropbox_workbooks_seen=int((result or {}).get("dropbox_workbooks_seen") or 0),
            source_mode=_trading_journal_source_mode(),
            local_dir=str(TRADING_JOURNAL_LOCAL_DIR),
            finished_at=_utc_now_iso(),
        )
        started_dt = _parse_iso_datetime(_sync_state_snapshot().get("started_at"))
        elapsed = max(0.0, (datetime.now(timezone.utc) - started_dt).total_seconds()) if started_dt else 0.0
        _log_trading_journal_sync_event("completed", ok=ok_flag, elapsed_seconds=elapsed, message=msg)
    except Exception as exc:
        _set_trading_journal_sync_state(
            running=False,
            progress=100,
            message=f"Failed: {exc}",
            ok=False,
            error=str(exc),
            result=None,
            rows_imported=0,
            rows_by_asset_class={},
            local_workbooks_seen=0,
            dropbox_workbooks_seen=0,
            source_mode=_trading_journal_source_mode(),
            local_dir=str(TRADING_JOURNAL_LOCAL_DIR),
            finished_at=_utc_now_iso(),
        )
        _log_trading_journal_sync_event("failed", error=str(exc), error_type=type(exc).__name__)
    finally:
        heartbeat_stop.set()
        hb_task.cancel()


def _master_journal_active_sync_payload(path: Path, sync_id: str, caller: str) -> Dict[str, object]:
    active = dict(MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE)
    started_epoch = _to_float(active.get("started_epoch"))
    elapsed = max(0.0, time.time() - started_epoch) if started_epoch is not None else 0.0
    active_sync_id = str(active.get("sync_id") or "")
    active_caller = str(active.get("caller") or "")
    active_path = str(active.get("path") or "")
    return {
        "ok": False,
        "master_journal_ok": False,
        "master_journal_path": str(path),
        "master_journal_exists": path.exists(),
        "master_journal_error": "Trading Journal workbook sync is already running.",
        "master_journal_error_type": "MASTER_JOURNAL_SYNC_IN_PROGRESS",
        "code": "MASTER_JOURNAL_SYNC_IN_PROGRESS",
        "status_code": 409,
        "sync_id": sync_id,
        "sync_caller": caller,
        "active_sync": active,
        "active_sync_id": active_sync_id,
        "active_caller": active_caller,
        "active_path": active_path,
        "active_elapsed_seconds": round(elapsed, 3),
        "diagnostics": {"workbook_sync_substage_timings": {}},
    }


class _NonAuthoritativeSnapshotShrinkError(RuntimeError):
    def __init__(self, diagnostics: Dict[str, object]):
        self.diagnostics = dict(diagnostics)
        super().__init__(
            "Trading Journal sync blocked a destructive non-authoritative snapshot "
            f"shrink (existing_trades={diagnostics.get('existing_trade_rows')}, "
            f"incoming_trades={diagnostics.get('incoming_trade_rows')}, "
            f"retained_ratio={diagnostics.get('effective_retained_ratio')}). "
            "Restore the complete journal source, or explicitly use local/master_journal "
            "authoritative mode for an intentional replacement."
        )


def _existing_master_journal_trade_population(path: Path) -> Dict[str, object]:
    population: Dict[str, object] = {
        "trade_rows": 0,
        "trade_row_ids": set(),
        "inspection_error": None,
    }
    if not path.exists():
        return population
    try:
        wb = load_workbook(path, data_only=True, read_only=True)
    except Exception as exc:
        population["inspection_error"] = f"Failed to open existing workbook: {exc}"
        return population
    try:
        trade_log = _get_trade_log_sheet(wb, allow_legacy=False)
        header_map = _trade_log_header_map(trade_log)
        row_id_index = int(header_map.get("Row ID") or 0) - 1
        row_type_index = int(header_map.get("Row Type") or 0) - 1
        symbol_index = int(header_map.get("Symbol") or 0) - 1
        trade_rows = 0
        trade_row_ids: Set[str] = set()
        for values in trade_log.iter_rows(
            min_row=_trade_log_data_start_row(trade_log),
            values_only=True,
        ):
            row_type = (
                str(values[row_type_index] or "").strip().lower()
                if 0 <= row_type_index < len(values)
                else ""
            )
            if row_type and row_type != "trade":
                continue
            row_id = (
                str(values[row_id_index] or "").strip()
                if 0 <= row_id_index < len(values)
                else ""
            )
            symbol = (
                str(values[symbol_index] or "").strip()
                if 0 <= symbol_index < len(values)
                else ""
            )
            if not row_id and not symbol:
                continue
            trade_rows += 1
            if row_id:
                trade_row_ids.add(row_id)
        population["trade_rows"] = trade_rows
        population["trade_row_ids"] = trade_row_ids
    except Exception as exc:
        population["inspection_error"] = (
            f"Failed to inspect existing Trade Log population: {exc}"
        )
    finally:
        wb.close()
    return population


def _non_authoritative_snapshot_shrink_guard(
    path: Path,
    snapshot: Dict[str, object],
) -> Dict[str, object]:
    source_mode = _trading_journal_source_mode()
    configured_authoritative = bool(
        _master_journal_single_file_mode()
        or _trading_journal_local_excel_authoritative()
    )
    diagnostics: Dict[str, object] = {
        "enabled": not configured_authoritative,
        "blocked": False,
        "source_mode": source_mode,
        "configured_authoritative": configured_authoritative,
        "minimum_existing_trade_rows": 10,
        "minimum_missing_trade_rows": 5,
        "minimum_retained_ratio": 0.80,
    }
    if configured_authoritative or not path.exists():
        diagnostics["reason"] = (
            "configured_authoritative_source"
            if configured_authoritative
            else "workbook_missing"
        )
        return diagnostics

    existing = _existing_master_journal_trade_population(path)
    inspection_error = str(existing.get("inspection_error") or "").strip()
    diagnostics["inspection_error"] = inspection_error or None
    if inspection_error:
        diagnostics["reason"] = "existing_workbook_population_unavailable"
        return diagnostics

    existing_count = int(existing.get("trade_rows") or 0)
    existing_ids = {
        str(row_id or "").strip()
        for row_id in (existing.get("trade_row_ids") or set())
        if str(row_id or "").strip()
    }
    incoming_rows = [
        row
        for row in (snapshot.get("items") or [])
        if isinstance(row, dict) and _row_type(row) == "trade"
    ]
    incoming_count = len(incoming_rows)
    incoming_ids = {
        str(row.get("id") or "").strip()
        for row in incoming_rows
        if str(row.get("id") or "").strip()
    }
    retained_ids = existing_ids & incoming_ids
    missing_existing_ids = existing_ids - incoming_ids
    count_retained_ratio = (
        min(1.0, incoming_count / existing_count)
        if existing_count > 0
        else 1.0
    )
    id_retained_ratio = (
        len(retained_ids) / len(existing_ids)
        if existing_ids
        else None
    )
    effective_retained_ratio = min(
        count_retained_ratio,
        id_retained_ratio if id_retained_ratio is not None else 1.0,
    )
    missing_trade_rows = max(
        max(0, existing_count - incoming_count),
        len(missing_existing_ids),
    )
    blocked = bool(
        existing_count >= 10
        and missing_trade_rows >= 5
        and effective_retained_ratio < 0.80
    )
    diagnostics.update(
        {
            "existing_trade_rows": existing_count,
            "incoming_trade_rows": incoming_count,
            "existing_trade_row_ids": len(existing_ids),
            "incoming_trade_row_ids": len(incoming_ids),
            "retained_existing_trade_row_ids": len(retained_ids),
            "missing_existing_trade_rows": missing_trade_rows,
            "count_retained_ratio": round(count_retained_ratio, 6),
            "id_retained_ratio": (
                round(id_retained_ratio, 6)
                if id_retained_ratio is not None
                else None
            ),
            "effective_retained_ratio": round(effective_retained_ratio, 6),
            "missing_existing_row_ids_sample": sorted(missing_existing_ids)[:20],
            "blocked": blocked,
            "reason": (
                "destructive_non_authoritative_snapshot_shrink"
                if blocked
                else "population_retained"
            ),
        }
    )
    return diagnostics


def _reserve_master_journal_workbook_sync(path: Path, sync_id: str, caller: str) -> Optional[Dict[str, object]]:
    if not MASTER_JOURNAL_WORKBOOK_SYNC_LOCK.acquire(blocking=False):
        APP_LOGGER.warning(
            "master_journal_workbook_sync_rejected sync_id=%s caller=%s active_sync_id=%s active_caller=%s",
            sync_id, caller, MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.get("sync_id"), MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.get("caller"),
        )
        return _master_journal_active_sync_payload(path, sync_id, caller)
    owner_thread_id = threading.get_ident()
    if (
        MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE
        and int(MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.get("owner_thread_id") or -1)
        == owner_thread_id
    ):
        MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE["depth"] = int(
            MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.get("depth") or 1
        ) + 1
        return None
    MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.clear()
    MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.update({
        "sync_id": sync_id,
        "caller": caller,
        "path": str(path),
        "started_at": _utc_now_iso(),
        "started_epoch": time.time(),
        "owner_thread_id": owner_thread_id,
        "depth": 1,
    })
    return None


def _release_master_journal_workbook_sync() -> None:
    depth = int(MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.get("depth") or 1)
    if depth > 1:
        MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE["depth"] = depth - 1
    else:
        MASTER_JOURNAL_WORKBOOK_SYNC_ACTIVE.clear()
    MASTER_JOURNAL_WORKBOOK_SYNC_LOCK.release()


def _sync_master_journal_workbook(*, defer_github_sync: bool = False, expected_survivor_row_ids: Optional[List[str]] = None, prebuilt_snapshot: Optional[Dict[str, object]] = None, sync_caller: Optional[str] = None, sync_id: Optional[str] = None) -> Dict[str, object]:
    sync_id = str(sync_id or f"mjsync-{uuid4().hex[:12]}")
    raw_caller = "" if sync_caller is None else str(sync_caller).strip()
    path = _master_journal_path()
    if not raw_caller or raw_caller.lower() == "direct":
        APP_LOGGER.error("master_journal_workbook_sync_missing_caller sync_id=%s caller=%s path=%s", sync_id, raw_caller or "<missing>", path)
        return {
            "ok": False,
            "master_journal_ok": False,
            "master_journal_path": str(path),
            "master_journal_exists": path.exists(),
            "master_journal_error": "Trading Journal workbook sync requires an explicit user/action caller.",
            "master_journal_error_type": "MASTER_JOURNAL_SYNC_CALLER_REQUIRED",
            "code": "MASTER_JOURNAL_SYNC_CALLER_REQUIRED",
            "status_code": 500,
            "sync_id": sync_id,
            "sync_caller": raw_caller,
            "diagnostics": {"workbook_sync_substage_timings": {}},
        }
    caller = raw_caller
    rejected = _reserve_master_journal_workbook_sync(path, sync_id, caller)
    if rejected is not None:
        return rejected
    APP_LOGGER.info("master_journal_workbook_sync_start sync_id=%s caller=%s path=%s prebuilt_snapshot=%s", sync_id, caller, path, isinstance(prebuilt_snapshot, dict))
    try:
        result = _sync_master_journal_workbook_unlocked(
            defer_github_sync=defer_github_sync,
            expected_survivor_row_ids=expected_survivor_row_ids,
            prebuilt_snapshot=prebuilt_snapshot,
            sync_caller=caller,
            sync_id=sync_id,
        )
        if isinstance(result, dict):
            result.setdefault("sync_id", sync_id)
            result.setdefault("sync_caller", caller)
        APP_LOGGER.info("master_journal_workbook_sync_done sync_id=%s caller=%s ok=%s snapshot_build_ran=%s", sync_id, caller, bool((result or {}).get("master_journal_ok") if isinstance(result, dict) else False), not isinstance(prebuilt_snapshot, dict))
        return result
    finally:
        _release_master_journal_workbook_sync()


def _trade_log_filter_coverage(ws) -> Dict[str, object]:
    ref = str(ws.auto_filter.ref or "") if ws.auto_filter else ""
    last_populated_row = _trade_log_last_populated_row(ws)
    result: Dict[str, object] = {
        "ref": ref,
        "last_populated_row": last_populated_row,
        "ok": False,
    }
    if not ref:
        result["reason"] = "missing"
        return result
    try:
        min_col, min_row, max_col, max_row = range_boundaries(ref)
    except Exception as exc:
        result.update({"reason": "invalid_range", "error": str(exc)})
        return result
    headers = _trade_log_header_map(ws)
    required_columns = [
        headers.get(header) for header in ("Open Time", "Close Time", "Row ID")
    ]
    expected_header_row = _trade_log_data_start_row(ws) - 1
    result.update(
        {
            "min_col": min_col,
            "min_row": min_row,
            "max_col": max_col,
            "max_row": max_row,
            "expected_header_row": expected_header_row,
        }
    )
    if min_col != 1 or min_row != expected_header_row:
        result["reason"] = "invalid_start"
        return result
    if any(column is None or column > max_col for column in required_columns):
        result["reason"] = "required_columns_excluded"
        return result
    if max_row < last_populated_row:
        result["reason"] = "populated_rows_excluded"
        return result
    result.update({"ok": True, "reason": "covered"})
    return result


def _sync_master_journal_workbook_unlocked(*, defer_github_sync: bool = False, expected_survivor_row_ids: Optional[List[str]] = None, prebuilt_snapshot: Optional[Dict[str, object]] = None, sync_caller: str = "internal", sync_id: Optional[str] = None) -> Dict[str, object]:
    path = _master_journal_path()
    tmp = path.with_suffix('.tmp.xlsx')
    created_tmp = False
    validation_warnings: List[str] = []
    snapshot_shrink_guard: Dict[str, object] = {}
    substage_timings: Dict[str, float] = {}
    _substage_t0 = time.perf_counter()
    def _finish_substage(stage: str) -> None:
        nonlocal _substage_t0
        elapsed = round(time.perf_counter() - _substage_t0, 6)
        substage_timings[stage] = elapsed
        APP_LOGGER.info("master_journal_workbook_sync_substage_done sync_id=%s caller=%s stage=%s elapsed=%.6fs", sync_id, sync_caller, stage, elapsed)
        _substage_t0 = time.perf_counter()
    for _stage in ("snapshot_build", "manual_override_read", "update_master_journal_workbook_data_only", "workbook_validation_load", "validation_trade_log", "validation_instrument_averages", "validation_calendar", "validation_reports", "validation_dashboard_balances", "validation_leaders", "final_replace", "enforce_single_file", "github_sync"):
        substage_timings.setdefault(_stage, 0.0)
    try:
        if _master_journal_single_file_mode():
            enforce_pre = _enforce_single_master_journal_xlsx(TRADING_JOURNAL_LOCAL_DIR, cleanup_known_generated=True)
            if not enforce_pre.get("ok"):
                raise RuntimeError("Unknown extra Excel files in journal directory: " + ", ".join(enforce_pre.get("unknown_extra_excel_files") or []) + ". Move legacy backups outside journal/. Keep only journal/Trading Journal.xlsx.")
            if not path.exists():
                raise FileNotFoundError("Trading Journal.xlsx is missing in master_journal single-file mode. Import history or create the workbook first.")
        if isinstance(prebuilt_snapshot, dict):
            snapshot = copy.deepcopy(prebuilt_snapshot)
        else:
            _update_trading_journal_import_status(stage="workbook_sync:snapshot_build", message="Building workbook snapshot")
            try:
                snapshot = _build_trading_journal_view_snapshot(force=True, sync_id=sync_id, sync_caller=sync_caller) or {}
            except TypeError as exc:
                msg = str(exc)
                if "unexpected keyword argument" not in msg or ("sync_id" not in msg and "sync_caller" not in msg):
                    raise
                snapshot = _build_trading_journal_view_snapshot(force=True) or {}
        source_items = [r for r in (snapshot.get("items") or []) if isinstance(r, dict)]
        source_trade_rows = [r for r in source_items if _row_type(r) == "trade"]
        _finish_substage("snapshot_build")

        manual_overrides = (
            read_master_journal_manual_overrides(path)
            if path.exists()
            else {}
        )
        _finish_substage("manual_override_read")
        normalization_input = source_items
        if (
            isinstance(manual_overrides, dict)
            and manual_overrides
            and not isinstance(prebuilt_snapshot, dict)
            and not _master_journal_single_file_mode()
        ):
            normalization_input = [
                r for r in _get_trading_journal_rows() if isinstance(r, dict)
            ]
        normalized_rows, recommendation_row_normalization = (
            _normalize_master_journal_rows(
                normalization_input,
                manual_overrides if isinstance(manual_overrides, dict) else {},
            )
        )
        if (
            int(recommendation_row_normalization.get("manual_override_rows_applied") or 0) > 0
            and not isinstance(prebuilt_snapshot, dict)
            and not _master_journal_single_file_mode()
        ):
            _set_trading_journal_rows(normalized_rows)
            snapshot = _build_manual_import_authoritative_snapshot()
            normalized_rows, rebuilt_normalization = _normalize_master_journal_rows(
                [r for r in (snapshot.get("items") or []) if isinstance(r, dict)],
                manual_overrides if isinstance(manual_overrides, dict) else {},
            )
            recommendation_row_normalization = {
                **recommendation_row_normalization,
                **rebuilt_normalization,
            }
        normalization_changed_rows = normalized_rows != source_items
        snapshot = dict(snapshot)
        snapshot["items"] = normalized_rows
        if normalization_changed_rows:
            # A manual Test override, execution de-duplication, or row repair can
            # change which trades contribute to every dashboard/report metric.
            # Keep the snapshot aggregates tied to the exact normalized rows
            # written to the workbook and used for recommendation artifacts.
            snapshot["stats"] = _compute_journal_stats_with_period_reports(
                normalized_rows,
                [
                    balance
                    for balance in (snapshot.get("balances") or [])
                    if isinstance(balance, dict)
                ],
            )
            recommendation_row_normalization["stats_recomputed"] = True
        else:
            recommendation_row_normalization["stats_recomputed"] = False
        source_items = normalized_rows
        source_trade_rows = [r for r in source_items if _row_type(r) == "trade"]

        snapshot_shrink_guard = _non_authoritative_snapshot_shrink_guard(
            path,
            snapshot,
        )
        if snapshot_shrink_guard.get("blocked"):
            raise _NonAuthoritativeSnapshotShrinkError(snapshot_shrink_guard)

        if path.exists():
            if expected_survivor_row_ids is None:
                update_result = update_master_journal_workbook_data_only(
                    path,
                    snapshot,
                    preserve_existing_layout=True,
                    publish_recommendation_assets=False,
                )
            else:
                update_result = update_master_journal_workbook_data_only(
                    path,
                    snapshot,
                    expected_survivor_row_ids=expected_survivor_row_ids,
                    preserve_existing_layout=True,
                    publish_recommendation_assets=False,
                )
            if not bool((update_result or {}).get("ok")):
                raise RuntimeError(str((update_result or {}).get("error") or "Trading Journal data-only update failed."))
            candidate_path = str((update_result or {}).get("candidate_path") or "").strip()
            if not candidate_path:
                raise RuntimeError("Trading Journal data-only update failed: candidate workbook path missing.")
            tmp = Path(candidate_path)
            created_tmp = True
            validate_path = tmp
            _finish_substage("update_master_journal_workbook_data_only")
        else:
            build_master_journal_workbook(
                snapshot,
                tmp,
                recommendation_workbook_path=path,
                publish_recommendation_assets=False,
                manual_overrides={},
            )
            created_tmp = True
            if not tmp.exists() or tmp.stat().st_size <= 0:
                raise RuntimeError("Trading Journal temporary workbook was not created.")
            validate_path = tmp
            _finish_substage("update_master_journal_workbook_data_only")

        from openpyxl import load_workbook as _load_wb
        wb = _load_wb(validate_path, data_only=True)
        _finish_substage("workbook_validation_load")
        try:
            for sheet in SHEET_ORDER:
                if sheet not in wb.sheetnames:
                    raise RuntimeError(f"Trading Journal validation failed: missing required sheet '{sheet}'.")
            trade_log = _get_trade_log_sheet(wb, allow_legacy=False)
            inst = _symbols_sheet(wb)
            cal = wb["P&L Calendar"]
            dash = _stats1_sheet(wb)
            detail_dash = _stats2_sheet(wb) or dash
            if "All Trades" in wb.sheetnames:
                raise RuntimeError("Trading Journal validation failed: legacy 'All Trades' sheet remains after migration.")
            if "_Trade Meta" in wb.sheetnames:
                raise RuntimeError("Trading Journal validation failed: '_Trade Meta' must not be present.")
            if not trade_log.auto_filter or not trade_log.auto_filter.ref:
                raise RuntimeError("Trading Journal validation failed: Trade Log filter missing.")
            trade_log_filter_coverage = _trade_log_filter_coverage(trade_log)
            if not trade_log_filter_coverage.get("ok"):
                raise RuntimeError(
                    "Trading Journal validation failed: Trade Log filter does not "
                    "cover its populated data; "
                    f"diagnostics={trade_log_filter_coverage}."
                )
            if not inst.auto_filter or not inst.auto_filter.ref:
                raise RuntimeError("Trading Journal validation failed: SYMBOLS filter missing.")
            def _is_hidden_trade_row(row: Dict[str, object]) -> bool:
                metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
                for key in ("is_hidden", "hidden", "_hidden"):
                    if _is_test_trade_value(row.get(key)) or _is_test_trade_value(metrics.get(key)):
                        return True
                return False

            validation_trade_rows = [
                _repair_or_flag_zero_trade_qty(dict(r))
                for r in (snapshot.get("items") or [])
                if isinstance(r, dict) and _row_type(r) == "trade"
            ]
            validation_trade_rows, _validation_dedupe_diagnostics = (
                _dedupe_trade_rows_by_execution(validation_trade_rows)
            )
            visible_trade_rows = [
                row for row in validation_trade_rows
                if not _is_hidden_trade_row(row)
            ]
            crypto_zero_qty_ids: List[str] = []
            fx_zero_qty_ids: List[str] = []
            for row in visible_trade_rows:
                qty = _to_float(row.get("qty"))
                if qty != 0:
                    continue
                acct = str(row.get("account") or row.get("account_label") or "").upper()
                sym = str(row.get("symbol") or "").upper()
                rid = str(row.get("id") or sym or "?")
                is_fx = any(x in acct for x in ("OANDA", "PEPPERSTONE")) or ("/" in sym and len(sym) == 7)
                if is_fx:
                    fx_zero_qty_ids.append(rid)
                else:
                    crypto_zero_qty_ids.append(rid)
            if crypto_zero_qty_ids:
                raise RuntimeError(
                    "Trading Journal validation failed: unrepaired crypto Qty=0 rows detected "
                    f"(sample row IDs: {', '.join(crypto_zero_qty_ids[:5])})."
                )
            workbook_row_ids: Set[str] = set()
            if visible_trade_rows:
                trade_headers = _trade_log_header_map(trade_log)
                trade_data_start = _trade_log_data_start_row(trade_log)
                symbol_col = trade_headers.get("Symbol")
                row_id_col = trade_headers.get("Row ID")
                if not symbol_col:
                    raise RuntimeError("Trading Journal validation failed: Trade Log Symbol column missing.")
                populated_symbol_rows = 0
                for rr in range(trade_data_start, trade_log.max_row + 1):
                    symbol = str(trade_log.cell(rr, symbol_col).value or "").strip()
                    if symbol:
                        populated_symbol_rows += 1
                    if row_id_col:
                        rid = str(trade_log.cell(rr, row_id_col).value or "").strip()
                        if rid:
                            workbook_row_ids.add(rid)
                if populated_symbol_rows <= 0:
                    raise RuntimeError("Trading Journal validation failed: Trade Log is blank despite source rows.")
                expected_ids = {str(r.get("id") or "").strip() for r in visible_trade_rows if str(r.get("id") or "").strip()}
                if _master_journal_single_file_mode() and expected_ids and (not row_id_col or not workbook_row_ids):
                    raise RuntimeError("Trading Journal validation failed: Row ID metadata is required in master_journal mode.")
                if expected_ids and not expected_ids.issubset(workbook_row_ids):
                    raise RuntimeError("Trading Journal validation failed: Trade Log row IDs do not match source snapshot.")
                open_col = trade_headers.get("Open Time")
                close_col = trade_headers.get("Close Time")
                dur_col = trade_headers.get("Trade Duration (DD:HH:MM:SS)")
                currency_cols = [trade_headers.get("Commission"), trade_headers.get("Net P/L")]
                def _trade_duration_cell_seconds(cell) -> Optional[float]:
                    value = cell.value
                    if value in (None, ""):
                        return None
                    if _is_ddhhmmss_number_format(cell.number_format):
                        parsed_ddhhmmss = _duration_ddhhmmss_cell_to_seconds(value)
                        if parsed_ddhhmmss is not None:
                            return float(parsed_ddhhmmss)
                    parsed_text = _parse_duration_text(value)
                    if parsed_text is not None:
                        return float(parsed_text)
                    parsed_ddhhmmss = _duration_ddhhmmss_cell_to_seconds(value)
                    return float(parsed_ddhhmmss) if parsed_ddhhmmss is not None else None
                for rr in range(trade_data_start, trade_log.max_row + 1):
                    if open_col:
                        ov = trade_log.cell(rr, open_col).value
                        if isinstance(ov, str) and "T" in ov:
                            raise RuntimeError("Trading Journal validation failed: Trade Log Open Time contains ISO 'T' string.")
                    if close_col:
                        cv = trade_log.cell(rr, close_col).value
                        if isinstance(cv, str) and "T" in cv:
                            raise RuntimeError("Trading Journal validation failed: Trade Log Close Time contains ISO 'T' string.")
                    if dur_col:
                        dur_cell = trade_log.cell(rr, dur_col)
                        if dur_cell.value not in (None, "") and _trade_duration_cell_seconds(dur_cell) is None:
                            raise RuntimeError("Trading Journal validation failed: Trade Log duration cells must be duration text or numeric DDHHMMSS.")
                if open_col and close_col and dur_col:
                    expected_duration_ids: Set[str] = set()
                    for row in visible_trade_rows:
                        if not _is_duration_validated_trade_row(row):
                            continue
                        rid = str(row.get("id") or "").strip()
                        if not rid:
                            continue
                        if str(row.get("open_time") or "").strip() and str(row.get("close_time") or "").strip():
                            expected_duration_ids.add(rid)
                    if expected_duration_ids and row_id_col:
                        row_lookup = {str(r.get("id") or "").strip(): r for r in visible_trade_rows if isinstance(r, dict)}
                        missing_duration_details: List[Dict[str, object]] = []
                        for rr in range(trade_data_start, trade_log.max_row + 1):
                            rid = str(trade_log.cell(rr, row_id_col).value or "").strip()
                            if rid not in expected_duration_ids:
                                continue
                            dur_cell = trade_log.cell(rr, dur_col)
                            dv = dur_cell.value
                            if _trade_duration_cell_seconds(dur_cell) is None:
                                src = row_lookup.get(rid) or {}
                                missing_duration_details.append({
                                    "row_id": rid,
                                    "row_type": _row_type(src) if isinstance(src, dict) else "",
                                    "open_time": src.get("open_time") if isinstance(src, dict) else "",
                                    "close_time": src.get("close_time") if isinstance(src, dict) else "",
                                    "duration_cell_value": dv,
                                })
                        if missing_duration_details:
                            raise RuntimeError(
                                "Trading Journal validation failed: Trade Log duration column blank/unparseable for trade rows with valid open/close timestamps "
                                f"(sample row IDs: {', '.join(str(d.get('row_id') or '') for d in missing_duration_details[:5])}; "
                                f"details={missing_duration_details[:3]})."
                            )
                for cc in [c for c in currency_cols if c]:
                    for rr in range(trade_data_start, trade_log.max_row + 1):
                        fmt = str(trade_log.cell(rr, cc).number_format or "")
                        if "UNKNOWN" in fmt:
                            col_name = next((name for name, col in trade_headers.items() if col == cc), f"col_{cc}")
                            sym = str(trade_log.cell(rr, trade_headers.get("Symbol")).value or "").strip() if trade_headers.get("Symbol") else ""
                            acct = str(trade_log.cell(rr, trade_headers.get("Account")).value or "").strip() if trade_headers.get("Account") else ""
                            row_type = str(trade_log.cell(rr, trade_headers.get("Row Type")).value or "").strip() if trade_headers.get("Row Type") else ""
                            raise RuntimeError(
                                "Trading Journal validation failed: Trade Log currency format contains UNKNOWN "
                                f"(row={rr}, column={col_name}, account={acct or '—'}, symbol={sym or '—'}, row_type={row_type or '—'})."
                            )
            stats = snapshot.get("stats") or {}
            by_instrument = stats.get("by_instrument") or []
            if by_instrument:
                instrument_header_map = {
                    str(name).strip().lower(): col
                    for name, col in _instrument_averages_header_map(inst).items()
                }
                symbol_idx = instrument_header_map.get("symbol")
                trades_idx = next(
                    (instrument_header_map[candidate] for candidate in ("trades", "total trades", "total_trades")
                     if candidate in instrument_header_map),
                    None,
                )
                if not symbol_idx or not trades_idx:
                    raise RuntimeError("Trading Journal validation failed: SYMBOLS Symbol/Trades headers missing.")
                has_instrument_data = False
                for rr in range(INSTRUMENT_AVERAGES_DATA_START_ROW, inst.max_row + 1):
                    symbol = str(inst.cell(rr, symbol_idx).value or "").strip()
                    trades = _safe_float(inst.cell(rr, trades_idx).value)
                    if symbol and trades is not None:
                        has_instrument_data = True
                        break
                if not has_instrument_data:
                    raise RuntimeError("Trading Journal validation failed: SYMBOLS is blank despite instrument stats.")
                def _inst_col(*aliases: str) -> int | None:
                    for a in aliases:
                        if a in instrument_header_map:
                            return instrument_header_map[a]
                    return None
                inst_dur_cols = [
                    _inst_col("shortest duration (dd:hh:mm:ss)", "shortest (dd:hh:mm:ss)"),
                    _inst_col("avg duration (dd:hh:mm:ss)"),
                    _inst_col("longest duration (dd:hh:mm:ss)", "longest (dd:hh:mm:ss)"),
                ]
                if all(c is not None for c in inst_dur_cols):
                    inst_dur_cols = [int(c) for c in inst_dur_cols]
                    has_any_duration_stat = any(
                        any(_safe_float(rec.get(k)) is not None for k in ("min_trade_duration_seconds", "avg_trade_duration_seconds", "max_trade_duration_seconds"))
                        for rec in by_instrument if isinstance(rec, dict)
                    )
                    any_duration_cells = False
                    def _symbols_duration_seconds(value: object, number_format: object = None) -> float | None:
                        if value in (None, ""):
                            return None
                        parsed = _parse_duration_text(value)
                        if parsed is not None:
                            return float(parsed)
                        if isinstance(value, (int, float)):
                            ddhhmmss = _duration_ddhhmmss_cell_to_seconds(value)
                            if ddhhmmss is not None:
                                return float(ddhhmmss)
                        return None
                    for rr in range(INSTRUMENT_AVERAGES_DATA_START_ROW, inst.max_row + 1):
                        vals = [inst.cell(rr, c).value for c in inst_dur_cols]
                        parsed = [
                            _symbols_duration_seconds(inst.cell(rr, c).value, inst.cell(rr, c).number_format)
                            for c in inst_dur_cols
                        ]
                        nonblank = [v for v in vals if v not in (None, "")]
                        parsed_present = [v for v in parsed if v is not None]
                        if parsed_present:
                            any_duration_cells = True
                        if nonblank and len(parsed_present) != len(nonblank):
                            raise RuntimeError("Trading Journal validation failed: SYMBOLS durations must be duration text or numeric DDHHMMSS.")
                        if len(parsed_present) == 3 and not (parsed_present[0] <= parsed_present[1] <= parsed_present[2]):
                            raise RuntimeError("Trading Journal validation failed: SYMBOLS duration order must satisfy Shortest <= Avg <= Longest.")
                    if has_any_duration_stat and not any_duration_cells:
                        raise RuntimeError("Trading Journal validation failed: SYMBOLS duration columns are blank despite duration stats.")
                net_col = instrument_header_map.get("net p/l %")
                avg_col = instrument_header_map.get("avg p/l %")
                if net_col and avg_col:
                    has_result_pct_stats = any(
                        (_safe_float(rec.get("net_result_pct")) is not None) or (_safe_float(rec.get("avg_result_pct")) is not None)
                        for rec in by_instrument if isinstance(rec, dict)
                    )
                    if has_result_pct_stats:
                        has_op = False
                        for rr in range(INSTRUMENT_AVERAGES_DATA_START_ROW, inst.max_row + 1):
                            if isinstance(inst.cell(rr, net_col).value, (int, float)) or isinstance(inst.cell(rr, avg_col).value, (int, float)):
                                has_op = True
                                break
                        if not has_op:
                            raise RuntimeError("Trading Journal validation failed: SYMBOLS Net/Avg P/L % columns are blank despite result_pct stats.")
            non_test_with_results = []
            from tools.master_journal_workbook import _as_date as _journal_as_date
            for r in visible_trade_rows:
                if _is_test_trade_value(r.get("is_test_trade")):
                    continue
                ts_value = r.get("close_time") or r.get("open_time")
                dt = _journal_as_date(ts_value) if ts_value else None
                if not dt:
                    continue
                if _safe_float(r.get("result_pct")) is None:
                    continue
                non_test_with_results.append(r)
            _finish_substage("validation_instrument_averages")
            if non_test_with_results:
                expected_year_months: Set[Tuple[int, int]] = set()
                for row in non_test_with_results:
                    ts_value = row.get("close_time") or row.get("open_time")
                    dt = _journal_as_date(ts_value) if ts_value else None
                    if dt:
                        expected_year_months.add((int(dt.year), int(dt.month)))
                missing_calendar_cells = _calendar_missing_expected_pl_cells(
                    cal,
                    expected_year_months,
                )
                if missing_calendar_cells:
                    raise RuntimeError(
                        "Trading Journal validation failed: P&L Calendar missing "
                        "expected dated P/L cells: "
                        + ", ".join(
                            f"{year:04d}-{month:02d}"
                            for year, month in missing_calendar_cells[:20]
                        )
                        + "."
                    )
            _finish_substage("validation_calendar")
            expected_reports = expected_report_sheet_names(snapshot)
            for sheet_name in expected_reports:
                if sheet_name not in wb.sheetnames:
                    raise RuntimeError(f"Trading Journal validation failed: missing required report sheet '{sheet_name}'.")
                report_ws = wb[sheet_name]
                if report_ws.max_column < 2 or report_ws.max_row < 53:
                    raise RuntimeError(f"Trading Journal validation failed: report sheet '{sheet_name}' is missing its metric layout.")
                if not str(report_ws.cell(1, 2).value or "").strip():
                    raise RuntimeError(f"Trading Journal validation failed: report sheet '{sheet_name}' has blank report headers.")
                metric_labels = [
                    str(report_ws.cell(rr, 1).value or "").strip()
                    for rr in range(2, report_ws.max_row + 1)
                ]
                required_report_labels = {
                    "Trades",
                    "Short break-even",
                    "Min drawdown",
                    "Total Commission",
                }
                missing_report_labels = sorted(required_report_labels - set(metric_labels))
                if missing_report_labels:
                    raise RuntimeError(
                        f"Trading Journal validation failed: report sheet '{sheet_name}' "
                        f"is missing required metric labels {missing_report_labels}."
                    )
            _finish_substage("validation_reports")
            balances = snapshot.get("balances") or []
            if balances:
                anchor = None
                for rr in range(1, detail_dash.max_row + 1):
                    for cc in range(1, detail_dash.max_column + 1):
                        if str(detail_dash.cell(rr, cc).value or "").strip().lower() == "account balances":
                            anchor = (rr, cc)
                            break
                    if anchor:
                        break
                if not anchor:
                    raise RuntimeError("Trading Journal validation failed: Account Balances section anchor missing.")
                header_row = None
                header_map: Dict[str, int] = {}
                for rr in range(anchor[0] + 1, min(detail_dash.max_row + 1, anchor[0] + 12)):
                    row_map: Dict[str, int] = {}
                    for cc in range(anchor[1], min(detail_dash.max_column + 1, anchor[1] + 8)):
                        token = str(detail_dash.cell(rr, cc).value or "").strip().lower()
                        if token in {"account", "balance", "currency", "as of", "as_of"}:
                            if token == "as_of":
                                token = "as of"
                            row_map[token] = cc
                    if {"account", "balance", "currency"}.issubset(set(row_map.keys())):
                        header_row = rr
                        header_map = row_map
                        break
                if not header_row:
                    raise RuntimeError("Trading Journal validation failed: Account Balances headers missing.")
                canonical_balances = _canonicalize_and_dedupe_balances([b for b in balances if isinstance(b, dict)])
                expected_balances: Dict[str, Dict[str, object]] = {}
                for b in canonical_balances:
                    if not isinstance(b, dict):
                        continue
                    account_label = str(b.get("account_label") or b.get("account") or "").strip()
                    if not account_label:
                        continue
                    expected_balances[account_label.upper()] = b
                actual_rows: Dict[str, Dict[str, object]] = {}
                for rr in range(header_row + 1, min(detail_dash.max_row + 1, header_row + 80)):
                    account = str(detail_dash.cell(rr, header_map["account"]).value or "").strip()
                    if not account:
                        continue
                    actual_rows[account.upper()] = {
                        "row": rr,
                        "account": account,
                        "balance": detail_dash.cell(rr, header_map["balance"]).value,
                        "currency": str(detail_dash.cell(rr, header_map["currency"]).value or "").strip(),
                    }
                nonnumeric: List[str] = []
                nonnumeric_skipped: List[str] = []
                mismatches: List[str] = []
                for account_key, expected in expected_balances.items():
                    expected_balance = _to_float(expected.get("balance"))
                    expected_currency = str(expected.get("currency") or "").strip()
                    expected_source = str(expected.get("balance_source") or expected.get("source") or "unknown")
                    actual = actual_rows.get(account_key)
                    if actual is None:
                        mismatches.append(f"{account_key}: missing account row; expected={expected_balance} {expected_currency} source={expected_source}")
                        continue
                    actual_balance = _to_float(actual.get("balance"))
                    actual_currency = str(actual.get("currency") or "").strip()
                    if expected_balance is None or actual_balance is None:
                        # Non-authoritative timeline placeholders should not block Trade Log persistence.
                        if expected_balance is None and str(expected_source).strip().lower() == "timeline_missing":
                            nonnumeric_skipped.append(
                                f"{actual.get('account')}: expected_balance={expected_balance}, actual_balance={actual.get('balance')}, expected_currency={expected_currency}, actual_currency={actual_currency}, balance_source={expected_source}"
                            )
                            continue
                        nonnumeric.append(
                            f"{actual.get('account')}: expected_balance={expected_balance}, actual_balance={actual.get('balance')}, expected_currency={expected_currency}, actual_currency={actual_currency}, balance_source={expected_source}"
                        )
                        continue
                    if abs(actual_balance - expected_balance) > 1e-9 or actual_currency.upper() != expected_currency.upper():
                        mismatches.append(
                            f"{actual.get('account')}: expected_balance={expected_balance}, actual_balance={actual_balance}, expected_currency={expected_currency}, actual_currency={actual_currency}, balance_source={expected_source}"
                        )
                if nonnumeric:
                    raise RuntimeError("Trading Journal validation failed: Account Balances missing numeric values: " + " | ".join(nonnumeric[:20]))
                if nonnumeric_skipped:
                    validation_warnings.append(
                        "Account balance validation skipped for non-authoritative timeline_missing entries: "
                        + " | ".join(nonnumeric_skipped[:20])
                    )
                if mismatches:
                    missing_expected_ids: List[str] = []
                    if expected_survivor_row_ids:
                        expected_set = {str(rid or "").strip() for rid in expected_survivor_row_ids if str(rid or "").strip()}
                        if expected_set:
                            missing_expected_ids = sorted([rid for rid in expected_set if rid not in workbook_row_ids])
                    if missing_expected_ids:
                        raise RuntimeError(
                            "Trading Journal validation failed: expected imported row IDs missing from Trade Log before balance validation. "
                            f"missing_row_ids={missing_expected_ids[:20]}"
                        )
                    bybit_demo_trade_rows: List[Dict[str, object]] = []
                    debug_headers = _trade_log_header_map(trade_log)
                    debug_data_start = _trade_log_data_start_row(trade_log)
                    acct_col = debug_headers.get("Account")
                    sym_col = debug_headers.get("Symbol")
                    rid_col = debug_headers.get("Row ID")
                    close_col = debug_headers.get("Close Time")
                    if acct_col and rid_col:
                        for rr in range(debug_data_start, trade_log.max_row + 1):
                            acct_val = str(trade_log.cell(rr, acct_col).value or "").strip()
                            if acct_val.lower() != "bybit demo":
                                continue
                            bybit_demo_trade_rows.append({
                                "row_id": str(trade_log.cell(rr, rid_col).value or "").strip(),
                                "symbol": str(trade_log.cell(rr, sym_col).value or "").strip() if sym_col else "",
                                "close_time": str(trade_log.cell(rr, close_col).value or "").strip() if close_col else "",
                            })
                    snapshot_bybit_demo_rows = [
                        {
                            "row_id": str(r.get("id") or "").strip(),
                            "symbol": str(r.get("symbol") or "").strip(),
                            "close_time": str(r.get("close_time") or "").strip(),
                        }
                        for r in visible_trade_rows
                        if str(r.get("account") or r.get("account_label") or "").strip().lower() == "bybit demo"
                    ]
                    raise RuntimeError(
                        "Trading Journal validation failed: Account Balances mismatch vs snapshot: "
                        + " | ".join(mismatches[:20])
                        + f" | candidate_bybit_demo_rows={bybit_demo_trade_rows[-5:]}"
                        + f" | snapshot_bybit_demo_rows={snapshot_bybit_demo_rows[-5:]}"
                    )
            _finish_substage("validation_dashboard_balances")
            leaders = ((stats.get("groups") or {}).get("leaders") or {})
            expected_payloads = {
                label: (leaders.get(key) or {}) for label, key in LEADER_LABEL_TO_KEY.items()
                if isinstance(leaders.get(key), dict) and any((leaders.get(key) or {}).get(k) is not None for k in ("symbol", "wins", "losses", "trades", "total_trades"))
            }
            if expected_payloads:
                _, header_map, metric_rows, _ = _find_instrument_leaders_table(detail_dash)
                metric_rows_normalized = {str(label or "").strip().lower(): row_idx for label, row_idx in (metric_rows or {}).items()}
                if not header_map:
                    validation_warnings.append("Instrument leaders validation skipped: optional Instrument Leaders section/header is missing.")
                    expected_payloads = {}
                present_expected_payloads = {label: payload for label, payload in expected_payloads.items() if metric_rows.get(label) or metric_rows_normalized.get(label)}
                if expected_payloads and not present_expected_payloads:
                    validation_warnings.append("Instrument leaders validation skipped: optional Instrument Leaders section has no recognized metric rows.")
                for metric_label in present_expected_payloads:
                    row_idx = metric_rows.get(metric_label) or metric_rows_normalized.get(metric_label)
                    symbol = str(detail_dash.cell(row_idx, header_map["symbol"]).value or "").strip()
                    trades_num = _safe_float(detail_dash.cell(row_idx, header_map["trades"]).value)
                    if not symbol or symbol == "—" or trades_num is None:
                        raise RuntimeError(f"Trading Journal validation failed: Instrument leaders row '{metric_label}' is present but blank/invalid; user-deleted rows are skipped.")
            _finish_substage("validation_leaders")
        finally:
            wb.close()

        if created_tmp:
            lock_status = _master_journal_lock_status(path)
            if lock_status.get("locked"):
                payload = _excel_workbook_open_payload(extra={"master_journal_path": str(path), "master_journal_ok": False, "master_journal_exists": path.exists(), "lock_status": lock_status, "diagnostics": {"workbook_sync_substage_timings": dict(substage_timings)}})
                payload["master_journal_error"] = payload["message"]
                return payload
            try:
                os.replace(tmp, path)
            except Exception as replace_exc:
                if _is_workbook_lock_exception(replace_exc):
                    payload = _excel_workbook_open_payload(extra={"master_journal_path": str(path), "master_journal_ok": False, "master_journal_exists": path.exists(), "replace_error": str(replace_exc), "diagnostics": {"workbook_sync_substage_timings": dict(substage_timings)}})
                    payload["master_journal_error"] = payload["message"]
                    payload["master_journal_error_type"] = type(replace_exc).__name__
                    return payload
                raise
        _finish_substage("final_replace")
        if not path.exists() or path.stat().st_size <= 0:
            raise RuntimeError("Trading Journal.xlsx was not created.")
        if _master_journal_single_file_mode():
            enforce_post = _enforce_single_master_journal_xlsx(TRADING_JOURNAL_LOCAL_DIR, cleanup_known_generated=True)
            if not enforce_post.get("ok"):
                raise RuntimeError("Unknown extra Excel files in journal directory after workbook sync: " + ", ".join(enforce_post.get("unknown_extra_excel_files") or []) + ". Move legacy backups outside journal/. Keep only journal/Trading Journal.xlsx.")
        _finish_substage("enforce_single_file")
        from tools.master_journal_workbook import (
            _prepare_recommendation_chart_bundle,
            _publish_recommendation_chart_bundle,
        )
        recommendation_chart_bundle = _prepare_recommendation_chart_bundle(
            source_items,
            path,
        )
        recommendation_chart_asset_directory = (
            _publish_recommendation_chart_bundle(recommendation_chart_bundle)
        )
        size = path.stat().st_size
        payload = {
            'master_journal_ok': True,
            'master_journal_path': str(path),
            'master_journal_exists': True,
            'master_journal_size_bytes': int(size),
            'master_journal_updated_at': _utc_now_iso(),
            'source_trade_rows': len(source_trade_rows),
            'source_rows_total': len(source_items),
            'master_journal_diagnostics': {
                'source_rows_total': len(source_items),
                'source_trade_rows': len(source_trade_rows),
                'source_balances': len(snapshot.get('balances') or []),
                'recommendation_row_normalization': dict(
                    recommendation_row_normalization
                ),
                'snapshot_shrink_guard': dict(snapshot_shrink_guard),
                'workbook_sync_substage_timings': dict(substage_timings),
                'recommendation_chart_asset_directory': str(
                    recommendation_chart_asset_directory
                ),
            },
        }
        if validation_warnings:
            payload['master_journal_warnings'] = list(validation_warnings)
        if _master_journal_single_file_mode():
            enforce_github = _enforce_single_master_journal_xlsx(TRADING_JOURNAL_LOCAL_DIR, cleanup_known_generated=True)
            if not enforce_github.get("ok"):
                raise RuntimeError("Unknown extra Excel files in journal directory before GitHub sync: " + ", ".join(enforce_github.get("unknown_extra_excel_files") or []) + ". Move legacy backups outside journal/. Keep only journal/Trading Journal.xlsx.")
        if defer_github_sync:
            payload.update({"github_sync_enabled": _trading_journal_github_sync_enabled(), "github_sync_ok": None, "github_sync_deferred": True})
        else:
            payload.update(_sync_journal_excel_files_to_github(path))
        _finish_substage("github_sync")
        payload["ok"] = bool(payload.get("master_journal_ok")) and payload.get("github_sync_ok") is not False
        return payload
    except Exception as exc:
        try:
            if created_tmp and tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        if _is_workbook_lock_exception(exc):
            payload = _excel_workbook_open_payload(extra={
                'master_journal_path': str(path),
                'master_journal_ok': False,
                'master_journal_exists': path.exists(),
                'master_journal_error': str(exc),
                'master_journal_error_type': type(exc).__name__,
                'diagnostics': {'workbook_sync_substage_timings': dict(substage_timings)},
            })
            return payload
        failure_diagnostics: Dict[str, object] = {
            'workbook_sync_substage_timings': dict(substage_timings),
        }
        if snapshot_shrink_guard:
            failure_diagnostics['snapshot_shrink_guard'] = dict(
                snapshot_shrink_guard
            )
        payload = {
            'ok': False,
            'master_journal_ok': False,
            'master_journal_path': str(path),
            'master_journal_exists': path.exists(),
            'master_journal_error': str(exc),
            'master_journal_error_type': type(exc).__name__,
            'diagnostics': failure_diagnostics,
        }
        if isinstance(exc, _NonAuthoritativeSnapshotShrinkError):
            payload.update({
                'code': 'NON_AUTHORITATIVE_SNAPSHOT_SHRINK_BLOCKED',
                'status_code': 409,
                'master_journal_diagnostics': failure_diagnostics,
            })
        return payload

def _trading_journal_github_sync_enabled() -> bool:
    raw = str(os.getenv("TRADING_JOURNAL_GITHUB_SYNC_ENABLED", "") or "").strip().lower()
    if raw in {"1", "true", "yes", "on"}:
        return not _is_render_env()
    if raw in {"0", "false", "no", "off"}:
        return False
    if _is_render_env():
        return False
    return APP_PROFILE == "local"


def _repo_root_for_journal_path(path: Path) -> Path:
    _ = path
    return BASE_DIR


def _run_git_command(args: List[str], cwd: Path, timeout_s: int) -> Tuple[int, str, str]:
    try:
        cp = subprocess.run(
            ["git", *args],
            cwd=str(cwd),
            capture_output=True,
            text=True,
            timeout=max(1, int(timeout_s)),
            shell=False,
        )
        return int(cp.returncode), str(cp.stdout or ""), str(cp.stderr or "")
    except Exception as exc:
        return 1, "", str(exc)


def _legacy_master_journal_tracked_and_missing(repo_root: Path, timeout_s: int) -> bool:
    legacy_rel = "journal/Master Journal.xlsx"
    legacy_abs = (repo_root / legacy_rel).resolve()
    if legacy_abs.exists():
        return False
    code, _, _ = _run_git_command(["ls-files", "--error-unmatch", "--", legacy_rel], repo_root, timeout_s)
    return code == 0


def _repo_state_files_for_github(master_path: Path, timeout_s: int = 60) -> List[Path]:
    repo_root = _repo_root_for_journal_path(master_path).resolve()
    master_resolved = master_path.expanduser().resolve()
    recommendation_asset_root = (
        master_resolved.parent
        / f"{master_resolved.stem}.assets"
        / "recommendations"
    ).resolve()
    allowlist = [
        master_resolved,
        repo_root / "journal" / "Trading Journal.xlsx",
    ]
    files: List[Path] = []
    seen: Set[Path] = set()
    for p in allowlist:
        rp = p.expanduser().resolve()
        try:
            rp.relative_to(repo_root)
        except Exception:
            continue
        if rp.exists() and rp.is_file():
            if rp in seen:
                continue
            seen.add(rp)
            files.append(rp)
    try:
        recommendation_asset_rel = str(
            recommendation_asset_root.relative_to(repo_root)
        ).replace("\\", "/")
    except ValueError:
        recommendation_asset_rel = ""
    if recommendation_asset_rel:
        for asset in (
            sorted(recommendation_asset_root.rglob("*.html"))
            if recommendation_asset_root.is_dir()
            else []
        ):
            resolved_asset = asset.resolve()
            if resolved_asset in seen:
                continue
            seen.add(resolved_asset)
            files.append(resolved_asset)
        code, tracked_output, _ = _run_git_command(
            ["ls-files", "-z", "--", recommendation_asset_rel],
            repo_root,
            timeout_s,
        )
        if code == 0:
            for tracked_rel in str(tracked_output or "").split("\0"):
                normalized_rel = tracked_rel.strip().replace("\\", "/")
                if not normalized_rel.casefold().endswith(".html"):
                    continue
                tracked_path = (repo_root / normalized_rel).resolve()
                try:
                    tracked_path.relative_to(recommendation_asset_root)
                except ValueError:
                    continue
                if tracked_path in seen:
                    continue
                seen.add(tracked_path)
                files.append(tracked_path)
    if _legacy_master_journal_tracked_and_missing(repo_root, timeout_s):
        files.append((repo_root / "journal" / "Master Journal.xlsx").resolve())
    return files


def _git_add_eligible_repo_state_files(
    repo_root: Path,
    files: Iterable[Path],
    timeout_s: int,
) -> Tuple[List[Path], str]:
    root = repo_root.resolve()
    candidates: List[Tuple[str, Path]] = []
    seen: Set[str] = set()
    for path in files:
        resolved = path.expanduser().resolve()
        try:
            rel = str(resolved.relative_to(root)).replace("\\", "/")
        except Exception:
            continue
        if not rel or rel in seen:
            continue
        seen.add(rel)
        candidates.append((rel, resolved))
    if not candidates:
        return [], ""

    code, out, err = _run_git_command(
        [
            "ls-files",
            "-z",
            "--cached",
            "--others",
            "--exclude-standard",
            "--",
            *[rel for rel, _ in candidates],
        ],
        root,
        timeout_s,
    )
    if code != 0:
        return [], err.strip() or "git ls-files eligibility check failed"
    eligible_rel = {
        item.replace("\\", "/")
        for item in str(out or "").split("\0")
        if item
    }
    return [
        path
        for rel, path in candidates
        if rel in eligible_rel
    ], ""


def _sync_journal_excel_files_to_github(master_path: Path) -> Dict[str, object]:
    enabled = _trading_journal_github_sync_enabled()
    remote = str(os.getenv("TRADING_JOURNAL_GITHUB_SYNC_REMOTE", "origin") or "origin").strip() or "origin"
    requested_branch = str(os.getenv("TRADING_JOURNAL_GITHUB_SYNC_BRANCH", "") or "").strip()
    timeout_s = int(str(os.getenv("TRADING_JOURNAL_GITHUB_SYNC_TIMEOUT_SECONDS", "60") or "60").strip() or "60")
    base = {
        "github_sync_enabled": bool(enabled),
        "github_sync_ok": True,
        "github_sync_noop": True,
        "github_sync_remote": remote,
        "github_sync_branch": requested_branch,
        "github_sync_commit": "",
        "github_sync_files": [],
        "github_sync_error": "",
        "github_sync_error_type": "",
        "github_sync_verified": False,
    }
    if not enabled:
        return base
    repo_root = _repo_root_for_journal_path(master_path)
    if not (repo_root / ".git").exists():
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": "local repo is not a Git checkout.", "github_sync_error_type": "NotGitRepo"}
    files = _repo_state_files_for_github(master_path, timeout_s=timeout_s)
    if not files:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": "No eligible repo state files found to sync.", "github_sync_error_type": "NoEligibleFiles"}
    code, _, err = _run_git_command(["--version"], repo_root, timeout_s)
    if code != 0:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Git is unavailable: {err.strip()}", "github_sync_error_type": "GitNotInstalled"}
    files, eligibility_error = _git_add_eligible_repo_state_files(
        repo_root,
        files,
        timeout_s,
    )
    if eligibility_error:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Failed to filter Git-eligible journal files: {eligibility_error}", "github_sync_error_type": "GitEligibilityFailed"}
    rel_files = [str(p.relative_to(repo_root)).replace("\\", "/") for p in files]
    base["github_sync_files"] = rel_files
    if not rel_files:
        return base
    branch = requested_branch
    if not branch:
        code, out, err = _run_git_command(["rev-parse", "--abbrev-ref", "HEAD"], repo_root, timeout_s)
        if code != 0:
            return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Failed to detect branch: {err.strip()}", "github_sync_error_type": "BranchDetectFailed"}
        branch = out.strip()
        if branch == "HEAD" or not branch:
            return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": "Git branch is detached (HEAD); set TRADING_JOURNAL_GITHUB_SYNC_BRANCH.", "github_sync_error_type": "DetachedHead"}
    base["github_sync_branch"] = branch
    code, _, err = _run_git_command(["remote", "get-url", remote], repo_root, timeout_s)
    if code != 0:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Git remote '{remote}' is not configured: {err.strip()}", "github_sync_error_type": "RemoteMissing"}

    code, out, err = _run_git_command(
        [
            "status",
            "--porcelain",
            "--untracked-files=all",
            "--",
            *rel_files,
        ],
        repo_root,
        timeout_s,
    )
    if code != 0:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Failed to inspect journal changes: {err.strip()}", "github_sync_error_type": "GitStatusFailed"}
    if not out.strip():
        code, local_head, err = _run_git_command(["rev-parse", "HEAD"], repo_root, timeout_s)
        if code != 0:
            return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Failed to inspect local HEAD: {err.strip()}", "github_sync_error_type": "HeadInspectFailed"}
        code, remote_out, err = _run_git_command(["ls-remote", "--heads", remote, f"refs/heads/{branch}"], repo_root, timeout_s)
        remote_head = remote_out.split()[0] if code == 0 and remote_out.split() else ""
        if code == 0 and remote_head == local_head.strip():
            return {**base, "github_sync_verified": True}
        code, _, err = _run_git_command(["push", remote, f"HEAD:{branch}"], repo_root, timeout_s)
        if code != 0:
            return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Git push retry failed: {err.strip()}", "github_sync_error_type": "GitPushFailed"}
        return {**base, "github_sync_noop": False, "github_sync_verified": True, "github_sync_commit": local_head.strip()[:12]}
    code, _, err = _run_git_command(["add", "-A", "--", *rel_files], repo_root, timeout_s)
    if code != 0:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Git add failed: {err.strip()}", "github_sync_error_type": "GitAddFailed"}
    code, _, err = _run_git_command(["diff", "--cached", "--quiet", "--", *rel_files], repo_root, timeout_s)
    if code == 0:
        return base
    if code != 1:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Failed to inspect staged journal changes: {err.strip()}", "github_sync_error_type": "GitDiffFailed"}
    code, _, err = _run_git_command(["commit", "--only", "-m", "Update trading journal state", "--", *rel_files], repo_root, timeout_s)
    if code != 0:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_error": f"Git commit failed: {err.strip()}", "github_sync_error_type": "GitCommitFailed"}
    code, out, err = _run_git_command(["rev-parse", "--short", "HEAD"], repo_root, timeout_s)
    commit = out.strip() if code == 0 else ""
    code, _, err = _run_git_command(["push", remote, f"HEAD:{branch}"], repo_root, timeout_s)
    if code != 0:
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_commit": commit, "github_sync_error": f"Git push failed: {err.strip()}", "github_sync_error_type": "GitPushFailed"}
    code, remote_out, verify_err = _run_git_command(["ls-remote", "--heads", remote, f"refs/heads/{branch}"], repo_root, timeout_s)
    remote_head = remote_out.split()[0] if code == 0 and remote_out.split() else ""
    code_head, local_head, _ = _run_git_command(["rev-parse", "HEAD"], repo_root, timeout_s)
    if code != 0 or code_head != 0 or remote_head != local_head.strip():
        return {**base, "github_sync_ok": False, "github_sync_noop": False, "github_sync_commit": commit, "github_sync_error": f"Push verification failed: {verify_err.strip() or 'origin branch does not match local HEAD'}", "github_sync_error_type": "GitPushVerificationFailed"}
    return {**base, "github_sync_ok": True, "github_sync_noop": False, "github_sync_verified": True, "github_sync_commit": commit}



def _open_path_with_os(path: Path) -> None:
    if os.name == "nt":
        os.startfile(str(path))  # type: ignore[attr-defined]
    elif sys.platform == "darwin":
        subprocess.Popen(["open", str(path)])
    else:
        subprocess.Popen(["xdg-open", str(path)])


def _cell_fill_rgb(cell: object) -> str:
    fill = getattr(cell, "fill", None)
    color = getattr(fill, "fgColor", None)
    rgb = str(getattr(color, "rgb", "") or "")
    return rgb[-6:].upper() if getattr(fill, "fill_type", None) == "solid" and rgb else ""


def _recommendation_text_like(value: object) -> bool:
    text = str(value or "").strip().casefold()
    if not text:
        return False
    return (
        text == "recommendation"
        or text.endswith("recommendation")
        or "recommendation" in text
        or text in {
            "need wins & losses",
            "reduce stop loss",
            "increase stop loss",
            "keep stop loss",
            "reduce target",
            "increase target",
            "keep target",
        }
    )


def _repair_stats1_recommendation_rows_for_excel_open(wb: object, diagnostics: Dict[str, object]) -> None:
    # Recommendation values are calculated from normalized trade rows during
    # the data-only update.  Excel-open polish has no authoritative snapshot;
    # deriving stops from rendered winner/loser averages here previously
    # replaced those values with a different algorithm and restyled the cells.
    diagnostics["stats1_recommendation_repair_skipped"] = (
        "authoritative recommendation snapshot required"
    )


def _polish_master_journal_for_excel_open(path: Path) -> Dict[str, object]:
    from tools.master_journal_workbook import (
        _normalize_generated_statistics_row_heights,
        _normalize_trade_log_row_heights,
    )

    diagnostics: Dict[str, object] = {
        "ok": True,
        "recommendation_cells_repaired": 0,
        "columns_resized": 0,
        "rows_resized": 0,
    }
    wb = load_workbook(path, keep_vba=path.suffix.lower() == ".xlsm")
    try:
        _repair_stats1_recommendation_rows_for_excel_open(wb, diagnostics)
        for ws in wb.worksheets:
            if ws.title == STATS1_SHEET:
                continue
            trade_log_data_start_row: Optional[int] = None
            if str(getattr(ws, "title", "")) in {"Trade Log", "All Trades"}:
                try:
                    trade_log_data_start_row = int(_trade_log_data_start_row(ws))
                except Exception:
                    trade_log_data_start_row = None
            recommendation_cols: Set[int] = set()
            for row in ws.iter_rows():
                for cell in row:
                    text = str(cell.value or "").strip().casefold()
                    if text in {
                        "recommendation",
                        STOP_RECOMMENDATION_HEADER.casefold(),
                        TARGET_RECOMMENDATION_HEADER.casefold(),
                    }:
                        recommendation_cols.add(int(cell.column))

            for row_idx in range(1, ws.max_row + 1):
                label = str(ws.cell(row_idx, 1).value or "").strip().casefold()
                if label == "recommendation":
                    for col_idx in range(2, ws.max_column + 1):
                        _apply_recommendation_cell_style(ws.cell(row_idx, col_idx))
                        diagnostics["recommendation_cells_repaired"] = int(diagnostics["recommendation_cells_repaired"]) + 1

            for col_idx in recommendation_cols:
                for row_idx in range(1, ws.max_row + 1):
                    cell = ws.cell(row_idx, col_idx)
                    if cell.value in (None, ""):
                        continue
                    _apply_recommendation_cell_style(cell)
                    diagnostics["recommendation_cells_repaired"] = int(diagnostics["recommendation_cells_repaired"]) + 1

            for row in ws.iter_rows():
                for cell in row:
                    if _cell_fill_rgb(cell) == "FFF2CC" and _recommendation_text_like(cell.value):
                        _apply_recommendation_cell_style(cell)
                        diagnostics["recommendation_cells_repaired"] = int(diagnostics["recommendation_cells_repaired"]) + 1

            col_widths: Dict[int, float] = {}
            row_heights: Dict[int, float] = {}
            for row in ws.iter_rows():
                for cell in row:
                    value = cell.value
                    if value is None:
                        continue
                    text = str(value)
                    if not text:
                        continue
                    lines = text.splitlines() or [text]
                    longest = max(len(part) for part in lines)
                    width = min(max(8.0, float(longest) + 2.0), 80.0)
                    col_widths[int(cell.column)] = max(col_widths.get(int(cell.column), 0.0), width)
                    line_count = max(1, len(lines))
                    if longest > 80:
                        alignment = copy.copy(cell.alignment)
                        alignment.wrap_text = True
                        cell.alignment = alignment
                        line_count = max(line_count, math.ceil(longest / 80))
                    if line_count > 1 and not (
                        trade_log_data_start_row is not None and int(cell.row) >= trade_log_data_start_row
                    ):
                        row_heights[int(cell.row)] = max(row_heights.get(int(cell.row), 0.0), min(120.0, 15.0 * min(line_count, 8)))

            for col_idx, width in col_widths.items():
                letter = get_column_letter(col_idx)
                current = ws.column_dimensions[letter].width
                next_width = round(max(float(current or 0), width), 2)
                if current != next_width:
                    ws.column_dimensions[letter].width = next_width
                    diagnostics["columns_resized"] = int(diagnostics["columns_resized"]) + 1

            for row_idx, height in row_heights.items():
                current = ws.row_dimensions[row_idx].height
                next_height = round(max(float(current or 0), height), 2)
                if current != next_height:
                    ws.row_dimensions[row_idx].height = next_height
                    diagnostics["rows_resized"] = int(diagnostics["rows_resized"]) + 1

        for ws in wb.worksheets:
            _normalize_trade_log_row_heights(ws, diagnostics)
        _normalize_generated_statistics_row_heights(
            wb,
            preserve_stats1_presentation=True,
        )

        wb.save(path)
        return diagnostics
    finally:
        wb.close()


def _master_journal_sync_ok(result: Dict[str, object] | None) -> bool:
    if not isinstance(result, dict):
        return False
    if "ok" in result:
        return bool(result.get("ok"))
    return bool(result.get("master_journal_ok")) and result.get("github_sync_ok") is not False


def _master_journal_sync_error(result: Dict[str, object] | None) -> str:
    if not isinstance(result, dict):
        return "no sync result returned"
    return str(
        result.get("error")
        or result.get("master_journal_error")
        or result.get("github_sync_error")
        or result.get("message")
        or "unknown error"
    )


def _build_manual_import_authoritative_snapshot(
    *, persist_sqlite: bool = True
) -> Dict[str, object]:
    try:
        return _build_trading_journal_view_snapshot(
            force=True,
            local_only=True,
            skip_external_balances=True,
            skip_live_account_refresh=True,
            persist_sqlite=persist_sqlite,
        ) or {}
    except TypeError as exc:
        msg = str(exc)
        if "unexpected keyword argument" not in msg or (
            "local_only" not in msg
            and "skip_external_balances" not in msg
            and "skip_live_account_refresh" not in msg
            and "persist_sqlite" not in msg
        ):
            raise
        return _build_trading_journal_view_snapshot(force=True) or {}


def _build_master_journal_verification_snapshot() -> Dict[str, object]:
    try:
        return _build_trading_journal_view_snapshot(
            force=True,
            skip_external_balances=True,
            skip_live_account_refresh=True,
            sync_caller="manual_import_verification",
        ) or {}
    except TypeError as exc:
        msg = str(exc)
        if (
            "unexpected keyword argument" not in msg
            or (
                "skip_external_balances" not in msg
                and "skip_live_account_refresh" not in msg
                and "sync_caller" not in msg
            )
        ):
            raise
        return _build_trading_journal_view_snapshot(force=True) or {}


def _is_oanda_transaction_export_balance(balance: object) -> bool:
    if not isinstance(balance, dict):
        return False
    return any(
        str(balance.get(field) or "").strip().lower()
        == "oanda_transaction_export_balance"
        for field in ("source", "balance_source")
    )


def _verify_imported_account_balance_snapshot(
    snapshot: Dict[str, object],
    expected_balance: Optional[Dict[str, object]],
    *,
    allow_equivalent_authoritative_balance: bool = False,
) -> Dict[str, object]:
    if not isinstance(expected_balance, dict):
        return {
            "ok": True,
            "balance_expected": False,
            "balance_applied": False,
            "snapshot_visible": False,
        }
    expected_value = _to_float(expected_balance.get("balance"))
    expected_label = str(
        expected_balance.get("label")
        or expected_balance.get("account")
        or expected_balance.get("account_label")
        or ""
    ).strip()
    expected_source = str(
        expected_balance.get("balance_source")
        or expected_balance.get("source")
        or ""
    ).strip()
    expected_as_of = expected_balance.get("as_of")
    target = next(
        (
            dict(item)
            for item in _snapshot_balance_items(snapshot)
            if _norm_account_key(
                item.get("label")
                or item.get("account")
                or item.get("account_label")
            )
            == _norm_account_key(expected_label)
        ),
        None,
    )
    snapshot_visible = isinstance(target, dict)
    actual_value = _to_float((target or {}).get("balance"))
    actual_source = str(
        (target or {}).get("balance_source")
        or (target or {}).get("source")
        or ""
    ).strip()
    expected_currency = str(expected_balance.get("currency") or "").strip().upper()
    actual_currency = str((target or {}).get("currency") or "").strip().upper()
    currency_matches = not expected_currency or actual_currency == expected_currency
    balance_tolerance = (
        0.005
        if allow_equivalent_authoritative_balance
        and expected_currency in {"AUD", "USD", "NZD", "CAD", "EUR", "GBP"}
        else 1e-6
    )
    value_matches = (
        expected_value is not None
        and actual_value is not None
        and abs(actual_value - expected_value) <= balance_tolerance
    )
    expected_source_key = re.sub(r"[^a-z0-9]+", "_", expected_source.lower()).strip("_")
    actual_source_key = re.sub(r"[^a-z0-9]+", "_", actual_source.lower()).strip("_")
    source_matches = not expected_source or actual_source_key == expected_source_key
    actual_as_of = (target or {}).get("as_of")
    as_of_not_older = True
    if expected_as_of not in (None, ""):
        expected_as_of_dt = _parse_iso_datetime(expected_as_of)
        actual_as_of_dt = _parse_iso_datetime(actual_as_of)
        as_of_not_older = bool(
            expected_as_of_dt is not None
            and actual_as_of_dt is not None
            and actual_as_of_dt.timestamp() >= expected_as_of_dt.timestamp()
        )
    if (
        allow_equivalent_authoritative_balance
        and not source_matches
        and _canonical_oanda_account_label(
            {
                "account": expected_label,
                "account_label": expected_label,
                "source": expected_source,
            }
        )
        in _OANDA_CANONICAL_ACCOUNT_LABELS
        and expected_source_key == "oanda_transaction_export_balance"
    ):
        source_matches = bool(
            as_of_not_older
            and actual_source_key
            in {
                "account_summary",
                "oanda_account_summary",
                "broker_account_summary",
                "oanda_broker_summary",
                "oanda_transaction_export_balance",
            }
        )
    freshness_matches = bool(
        expected_as_of in (None, "") or as_of_not_older
    )
    applied = bool(
        snapshot_visible
        and value_matches
        and source_matches
        and currency_matches
        and freshness_matches
    )
    return {
        "ok": applied,
        "balance_expected": True,
        "balance_applied": applied,
        "snapshot_visible": snapshot_visible,
        "account": expected_label,
        "expected_balance": expected_value,
        "actual_balance": actual_value,
        "expected_source": expected_source,
        "actual_source": actual_source,
        "expected_as_of": expected_as_of,
        "actual_as_of": actual_as_of,
        "allow_equivalent_authoritative_balance": allow_equivalent_authoritative_balance,
        "balance_tolerance": balance_tolerance,
        "value_matches": value_matches,
        "source_matches": source_matches,
        "currency_matches": currency_matches,
        "expected_currency": expected_currency,
        "actual_currency": actual_currency,
        "as_of_not_older": as_of_not_older,
        "freshness_matches": freshness_matches,
    }


def _path_is_within(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except Exception:
        return False


def _relative_file_list(root: Path, *, allowed_suffixes: Optional[Set[str]] = None) -> List[str]:
    root_path = Path(root)
    if not root_path.exists() or not root_path.is_dir():
        return []
    root_resolved = root_path.resolve()
    files: List[str] = []
    for path in sorted(root_path.rglob("*")):
        if not path.is_file():
            continue
        if allowed_suffixes is not None and path.suffix.lower() not in allowed_suffixes:
            continue
        resolved = path.resolve()
        if not _path_is_within(resolved, root_resolved):
            continue
        files.append(resolved.relative_to(root_resolved).as_posix())
    return files


def _normalize_pine_name(name: object) -> str:
    raw = str(name or "").strip().replace("\\", "/")
    if raw.startswith("pinescripts/"):
        raw = raw[len("pinescripts/") :]
    return raw


def _resolve_pine_script(name: object) -> Path:
    safe_name = _normalize_pine_name(name)
    if not safe_name or Path(safe_name).is_absolute() or ".." in Path(safe_name).parts:
        raise HTTPException(status_code=400, detail="Invalid Pine script path.")
    path = (PINE_SCRIPTS_DIR / safe_name).resolve()
    root = PINE_SCRIPTS_DIR.resolve()
    if not _path_is_within(path, root):
        raise HTTPException(status_code=400, detail="Invalid Pine script path.")
    if path.suffix.lower() not in PINE_ALLOWED_SUFFIXES:
        raise HTTPException(status_code=415, detail="Unsupported Pine script file type.")
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Pine script not found.")
    return path


