def _import_uploaded_trading_journal_file(upload_name: str, payload: bytes, account_mode: Optional[str] = None) -> Dict[str, object]:
    global _PENDING_MANUAL_SYNC_ROWS, _PENDING_MANUAL_SYNC_BALANCES
    global _TRADING_JOURNAL_CACHE, _TRADING_JOURNAL_CACHE_KEY
    name = str(upload_name or "upload").strip() or "upload"
    suffix = Path(name).suffix.lower()
    allowed = {".xlsx", ".xlsm", ".xls", ".csv"}
    mode = str(account_mode or "").strip().lower()
    if suffix not in allowed:
        return {"ok": False, "status_code": 415, "message": f"Unsupported file type: {suffix or 'unknown'}", "uploaded_name": name, "file_type": suffix or "unknown", "errors": ["unsupported_file_type"], "warnings": []}
    if not payload:
        return {"ok": False, "status_code": 400, "message": "Uploaded file is empty.", "uploaded_name": name, "file_type": suffix, "errors": ["empty_upload"], "warnings": []}
    if mode and mode not in {"demo", "live"}:
        return {"ok": False, "status_code": 422, "message": "account_mode must be demo or live.", "uploaded_name": name, "file_type": suffix, "errors": ["invalid_account_mode"], "warnings": []}
    stem = Path(name).stem.lower()
    tokens = [t for t in re.split(r"[^a-z0-9]+", stem) if t]
    inferred_mode = "demo" if "demo" in tokens else ("live" if "live" in tokens else "")
    if not mode:
        mode = inferred_mode
    if not TRADING_JOURNAL_IMPORT_LOCK.acquire(blocking=False):
        return {"ok": False, "status_code": 409, "code": "TRADING_JOURNAL_IMPORT_IN_PROGRESS", "message": "Trading Journal import is still running. Wait for it to complete before opening the workbook.", "uploaded_name": name, "file_type": suffix, "errors": ["import_in_progress"], "warnings": []}
    acquired_import_lock = True
    master_workbook_reserved = False
    _update_trading_journal_import_status(running=True, stage="preflight", message="Checking workbook lock", started_at=_utc_now_iso(), started_epoch=time.time(), finished_at=None, upload_name=name)
    tmp_path: Optional[Path] = None
    timings: Dict[str, float] = {}
    try:
        workbook_path_for_preflight = _master_journal_path()
        if workbook_path_for_preflight.exists():
            lock_status = _master_journal_lock_status(workbook_path_for_preflight)
            if lock_status.get("locked"):
                return _excel_workbook_open_payload(extra={"uploaded_name": name, "file_type": suffix, "rows_parsed": 0, "rows_upserted": 0, "warnings": [], "lock_status": lock_status, "import_timings": timings})
        with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as tf:
            tf.write(payload)
            tmp_path = Path(tf.name)
        t0 = time.perf_counter()
        rows: List[Dict[str, object]] = []
        balance: Optional[Dict[str, object]] = None
        bybit_diag: Dict[str, object] = {"bybit_execution_rows_seen": 0, "bybit_completed_trades_imported": 0, "bybit_unmatched_execution_rows": 0}
        unmatched_exec_ids: List[str] = []
        is_bybit_csv = bool(suffix == ".csv" and _is_bybit_trade_history_csv(tmp_path))
        inference_warnings: List[str] = []
        inference_diag: Dict[str, object] = {
            "pnl_inferred_count": 0,
            "pnl_unresolved_count": 0,
            "pnl_unresolved_row_ids": [],
        }
        _update_trading_journal_import_status(stage="parse", message="Parsing uploaded file")
        APP_LOGGER.info("trading_journal_import_stage_start stage=parse upload=%s", name)
        if is_bybit_csv:
            if not mode:
                return {"ok": False, "status_code": 422, "message": "Bybit history CSV account is ambiguous. Select Demo or Live before importing.", "uploaded_name": name, "file_type": suffix, "errors": ["ambiguous_bybit_account"], "requires_account_mode": True, "detected_file_kind": "bybit_history_csv", "account_mode_options": ["demo", "live"], "warnings": []}
            try:
                rows, unmatched_exec_ids, bybit_diag = _parse_bybit_trade_history_csv_with_diagnostics(tmp_path, account_mode=mode)
            except Exception as exc:
                return {"ok": False, "status_code": 422, "message": f"Failed to parse {name}: {exc}", "uploaded_name": name, "file_type": suffix, "errors": [str(exc)], "warnings": []}
            balance = None
        else:
            try:
                rows, balance = _parse_local_trading_journal_workbook(tmp_path, original_name=name, account_mode=mode or None)
            except Exception as exc:
                return {"ok": False, "status_code": 422, "message": f"Failed to parse {name}: {exc}", "uploaded_name": name, "file_type": suffix, "errors": [str(exc)], "warnings": []}
        if is_bybit_csv and unmatched_exec_ids:
            return {
                "ok": False,
                "status_code": 422,
                "message": "Unmatched Bybit execution rows remain open; import blocked.",
                "uploaded_name": name,
                "file_type": suffix,
                "rows_parsed": len(rows),
                "errors": ["unmatched_bybit_executions"],
                "warnings": [],
                **bybit_diag,
            }
        timings["parse"] = round(time.perf_counter() - t0, 6)
        APP_LOGGER.info("trading_journal_import_stage_done stage=parse elapsed=%.6fs upload=%s", timings["parse"], name)
        oanda_transaction_export_balance = (
            dict(balance)
            if _is_oanda_transaction_export_balance(balance)
            else None
        )
        t1 = time.perf_counter()
        _update_trading_journal_import_status(stage="pnl_inference", message="Inferring P/L")
        APP_LOGGER.info("trading_journal_import_stage_start stage=pnl_inference upload=%s", name)
        existing_rows = _get_trading_journal_rows()
        rows, inference_warnings, inference_diag = _infer_realized_net_profit_from_balance_continuity(rows, existing_rows)
        timings["pnl_inference"] = round(time.perf_counter() - t1, 6)
        APP_LOGGER.info("trading_journal_import_stage_done stage=pnl_inference elapsed=%.6fs upload=%s", timings["pnl_inference"], name)
        rows = [r for r in (rows or []) if isinstance(r, dict)]
        missing_ids = [r for r in rows if str((r or {}).get("row_type") or "trade").strip().lower() == "trade" and not str((r or {}).get("id") or "").strip()]
        if missing_ids:
            return {"ok": False, "status_code": 422, "message": "Parsed trade rows are missing stable row IDs.", "uploaded_name": name, "file_type": suffix, "rows_parsed": len(rows), "errors": ["missing_trade_row_ids"], "warnings": []}
        if not rows and balance and not isinstance(
            oanda_transaction_export_balance, dict
        ):
            return {"ok": False, "status_code": 422, "message": "Balance-only import is not implemented yet for manual uploads.", "uploaded_name": name, "file_type": suffix, "rows_parsed": 0, "rows_upserted": 0, "balance_parsed": True, "errors": ["balance_only_not_supported"], "warnings": []}
        if not rows and not oanda_transaction_export_balance:
            return {"ok": False, "status_code": 422, "message": "No trade rows or account balance found in uploaded file.", "uploaded_name": name, "file_type": suffix, "rows_parsed": 0, "errors": ["zero_rows"], "warnings": []}
        previous_rows = copy.deepcopy([r for r in _get_trading_journal_rows() if isinstance(r, dict)])
        rollback_rows = copy.deepcopy(previous_rows)
        parsed_ids = [str(r.get("id") or "").strip() for r in rows if str(r.get("id") or "").strip()]
        if rows and not parsed_ids:
            return {"ok": False, "status_code": 422, "message": "No verifiable row IDs were parsed from trade rows.", "uploaded_name": name, "file_type": suffix, "rows_parsed": len(rows), "errors": ["no_verifiable_row_ids"], "warnings": []}
        duplicate_rows_merged = 0
        rows_upserted = 0
        workbook_path = _master_journal_path()
        import_workbook_sync_id = f"mjsync-import-owner-{uuid4().hex[:12]}"
        rejected = _reserve_master_journal_workbook_sync(
            workbook_path,
            import_workbook_sync_id,
            "manual_import_transaction",
        )
        if rejected is not None:
            return {
                **rejected,
                "uploaded_name": name,
                "file_type": suffix,
                "rows_parsed": len(rows),
                "rows_upserted": 0,
                "errors": ["workbook_sync_in_progress"],
                "warnings": [],
            }
        master_workbook_reserved = True
        locked_after_reservation = (
            _master_journal_lock_status(workbook_path)
            if workbook_path.exists()
            else {"locked": False}
        )
        if locked_after_reservation.get("locked"):
            return _excel_workbook_open_payload(
                extra={
                    "uploaded_name": name,
                    "file_type": suffix,
                    "rows_parsed": len(rows),
                    "rows_upserted": 0,
                    "warnings": [],
                    "lock_status": locked_after_reservation,
                    "import_timings": timings,
                }
            )
        _recover_trading_journal_derived_refresh_state_if_needed()
        with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
            pending_recovery_state = copy.deepcopy(
                TRADING_JOURNAL_DERIVED_REFRESH_STATE
            )
        pending_recovery_payload = pending_recovery_state.get(
            "incremental_recovery"
        )
        pending_recovery_phase = ""
        normalized_pending_recovery: Optional[Dict[str, object]] = None
        if pending_recovery_payload is not None:
            try:
                normalized_pending_recovery = (
                    _normalize_trading_journal_incremental_recovery_payload(
                        pending_recovery_payload
                    )
                )
                pending_recovery_phase = str(
                    normalized_pending_recovery.get("phase") or ""
                )
            except Exception:
                pending_recovery_phase = "invalid"
        legacy_recovery_pending = bool(
            str(pending_recovery_state.get("intent_kind") or "").strip().lower()
            == "legacy_incremental_unknown"
            and (
                pending_recovery_state.get("queued")
                or pending_recovery_state.get("running")
                or pending_recovery_state.get("pending")
            )
        )
        retained_recovery_terminal_failed = bool(
            normalized_pending_recovery is not None
            and pending_recovery_phase
            in {"prepared", "json_committed", "workbook_committed"}
            and str(pending_recovery_state.get("status") or "")
            .strip()
            .lower()
            == "failed"
            and not pending_recovery_state.get("queued")
            and not pending_recovery_state.get("running")
            and not pending_recovery_state.get("pending")
        )
        if retained_recovery_terminal_failed:
            recovery_row_ids = list(
                pending_recovery_state.get("affected_row_ids") or []
            )
            if not recovery_row_ids:
                recovery_row_ids = [
                    str(row.get("id") or "").strip()
                    for row in (
                        normalized_pending_recovery.get("json_rows") or []
                    )
                    if isinstance(row, dict)
                    and str(row.get("id") or "").strip()
                ]
            requeued_state = _queue_trading_journal_derived_refresh(
                recovery_row_ids,
                incremental_recovery=normalized_pending_recovery,
            )
            return {
                "ok": False,
                "status_code": 409,
                "code": "TRADING_JOURNAL_INCREMENTAL_RECOVERY_REQUEUED",
                "message": (
                    "The retained incremental recovery transaction was requeued. "
                    "Retry this import after recovery completes."
                ),
                "uploaded_name": name,
                "file_type": suffix,
                "rows_parsed": len(rows),
                "rows_upserted": 0,
                "recovery_requeued": True,
                "errors": ["recovery_requeued"],
                "warnings": [],
                "derived_refresh": _public_trading_journal_derived_refresh_state(
                    requeued_state
                ),
            }
        if (
            pending_recovery_phase
            and pending_recovery_phase != "incremental_committed"
        ) or legacy_recovery_pending:
            return {
                "ok": False,
                "status_code": 409,
                "code": "TRADING_JOURNAL_INCREMENTAL_RECOVERY_PENDING",
                "message": (
                    "A previous incremental journal import is still being "
                    "recovered. Retry after recovery completes."
                ),
                "uploaded_name": name,
                "file_type": suffix,
                "rows_parsed": len(rows),
                "rows_upserted": 0,
                "errors": ["incremental_recovery_pending"],
                "warnings": [],
                "derived_refresh": (
                    _public_trading_journal_derived_refresh_state(
                        pending_recovery_state
                    )
                ),
            }
        workbook_backup_bytes: Optional[bytes] = None
        workbook_had_original = workbook_path.exists()
        journal_json_had_original = False
        journal_json_backup_bytes: Optional[bytes] = None
        journal_cache_before: object = None
        journal_cache_key_before: object = None
        derived_refresh_had_original = False
        derived_refresh_backup_bytes: Optional[bytes] = None
        derived_refresh_memory_before: Optional[Dict[str, object]] = None
        pre_import_workbook_row_ids: List[str] = []
        workbook_existing_rows: List[Dict[str, object]] = []
        workbook_source_preflight: Dict[str, object] = {}
        if workbook_had_original:
            workbook_source_preflight = read_master_journal_source(workbook_path) or {}
            workbook_existing_rows = [dict(r) for r in (workbook_source_preflight.get("items") or []) if isinstance(r, dict) and str((r or {}).get("id") or "").strip()]
            pre_import_workbook_row_ids = [str((r or {}).get("id") or "").strip() for r in workbook_existing_rows]
        verify_result: Optional[Dict[str, object]] = None
        sync_result: Optional[Dict[str, object]] = None
        github_sync_result: Dict[str, object] = {}
        github_sync_started = False
        github_sync_returned = False
        manual_import_snapshot: Optional[Dict[str, object]] = None
        balance_verification: Dict[str, object] = {
            "ok": not bool(oanda_transaction_export_balance),
            "balance_expected": bool(oanda_transaction_export_balance),
            "balance_applied": False,
            "snapshot_visible": False,
        }
        rows_persisted = False
        previous_pending_rows = [dict(r) for r in (_PENDING_MANUAL_SYNC_ROWS or []) if isinstance(r, dict)]
        previous_pending_balances = [
            dict(item)
            for item in (_PENDING_MANUAL_SYNC_BALANCES or [])
            if isinstance(item, dict)
        ]
        pending_restored = False
        duplicate_noop_fast_path_used = False
        incremental_path_eligible = False
        incremental_json_upsert_started = False
        incremental_failure_rollback_required = False
        incremental_workbook_attempted = False
        incremental_workbook_update_used = False
        incremental_full_fallback_started = False
        incremental_affected_row_ids: List[str] = []
        incremental_state_delta_row_ids: List[str] = []
        incremental_json_upsert_row_ids: List[str] = []
        incremental_fallback_reason = ""
        incremental_recovery_payload: Optional[Dict[str, object]] = None
        derived_refresh_state: Dict[str, object] = {}
        deferred_manual_hydration_rows: Optional[List[Dict[str, object]]] = None
        try:
            def _stable_projection_time(row: Dict[str, object], field: str) -> str:
                value = row.get(field)
                if value in (None, ""):
                    return ""
                if _canonical_oanda_account_label(row) in _OANDA_CANONICAL_ACCOUNT_LABELS:
                    try:
                        parsed = pd.to_datetime(value)
                        dt = parsed.to_pydatetime()
                        if dt.tzinfo is not None:
                            dt = dt.astimezone(JOURNAL_DISPLAY_TZ).replace(tzinfo=None)
                        return dt.isoformat()
                    except Exception:
                        pass
                return str(value).strip()

            def _stable_trade_log_projection(row: Dict[str, object]) -> Dict[str, object]:
                account = _canonical_oanda_account_label(row) or _canonical_journal_account_label(
                    row.get("account_label") or row.get("account"),
                    source=row.get("source"),
                    account_mode=row.get("account_mode"),
                )
                net_profit = _to_float(row.get("net_profit"))
                if net_profit is None:
                    net_profit = _to_float(row.get("realized_pnl"))
                return {
                    "id": str(row.get("id") or "").strip(),
                    "row_type": _row_type(row),
                    "account": account,
                    "symbol": _canonical_symbol(row.get("symbol") or ""),
                    "side": str(row.get("side") or "").strip().upper(),
                    "open_time": _stable_projection_time(row, "open_time"),
                    "close_time": _stable_projection_time(row, "close_time"),
                    "qty": _to_float(row.get("qty")),
                    "entry_price": _to_float(row.get("entry_price")),
                    "exit_price": _to_float(row.get("exit_price")),
                    "net_profit": net_profit,
                    "commission": _to_float(row.get("commission")),
                    "balance_after_trade": _to_float(row.get("balance_after_trade")),
                    "stop_loss": _to_float(row.get("stop_loss")),
                    "take_profit": _to_float(row.get("take_profit")),
                    "result_pct": _to_float(row.get("result_pct")),
                    "r_multiple": _to_float(row.get("r_multiple")),
                }

            def _uploaded_projection_matches_workbook(
                uploaded_row: Dict[str, object], workbook_row: Dict[str, object]
            ) -> bool:
                uploaded_projection = _stable_trade_log_projection(uploaded_row)
                workbook_projection = _stable_trade_log_projection(workbook_row)
                optional_when_missing = {
                    "stop_loss",
                    "take_profit",
                }
                workbook_manual_fields = {"result_pct", "r_multiple"}
                numeric_fields = {
                    "qty",
                    "entry_price",
                    "exit_price",
                    "net_profit",
                    "commission",
                    "balance_after_trade",
                    "stop_loss",
                    "take_profit",
                    "result_pct",
                    "r_multiple",
                }
                for key, uploaded_value in uploaded_projection.items():
                    if key in workbook_manual_fields:
                        continue
                    if key in optional_when_missing and uploaded_value in (None, ""):
                        continue
                    workbook_value = workbook_projection.get(key)
                    if key in numeric_fields:
                        if uploaded_value is None or workbook_value is None:
                            if uploaded_value is not workbook_value:
                                return False
                            continue
                        if not math.isclose(
                            float(uploaded_value),
                            float(workbook_value),
                            rel_tol=1e-12,
                            abs_tol=1e-9,
                        ):
                            return False
                    elif workbook_value != uploaded_value:
                        return False
                return True

            def _stable_trade_log_projections_equal(
                left_row: Dict[str, object],
                right_row: Dict[str, object],
                *,
                ignore_workbook_manual_fields: bool = False,
            ) -> bool:
                left_projection = _stable_trade_log_projection(left_row)
                right_projection = _stable_trade_log_projection(right_row)
                workbook_manual_fields = {"result_pct", "r_multiple"}
                numeric_fields = {
                    "qty",
                    "entry_price",
                    "exit_price",
                    "net_profit",
                    "commission",
                    "balance_after_trade",
                    "stop_loss",
                    "take_profit",
                    "result_pct",
                    "r_multiple",
                }
                for key, left_value in left_projection.items():
                    if ignore_workbook_manual_fields and key in workbook_manual_fields:
                        continue
                    right_value = right_projection.get(key)
                    if key in numeric_fields:
                        if left_value is None or right_value is None:
                            if left_value is not right_value:
                                return False
                            continue
                        if not math.isclose(
                            float(left_value),
                            float(right_value),
                            rel_tol=1e-12,
                            abs_tol=1e-9,
                        ):
                            return False
                    elif left_value != right_value:
                        return False
                return True

            def _normalized_incremental_state(
                row: Dict[str, object],
            ) -> Dict[str, object]:
                normalized = _normalize_journal_profit_fields(dict(row))
                normalized.pop("updated_at", None)
                safe = _json_safe(normalized)

                missing = object()

                def compact(value: object, *, parent_key: str = "") -> object:
                    if value is None or value == "":
                        return missing
                    if isinstance(value, dict):
                        compacted: Dict[str, object] = {}
                        for raw_key, raw_value in value.items():
                            key = str(raw_key)
                            if key == "updated_at":
                                continue
                            if parent_key == "raw_refs" and key == "source_path":
                                # Upload parsing uses a fresh temporary file on
                                # each request; that path is transport metadata,
                                # not a durable journal-row change.
                                continue
                            compacted_value = compact(raw_value, parent_key=key)
                            if compacted_value is not missing:
                                compacted[key] = compacted_value
                        return compacted if compacted else missing
                    if isinstance(value, (list, tuple)):
                        compacted_items = [
                            compact(item, parent_key=parent_key) for item in value
                        ]
                        kept = [item for item in compacted_items if item is not missing]
                        return kept if kept else missing
                    return value

                if isinstance(safe, dict) and safe.get("is_test_trade") is False:
                    safe = dict(safe)
                    safe.pop("is_test_trade", None)
                compacted = compact(safe)
                return dict(compacted) if isinstance(compacted, dict) else {}

            def _incremental_state_delta_ids(
                incoming: Iterable[Dict[str, object]],
                persisted: Iterable[Dict[str, object]],
                workbook_by_id: Dict[str, Dict[str, object]],
            ) -> List[str]:
                persisted_by_id = {
                    str((row or {}).get("id") or "").strip(): dict(row)
                    for row in persisted
                    if isinstance(row, dict)
                    and str((row or {}).get("id") or "").strip()
                }
                changed_ids: Set[str] = set()
                for raw in incoming:
                    if not isinstance(raw, dict):
                        continue
                    row_id = str(raw.get("id") or "").strip()
                    if not row_id:
                        continue
                    candidate = dict(raw)
                    workbook_row = workbook_by_id.get(row_id)
                    if (
                        isinstance(workbook_row, dict)
                        and _canonical_oanda_account_label(candidate)
                        in _OANDA_CANONICAL_ACCOUNT_LABELS
                    ):
                        candidate = _preserve_workbook_manual_fields(
                            candidate,
                            workbook_row,
                        )
                    candidate = _normalize_journal_profit_fields(candidate)
                    candidate["id"] = row_id
                    existing = persisted_by_id.get(row_id)
                    if not isinstance(existing, dict):
                        # Workbook-visible new rows are already included in the
                        # affected-row set. A missing runtime cache row alone must
                        # not defeat the established workbook no-op path.
                        continue
                    merged = _merge_trading_journal_row(existing, candidate)
                    normalized_merged = _normalized_incremental_state(merged)
                    normalized_existing = _normalized_incremental_state(existing)
                    if normalized_merged != normalized_existing:
                        changed_ids.add(row_id)
                return sorted(changed_ids)

            rows = [
                _backfill_trade_row_context_fields(dict(r)) if isinstance(r, dict) else r
                for r in rows
            ]
            incremental_state_source_rows = [
                dict(row) for row in rows if isinstance(row, dict)
            ]
            preflight_rows, preflight_replaced_oanda_ids = _prepare_oanda_canonical_replacements(
                workbook_existing_rows,
                rows,
            )
            workbook_map = {
                str((r or {}).get("id") or "").strip(): dict(r)
                for r in workbook_existing_rows
                if str((r or {}).get("id") or "").strip()
            }
            preflight_state_delta_row_ids = _incremental_state_delta_ids(
                incremental_state_source_rows,
                previous_rows,
                workbook_map,
            )
            preflight_parsed_map = {
                str((r or {}).get("id") or "").strip(): dict(r)
                for r in preflight_rows
                if str((r or {}).get("id") or "").strip()
            }
            preflight_expected_survivors = sorted(
                (set(pre_import_workbook_row_ids) - preflight_replaced_oanda_ids)
                | set(preflight_parsed_map)
            )
            preflight_balance_verification = _verify_imported_account_balance_snapshot(
                workbook_source_preflight,
                oanda_transaction_export_balance,
                allow_equivalent_authoritative_balance=True,
            )
            fast_path_noop = (
                bool(
                    preflight_parsed_map
                    or isinstance(oanda_transaction_export_balance, dict)
                )
                and not preflight_replaced_oanda_ids
                and all(
                (rid in workbook_map)
                and _uploaded_projection_matches_workbook(
                    preflight_parsed_map[rid], workbook_map[rid]
                )
                for rid in preflight_parsed_map
                )
                and set(preflight_expected_survivors).issubset(
                    set(pre_import_workbook_row_ids)
                )
                and bool(preflight_balance_verification.get("ok"))
                and not preflight_state_delta_row_ids
            )
            if fast_path_noop:
                duplicate_rows_merged = sum(
                    1 for rid in preflight_parsed_map if rid in workbook_map
                )
                timings.update(
                    {
                        "upsert": 0.0,
                        "snapshot_build": 0.0,
                        "workbook_sync": 0.0,
                        "verification": 0.0,
                        "workbook_snapshot_verification": 0.0,
                        "snapshot_persist": 0.0,
                        "github_sync": 0.0,
                    }
                )
                APP_LOGGER.info(
                    "trading_journal_import_duplicate_noop upload=%s rows=%s balance_expected=%s preflight_source_reused=True",
                    name,
                    len(preflight_parsed_map),
                    bool(oanda_transaction_export_balance),
                )
                message = (
                    "All uploaded rows and the uploaded account balance already existed; "
                    "no workbook rebuild was required."
                    if oanda_transaction_export_balance
                    else "All uploaded rows already existed; no workbook rebuild was required."
                )
                derived_refresh = (
                    _trading_journal_derived_refresh_status_snapshot()
                )
                terminal_failed_refresh = bool(
                    str(derived_refresh.get("status") or "").strip().lower()
                    == "failed"
                    and derived_refresh.get("refresh_required")
                    and not derived_refresh.get("pending")
                )
                if terminal_failed_refresh:
                    retry_ids = list(
                        derived_refresh.get("affected_row_ids") or []
                    ) or list(preflight_parsed_map)
                    derived_refresh = _queue_trading_journal_derived_refresh(
                        retry_ids
                    )
                derived_pending = bool(
                    derived_refresh.get("queued")
                    or derived_refresh.get("running")
                    or derived_refresh.get("pending")
                    or str(derived_refresh.get("status") or "")
                    .strip()
                    .lower()
                    == "retrying"
                )
                if derived_pending:
                    message += (
                        " A derived workbook refresh and GitHub sync are still queued."
                    )
                return {
                    "ok": True,
                    "status_code": 200,
                    "message": message,
                    "uploaded_name": name,
                    "file_type": suffix,
                    "rows_parsed": len(rows),
                    "rows_upserted": 0,
                    "duplicate_rows_merged": duplicate_rows_merged,
                    "duplicate_noop_fast_path_used": True,
                    "workbook_rebuild_required": False,
                    "balance_parsed": bool(balance),
                    "rows_persisted": True,
                    "balance_applied": bool(preflight_balance_verification.get("balance_applied")),
                    "snapshot_visible": bool(preflight_balance_verification.get("snapshot_visible")),
                    "balance_verification": preflight_balance_verification,
                    "master_journal_path": str(workbook_path),
                    "verified_row_ids_count": len(preflight_parsed_map),
                    "missing_row_ids": [],
                    "warnings": inference_warnings,
                    "errors": [],
                    "import_timings": timings,
                    **inference_diag,
                    **bybit_diag,
                    "github_sync_skipped": not derived_pending,
                    "github_sync_deferred": derived_pending,
                    "github_sync_commit_sha": None,
                    "github_sync_path": str(workbook_path),
                    "github_sync_message": (
                        "GitHub sync deferred until the queued derived workbook refresh."
                        if derived_pending
                        else "GitHub sync skipped because the workbook was unchanged."
                    ),
                    "incremental_workbook_update_used": False,
                    "affected_row_ids": [],
                    "state_delta_row_ids": [],
                    "json_upsert_row_ids": [],
                    "derived_refresh": derived_refresh,
                }

            if workbook_had_original:
                workbook_backup_bytes = workbook_path.read_bytes()
            should_hydrate = False
            if workbook_existing_rows:
                current_ids = {str((r or {}).get("id") or "").strip() for r in previous_rows if str((r or {}).get("id") or "").strip()}
                workbook_ids = {str((r or {}).get("id") or "").strip() for r in workbook_existing_rows if str((r or {}).get("id") or "").strip()}
                current_map = {str((r or {}).get("id") or "").strip(): dict(r) for r in previous_rows if str((r or {}).get("id") or "").strip()}
                workbook_map = {str((r or {}).get("id") or "").strip(): dict(r) for r in workbook_existing_rows if str((r or {}).get("id") or "").strip()}
                stale_ids = [
                    rid for rid in workbook_ids.intersection(current_ids)
                    if not _stable_trade_log_projections_equal(
                        current_map.get(rid, {}), workbook_map.get(rid, {})
                    )
                ]
                material_stale_ids = [
                    rid
                    for rid in workbook_ids.intersection(current_ids)
                    if not _stable_trade_log_projections_equal(
                        current_map.get(rid, {}),
                        workbook_map.get(rid, {}),
                        ignore_workbook_manual_fields=True,
                    )
                ]
                hydration_required = bool(
                    (not previous_rows)
                    or (not workbook_ids.issubset(current_ids))
                    or stale_ids
                )
                should_hydrate = bool(
                    (not previous_rows)
                    or (not workbook_ids.issubset(current_ids))
                    or material_stale_ids
                )
                hydrated_rows_added = 0
                hydrated_rows_replaced = 0
                if hydration_required:
                    merged = dict(current_map)
                    for row in workbook_existing_rows:
                        rid = str((row or {}).get("id") or "").strip()
                        if not rid:
                            continue
                        if rid not in merged:
                            merged[rid] = dict(row)
                            hydrated_rows_added += 1
                        elif rid in stale_ids:
                            merged[rid] = dict(row)
                            hydrated_rows_replaced += 1
                    hydrated_rows = list(merged.values())
                    if should_hydrate:
                        _set_trading_journal_rows(hydrated_rows)
                        previous_rows = copy.deepcopy(
                            [
                                r
                                for r in _get_trading_journal_rows()
                                if isinstance(r, dict)
                            ]
                        )
                    else:
                        deferred_manual_hydration_rows = [
                            _normalize_journal_profit_fields(dict(row))
                            for row in hydrated_rows
                            if isinstance(row, dict)
                        ]
                        previous_rows = copy.deepcopy(
                            deferred_manual_hydration_rows
                        )
                APP_LOGGER.info(
                    "trading_journal_import_hydration upload=%s workbook_rows_loaded=%s state_rows_before_hydration=%s hydrated_rows_added=%s hydrated_rows_replaced_due_to_stale_state=%s stale_same_id_count=%s material_stale_same_id_count=%s manual_only_hydration_deferred=%s",
                    name,
                    len(workbook_existing_rows),
                    len(current_map),
                    hydrated_rows_added,
                    hydrated_rows_replaced,
                    len(stale_ids),
                    len(material_stale_ids),
                    bool(deferred_manual_hydration_rows),
                )
            existing_ids = {str((r or {}).get("id") or "").strip() for r in previous_rows if str((r or {}).get("id") or "").strip()}
            duplicate_rows_merged = sum(1 for rid in parsed_ids if rid in existing_ids)
            APP_LOGGER.info(
                "trading_journal_import_duplicate_check upload=%s parsed_duplicate_ids_after_hydration=%s duplicate_rows_merged=%s",
                name,
                [rid for rid in parsed_ids if rid in existing_ids][:10],
                duplicate_rows_merged,
            )
            rows, replaced_oanda_legacy_ids = _prepare_oanda_canonical_replacements(previous_rows, rows)
            rows = [
                _preserve_workbook_manual_fields(
                    dict(row), workbook_map[str(row.get("id") or "").strip()]
                )
                if (
                    isinstance(row, dict)
                    and str(row.get("id") or "").strip() in workbook_map
                    and _canonical_oanda_account_label(row)
                    in _OANDA_CANONICAL_ACCOUNT_LABELS
                )
                else row
                for row in rows
            ]
            expected_survivors = sorted(
                (set(pre_import_workbook_row_ids) - replaced_oanda_legacy_ids) | set(parsed_ids)
            )
            parsed_map = {str((r or {}).get("id") or "").strip(): dict(r) for r in rows if str((r or {}).get("id") or "").strip()}
            workbook_structure = (
                workbook_source_preflight.get("_workbook_structure")
                if isinstance(workbook_source_preflight, dict)
                else {}
            )
            workbook_sheet_order = (
                list(workbook_structure.get("sheet_order") or [])
                if isinstance(workbook_structure, dict)
                else []
            )
            workbook_schema_current = bool(
                workbook_had_original
                and "Trade Log" in workbook_sheet_order
                and "All Trades" not in workbook_sheet_order
                and all(sheet_name in workbook_sheet_order for sheet_name in SHEET_ORDER)
                and len(pre_import_workbook_row_ids)
                == len(set(pre_import_workbook_row_ids))
            )
            ordinary_oanda_rows = all(
                isinstance(row, dict)
                and _row_type(row) == "trade"
                and str(row.get("source") or "").strip().lower()
                == "oanda_transaction_export"
                and _canonical_oanda_account_label(row)
                in _OANDA_CANONICAL_ACCOUNT_LABELS
                and str(row.get("id") or "").strip().startswith("oanda_export:")
                and _to_float(row.get("balance_after_trade")) is not None
                for row in rows
            )
            incremental_affected_row_ids = sorted(
                str(row.get("id") or "").strip()
                for row in rows
                if str(row.get("id") or "").strip()
                and (
                    str(row.get("id") or "").strip() not in workbook_map
                    or not _stable_trade_log_projections_equal(
                        row,
                        workbook_map.get(str(row.get("id") or "").strip(), {}),
                    )
                )
            )
            incremental_state_delta_row_ids = _incremental_state_delta_ids(
                incremental_state_source_rows,
                previous_rows,
                workbook_map,
            )
            incremental_json_upsert_row_ids = sorted(
                set(incremental_affected_row_ids)
                | set(incremental_state_delta_row_ids)
            )
            incremental_path_eligible = bool(
                workbook_schema_current
                and not should_hydrate
                and isinstance(oanda_transaction_export_balance, dict)
                and not preflight_replaced_oanda_ids
                and not replaced_oanda_legacy_ids
                and ordinary_oanda_rows
                and len(parsed_ids) == len(set(parsed_ids)) == len(rows)
                and len(incremental_json_upsert_row_ids)
                <= TRADING_JOURNAL_INCREMENTAL_RECOVERY_MAX_ROWS
            )
            if incremental_path_eligible:
                json_upsert_id_set = set(incremental_json_upsert_row_ids)
                workbook_affected_id_set = set(incremental_affected_row_ids)
                try:
                    incremental_recovery_payload = (
                        _normalize_trading_journal_incremental_recovery_payload(
                            {
                                "version": TRADING_JOURNAL_INCREMENTAL_RECOVERY_VERSION,
                                "transaction_id": f"incremental-{uuid4().hex[:12]}",
                                "phase": "prepared",
                                "json_rows": [
                                    dict(row)
                                    for row in rows
                                    if str((row or {}).get("id") or "").strip()
                                    in json_upsert_id_set
                                ],
                                "workbook_rows": [
                                    dict(row)
                                    for row in rows
                                    if str((row or {}).get("id") or "").strip()
                                    in workbook_affected_id_set
                                ],
                                "account_balance": dict(
                                    oanda_transaction_export_balance
                                ),
                                "created_at": _utc_now_iso(),
                            }
                        )
                    )
                except Exception as recovery_payload_exc:
                    incremental_path_eligible = False
                    incremental_fallback_reason = (
                        "durable_recovery_payload_ineligible:"
                        f"{recovery_payload_exc}"
                    )
            if not incremental_path_eligible:
                if incremental_fallback_reason:
                    pass
                elif not workbook_schema_current:
                    incremental_fallback_reason = "workbook_schema_not_current"
                elif should_hydrate:
                    incremental_fallback_reason = "runtime_journal_state_not_current"
                elif not isinstance(oanda_transaction_export_balance, dict):
                    incremental_fallback_reason = "oanda_export_balance_missing"
                elif preflight_replaced_oanda_ids or replaced_oanda_legacy_ids:
                    incremental_fallback_reason = "canonical_replacement_required"
                elif not ordinary_oanda_rows:
                    incremental_fallback_reason = "non_oanda_or_incomplete_trade_rows"
                elif len(parsed_ids) != len(set(parsed_ids)) or len(parsed_ids) != len(rows):
                    incremental_fallback_reason = "unstable_or_duplicate_row_ids"
                elif (
                    len(incremental_json_upsert_row_ids)
                    > TRADING_JOURNAL_INCREMENTAL_RECOVERY_MAX_ROWS
                ):
                    incremental_fallback_reason = "affected_state_row_limit_exceeded"
                else:
                    incremental_fallback_reason = "affected_row_limit_exceeded"
            pending_balance_map: Dict[str, Dict[str, object]] = {}
            for item in [
                *previous_pending_balances,
                *(
                    [oanda_transaction_export_balance]
                    if isinstance(oanda_transaction_export_balance, dict)
                    else []
                ),
            ]:
                if not isinstance(item, dict):
                    continue
                pending_key = _norm_account_key(
                    item.get("label")
                    or item.get("account")
                    or item.get("account_label")
                )
                if pending_key:
                    pending_balance_map[pending_key] = dict(item)
            _PENDING_MANUAL_SYNC_BALANCES = list(pending_balance_map.values())
            if incremental_path_eligible:
                journal_json_had_original = TRADING_JOURNAL_PATH.exists()
                journal_json_backup_bytes = (
                    TRADING_JOURNAL_PATH.read_bytes()
                    if journal_json_had_original
                    else None
                )
                journal_cache_before = copy.deepcopy(_TRADING_JOURNAL_CACHE)
                journal_cache_key_before = copy.deepcopy(_TRADING_JOURNAL_CACHE_KEY)
                _recover_trading_journal_derived_refresh_state_if_needed()
                with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
                    derived_refresh_had_original = (
                        TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH.exists()
                    )
                    derived_refresh_backup_bytes = (
                        TRADING_JOURNAL_DERIVED_REFRESH_STATE_PATH.read_bytes()
                        if derived_refresh_had_original
                        else None
                    )
                    derived_refresh_memory_before = copy.deepcopy(
                        TRADING_JOURNAL_DERIVED_REFRESH_STATE
                    )
                incremental_failure_rollback_required = True
                derived_refresh_state = _queue_trading_journal_derived_refresh(
                    incremental_json_upsert_row_ids,
                    incremental_recovery=incremental_recovery_payload,
                )
                incremental_json_upsert_started = True
                if deferred_manual_hydration_rows is not None:
                    _set_trading_journal_rows(
                        deferred_manual_hydration_rows,
                        invalidate_view_snapshot=False,
                        schedule_state_backup=False,
                    )
            t2 = time.perf_counter()
            _update_trading_journal_import_status(stage="upsert", message="Saving imported rows")
            APP_LOGGER.info("trading_journal_import_stage_start stage=upsert upload=%s", name)
            upsert_rows = rows
            if incremental_path_eligible:
                incremental_json_upsert_row_id_set = set(
                    incremental_json_upsert_row_ids
                )
                upsert_rows = [
                    row
                    for row in rows
                    if str((row or {}).get("id") or "").strip()
                    in incremental_json_upsert_row_id_set
                ]
            rows_upserted = _upsert_trading_journal_rows(
                upsert_rows,
                allow_broker_rows_in_single_file=True,
                invalidate_view_snapshot=not incremental_path_eligible,
                schedule_state_backup=not incremental_path_eligible,
                preserve_unaffected_rows=incremental_path_eligible,
            )
            if incremental_path_eligible:
                derived_refresh_state = (
                    _set_trading_journal_incremental_recovery_phase(
                        "json_committed"
                    )
                )
            timings["upsert"] = round(time.perf_counter() - t2, 6)
            APP_LOGGER.info("trading_journal_import_stage_done stage=upsert elapsed=%.6fs upload=%s", timings["upsert"], name)
            if incremental_path_eligible:
                repaired_rows = _get_trading_journal_rows()
                repaired_changed = 0
            else:
                repaired_rows, repaired_changed = _backfill_persisted_bybit_trade_fields(
                    _get_trading_journal_rows()
                )
            workbook_manual_rows_preserved = 0
            rows_with_workbook_manual_fields: List[Dict[str, object]] = []
            for persisted_row in ([] if incremental_path_eligible else repaired_rows):
                if not isinstance(persisted_row, dict):
                    continue
                rid = str(persisted_row.get("id") or "").strip()
                workbook_row = workbook_map.get(rid)
                preserved_row = (
                    _preserve_workbook_manual_fields(
                        dict(persisted_row), workbook_row
                    )
                    if isinstance(workbook_row, dict)
                    else dict(persisted_row)
                )
                if preserved_row != persisted_row:
                    workbook_manual_rows_preserved += 1
                rows_with_workbook_manual_fields.append(preserved_row)
            if workbook_manual_rows_preserved:
                repaired_rows = rows_with_workbook_manual_fields
                repaired_changed = True
            if repaired_changed:
                _set_trading_journal_rows(repaired_rows)
                rows = [_backfill_trade_row_context_fields(dict(r)) if isinstance(r, dict) else r for r in rows]
            APP_LOGGER.info(
                "trading_journal_import_workbook_manual_fields_preserved upload=%s rows=%s",
                name,
                workbook_manual_rows_preserved,
            )

            post_upsert_rows_by_id = {
                str((row or {}).get("id") or "").strip(): dict(row)
                for row in repaired_rows
                if isinstance(row, dict) and str(row.get("id") or "").strip()
            }
            pending_map: Dict[str, Dict[str, object]] = {}
            post_upsert_import_rows = [
                _preserve_workbook_manual_fields(
                    post_upsert_rows_by_id.get(
                        str((row or {}).get("id") or "").strip(), dict(row)
                    ),
                    workbook_map[str((row or {}).get("id") or "").strip()],
                )
                if (
                    str((row or {}).get("id") or "").strip() in workbook_map
                    and _canonical_oanda_account_label(row)
                    in _OANDA_CANONICAL_ACCOUNT_LABELS
                )
                else post_upsert_rows_by_id.get(
                    str((row or {}).get("id") or "").strip(), dict(row)
                )
                for row in rows
                if isinstance(row, dict)
            ]
            for r in [*post_upsert_import_rows, *previous_pending_rows]:
                rid = str((r or {}).get("id") or "").strip()
                if rid:
                    pending_map[rid] = dict(r)
            for rid, workbook_row in workbook_map.items():
                current_row = pending_map.get(rid) or post_upsert_rows_by_id.get(rid)
                if not isinstance(current_row, dict):
                    continue
                preserved_row = _preserve_workbook_manual_fields(
                    current_row, workbook_row
                )
                if preserved_row != current_row:
                    pending_map[rid] = preserved_row
            _PENDING_MANUAL_SYNC_ROWS = list(pending_map.values())

            if incremental_path_eligible:
                incremental_rows_by_id = {
                    str((row or {}).get("id") or "").strip(): dict(row)
                    for row in post_upsert_import_rows
                    if isinstance(row, dict)
                    and str((row or {}).get("id") or "").strip()
                }
                incremental_changed_rows = [
                    incremental_rows_by_id[row_id]
                    for row_id in incremental_affected_row_ids
                    if row_id in incremental_rows_by_id
                ]
                if len(incremental_changed_rows) != len(
                    incremental_affected_row_ids
                ):
                    raise RuntimeError(
                        "Incremental import lost an affected row after durable JSON upsert."
                    )

                t3 = time.perf_counter()
                _update_trading_journal_import_status(
                    stage="workbook_sync:incremental",
                    message="Saving affected Trade Log rows and account balance",
                )
                sync_id = f"mjsync-incremental-{uuid4().hex[:12]}"
                sync_caller = "manual_import_incremental"
                rejected = _reserve_master_journal_workbook_sync(
                    workbook_path,
                    sync_id,
                    sync_caller,
                )
                if rejected is not None:
                    sync_result = rejected
                    raise RuntimeError(_master_journal_sync_error(rejected))
                try:
                    incremental_workbook_attempted = True
                    try:
                        sync_result = update_master_journal_workbook_incremental(
                            workbook_path,
                            incremental_changed_rows,
                            account_balance=oanda_transaction_export_balance,
                            expected_survivor_row_ids=expected_survivors,
                        )
                    except IncrementalWorkbookUpdateNotEligible as exc:
                        incremental_fallback_reason = (
                            f"workbook_helper_ineligible:{exc}"
                        )
                        if bool(getattr(exc, "unsafe_full_rebuild", False)):
                            raise RuntimeError(
                                "Incremental workbook update was refused because a full "
                                "rebuild could discard workbook-owned content: "
                                f"{exc}"
                            ) from exc
                        incremental_path_eligible = False
                        incremental_full_fallback_started = True
                        APP_LOGGER.info(
                            "trading_journal_import_incremental_ineligible upload=%s reason=%s; using full sync",
                            name,
                            exc,
                        )
                    else:
                        if not bool((sync_result or {}).get("ok")):
                            raise RuntimeError(
                                "Incremental workbook update failed: "
                                f"{_master_journal_sync_error(sync_result)}"
                            )
                        helper_affected_ids = sorted(
                            str(row_id or "").strip()
                            for row_id in ((sync_result or {}).get("affected_row_ids") or [])
                            if str(row_id or "").strip()
                        )
                        if helper_affected_ids != incremental_affected_row_ids:
                            raise RuntimeError(
                                "Incremental workbook update affected an unexpected row set."
                            )
                        incremental_workbook_update_used = True
                finally:
                    _release_master_journal_workbook_sync()
                timings["workbook_sync"] = round(time.perf_counter() - t3, 6)

                if incremental_workbook_update_used:
                    diagnostics = (
                        dict((sync_result or {}).get("diagnostics") or {})
                        if isinstance((sync_result or {}).get("diagnostics"), dict)
                        else {}
                    )
                    verified_balance = (
                        dict(diagnostics.get("verified_account_balance") or {})
                        if isinstance(diagnostics.get("verified_account_balance"), dict)
                        else {}
                    )
                    account_balance_updated = bool(
                        (sync_result or {}).get("account_balance_updated")
                    )
                    if not account_balance_updated:
                        raise RuntimeError(
                            "Incremental workbook update did not persist the imported account balance."
                        )
                    if not verified_balance:
                        raise RuntimeError(
                            "Incremental workbook update did not return verified account balance diagnostics."
                        )
                    expected_balance_value = _to_float(
                        (oanda_transaction_export_balance or {}).get("balance")
                    )
                    actual_balance_value = _to_float(verified_balance.get("balance"))
                    verified_balance_matches = bool(
                        expected_balance_value is not None
                        and actual_balance_value is not None
                        and math.isclose(
                            expected_balance_value,
                            actual_balance_value,
                            rel_tol=1e-12,
                            abs_tol=1e-9,
                        )
                    )
                    if not verified_balance_matches:
                        raise RuntimeError(
                            "Incremental workbook balance diagnostics did not match the imported balance."
                        )
                    balance_verification = {
                        "ok": True,
                        "balance_expected": True,
                        "balance_applied": True,
                        "snapshot_visible": False,
                        "derived_refresh_pending": True,
                        "expected_balance": expected_balance_value,
                        "actual_balance": actual_balance_value,
                        "actual_currency": verified_balance.get("currency"),
                        "actual_as_of": verified_balance.get("as_of"),
                        "actual_source": verified_balance.get("source"),
                        "provenance_defined_name": verified_balance.get(
                            "provenance_defined_name"
                        ),
                    }
                    derived_refresh_state = (
                        _set_trading_journal_incremental_recovery_phase(
                            "workbook_committed"
                        )
                    )
                    t5 = time.perf_counter()
                    _persist_trading_journal_sqlite_incremental(
                        incremental_changed_rows,
                        oanda_transaction_export_balance,
                        import_meta={
                            "source_mode": "manual_upload_incremental",
                            "workbooks_scanned": 1,
                            "workbooks_changed": 1,
                            "rows_imported": len(incremental_changed_rows),
                            "warnings": [],
                            "errors": [],
                        },
                        derived_refresh_state=derived_refresh_state,
                    )
                    timings["snapshot_persist"] = round(
                        time.perf_counter() - t5,
                        6,
                    )
                    try:
                        derived_refresh_state = (
                            _set_trading_journal_incremental_recovery_phase(
                                "incremental_committed"
                            )
                        )
                        derived_refresh_state = (
                            _defer_trading_journal_derived_refresh_after_incremental_commit()
                        )
                    except Exception as post_commit_exc:
                        # JSON, workbook, and SQLite are now a coherent primary
                        # commit. The already-durable workbook_committed phase is
                        # sufficient for idempotent restart recovery, so a later
                        # state/debounce write must never roll those stores back.
                        warning = (
                            "Incremental import committed, but the derived refresh "
                            f"state transition will be recovered: {post_commit_exc}"
                        )
                        inference_warnings.append(warning)
                        APP_LOGGER.warning(
                            "trading_journal_import_post_commit_state_transition_failed upload=%s error=%s",
                            name,
                            post_commit_exc,
                        )
                        with TRADING_JOURNAL_DERIVED_REFRESH_LOCK:
                            derived_refresh_state = copy.deepcopy(
                                TRADING_JOURNAL_DERIVED_REFRESH_STATE
                            )
                            if (
                                bool(derived_refresh_state.get("queued"))
                                and not bool(derived_refresh_state.get("running"))
                            ):
                                try:
                                    _arm_trading_journal_derived_refresh_timer_locked()
                                except Exception as arm_exc:
                                    APP_LOGGER.warning(
                                        "trading_journal_import_post_commit_timer_rearm_failed upload=%s error=%s",
                                        name,
                                        arm_exc,
                                    )
                    _PENDING_MANUAL_SYNC_ROWS = previous_pending_rows
                    _PENDING_MANUAL_SYNC_BALANCES = previous_pending_balances
                    pending_restored = True
                    rows_persisted = True
                    timings.update(
                        {
                            "snapshot_build": 0.0,
                            "verification": 0.0,
                            "workbook_snapshot_verification": 0.0,
                            "github_sync": 0.0,
                        }
                    )
                    try:
                        _schedule_dropbox_upload_state_backup()
                    except Exception as backup_exc:
                        APP_LOGGER.warning(
                            "trading_journal_import_state_backup_schedule_failed upload=%s error=%s",
                            name,
                            backup_exc,
                        )
                    incremental_failure_rollback_required = False
                    APP_LOGGER.info(
                        "trading_journal_import_incremental_success timings=%s upload=%s affected_row_ids=%s generation=%s",
                        timings,
                        name,
                        incremental_affected_row_ids,
                        derived_refresh_state.get("generation"),
                    )
                    return {
                        "ok": True,
                        "status_code": 200,
                        "message": (
                            "Affected Trade Log rows and the Oanda account balance were saved; derived workbook refresh queued."
                            if incremental_affected_row_ids
                            else "The Oanda account balance was saved; derived workbook refresh queued."
                        ),
                        "uploaded_name": name,
                        "file_type": suffix,
                        "rows_parsed": len(rows),
                        "rows_upserted": rows_upserted,
                        "duplicate_rows_merged": duplicate_rows_merged,
                        "balance_parsed": bool(balance),
                        "rows_persisted": rows_persisted,
                        "balance_applied": True,
                        "snapshot_visible": False,
                        "balance_verification": balance_verification,
                        "master_journal_path": str(workbook_path),
                        "verified_row_ids_count": len(parsed_ids),
                        "missing_row_ids": [],
                        "warnings": inference_warnings,
                        "errors": [],
                        "import_timings": timings,
                        **inference_diag,
                        **bybit_diag,
                        "incremental_workbook_update_used": True,
                        "workbook_rebuild_required": False,
                        "affected_row_ids": incremental_affected_row_ids,
                        "state_delta_row_ids": incremental_state_delta_row_ids,
                        "json_upsert_row_ids": incremental_json_upsert_row_ids,
                        "affected_row_numbers": list(
                            (sync_result or {}).get("affected_row_numbers") or []
                        ),
                        "derived_refresh": (
                            _public_trading_journal_derived_refresh_state(
                                derived_refresh_state
                            )
                        ),
                        "github_sync_enabled": _trading_journal_github_sync_enabled(),
                        "github_sync_ok": None,
                        "github_sync_noop": False,
                        "github_sync_deferred": True,
                        "github_sync_commit": "",
                        "github_sync_commit_sha": None,
                        "github_sync_path": str(workbook_path),
                        "github_sync_message": "GitHub sync deferred until the queued derived workbook refresh.",
                        "diagnostics": diagnostics,
                    }

            t_snap = time.perf_counter()
            _update_trading_journal_import_status(stage="snapshot_build", message="Building authoritative import snapshot")
            APP_LOGGER.info("trading_journal_import_stage_start stage=snapshot_build upload=%s mode=authoritative_workbook", name)
            manual_import_snapshot = _build_manual_import_authoritative_snapshot(
                persist_sqlite=False
            )
            pending_balance_verification = _verify_imported_account_balance_snapshot(
                manual_import_snapshot,
                oanda_transaction_export_balance,
            )
            if bool(oanda_transaction_export_balance) and not bool(pending_balance_verification.get("ok")):
                raise RuntimeError(
                    "Authoritative import snapshot did not apply parsed account balance: "
                    f"expected={pending_balance_verification.get('expected_balance')} "
                    f"actual={pending_balance_verification.get('actual_balance')} "
                    f"expected_source={pending_balance_verification.get('expected_source')} "
                    f"actual_source={pending_balance_verification.get('actual_source')}"
                )
            timings["snapshot_build"] = round(time.perf_counter() - t_snap, 6)
            APP_LOGGER.info("trading_journal_import_stage_done stage=snapshot_build elapsed=%.6fs upload=%s mode=authoritative_workbook", timings["snapshot_build"], name)
            t3 = time.perf_counter()
            _update_trading_journal_import_status(stage="workbook_sync", message="Updating Trading Journal.xlsx")
            APP_LOGGER.info("trading_journal_import_stage_start stage=workbook_sync upload=%s", name)
            sync_result = _sync_master_journal_workbook(defer_github_sync=True, expected_survivor_row_ids=expected_survivors, prebuilt_snapshot=manual_import_snapshot, sync_caller="manual_import")
            timings["workbook_sync"] = round(time.perf_counter() - t3, 6)
            APP_LOGGER.info("trading_journal_import_stage_done stage=workbook_sync elapsed=%.6fs upload=%s", timings["workbook_sync"], name)
            if not _master_journal_sync_ok(sync_result):
                sync_missing = list((sync_result or {}).get("missing_row_ids") or [])
                APP_LOGGER.error(
                    "trading_journal_import workbook_sync failed upload=%s elapsed=%.6fs missing_row_ids_count=%s missing_row_ids_sample=%s error=%s",
                    name, timings["workbook_sync"], len(sync_missing), sync_missing[:5], _master_journal_sync_error(sync_result),
                )
                if isinstance(sync_result, dict) and sync_result.get("code") == "EXCEL_WORKBOOK_OPEN":
                    raise PermissionError(_master_journal_sync_error(sync_result))
                raise RuntimeError(f"Workbook sync failed: {_master_journal_sync_error(sync_result)}")
            _PENDING_MANUAL_SYNC_ROWS = previous_pending_rows
            _PENDING_MANUAL_SYNC_BALANCES = previous_pending_balances
            pending_restored = True

            t4 = time.perf_counter()
            _update_trading_journal_import_status(stage="verification", message="Verifying workbook rows")
            APP_LOGGER.info("trading_journal_import_stage_start stage=verification upload=%s expected_row_ids=%s", name, len(expected_survivors))
            verify_result = _verify_trade_log_row_ids_in_workbook(_master_journal_path(), expected_survivors)
            timings["verification"] = round(time.perf_counter() - t4, 6)
            APP_LOGGER.info(
                "trading_journal_import_stage_done stage=verification elapsed=%.6fs upload=%s found_row_ids_count=%s missing_row_ids_count=%s",
                timings["verification"],
                name,
                (verify_result or {}).get("found_row_ids_count"),
                len((verify_result or {}).get("missing_row_ids") or []),
            )
            if not bool((verify_result or {}).get("ok")):
                raise RuntimeError(f"Workbook verification failed after import. missing_row_ids={(verify_result or {}).get('missing_row_ids') or []}")
            rows_persisted = True
            t5 = time.perf_counter()
            APP_LOGGER.info("trading_journal_import_stage_start stage=workbook_snapshot_verification upload=%s", name)
            if not isinstance(manual_import_snapshot, dict):
                raise RuntimeError("Authoritative import snapshot was not retained for verification.")
            snapshot = manual_import_snapshot
            if bool(oanda_transaction_export_balance):
                workbook_source_after_import = read_master_journal_source(
                    _master_journal_path()
                )
                workbook_balance_verification = _verify_imported_account_balance_snapshot(
                    {
                        "balances": (
                            workbook_source_after_import.get("balances")
                            if isinstance(workbook_source_after_import, dict)
                            else []
                        )
                    },
                    oanda_transaction_export_balance,
                )
                if not bool(workbook_balance_verification.get("ok")):
                    raise RuntimeError(
                        "Workbook Account Balances reread failed after import: "
                        f"expected={workbook_balance_verification.get('expected_balance')} "
                        f"actual={workbook_balance_verification.get('actual_balance')} "
                        f"expected_source={workbook_balance_verification.get('expected_source')} "
                        f"actual_source={workbook_balance_verification.get('actual_source')}"
                    )
                balance_verification = _verify_imported_account_balance_snapshot(
                    snapshot,
                    oanda_transaction_export_balance,
                )
                if not bool(balance_verification.get("ok")):
                    raise RuntimeError(
                        "Workbook account balance verification failed after import: "
                        f"expected={balance_verification.get('expected_balance')} "
                        f"actual={balance_verification.get('actual_balance')} "
                        f"expected_source={balance_verification.get('expected_source')} "
                        f"actual_source={balance_verification.get('actual_source')} "
                        f"workbook_as_of={workbook_balance_verification.get('actual_as_of')} "
                        f"snapshot_as_of={balance_verification.get('actual_as_of')}"
                    )
            timings["workbook_snapshot_verification"] = round(time.perf_counter() - t5, 6)
            APP_LOGGER.info("trading_journal_import_stage_done stage=workbook_snapshot_verification elapsed=%.6fs upload=%s", timings["workbook_snapshot_verification"], name)
            t5 = time.perf_counter()
            APP_LOGGER.info("trading_journal_import_stage_start stage=snapshot_persist upload=%s", name)
            _persist_trading_journal_sqlite(snapshot, import_meta={"source_mode": "manual_upload", "rows_imported": len(rows), "warnings": [], "errors": []})
            timings["snapshot_persist"] = round(time.perf_counter() - t5, 6)
            APP_LOGGER.info("trading_journal_import_stage_done stage=snapshot_persist elapsed=%.6fs upload=%s", timings["snapshot_persist"], name)
            t6 = time.perf_counter()
            APP_LOGGER.info("trading_journal_import_stage_start stage=github_sync upload=%s", name)
            github_sync_started = True
            github_sync_result = _sync_journal_excel_files_to_github(_master_journal_path())
            github_sync_returned = True
            timings["github_sync"] = round(time.perf_counter() - t6, 6)
            APP_LOGGER.info("trading_journal_import_stage_done stage=github_sync elapsed=%.6fs upload=%s", timings["github_sync"], name)
            if github_sync_result.get("github_sync_enabled") and github_sync_result.get("github_sync_ok") is False:
                raise RuntimeError(f"GitHub sync failed after local verification: {github_sync_result.get('github_sync_error') or 'unknown error'}")
            if derived_refresh_state:
                queued_generation = int(
                    derived_refresh_state.get("generation") or 0
                )
                derived_refresh_state = (
                    _mark_trading_journal_derived_refresh_generation_succeeded(
                        queued_generation,
                        result={
                            "workbook_sync": _json_safe(sync_result or {}),
                            "github_sync": _json_safe(github_sync_result or {}),
                            "completed_inline": True,
                        },
                    )
                )
                incremental_failure_rollback_required = False
                incremental_json_upsert_started = False
                try:
                    _schedule_dropbox_upload_state_backup()
                except Exception as backup_exc:
                    APP_LOGGER.warning(
                        "trading_journal_import_state_backup_schedule_failed upload=%s error=%s",
                        name,
                        backup_exc,
                    )
        except Exception as exc:
            if not pending_restored:
                _PENDING_MANUAL_SYNC_ROWS = previous_pending_rows
                _PENDING_MANUAL_SYNC_BALANCES = previous_pending_balances
            rollback_errors: List[str] = []
            t_rb = time.perf_counter()
            incremental_exact_rollback = bool(
                incremental_json_upsert_started
                or incremental_failure_rollback_required
            )
            if incremental_exact_rollback:
                try:
                    if journal_json_had_original and journal_json_backup_bytes is not None:
                        _atomic_write_bytes(
                            TRADING_JOURNAL_PATH,
                            journal_json_backup_bytes,
                        )
                    elif TRADING_JOURNAL_PATH.exists():
                        TRADING_JOURNAL_PATH.unlink()
                    _TRADING_JOURNAL_CACHE = copy.deepcopy(journal_cache_before)
                    _TRADING_JOURNAL_CACHE_KEY = copy.deepcopy(
                        journal_cache_key_before
                    )
                except Exception as row_restore_exc:
                    rollback_errors.append(
                        f"could not restore journal rows: {row_restore_exc}"
                    )
                if derived_refresh_memory_before is not None:
                    try:
                        _restore_trading_journal_derived_refresh_state(
                            had_original=derived_refresh_had_original,
                            backup_bytes=derived_refresh_backup_bytes,
                            memory_state=derived_refresh_memory_before,
                        )
                    except Exception as derived_restore_exc:
                        rollback_errors.append(
                            "could not restore derived refresh state: "
                            f"{derived_restore_exc}"
                        )
            else:
                try:
                    _set_trading_journal_rows(rollback_rows)
                except Exception as row_restore_exc:
                    rollback_errors.append(
                        f"could not restore journal rows: {row_restore_exc}"
                    )
            try:
                if workbook_had_original and workbook_backup_bytes is not None:
                    _atomic_write_bytes(workbook_path, workbook_backup_bytes)
                elif not workbook_had_original and workbook_path.exists():
                    workbook_path.unlink()
            except Exception as restore_exc:
                rollback_errors.append(f"could not restore workbook: {restore_exc}")
            workbook_restore_failed = any(
                error.startswith("could not restore workbook:")
                for error in rollback_errors
            )
            rollback_rows_persisted = bool(
                parsed_ids
                and set(parsed_ids).issubset(set(pre_import_workbook_row_ids))
            )
            rollback_balance_verification: Dict[str, object] = {
                "ok": False,
                "balance_applied": False,
                "snapshot_visible": False,
            }
            if workbook_restore_failed:
                try:
                    rollback_row_verification = _verify_trade_log_row_ids_in_workbook(
                        workbook_path,
                        parsed_ids,
                    )
                    rollback_rows_persisted = bool(
                        (rollback_row_verification or {}).get("ok")
                    )
                except Exception as rollback_verify_exc:
                    rollback_errors.append(
                        f"could not verify workbook after rollback: {rollback_verify_exc}"
                    )
            if not incremental_exact_rollback or incremental_full_fallback_started:
                try:
                    rollback_snapshot = (
                        _build_master_journal_verification_snapshot()
                        if bool(oanda_transaction_export_balance)
                        else _build_manual_import_authoritative_snapshot()
                    )
                    if bool(oanda_transaction_export_balance):
                        rollback_balance_verification = _verify_imported_account_balance_snapshot(
                            rollback_snapshot,
                            oanda_transaction_export_balance,
                        )
                    _persist_trading_journal_sqlite(rollback_snapshot, import_meta={"source_mode": "manual_upload_rollback", "rows_imported": 0, "warnings": [], "errors": [str(exc), *rollback_errors]})
                except Exception as persist_rollback_exc:
                    rollback_errors.append(f"could not persist rollback snapshot: {persist_rollback_exc}")
            timings["rollback"] = round(time.perf_counter() - t_rb, 6)
            APP_LOGGER.warning("trading_journal_import_failed timings=%s upload=%s", timings, name)
            code = 500
            msg = str(exc)
            missing = (verify_result or {}).get("missing_row_ids") or list((sync_result or {}).get("missing_row_ids") or [])
            if rollback_errors:
                msg = f"{msg} | rollback failed: {'; '.join(rollback_errors)}"
            rollback_local_state_restored = not rollback_errors
            github_state_restored = bool(
                not github_sync_started
                or (
                    github_sync_returned
                    and isinstance(github_sync_result, dict)
                    and github_sync_result.get("github_sync_enabled") is False
                )
            )
            rollback_restored = bool(
                rollback_local_state_restored and github_state_restored
            )
            if _is_workbook_lock_exception(exc) or (isinstance(sync_result, dict) and sync_result.get("code") == "EXCEL_WORKBOOK_OPEN"):
                payload = _excel_workbook_open_payload(extra={
                    "uploaded_name": name,
                    "file_type": suffix,
                    "rows_parsed": len(rows),
                    "rows_upserted": 0,
                    "missing_row_ids": missing,
                    "warnings": [],
                    "import_timings": timings,
                    "master_journal_error": _master_journal_sync_error(sync_result) or msg,
                    "diagnostics": (sync_result or {}).get("diagnostics") if isinstance(sync_result, dict) else None,
                    "rows_persisted": rollback_rows_persisted,
                    "balance_applied": bool(rollback_balance_verification.get("balance_applied")),
                    "snapshot_visible": bool(rollback_balance_verification.get("snapshot_visible")),
                    "balance_verification": rollback_balance_verification,
                    "rollback_restored": rollback_restored,
                    "rollback_local_state_restored": rollback_local_state_restored,
                    "rollback_github_state_restored": github_state_restored,
                })
                payload["errors"] = ["workbook_locked", *rollback_errors]
                return payload
            return {"ok": False, "status_code": code, "message": msg, "uploaded_name": name, "file_type": suffix, "rows_parsed": len(rows), "rows_upserted": 0, "rows_persisted": rollback_rows_persisted, "balance_applied": bool(rollback_balance_verification.get("balance_applied")), "snapshot_visible": bool(rollback_balance_verification.get("snapshot_visible")), "balance_verification": rollback_balance_verification, "rollback_restored": rollback_restored, "rollback_local_state_restored": rollback_local_state_restored, "rollback_github_state_restored": github_state_restored, "missing_row_ids": missing, "errors": [msg, *rollback_errors], "warnings": [], "import_timings": timings, "master_journal_error": _master_journal_sync_error(sync_result), "diagnostics": (sync_result or {}).get("diagnostics")}
        APP_LOGGER.info("trading_journal_import_success timings=%s upload=%s", timings, name)
        message = "Import complete. Duplicate rows already present; stats refreshed; workbook trade rows unchanged." if duplicate_noop_fast_path_used else "Import complete."
        result = {"ok": True, "status_code": 200, "message": message, "uploaded_name": name, "file_type": suffix, "rows_parsed": len(rows), "rows_upserted": rows_upserted, "duplicate_rows_merged": duplicate_rows_merged, "balance_parsed": bool(balance), "rows_persisted": rows_persisted, "balance_applied": bool(balance_verification.get("balance_applied")), "snapshot_visible": bool(balance_verification.get("snapshot_visible")), "balance_verification": balance_verification, "master_journal_path": str(_master_journal_path()), "verified_row_ids_count": len(parsed_ids), "missing_row_ids": [], "warnings": inference_warnings, "errors": [], "import_timings": timings, **inference_diag, **bybit_diag, **github_sync_result, "github_sync_deferred": False, "github_sync_commit_sha": github_sync_result.get("github_sync_commit"), "github_sync_path": str(_master_journal_path()), "github_sync_message": ("GitHub sync disabled" if not github_sync_result.get("github_sync_enabled") else ("GitHub sync complete" if github_sync_result.get("github_sync_ok") else str(github_sync_result.get("github_sync_error") or "")))}
        result.update(
            {
                "incremental_workbook_update_used": False,
                "workbook_rebuild_required": True,
                "incremental_fallback_reason": incremental_fallback_reason,
                "affected_row_ids": [],
                "derived_refresh": _trading_journal_derived_refresh_status_snapshot(),
            }
        )
        return result
    except Exception as exc:
        return {"ok": False, "status_code": 500, "message": f"Unexpected import error for {name}.", "uploaded_name": name, "file_type": suffix or "unknown", "rows_parsed": 0, "rows_upserted": 0, "duplicate_rows_merged": 0, "balance_parsed": False, "master_journal_path": str(_master_journal_path()), "verified_row_ids_count": 0, "missing_row_ids": [], "warnings": [], "errors": [str(exc)]}
    finally:
        try:
            if tmp_path is not None:
                tmp_path.unlink(missing_ok=True)
        except Exception:
            pass
        _update_trading_journal_import_status(running=False, stage="idle", message="", finished_at=_utc_now_iso(), upload_name="")
        if master_workbook_reserved:
            _release_master_journal_workbook_sync()
        if acquired_import_lock:
            TRADING_JOURNAL_IMPORT_LOCK.release()

@app.post("/api/trading-journal/import-file")
async def trading_journal_import_file(file: UploadFile = File(...), account_mode: Optional[str] = Form(None)) -> JSONResponse:
    try:
        payload = await file.read()
    except Exception as exc:
        result = {"ok": False, "status_code": 400, "message": "Failed to read uploaded file.", "uploaded_name": str(getattr(file, "filename", "") or "upload"), "file_type": Path(str(getattr(file, "filename", "") or "")).suffix.lower() or "unknown", "errors": [str(exc)], "warnings": []}
        return JSONResponse(result, status_code=400)
    result = await asyncio.to_thread(
        _import_uploaded_trading_journal_file,
        file.filename or "upload",
        payload,
        account_mode,
    )
    status_code = int(result.get("status_code") or (200 if result.get("ok") else 422))
    return JSONResponse(result, status_code=status_code)



def _stream_trade_log_header_map_and_start_row(ws) -> Tuple[Dict[str, int], int]:
    preview = list(ws.iter_rows(min_row=1, max_row=4, values_only=True))
    header_map: Dict[str, int] = {}
    header_row_number = 0
    for offset, row in enumerate(preview, start=1):
        current = {
            str(value or "").strip(): idx
            for idx, value in enumerate(row or (), start=1)
            if str(value or "").strip()
        }
        if "Row ID" in current:
            header_map = current
            header_row_number = offset
            break
    if not header_map:
        return {}, 2
    row_id_index = header_map["Row ID"] - 1
    data_start_row = header_row_number + 1
    if header_row_number == 1 and len(preview) >= 3:
        row2 = preview[1] if len(preview) > 1 else ()
        row3 = preview[2] if len(preview) > 2 else ()
        row2_row_id = str((row2[row_id_index] if row_id_index < len(row2) else "") or "").strip()
        row3_row_id = str((row3[row_id_index] if row_id_index < len(row3) else "") or "").strip()
        if not row2_row_id and not row3_row_id:
            data_start_row = 4
    return header_map, data_start_row


def _verify_trade_log_row_ids_in_workbook(workbook_path: Path, expected_row_ids: List[str]) -> Dict[str, object]:
    expected = [str(x).strip() for x in (expected_row_ids or []) if str(x).strip()]
    if not workbook_path.exists():
        return {"ok": False, "expected_row_ids": expected, "found_row_ids_count": 0, "missing_row_ids": expected, "error": "Workbook does not exist."}
    try:
        wb = load_workbook(workbook_path, data_only=True, read_only=True)
    except Exception as exc:
        return {"ok": False, "expected_row_ids": expected, "found_row_ids_count": 0, "missing_row_ids": expected, "error": f"Failed to open workbook: {exc}"}
    found: List[str] = []
    try:
        try:
            ws = _get_trade_log_sheet(wb, allow_legacy=False)
        except Exception as exc:
            return {"ok": False, "expected_row_ids": expected, "found_row_ids_count": 0, "missing_row_ids": expected, "error": f"Trade Log sheet missing: {exc}"}
        header_map, data_start_row = _stream_trade_log_header_map_and_start_row(ws)
        if "Row ID" not in header_map:
            return {"ok": False, "expected_row_ids": expected, "found_row_ids_count": 0, "missing_row_ids": expected, "error": "Trade Log Row ID column missing."}
        ridx = header_map["Row ID"] - 1
        for row in ws.iter_rows(min_row=data_start_row, values_only=True):
            rid = str((row[ridx] if ridx < len(row) else "") or "").strip()
            if rid:
                found.append(rid)
    finally:
        wb.close()
    found_ids = set(found)
    missing = [rid for rid in expected if rid not in found_ids]
    return {"ok": len(missing) == 0, "expected_row_ids": expected, "found_row_ids_count": len(found), "missing_row_ids": missing}





_MONTHLY_AUD_REVAL_ROW_ID_RE = re.compile(r"^monthly_aud_reval:bybit_live:(\d{4}-\d{2})$")

def _monthly_aud_reval_row_id_month(row_id: object) -> str:
    m = _MONTHLY_AUD_REVAL_ROW_ID_RE.match(str(row_id or "").strip())
    return m.group(1) if m else ""

def _is_monthly_aud_reval_anchor_semantics(*, row_type: object, symbol: object, account: object) -> bool:
    return (
        str(row_type or "").strip().lower() == "monthly_aud_reval"
        and str(symbol or "").strip().upper() == "MONTHLY AUD P/L"
        and _canonical_journal_account_label(account).upper() == "BYBIT"
    )

def _is_monthly_aud_reval_state_row(row: object) -> bool:
    if not isinstance(row, dict):
        return False
    rid_month = _monthly_aud_reval_row_id_month(row.get("id"))
    if not rid_month:
        return False
    account = row.get("account_label") or row.get("account")
    if not _is_monthly_aud_reval_anchor_semantics(row_type=row.get("row_type"), symbol=row.get("symbol"), account=account):
        return False
    refs = row.get("raw_refs") if isinstance(row.get("raw_refs"), dict) else {}
    period_month = str(refs.get("period_month") or "").strip()
    return not period_month or period_month == rid_month

def _read_monthly_aud_reval_months_from_workbook(workbook_path: Path) -> Dict[str, object]:
    base = {
        "ok": True,
        "months": [],
        "row_ids": [],
        "ignored_invalid_workbook_anchors": [],
        "error": "",
        "workbook_exists": workbook_path.exists(),
        "trade_log_exists": False,
        "row_id_column_exists": False,
    }
    if not workbook_path.exists():
        return base
    try:
        wb = load_workbook(workbook_path, data_only=True, read_only=True)
    except Exception as exc:
        return {**base, "ok": False, "error": f"Failed to open workbook: {exc}", "workbook_exists": True}
    try:
        try:
            ws = _get_trade_log_sheet(wb, allow_legacy=False)
        except Exception as exc:
            return {**base, "ok": False, "error": f"Trade Log sheet missing: {exc}", "workbook_exists": True, "trade_log_exists": False}
        header_map, data_start_row = _stream_trade_log_header_map_and_start_row(ws)
        if "Row ID" not in header_map:
            return {**base, "ok": False, "error": "Trade Log Row ID column missing.", "workbook_exists": True, "trade_log_exists": True, "row_id_column_exists": False}
        idx = {header: col - 1 for header, col in header_map.items()}
        rid_idx = idx["Row ID"]
        row_ids: List[str] = []
        months: List[str] = []
        ignored: List[Dict[str, object]] = []
        for row_num, row in enumerate(ws.iter_rows(min_row=data_start_row, values_only=True), start=data_start_row):
            rid = str((row[rid_idx] if rid_idx < len(row) else "") or "").strip()
            if not rid.startswith("monthly_aud_reval:"):
                continue
            month = _monthly_aud_reval_row_id_month(rid)
            row_type = str((row[idx["Row Type"]] if "Row Type" in idx and idx["Row Type"] < len(row) else "") or "").strip()
            symbol = str((row[idx["Symbol"]] if "Symbol" in idx and idx["Symbol"] < len(row) else "") or "").strip()
            account_col = idx.get("Account Label", idx.get("Account"))
            account = str((row[account_col] if account_col is not None and account_col < len(row) else "") or "").strip()
            valid = bool(month) and _is_monthly_aud_reval_anchor_semantics(row_type=row_type, symbol=symbol, account=account)
            if valid:
                row_ids.append(rid)
                months.append(month)
            else:
                ignored.append({
                    "row_number": row_num,
                    "row_id": rid,
                    "row_id_month": month,
                    "row_type": row_type,
                    "symbol": symbol,
                    "account": account,
                    "reason": "invalid_monthly_aud_reval_anchor_semantics",
                })
        return {**base, "months": sorted(set(months)), "row_ids": row_ids, "ignored_invalid_workbook_anchors": ignored, "workbook_exists": True, "trade_log_exists": True, "row_id_column_exists": True}
    finally:
        wb.close()



@app.post("/api/trading-journal/bybit-demo/balance-adjustment")
async def trading_journal_bybit_demo_balance_adjustment(payload: Dict[str, object] = Body(default_factory=dict)) -> JSONResponse:
    global _PENDING_MANUAL_SYNC_ROWS
    if not ENABLE_BYBIT_DEMO_JOURNAL:
        return JSONResponse({"ok": False, "message": "Bybit Demo journal is disabled.", "errors": ["bybit_demo_journal_disabled"]}, status_code=409)
    amount = payload.get("amount")
    try:
        amount = float(amount)
    except Exception:
        amount = float("nan")
    if not math.isfinite(amount) or amount == 0.0:
        return JSONResponse({"ok": False, "message": "Amount must be a finite non-zero number.", "errors": ["invalid_amount"]}, status_code=422)
    workbook_path = _master_journal_path()
    lock = _master_journal_lock_status(workbook_path)
    if lock.get("locked"):
        return JSONResponse({"ok": False, "message": "Trading Journal.xlsx appears to be open in Excel. Close it, then resume.", "errors": [str(lock.get("reason") or "workbook_locked")]}, status_code=423)
    snapshot = _build_trading_journal_view_snapshot(force=True) or {}
    demo_bal = next((b for b in (snapshot.get("balances") or []) if _is_bybit_demo_account_label((b or {}).get("label") or (b or {}).get("account"))), None)
    prev_balance = (demo_bal or {}).get("balance")
    if not isinstance(prev_balance, (int, float)) or not math.isfinite(float(prev_balance)):
        return JSONResponse({"ok": False, "message": "Current Bybit Demo dashboard balance is unavailable.", "errors": ["missing_bybit_demo_balance"]}, status_code=409)
    prev_balance = float(prev_balance)
    reason = str(payload.get("reason") or "").strip()
    prev_pending = [dict(r) for r in (_PENDING_MANUAL_SYNC_ROWS or []) if isinstance(r, dict)]
    prev_rows = copy.deepcopy([r for r in _get_trading_journal_rows() if isinstance(r, dict)])
    workbook_exists = workbook_path.exists()
    workbook_backup = workbook_path.read_bytes() if workbook_exists else None
    new_balance = prev_balance + amount
    as_of_iso = str((demo_bal or {}).get("as_of") or "").strip()
    stamp = _journal_local_now_naive_iso()
    if as_of_iso:
        try:
            as_of = _parse_any_dt(as_of_iso)
            if as_of is not None:
                if as_of.tzinfo is not None:
                    try:
                        tz_name = str(APP_TIMEZONE or "").strip() or "Australia/Brisbane"
                        as_of = as_of.astimezone(ZoneInfo(tz_name))
                    except Exception:
                        pass
                nxt_dt = (as_of + timedelta(seconds=1)).replace(tzinfo=None, microsecond=0)
                stamp_dt = _parse_any_dt(stamp)
                if stamp_dt is None:
                    stamp_dt = datetime.min
                else:
                    stamp_dt = stamp_dt.replace(tzinfo=None, microsecond=0)
                if nxt_dt > stamp_dt:
                    stamp = nxt_dt.isoformat()
        except Exception:
            pass
    row = {"id": f"manual:bybit_demo_balance_adjustment:{uuid4().hex[:12]}", "row_type": "cashflow", "source": "manual_bybit_demo_balance_adjustment", "account": "Bybit Demo", "account_label": "Bybit Demo", "currency": "USDT", "account_currency": "USDT", "balance_after_trade_currency": "USDT", "symbol": "CASHFLOW", "symbol_raw": "CASHFLOW", "side": "ADJUSTMENT", "cashflow_type": "balance_adjustment", "cashflow_amount": amount, "cashflow_new_balance": new_balance, "balance_after_trade": new_balance, "open_time": stamp, "close_time": stamp, "notes": f"Journal-only Bybit Demo balance adjustment; does not change Bybit. {reason}".strip()}
    try:
        _PENDING_MANUAL_SYNC_ROWS = [*prev_pending, dict(row)]
        _set_trading_journal_rows([*prev_rows, dict(row)])
        sync = _sync_master_journal_workbook(defer_github_sync=True, sync_caller="bybit_demo_balance_adjustment")
        if not _master_journal_sync_ok(sync):
            raise RuntimeError(_master_journal_sync_error(sync))
        verify = _verify_trade_log_row_ids_in_workbook(_master_journal_path(), [row["id"]])
        if not bool(verify.get("ok")):
            raise RuntimeError(f"missing_row_ids={verify.get('missing_row_ids') or []}")
        _PENDING_MANUAL_SYNC_ROWS = prev_pending
        snap2 = _build_trading_journal_view_snapshot(force=True) or {}
        after = next((b for b in (snap2.get("balances") or []) if _is_bybit_demo_account_label((b or {}).get("label") or (b or {}).get("account"))), None)
        after_bal = (after or {}).get("balance")
        if not isinstance(after_bal, (int, float)) or round(float(after_bal), 8) != round(new_balance, 8):
            raise RuntimeError("post_clear_balance_mismatch after pending rows were restored")
        return JSONResponse({"ok": True, "row_id": row["id"], "currency": "USDT", "previous_balance": prev_balance, "adjustment_amount": amount, "new_balance": new_balance, "master_journal_path": str(_master_journal_path())})
    except Exception as exc:
        rollback_errors: List[str] = []
        try:
            _PENDING_MANUAL_SYNC_ROWS = prev_pending
        except Exception as rb_exc:
            rollback_errors.append(f"pending_restore_failed:{rb_exc}")
        try:
            _set_trading_journal_rows(prev_rows)
        except Exception as rb_exc:
            rollback_errors.append(f"rows_restore_failed:{rb_exc}")
        try:
            if workbook_exists and workbook_backup is not None:
                workbook_path.parent.mkdir(parents=True, exist_ok=True)
                workbook_path.write_bytes(workbook_backup)
            elif (not workbook_exists) and workbook_path.exists():
                workbook_path.unlink()
        except Exception as rb_exc:
            rollback_errors.append(f"workbook_restore_failed:{rb_exc}")
        try:
            _build_trading_journal_view_snapshot(force=True)
        except Exception as rb_exc:
            rollback_errors.append(f"snapshot_rebuild_failed:{rb_exc}")
        return JSONResponse({"ok": False, "message": f"Bybit Demo balance adjustment failed: {exc}", "errors": [str(exc), *rollback_errors], "rollback_errors": rollback_errors}, status_code=500)

def _brisbane_now() -> datetime:
    return datetime.now(ZoneInfo("Australia/Brisbane"))


def _ym_iter(start_ym: str, end_ym: str) -> List[str]:
    out: List[str] = []
    cur = datetime.strptime(start_ym + "-01", "%Y-%m-%d")
    end = datetime.strptime(end_ym + "-01", "%Y-%m-%d")
    while cur <= end:
        out.append(cur.strftime("%Y-%m"))
        y = cur.year + (1 if cur.month == 12 else 0)
        m = 1 if cur.month == 12 else cur.month + 1
        cur = cur.replace(year=y, month=m)
    return out


def _monthly_months_from_rows(rows: List[Dict[str, object]]) -> Set[str]:
    months: Set[str] = set()
    for r in rows or []:
        if not _is_monthly_aud_reval_state_row(r):
            continue
        month = _monthly_aud_reval_row_id_month((r or {}).get("id"))
        if month:
            months.add(month)
    return months



@app.post("/api/trading-journal/crypto-monthly-pnl")
async def trading_journal_crypto_monthly_pnl() -> JSONResponse:
    now_bne = _brisbane_now()
    now_brisbane = now_bne.isoformat()
    current_month = now_bne.strftime("%Y-%m")
    dt = datetime.strptime(current_month + "-01", "%Y-%m-%d")
    prev = dt.replace(year=dt.year-1, month=12) if dt.month == 1 else dt.replace(month=dt.month-1)
    last_completed = prev.strftime("%Y-%m")
    code_version = _trading_journal_code_version()

    pre_state_rows = _monthly_aud_revaluation_rows_for_journal_view()
    pre_months = {m for m in _monthly_months_from_rows(pre_state_rows) if m <= last_completed}
    wb_path = _master_journal_path()
    workbook_anchor = _read_monthly_aud_reval_months_from_workbook(wb_path)
    ignored_invalid = list(workbook_anchor.get("ignored_invalid_workbook_anchors") or [])
    response_diag = {
        "now_brisbane": now_brisbane,
        "current_month": current_month,
        "last_completed_month": last_completed,
        "state_months": sorted(pre_months),
        "workbook_months": [],
        "ignored_invalid_workbook_anchors": ignored_invalid,
        "missing_workbook_months": [],
        "synced_existing_months": [],
        "code_version": code_version,
        "app_commit": code_version,
    }
    if workbook_anchor.get("workbook_exists") and not workbook_anchor.get("ok"):
        return JSONResponse({"ok": False, "button": "crypto_monthly_pnl", **response_diag, "message": "Failed to inspect workbook monthly anchors.", "workbook_anchor": workbook_anchor, "master_journal_path": str(wb_path)}, status_code=500)

    pre_wb_months: Set[str] = {str(m) for m in (workbook_anchor.get("months") or []) if str(m) and str(m) <= last_completed}
    response_diag["workbook_months"] = sorted(pre_wb_months)
    missing_from_workbook = sorted(m for m in pre_months if m <= last_completed and m not in pre_wb_months)
    response_diag["missing_workbook_months"] = missing_from_workbook

    if not pre_months and not pre_wb_months:
        return JSONResponse({"ok": False, "button": "crypto_monthly_pnl", **response_diag, "target_months": [], "processed_months": [], "inserted_months": [], "skipped_existing_months": [], "rows_inserted": 0, "verified_row_ids": [], "master_journal_path": str(wb_path), "message": "Bootstrap required: no existing valid crypto monthly AUD P&L anchor row found."}, status_code=422)

    due_from_workbook: List[str] = []
    if pre_wb_months:
        latest_workbook = sorted(pre_wb_months)[-1]
        due_from_workbook = _ym_iter(latest_workbook, last_completed)
        if due_from_workbook and due_from_workbook[0] == latest_workbook:
            due_from_workbook = due_from_workbook[1:]
    target_months = sorted({m for m in [*missing_from_workbook, *due_from_workbook] if m <= last_completed and m < current_month})

    if not target_months:
        invalid_months = sorted({str(x.get("row_id_month") or "") for x in ignored_invalid if isinstance(x, dict) and str(x.get("row_id_month") or "")})
        warning = last_completed in invalid_months
        message = "No completed crypto monthly AUD P&L month is due."
        if warning:
            message += " Ignored invalid workbook monthly-looking anchor(s) include the last completed month; they were not counted as valid anchors."
        return JSONResponse({"ok": True, "button": "crypto_monthly_pnl", **response_diag, "target_months": [], "processed_months": [], "inserted_months": [], "skipped_existing_months": [], "rows_inserted": 0, "verified_row_ids": [], "master_journal_path": str(wb_path), "message": message})

    needs_state_sync = [m for m in target_months if m not in pre_months]
    run: Dict[str, object] = {"ok": True, "skipped": True, "reason": "target_months_already_present_in_state"}
    if needs_state_sync:
        run = await _run_monthly_aud_revaluation_sync(reason="manual_crypto_monthly_pnl")
        if not run.get("ok"):
            return JSONResponse({"ok": False, "button": "crypto_monthly_pnl", **response_diag, "target_months": target_months, "processed_months": target_months, "needed_state_sync_months": needs_state_sync, **run}, status_code=500)

    post_state_months = _monthly_months_from_rows(_monthly_aud_revaluation_rows_for_journal_view())
    missing_state_months = [m for m in target_months if m not in post_state_months]
    if missing_state_months:
        return JSONResponse({"ok": False, "button": "crypto_monthly_pnl", **response_diag, "target_months": target_months, "processed_months": target_months, "inserted_months": [m for m in target_months if m in post_state_months and m not in pre_months], "synced_existing_months": [], "skipped_existing_months": [m for m in target_months if m in pre_months], "rows_inserted": 0, "verified_row_ids": [], "missing_months": missing_state_months, "master_journal_path": str(wb_path), "message": "Crypto monthly AUD P&L state update incomplete."}, status_code=500)

    expected_ids = [f"monthly_aud_reval:bybit_live:{m}" for m in target_months]
    workbook_sync = _sync_master_journal_workbook(sync_caller="crypto_monthly_pnl", expected_survivor_row_ids=expected_ids)
    if not _master_journal_sync_ok(workbook_sync):
        status_code = int(workbook_sync.get("status_code") or 500) if isinstance(workbook_sync, dict) else 500
        return JSONResponse({"ok": False, "button": "crypto_monthly_pnl", **response_diag, "target_months": target_months, "processed_months": target_months, "inserted_months": [m for m in target_months if m in post_state_months and m not in pre_months], "synced_existing_months": [], "skipped_existing_months": [m for m in target_months if m in pre_months], "rows_inserted": 0, "verified_row_ids": [], "master_journal_path": str(wb_path), "message": f"Workbook sync failed: {_master_journal_sync_error(workbook_sync)}", **(workbook_sync if isinstance(workbook_sync, dict) else {})}, status_code=status_code)

    path = Path(str(workbook_sync.get("master_journal_path") or wb_path))
    verification = _verify_trade_log_row_ids_in_workbook(path, expected_ids)
    inserted = [m for m in target_months if m in post_state_months and m not in pre_months]
    synced_existing = [m for m in target_months if m in pre_months]
    missing = [m for m in target_months if m not in post_state_months]
    verified_ids = [f"monthly_aud_reval:bybit_live:{m}" for m in target_months if f"monthly_aud_reval:bybit_live:{m}" not in (verification.get("missing_row_ids") or [])]
    if missing or not verification.get("ok"):
        return JSONResponse({"ok": False, "button": "crypto_monthly_pnl", **response_diag, "target_months": target_months, "processed_months": target_months, "inserted_months": inserted, "synced_existing_months": synced_existing, "skipped_existing_months": synced_existing, "rows_inserted": len(inserted), "verified_row_ids": verified_ids, "missing_months": missing, "missing_row_ids": verification.get("missing_row_ids") or [], "master_journal_path": str(path), "message": "Crypto monthly AUD P&L update incomplete."}, status_code=500)
    action_word = "Inserted" if inserted else "Synced"
    action_months = inserted if inserted else synced_existing
    return JSONResponse({"ok": True, "button": "crypto_monthly_pnl", **response_diag, "target_months": target_months, "processed_months": target_months, "inserted_months": inserted, "synced_existing_months": synced_existing, "skipped_existing_months": synced_existing, "rows_inserted": len(inserted), "verified_row_ids": verified_ids, "master_journal_path": str(path), "message": f"{action_word} crypto monthly AUD P&L for {', '.join(action_months)}."})

@app.get("/api/trading-journal/import/status")
async def trading_journal_import_status() -> JSONResponse:
    return JSONResponse({"ok": True, **_trading_journal_import_status_snapshot()})

@app.post("/api/trading-journal/open-master-journal")
async def open_master_journal_file() -> JSONResponse:
    status = _trading_journal_import_status_snapshot()
    if status.get("running"):
        return JSONResponse({
            "ok": False,
            "code": "TRADING_JOURNAL_IMPORT_IN_PROGRESS",
            "message": "Trading Journal import is still running. Wait for it to complete before opening the workbook.",
            "import_status": status,
        }, status_code=409)
    path = _master_journal_path()
    if not path.exists():
        raise HTTPException(status_code=404, detail="Trading Journal.xlsx does not exist. Import history or create the journal workbook first.")
    polish: Dict[str, object] = {}
    try:
        polish = await asyncio.to_thread(_polish_master_journal_for_excel_open, path)
    except PermissionError as exc:
        polish = {
            "ok": False,
            "warning": "Trading Journal.xlsx is already open or locked, so rows/columns and recommendation styling could not be refreshed before opening.",
            "error": str(exc),
        }
    except Exception as exc:
        polish = {
            "ok": False,
            "warning": "Trading Journal.xlsx opened, but pre-open row/column sizing and recommendation styling failed.",
            "error": str(exc),
        }
    try:
        _open_path_with_os(path)
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to open Trading Journal.xlsx: {exc}")
    return JSONResponse({"ok": True, "master_journal_path": str(path.resolve()), "open_polish": polish})



def _expected_dashboard_balance_map(snapshot: Optional[Dict[str, object]]) -> Dict[str, Dict[str, object]]:
    if not isinstance(snapshot, dict):
        return {}
    expected: Dict[str, Dict[str, object]] = {}
    for rec in _canonicalize_and_dedupe_balances([b for b in (snapshot.get("balances") or []) if isinstance(b, dict)]):
        if not isinstance(rec, dict):
            continue
        label = str(rec.get("account_label") or rec.get("account") or rec.get("label") or "").strip()
        if not label:
            continue
        expected[label.upper()] = rec
    return expected


def _trading_journal_code_version() -> str:
    env_version = str(os.getenv("RENDER_GIT_COMMIT") or os.getenv("GIT_COMMIT") or "").strip()
    if env_version:
        return env_version[:12]
    try:
        head = (BASE_DIR / ".git" / "HEAD").read_text(encoding="utf-8").strip()
        if head.startswith("ref:"):
            ref = head.split(":", 1)[1].strip()
            value = (BASE_DIR / ".git" / ref).read_text(encoding="utf-8").strip()
            return value[:12] if value else "unknown"
        return head[:12] if head else "unknown"
    except Exception:
        return "unknown"


def _resync_source_fingerprint(path: Path) -> Dict[str, object]:
    if not _master_journal_single_file_mode():
        return _journal_source_fingerprint()
    files = [
        _source_file_fingerprint(path),
        _source_file_fingerprint(MONTHLY_AUD_REVALUATION_PATH),
        _source_file_fingerprint(MONTHLY_AUD_REVALUATION_STATE_PATH),
        *_trade_context_source_fingerprint(),
    ]
    return {
        "source_mode": "master_journal",
        "local_dir": str(TRADING_JOURNAL_LOCAL_DIR),
        "schema_version": TRADING_JOURNAL_VIEW_CACHE_VERSION,
        "code_version": _trading_journal_code_version(),
        "files": sorted(files, key=lambda item: str(item.get("path") or "")),
    }


def _fingerprint_changed_components(previous: object, current: object) -> List[Dict[str, object]]:
    if previous == current:
        return []
    if not isinstance(previous, dict) or not isinstance(current, dict):
        return [{"component": "fingerprint", "previous": previous, "current": current}]
    changes: List[Dict[str, object]] = []
    for key in sorted((set(previous.keys()) | set(current.keys())) - {"files"}):
        if previous.get(key) != current.get(key):
            changes.append({"component": key, "previous": previous.get(key), "current": current.get(key)})
    prev_files = {str(item.get("path") or ""): item for item in (previous.get("files") or []) if isinstance(item, dict)}
    cur_files = {str(item.get("path") or ""): item for item in (current.get("files") or []) if isinstance(item, dict)}
    for path_key in sorted(set(prev_files) | set(cur_files)):
        if prev_files.get(path_key) != cur_files.get(path_key):
            changes.append({"component": "file", "path": path_key, "previous": prev_files.get(path_key), "current": cur_files.get(path_key)})
    return changes


def _resync_expected_snapshot_from_metadata(meta: Dict[str, object]) -> Optional[Dict[str, object]]:
    balances = meta.get("expected_balances") if isinstance(meta, dict) else None
    if not isinstance(balances, list):
        return None
    return {"items": [], "stats": {"totals": {}, "groups": {}}, "balances": [b for b in balances if isinstance(b, dict)]}


def _load_resync_success_metadata(path: Path, fingerprint: Dict[str, object]) -> Optional[Dict[str, object]]:
    meta = _load_json_file(TRADING_JOURNAL_RESYNC_CACHE_PATH, {})
    if not isinstance(meta, dict):
        return None
    if int(meta.get("schema_version") or 0) != TRADING_JOURNAL_RESYNC_CACHE_SCHEMA_VERSION:
        return None
    if str(meta.get("workbook_path") or "") != str(path):
        return None
    if meta.get("source_fingerprint") != fingerprint:
        return None
    if str(meta.get("code_version") or "") != _trading_journal_code_version():
        return None
    snapshot = _resync_expected_snapshot_from_metadata(meta)
    if not isinstance(snapshot, dict):
        return None
    return {**meta, "snapshot": snapshot}


def _save_resync_success_metadata(path: Path, fingerprint: Dict[str, object], snapshot: Dict[str, object]) -> None:
    balances = list(_expected_dashboard_balance_map(snapshot).values())
    meta = {
        "schema_version": TRADING_JOURNAL_RESYNC_CACHE_SCHEMA_VERSION,
        "verified_at": _utc_now_iso(),
        "workbook_path": str(path),
        "source_fingerprint": fingerprint,
        "expected_balances": _json_safe(balances),
        "code_version": _trading_journal_code_version(),
    }
    _save_json_file(TRADING_JOURNAL_RESYNC_CACHE_PATH, meta)


def _fast_verify_trading_journal_workbook(path: Path, *, expected_snapshot: Optional[Dict[str, object]] = None) -> Dict[str, object]:
    diagnostics: Dict[str, object] = {
        "checked_accounts": [],
        "formula_error_cells": [],
        "managed_source_cells": [],
        "managed_row_height_mismatches": [],
        "verbose_duration_cells": [],
        "recommendation_links_checked": [],
    }
    if not path.exists():
        return {"ok": False, "error": "Trading Journal.xlsx is missing.", "diagnostics": diagnostics}
    wb = load_workbook(path, data_only=False)
    try:
        expected_order = [*SHEET_ORDER, *expected_report_sheet_names(expected_snapshot)]
        diagnostics["sheet_order"] = list(wb.sheetnames)
        missing_sheets = [name for name in expected_order if name not in wb.sheetnames]
        expected_positions = [wb.sheetnames.index(name) for name in expected_order if name in wb.sheetnames]
        if missing_sheets or expected_positions != sorted(expected_positions):
            return {
                "ok": False,
                "error": (
                    "sheet_order_mismatch: required generated sheets must remain "
                    f"in order; missing={missing_sheets}, got={wb.sheetnames}"
                ),
                "diagnostics": diagnostics,
            }
        diagnostics["preserved_extra_sheets"] = [
            name for name in wb.sheetnames if name not in expected_order
        ]
        dash = _stats1_sheet(wb)
        detail_dash = _stats2_sheet(wb) or dash
        trade_log = wb["Trade Log"]
        inst = _symbols_sheet(wb)
        diagnostics["trade_log_filter"] = trade_log.auto_filter.ref
        diagnostics["instrument_averages_filter"] = inst.auto_filter.ref
        if not trade_log.auto_filter.ref:
            return {"ok": False, "error": "Trade Log filter is missing.", "diagnostics": diagnostics}
        trade_log_filter_coverage = _trade_log_filter_coverage(trade_log)
        diagnostics["trade_log_filter_coverage"] = trade_log_filter_coverage
        if not trade_log_filter_coverage.get("ok"):
            return {
                "ok": False,
                "error": "trade_log_filter_excludes_populated_rows",
                "diagnostics": diagnostics,
            }
        if not inst.auto_filter.ref:
            return {"ok": False, "error": "SYMBOLS filter is missing.", "diagnostics": diagnostics}
        error_tokens = ("#REF!", "#DIV/0!", "#VALUE!", "#NAME?", "#N/A")
        for ws in wb.worksheets:
            for row in ws.iter_rows():
                for cell in row:
                    value = cell.value
                    if isinstance(value, str) and any(token in value for token in error_tokens):
                        diagnostics["formula_error_cells"].append({"sheet": ws.title, "cell": cell.coordinate, "value": value})
                        if len(diagnostics["formula_error_cells"]) >= 20:
                            break
                if len(diagnostics["formula_error_cells"]) >= 20:
                    break
            if len(diagnostics["formula_error_cells"]) >= 20:
                break
        if diagnostics["formula_error_cells"]:
            return {"ok": False, "error": "formula_error_strings_found", "diagnostics": diagnostics}

        managed_statistics_sheets = [
            ws
            for ws in wb.worksheets
            if ws.title in {STATS1_SHEET, REPORT_YEARLY_SHEET}
            or (ws.title.isdigit() and int(ws.title) >= 2018)
        ]
        verbose_duration_pattern = re.compile(
            r"\b\d+(?:\.\d+)?\s*(?:days?|hours?|minutes?|seconds?)\b",
            re.IGNORECASE,
        )
        for ws in managed_statistics_sheets:
            for row_number in range(1, ws.max_row + 1):
                populated = False
                for col_number in range(1, ws.max_column + 1):
                    cell = ws.cell(row_number, col_number)
                    value = cell.value
                    if value not in (None, ""):
                        populated = True
                    if str(value or "").strip().casefold() == "source":
                        diagnostics["managed_source_cells"].append(
                            {"sheet": ws.title, "cell": cell.coordinate}
                        )
                    if isinstance(value, str) and verbose_duration_pattern.search(value):
                        diagnostics["verbose_duration_cells"].append(
                            {"sheet": ws.title, "cell": cell.coordinate, "value": value}
                        )
                if row_number >= 2 and populated:
                    height = ws.row_dimensions[row_number].height
                    if height is None or abs(float(height) - 14.5) > 1e-9:
                        diagnostics["managed_row_height_mismatches"].append(
                            {"sheet": ws.title, "row": row_number, "height": height}
                        )
        if diagnostics["managed_source_cells"]:
            return {"ok": False, "error": "generated_source_rows_remain", "diagnostics": diagnostics}
        if diagnostics["managed_row_height_mismatches"]:
            return {"ok": False, "error": "generated_statistics_row_height_mismatch", "diagnostics": diagnostics}
        if diagnostics["verbose_duration_cells"]:
            return {"ok": False, "error": "verbose_duration_text_remains", "diagnostics": diagnostics}

        anchor = None
        for rr in range(1, detail_dash.max_row + 1):
            for cc in range(1, detail_dash.max_column + 1):
                if str(detail_dash.cell(rr, cc).value or "").strip().lower() == "account balances":
                    anchor = (rr, cc)
                    break
            if anchor:
                break
        if not anchor:
            return {"ok": False, "error": "Account Balances section anchor missing.", "diagnostics": diagnostics}
        header_row = None
        header_map: Dict[str, int] = {}
        for rr in range(anchor[0] + 1, min(detail_dash.max_row + 1, anchor[0] + 12)):
            row_map: Dict[str, int] = {}
            for cc in range(anchor[1], min(detail_dash.max_column + 1, anchor[1] + 8)):
                token = str(detail_dash.cell(rr, cc).value or "").strip().lower().replace("_", " ")
                if token in {"account", "balance", "currency", "risk of ruin", "net p/l percentage", "as of"}:
                    row_map[token] = cc
            if {"account", "balance", "currency"}.issubset(set(row_map.keys())):
                header_row = rr
                header_map = row_map
                break
        if not header_row:
            return {"ok": False, "error": "Account Balances headers missing.", "diagnostics": diagnostics}
        if "as of" in header_map:
            return {"ok": False, "error": "stats2_as_of_column_present", "diagnostics": diagnostics}
        if "net p/l percentage" not in header_map:
            return {"ok": False, "error": "stats2_net_pl_percentage_header_missing", "diagnostics": diagnostics}
        actual: Dict[str, Dict[str, object]] = {}
        for rr in range(header_row + 1, min(detail_dash.max_row + 1, header_row + 100)):
            account = str(detail_dash.cell(rr, header_map["account"]).value or "").strip()
            if not account:
                continue
            actual[account.upper()] = {
                "account": account,
                "row": rr,
                "balance": _to_float(detail_dash.cell(rr, header_map["balance"]).value),
                "currency": str(detail_dash.cell(rr, header_map["currency"]).value or "").strip().upper(),
            }
        diagnostics["checked_accounts"] = sorted(actual.keys())
        mismatches: List[str] = []
        expected_balance_map = _expected_dashboard_balance_map(expected_snapshot)
        diagnostics["source_driven_nonzero_accounts"] = sorted(
            account_key
            for account_key, expected in expected_balance_map.items()
            if (_to_float(expected.get("balance")) or 0.0) != 0.0
        )
        for account_key, expected in expected_balance_map.items():
            row = actual.get(account_key)
            expected_balance = _to_float(expected.get("balance"))
            expected_currency = str(expected.get("currency") or "").strip().upper()
            if expected_balance is None:
                continue
            if row is None:
                mismatches.append(f"{account_key}: missing expected snapshot account")
                continue
            bal = _to_float(row.get("balance"))
            currency = str(row.get("currency") or "").upper()
            if bal is None or abs(bal - expected_balance) > max(1e-9, abs(expected_balance) * 1e-12) or currency != expected_currency:
                mismatches.append(f"{account_key}: expected={expected_balance} {expected_currency}, actual={row.get('balance')} {currency}")
        if mismatches:
            diagnostics["account_balance_mismatches"] = mismatches
            return {"ok": False, "error": "dashboard_account_balance_verification_failed", "diagnostics": diagnostics}

        bybit_demo = actual.get("BYBIT DEMO")
        if bybit_demo is not None:
            bybit_demo_value = detail_dash.cell(
                int(bybit_demo["row"]), header_map["net p/l percentage"]
            ).value
            diagnostics["bybit_demo_net_pl_percentage"] = bybit_demo_value
            if bybit_demo_value not in (None, ""):
                return {"ok": False, "error": "bybit_demo_net_pl_percentage_not_blank", "diagnostics": diagnostics}

        trade_headers = _trade_log_header_map(trade_log)
        row_id_col = trade_headers.get("Row ID")
        currency_col = trade_headers.get("Currency")
        net_pl_col = trade_headers.get("Net P/L")
        aud_revaluation_rows: List[int] = []
        if row_id_col and currency_col and net_pl_col:
            for row_number in range(_trade_log_data_start_row(trade_log), trade_log.max_row + 1):
                row_id = str(trade_log.cell(row_number, row_id_col).value or "").strip()
                if not row_id.startswith("monthly_aud_reval:"):
                    continue
                aud_revaluation_rows.append(row_number)
                currency = str(trade_log.cell(row_number, currency_col).value or "").strip().upper()
                number_format = str(trade_log.cell(row_number, net_pl_col).number_format or "").upper()
                if currency != "AUD" or "AUD" not in number_format or "USDT" in number_format:
                    diagnostics["monthly_aud_revaluation_format_mismatch"] = {
                        "row": row_number,
                        "row_id": row_id,
                        "currency": currency,
                        "number_format": number_format,
                    }
                    return {"ok": False, "error": "monthly_aud_revaluation_currency_format_mismatch", "diagnostics": diagnostics}
        diagnostics["monthly_aud_revaluation_rows_checked"] = aud_revaluation_rows

        symbol_headers = _instrument_averages_header_map(inst)
        symbol_col = symbol_headers.get("Symbol", 1)
        symbol_format_mismatches: List[Dict[str, object]] = []
        required_symbol_formats = {
            "Net R Multiple": '0.000"R"',
            "Net P/L %": "0.00%",
            "Avg P/L %": "0.00%",
            "Win Rate %": "0.00%",
            "Avg stop % (W)": "0.00%",
            "Avg stop % (L)": "0.00%",
            "Avg target % (W)": "0.00%",
            "Avg target % (L)": "0.00%",
        }
        for row_number in range(INSTRUMENT_AVERAGES_DATA_START_ROW, inst.max_row + 1):
            if inst.cell(row_number, symbol_col).value in (None, ""):
                continue
            for header, expected_format in required_symbol_formats.items():
                col_number = symbol_headers.get(header)
                if not col_number:
                    continue
                actual_format = str(inst.cell(row_number, col_number).number_format or "")
                if actual_format != expected_format:
                    symbol_format_mismatches.append(
                        {
                            "row": row_number,
                            "symbol": inst.cell(row_number, symbol_col).value,
                            "header": header,
                            "expected": expected_format,
                            "actual": actual_format,
                        }
                    )
        diagnostics["symbols_format_mismatches"] = symbol_format_mismatches
        if symbol_format_mismatches:
            return {"ok": False, "error": "symbols_performance_number_format_mismatch", "diagnostics": diagnostics}

        recommendation_cells = []
        stats_market_cols = _stats1_market_columns(dash)
        for row_number in range(2, dash.max_row + 1):
            if str(dash.cell(row_number, 1).value or "").strip().casefold() != "recommendation":
                continue
            for col_number in stats_market_cols.values():
                cell = dash.cell(row_number, col_number)
                if cell.value not in (None, ""):
                    recommendation_cells.append(cell)
        for row_number in range(INSTRUMENT_AVERAGES_DATA_START_ROW, inst.max_row + 1):
            if inst.cell(row_number, symbol_col).value in (None, ""):
                continue
            for header in (STOP_RECOMMENDATION_HEADER, TARGET_RECOMMENDATION_HEADER):
                col_number = symbol_headers.get(header)
                if col_number and inst.cell(row_number, col_number).value not in (None, ""):
                    recommendation_cells.append(inst.cell(row_number, col_number))
        for cell in recommendation_cells:
            hyperlink = cell.hyperlink
            target = str(getattr(hyperlink, "target", "") or "").strip() if hyperlink else ""
            decoded_target = unquote(target)
            diagnostics["recommendation_links_checked"].append(
                {"sheet": cell.parent.title, "cell": cell.coordinate, "target": target}
            )
            if not target or urlparse(decoded_target).scheme:
                return {"ok": False, "error": "recommendation_offline_hyperlink_missing", "diagnostics": diagnostics}
            artifact = (path.parent / Path(decoded_target.replace("/", os.sep))).resolve()
            try:
                artifact.relative_to(path.parent.resolve())
            except ValueError:
                return {"ok": False, "error": "recommendation_hyperlink_outside_workbook_tree", "diagnostics": diagnostics}
            if not artifact.is_file():
                diagnostics["missing_recommendation_artifact"] = str(artifact)
                return {"ok": False, "error": "recommendation_artifact_missing", "diagnostics": diagnostics}
            html_text = artifact.read_text(encoding="utf-8")
            html_lower = html_text.casefold()
            if (
                "<svg" not in html_lower
                or "data-recommended-value=" not in html_lower
                or "http://" in html_lower
                or "https://" in html_lower
            ):
                diagnostics["invalid_recommendation_artifact"] = str(artifact)
                return {"ok": False, "error": "recommendation_artifact_not_self_contained", "diagnostics": diagnostics}
            marker_match = re.search(
                r"data-recommended-value\s*=\s*[\"']([^\"']+)[\"']",
                html_text,
                re.IGNORECASE,
            )
            recommendation_match = re.search(
                r"Workbook recommendation</strong>\s*<p>(.*?)</p>",
                html_text,
                re.IGNORECASE | re.DOTALL,
            )
            expected_text = str(cell.value or "").strip()
            artifact_text = (
                html.unescape(re.sub(r"<[^>]+>", "", recommendation_match.group(1))).strip()
                if recommendation_match
                else ""
            )
            expected_marker_match = re.search(
                r"\bRecommended:\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+))",
                expected_text,
                re.IGNORECASE,
            )
            artifact_marker = _to_float(marker_match.group(1)) if marker_match else None
            expected_marker_token = (
                expected_marker_match.group(1)
                if expected_marker_match
                else ""
            )
            expected_marker = (
                _to_float(expected_marker_token)
                if expected_marker_match
                else None
            )
            marker_precision_match = re.fullmatch(
                r"[-+]?(?:\d+)(?:\.(\d*))?",
                expected_marker_token,
            )
            displayed_marker_precision = (
                len(marker_precision_match.group(1) or "")
                if marker_precision_match
                else None
            )
            displayed_marker_unit = (
                10.0 ** (-displayed_marker_precision)
                if displayed_marker_precision is not None
                else None
            )
            displayed_marker_half_unit = (
                displayed_marker_unit / 2.0
                if displayed_marker_unit is not None
                else None
            )
            marker_rounding_epsilon = (
                max(1e-12, displayed_marker_unit * 1e-9)
                if displayed_marker_unit is not None
                else 0.0
            )
            marker_matches = (
                artifact_marker is not None
                and expected_marker is not None
                and math.isfinite(artifact_marker)
                and math.isfinite(expected_marker)
                and displayed_marker_half_unit is not None
                # The HTML marker is serialized to 12 significant digits while
                # workbook text is formatted from the pre-serialization value.
                # At an exact half-unit boundary (for example, marker 2.375 and
                # display 2.37), the marker no longer records which side of the
                # boundary the original binary value occupied.  Accept exactly
                # one half of the displayed unit; the exact artifact/workbook
                # recommendation text comparison below remains authoritative.
                and abs(artifact_marker - expected_marker)
                <= displayed_marker_half_unit + marker_rounding_epsilon
            )
            if artifact_text != expected_text or not marker_matches:
                diagnostics.setdefault("recommendation_content_mismatches", []).append(
                    {
                        "sheet": cell.parent.title,
                        "cell": cell.coordinate,
                        "artifact": str(artifact),
                        "expected_text": expected_text,
                        "artifact_text": artifact_text,
                        "expected_recommended_value": expected_marker,
                        "artifact_recommended_value": artifact_marker,
                        "displayed_recommended_value_precision": displayed_marker_precision,
                        "displayed_recommended_value_half_unit": displayed_marker_half_unit,
                    }
                )
                return {
                    "ok": False,
                    "error": "recommendation_artifact_content_mismatch",
                    "diagnostics": diagnostics,
                }
        return {"ok": True, "diagnostics": diagnostics}
    finally:
        wb.close()


def _resync_fast_path_snapshot(path: Path, fingerprint: Dict[str, object]) -> Tuple[Optional[Dict[str, object]], str, Dict[str, object]]:
    diagnostics: Dict[str, object] = {"changed_components": []}
    if _PENDING_MANUAL_SYNC_ROWS:
        return None, "pending_manual_rows", diagnostics
    if not path.exists():
        return None, "workbook_missing", diagnostics
    last = TRADING_JOURNAL_RESYNC_LAST_SUCCESS
    if (
        str(last.get("workbook_path") or "") == str(path)
        and isinstance(last.get("snapshot"), dict)
        and last.get("fingerprint") == fingerprint
    ):
        return last.get("snapshot"), "memory_fingerprint_match", diagnostics  # type: ignore[return-value]
    if isinstance(last.get("fingerprint"), dict) and str(last.get("workbook_path") or "") == str(path):
        diagnostics["memory_changed_components"] = _fingerprint_changed_components(last.get("fingerprint"), fingerprint)

    meta = _load_json_file(TRADING_JOURNAL_RESYNC_CACHE_PATH, {})
    if isinstance(meta, dict) and meta:
        if int(meta.get("schema_version") or 0) != TRADING_JOURNAL_RESYNC_CACHE_SCHEMA_VERSION:
            diagnostics["metadata_schema_changed"] = {"previous": meta.get("schema_version"), "current": TRADING_JOURNAL_RESYNC_CACHE_SCHEMA_VERSION}
        elif str(meta.get("workbook_path") or "") != str(path):
            diagnostics["metadata_workbook_path_changed"] = {"previous": meta.get("workbook_path"), "current": str(path)}
        elif str(meta.get("code_version") or "") != _trading_journal_code_version():
            diagnostics["metadata_code_version_changed"] = {"previous": meta.get("code_version"), "current": _trading_journal_code_version()}
        elif meta.get("source_fingerprint") != fingerprint:
            diagnostics["changed_components"] = _fingerprint_changed_components(meta.get("source_fingerprint"), fingerprint)
        else:
            snapshot = _resync_expected_snapshot_from_metadata(meta)
            if isinstance(snapshot, dict):
                TRADING_JOURNAL_RESYNC_LAST_SUCCESS.update({
                    "fingerprint": fingerprint,
                    "snapshot": snapshot,
                    "verified_at": meta.get("verified_at"),
                    "workbook_path": str(path),
                })
                return snapshot, "persisted_fingerprint_match", diagnostics
            diagnostics["metadata_snapshot_missing"] = True
    else:
        diagnostics["metadata_missing"] = True
    return None, "fingerprint_changed_or_no_verified_cache", diagnostics


def _run_trading_journal_resync() -> Dict[str, object]:
    request_id = f"resync-{uuid4().hex[:12]}"
    timings: Dict[str, float] = {}
    started = time.perf_counter()
    path = _master_journal_path()
    master_reserved = False
    if not TRADING_JOURNAL_RESYNC_LOCK.acquire(blocking=False):
        return {
            "ok": False,
            "button": "resync",
            "code": "TRADING_JOURNAL_RESYNC_IN_PROGRESS",
            "message": "Trading Journal Resync is already running.",
            "request_id": request_id,
            "app_version": _trading_journal_code_version(),
            "fast_path_reason": "resync_already_running",
            "master_journal_path": str(path),
            "resync_timings": timings,
            "status_code": 409,
        }
    APP_LOGGER.info("trading_journal_resync_start request_id=%s path=%s", request_id, path)
    try:
        lock_status = _master_journal_lock_status(path) if path.exists() else {"locked": False}
        if lock_status.get("locked"):
            payload = _excel_workbook_open_payload(extra={"button": "resync", "request_id": request_id, "app_version": _trading_journal_code_version(), "fast_path_reason": "workbook_locked", "master_journal_path": str(path), "lock_status": lock_status, "resync_timings": timings})
            payload["status_code"] = 409
            return payload

        rejected = _reserve_master_journal_workbook_sync(path, request_id, "resync")
        if rejected is not None:
            rejected.update({
                "button": "resync",
                "request_id": request_id,
                "app_version": _trading_journal_code_version(),
                "fast_path_reason": "workbook_sync_already_running",
                "resync_timings": timings,
                "skipped_snapshot_build": True,
                "snapshot_build_ran": False,
            })
            return rejected
        master_reserved = True
        APP_LOGGER.info("master_journal_workbook_sync_start sync_id=%s caller=resync path=%s prebuilt_snapshot=True reserved_before_snapshot=True", request_id, path)

        fingerprint = _resync_source_fingerprint(path)
        fast_snapshot, fast_path_reason, fast_path_diagnostics = _resync_fast_path_snapshot(path, fingerprint)
        if isinstance(fast_snapshot, dict):
            t0 = time.perf_counter()
            verification = _fast_verify_trading_journal_workbook(path, expected_snapshot=fast_snapshot)
            timings["fast_verification"] = round(time.perf_counter() - t0, 6)
            timings["total"] = round(time.perf_counter() - started, 6)
            if verification.get("ok"):
                APP_LOGGER.info("master_journal_workbook_sync_done sync_id=%s caller=resync ok=True snapshot_build_ran=False", request_id)
                payload = {
                    "ok": True,
                    "button": "resync",
                    "message": "Trading Journal resync verified; no source changes detected.",
                    "request_id": request_id,
                    "sync_id": request_id,
                    "sync_caller": "resync",
                    "master_journal_path": str(path),
                    "resync_timings": timings,
                    "skipped_snapshot_build": True,
                    "snapshot_build_ran": False,
                    "fast_path_reason": fast_path_reason,
                    "fast_path_diagnostics": fast_path_diagnostics,
                    "app_version": _trading_journal_code_version(),
                    "fast_verification": verification,
                    "status_code": 200,
                }
                return payload
            APP_LOGGER.warning("trading_journal_resync_fast_verify_failed request_id=%s reason=%s error=%s", request_id, fast_path_reason, verification.get("error"))
        else:
            APP_LOGGER.info("trading_journal_resync_fast_path_not_used request_id=%s reason=%s diagnostics=%s", request_id, fast_path_reason, fast_path_diagnostics)

        t0 = time.perf_counter()
        snapshot = _build_trading_journal_view_snapshot(force=True, skip_external_balances=True, skip_live_account_refresh=True, sync_id=request_id, sync_caller="resync") or {}
        timings["snapshot_build"] = round(time.perf_counter() - t0, 6)
        t0 = time.perf_counter()
        sync = _sync_master_journal_workbook_unlocked(defer_github_sync=True, prebuilt_snapshot=snapshot if isinstance(snapshot, dict) else {}, sync_caller="resync", sync_id=request_id)
        timings["workbook_sync"] = round(time.perf_counter() - t0, 6)
        if isinstance(sync, dict):
            sync.setdefault("sync_id", request_id)
            sync.setdefault("sync_caller", "resync")
        ok = _master_journal_sync_ok(sync)
        verification = None
        if ok and path.exists():
            t0 = time.perf_counter()
            verification = _fast_verify_trading_journal_workbook(path, expected_snapshot=snapshot if isinstance(snapshot, dict) else None)
            timings["final_fast_verification"] = round(time.perf_counter() - t0, 6)
            if not verification.get("ok"):
                ok = False
                sync = {**(sync if isinstance(sync, dict) else {}), "master_journal_ok": False, "master_journal_error": verification.get("error"), "master_journal_diagnostics": {"fast_verification": verification}}
        if ok and isinstance(snapshot, dict):
            verified_fingerprint = _resync_source_fingerprint(path)
            TRADING_JOURNAL_RESYNC_LAST_SUCCESS.update({
                "fingerprint": verified_fingerprint,
                "snapshot": copy.deepcopy(snapshot),
                "verified_at": _utc_now_iso(),
                "workbook_path": str(path),
            })
            _save_resync_success_metadata(path, verified_fingerprint, snapshot)
        timings["total"] = round(time.perf_counter() - started, 6)
        APP_LOGGER.info("master_journal_workbook_sync_done sync_id=%s caller=resync ok=%s snapshot_build_ran=True", request_id, ok)
        payload = {"ok": ok, "button": "resync", "message": "Trading Journal resync complete." if ok else _master_journal_sync_error(sync), "request_id": request_id, "app_version": _trading_journal_code_version(), "resync_timings": timings, "skipped_snapshot_build": False, "snapshot_build_ran": True, "fast_path_reason": fast_path_reason, "fast_path_diagnostics": fast_path_diagnostics, **(sync if isinstance(sync, dict) else {})}
        if verification is not None:
            payload["fast_verification"] = verification
        payload.setdefault("status_code", 200 if ok else 500)
        return payload
    finally:
        timings.setdefault("total", round(time.perf_counter() - started, 6))
        APP_LOGGER.info("trading_journal_resync_done request_id=%s elapsed=%.6fs", request_id, timings.get("total") or 0.0)
        if master_reserved:
            _release_master_journal_workbook_sync()
        TRADING_JOURNAL_RESYNC_LOCK.release()


@app.post("/api/trading-journal/resync")
async def trading_journal_resync() -> JSONResponse:
    result = await asyncio.to_thread(_run_trading_journal_resync)
    status_code = int(result.pop("status_code", 200 if result.get("ok") else 500))
    return JSONResponse(_json_safe(result), status_code=status_code)


@app.post("/api/trading-journal/sync")
async def trading_journal_sync() -> JSONResponse:
    return await trading_journal_resync()
def _runtime_is_render() -> bool:
    return _resolve_app_profile() == "render"


def _scanner_local_only_response(path: str) -> PlainTextResponse:
    return PlainTextResponse(
        "Alerts are local-only. Run run_local_master_control.bat on your PC.",
        status_code=410,
        headers={"cache-control": "no-store, max-age=0", "x-disabled-path": path},
    )
def _is_local_exit_allowed() -> bool:
    return _resolve_app_profile() == "local"


def _close_local_master_edge_target(current_url: Optional[str]) -> Dict[str, object]:
    debug_port_raw = str(os.getenv("LOCAL_MASTER_EDGE_DEBUG_PORT") or "").strip()
    if not debug_port_raw.isdigit():
        raise HTTPException(status_code=500, detail="LOCAL_MASTER_EDGE_DEBUG_PORT is missing or invalid.")
    debug_port = int(debug_port_raw)
    response = requests.get(f"http://127.0.0.1:{debug_port}/json", timeout=2.5)
    response.raise_for_status()
    targets = response.json()
    if not isinstance(targets, list):
        raise HTTPException(status_code=500, detail="Edge DevTools target list was malformed.")
    wanted = {str(current_url or "").strip(), "http://127.0.0.1:8000/", "http://localhost:8000/"}
    page_targets = [t for t in targets if isinstance(t, dict) and str(t.get("type", "")).lower() == "page"]
    matched = None
    for target in page_targets:
        target_url = str(target.get("url") or "").strip()
        if target_url in wanted:
            matched = target
            break
    if matched is None:
        for target in page_targets:
            target_url = str(target.get("url") or "").strip().lower()
            if target_url.startswith("http://127.0.0.1:8000/") or target_url.startswith("http://localhost:8000/"):
                matched = target
                break
    if matched is None:
        raise HTTPException(status_code=409, detail="Local Trading Tools Edge tab was not found; app was not shut down.")
    target_id = str(matched.get("id") or "").strip()
    if not target_id:
        raise HTTPException(status_code=500, detail="Edge DevTools target id missing.")
    close_response = requests.get(f"http://127.0.0.1:{debug_port}/json/close/{quote(target_id, safe='')}", timeout=2.5)
    if close_response.status_code >= 400:
        raise HTTPException(status_code=409, detail="Failed to close Local Trading Tools Edge tab; app was not shut down.")
    return {"ok": True, "target_id": target_id, "target_url": str(matched.get("url") or "")}


def _write_text_file_atomic(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_name(f"{path.name}.{os.getpid()}.{threading.get_ident()}.tmp")
    with temp_path.open("w", encoding="utf-8", newline="") as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temp_path, path)


def _local_exit_marker_payload(reason: str, requesting_action: str) -> str:
    return json.dumps(
        {
            "reason": str(reason or "").strip() or requesting_action,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "server_pid": os.getpid(),
            "requesting_action": requesting_action,
        },
        sort_keys=True,
    ) + "\n"


def _write_local_exit_markers(reason: str, requesting_action: str) -> Tuple[Path, Optional[Path]]:
    sentinel_raw = str(os.getenv("LOCAL_MASTER_EXIT_REQUEST") or "").strip()
    if not sentinel_raw:
        raise HTTPException(status_code=500, detail="LOCAL_MASTER_EXIT_REQUEST is missing.")
    sentinel_path = Path(sentinel_raw)
    normal_raw = str(os.getenv("LOCAL_MASTER_NORMAL_EXIT_FILE") or "").strip()
    if not normal_raw:
        raise HTTPException(status_code=500, detail="LOCAL_MASTER_NORMAL_EXIT_FILE is missing.")
    normal_path = Path(normal_raw)
    payload = _local_exit_marker_payload(reason, requesting_action)
    _write_text_file_atomic(normal_path, payload)
    # Publish the worker-watched sentinel last so shutdown cannot begin before
    # the normal-exit marker has been flushed successfully.
    _write_text_file_atomic(sentinel_path, payload)
    return sentinel_path, normal_path


def _write_local_exit_sentinel() -> Path:
    sentinel_path, _normal_path = _write_local_exit_markers("local_exit", "legacy_sentinel")
    return sentinel_path


def _schedule_local_master_process_exit(delay_seconds: float = 0.75) -> None:
    def _shutdown() -> None:
        time.sleep(max(0.0, float(delay_seconds)))
        os.kill(os.getpid(), signal.SIGTERM)

    threading.Thread(target=_shutdown, name="local-master-exit", daemon=True).start()


@app.post("/api/local-shutdown")
async def local_shutdown(payload: Dict[str, object] = Body(default_factory=dict)) -> JSONResponse:
    if not _is_local_exit_allowed():
        raise HTTPException(status_code=404, detail="Local shutdown is only available in local profile.")
    reason = str((payload or {}).get("reason") or "launcher_preflight").strip() or "launcher_preflight"
    try:
        sentinel_path, normal_path = _write_local_exit_markers(reason, "local_shutdown")
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to schedule local shutdown: {exc}") from exc
    response_payload = {"ok": True, "sentinel": str(sentinel_path), "normal_marker": str(normal_path or ""), "reason": reason}
    response = JSONResponse(response_payload)
    APP_LOGGER.info("LOCAL_SHUTDOWN_REQUESTED reason=%s sentinel=%s normal_marker=%s", reason, sentinel_path, normal_path)
    _schedule_local_master_process_exit()
    return response


@app.post("/api/local-exit")
async def local_exit(payload: Dict[str, object] = Body(default_factory=dict)) -> JSONResponse:
    if not _is_local_exit_allowed():
        raise HTTPException(status_code=404, detail="Local exit is only available in local profile.")
    try:
        sentinel_path, normal_path = _write_local_exit_markers("exit_button", "local_exit")
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to schedule local shutdown: {exc}") from exc
    response_payload = {
        "ok": True,
        "sentinel": str(sentinel_path),
        "normal_marker": str(normal_path),
        "reason": "exit_button",
        "action": "local_exit",
    }
    response = JSONResponse(response_payload)
    APP_LOGGER.info(
        "LOCAL_EXIT_REQUESTED reason=exit_button action=local_exit sentinel=%s normal_marker=%s",
        sentinel_path,
        normal_path,
    )
    _schedule_local_master_process_exit()
    return response
